INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003963', 'M20B-EVID-003963-P2-DIRECT', 'M20B-P2-R-003963-R126A', 'PMID:11564763; DOI:10.4049/jimmunol.167.7.3545; PMID:12351624; DOI:10.1074/jbc.M205114200; PMID:22802649; PMCID:PMC3412030; DOI:10.1073/pnas.1117551109', NULL, 'literature_xml', 'exact_identifier_match:PMID:11564763', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_direct_complex_support', 'PMID:11564763; DOI:10.4049/jimmunol.167.7.3545; https://pubmed.ncbi.nlm.nih.gov/11564763/; PMID:12351624; DOI:10.1074/jbc.M205114200; https://pubmed.ncbi.nlm.nih.gov/12351624/; PMID:22802649; PMCID:PMC3412030; DOI:10.1073/pnas.1117551109; https://pubmed.ncbi.nlm.nih.gov/22802649/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID11564763_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID12351624_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID22802649_europepmc.xml', 'Primary receptor-binding and receptor-reconstitution studies report that IL-20 binds the IL22R1/IL20RB type-II IL-20 receptor complex; a separate primary structural study resolves IL-20-family receptor-sharing architecture and preserves IL20RB-containing heteromeric complex notation.', 'Promote IL-20 engagement of the IL20RB_IL22RA1 type-II receptor complex as direct molecular/receptor-complex evidence; keep the IL20RA_IL20RB type-I complex as a separate branch.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID11564763_europepmc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003963-P2-DIRECT' AND x.extraction_id='M20B-P2-R-003963-R126A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003963', 'M20B-EVID-003963-P2-RELAY', 'M20B-P2-R-003963-R126B', 'PMID:11564763; DOI:10.4049/jimmunol.167.7.3545; PMID:12351624; DOI:10.1074/jbc.M205114200', NULL, 'literature_xml', 'exact_identifier_match:PMID:11564763', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_proximal_relay_support', 'PMID:11564763; DOI:10.4049/jimmunol.167.7.3545; https://pubmed.ncbi.nlm.nih.gov/11564763/; PMID:12351624; DOI:10.1074/jbc.M205114200; https://pubmed.ncbi.nlm.nih.gov/12351624/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID11564763_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID12351624_europepmc.xml', 'In receptor-reconstitution assays, IL-20 binding to type-I or type-II IL-20 receptor complexes produced STAT3 phosphorylation and activation of a minimal STAT-binding promoter; the type-II IL20RB_IL22RA1 branch is therefore supported as an IL-20-to-STAT3 relay.', 'Record the IL20RB_IL22RA1-to-STAT3 receptor-proximal relay separately from direct receptor-complex binding and downstream tissue function; do not infer an untested JAK assignment.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID11564763_europepmc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003963-P2-RELAY' AND x.extraction_id='M20B-P2-R-003963-R126B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003973', 'M20B-EVID-003973-P2-DIRECT', 'M20B-P2-R-003973-R127A', 'PMID:11706020; DOI:10.1074/jbc.M106043200; PMID:11564763; DOI:10.4049/jimmunol.167.7.3545; PMID:12351624; DOI:10.1074/jbc.M205114200', NULL, 'literature_xml', 'exact_identifier_match:PMID:11564763', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_direct_complex_support', 'PMID:11706020; DOI:10.1074/jbc.M106043200; https://pubmed.ncbi.nlm.nih.gov/11706020/; PMID:11564763; DOI:10.4049/jimmunol.167.7.3545; https://pubmed.ncbi.nlm.nih.gov/11564763/; PMID:12351624; DOI:10.1074/jbc.M205114200; https://pubmed.ncbi.nlm.nih.gov/12351624/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_PMID11706020_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID11564763_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID12351624_europepmc.xml', 'Primary studies report IL-24 binding to both IL22R1/IL20RB and IL20RA/IL20RB heteromeric receptors; saturation binding was demonstrated after receptor transfection and endogenous receptor binding was detected in human keratinocytes.', 'Promote IL-24 engagement of the IL20RB_IL22RA1 type-II receptor complex as direct molecular/receptor-complex evidence; preserve the IL20RA_IL20RB type-I branch separately.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID11564763_europepmc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003973-P2-DIRECT' AND x.extraction_id='M20B-P2-R-003973-R127A');
