INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003963', 'M20B-EVID-003963-P2-DIRECT', 'M20B-P2-R-003963-R126A', 'PMID:11564763; DOI:10.4049/jimmunol.167.7.3545; PMID:12351624; DOI:10.1074/jbc.M205114200; PMID:22802649; PMCID:PMC3412030; DOI:10.1073/pnas.1117551109', NULL, 'literature_xml', 'exact_identifier_match:PMID:22802649', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_direct_complex_support', 'PMID:11564763; DOI:10.4049/jimmunol.167.7.3545; https://pubmed.ncbi.nlm.nih.gov/11564763/; PMID:12351624; DOI:10.1074/jbc.M205114200; https://pubmed.ncbi.nlm.nih.gov/12351624/; PMID:22802649; PMCID:PMC3412030; DOI:10.1073/pnas.1117551109; https://pubmed.ncbi.nlm.nih.gov/22802649/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID11564763_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID12351624_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID22802649_europepmc.xml', 'Primary receptor-binding and receptor-reconstitution studies report that IL-20 binds the IL22R1/IL20RB type-II IL-20 receptor complex; a separate primary structural study resolves IL-20-family receptor-sharing architecture and preserves IL20RB-containing heteromeric complex notation.', 'Promote IL-20 engagement of the IL20RB_IL22RA1 type-II receptor complex as direct molecular/receptor-complex evidence; keep the IL20RA_IL20RB type-I complex as a separate branch.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID22802649_europepmc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003963-P2-DIRECT' AND x.extraction_id='M20B-P2-R-003963-R126A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003963', 'M20B-EVID-003963-P2-FUNC', 'M20B-P2-R-003963-R126C', 'PMID:33610678; PMCID:PMC8323118; DOI:10.1016/j.jhep.2021.02.004', '33610678', 'literature_xml', 'exact_identifier_match:PMID:33610678', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_functional_support', 'PMID:33610678; PMCID:PMC8323118; DOI:10.1016/j.jhep.2021.02.004; https://pubmed.ncbi.nlm.nih.gov/33610678/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_PMID33610678.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID33610678_europepmc.xml', 'In primary mouse hepatocyte and in vivo models, IL-20 signaling through IL22R1/IL20RB increased NQO1 through ERK/p38MAPK/NRF2, promoted degradation of the transcriptional regulator IκBζ, and reduced IκBζ-dependent Il6 and Lcn2 outputs; Il20 deficiency protected against acute hepatitis and bacterial infection.', 'Record IL20RB_IL22RA1-associated ERK/p38MAPK/NRF2 and IκBζ-associated Il6/Lcn2 cellular and tissue outputs as downstream function; retain NFKBIZ/IκBζ as a bounded transcriptional-regulator candidate rather than a direct ligand-TF interaction.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL20_primary_PMID33610678_europepmc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003963-P2-FUNC' AND x.extraction_id='M20B-P2-R-003963-R126C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003964', 'M20B-EVID-003964-P2-RELAY', 'M20B-P2-R-003964-R125B', 'PMID:11418623; DOI:10.4049/jimmunol.167.1.1; PMID:12093291; DOI:10.1021/bi0202023', NULL, 'full_text_xml', 'exact_identifier_match:PMID:11418623', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_proximal_relay_support', 'PMID:11418623; DOI:10.4049/jimmunol.167.1.1; https://pubmed.ncbi.nlm.nih.gov/11418623/; PMID:12093291; DOI:10.1021/bi0202023; https://pubmed.ncbi.nlm.nih.gov/12093291/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_pubmed_abstracts.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_PMID11418623.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_PMID12093291.xml', 'Common gamma chain was indispensable for IL-21 signaling: IL-21 bound IL-21R but failed to signal in gamma-chain-deficient cells, whereas gamma-chain reconstitution enabled JAK1/JAK3 and STAT activation. An independent gamma-chain-deficient/reconstitution study further showed IL-21-induced JAK1/JAK3 phosphorylation and STAT5 activation, with JAK3 inhibition reducing proliferation.', 'Record the IL21R_IL2RG-to-JAK1/JAK3/STAT1/STAT3/STAT5 receptor-proximal relay separately from direct complex structure and cellular growth output.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_PMID11418623.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003964-P2-RELAY' AND x.extraction_id='M20B-P2-R-003964-R125B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003964', 'M20B-EVID-003964-P2-RELAY', 'M20B-P2-R-003964-R125B', 'PMID:11418623; DOI:10.4049/jimmunol.167.1.1; PMID:12093291; DOI:10.1021/bi0202023', NULL, 'full_text_xml', 'exact_identifier_match:PMID:12093291', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_proximal_relay_support', 'PMID:11418623; DOI:10.4049/jimmunol.167.1.1; https://pubmed.ncbi.nlm.nih.gov/11418623/; PMID:12093291; DOI:10.1021/bi0202023; https://pubmed.ncbi.nlm.nih.gov/12093291/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_pubmed_abstracts.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_PMID11418623.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_PMID12093291.xml', 'Common gamma chain was indispensable for IL-21 signaling: IL-21 bound IL-21R but failed to signal in gamma-chain-deficient cells, whereas gamma-chain reconstitution enabled JAK1/JAK3 and STAT activation. An independent gamma-chain-deficient/reconstitution study further showed IL-21-induced JAK1/JAK3 phosphorylation and STAT5 activation, with JAK3 inhibition reducing proliferation.', 'Record the IL21R_IL2RG-to-JAK1/JAK3/STAT1/STAT3/STAT5 receptor-proximal relay separately from direct complex structure and cellular growth output.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_PMID12093291.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003964-P2-RELAY' AND x.extraction_id='M20B-P2-R-003964-R125B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003964', 'M20B-EVID-003964-P2-FUNC', 'M20B-P2-R-003964-R125C', 'PMID:19608866; PMID:17234735; PMCID:PMC1885510; DOI:10.1182/blood-2006-10-054973', '17234735', 'full_text_xml', 'exact_identifier_match:PMID:17234735', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_functional_support', 'PMID:19608866; https://pubmed.ncbi.nlm.nih.gov/19608866/; PMID:17234735; PMCID:PMC1885510; DOI:10.1182/blood-2006-10-054973; https://pubmed.ncbi.nlm.nih.gov/17234735/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_pubmed_abstracts.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_PMID17234735.xml', 'Recombinant IL-21 increased JAK3/STAT3 activation and cell growth in ALK-positive anaplastic large-cell lymphoma models, while IL-21R siRNA reduced STAT3 activation and growth. In primary and engineered lymphoid models, IL-21R tyrosine 510 supported STAT1/STAT3 phosphorylation and proliferation; IL-21 also weakly activated Shc/Akt, and MAPK/PI3K inhibition reduced proliferation.', 'Record IL-21R-dependent JAK3/STAT3-associated growth and IL-21R-linked STAT1/STAT3, MAPK, and PI3K proliferation outputs as downstream cellular function, separate from receptor-complex assembly and relay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL21_batch125_PMID17234735.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003964-P2-FUNC' AND x.extraction_id='M20B-P2-R-003964-R125C');
