INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003982', 'M20B-EVID-003982-P2-RELAY', 'M20B-P2-R-003982-R129B', 'PMID:8557662; PMID:9813029; PMID:8624802', NULL, 'literature_xml', 'exact_identifier_match:PMID:9813029', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_proximal_relay_support', 'PMID:8557662; https://pubmed.ncbi.nlm.nih.gov/8557662/; PMID:9813029; https://pubmed.ncbi.nlm.nih.gov/9813029/; PMID:8624802; https://pubmed.ncbi.nlm.nih.gov/8624802/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL4_jak_PMID8557662_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL4_jak_PMID9813029_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL4_jak_PMID8624802_europepmc.xml', 'Gamma-chain-deficient human B cells show loss or marked reduction of IL-4-induced JAK3 and STAT6 activation, while primary/common-gamma receptor studies support IL-4R-linked JAK1/JAK3 signaling and gamma-chain/JAK3-dependent STAT5 activation.', 'Record the IL4RA_IL2RG-to-JAK1/JAK3-STAT6/STAT5 type-I relay separately from direct binding and downstream function.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL4_jak_PMID9813029_europepmc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003982-P2-RELAY' AND x.extraction_id='M20B-P2-R-003982-R129B');
