INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003979', 'M20B-EVID-003979-P2-RELAY', 'M20B-P2-R-003979-R129B', 'PMID:18005266; PMID:11709700', NULL, 'literature_xml', 'exact_identifier_match:PMID:11709700', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_proximal_relay_support', 'PMID:18005266; https://pubmed.ncbi.nlm.nih.gov/18005266/; PMID:11709700; https://pubmed.ncbi.nlm.nih.gov/11709700/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL4_signal_PMID18005266_europepmc.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL4_signal_PMID11709700_europepmc.xml', 'Primary type-II receptor models support IL-4-induced JAK1/MAPK signaling, while human keratinocyte studies report IL-4-induced JAK1/JAK2, STAT6, ERK, and p38 activation in a type-II IL4RA/IL13RA1 receptor context.', 'Record the IL4RA_IL13RA1-to-JAK1/JAK2-STAT6-ERK/p38 type-II relay separately from receptor binding and airway function; do not transfer the type-I gamma-chain JAK3 assignment.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL4_signal_PMID11709700_europepmc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003979-P2-RELAY' AND x.extraction_id='M20B-P2-R-003979-R129B');
