INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004013', 'M20B-EVID-004013-P2-FUNC', 'M20B-P2-R-004013-R133C', 'PMID:23950756; PMCID:PMC3738877; DOI:10.3389/fendo.2013.00098; PMID:12538620; DOI:10.1210/en.2002-220828', NULL, 'full_text_xml', 'exact_identifier_match:PMID:12538620', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_functional_support', 'PMID:23950756; https://pubmed.ncbi.nlm.nih.gov/23950756/; PMCID:PMC3738877; https://pmc.ncbi.nlm.nih.gov/articles/PMC3738877/; DOI:10.3389/fendo.2013.00098; PMID:12538620; https://pubmed.ncbi.nlm.nih.gov/12538620/; DOI:10.1210/en.2002-220828; local=data/raw/evidence/module20_24_supervised_cli_phase2/PMC3738877_bioc.json', 'Insulin stimulation of mouse fibroblasts expressing functional IGF1R but no insulin receptor produces a distinct IGF1R-mediated gene-expression program; in a separate IGF1R-deficient fetal brown-adipocyte model, insulin-induced FAS, ADD1/SREBP, UCP1, and C/EBPalpha outputs are impaired or absent.', 'Promote an IGF1R-context insulin gene-expression and brown-adipocyte differentiation output, while leaving the terminal TF identity and SCI-cell function unresolved.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INS2_IGF1R_PMID12538620_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004013-P2-FUNC' AND x.extraction_id='M20B-P2-R-004013-R133C');
