INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004013', 'M20B-EVID-004013-P2-DIRECT', 'M20B-P2-R-004013-R133A', 'PMID:2552816; DOI:10.1152/ajpcell.1989.257.4.C612', '2552816', 'full_text_xml', 'exact_identifier_match:PMID:2552816', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_cross_receptor_support', 'PMID:2552816; https://pubmed.ncbi.nlm.nih.gov/2552816/; DOI:10.1152/ajpcell.1989.257.4.C612; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INS2_IGF1R_PMID2552816_core.xml', 'Equilibrium binding and cross-linked ligand-receptor complexes in toad urinary bladder identify distinct insulin and IGF-I receptors; insulin crosses over to the IGF-I receptor at substantially lower affinity than to the insulin receptor.', 'Promote insulin/INS2 engagement of IGF1R as a lower-affinity cross-receptor interaction, not as the primary physiological insulin receptor.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INS2_IGF1R_PMID2552816_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004013-P2-DIRECT' AND x.extraction_id='M20B-P2-R-004013-R133A');
