INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004014', 'M20B-EVID-004014-P2-RELAY', 'M20B-P2-R-004014-R134B', 'PMID:6178977; DOI:10.1038/298667a0; PMID:11526109; DOI:10.1074/jbc.M105194200; PMID:34826178; DOI:10.1111/febs.16299', NULL, 'full_text_xml', 'exact_identifier_match:PMID:34826178', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_proximal_relay_support', 'PMID:6178977; https://pubmed.ncbi.nlm.nih.gov/6178977/; DOI:10.1038/298667a0; PMID:11526109; https://pubmed.ncbi.nlm.nih.gov/11526109/; DOI:10.1074/jbc.M105194200; PMID:34826178; https://pubmed.ncbi.nlm.nih.gov/34826178/; DOI:10.1111/febs.16299; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INS2_INSR_PMID6178977_core.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INS2_INSR_PMID11526109_core.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INS2_INSR_PMID34826178_core.xml', 'Insulin stimulates INSR tyrosine phosphorylation; insulin also drives IRS1 recruitment/targeting and a broad, site-specific INSR phosphorylation program across juxtamembrane, kinase-domain, and C-terminal residues.', 'Record the INSR-to-IRS1 receptor-proximal relay separately from ligand binding and cellular outputs.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INS2_INSR_PMID34826178_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004014-P2-RELAY' AND x.extraction_id='M20B-P2-R-004014-R134B');
