INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004036', 'M20B-EVID-004036-P2-FUNC', 'M20B-P2-R-004036-R137C', 'PMID:29535183; DOI:10.1530/JME-17-0152; PMID:27243554; DOI:10.1111/bph.13522', NULL, 'full_text_xml', 'exact_identifier_match:PMID:27243554', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_functional_support', 'PMID:29535183; https://pubmed.ncbi.nlm.nih.gov/29535183/; DOI:10.1530/JME-17-0152; PMID:27243554; https://pubmed.ncbi.nlm.nih.gov/27243554/; DOI:10.1111/bph.13522; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID29535183_core.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID27243554_core.xml', 'INSL5/RXFP4 signaling produces ERK1/2, Akt, S6RP, cAMP, and enteroendocrine GLP-1 secretion changes in NCI-H716 and related models; RXFP4 pathway perturbation and receptor expression support branch association.', 'Promote RXFP4-associated endocrine/cellular output, retaining the existing Module 23B function edge and leaving terminal TF identity unknown.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID27243554_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004036-P2-FUNC' AND x.extraction_id='M20B-P2-R-004036-R137C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004036', 'M20B-EVID-004036-P2-RELAY', 'M20B-P2-R-004036-R137B', 'PMID:27243554; DOI:10.1111/bph.13522', '27243554', 'full_text_xml', 'exact_identifier_match:PMID:27243554', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_proximal_relay_support', 'PMID:27243554; https://pubmed.ncbi.nlm.nih.gov/27243554/; DOI:10.1111/bph.13522; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID27243554_core.xml', 'INSL5 activation of RXFP4 inhibits forskolin-stimulated cAMP, recruits Gαi/o and beta-arrestin/GRK2, and increases ERK1/2, p38MAPK, and Akt signaling in engineered receptor systems.', 'Record the RXFP4-to-Gαi/o-cAMP/ERK/p38/Akt receptor-proximal relay separately from direct receptor engagement and endocrine output.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID27243554_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004036-P2-RELAY' AND x.extraction_id='M20B-P2-R-004036-R137B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E002566', 'M22B-EVID-004126', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID27243554_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-004126' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000190', 'M23B-EVID-000273', 'M23B-P2-R-RECOVERY-INSL5-RXFP4-DIRECT-000001', 'PMID:18576448; PMCID:PMC2699039; PMID:27243554; PMCID:PMC4913371', '18576448', 'full_text_xml', 'exact_identifier_match:PMID:27243554', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:18576448; PMCID:PMC2699039; https://pubmed.ncbi.nlm.nih.gov/18576448/; https://pmc.ncbi.nlm.nih.gov/articles/PMC2699039/', 'Primary INSL5 synthesis and receptor studies support a high-affinity cognate INSL5-RXFP4 interaction and receptor activation; receptor specificity was evaluated against other relaxin-family receptors. The direct record is retained at the ligand-receptor level, while the later signaling paper is used separately for intracellular relay evidence.', 'Retain INSL5-RXFP4 as a direct cognate ligand-receptor comparator supported by primary synthesis/receptor studies. Do not infer a traumatic-SCI role or merge direct receptor evidence with the Gi/o-ERK/Akt relay.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID27243554_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000273' AND x.extraction_id='M23B-P2-R-RECOVERY-INSL5-RXFP4-DIRECT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000191', 'M23B-EVID-000274', 'M23B-P2-R-RECOVERY-INSL5-RXFP4-RELAY-000001', 'PMID:27243554; PMCID:PMC5406383; DOI:10.1111/bph.13522', '27243554', 'full_text_xml', 'exact_identifier_match:PMID:27243554', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:27243554; PMCID:PMC5406383; DOI:10.1111/bph.13522; https://pubmed.ncbi.nlm.nih.gov/27243554/; https://pmc.ncbi.nlm.nih.gov/articles/PMC5406383/', 'In CHO cells stably expressing RXFP4, INSL5 inhibited forskolin-stimulated cAMP and increased ERK1/2, p38MAPK, Akt Ser473/Thr308, and S6 phosphorylation. Pertussis-toxin sensitivity and rescue with PTX-insensitive Gi/o mutants supported Gi/o coupling; BRET assays supported GRK2/beta-arrestin recruitment and Rab5a-associated internalization. Separate MIN6 and NCI-H716 experiments showed inhibition of glucose-stimulated insulin secretion/Ca2+ mobilization and forskolin-stimulated cAMP. No terminal TF was established.', 'Promote the INSL5-RXFP4-Gi/o-cAMP/ERK/p38/Akt/S6 receptor-proximal relay in the tested engineered and endocrine comparator systems. Keep insulin/Ca2+ and proliferation outputs separate from the relay and do not infer a terminal TF or SCI transfer.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID27243554_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000274' AND x.extraction_id='M23B-P2-R-RECOVERY-INSL5-RXFP4-RELAY-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000242', 'M23B-EVID-000275', 'M23B-P2-R-C23B271-000009', 'PMID:29535183; DOI:10.1530/JME-17-0152; PMID:27243554; DOI:10.1111/bph.13522', NULL, 'full_text_xml', 'exact_identifier_match:PMID:27243554', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_support', 'PMID:29535183; https://pubmed.ncbi.nlm.nih.gov/29535183/; DOI:10.1530/JME-17-0152; PMID:27243554; https://pubmed.ncbi.nlm.nih.gov/27243554/; DOI:10.1111/bph.13522', 'Primary INSL5 studies report INSL5-induced ERK1/2, AKT, S6RP, cAMP, and GLP-1 secretion changes in RXFP4-expressing enteroendocrine/epithelial models. A separate primary engineered-receptor study supports Gi/o-linked cAMP and ERK signaling downstream of RXFP4.', 'The primary studies support an INSL5-RXFP4-associated endocrine signaling/output branch: INSL5 elicited ERK1/2, AKT, S6RP, and cAMP changes in RXFP4-expressing models and altered GLP-1 secretion, while engineered RXFP4 studies support Gi/o-linked cAMP/ERK signaling. This is receptor-proximal/downstream functional evidence, not a terminal-TF result or SCI model.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_INSL5_RXFP3_boundary_PMID27243554_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000275' AND x.extraction_id='M23B-P2-R-C23B271-000009');
