ct WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_KISS1_KISS1R_PMID11527393_core.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004053-P2-FUNC' AND x.extraction_id='M20B-P2-R-004053-R139C');
