INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004138', 'M20B-EVID-004138-P2-DIRECT', 'M20B-P2-R-004138-R153A', 'PMID:36828548; PMCID:PMC9997507; DOI:10.1083/jcb.202211031', '36828548', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.202211031;PMCID:PMC9997507;PMID:36828548', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_receptor_support', 'PMID:36828548; PMCID:PMC9997507; DOI:10.1083/jcb.202211031; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_LGI2_ADAM23_PMID36828548_pmc.html', 'ADAM23-Fc pulldown after HEK293T co-transfection recovered LGI2, and LGI2 co-localized with ADAM23 at juxtaparanodal Kv1 complexes in mouse myelinated nerve.', 'Promote direct LGI2 association with ADAM23 while retaining family-comparative and heterologous-assay limits.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_LGI2_ADAM23_PMID36828548_pmc.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004138-P2-DIRECT' AND x.extraction_id='M20B-P2-R-004138-R153A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004138', 'M20B-EVID-004138-P2-FUNC', 'M20B-P2-R-004138-R153C', 'PMID:36828548; PMCID:PMC9997507; DOI:10.1083/jcb.202211031', '36828548', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.202211031;PMCID:PMC9997507;PMID:36828548', 'supporting_validated_claim', 'B', 'L3', 'validated_primary_observation', 'validated_conditional_functional_support', 'PMID:36828548; PMCID:PMC9997507; DOI:10.1083/jcb.202211031; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_LGI2_ADAM23_PMID36828548_pmc.html', 'Complete loss of ADAM23-dependent JXP Kv1 complexes lengthens the refractory period of myelinated axons; combined Lgi2/Lgi3 loss abolishes JXP Kv1 clustering, but Lgi2 loss alone does not.', 'Promote conditional LGI2/ADAM23-associated Kv1-clustering and axonal refractory-period outputs while leaving a standalone LGI2-only effect and terminal TF unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_LGI2_ADAM23_PMID36828548_pmc.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004138-P2-FUNC' AND x.extraction_id='M20B-P2-R-004138-R153C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004138', 'M20B-EVID-004138-P2-RELAY', 'M20B-P2-R-004138-R153B', 'PMID:36828548; PMCID:PMC9997507; DOI:10.1083/jcb.202211031', '36828548', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.202211031;PMCID:PMC9997507;PMID:36828548', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_complex_pathway_support', 'PMID:36828548; PMCID:PMC9997507; DOI:10.1083/jcb.202211031; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_LGI2_ADAM23_PMID36828548_pmc.html', 'Lgi2 deletion alone leaves JXP Kv1 localization largely normal, while combined Lgi2/Lgi3 deletion abolishes JXP Kv1-complex accumulation; Adam23 loss likewise removes the complex, supporting a partially redundant LGI2/ADAM23 receptor-complex/pathway branch.', 'Promote a conditional LGI2–ADAM23 receptor-complex/pathway record for JXP Kv1 clustering and stability; terminal TF remains unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_LGI2_ADAM23_PMID36828548_pmc.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004138-P2-RELAY' AND x.extraction_id='M20B-P2-R-004138-R153B');
