INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003899', 'M20B-EVID-003899-P2-FUNC', 'M20B-P2-R-003899-R116F', 'PMID:18434416; PMCID:PMC7188307; DOI:10.1242/dev.018044', '18434416', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC7188307', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'Exact primary mouse Ihh cartilage function paper retrieved; no generic Hedgehog review, SHH-only reporter, or terminal-TF occupancy claim was transferred.', 'Upregulated Ihh/Hedgehog signaling accelerated chondrocyte hypertrophy in PTHrP-null embryonic and postnatal cartilage models; the effect was altered by Ptch1/Smo and cyclopamine perturbations and was associated with Bmp and Wnt/beta-catenin activity.', 'The authors conclude that increased Indian hedgehog signaling accelerates chondrocyte hypertrophy, with Ptch1/Smo and cyclopamine perturbations altering the phenotype and BMP/Wnt-beta-catenin signaling implicated as downstream mediators.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMC7188307_IHH_PTCH1_SMO_full.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003899-P2-FUNC' AND x.extraction_id='M20B-P2-R-003899-R116F');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003899', 'M20B-EVID-003899-P2-RELAY', 'M20B-P2-R-003899-R116E', 'PMID:18434416; PMCID:PMC7188307; DOI:10.1242/dev.018044', '18434416', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC7188307', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'Exact primary mouse Ihh/PTCH1/Smo pathway paper retrieved through PubMed/PMC. Direct purified ligand–receptor binding and SCI transfer were not inferred.', 'The mouse chondrocyte study manipulated Ihh pathway activity using Ihh overexpression, Ptch1 removal, Smo removal, and cyclopamine. The paper defines the Ptch1-to-Smo receptor-proximal relay and reports that pathway activation increases Hh target-gene expression including Gli1, Ptch1, and Hhip.', 'The authors conclude that Indian hedgehog signaling promotes chondrocyte hypertrophy independently of PTHrP; Ptch1/Smo and cyclopamine perturbations establish pathway dependence, while BMP and Wnt/beta-catenin signaling may mediate the downstream effect.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMC7188307_IHH_PTCH1_SMO_full.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003899-P2-RELAY' AND x.extraction_id='M20B-P2-R-003899-R116E');
