INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003832', 'M20B-EVID-003832-P2-DIRECT', 'M20B-P2-R-003832-R111A', 'PMID:24509440; PMCID:PMC5030467; DOI:10.1016/j.matbio.2014.01.016', '24509440', 'full_text_xml', 'exact_identifier_match:PMID:24509440', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'M20B-C-PH2-R-003832-R111A', 'Exact perlecan/alpha2beta1 primary adhesion study retrieved; singleton ITGA2 inference excluded.', 'Human vascular smooth-muscle cells bound the perlecan protein core through an interaction involving the α2β1 integrin; domain III and domain V/endorepellin contributed to the adhesion context.', 'Abstract; Results', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMID24509440_HSPG2_ITGA2B1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003832-P2-DIRECT' AND x.extraction_id='M20B-P2-R-003832-R111A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003832', 'M20B-EVID-003832-P2-FUNC', 'M20B-P2-R-003832-R111B', 'PMID:24509440; PMCID:PMC5030467; DOI:10.1016/j.matbio.2014.01.016', '24509440', 'full_text_xml', 'exact_identifier_match:PMID:24509440', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'M20B-C-PH2-R-003832-R111B', 'Exact perlecan adhesion/growth-factor primary study; functional layer separated from complex-level binding.', 'Perlecan glycanation and protein-core interactions modulated human smooth-muscle-cell adhesion, proliferation, and FGF2 signaling; endothelial perlecan promoted FGF1 and FGF2 signaling in a distinct glycan context.', 'Abstract; Results', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMID24509440_HSPG2_ITGA2B1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003832-P2-FUNC' AND x.extraction_id='M20B-P2-R-003832-R111B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003833', 'M20B-EVID-003833-P2-DIRECT', 'M20B-P2-R-003833-R111A', 'PMID:24509440; PMCID:PMC5030467; DOI:10.1016/j.matbio.2014.01.016', '24509440', 'full_text_xml', 'exact_identifier_match:PMID:24509440', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'M20B-C-PH2-R-003833-R111A', 'Exact perlecan/alpha2beta1 primary adhesion study; no isolated ITGB1 assay recovered.', 'The perlecan adhesion record involved the α2β1 integrin heterodimer, so the queued ITGB1 label is supported only as the beta1-containing complex context.', 'Abstract; Results', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMID24509440_HSPG2_ITGA2B1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003833-P2-DIRECT' AND x.extraction_id='M20B-P2-R-003833-R111A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003833', 'M20B-EVID-003833-P2-FUNC', 'M20B-P2-R-003833-R111B', 'PMID:24509440; PMCID:PMC5030467; DOI:10.1016/j.matbio.2014.01.016', '24509440', 'full_text_xml', 'exact_identifier_match:PMID:24509440', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'M20B-C-PH2-R-003833-R111B', 'Exact perlecan/alpha2beta1 primary study; subunit-alone inference explicitly excluded.', 'The same primary study reports perlecan-associated adhesion, proliferation, and FGF signaling outputs, but none is attributable to ITGB1 alone rather than the tested α2β1 complex and glycanation context.', 'Abstract; Results', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMID24509440_HSPG2_ITGA2B1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003833-P2-FUNC' AND x.extraction_id='M20B-P2-R-003833-R111B');
