INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003728', 'M20B-EVID-003728-P2-FUNC', 'M20B-P2-R-003728-R102B', 'PMCID:PMC4682789; PMID:26658875; DOI:10.1523/JNEUROSCI.2310-15.2015', '26658875', 'full_text_xml', 'exact_identifier_match:PMID:26658875', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_functional_output', 'PMCID:PMC4682789; PMID:26658875; DOI:10.1523/JNEUROSCI.2310-15.2015; https://pmc.ncbi.nlm.nih.gov/articles/PMC4682789/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMID26658875_GRPR_PI3K.xml', 'Intrathecal GRP induced intense scratching in mice; GRPR antagonists or PI3K-gamma inhibition reduced scratching, and an Akt activator induced scratching. GRPR blockade or PI3K-gamma inhibition also reversed scratching in a dry-skin model.', 'Promote GRP-GRPR-PI3K-gamma/Akt-dependent itch transmission as a downstream functional output in the tested mouse models. Do not generalize itch behavior to SCI repair, infer a terminal TF, or collapse it into the receptor-proximal relay record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMID26658875_GRPR_PI3K.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003728-P2-FUNC' AND x.extraction_id='M20B-P2-R-003728-R102B');
