INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003912', 'M20B-EVID-003912-P2-DIRECT', 'M20B-P2-R-003912-R118A', 'PMID:38287195; DOI:10.1038/s41594-023-01190-6; PMID:12023369', '38287195', 'full_text_xml', 'exact_identifier_match:PMID:38287195', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_complex_support', 'PMID:38287195; DOI:10.1038/s41594-023-01190-6; PMID:12023369; DOI:10.4049/jimmunol.168.11.5699; https://pubmed.ncbi.nlm.nih.gov/38287195/; https://pubmed.ncbi.nlm.nih.gov/12023369/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMID38287195_IL12_IL23_complex.xml; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_IL12_IL23_batch118_pubmed_abstracts.xml', 'Primary structural and receptor-identification studies support the IL-23 receptor complex containing IL-23R and shared IL-12Rbeta1: IL-23 engages the complete extracellular receptor assembly, binds IL-23R, and uses IL-12Rbeta1 but not IL-12Rbeta2.', 'Promote IL-23 engagement of the IL12RB1_IL23R receptor complex as direct receptor-complex evidence. Preserve the IL23R/IL12RB1 complex and do not substitute IL12RB2 or infer a standalone IL23R receptor.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PMID38287195_IL12_IL23_complex.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003912-P2-DIRECT' AND x.extraction_id='M20B-P2-R-003912-R118A');
