INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_RTN4R_PMC9121835_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004759', 'M20B-EVID-004759-P2-DIRECT', 'M20B-P2-R-004759-R243A', 'PMID:24453941; PMCID:PMC3891622; DOI:10.1371/journal.pbio.1001763', '24453941', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3891622', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_fulltext', 'validated_direct_receptor_support', 'PMID:24453941; PMCID:PMC3891622; DOI:10.1371/journal.pbio.1001763; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_S1PR2_PMC3891622_fulltext.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_NGFR_RTN4R_S1PR2_primary_records.xml', 'Nogo-A-Delta20 binds S1PR2 through extracellular receptor-loop sites distinct from the S1P pocket; co-immunoprecipitation, receptor-membrane binding, and a biosensor assay supported the interaction, including a reported approximately 142 nM affinity for Nogo-A-ext in the tested membrane preparation.', 'Promote direct Nogo-A-Delta20/RTN4-to-S1PR2 engagement with explicit ligand-domain and receptor-loop specificity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_S1PR2_PMC3891622_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004759-P2-DIRECT' AND x.extraction_id='M20B-P2-R-004759-R243A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004759', 'M20B-EVID-004759-P2-FUNC', 'M20B-P2-R-004759-R243C', 'PMID:24453941; PMCID:PMC3891622; DOI:10.1371/journal.pbio.1001763; PMID:31235580; PMCID:PMC6628809; DOI:10.1073/pnas.1905309116', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC3891622', 'candidate_requires_review', 'B', 'L2', 'validated_primary_fulltext', 'validated_functional_output', 'PMID:24453941; PMCID:PMC3891622; DOI:10.1371/journal.pbio.1001763; PMID:31235580; PMCID:PMC6628809; DOI:10.1073/pnas.1905309116; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_S1PR2_PMC3891622_fulltext.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_NGFR_RTN4R_S1PR2_primary_records.xml', 'Blocking or deleting S1PR2 reverses Nogo-A-Delta20/myelin inhibition of cell spreading and neurite outgrowth and increases hippocampal/cortical LTP; Nogo-A or S1PR2 deletion also improves vascular sprouting and neurological recovery after cerebral ischemia in mice.', 'Promote Nogo-A/S1PR2-associated neurite, synaptic-plasticity, and conditional vascular-repair outputs; terminal TF identity remains unknown.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_S1PR2_PMC3891622_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004759-P2-FUNC' AND x.extraction_id='M20B-P2-R-004759-R243C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004759', 'M20B-EVID-004759-P2-RELAY', 'M20B-P2-R-004759-R243B', 'PMID:24453941; PMCID:PMC3891622; DOI:10.1371/journal.pbio.1001763; PMID:26290381; DOI:10.1242/jcs.167981', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC3891622', 'candidate_requires_review', 'B', 'L1', 'validated_primary_fulltext', 'validated_receptor_proximal_relay_support', 'PMID:24453941; PMCID:PMC3891622; DOI:10.1371/journal.pbio.1001763; PMID:26290381; DOI:10.1242/jcs.167981; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_S1PR2_PMC3891622_fulltext.xml', 'Nogo-A-Delta20/S1PR2 signaling activates a G13-LARG-RhoA branch; Nogo-A induces S1PR2 internalization and TSPAN3-dependent S1PR2 clustering/complex organization, while S1PR2 blockade or silencing suppresses Nogo-A-induced RhoA activation.', 'Promote the RTN4/S1PR2 receptor-proximal G13-LARG-RhoA relay and retain TSPAN3 as a modulatory complex organizer rather than a direct ligand receptor.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_RTN4_S1PR2_PMC3891622_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004759-P2-RELAY' AND x.extraction_id='M20B-P2-R-004759-R243B');
