INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004814', 'M20B-EVID-004814-P2-DIRECT', 'M20B-P2-R-004814-R249A', 'PMID:23104057; PMCID:PMC3590443; DOI:10.1038/nsmb.2416', '23104057', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3590443', 'candidate_requires_review', 'B', 'L1', 'validated_primary_abstract', 'validated_receptor_complex_structural_claim', 'PMID:23104057; PMCID:PMC3590443; DOI:10.1038/nsmb.2416; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema3A_PMC3590443_fulltext.xml', 'Biophysical and cellular analyses of the Sema3A/PlexinA2/neuropilin-1 ternary complex showed a dimeric semaphorin-receptor assembly in which neuropilin stabilizes a canonical Sema3-Plexin interaction.', 'Promote Sema3A interaction only as a ternary PlexinA2/neuropilin-1 receptor-complex edge; do not infer free PlexinA2 binding independent of neuropilin.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema3A_PMC3590443_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004814-P2-DIRECT' AND x.extraction_id='M20B-P2-R-004814-R249A');
