INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004816', 'M20B-EVID-004816-P2-RELAY', 'M20B-P2-R-004816-R249B', 'PMID:15721238; DOI:10.1016/j.neuron.2005.01.013; PMID:34039996; PMCID:PMC8155012; DOI:10.1038/s41467-021-23541-x', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC8155012', 'candidate_requires_review', 'B', 'L2', 'validated_primary_abstract', 'validated_receptor_complex_relay', 'PMID:15721238; DOI:10.1016/j.neuron.2005.01.013; PMID:34039996; PMCID:PMC8155012; DOI:10.1038/s41467-021-23541-x; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema3A_primary_records.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema3A_PMC8155012_fulltext.xml', 'Neuropilin-1 signaling was mediated principally by PlexinA4 in the sensory/sympathetic neuron comparison; the structural complex places PlexinA4 membrane-proximal regions for intracellular active-dimer formation.', 'Record NRP1/PlexinA4 receptor-complex assignment and membrane-proximal dimerization relay; no unique kinase or terminal TF is established.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema3A_PMC8155012_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004816-P2-RELAY' AND x.extraction_id='M20B-P2-R-004816-R249B');
