INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004877', 'M20B-EVID-004877-P2-FUNC', 'M20B-P2-R-004877-R252B', 'PMID:12879062; PMID:17377534; PMCID:PMC5353663; DOI:10.1038/nature01790; DOI:10.1038/ncomms14666', '12879062', 'full_text_xml', 'exact_identifier_match:DOI:10.1038/ncomms14666;PMCID:PMC5353663', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_full_text', 'validated_integrin_functional_output', 'PMID:12879062; PMID:17377534; PMCID:PMC5353663; DOI:10.1038/nature01790; DOI:10.1038/ncomms14666; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema5_Sema7_primary_records.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema7A_PMC5353663_fulltext.xml', 'Sema7A/beta1-integrin signaling supported axon outgrowth, embryonic tract formation, and adult-born granule-cell dendrite/spine development; alpha1beta1-dependent immune cytokine production and inflammatory phenotypes were also reported in separate primary models.', 'Retain conditional integrin-associated neural and immune outputs while keeping the alpha1beta1 complex, PlexinC1 branch, and terminal TFs distinct; no SCI-specific function is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema7A_PMC5353663_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004877-P2-FUNC' AND x.extraction_id='M20B-P2-R-004877-R252B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004878', 'M20B-EVID-004878-P2-FUNC', 'M20B-P2-R-004878-R252A', 'PMID:28281529; PMCID:PMC5353663; DOI:10.1038/ncomms14666', '28281529', 'full_text_xml', 'exact_identifier_match:DOI:10.1038/ncomms14666;PMCID:PMC5353663', 'supporting_validated_claim', 'B', 'L2', 'validated_primary_full_text', 'validated_PlexinC1_dependent_function', 'PMID:28281529; PMCID:PMC5353663; DOI:10.1038/ncomms14666; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema7A_PMC5353663_fulltext.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC5353663_Sema7A_integrin_PlexinC1_full.html', 'In adult mouse dentate gyrus, Sema7A inhibited early neural-progenitor proliferation through PlexinC1 in vitro and in vivo; Sema7A and PlexinC1 knockout mice showed concordant increased proliferation, while later dendritic effects used beta1-integrin receptors rather than PlexinC1.', 'Retain Sema7A/PlexinC1-dependent inhibition of early progenitor proliferation as an exact functional output; direct purified Sema7A-PlexinC1 affinity, intracellular relay molecules, terminal TF, and SCI transfer remain unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema7A_PMC5353663_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004878-P2-FUNC' AND x.extraction_id='M20B-P2-R-004878-R252A');
