INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_B22B_fulltext/html/PMC87113.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_pdf', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_IFNG_PYK2_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_pdf', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PDGF_PI3K_fulltext_7519847.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'M21B-P2-R-000021', 'PMID:20038584', '20038584', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m109.037341;PMCID:PMC2844188', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC2844188; PMID:20038584; DOI:10.1074/jbc.M109.037341; PMID:21558270; DOI:10.1073/pnas.0837789100', 'In TNFR2-expressing HeLa and Jurkat systems and primary human T cells, receptor-selective membrane-TNF stimulation caused TNFR2-specific p100 processing, p52/RelB nuclear translocation, and cytosolic TRAF2 depletion; the study separated this alternative NF-kappaB branch from the stronger TNFR1 classical NF-kappaB response. The linked TNFR2 review/primary record also supports TRAF2-dependent NF-kappaB/JNK signaling, but no universal TRAF2-to-JNK ordering was inferred from the full-text paper.', 'The authors conclude that membrane TNF activates TNFR2 to deplete TRAF2 and trigger the alternative NF-kappaB pathway through p100 processing, p52 generation and RelB nuclear translocation, while TNFR1 preferentially drives the classical NF-kappaB branch. The TNFR2/JNK component remains bounded to linked primary evidence and is not merged with the measured alternative-NF-kappaB sequence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC2844188_TNFR2_p100_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='M21B-P2-R-000021');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'M21B-P2-R-000036', 'PMID:20038584; PMCID:PMC2844188; DOI:10.1074/jbc.M109.037341', '20038584', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m109.037341;PMCID:PMC2844188', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:20038584; PMCID:PMC2844188; DOI:10.1074/jbc.M109.037341; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2844188.html', 'TNFR2-specific oligomerized or membrane TNF induced IL-8 in TNFR2-expressing HeLa systems, was blocked by TNFR2-Fc but not TNFR1-Fc, and shifted signaling toward p100 processing, p52/RelB nuclear accumulation, TRAF2 depletion, and NIK accumulation rather than the TNFR1-associated p65/p50 branch. The same TNFR2-specific membrane-TNF system induced p100 processing in co-culture, and TNFR2-specific stimulation induced p100 processing in a subset of primary human T-cell samples.', 'The authors conclude that membrane or oligomerized TNF selectively activates TNFR2 and drives a TRAF2/cIAP/TRAF3/NIK-associated alternative NF-kappaB program with p100 processing, p52/RelB nuclear signaling, and IL-8 output, distinct from the TNFR1 p65/p50 branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC2844188_TNFR2_p100_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='M21B-P2-R-000036');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'P2MAN-M21B-M21B-EVID-000021-PMID_20038584', 'PMID:20038584', '20038584', 'full_text_html', 'exact_identifier_match:PMCID:PMC2844188', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC2844188_TNFR2_p100_full.html; M21B-EVID-000021; identifier: PMID:20038584; PMCID:PMC2844188', 'Oligomerized/membrane TNF activated TNFR2-associated p100 processing and nuclear translocation of p52/RelB in multiple cell lines, whereas non-oligomerized soluble TNF was weak or inactive for this alternative NF-κB output.', 'The authors conclude that TNFR2, unlike TNFR1 in the tested setting, can trigger p100 processing and that ligand form controls this branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC2844188_TNFR2_p100_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000021-PMID_20038584');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000069', 'M21B-EVID-000022', 'M21B-P2-R-000022', 'PMID:22933014', '22933014', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s00401-012-1034-0;PMCID:PMC3508279', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC3508279; PMID:22933014; DOI:10.1007/s00401-012-1034-0', 'In the cuprizone-demylinated mouse corpus callosum, activated astrocytes and microglia expressed TNFR1/TNFR2, while TNFR2 deficiency abolished astrocyte CXCL12 upregulation and reduced CXCR4-positive NG2-positive OPCs. Lentiviral CXCL12 delivery rescued OPC proliferation and myelin expression in acutely demyelinated TNFR2-null mice; chronic demyelination required CXCL12-expressing astrocyte engraftment.', 'The authors conclude that TNFR2 activity in activated astrocytes induces CXCL12 during demyelination and that the CXCL12-CXCR4 axis promotes OPC proliferation and differentiation/remyelination. This is a downstream CNS repair relay, not a direct TNFR2-to-CXCL12 molecular interaction and not a traumatic-SCI-specific result.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC3508279_TNFR2_CXCL12_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000022' AND x.extraction_id='M21B-P2-R-000022');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000069', 'M21B-EVID-000022', 'M21B-P2-R-000037', 'PMID:22933014; PMCID:PMC3508279; DOI:10.1007/s00401-012-1034-0', '22933014', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s00401-012-1034-0;PMCID:PMC3508279', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:22933014; PMCID:PMC3508279; DOI:10.1007/s00401-012-1034-0; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC3508279.html', 'In cuprizone-demyelinated mouse corpus callosum, activated astrocytes expressed TNFR1/TNFR2 and oligodendrocyte progenitors expressed more TNFR2 than TNFR1. TNFR2-null mice had reduced astrocytic CXCL12 and fewer CXCR4-positive NG2 progenitors; CXCR4 antagonism reduced corpus-callosum OPC proliferation, supporting a TNFR2-to-astrocyte-CXCL12-to-CXCR4-OPC functional relay during remyelination.', 'The authors conclude that astrocytic TNFR2 is required for CXCL12 expression and that CXCL12/CXCR4 signaling regulates OPC proliferation within the demyelinated adult CNS.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC3508279_TNFR2_CXCL12_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000022' AND x.extraction_id='M21B-P2-R-000037');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000069', 'M21B-EVID-000022', 'P2MAN-M21B-M21B-EVID-000022-PMID_22933014', 'PMID:22933014', '22933014', 'full_text_html', 'exact_identifier_match:PMCID:PMC3508279', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC3508279_TNFR2_CXCL12_full.html; M21B-EVID-000022; identifier: PMID:22933014; PMCID:PMC3508279', 'Cuprizone exposure increased TNFR2 in activated corpus-callosum astrocytes; TNFR2-null mice had lower astrocyte CXCL12, fewer CXCR4+ OPCs, and impaired remyelination-related OPC responses; CXCL12 lentiviral delivery rescued OPC proliferation/myelin measures (Figs. 1–6).', 'The authors conclude that astrocyte TNFR2 promotes OPC proliferation/differentiation through induction of CXCL12 and downstream CXCR4 signaling.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC3508279_TNFR2_CXCL12_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000022' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000022-PMID_22933014');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC6763083_TNFR2_SCI_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000068', 'M21B-EVID-000023', 'M21B-P2-R-000023', 'PMID:11517251', '11517251', 'literature_xml', 'exact_identifier_match:PMID:11517251', 'supporting_validated_claim', 'B', 'L2', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC6630008; PMID:30941924; DOI:10.1111/cns.13125; PMID:11517251; DOI:10.1523/JNEUROSCI.21-17-06617.2001', 'TNFR2-specific agonism or TNFR2 deletion studies support a beneficial TNFR2/NF-kappaB/c-IAP2 survival context after contusive spinal cord injury. In the primary SCI agonist study, continuous EHD2-sc-mTNFR2 delivery after T9 contusion improved BMS locomotion scores and cortical hindlimb-evoked responses; TNFR2 agonism protected cultured rat cortical neurons from glutamate toxicity through PI3K-gamma-dependent signaling.', 'The primary studies support a bounded TNFR2 functional repair branch after SCI, with TNFR2-specific agonism improving locomotor and cortical responses and PI3K-gamma-mediated neuronal protection in vitro; the deletion study supports TNFR-NF-kappaB/c-IAP2 survival context. No single receiver cell or terminal NF-kappaB target was assigned.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID11517251_22933014_9862719_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000023' AND x.extraction_id='M21B-P2-R-000023');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000068', 'M21B-EVID-000023', 'M21B-P2-R-000038', 'PMID:11517251; PMCID:PMC6763083; DOI:10.1523/JNEUROSCI.21-17-06617.2001', '11517251', 'literature_xml', 'exact_identifier_match:PMID:11517251', 'supporting_validated_claim', 'B', 'L2', 'validated_primary_observation', 'validated_author_claim', 'PMID:11517251; PMCID:PMC6763083; DOI:10.1523/JNEUROSCI.21-17-06617.2001; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC6763083.html', 'After traumatic spinal cord injury in mice, TNFR1-null and TNFR2-null animals showed poorer BBB recovery, blunted injury-induced NF-kappaB DNA-binding activity, lower c-IAP2 expression, and increased active caspase-3 relative to wild-type injury controls. Immunostaining localized c-IAP2 and caspase-3 changes in injured spinal tissue, supporting a TNFR-associated NF-kappaB/c-IAP2 survival branch during SCI recovery.', 'The authors conclude that TNFR signaling contributes to NF-kappaB activation and c-IAP2 expression after SCI and that loss of TNFR1 or TNFR2 worsens functional recovery and apoptotic readouts.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID11517251_22933014_9862719_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000023' AND x.extraction_id='M21B-P2-R-000038');
