INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000068', 'M21B-EVID-000023', 'P2MAN-M21B-M21B-EVID-000023-PMID_11517251', 'PMID:11517251', '11517251', 'full_text_html', 'exact_identifier_match:PMID:11517251', 'candidate_requires_review', 'B', 'L2', 'unresolved', 'unresolved', 'PMID:11517251', 'Unresolved: exact primary paper anchor identified, but no verified surrounding Results/Methods/figure/table passage was retained in this run; abstract/metadata alone is insufficient for an atomic Observation.', 'Unresolved: no separate explicit author interpretation was verified from an accessible primary-paper section or figure legend; do not convert the B-layer curator summary into an AuthorClaim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID11517251_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000023' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000023-PMID_11517251');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'M21B-P2-R-000021', 'PMID:20038584', '20038584', 'literature_xml', 'exact_identifier_match:PMID:20038584', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC2844188; PMID:20038584; DOI:10.1074/jbc.M109.037341; PMID:21558270; DOI:10.1073/pnas.0837789100', 'In TNFR2-expressing HeLa and Jurkat systems and primary human T cells, receptor-selective membrane-TNF stimulation caused TNFR2-specific p100 processing, p52/RelB nuclear translocation, and cytosolic TRAF2 depletion; the study separated this alternative NF-kappaB branch from the stronger TNFR1 classical NF-kappaB response. The linked TNFR2 review/primary record also supports TRAF2-dependent NF-kappaB/JNK signaling, but no universal TRAF2-to-JNK ordering was inferred from the full-text paper.', 'The authors conclude that membrane TNF activates TNFR2 to deplete TRAF2 and trigger the alternative NF-kappaB pathway through p100 processing, p52 generation and RelB nuclear translocation, while TNFR1 preferentially drives the classical NF-kappaB branch. The TNFR2/JNK component remains bounded to linked primary evidence and is not merged with the measured alternative-NF-kappaB sequence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID20038584_9862719_10880245_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='M21B-P2-R-000021');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'M21B-P2-R-000036', 'PMID:20038584; PMCID:PMC2844188; DOI:10.1074/jbc.M109.037341', '20038584', 'literature_xml', 'exact_identifier_match:PMID:20038584', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:20038584; PMCID:PMC2844188; DOI:10.1074/jbc.M109.037341; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2844188.html', 'TNFR2-specific oligomerized or membrane TNF induced IL-8 in TNFR2-expressing HeLa systems, was blocked by TNFR2-Fc but not TNFR1-Fc, and shifted signaling toward p100 processing, p52/RelB nuclear accumulation, TRAF2 depletion, and NIK accumulation rather than the TNFR1-associated p65/p50 branch. The same TNFR2-specific membrane-TNF system induced p100 processing in co-culture, and TNFR2-specific stimulation induced p100 processing in a subset of primary human T-cell samples.', 'The authors conclude that membrane or oligomerized TNF selectively activates TNFR2 and drives a TRAF2/cIAP/TRAF3/NIK-associated alternative NF-kappaB program with p100 processing, p52/RelB nuclear signaling, and IL-8 output, distinct from the TNFR1 p65/p50 branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID20038584_9862719_10880245_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='M21B-P2-R-000036');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'M21B-P2-R-RECOVERY-TNFR2-ALT-NFKB-000001', 'PMID:20038584; PMID:21558270', NULL, 'literature_xml', 'exact_identifier_match:PMID:20038584', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_pathway_bounded', 'PMID:20038584; PMID:21558270; https://pubmed.ncbi.nlm.nih.gov/20038584/; https://pubmed.ncbi.nlm.nih.gov/21558270/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID20038584_9862719_10880245_pubmed.xml', 'The primary TNFR2 study reports that membrane TNF, but not soluble TNF, selectively induced alternative NF-kappaB signaling and p100 processing through TNFR2 in tumor cell lines and primary T cells; TNFR2-specific signaling depleted cytosolic TRAF2. The related TNFR2 branch summary supports TRAF2-dependent NF-kappaB/JNK context, but this paper does not by itself establish the classical IKK-NFKB1-RELA edge or a traumatic-SCI cell-specific relay.', 'Promote the bounded membrane-TNF -> TNFR2 -> TRAF2 depletion -> alternative NF-kappaB/p100-p52 branch in the tested comparator systems. Keep the classical TNFR2-TRAF2-IKK-NFKB1-RELA branch and traumatic-SCI astrocyte transfer separate unless supported by another primary record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID20038584_9862719_10880245_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='M21B-P2-R-RECOVERY-TNFR2-ALT-NFKB-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'P2MAN-M21B-M21B-EVID-000021-PMID_20038584', 'PMID:20038584', '20038584', 'literature_xml', 'exact_identifier_match:PMID:20038584', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC2844188_TNFR2_p100_full.html; M21B-EVID-000021; identifier: PMID:20038584; PMCID:PMC2844188', 'Oligomerized/membrane TNF activated TNFR2-associated p100 processing and nuclear translocation of p52/RelB in multiple cell lines, whereas non-oligomerized soluble TNF was weak or inactive for this alternative NF-κB output.', 'The authors conclude that TNFR2, unlike TNFR1 in the tested setting, can trigger p100 processing and that ligand form controls this branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID20038584_9862719_10880245_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000021-PMID_20038584');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000069', 'M21B-EVID-000022', 'M21B-P2-R-000022', 'PMID:22933014', '22933014', 'full_text_html', 'exact_identifier_match:PMID:22933014', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC3508279; PMID:22933014; DOI:10.1007/s00401-012-1034-0', 'In the cuprizone-demylinated mouse corpus callosum, activated astrocytes and microglia expressed TNFR1/TNFR2, while TNFR2 deficiency abolished astrocyte CXCL12 upregulation and reduced CXCR4-positive NG2-positive OPCs. Lentiviral CXCL12 delivery rescued OPC proliferation and myelin expression in acutely demyelinated TNFR2-null mice; chronic demyelination required CXCL12-expressing astrocyte engraftment.', 'The authors conclude that TNFR2 activity in activated astrocytes induces CXCL12 during demyelination and that the CXCL12-CXCR4 axis promotes OPC proliferation and differentiation/remyelination. This is a downstream CNS repair relay, not a direct TNFR2-to-CXCL12 molecular interaction and not a traumatic-SCI-specific result.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID22933014_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000022' AND x.extraction_id='M21B-P2-R-000022');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000069', 'M21B-EVID-000022', 'M21B-P2-R-000037', 'PMID:22933014; PMCID:PMC3508279; DOI:10.1007/s00401-012-1034-0', '22933014', 'full_text_html', 'exact_identifier_match:PMID:22933014', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:22933014; PMCID:PMC3508279; DOI:10.1007/s00401-012-1034-0; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC3508279.html', 'In cuprizone-demyelinated mouse corpus callosum, activated astrocytes expressed TNFR1/TNFR2 and oligodendrocyte progenitors expressed more TNFR2 than TNFR1. TNFR2-null mice had reduced astrocytic CXCL12 and fewer CXCR4-positive NG2 progenitors; CXCR4 antagonism reduced corpus-callosum OPC proliferation, supporting a TNFR2-to-astrocyte-CXCL12-to-CXCR4-OPC functional relay during remyelination.', 'The authors conclude that astrocytic TNFR2 is required for CXCL12 expression and that CXCL12/CXCR4 signaling regulates OPC proliferation within the demyelinated adult CNS.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID22933014_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000022' AND x.extraction_id='M21B-P2-R-000037');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000069', 'M21B-EVID-000022', 'P2MAN-M21B-M21B-EVID-000022-PMID_22933014', 'PMID:22933014', '22933014', 'full_text_html', 'exact_identifier_match:PMID:22933014', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC3508279_TNFR2_CXCL12_full.html; M21B-EVID-000022; identifier: PMID:22933014; PMCID:PMC3508279', 'Cuprizone exposure increased TNFR2 in activated corpus-callosum astrocytes; TNFR2-null mice had lower astrocyte CXCL12, fewer CXCR4+ OPCs, and impaired remyelination-related OPC responses; CXCL12 lentiviral delivery rescued OPC proliferation/myelin measures (Figs. 1–6).', 'The authors conclude that astrocyte TNFR2 promotes OPC proliferation/differentiation through induction of CXCL12 and downstream CXCR4 signaling.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID22933014_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000022' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000022-PMID_22933014');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003940', 'M20B-EVID-003940-P2-BOUNDARY', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID9862719_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003940-P2-BOUNDARY' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E003942', 'M20B-EVID-003942-P2-BOUNDARY', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID9862719_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-003942-P2-BOUNDARY' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000070', 'M21B-EVID-000024', 'M21B-P2-R-000024', 'PMID:9862719; DOI:10.4049/jimmunol.161.12.6871', '9862719', 'full_text_html', 'exact_identifier_match:PMID:9862719', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:9862719; DOI:10.4049/jimmunol.161.12.6871; https://academic.oup.com/jimmunol/article/161/12/6871/8043532', 'IL-1 binding to IL1R2 recruited IL1RAP into a nonfunctional decoy complex. Chimeric IL1R2 extracellular/transmembrane receptors transduced an IL-1 signal and induced IL-2 only in IL1RAP-positive EL-4-derived cells, while radiolabeled-IL-1 crosslinking and immunoprecipitation showed ligated IL1R2-IL1RAP association in normal human B cells and cotransfected EL-4 cells.', 'The authors conclude that ligated IL1R2 recruits IL1RAP into a nonfunctional trimeric decoy complex and thereby limits IL1R1-IL1RAP signaling by competing for the accessory protein. The chimeric receptor result is not evidence that native IL1R2 transduces an intracellular signal.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID9862719_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000024' AND x.extraction_id='M21B-P2-R-000024');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000070', 'M21B-EVID-000024', 'M21B-P2-R-000039', 'PMID:9862719; DOI:10.4049/jimmunol.161.12.6871', '9862719', 'full_text_html', 'exact_identifier_match:PMID:9862719', 'candidate_requires_review', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:9862719; DOI:10.4049/jimmunol.161.12.6871', 'PubMed metadata and abstract were retrieved, but no stable full-text Results, Methods, or figure passage was recovered in this external retry. The IL1R2-IL1RAP complex and decoy-receptor mechanism therefore remain unvalidated at the atomic extraction layer.', 'Do not promote IL1R2-IL1RAP assembly, dominant-negative behavior, or any intracellular relay without a stable primary-paper passage.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID9862719_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000024' AND x.extraction_id='M21B-P2-R-000039');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000070', 'M21B-EVID-000024', 'M21B-P2-R-000080', 'PMID:9862719; DOI:10.4049/jimmunol.161.12.6871', '9862719', 'full_text_html', 'exact_identifier_match:PMID:9862719', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:9862719; DOI:10.4049/jimmunol.161.12.6871; https://pubmed.ncbi.nlm.nih.gov/9862719/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_9862719_il1r2_il1rap_pubmed.xml', 'The PubMed abstract reports that IL-1-ligated IL1R2 physically associated with IL1RAP in radiolabeled-ligand crosslinking and immunoprecipitation experiments in normal human B cells and transiently cotransfected murine EL-4 D6/76 cells; a chimeric IL1R2-extracellular/transmembrane receptor signaled IL-2 production only when IL1RAP was present.', 'Promote bounded IL1R2-IL1RAP receptor-complex association and decoy-complex behavior. Keep it distinct from purified IL-1/IL1R2 affinity and from an intracellular IL1R2 relay; the proposed inhibition of IL1R1-IL1RAP assembly is an abstract-level author interpretation.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID9862719_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000024' AND x.extraction_id='M21B-P2-R-000080');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000070', 'M21B-EVID-000024', 'M21B-P2-R-RECOVERY-IL1R2-IL1RAP-000001', 'PMID:9862719; DOI:10.4049/jimmunol.161.12.6871', '9862719', 'full_text_html', 'exact_identifier_match:PMID:9862719', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:9862719; DOI:10.4049/jimmunol.161.12.6871; https://pubmed.ncbi.nlm.nih.gov/9862719/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_9862719_il1r2_il1rap_pubmed.xml', 'In murine EL-4-derived cells, a chimeric receptor containing the IL-1RII extracellular/transmembrane portions and IL-1RI signaling domain transduced IL-1-induced IL-2 production only when IL-1RAcP was present. Crosslinking with radioiodinated IL-1 followed by immunoprecipitation showed ligated IL-1RII association with IL-1RAcP in normal human B cells and cotransfected EL-4 cells. The authors propose ligand-dependent IL-1RII/IL-1RAcP coreceptor sequestration that reduces signaling IL-1RI availability.', 'Retain ligand-dependent IL-1RII–IL-1RAcP association and the proposed coreceptor-competition mechanism as primary comparator evidence for the IL1R2-IL1RAP decoy branch. Do not treat it as purified binding biophysics, endogenous SCI astrocyte assembly, or evidence for a downstream NF-kappaB/JNK branch.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID9862719_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000024' AND x.extraction_id='M21B-P2-R-RECOVERY-IL1R2-IL1RAP-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000070', 'M21B-EVID-000024', 'P2MAN-M21B-M21B-EVID-000024-PMID_9862719', 'PMID:9862719', '9862719', 'full_text_html', 'exact_identifier_match:PMID:9862719', 'candidate_requires_review', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:9862719', 'Unresolved: exact primary paper anchor identified, but no verified surrounding Results/Methods/figure/table passage was retained in this run; abstract/metadata alone is insufficient for an atomic Observation.', 'Unresolved: no separate explicit author interpretation was verified from an accessible primary-paper section or figure legend; do not convert the B-layer curator summary into an AuthorClaim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMID9862719_pubmed.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000024' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000024-PMID_9862719');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q001/PMC3463309.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000001;M21B-E000002;M21B-E000003;M21B-E000004;M21B-E000005;M21B-E000006;M21B-E000007', 'M21B-EVID-000001', 'M21B-P2-R-000001', 'PMID:8999038; DOI:10.1074/jbc.271.51.32635; PMID:9188471; DOI:10.1074/jbc.272.25.15760', NULL, 'literature_xml', 'exact_identifier_match:PMID:8999038', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:8999038; DOI:10.1074/jbc.271.51.32635; https://pubmed.ncbi.nlm.nih.gov/8999038/; PMID:9188471; DOI:10.1074/jbc.272.25.15760; https://pubmed.ncbi.nlm.nih.gov/9188471/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_M21B_001_005.xml', 'The primary PubMed abstracts report that human OSM activates two receptor-complex branches: gp130-LIFR (type I) and gp130-OSMRbeta (type II), whereas LIF activates gp130-LIFR but not gp130-OSMRbeta. The studies report receptor-associated JAK1, JAK2, and TYK2 activation and STAT3 recruitment through both OSM receptor complexes, with STAT5B activation specifically associated with the type-II gp130-OSMRbeta complex; the receptor-subunit comparison used co-precipitation, flow cytometry, PCR, tyrosine-phosphorylation analyses, proliferation, and acute-phase protein assays.', 'The primary abstracts conclude that alternative LIFR-gp130 and OSMRbeta-gp130 subunits confer different OSM receptor specificities and signaling outputs. This supports the registered receptor-complex-to-JAK/STAT pathway edges, but does not establish ligand occupancy by purified binding, receptor-specific necessity for every JAK node, a traumatic-SCI receiver-cell context, or a terminal TF target.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q001/PMID_8999038_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000001' AND x.extraction_id='M21B-P2-R-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000001;M21B-E000002;M21B-E000003;M21B-E000004;M21B-E000005;M21B-E000006;M21B-E000007', 'M21B-EVID-000001', 'M21B-P2-R-000046', 'PMID:8999038; PMID:9188471', NULL, 'literature_xml', 'exact_identifier_match:PMID:8999038', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:8999038; PMID:9188471; https://pubmed.ncbi.nlm.nih.gov/8999038/; https://pubmed.ncbi.nlm.nih.gov/9188471/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch051_PMIDs_001_005_pubmed.xml', 'Human OSM signaling used two gp130-containing receptor complexes: gp130-LIFR, which responds to both LIF and OSM, and gp130-OSMRbeta, which responds to OSM but not LIF. Both receptor complexes activated JAK1, JAK2, and TYK2 and recruited STAT3; STAT5b activation was specific to the gp130-OSMRbeta type-II complex.', 'Retain distinct gp130-LIFR and gp130-OSMRbeta receptor-complex branches: both activate JAK-family kinases and STAT3, while STAT5b is specific to the type-II OSMRbeta-gp130 branch in the tested human systems. Do not collapse the complexes or infer SCI branch weights.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q001/PMID_8999038_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000001' AND x.extraction_id='M21B-P2-R-000046');
