INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000039;M21B-E000040;M21B-E000041;M21B-E000042;M21B-E000043', 'M21B-EVID-000009', 'M21B-P2-R-000009', 'PMID:11278445; PMID:7798267; PMID:8649846', NULL, 'literature_xml', 'exact_identifier_match:PMID:8649846', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:11278445; DOI:10.1074/jbc.M008870200; PMID:7798267; PMID:8649846; local cache=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_M21B_006_010.xml', 'Recovered PubMed abstracts report that EGF and NGF generate distinct ERK kinetics through Ras/Rap1, Crk/C3G/B-Raf and FRS2 assemblies, and that EGF-induced EGFR-to-Ras activation is mediated predominantly through Shc-Grb2-Sos complexes; Sos1 association with EGFR/Grb2 is stimulus- and phosphorylation-state-dependent. Exact Results/Methods/figure passages remain unresolved.', 'Abstract-level relay claims retained as retrieval leads; exact author claim and figure locus require full text.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q002/PMID_8649846_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000009' AND x.extraction_id='M21B-P2-R-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000039;M21B-E000040;M21B-E000041;M21B-E000042;M21B-E000043', 'M21B-EVID-000009', 'P2MAN-M21B-M21B-EVID-000009-PMID_8649846', 'PMID:8649846', '8649846', 'literature_xml', 'exact_identifier_match:PMID:8649846', 'candidate_requires_review', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:8649846', 'Unresolved: exact primary paper anchor identified, but no verified surrounding Results/Methods/figure/table passage was retained in this run; abstract/metadata alone is insufficient for an atomic Observation.', 'Unresolved: no separate explicit author interpretation was verified from an accessible primary-paper section or figure legend; do not convert the B-layer curator summary into an AuthorClaim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q002/PMID_8649846_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000009' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000009-PMID_8649846');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000047', 'M21B-EVID-000011', 'M21B-P2-R-000011', 'PMCID:PMC1137045; PMID:7519847', '7519847', 'full_text_html', 'exact_identifier_match:DOI:10.1042/bj3010703;PMCID:PMC1137045', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1137045; PMID:7519847; DOI:10.1042/bj3010703; https://europepmc.org/articles/PMC1137045?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PDGF_PI3K_fulltext_7519847.pdf', 'In quiescent NIH-3T3 fibroblasts, PDGF stimulation induced rapid, transient association of PI3-K with the activated PDGF receptor, detectable within 1 minute and maximal at 5 minutes, with a correlated transient increase in intrinsic PI3-K activity (Fig. 5A-D). Reconstitution and kinase assays showed that the PDGF receptor phosphorylated both p85alpha and p110 when the p85alpha-p110 complex was present (Fig. 2A-D), while receptor immunoprecipitates from PDGF-stimulated NIH-3T3 cells contained a p110 product phosphorylated predominantly on tyrosine (Fig. 3A-C). Tyrosine phosphorylation of p110 was detected in vivo after PDGF stimulation and persisted while receptor association declined (Fig. 6A-B); receptor immunodepletion showed release of tyrosine-phosphorylated p110 (Fig. 7A-B).', 'The authors conclude that the PDGF receptor activates PI3-K in vivo through rapid enzyme relocation/recruitment and increased intrinsic activity, and that receptor tyrosine phosphorylation of p110 may regulate PI3-K in some circumstances. The paper supports a receptor-proximal PDGFR-PI3K relay, not a complete PDGFR-to-AKT/ERK or SCI functional chain.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q003/PMC1137045.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000011' AND x.extraction_id='M21B-P2-R-000011');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000065', 'M21B-EVID-000020', 'M21B-P2-R-000020', 'PMID:7544915; DOI:10.1126/science.7544915', '7544915', 'literature_xml', 'exact_identifier_match:PMID:7544915', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:7544915; DOI:10.1126/science.7544915; https://pubmed.ncbi.nlm.nih.gov/7544915/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_M21B_016_020.xml', 'The primary abstract reports that TRAF2 overexpression, but not TRAF1 or TRAF3, was sufficient to induce NF-kappa B activation, while a dominant-negative TRAF2 derivative lacking the amino-terminal RING finger inhibited NF-kappa B activation mediated by TNF receptor 2 and CD40. This supports a TRAF2-dependent TNFR2-to-NF-kappa B relay in the tested transfection/reporter systems.', 'The authors conclude that TRAF2 is a common mediator of TNFR2 and CD40 signaling to NF-kappa B. The abstract supports a receptor/pathway relay and perturbation dependence, but does not by itself establish endogenous direct TNFR2-TRAF2 recruitment, all TNFR2 adaptor usage, exact receptor-proximal complex stoichiometry, an SCI receiver-cell context, or a terminal NF-kappa B target-gene occupancy edge.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q004/PMID_7544915_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000020' AND x.extraction_id='M21B-P2-R-000020');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000065', 'M21B-EVID-000020', 'P2MAN-M21B-M21B-EVID-000020-PMID_7544915', 'PMID:7544915', '7544915', 'literature_xml', 'exact_identifier_match:PMID:7544915', 'candidate_requires_review', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:7544915', 'Unresolved: exact primary paper anchor identified, but no verified surrounding Results/Methods/figure/table passage was retained in this run; abstract/metadata alone is insufficient for an atomic Observation.', 'Unresolved: no separate explicit author interpretation was verified from an accessible primary-paper section or figure legend; do not convert the B-layer curator summary into an AuthorClaim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q004/PMID_7544915_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000020' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000020-PMID_7544915');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000065', 'M21B-EVID-PROMO-20260826-005', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_Q004/PMID_7544915_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-PROMO-20260826-005' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_pdf', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_TGFBR_SMAD_fulltext_9311995.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000077;M21B-E000078', 'M21B-EVID-000029', 'M21B-P2-000029', 'PMCID:PMC2621323', '18922473', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2621323', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC2621323_TGFBR1_TAK1_bioc.json; M21B-EVID-000029; identifier: PMCID:PMC2621323; PMID:18922473; DOI:10.1016/j.molcel.2008.09.002', 'TGF-β receptor activation required TRAF6 for JNK/p38 activation; TRAF6 associated with activated TβRI/TβRII complexes, underwent transient K63-linked ubiquitination, and interacted with TAK1; TRAF6 loss reduced JNK/p38 and apoptosis/EMT outputs while leaving Smad activation intact (Figs. 1–4).', 'The authors conclude that receptor-associated TRAF6 connects activated TGF-β receptors to a Smad-independent TAK1/JNK/p38 branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC2621323_TGFBR1_TAK1_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000029' AND x.extraction_id='M21B-P2-000029');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000077;M21B-E000078', 'M21B-EVID-000029', 'M21B-P2-R-000029', 'PMCID:PMC2621323', '18922473', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2621323', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC2621323; PMID:18922473; DOI:10.1016/j.molcel.2008.09.002; local BioC cache=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2621323_bioc.json', 'In TGF-beta-treated signaling systems, dominant-negative or siRNA loss of TRAF6 suppressed JNK and p38 activation while sparing Smad2 signaling. Immunoprecipitation and reprecipitation experiments showed ligand-activated TGF-beta receptor complexes associate with TRAF6; TGF-beta induced K63-linked TRAF6 ubiquitination and TRAF6-TAK1 association, linking the receptor complex to the Smad-independent JNK/p38 branch.', 'The authors conclude that the ligand-activated TGF-beta receptor complex binds and K63-ubiquitinates TRAF6, which is specifically required to activate TAK1-dependent JNK and p38 independently of Smads.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC2621323_TGFBR1_TAK1_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000029' AND x.extraction_id='M21B-P2-R-000029');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000077;M21B-E000078', 'M21B-EVID-000029', 'M21B-P2-R-000044', 'PMID:18922473; PMCID:PMC2621323; DOI:10.1016/j.molcel.2008.09.002', '18922473', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2621323', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMID:18922473; PMCID:PMC2621323; DOI:10.1016/j.molcel.2008.09.002; https://pubmed.ncbi.nlm.nih.gov/18922473/; https://pmc.ncbi.nlm.nih.gov/articles/PMC2621323/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC2621323_TGFBR1_TAK1_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMIDs_33921794_28559424_18922473_19361494_pubmed.xml', 'In mink lung epithelial and mouse hepatocyte systems, activated TGF-beta receptor complexes associated with TRAF6; TGF-beta induced K63-linked TRAF6 ubiquitination and TRAF6-TAK1 association, and TRAF6 loss or dominant-negative perturbation reduced TGF-beta-induced JNK and p38 activation without equivalently blocking Smad2 phosphorylation.', 'Promote the bounded TGF-beta receptor-complex -> TRAF6 K63-ubiquitination -> TAK1 -> JNK/p38 noncanonical relay. Preserve receptor-complex and adaptor ordering; do not treat this pathway evidence as direct TGF-beta receptor ligand-binding biophysics or transfer it wholesale to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC2621323_TGFBR1_TAK1_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000029' AND x.extraction_id='M21B-P2-R-000044');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000072', 'M21B-EVID-000026', 'M21B-P2-000026', 'PMCID:PMC9527244', '36184639', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC9527244', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC9527244_IL1R1_astrocyte_bioc.json; M21B-EVID-000026; identifier: PMCID:PMC9527244; DOI:10.1038/s41467-022-33463-x (no PMID was present in the retained artifact)', 'After SCI or central rmIL-1α administration, astrocyte- and endothelial-IL-1R1 conditional restoration produced IL-1α-associated neutrophil infiltration and mature-oligodendrocyte loss; astrocyte-specific Il1r1 deletion reduced these effects; IL-1α-stimulated astrocytes produced ROS and conditioned medium toxic to oligodendrocytes (Figs. 4–10).', 'The authors conclude that damaged microglia release IL-1α, which acts through astrocytic and endothelial IL-1R1 to drive secondary degeneration, with astrocyte-derived ROS contributing to oligodendrocyte loss.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC9527244_IL1R1_astrocyte_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000026' AND x.extraction_id='M21B-P2-000026');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000072', 'M21B-EVID-000026', 'M21B-P2-R-000026', 'PMCID:PMC9527244', '36184639', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC9527244', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC9527244; DOI:10.1038/s41467-022-33463-x; local BioC cache=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC9527244_bioc.json', 'In mouse CNS and SCI models, rmIL-1alpha caused neutrophil infiltration and mature oligodendrocyte loss; anakinra blocked both effects and Il1r1-null mice had better locomotor recovery after SCI. Cell-specific receptor restoration/deletion showed that astrocytic IL-1R1 partially reinstated IL-1alpha-induced oligodendrocyte loss, endothelial IL-1R1 contributed to neutrophil recruitment, and IL-1alpha-stimulated astrocytes produced ROS whose inhibition prevented oligodendrocyte loss.', 'The authors conclude that microglia-derived IL-1alpha drives neuroinflammation and oligodendrocyte loss after SCI partly through endothelial and astrocytic IL-1R1 signaling, with astrocyte-derived ROS contributing to secondary degeneration.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC9527244_IL1R1_astrocyte_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000026' AND x.extraction_id='M21B-P2-R-000026');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMIDs_33921794_28559424_18922473_19361494_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch051_PMIDs_001_005_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch052_PMIDs_031_035_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch053_PMIDs_036_040_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000100', 'M21B-EVID-000045', 'M21B-P2-R-000011A', 'PMCID:PMC12012454; PMID:40208942; DOI:10.1073/pnas.2417400122', '40208942', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC12012454', 'supporting_validated_claim', 'B', 'L3', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC12012454; PMID:40208942; DOI:10.1073/pnas.2417400122; https://pmc.ncbi.nlm.nih.gov/articles/PMC12012454/; https://europepmc.org/articles/PMC12012454?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M21B_RYK_astrocyte_SCI_fulltext.pdf', 'After C5 dorsal-column spinal-cord injury, Ryk expression increased in mouse astrocytes at the lesion border and in injured human spinal-cord astrocytes/axons. Astrocyte-specific Ryk conditional knockout accelerated astrocyte process polarization and border formation, reduced lesion volume and fibrosis, preserved neurons and corticospinal axons, and improved sensory-motor readouts including rotarod and grid-walk performance (Fig. 1-3). These results support an astrocytic RYK-associated SCI scar-border and wound-healing function, not a soluble Wnt-RYK binding or direct intracellular kinase edge.', 'The authors conclude that astrocytic Ryk regulates injury responses and multicellular wound healing after SCI, and that inhibiting Ryk in astrocytes accelerates protective border formation and improves neuronal preservation and functional recovery. The paper does not identify the initiating Wnt ligand, establish RYK extracellular affinity, or prove that the measured tissue effects are mediated by a single canonical or noncanonical Wnt branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch054_PMC12012454_RYK_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000045' AND x.extraction_id='M21B-P2-R-000011A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000100', 'M21B-EVID-000045', 'M21B-P2-R-000011B', 'PMCID:PMC12012454; PMID:40208942; DOI:10.1073/pnas.2417400122', '40208942', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC12012454', 'supporting_validated_claim', 'B', 'L3', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC12012454; PMID:40208942; DOI:10.1073/pnas.2417400122; https://pmc.ncbi.nlm.nih.gov/articles/PMC12012454/; https://europepmc.org/articles/PMC12012454?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M21B_RYK_astrocyte_SCI_fulltext.pdf', 'In astrocytes after SCI, astrocyte-specific Ryk knockout transiently increased nuclear phosphorylated beta-catenin at 7 days but not 14 days, and increased NrCAM expression. NrCAM antisense oligonucleotides reduced NrCAM and reversed Ryk-knockout-associated astrocyte elongation/polarization and much of the associated fibroblast and microglial border phenotype (Fig. 4-7). CellChat inferred increased canonical Wnt and other intercellular signaling, but these predictions were not treated as direct ligand-receptor or noncanonical-PCP evidence. The paper cites NrCAM as a known beta-catenin/LEF-1 transcriptional target but does not measure beta-catenin/LEF-1 chromatin occupancy in this study.', 'The authors propose that injury-activated canonical Wnt signaling is negatively regulated by Ryk in astrocytes, and that increased beta-catenin-dependent NrCAM contributes to astrocyte process elongation and border formation. They explicitly leave activation of a noncanonical Wnt/planar-cell-polarity pathway in astrocytes as a question for future study.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch054_PMC12012454_RYK_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000045' AND x.extraction_id='M21B-P2-R-000011B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000096', 'M21B-EVID-000042', 'M21B-P2-R-000062', 'PMCID:PMC5682656', '28981091', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC5682656', 'supporting_validated_claim', 'B', 'L4', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMCID:PMC5682656; https://pmc.ncbi.nlm.nih.gov/articles/PMC5682656/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch054_PMC5682656_FGF10_FGFR2_SCI_bioc.json', 'After rat acute SCI, neuron- and microglia/macrophage-derived FGF10 increased and exogenous FGF10 improved functional recovery, reduced apoptosis, and repaired neurites through FGFR2/PI3K/AKT. FGFR2 knockdown suppressed pathway activation and abolished anti-apoptotic and neurite-repair effects in vitro; FGF10 also reduced microglial/macrophage TLR4/NF-kappaB inflammatory activation.', 'Promote the rat SCI FGF10 -> FGFR2 -> PI3K/AKT neuronal-survival and neurite-repair relay, with a separate FGF10-associated TLR4/NF-kappaB microglia/macrophage anti-inflammatory branch. Do not infer direct FGF10-FGFR2 binding or an astrocyte receiver branch from this study.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch054_PMC5682656_FGF10_FGFR2_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000042' AND x.extraction_id='M21B-P2-R-000062');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000097', 'M21B-EVID-000043', 'M21B-P2-R-000063', 'PMCID:PMC9013464', '35429978', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC9013464', 'supporting_validated_claim', 'B', 'L4', 'validated_fulltext', 'validated_functional_context', 'PMCID:PMC9013464; https://pmc.ncbi.nlm.nih.gov/articles/PMC9013464/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch054_PMC9013464_PDGF_SCI_bioc.json', 'In mouse compression SCI, PDGFB and PDGFD increased successively, with PDGFB mainly astrocyte-derived and PDGFD mainly macrophage/microglia- and fibroblast-derived. Exogenous PDGFB or PDGFD induced fibrosis in uninjured spinal cord, while PDGFR-beta inhibitor SU16f reduced fibrotic scar, lesion/inflammation, and improved axon regeneration and locomotor recovery after SCI.', 'Promote the PDGFB/PDGFD -> PDGFR-beta fibrotic-scar and secondary-injury functional branch after mouse SCI. Keep PDGFB and PDGFD source-cell distinctions explicit; do not infer direct binding or intracellular adaptor ordering beyond PDGFR-beta pathway dependence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch054_PMC9013464_PDGF_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000043' AND x.extraction_id='M21B-P2-R-000063');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000095', 'M21B-EVID-000041', 'M21B-P2-R-000061', 'PMID:8075814', '8075814', 'literature_xml', 'exact_identifier_match:PMID:8075814', 'candidate_requires_review', 'B', 'L2', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:8075814; https://pubmed.ncbi.nlm.nih.gov/8075814/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch054_PMID8075814_CNTF_astrocyte_pubmed.xml', 'In adult rat CNS lesions, CNTFR-alpha expression shifted from neuronal localization to astrocytes at the glial-scar edge; cultured hippocampal astrocytes contained a functional CNTF receptor complex capable of signal transduction, unlike truncated TrkB/TrkC forms that lacked measured signaling competence.', 'Retain CNTFR-alpha astrocyte receptor-context and functional CNTF-complex signaling in injured rat CNS. Preserve the unresolved receptor-complex composition and do not infer a specific CNTFR-alpha/gp130/LIFR versus CNTFR-alpha/gp130/OSMR branch or direct CNTF binding from this record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch054_PMID8075814_CNTF_astrocyte_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000041' AND x.extraction_id='M21B-P2-R-000061');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000101;M21B-E000102', 'M21B-EVID-000046', 'M21B-P2-R-000010A', 'PMCID:PMC11468415; PMID:39390606; DOI:10.1186/s12974-024-03246-w', '39390606', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11468415', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC11468415; PMID:39390606; DOI:10.1186/s12974-024-03246-w; https://pmc.ncbi.nlm.nih.gov/articles/PMC11468415/; https://europepmc.org/articles/PMC11468415?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M21B_DLL4_NOTCH1_IL6_fulltext.pdf', 'In reactive human astrocytes, chromatin immunoprecipitation with an NICD antibody followed by human IL6 promoter PCR showed NICD enrichment relative to IgG (Fig. 4B). Astrocyte Dll4 loss in EAE mice and DLL4 siRNA in reactive human astrocytes reduced Il6/IL-6 expression, while DLL4 lentiviral gain in non-reactive human astrocytes increased IL-6 and canonical Notch-response genes HES1, HEY1, and HEY2 (Fig. 3; Fig. 4B-G). The ChIP result supports NICD occupancy at the IL6 promoter in the tested reactive-astrocyte system; it is not a purified DNA-binding assay and does not establish STAT3 occupancy at the IL6 promoter.', 'The authors conclude that astrocytic DLL4 activates NOTCH1/NICD and increases IL-6 transcription through NICD interaction with the IL6 gene promoter in reactive astrocytes. This is direct transcription-factor occupancy evidence for the NICD-to-IL6 promoter relationship, not evidence of extracellular DLL4-NOTCH1 affinity or STAT3 binding at the promoter.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC11468415_DLL4_NOTCH1_IL6_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000046' AND x.extraction_id='M21B-P2-R-000010A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000101;M21B-E000102', 'M21B-EVID-000046', 'M21B-P2-R-000010B', 'PMCID:PMC11468415; PMID:39390606; DOI:10.1186/s12974-024-03246-w', '39390606', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11468415', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC11468415; PMID:39390606; DOI:10.1186/s12974-024-03246-w; https://pmc.ncbi.nlm.nih.gov/articles/PMC11468415/; https://europepmc.org/articles/PMC11468415?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M21B_DLL4_NOTCH1_IL6_fulltext.pdf', 'In reactive human astrocytes, DLL4 siRNA reduced IL-6 and phospho-STAT3 levels toward non-reactive-astrocyte values, while IL-6-receptor blockade with tocilizumab reduced phospho-STAT3 without changing DLL4 expression (Fig. 5A-J). Astrocyte-specific Dll4 or Notch1 deletion reduced EAE severity and astrocyte reactivity-associated outputs in vivo (Fig. 2; Fig. 4), and the authors link the pathway to downstream VEGFA/TYMP and inflammatory-barrier outputs. These perturbations support a DLL4-NOTCH1-to-IL-6-to-STAT3/reactivity pathway and functional CNS-inflammation branch; they do not establish a direct DLL4-NOTCH1 affinity measurement or a terminal STAT3 target-gene edge.', 'The authors conclude that DLL4-NOTCH1 activity increases IL-6, which activates JAK/STAT signaling and STAT3 phosphorylation to promote reactive-astrocyte markers and inflammatory blood-brain-barrier outputs. The study supports pathway/function ordering but does not identify a unique terminal STAT3 chromatin target or transfer the EAE result to traumatic SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC11468415_DLL4_NOTCH1_IL6_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000046' AND x.extraction_id='M21B-P2-R-000010B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000104;M21B-E000105', 'M21B-EVID-000048', 'M21B-P2-R-000068', 'PMCID:PMC13366903; PMID:42217185; DOI:10.1016/j.celrep.2026.117418', '42217185', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC13366903', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_functional_context', 'PMCID:PMC13366903; PMID:42217185; DOI:10.1016/j.celrep.2026.117418; https://pmc.ncbi.nlm.nih.gov/articles/PMC13366903/; https://pubmed.ncbi.nlm.nih.gov/42217185/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC13366903_CSf1_IFNbeta_SCI_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMIDs_046_050_pubmed.xml', 'After focal mouse SCI, lesion-border astrocytes upregulated CSF1 and required it for perilesional microglial proliferation, wound closure, and motor recovery; astrocyte Csf1 deletion also reduced border astrocytes. Microglia-derived IFN-beta reciprocally supported astrocyte survival and border formation, while disruption of astrocyte interferon signaling impaired repair and recovery.', 'Promote the reciprocal CSF1/CSF1R-associated astrocyte-to-microglia and IFN-beta/IFNAR-associated microglia-to-astrocyte repair crosstalk after focal mouse SCI. Keep ligand source, receptor-proximal kinase ordering, and downstream wound-repair outputs distinct; do not infer direct ligand binding from cell-source and conditional-genetic evidence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC13366903_CSf1_IFNbeta_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000048' AND x.extraction_id='M21B-P2-R-000068');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000068', 'M21B-EVID-000023', 'M21B-P2-R-000023', 'PMID:11517251', '11517251', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6630008', 'supporting_validated_claim', 'B', 'L2', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC6630008; PMID:30941924; DOI:10.1111/cns.13125; PMID:11517251; DOI:10.1523/JNEUROSCI.21-17-06617.2001', 'TNFR2-specific agonism or TNFR2 deletion studies support a beneficial TNFR2/NF-kappaB/c-IAP2 survival context after contusive spinal cord injury. In the primary SCI agonist study, continuous EHD2-sc-mTNFR2 delivery after T9 contusion improved BMS locomotion scores and cortical hindlimb-evoked responses; TNFR2 agonism protected cultured rat cortical neurons from glutamate toxicity through PI3K-gamma-dependent signaling.', 'The primary studies support a bounded TNFR2 functional repair branch after SCI, with TNFR2-specific agonism improving locomotor and cortical responses and PI3K-gamma-mediated neuronal protection in vitro; the deletion study supports TNFR-NF-kappaB/c-IAP2 survival context. No single receiver cell or terminal NF-kappaB target was assigned.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC6630008_TNFR2_PI3Kgamma_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000023' AND x.extraction_id='M21B-P2-R-000023');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000068', 'M21B-EVID-000023', 'P2MAN-M21B-M21B-EVID-000023-PMID_30941924', 'PMID:30941924', '30941924', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6630008', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC6630008_TNFR2_PI3Kgamma_SCI_bioc.json; M21B-EVID-000023; identifier: PMID:30941924; PMCID:PMC6630008; DOI:10.1111/cns.13125', 'TNFR2-specific agonist EHD2-sc-mTNFR2 protected rat cortical neurons from glutamate toxicity, and PI3Kγ inhibition reduced that protection (Fig. 1); continuous intraspinal delivery after mouse T9 contusion improved BMS locomotion and cortical sensory-evoked responses and altered neural/tissue measures (Figs. 2–5).', 'The authors conclude that TNFR2 activation improves locomotor and cortical responses after contusive SCI and protects neurons through PI3Kγ in vitro.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC6630008_TNFR2_PI3Kgamma_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000023' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000023-PMID_30941924');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000103', 'M21B-EVID-000047', 'M21B-P2-R-000067', 'PMID:30941924; PMCID:PMC6630008', '30941924', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6630008', 'supporting_validated_claim', 'B', 'L2', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMID:30941924; PMCID:PMC6630008; https://pubmed.ncbi.nlm.nih.gov/30941924/; https://pmc.ncbi.nlm.nih.gov/articles/PMC6630008/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC6630008_TNFR2_PI3Kgamma_SCI_bioc.json', 'Selective TNFR2 agonism protected neurons from glutamate excitotoxicity through PI3K-gamma in vitro and improved locomotor recovery after direct spinal infusion following mouse T9 contusion SCI; increased neurofilament-H and CNPase and improved cortical somatosensory responses were observed without reducing lesion size.', 'Promote the mouse SCI TNFR2 -> PI3K-gamma neuroprotective and functional-recovery branch. Keep the in vitro rat-neuron species context separate from mouse in vivo SCI and do not infer a direct TNFR2-PI3K-gamma physical interaction or astrocyte-specific mechanism.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch055_PMC6630008_TNFR2_PI3Kgamma_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000047' AND x.extraction_id='M21B-P2-R-000067');
