INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'metadata_or_search_json', 'not_attempted', 'metadata_or_search_only', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact. Its role is metadata/search/manifest output and it is not treated as direct biological evidence.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_DOI_0802308105_esearch.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_MR_ESR1_EGFR_TSHR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000372', 'M22B-EVID-000092', 'M22B-P2-R-000092-R092', 'PMCID:PMC10409762; PMID:37553521; PMID:15883158; DOI:10.1074/jbc.M502825200', '37553521', 'full_text_xml', 'exact_identifier_match:PMCID:PMC10409762', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC10409762; PMID:37553521; PMID:15883158; DOI:10.1038/s42003-023-05194-2; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC10409762_BMP8A.xml; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_TPO_IL10_GDF10_BMP8A_pubmed.xml', 'Bmp8a loss caused obesity, fatty liver, and altered lipid metabolism in zebrafish, while Bmp8a overexpression in mouse 3T3-L1 cells increased pSMAD1/5/8 and pSMAD2/3. Inhibition experiments indicated that the anti-adipogenic effect was primarily dependent on SMAD2/3, with SMAD2/3 binding to the PPARgamma promoter and NF-kB/PPARgamma effects on Fabp4.', 'The primary study supports a Bmp8a-associated adipocyte/lipid program with pSMAD1/5/8 and pSMAD2/3 readouts, but its dominant anti-adipogenic mechanism is SMAD2/3-to-PPARgamma rather than an isolated SMAD1/5/8 or SMAD9 branch; submitted receptor-complex composition and SCI transfer remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC10409762_BMP8A.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000092' AND x.extraction_id='M22B-P2-R-000092-R092');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000371', 'M22B-EVID-000093', 'M22B-P2-R-000123', 'PMID:37553521; PMCID:PMC10409762; DOI:10.1038/s42003-023-05194-2', '37553521', 'full_text_xml', 'exact_identifier_match:PMCID:PMC10409762', 'candidate_requires_review', NULL, 'L1', 'validated_abstract_bounded', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:37553521; PMCID:PMC10409762; DOI:10.1038/s42003-023-05194-2; https://pubmed.ncbi.nlm.nih.gov/37553521/; https://pmc.ncbi.nlm.nih.gov/articles/PMC10409762/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC10409762_bioc.json', 'Reuse the BMP8A adipocyte/lipid-metabolism observation for the distinct phenotype handoff: Bmp8a loss increased zebrafish obesity/fatty liver and Bmp8a overexpression inhibited 3T3-L1 adipocyte differentiation. The phenotype is not evidence for direct SMAD1/5/9 target binding.', 'Reuse the BMP8A-associated lipid metabolism and adipocyte differentiation phenotype while keeping the dominant SMAD2/3 mechanism and receptor uncertainty explicit. Do not infer a terminal SMAD1/5/9 target or SCI relevance.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC10409762_BMP8A.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000093' AND x.extraction_id='M22B-P2-R-000123');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000373', 'M22B-EVID-000094', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC10409762_BMP8A.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000094' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000382', 'M22B-EVID-000422', 'M22B-P2-R-000396', 'PMCID:PMC10409762; PMID:31940275', '31940275', 'full_text_xml', 'exact_identifier_match:PMCID:PMC10409762', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC10409762; PMID:31940275; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch050_PMC10409762_BMP8A_SMAD2_3_ALK4_PPARgamma.html', 'Bmp8a overexpression increased Smad2/3 phosphorylation and CAGA reporter activity in 3T3-L1 preadipocytes, while the Smad2/3 inhibitor TP0427736 blocked the anti-adipogenic phenotype. Receptor-expression, dominant-negative receptor, and reporter experiments supported an ALK4-centered type-I context with ACVR2A, ACVR2B, or TGFBR2-compatible type-II contexts; PPARgamma promoter reporter and predicted-site deletion linked the pathway to PPARgamma repression. No ChIP or direct Smad2/3 occupancy assay was shown.', 'BMP8A activates an ALK4-centered SMAD2/3 pathway that suppresses adipocyte differentiation and represses PPARgamma promoter activity in the tested models, but the paper provides reporter/deletion and pathway evidence rather than direct SMAD2/3 occupancy; exact BMPR1A/ACVR2B or BMPR1B/ACVR2B handoff specificity and SCI transfer remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC10409762_BMP8A.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000422' AND x.extraction_id='M22B-P2-R-000396');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000448', 'M22B-EVID-000007', 'M22B-P2-R-000007', 'PMID:10064602', '10064602', 'full_text_html', 'exact_identifier_match:DOI:10.1093/emboj/18.5.1367;PMCID:PMC1171226', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367; https://pmc.ncbi.nlm.nih.gov/articles/PMC1171226/', 'In human IL-3-dependent F-36P-mpl cells, dominant-negative STAT5 reduced IL-3-dependent growth and cyclin D1 mRNA, while constitutively active STAT5A enabled factor-independent proliferation. STAT5A transactivated a cyclin D1 promoter element near -481 bp, STAT5 bound the element in IL-3-responsive EMSA, and cyclin D1 rescued the dominant-negative STAT5 growth defect.', 'The authors conclude that STAT5 directly regulates the cyclin D1 promoter through a STAT-binding element and contributes, together with Ras, to IL-3-dependent hematopoietic growth.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1171226_STAT5_Ccnd1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000007' AND x.extraction_id='M22B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000448', 'M22B-EVID-000007', 'M22B-P2-R-000007-R096', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367', '10064602', 'full_text_html', 'exact_identifier_match:DOI:10.1093/emboj/18.5.1367;PMCID:PMC1171226', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1171226_STAT5_Ccnd1.html; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch096_pubmed.xml', 'In human IL-3-dependent F-36P-mpl hematopoietic cells, dominant-negative STAT5 or Ras reduced IL-3-dependent growth and cyclin D1 expression; constitutively active STAT5A transactivated the cyclin D1 promoter, mutation of a candidate STAT element at -481 bp reduced activity, and EMSA showed IL-3-responsive STAT5 binding to that element.', 'The primary study directly supports an IL-3-associated STAT5-to-Ccnd1 promoter element and a growth-rescue relationship in hematopoietic models; the exact IL-3 receptor-complex composition, transfer to IL-5/IL-7/IL-9/IL-22 handoffs, and SCI relevance remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1171226_STAT5_Ccnd1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000007' AND x.extraction_id='M22B-P2-R-000007-R096');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000354', 'M22B-EVID-000088', 'M22B-P2-R-000088-R092', 'PMCID:PMC12097095; PMID:40125634; DOI:10.1002/advs.202500616', '40125634', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12097095', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC12097095; PMID:40125634; DOI:10.1002/advs.202500616; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml', 'Autocrine GDF10 signaling through BMPR2/ALK3 in mouse and human hepatic stellate cells activated phosphorylated SMAD1/5/8, recruited pSMAD1/5/8 to the Smad7 promoter, activated a Smad7 promoter reporter, and induced Smad7 expression; Smad7 loss weakened the antifibrotic output.', 'The primary study directly supports GDF10-BMPR2/ALK3-pSMAD1/5/8 recruitment and activation of the Smad7 promoter in hepatic stellate-cell models; the BMPR2-only handoff label omits ALK3, SMAD8/SMAD9 paralog specificity is not resolved, and SCI transfer is unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000088' AND x.extraction_id='M22B-P2-R-000088-R092');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000358', 'M22B-EVID-000089', 'M22B-P2-R-000089-R092', 'PMCID:PMC12097095; PMID:40125634; DOI:10.1002/advs.202500616', '40125634', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12097095', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC12097095; PMID:40125634; DOI:10.1002/advs.202500616; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml', 'GDF10-BMPR2/ALK3-SMAD1/5/8-Smad7 signaling inhibited TGF-beta-SMAD2/3 signaling, reduced hepatic stellate-cell activation, and alleviated liver fibrosis in mouse models; the broader program includes the direct Smad7 promoter record but is not equivalent to it.', 'The primary study supports a GDF10-BMPR2/ALK3-SMAD1/5/8-Smad7 antifibrotic hepatic-stellate-cell program and functional suppression of TGF-beta-SMAD2/3 activation; direct promoter occupancy remains represented only by M22B-E000354.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000089' AND x.extraction_id='M22B-P2-R-000089-R092');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000361', 'M22B-EVID-000090', 'M22B-P2-R-000120', 'PMID:40125634; PMCID:PMC12097095; DOI:10.1002/advs.202500616', '40125634', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12097095', 'candidate_requires_review', NULL, 'L1', 'validated_abstract_bounded', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:40125634; PMCID:PMC12097095; DOI:10.1002/advs.202500616; https://pubmed.ncbi.nlm.nih.gov/40125634/; https://pmc.ncbi.nlm.nih.gov/articles/PMC12097095/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC12097095_bioc.json', 'Reuse the GDF10-BMPR2/ALK3-SMAD1/5/8-Smad7 observation for the antifibrotic phenotype handoff: GDF10 gain or recombinant treatment reduced HSC activation and liver fibrosis, while GDF10 loss worsened fibrosis. The phenotype is kept distinct from direct SMAD1/5/8 promoter occupancy.', 'Reuse the GDF10-BMPR2/ALK3-SMAD1/5/8-Smad7 antifibrotic HSC/liver-fibrosis phenotype as a distinct functional output. Do not infer direct SMAD target occupancy from the phenotype or transfer the result to SCI.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000090' AND x.extraction_id='M22B-P2-R-000120');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000397', 'M22B-EVID-000091', 'M22B-P2-R-000121', 'PMID:40125634; PMCID:PMC12097095; DOI:10.1002/advs.202500616', '40125634', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12097095', 'negative_or_boundary_evaluated', 'U', 'L0', 'boundary_only', 'unresolved', 'PMID:40125634; PMCID:PMC12097095; DOI:10.1002/advs.202500616; https://pubmed.ncbi.nlm.nih.gov/40125634/; https://pmc.ncbi.nlm.nih.gov/articles/PMC12097095/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC12097095_bioc.json', 'The retrieved GDF10 primary study supports BMPR2/ALK3 signaling, phospho-SMAD1/5/8, SMAD1/5 promoter occupancy, and a direct Smad7 promoter edge, but it does not resolve SMAD8- or SMAD9-specific occupancy or target-gene causality. No SMAD8-specific target edge is promoted.', 'Leave the SMAD8/SMAD9 target assignment unresolved. Do not transfer the validated SMAD1/5-to-Smad7 promoter evidence to SMAD8 or treat BMPR2-only labeling as equivalent to BMPR2/ALK3 in an SCI receiver cell.', 'The linked Phase-2 adjudication explicitly bounds or rejects support for the requested exact relationship. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000091' AND x.extraction_id='M22B-P2-R-000121');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005565', 'M22B-EVID-003652', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003652' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000407', 'M22B-EVID-000461', 'M22B-P2-R-000019A', 'PMCID:PMC12520477; PMID:40755420; DOI:10.1002/advs.202506209', '40755420', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12520477', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC12520477; PMID:40755420; DOI:10.1002/advs.202506209; https://pmc.ncbi.nlm.nih.gov/articles/PMC12520477/; https://pubmed.ncbi.nlm.nih.gov/40755420/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12520477_CCL7_CCR1_STAT1.xml', 'In mouse bone-marrow-derived macrophages, recombinant mouse CCL7 (100 ng/ml, 24 hours) increased STAT1 phosphorylation, inflammatory cytokine secretion, M1 polarization, migration/invasion, glycolysis, and STAT1 K665 succinylation; these effects were reduced in Ccr1-knockout macrophages. Re-expression of CCR1 in Ccr1-knockout cells partially restored inflammatory and metabolic outputs, while STAT1 depletion blocked the rescue. The study supports a CCL7–CCR1–STAT1 pathway branch with KAT2A-dependent STAT1 modification, but it did not demonstrate direct CCL7–CCR1 binding or a canonical JAK1/2 phosphorylation relay.', 'The authors conclude that CCL7–CCR1 activation increases KAT2A-dependent STAT1 K665 succinylation, sustaining STAT1 activity and driving pro-inflammatory macrophage polarization and metabolic reprogramming.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12520477_CCL7_CCR1_STAT1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000461' AND x.extraction_id='M22B-P2-R-000019A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000407', 'M22B-EVID-000461', 'M22B-P2-R-000019B', 'PMCID:PMC12520477; PMID:40755420; DOI:10.1002/advs.202506209', '40755420', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12520477', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC12520477; PMID:40755420; DOI:10.1002/advs.202506209; https://pmc.ncbi.nlm.nih.gov/articles/PMC12520477/; https://pubmed.ncbi.nlm.nih.gov/40755420/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12520477_CCL7_CCR1_STAT1.xml', 'In CCL7-treated mouse BMDMs, STAT1 CUT&Tag showed increased promoter occupancy and ChIP-PCR confirmed STAT1 at HK1, LDHB, and SLC2A1 promoter regions. Dual-luciferase assays validated STAT1-responsive sites, and increased binding was accompanied by increased target-gene mRNA and protein. STAT1 K665R reduced these effects, linking succinylation state to promoter binding and glycolytic-gene regulation. The record supports direct STAT1-to-target-module evidence while retaining HK1/LDHB/SLC2A1 as a gene module rather than claiming every glycolytic gene.', 'The authors conclude that CCL7–CCR1-associated STAT1 K665 succinylation increases STAT1 binding at HK1, LDHB, and SLC2A1 regulatory regions and promotes transcription and translation of this glycolytic target module.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12520477_CCL7_CCR1_STAT1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000461' AND x.extraction_id='M22B-P2-R-000019B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1383672_SMAD8_Msx1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_or_bioc_json', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1383672_SMAD8_Msx1_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000021', 'M22B-EVID-000617', 'M22B-P2-R-000026A', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103', '16606840', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1458887', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103; https://pmc.ncbi.nlm.nih.gov/articles/PMC1458887/; https://pubmed.ncbi.nlm.nih.gov/16606840/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml', 'In NG108-15 neuronal cells, coexpression of dopamine D2R with CLOCK and BMAL1 increased quinpirole-dependent mPer1 promoter-luciferase activity, and haloperidol blocked the response. Deleting the mPer1 CRE did not abolish D2R stimulation, whereas mutation of three E-box elements did. The response was blocked by the MEK inhibitor U0126 and a dominant-negative ERK2, while constitutively active MEK1 mimicked it. Quinpirole also increased CBP recruitment to CLOCK:BMAL1 and CBP phosphorylation without changing CLOCK-BMAL1 association. The study therefore supports a D2R-to-MEK/ERK-to-CLOCK:BMAL1/CBP transcriptional relay, not direct D2R binding to the mPer1 promoter.', 'The authors conclude that D2R signaling potentiates CLOCK:BMAL1-driven mPer1 transcription through a MAPK pathway that increases CBP recruitment and phosphorylation at the CLOCK:BMAL1 complex, with the E-boxes rather than the mPer1 CRE mediating the receptor-dependent response.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000617' AND x.extraction_id='M22B-P2-R-000026A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000021', 'M22B-EVID-000617', 'M22B-P2-R-000026B', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103', '16606840', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1458887', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103; https://pmc.ncbi.nlm.nih.gov/articles/PMC1458887/; https://pubmed.ncbi.nlm.nih.gov/16606840/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml', 'In D2R-null mice, retinal mPer1 oscillatory expression was markedly lower and a 30-minute light pulse at circadian time 18 produced much less mPer1 induction than in wild-type mice. In clock/clock mice expressing transcriptionally inactive CLOCK-Delta19, the same light pulse failed to induce mPer1. These in-vivo data support a physiological requirement for D2R and functional CLOCK:BMAL1 signaling in the retinal mPer1 light-response program.', 'The authors conclude that retinal D2R signaling and a functional CLOCK:BMAL1 complex are required for normal mPer1 oscillation and light-inducibility, establishing an in-vivo dopamine-to-circadian-gene functional branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000617' AND x.extraction_id='M22B-P2-R-000026B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000021', 'M22B-EVID-000617', 'M22B-P2-R-000335', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103', '16606840', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1458887', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC1458887; local full text retry_B22B_batch095_PMC1458887_full.xml', 'D2 receptor activation enhanced CLOCK:BMAL1-dependent mPer1 reporter transcription through a MAPK/ERK pathway and increased CREB-binding-protein recruitment/phosphorylation; D2R-null retina showed reduced mPer1 expression and light response.', 'D2R-MAPK/ERK signaling supports CLOCK:BMAL1-dependent mPer1 transcription and CREB-binding-protein recruitment, but endogenous CLOCK/BMAL1 occupancy at mPer1 is not established by this study.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000617' AND x.extraction_id='M22B-P2-R-000335');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000821', 'M22B-EVID-000624', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000624' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E001373', 'M22B-EVID-000630', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000630' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000019', 'M22B-EVID-000735', 'M22B-P2-R-000022C', 'PMCID:PMC17684; PMID:11087824; DOI:10.1073/pnas.240452197', '11087824', 'full_text_xml', 'exact_identifier_match:PMCID:PMC17684', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC17684; PMID:11087824; DOI:10.1073/pnas.240452197; https://pmc.ncbi.nlm.nih.gov/articles/PMC17684/; https://pubmed.ncbi.nlm.nih.gov/11087824/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC17684_GABAB_CREB2_ATFx.xml', 'In CHO-GABA-B cells, baclofen induced dose-dependent activation of a Gadd153-promoter CAT reporter with an EC50 of approximately 4 micromolar. Reporter activation was abolished by the GABA-B antagonist CGP54626 and strongly reduced by pertussis toxin or the MAPK inhibitor PD98059; it was diminished without transfected CREB2 and was not observed with a mutated CREB2-recognition site in the reporter. The study therefore supports G protein and MAPK-inhibitor-sensitive receptor signaling into a CREB2-responsive reporter, but it did not measure ERK phosphorylation directly or establish endogenous Gadd153 regulation in the receptor model.', 'The authors conclude that GABA-B receptor stimulation activates CREB2-dependent transcription through G protein and MAPK signaling mechanisms, using the Gadd153 promoter-CAT construct as a responsive reporter. They describe Gadd153 as a candidate target but explicitly state that a role for GABA-B receptors in endogenous Gadd153 stress responses was not established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC17684_GABAB_CREB2_ATFx.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000735' AND x.extraction_id='M22B-P2-R-000022C');
