INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000018', 'M22B-EVID-000826', 'M22B-P2-R-000022B', 'PMCID:PMC17684; PMID:11087824; DOI:10.1073/pnas.240452197', '11087824', 'full_text_xml', 'exact_identifier_match:PMCID:PMC17684', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC17684; PMID:11087824; DOI:10.1073/pnas.240452197; https://pmc.ncbi.nlm.nih.gov/articles/PMC17684/; https://pubmed.ncbi.nlm.nih.gov/11087824/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC17684_GABAB_CREB2_ATFx.xml', 'In CHO cells stably expressing GABA-B receptors, baclofen induced loss of cytoplasmic eGFP-CREB2 fluorescence and reduced cytoplasmic CREB2 by immunoblotting; the selective GABA-B antagonist CGP54626 blocked or attenuated the response. In primary rat cortical cultures, baclofen increased the fraction of CREB2-bright nuclei and increased nuclear CREB2 approximately 3.3-fold, with antagonist sensitivity. These experiments support receptor-mediated CREB2 redistribution from cytoplasm toward nucleus, but do not demonstrate CREB2 occupancy at an endogenous genomic locus.', 'The authors conclude that GABA-B receptor activation drives CREB2 redistribution and nuclear accumulation in recombinant receptor cells and neurons with endogenous GABA-B receptors, supporting a receptor-associated transcriptional signaling program.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC17684_GABAB_CREB2_ATFx.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000826' AND x.extraction_id='M22B-P2-R-000022B');
