INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E001698', 'M22B-EVID-000925', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC17684_GABAB_CREB2_ATFx.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000925' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000459', 'M22B-EVID-000010', 'M22B-P2-R-000010', 'PMID:16814729', '16814729', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1904486', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011; https://pmc.ncbi.nlm.nih.gov/articles/PMC1904486/', 'IL-4 induced PGC-1β in macrophages in a STAT6-dependent manner, and PGC-1β coactivated STAT6 at the Arg1 promoter. IL-4 increased STAT6 and PGC-1β recruitment to the Arg1 enhancer; mutation of the STAT6 site abolished STAT6/PGC-1β reporter activation, while PGC-1β expression increased arginase activity and reduced LPS-induced inflammatory cytokines.', 'The authors conclude that STAT6 and PGC-1β cooperate at the Arg1 promoter to drive alternative macrophage activation and associated oxidative/anti-inflammatory functions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1904486_PGC1b.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000010' AND x.extraction_id='M22B-P2-R-000010');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000459', 'M22B-EVID-000010', 'M22B-P2-R-000010-R096', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011', '16814729', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1904486', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_fulltext', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011; https://pmc.ncbi.nlm.nih.gov/articles/PMC1904486/', 'In mouse RAW264.7 macrophages, IL-4 activated STAT6 and increased Arg1 promoter activity; PGC-1β coexpression enhanced this activity, mutation of the STAT6 response element abolished activation, co-immunoprecipitation detected a PGC-1β–STAT6 complex, and quantitative ChIP showed IL-4-dependent corecruitment of STAT6 and PGC-1β to the Arg1 enhancer. PGC-1β perturbation changed arginase and inflammatory-cytokine outputs.', 'The primary study concludes that IL-4-activated STAT6 recruits and is coactivated by PGC-1β at the Arg1 enhancer, contributing to alternative macrophage activation and metabolic/anti-inflammatory outputs.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1904486_PGC1b.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000010' AND x.extraction_id='M22B-P2-R-000010-R096');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000459', 'M22B-EVID-000010', 'M22B-P2-R-RECOVERY-STAT6-ARG1-000001', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011', '16814729', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1904486', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011; https://pmc.ncbi.nlm.nih.gov/articles/PMC1904486/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch074_PMC1904486_PGC1beta.html', 'In mouse RAW264.7 macrophages, IL-4 activated STAT6 and increased arginase I promoter activity approximately twofold; coexpression of PGC-1beta increased activity to approximately eightfold over basal. Mutation of the STAT6 response element in the arginase I enhancer abolished activation by STAT6 plus PGC-1beta. Coimmunoprecipitation detected a soluble PGC-1beta-STAT6 complex, and quantitative ChIP showed IL-4-dependent corecruitment of STAT6 and PGC-1beta to the arginase I enhancer. PGC-1beta expression increased IL-4-associated arginase activity and reduced inflammatory cytokine output, while PGC-1beta knockdown impaired the alternative macrophage program. Separately, STAT6-null macrophages failed to induce the IL-4-responsive metabolic program, and STAT6 directly bound and activated an MCAD promoter STAT6 response element by EMSA, supershift, and promoter mutagenesis.', 'The authors conclude that IL-4-activated STAT6 recruits and is coactivated by PGC-1beta at the arginase I enhancer, contributing to alternative macrophage activation and its metabolic and anti-inflammatory outputs. The STAT6 response-element mutation, STAT6/PGC-1beta ChIP, and coimmunoprecipitation support a direct promoter/enhancer-regulatory record with co-regulatory dependence. This does not establish direct IL-13 receptor-complex regulation in every cell type or an SCI receiver-cell result.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1904486_PGC1b.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000010' AND x.extraction_id='M22B-P2-R-RECOVERY-STAT6-ARG1-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000383', 'M22B-EVID-000044', 'M22B-P2-R-000044-R089', 'PMCID:PMC230332; PMID:14517293; DOI:10.1128/MCB.23.20.7230-7242.2003', '14517293', 'full_text_xml', 'exact_identifier_match:PMCID:PMC230332', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC230332; PMID:14517293; DOI:10.1128/MCB.23.20.7230-7242.2003; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC230332_program.xml', 'Myostatin bound ActRIIB and formed receptor complexes with ALK4 or ALK5, induced Smad2/Smad3 phosphorylation and TGF-beta-like reporter activity, and selectively blocked BMP7 but not BMP2 signaling and adipogenesis in mesenchymal precursor and preadipocyte models.', 'The primary study supports a myostatin-ActRIIB/ALK4-or-ALK5-Smad2/3 receptor-proximal pathway and BMP7-antagonist/adipogenesis output. It does not establish a direct Smad2/3 target-gene occupancy edge and is a comparator for the shared pathway family, not a Nodal-specific claim.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC230332_program.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000044' AND x.extraction_id='M22B-P2-R-000044-R089');
