INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000392', 'M22B-EVID-000022', 'M22B-P2-R-000022-R098', 'PMCID:PMC2430079; PMID:18314002; DOI:10.1016/j.bone.2008.01.006', '18314002', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.bone.2008.01.006;PMCID:PMC2430079', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC2430079; PMID:18314002; DOI:10.1016/j.bone.2008.01.006; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2430079_SMAD_CTGF.html; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch098_pubmed.xml', 'TGF-beta1 induced CTGF promoter activity in primary rat osteoblasts through Smads3/4 plus Src-ERK signaling; promoter deletion/mutation and EMSA showed that both TRE and SBE motifs were required.', 'The primary study supports a TGF-beta1-Smad3/4-Src-ERK CTGF promoter pathway in rat osteoblasts, but does not establish an isolated Smad3/4-only edge, Smad2 participation, BMP8B/GDF11/activin/MSTN receptor use, or SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2430079_SMAD_CTGF.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000022' AND x.extraction_id='M22B-P2-R-000022-R098');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000392', 'M22B-EVID-000022', 'M22B-P2-R-000054', 'PMID:18314002; PMCID:PMC2430079; DOI:10.1016/j.bone.2008.01.006', '18314002', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.bone.2008.01.006;PMCID:PMC2430079', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:18314002; PMCID:PMC2430079; DOI:10.1016/j.bone.2008.01.006; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2430079.html', 'In primary rat osteoblasts, TGF-beta1 increased CTGF promoter activity and CTGF protein expression. TGF-beta1 activated Smad2 and Smad3, but siRNA depletion showed that Smad3 and Smad4, not Smad2, were required for CTGF promoter activation and protein induction. ERK and Src activity were also required, and promoter deletion analysis supported combined SBE and TRE requirements.', 'The authors conclude that TGF-beta1 induction of CTGF in primary osteoblasts requires Smad3/Smad4 together with ERK and Src signaling and depends on cooperating SBE and TRE promoter elements; Smad2 activation alone is insufficient.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2430079_SMAD_CTGF.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000022' AND x.extraction_id='M22B-P2-R-000054');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000395', 'M22B-EVID-000023', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', NULL, 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2430079_SMAD_CTGF.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000023' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2798829_BMP_SMAD.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000456', 'M22B-EVID-000028', 'M22B-P2-R-000028', 'PMID:14627821; PMCID:PMC290274; DOI:10.1093/nar/gkg907', '14627821', 'full_text_xml', 'exact_identifier_match:PMCID:PMC290274', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:14627821; PMCID:PMC290274; DOI:10.1093/nar/gkg907; https://pmc.ncbi.nlm.nih.gov/articles/PMC290274/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch076_PMC290274_CIS.html', 'In IL-3-dependent murine Ba/F3-beta pro-B cells, IL-3 stimulation recruited STAT5A/B to the endogenous Cis promoter, including the -184/-102 STAT5-site amplicon; constitutively active STAT5A increased Cis expression and STAT5A/B siRNA reduced IL-3-induced Cis. ChIP and RT-qPCR/western analyses support STAT5 promoter association and cytokine-induced Cis transcription; TSA separated STAT5 recruitment from basal transcription-machinery recruitment.', 'The primary study concludes that STAT5 recruitment to the cytokine-inducible Cis promoter is required in the IL-3/Ba/F3 comparator for Cis transcription, with local chromatin remodeling and a separate deacetylase-sensitive recruitment step. This supports the shared STAT5-to-Cish direct TF-target edge, but not assignment to every queued IL-2/IL-5/IL-7/IL-9/IL-15 receptor branch or an SCI receiver cell.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC290274_Cish.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000028' AND x.extraction_id='M22B-P2-R-000028');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000449', 'M22B-EVID-000055', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', NULL, 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC290274_Cish.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000055' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000124', 'M22B-EVID-000150', 'M22B-P2-R-000028I', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436', '17962702', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2905627', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436; https://pmc.ncbi.nlm.nih.gov/articles/PMC2905627/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml', 'GDNF increased phosphorylation of CREB1, ATF1, and CREM1 and induced c-fos transcription in C18-4 mouse spermatogonial stem cells. MEK1/ERK inhibition with PD98059 blocked GDNF-induced ERK1/2 phosphorylation and c-fos transcription, supporting an ERK-dependent CREB-family/immediate-early branch.', 'The authors conclude that GDNF/GFRα1/Ret activates Ras/ERK1/2 and thereby phosphorylates CREB-family factors and induces c-fos transcription.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000150' AND x.extraction_id='M22B-P2-R-000028I');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000124', 'M22B-EVID-000150', 'M22B-P2-R-000028J', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436', '17962702', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2905627', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436; https://pmc.ncbi.nlm.nih.gov/articles/PMC2905627/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml', 'GDNF increased BrdU incorporation, metaphase counts, and cyclin A/CDK2 expression in C18-4 cells, while PD98059 blocked the GDNF-induced BrdU, metaphase, cyclin A, and CDK2 responses. These data link the measured GDNF/ERK branch to S-phase entry and spermatogonial stem-cell proliferation.', 'The authors conclude that GDNF-induced Ras/ERK1/2 signaling promotes cell-cycle progression and proliferation of the C18-4 spermatogonial stem-cell model through downstream cyclin A/CDK2-associated outputs.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000150' AND x.extraction_id='M22B-P2-R-000028J');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000124', 'M22B-EVID-000150', 'M22B-P2-R-000152', 'PMCID:PMC2905627; PMID:17962702; PMID:8657281; DOI:10.1634/stemcells.2007-0436; DOI:10.1038/381785a0', '8657281', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2905627', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_downstream_program', 'PMCID:PMC2905627; PMID:17962702; PMID:8657281; DOI:10.1634/stemcells.2007-0436; DOI:10.1038/381785a0; https://pmc.ncbi.nlm.nih.gov/articles/PMC2905627/; https://pubmed.ncbi.nlm.nih.gov/8657281/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMIDs_141_150_pubmed.xml', 'In the mouse C18-4 spermatogonial stem-cell line and freshly isolated type-A spermatogonia, GDNF stimulated RET phosphorylation, Shc/Grb2 recruitment, Ras and ERK1/2 activation, phosphorylation of CREB-1, ATF-1, and CREM-1, and c-fos transcription. MEK1/ERK1/2 inhibition blocked ERK1/2 phosphorylation, c-fos transcription, DNA synthesis, and proliferation readouts. A separate primary receptor study showed GDNF binding to RET and RET-dependent survival/growth responses in transfected fibroblasts.', 'Retain GDNF-GFRα1/RET-to-Ras/ERK1/2-to-CREB-family/c-fos as a primary spermatogonial proliferation program, with direct RET engagement supported by the receptor comparator. Do not infer direct CREB-family occupancy at a terminal gene or transfer the germ-cell proliferative output to SCI receivers.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000150' AND x.extraction_id='M22B-P2-R-000152');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000126', 'M22B-EVID-000151', 'M22B-P2-R-000153', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436', '17962702', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2905627', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436; https://pmc.ncbi.nlm.nih.gov/articles/PMC2905627/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml', 'Reuse the validated GDNF-GFRα1/RET-Ras/ERK1/2-CREB-family observation for the distinct phenotype handoff: GDNF-induced c-fos transcription, cyclin A/CDK2 expression, DNA synthesis, and spermatogonial stem-cell proliferation were blocked by MEK1/ERK1/2 inhibition. No direct CREB-family target-gene edge is assigned.', 'Reuse GDNF-GFRα1/RET-CREB-family signaling and spermatogonial proliferation as a separate functional output. Do not convert c-fos transcription into direct CREB occupancy or transfer the germ-cell phenotype to SCI receivers.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000151' AND x.extraction_id='M22B-P2-R-000153');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000125', 'M22B-EVID-000152', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000152' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2928856_plumbagin_STAT3.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000455', 'M22B-EVID-000077', 'M22B-P2-R-000077-R091', 'PMCID:PMC309603; PMID:14645506; DOI:10.1128/MCB.23.24.8934-8945.2003', '14645506', 'full_text_xml', 'exact_identifier_match:PMCID:PMC309603', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC309603; PMID:14645506; DOI:10.1128/MCB.23.24.8934-8945.2003; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC309603_TPO_Ccnd1.xml', 'TPO stimulation of human UT7-mpl cells increased cyclin D1 expression and promoter activity. A proximal bipartite Oct-GAS2 element recruited STAT5A/STAT5B with Oct-1, and mutations of the combined element reduced TPO-dependent cyclin D1 promoter activation; biochemical pull-down and EMSA supported the Oct-1/STAT5 DNA-bound complex.', 'The primary study directly supports TPO/MPL-associated STAT5A/STAT5B recruitment and Oct-1 cooperation at the cyclin D1 promoter in UT7-mpl cells; it does not establish the edge in SCI or resolve a single STAT5 paralog as uniquely sufficient.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC309603_TPO_Ccnd1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000077' AND x.extraction_id='M22B-P2-R-000077-R091');
