INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3176640_NDN.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3352154_EGF_ELK1_EGR1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000310', 'M22B-EVID-000271', 'M22B-P2-R-000029B', 'PMCID:PMC3408167; PMID:22669972; DOI:10.1074/jbc.M112.356279', '22669972', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m112.356279;PMCID:PMC3408167', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3408167; PMID:22669972; DOI:10.1074/jbc.M112.356279; https://pmc.ncbi.nlm.nih.gov/articles/PMC3408167/; https://pubmed.ncbi.nlm.nih.gov/22669972/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3408167_TNF_NFKB_FAS.html', 'In human SW620 metastatic colon carcinoma cells, TNFα treatment increased cell-surface Fas, and p50 ChIP after 30 minutes showed canonical NF-κB association with multiple regions of the human FAS promoter. EMSA showed canonical NF-κB binding to all five mapped NF-κB consensus sequences in the promoter. Blocking canonical NF-κB with dominant-negative IKKβ reduced Fas protein and mRNA, whereas blocking alternate NF-κB with dominant-negative IKKα increased both.', 'The authors conclude that TNFα-activated canonical NF-κB directly binds multiple sites in the human FAS promoter and activates FAS transcription, while alternate NF-κB acts as a repressive branch in the tested carcinoma context.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3408167_TNF_NFKB_FAS.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000271' AND x.extraction_id='M22B-P2-R-000029B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000310', 'M22B-EVID-000271', 'M22B-P2-R-000239', 'PMCID:PMC3408167; PMID:22669972; DOI:10.1074/jbc.M112.356279', '22669972', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m112.356279;PMCID:PMC3408167', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC3408167; PMID:22669972; DOI:10.1074/jbc.M112.356279; https://pmc.ncbi.nlm.nih.gov/articles/PMC3408167/', 'TNF-alpha and IFN-gamma increased FAS expression in tumor-cell and MEF models. ChIP with p50 and phosphorylated STAT1 across the FAS promoter, EMSA with NF-kappaB subunits including p65, and promoter perturbation support direct canonical NF-kappaB/RelA-associated FAS transcription; the paper also distinguishes an alternate NF-kappaB repressive mechanism. This is a TNF-to-NF-kappaB-to-FAS transcription chain, not a direct TNF-FAS molecular interaction.', 'Promote the direct NF-kappaB/RelA-associated FAS promoter edge in the reported tumor-cell and MEF systems. Link it to TNF only through the measured upstream activation context and preserve the alternate NF-kappaB repressor branch; do not represent TNF as directly binding FAS or assume TNFR subtype specificity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3408167_TNF_NFKB_FAS.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000271' AND x.extraction_id='M22B-P2-R-000239');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000344', 'M22B-EVID-000018', 'M22B-P2-R-000018-R097', 'PMCID:PMC3423339; PMID:22622516; DOI:10.1007/s10456-012-9277-x', '22622516', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3423339', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC3423339; PMID:22622516; DOI:10.1007/s10456-012-9277-x; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3423339_BMP9_EphrinB2.xml; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch097_pubmed.xml', 'BMP9 induced EphrinB2 in endothelial cells through an ALK1-ACVRL1 and BMPRII/ActRII coreceptor context, with ID1 and ID3 required for full induction; Alk1 or EphrinB2 loss altered sprouting and arterial-venous anastomosis, while BMP9 blocked endothelial sprouting.', 'The primary study supports a BMP9-ALK1-BMPRII/ActRII-ID1/ID3 endothelial pathway and sprouting phenotype, but does not establish direct ID1/ID3 occupancy at the EphrinB2 locus, distinguish BMPRII from ActRII in every assay, or transfer the vascular result to SCI endothelium.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3423339_BMP9_EphrinB2.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000018' AND x.extraction_id='M22B-P2-R-000018-R097');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000432', 'M22B-EVID-000083', 'M22B-P2-R-000083-R092', 'PMCID:PMC3424405; PMID:22865915; DOI:10.4049/jimmunol.1201126', '22865915', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3424405', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC3424405; PMID:22865915; DOI:10.4049/jimmunol.1201126; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3424405_IL10_Zfp36.xml', 'IL-10 induced STAT3 recruitment to a conserved STAT3 binding site in the Ttp/Zfp36 promoter in LPS-activated mouse bone-marrow-derived macrophages; STAT3 was required for efficient IL-10-induced Ttp expression, forming a feedback loop that limited inflammatory cytokine production.', 'The primary study directly supports IL-10 receptor-pathway-associated STAT3 recruitment and transcriptional activation of the Ttp/Zfp36 promoter in activated macrophages; receptor-complex details, cell-state transfer, and SCI application remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3424405_IL10_Zfp36.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000083' AND x.extraction_id='M22B-P2-R-000083-R092');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000417', 'M22B-EVID-000030', 'M22B-P2-R-000028B', 'PMCID:PMC3529151; PMID:22306691; DOI:10.1038/ni.2227', '22306691', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3529151', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3529151; PMID:22306691; DOI:10.1038/ni.2227; https://pmc.ncbi.nlm.nih.gov/articles/PMC3529151/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3529151_IL35.xml', 'IL-35 stimulation of activated wild-type mouse Tconv cells induced STAT1 and STAT4 phosphorylation but not STAT3 or STAT5 above background. In receptor-chain single-deficient cells, IL-12Rβ2-supported signaling produced pSTAT4 whereas gp130-supported signaling produced pSTAT1; Stat1−/− and Stat4−/− cells showed reduced IL-35-mediated suppression, while Stat3 deficiency did not reproduce that defect.', 'The authors conclude that IL-35 uses receptor-chain-specific STAT1 and STAT4 activation and that both STAT1 and STAT4 are required for maximal IL-35-mediated suppressive activity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3529151_IL35.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000030' AND x.extraction_id='M22B-P2-R-000028B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000417', 'M22B-EVID-000030', 'M22B-P2-R-000028C', 'PMCID:PMC3529151; PMID:22306691; DOI:10.1038/ni.2227', '22306691', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3529151', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3529151; PMID:22306691; DOI:10.1038/ni.2227; https://pmc.ncbi.nlm.nih.gov/articles/PMC3529151/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3529151_IL35.xml', 'IL-35 induced STAT1:STAT4 heterodimer formation by reciprocal co-immunoprecipitation. ChIP and ChIP-reChIP in activated mouse Tconv cells showed IL-35-dependent co-enrichment of STAT1 and STAT4 at multiple sites in the Il12a and Ebi3 promoters, strongest at Il12a−250 and Ebi3−500, while IL-12 plus IFN-γ induced little STAT1:STAT4 promoter interaction. IL-35 also induced Ebi3 and Il12a transcription within 1–3 hours, and Stat1 or Stat4 deficiency reduced those transcripts.', 'The authors conclude that an IL-35-induced STAT1:STAT4 heterodimer directly engages multiple Il12a and Ebi3 promoter sites and provides a distinct transcriptional route to IL-35 production and iTr35 conversion.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3529151_IL35.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000030' AND x.extraction_id='M22B-P2-R-000028C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000417', 'M22B-EVID-000030', 'M22B-P2-R-000028D', 'PMCID:PMC3529151; PMID:22306691; DOI:10.1038/ni.2227', '22306691', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3529151', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3529151; PMID:22306691; DOI:10.1038/ni.2227; https://pmc.ncbi.nlm.nih.gov/articles/PMC3529151/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3529151_IL35.xml', 'IL-35 induced Ebi3 and Il12a expression and conversion of naive mouse Tconv cells into suppressive iTr35 cells. Deletion of either Il12rb2 or gp130 blocked IL-35-induced Ebi3/Il12a upregulation and prevented the suppressive iTr35 phenotype, while IL-35R double-deficient cells were resistant to suppression in vitro and in vivo.', 'The authors conclude that complete IL-35R signaling and coordinated STAT1/STAT4 activity are required for IL-35 production and the suppressive iTr35 cell-state output.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3529151_IL35.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000030' AND x.extraction_id='M22B-P2-R-000028D');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000417', 'M22B-EVID-000030', 'M22B-P2-R-000030', 'PMCID:PMC3529151', '22306691', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3529151', 'candidate_requires_review', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC3529151', 'The stable PMCID anchor and B-layer summary identify an IL-35-associated STAT1/STAT4 suppressor-cell program, but no retained complete primary-paper Results/Methods/figure passage was available through the supervised CLI cache.', 'Do not assign separate directional STAT1, STAT4, Ebi3, or Il12a edges, or collapse partial IL12RB2/gp130 signaling into one receptor pathway without primary validation.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3529151_IL35.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000030' AND x.extraction_id='M22B-P2-R-000030');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000442', 'M22B-EVID-000034', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3529151_IL35.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000034' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3623615_STAT1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_or_bioc_json', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3623615_STAT1_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000385', 'M22B-EVID-000047', 'M22B-P2-R-000047-R089', 'PMCID:PMC4067217; PMID:24798330; DOI:10.1074/jbc.M114.550301', '24798330', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4067217', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC4067217; PMID:24798330; DOI:10.1074/jbc.M114.550301; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4067217_program.xml', 'Purified Nodal-Gdf1 heterodimers with bound prodomains produced stronger CAGA-luc Activin-pathway output than Nodal alone; Cryptic/Cripto context, Acvr2a/Acvr2b inhibition or depletion, receptor-Fc pulldown, and improved human ES-cell endoderm marker induction supported a receptor-complex and functional program.', 'The primary study supports a Nodal-Gdf1-CFC/Activin-receptor-Smad2/3-associated pathway and endoderm output, while showing that Gdf1 potentiation does not simply increase receptor affinity. It does not establish direct Smad2/3 promoter occupancy, exact receptor stoichiometry for every context, or SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4067217_program.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000047' AND x.extraction_id='M22B-P2-R-000047-R089');
