INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004502', 'M20B-EVID-004502-P2-DIRECT', 'M20B-P2-R-004502-R222A', 'PMID:25595774; PMCID:PMC4319313; DOI:10.4049/jimmunol.1402303', '25595774', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4319313', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_claim', 'PMID:25595774; PMCID:PMC4319313; DOI:10.4049/jimmunol.1402303; https://doi.org/10.4049/jimmunol.1402303; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PGLYRP1_PIGF_PLA2G10_receptor_primary_records.xml; /private/tmp/PMC4319313_full.xml', 'PGLYRP1/peptidoglycan complexes bound TREM-1; SPR showed PGLYRP1 binding to immobilized TREM-1, and TREM-1-Fc bound membrane PGLYRP1 cells.', 'PGLYRP1 directly engages TREM-1 in the reported multimeric or peptidoglycan-complexed states.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4319313_TREM1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004502-P2-DIRECT' AND x.extraction_id='M20B-P2-R-004502-R222A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004502', 'M20B-EVID-004502-P2-FUNC', 'M20B-P2-R-004502-R222C', 'PMID:25595774; PMCID:PMC4319313; DOI:10.4049/jimmunol.1402303', '25595774', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4319313', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_functional_claim', 'PMID:25595774; PMCID:PMC4319313; DOI:10.4049/jimmunol.1402303; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PGLYRP1_PIGF_PLA2G10_receptor_primary_records.xml; /private/tmp/PMC4319313_full.xml', 'PGLYRP1/peptidoglycan or multimerized PGLYRP1 induced TNF-alpha in human macrophages and IL-8 in human neutrophils; anti-TREM-1 or anti-PGLYRP1 reduced the response.', 'PGLYRP1→TREM-1 supports conditional myeloid inflammatory cytokine output.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4319313_TREM1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004502-P2-FUNC' AND x.extraction_id='M20B-P2-R-004502-R222C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004502', 'M20B-EVID-004502-P2-RELAY', 'M20B-P2-R-004502-R222B', 'PMID:25595774; PMCID:PMC4319313; DOI:10.4049/jimmunol.1402303', '25595774', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4319313', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_relay_claim', 'PMID:25595774; PMCID:PMC4319313; DOI:10.4049/jimmunol.1402303; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_PGLYRP1_PIGF_PLA2G10_receptor_primary_records.xml; /private/tmp/PMC4319313_full.xml', 'PGLYRP1 activated a TREM-1/DAP12 reporter with NFAT-LacZ output; anti-TREM-1 blocked the response, and membrane PGLYRP1 activated the reporter without peptidoglycan.', 'PGLYRP1→TREM-1 engages a TREM-1/DAP12 receptor-proximal activation relay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4319313_TREM1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004502-P2-RELAY' AND x.extraction_id='M20B-P2-R-004502-R222B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000427', 'M22B-EVID-000069', 'M22B-P2-R-000069-R091-A', 'PMCID:PMC4319313; PMID:25595774; DOI:10.4049/jimmunol.1402303', '25595774', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4319313', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_LIGAND_RECEPTOR_FUNCTION_BOUNDED', 'PMCID:PMC4319313; PMID:25595774; DOI:10.4049/jimmunol.1402303; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4319313_TREM1.xml', 'PGLYRP1 complexed with bacterial peptidoglycan or was multimerized to bind and activate TREM-1; TREM-1 reporter activation and TNF-alpha/IL-8 production in human macrophages and neutrophils were reduced by TREM-1 blockade.', 'The primary study supports PGLYRP1/peptidoglycan-to-TREM-1 binding and activation, but it does not establish a STAT3 relay or a STAT3 target gene; those downstream layers remain separate and unknown in this source.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4319313_TREM1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000069' AND x.extraction_id='M22B-P2-R-000069-R091-A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000436', 'M22B-EVID-000071', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4319313_TREM1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000071' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000830', 'M22B-P2-R-000023A', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468', '26020477', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; https://pmc.ncbi.nlm.nih.gov/articles/PMC4447080/; https://pubmed.ncbi.nlm.nih.gov/26020477/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml', 'In primary mouse cerebellar granule neurons, baclofen increased Fmrp protein and Fmr1 mRNA in a dose- and time-dependent manner; CGP7930, a GABA-B positive allosteric modulator with agonist activity in this system, produced a similar FMRP-expression response. In recombinant MEFs co-transfected with GABA-B1 and GABA-B2, CREB depletion abolished the baclofen-induced increase in FMRP. The result supports GABA-B-to-CREB-dependent Fmr1/FMRP regulation, but does not establish CREB binding at the endogenous Fmr1 regulatory region.', 'The authors conclude that GABA-B receptor activation increases Fmr1/FMRP expression through CREB-dependent signaling in the tested neuronal and recombinant-cell models. This is an indirect receptor-to-regulatory-output record, not a direct CREB-to-Fmr1 promoter edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000830' AND x.extraction_id='M22B-P2-R-000023A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000830', 'M22B-P2-R-000346', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; PMID:17582742; DOI:10.1016/j.cellsig.2007.05.004', '26020477', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; local full text retry_B22B_batch042_PMC4447080_GABAB_FMRP.html; local PubMed retry_B22B_batch042_pubmed_11312600_26020477_17582742.xml', 'In cultured mouse cerebellar granule neurons, baclofen and the GABA-B positive allosteric modulator CGP7930 increased Fmr1 mRNA and FMRP protein and induced transient CREB phosphorylation. CREB siRNA blocked baclofen-induced FMRP upregulation in GABA-B1/GABA-B2-expressing MEFs. Perturbation of Gi/o, PLC-beta, FAK, IGF-1R, and PKC bounded parallel GABA-B-to-CREB relays, but no CREB occupancy assay at the Fmr1 regulatory region was reported.', 'GABA-B receptor activation supports a CREB-dependent Fmr1/FMRP expression program through parallel IGF-1R transactivation/ERK-Akt and PKC branches, but the primary study does not demonstrate CREB binding at the Fmr1 regulatory region; retain this as pathway/function evidence rather than a direct TF-target edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000830' AND x.extraction_id='M22B-P2-R-000346');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000831', 'M22B-P2-R-000023B', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468', '26020477', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; https://pmc.ncbi.nlm.nih.gov/articles/PMC4447080/; https://pubmed.ncbi.nlm.nih.gov/26020477/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml', 'In primary mouse cerebellar granule neurons, baclofen and CGP7930 caused concentration-dependent, transient CREB phosphorylation that peaked at approximately 10 minutes and returned toward baseline by 60 minutes; the baclofen response was blocked by the competitive GABA-B antagonist CGP54626. CREB siRNA in GABA-B1/GABA-B2-expressing MEFs eliminated the baclofen-induced FMRP increase, linking the measured CREB activation state to the downstream FMRP output without demonstrating CREB occupancy at Fmr1 chromatin.', 'The authors conclude that GABA-B receptor activation produces a transient CREB phosphorylation response that is required for the observed FMRP upregulation in the tested models.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000831' AND x.extraction_id='M22B-P2-R-000023B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000832', 'M22B-P2-R-000023C', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468', '26020477', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; https://pmc.ncbi.nlm.nih.gov/articles/PMC4447080/; https://pubmed.ncbi.nlm.nih.gov/26020477/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml', 'In primary mouse cerebellar granule neurons, baclofen-induced phosphorylation of ERK1/2, Akt, and CREB was reduced by pertussis toxin, the PLC-beta inhibitor U73122, the FAK inhibitor PF573228, or the IGF-1R inhibitor AG1024. In recombinant GABA-B1/GABA-B2-expressing MEFs, IGF-1R siRNA or shRNA reduced baclofen-induced ERK1/2, Akt, and CREB phosphorylation. These perturbations support a G protein/PLC-beta/FAK-dependent IGF-1R transactivation branch feeding into ERK-Akt-CREB, without showing direct GABA-B/IGF-1R binding.', 'The authors conclude that GABA-B receptor-mediated G protein/PLC-beta/FAK signaling transactivates IGF-1R and thereby contributes to ERK1/2, Akt, and CREB phosphorylation. The study supports a receptor-proximal/pathway branch, not a purified receptor-IGF-1R molecular interaction.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000832' AND x.extraction_id='M22B-P2-R-000023C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000833', 'M22B-P2-R-000023D', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468', '26020477', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; https://pmc.ncbi.nlm.nih.gov/articles/PMC4447080/; https://pubmed.ncbi.nlm.nih.gov/26020477/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml', 'In primary mouse cerebellar granule neurons, broad PKC inhibitors reduced baclofen-induced CREB phosphorylation while leaving ERK1/2 and Akt phosphorylation largely unchanged; siRNA against PKC-alpha or PKC-beta in GABA-B1/GABA-B2-expressing MEFs reduced baclofen-induced CREB phosphorylation without reducing IGF-1R transactivation or ERK1/2/Akt phosphorylation. PKC inhibition also reduced baclofen-induced FMRP expression. The findings support a PKC-dependent CREB branch that is at least partly independent of the IGF-1R/ERK-Akt branch.', 'The authors conclude that calcium-sensitive PKC-alpha/beta signaling is required for GABA-B receptor-induced CREB activation and contributes to FMRP upregulation independently of IGF-1R transactivation and ERK1/2-Akt phosphorylation.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000833' AND x.extraction_id='M22B-P2-R-000023D');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000127', 'M22B-EVID-000834', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000834' AND x.extraction_id='');
