INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_or_bioc_json', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4510980_SMAD23_lefty_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000174', 'M22B-EVID-000141', 'M22B-P2-R-000141-R094', 'PMCID:PMC4763945; PMID:26555052; DOI:10.1016/j.devcel.2015.10.006', '26555052', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4763945', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC4763945; PMID:26555052; DOI:10.1016/j.devcell.2015.10.006; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4763945_ETV.json; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_pubmed.xml', 'In embryonic mouse lung epithelium, FGF-activated ETV4/ETV5 factors promoted Shh expression through a long-range MACS1 enhancer approximately 800 kb upstream of Shh; mutation of conserved ETV sites reduced enhancer activity, wild-type but not DNA-binding-defective ETV5 activated the reporter, and ETV5-Flag ChIP recovered the enhancer.', 'The primary study directly supports ETV5 occupancy and enhancer-dependent activation of Shh in the FGF10-FGFR2-linked lung epithelial program; ETV4 and the exact upstream ligand/receptor isoform are not separately resolved in the ChIP assay, and SCI transfer is unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4763945_ETV.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000141' AND x.extraction_id='M22B-P2-R-000141-R094');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000172', 'M22B-EVID-000142', 'M22B-P2-R-000142-R094', 'PMCID:PMC4763945; PMID:26555052; DOI:10.1016/j.devcel.2015.10.006', '26555052', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4763945', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC4763945; PMID:26555052; DOI:10.1016/j.devcell.2015.10.006; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4763945_ETV.json', 'Loss of epithelial Etv4/Etv5 increased Fgf10, decreased Shh, prolonged lung branch-tip growth, and delayed new branch formation; reducing Fgf10 dosage or activating SHH signaling partially rescued the mutant branching phenotype.', 'The primary study supports an FGF-ETV-SHH feedback program controlling lung branching periodicity and branch-tip morphogenesis, but the developmental phenotype is separate from direct ETV5 enhancer occupancy and is not evidence of an SCI repair function or ETV4-specific causality.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4763945_ETV.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000142' AND x.extraction_id='M22B-P2-R-000142-R094');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000172', 'M22B-EVID-000142', 'M22B-P2-R-000147', 'PMID:26555052; PMCID:PMC4763945; DOI:10.1016/j.devcell.2015.10.006', '26555052', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4763945', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:26555052; PMCID:PMC4763945; DOI:10.1016/j.devcel.2015.10.006; https://pmc.ncbi.nlm.nih.gov/articles/PMC4763945/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC4763945_bioc.json', 'Reuse the validated FGF-regulated ETV/Shh observation for the distinct lung branching phenotype handoff: Etv4/Etv5 loss increased Fgf10, reduced Shh signaling, enlarged branch tips, and reduced or delayed new branch formation; Fgf10 dosage and Smoothened agonist experiments partially attenuated the phenotype. No phenotype-to-TF-target shortcut is made.', 'Reuse the FGF-ETV-SHH feedback-loop and lung branching phenotype as a separate functional output. Do not assign the phenotype to ETV4 or ETV5 alone, and do not infer an SCI repair output.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4763945_ETV.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000142' AND x.extraction_id='M22B-P2-R-000147');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004439', 'M20B-EVID-004439-P2-FUNC', 'M20B-P2-R-004439-R216C', 'PMID:27539849; PMCID:PMC5076839; DOI:10.1074/jbc.M116.748483; PMID:35008777; PMCID:PMC8745562; DOI:10.1016/j.cels.2015.12.004', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC5076839', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_functional_output_support', 'PMID:27539849; PMCID:PMC5076839; DOI:10.1074/jbc.M116.748483; PMID:35008777; PMCID:PMC8745562; DOI:10.1016/j.cels.2015.12.004; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_OSM_IL6ST_LIFR_OSMR_primary_records.xml', 'OSM/LIFR-associated STAT3 signaling contributed to bone remodeling and sclerostin/RANKL regulation in mouse osteocytes; engineered hlOSM-mediated LIFR activation contributed to cardioprotection after myocardial infarction in mice.', 'Promote conditional OSM-gp130/LIFR bone and cardiac outputs with species/ligand engineering qualification.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5076839_OSM_bone.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004439-P2-FUNC' AND x.extraction_id='M20B-P2-R-004439-R216C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004439', 'M20B-EVID-004439-P2-RELAY', 'M20B-P2-R-004439-R216B', 'PMID:27539849; PMCID:PMC5076839; DOI:10.1074/jbc.M116.748483; PMID:22937020; PMCID:PMC3425591; DOI:10.1371/journal.pone.0043155; PMID:37120549; PMCID:PMC10149029; DOI:10.1186/s12967-023-04163-x', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC5076839', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_proximal_relay_support', 'PMID:27539849; PMCID:PMC5076839; DOI:10.1074/jbc.M116.748483; PMID:22937020; PMCID:PMC3425591; DOI:10.1371/journal.pone.0043155; PMID:37120549; PMCID:PMC10149029; DOI:10.1186/s12967-023-04163-x; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_OSM_IL6ST_LIFR_OSMR_primary_records.xml', 'OSM/LIFR/gp130 signaling induced JAK/STAT, with preferential STAT3 in low-affinity murine OSM-LIFR contexts; rat OSM activated JAK/STAT, MAPK, and PI3K/Akt; cardiac OSMR loss engaged a compensatory OSM/LIFR/STAT3 branch.', 'Promote qualified OSM-gp130/LIFR STAT3/JAK-MAPK/PI3K relay; retain STAT3 as a pathway/TF endpoint for Module 22A review rather than infer broader TF activity.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5076839_OSM_bone.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004439-P2-RELAY' AND x.extraction_id='M20B-P2-R-004439-R216B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000426', 'M22B-EVID-000067', 'M22B-P2-R-000067-R091', 'PMCID:PMC5076839; PMID:27539849; DOI:10.1074/jbc.M116.748483', '27539849', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5076839', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC5076839; PMID:27539849; DOI:10.1074/jbc.M116.748483; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5076839_OSM_bone.xml', 'Murine OSM acting through low-affinity LIFR-gp130 in Osmr-null osteocyte/osteoblast models preferentially phosphorylated STAT3 rather than STAT1, induced STAT3-associated genes including Socs3, and suppressed sclerostin; OSM/LIFR and LIFR-dependent genetic models linked the pathway to bone formation and bone-mass protection.', 'The primary study supports a species- and receptor-complex-dependent OSM-LIFR-gp130-STAT3 bone-remodeling program and Socs3 expression output, not a direct STAT3 target-gene occupancy edge or universal OSM/LIFR behavior in SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5076839_OSM_bone.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000067' AND x.extraction_id='M22B-P2-R-000067-R091');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000438', 'M22B-EVID-000068', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5076839_OSM_bone.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000068' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000428', 'M22B-EVID-000074', 'M22B-P2-R-000074-R091', 'PMCID:PMC5549806; PMID:28689994; DOI:10.1016/j.stemcr.2017.06.002', '28689994', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5549806', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC5549806; PMID:28689994; DOI:10.1016/j.stemcr.2017.06.002; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5549806_STRA6.xml', 'RBP4-bound retinol/STRA6 signaling was associated with JAK2-STAT3 activation and maintenance of colon cancer stem-cell properties. STRA6 or RBP4 knockdown reduced pSTAT3, SOX2/NANOG expression, sphere formation, tumor-initiating frequency, and xenograft growth; no STAT3 occupancy at the listed stemness loci was shown.', 'The primary study supports an RBP4-STRA6-JAK2-STAT3-associated cancer stem-cell maintenance program and tumor function, but not direct STAT3 binding at SOX2, LGR5, VEGFA, MYC, or MMP9 loci and not SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5549806_STRA6.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000074' AND x.extraction_id='M22B-P2-R-000074-R091');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000435', 'M22B-EVID-000075', 'M22B-P2-R-000108', 'PMID:28689994; PMCID:PMC5549806; DOI:10.1016/j.stemcr.2017.06.002', '28689994', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5549806', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:28689994; PMCID:PMC5549806; DOI:10.1016/j.stemcr.2017.06.002; https://pubmed.ncbi.nlm.nih.gov/28689994/; https://pmc.ncbi.nlm.nih.gov/articles/PMC5549806/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch064_PMC5549806_bioc.json', 'Reuse the validated RBP4-STRA6/JAK2-STAT3 colon cancer stem-cell observation for the distinct phenotype handoff: RBP4 or STRA6 knockdown reduced sphere-initiating cell frequency, tumor initiation, tumor growth, and stemness-associated expression. No direct STAT3 target gene is assigned.', 'Reuse the RBP4-STRA6-associated STAT3 stemness/tumor-initiation phenotype for this distinct handoff while preserving one source observation. Do not infer a terminal STAT3 target or SCI relevance from the tumor phenotype.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5549806_STRA6.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000075' AND x.extraction_id='M22B-P2-R-000108');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000437', 'M22B-EVID-000076', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5549806_STRA6.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000076' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000014', 'M22B-EVID-000125', 'M22B-P2-R-000125-R093-B', 'PMCID:PMC5585343; PMID:28874659; DOI:10.1038/s41467-017-00357-2', '28874659', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5585343', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC5585343; PMID:28874659; DOI:10.1038/s41467-017-00357-2; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5585343_TSHR_ATF2.xml', 'Endogenous TSHR internalized and trafficked to the trans-Golgi network, where TSH/TSHR complexes met and activated Gs-protein in a retromer-coated compartment; late local cAMP/PKA signaling was required for efficient CREB phosphorylation and TSH-dependent gene transcription. Blocking internalization, PKA-II/TGN localization, retromer, or Golgi organization impaired the response.', 'The primary study supports an intracellular TSH-TSHR-to-TGN-Gs-cAMP/PKA-CREB transcriptional relay, but does not establish CREB occupancy at a named endogenous target gene, the exact TSHR receptor-complex stoichiometry, or SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5585343_TSHR_ATF2.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000125' AND x.extraction_id='M22B-P2-R-000125-R093-B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5621925_IL23_STAT.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC5626396_IL22_Reg3g.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000452', 'M22B-EVID-000080', 'M22B-P2-R-000028F', 'PMCID:PMC6039124; PMID:29535264; DOI:10.1126/scisignal.aam8858', '29535264', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6039124', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6039124; PMID:29535264; DOI:10.1126/scisignal.aam8858; https://pmc.ncbi.nlm.nih.gov/articles/PMC6039124/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6039124_TSLP.xml', 'In mouse CD4+ T cells, a selective JAK2 inhibitor blocked TSLP-induced STAT5 phosphorylation and abrogated TSLP induction of Il5 and Il13. Retroviral Cre-mediated deletion of Stat5a/Stat5b similarly prevented TSLP induction of TH2 cytokine genes, while TSLP still repressed BCL6, showing that TSLP uses separable STAT5-dependent and STAT5-independent branches.', 'The authors conclude that the TSLP-to-Il5/Il13 transcriptional branch requires JAK2 and STAT5, whereas the TSLP-mediated BCL6 repression branch is separable from STAT5 activity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6039124_TSLP.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000080' AND x.extraction_id='M22B-P2-R-000028F');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000452', 'M22B-EVID-000080', 'M22B-P2-R-000028G', 'PMCID:PMC6039124; PMID:29535264; DOI:10.1126/scisignal.aam8858', '29535264', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6039124', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6039124; PMID:29535264; DOI:10.1126/scisignal.aam8858; https://pmc.ncbi.nlm.nih.gov/articles/PMC6039124/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6039124_TSLP.xml', 'TSLP reduced Bcl6 transcript and protein abundance in differentiating mouse CD4+ T cells, and enforced BCL6 expression abolished TSLP-induced Il4, Il5, and Il13 expression. In vivo, transferred wild-type CD4+ T cells produced a stronger house-dust-mite-induced TH2 response than TSLPR-deficient donor cells; TSLP/IL-4-programmed cells also retained pathogenic memory potential.', 'The authors conclude that TSLP establishes a pathogenic TH2 cell state through coordinated JAK2/STAT5 activation and BCL6 repression, with persistent cytokine-producing potential after transient exposure.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6039124_TSLP.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000080' AND x.extraction_id='M22B-P2-R-000028G');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000452', 'M22B-EVID-000080', 'M22B-P2-R-000112', 'PMCID:PMC6039124; DOI:10.1126/science.aan8670', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC6039124', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_program_support', 'PMCID:PMC6039124; DOI:10.1126/science.aan8670; https://pmc.ncbi.nlm.nih.gov/articles/PMC6039124/; https://doi.org/10.1126/science.aan8670; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch064_PMC6039124_bioc.json', 'In mouse and human CD4 T-cell comparator systems, TSLP activated JAK1/JAK2-STAT5 and initiated a pathogenic TH2 transcriptional program. JAK2 inhibition or Stat5a/Stat5b deletion reduced TSLP-induced Il5/Il13 expression; STAT5 ChIP-seq showed binding at regulatory regions associated with Il4, Il13, and Il9. IL-4 amplified and stabilized the response. The record is a multi-locus TF program rather than a single terminal target handoff.', 'Retain TSLP -> JAK1/JAK2-STAT5 -> Il4/Il5/Il9/Il13 TH2-locus program and pathogenic TH2 output as multi-locus TF-program evidence. Do not collapse this into one terminal STAT5 target or transfer the allergic T-cell program to SCI receiver cells.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6039124_TSLP.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000080' AND x.extraction_id='M22B-P2-R-000112');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000454', 'M22B-EVID-000081', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', NULL, 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6039124_TSLP.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000081' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000453', 'M22B-EVID-000082', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6039124_TSLP.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000082' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000336', 'M22B-EVID-000620', 'M22B-P2-R-000338', 'PMCID:PMC6094125; PMID:30037996; DOI:10.1073/pnas.1800930115', '30037996', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6094125', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC6094125; local full text retry_B22B_batch095_PMC6094125_full.xml', 'Eda/EDAR signaling increased RelB occupancy at the Ltb and human Tnfrsf9 promoter regions and recruited BAF chromatin-remodeling components; RelB, BAF, and Tfg perturbations reduced Eda-induced target transcription. Mouse Tnfrsf9 lacked the relevant NF-kB site in the tested skin context.', 'Eda-A1-EDAR signaling directly supports RelB occupancy and RelB/BAF-dependent transcription at the Ltb promoter; Tnfrsf9 occupancy is human-cell-specific in this study and is not transferred to mouse skin.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6094125_EDA_EDAR_RelB_BAF.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000620' AND x.extraction_id='M22B-P2-R-000338');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E001397', 'M22B-EVID-000639', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6094125_EDA_EDAR_RelB_BAF.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000639' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000053', 'M22B-EVID-000213', 'M22B-P2-R-000199', 'PMID:17889508; DOI:10.1016/j.cellsig.2007.08.016; PMID:30115027; PMCID:PMC6097285; DOI:10.1186/s12885-018-4717-7', NULL, 'full_text_html', 'exact_identifier_match:DOI:10.1186/s12885-018-4717-7;PMCID:PMC6097285', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMID:17889508; DOI:10.1016/j.cellsig.2007.08.016; https://pubmed.ncbi.nlm.nih.gov/17889508/; PMID:30115027; PMCID:PMC6097285; DOI:10.1186/s12885-018-4717-7; https://pmc.ncbi.nlm.nih.gov/articles/PMC6097285/', 'Gastrin acting through CCK-B/CCKBR activates PKC-Raf1-MEK1-ERK1/2 in AGS-B gastric cells; MEK/ERK blockade removes gastrin-dependent chromogranin A promoter transactivation, and the minimal CgA-85/-64 element is necessary and sufficient for MEK/ERK responsiveness. The abstract attributes the promoter effect to enhanced Sp1 and CREB phosphorylation. A separate breast-cancer study supports gastrin/CCKBR/ERK/p65 signaling and tumor-suppressive outputs in ER-positive models, but does not establish a direct p65 target promoter.', 'Promote the gastrin-CCKBR-PKC-Raf1-MEK1-ERK1/2-Sp1/CREB-to-CgA promoter program as direct promoter-reporter evidence bounded to AGS-B cells and the primary abstract. Retain the ER-positive breast CCKBR/ERK/p65 program as a separate receptor/pathway context; do not infer a direct p65 target gene or merge the two cell contexts.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6097285_GASTRIN_CCKBR_CREB_CHGA.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000213' AND x.extraction_id='M22B-P2-R-000199');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000054', 'M22B-EVID-000214', 'M22B-P2-R-000200', 'PMID:17889508; DOI:10.1016/j.cellsig.2007.08.016; PMID:30115027; PMCID:PMC6097285; DOI:10.1186/s12885-018-4717-7', NULL, 'full_text_html', 'exact_identifier_match:DOI:10.1186/s12885-018-4717-7;PMCID:PMC6097285', 'linked_unresolved', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:30115027; PMCID:PMC6097285; DOI:10.1186/s12885-018-4717-7; PMID:17889508; DOI:10.1016/j.cellsig.2007.08.016; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch078_PMC6097285_full.xml and retry_B22B_batch078_PMIDs_211_220_pubmed.xml', 'Reuse the gastrin/CCKBR observation for a distinct functional output: gastrin-associated ERK/p65 activity inhibited ER-positive breast-cancer cell growth and xenograft output in the tested models, while the separate AGS-B study reported gastrin-dependent CgA promoter transactivation. These are not a single universal cellular response.', 'Reuse the gastrin-associated breast-cancer growth-suppression phenotype as a separate functional context. Do not transfer it to SCI repair, infer direct p65 target binding, or collapse it with the gastric CgA promoter program.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6097285_GASTRIN_CCKBR_CREB_CHGA.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000214' AND x.extraction_id='M22B-P2-R-000200');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000154', 'M22B-EVID-000123', 'M22B-P2-R-000123-R093', 'PMID:8570211; PMCID:PMC6207915; PMID:30249613; DOI:10.1124/mol.118.113399', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC6207915', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMID:8570211; PMCID:PMC6207915; PMID:30249613; DOI:10.1124/mol.118.113399; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6207915_BTC_EGFR.xml; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_MR_ESR1_EGFR_TSHR_pubmed.xml', 'Betacellulin activated EGFR and ErbB4 and produced receptor-pattern-specific cellular responses distinct from EGF or neuregulin-beta; a later primary study showed BTC biases EGFR to dimerize with ErbB3, with receptor-complex-specific signaling and growth consequences. The ERK-ELK1-EGR1 promoter record remains an EGF comparator.', 'The primary records support BTC activation of EGFR/ErbB4 and a receptor-pattern-specific EGFR-ErbB3 program, but do not establish BTC-specific ERK-ELK1 occupancy or a direct EGR1 promoter edge; EGF-derived ELK1 evidence is not transferred, and SCI relevance remains unresolved.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6207915_BTC_EGFR.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000123' AND x.extraction_id='M22B-P2-R-000123-R093');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000167', 'M22B-EVID-000105', 'M22B-P2-R-000105-R093', 'PMCID:PMC6366152; PMID:19605792; DOI:10.1095/biolreprod.109.077206', '19605792', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6366152', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC6366152; PMID:19605792; DOI:10.1095/biolreprod.109.077206; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6366152_ESR1_CYP19A1.xml; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_MR_ESR1_EGFR_TSHR_pubmed.xml', 'Estradiol induced the mouse hypothalamic neuronal Cyp19a1 aromatase promoter I.f through two AP-1 elements; ESR1 and JUN occupied those elements in intact cells and cell-free assays, ESR1 knockdown abolished the response, and mutation of the elements reduced promoter activation.', 'The primary study directly supports an estradiol-ESR1/JUN regulatory edge at the brain-specific Cyp19a1 promoter I.f in mouse hypothalamic neuronal models, with functional promoter dependence and ESR1/JUN occupancy; the ligand source, canonical estrogen-receptor complex details, and SCI transfer remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6366152_ESR1_CYP19A1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000105' AND x.extraction_id='M22B-P2-R-000105-R093');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_or_bioc_json', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6379767_FXR_CYP11A1_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000414', 'M22B-EVID-000011', 'M22B-P2-R-000011-R097', 'PMCID:PMC6606597; PMID:31266943; DOI:10.1038/s41467-019-10970-y', '31266943', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6606597', 'linked_unresolved', 'B', 'L1', 'reuse_validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC6606597; PMID:31266943; DOI:10.1038/s41467-019-10970-y; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6606597_ISGF3.xml', 'Reuse of the validated primary observation: basal ISG expression was associated with promoter-proximal STAT2-IRF9, whereas IFN-beta stimulation recruited canonical STAT1-STAT2-IRF9 ISGF3 to ISRE-containing genes in mouse MEFs and macrophages; chromatin, transcriptome, DNA-affinity, and perturbation assays supported the shared antiviral program.', 'The primary study supports a shared type-I interferon STAT2-IRF9-to-ISGF3-to-ISRE program, but exact target induction for IFN-lambda handoffs and the IFN-gamma GAF branch remains unresolved; no ligand-specific target assignment is inferred from the shared edge.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6606597_ISGF3.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000011' AND x.extraction_id='M22B-P2-R-000011-R097');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000414', 'M22B-EVID-000011', 'M22B-P2-R-000048', 'PMID:31266943; PMCID:PMC6606597; DOI:10.1038/s41467-019-10970-y', '31266943', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6606597', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:31266943; PMCID:PMC6606597; DOI:10.1038/s41467-019-10970-y; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC6606597.html', 'In mouse embryonic fibroblasts and bone-marrow-derived macrophages, basal ISG expression was associated with a preformed STAT2-IRF9 complex, whereas IFN-beta induced a switch to canonical ISGF3. ChIP-seq, transcriptome analysis, ISRE oligo pull-down, interaction/proximity assays, and perturbation of IRF9/STAT components supported ISGF3 association with ISRE-containing interferon-stimulated genes and IFN-induced transcription.', 'The authors conclude that a preformed STAT2-IRF9 complex controls basal ISG expression and that IFN stimulation rapidly switches promoter-associated transcription to canonical ISGF3, providing a molecular switch for interferon-induced gene transcription.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6606597_ISGF3.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000011' AND x.extraction_id='M22B-P2-R-000048');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000414', 'M22B-EVID-000011', 'M22B-P2-R-000067', 'PMID:31266943; PMCID:PMC6606597; DOI:10.1038/s41467-019-10970-y', '31266943', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6606597', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_tf_program_support', 'PMID:31266943; PMCID:PMC6606597; DOI:10.1038/s41467-019-10970-y; https://pubmed.ncbi.nlm.nih.gov/31266943/; https://pmc.ncbi.nlm.nih.gov/articles/PMC6606597/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch058_PMIDs_011_020_pubmed.xml', 'In mouse macrophages, type-I IFN and IFN-gamma switched basal STAT2-IRF9 complexes to promoter-bound ISGF3 containing STAT1, STAT2, and IRF9; integrated transcriptomic/proteomic and proximity-labeling analyses supported a shared interferon-stimulated gene program. This is complex/program evidence rather than one target-gene edge.', 'Retain the IFN -> STAT1/STAT2/IRF9 ISGF3 -> ISRE program as downstream TF-complex evidence. Keep the program-level chromatin record distinct from individual ISG target edges and do not infer every IFN-ligand receptor handoff induces the same program in SCI receiver cells.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6606597_ISGF3.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000011' AND x.extraction_id='M22B-P2-R-000067');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000414', 'M22B-EVID-000029', 'M22B-P2-R-000029', 'PMID:31266943; PMCID:PMC6606597; DOI:10.1038/s41467-019-10970-y; PMID:11440635', '31266943', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6606597', 'candidate_requires_review', NULL, 'L1', 'unresolved', 'unresolved', 'PMID:31266943; PMCID:PMC6606597; DOI:10.1038/s41467-019-10970-y; PMID:11440635', 'The stable anchors and B-layer summary identify an ISGF3/ISRE antiviral program, but no retained complete primary-paper Results/Methods/figure passage was available through the supervised CLI cache.', 'Do not assign the shared ISGF3 program to each IFN-lambda handoff or to the IFN-gamma GAF branch without ligand-specific primary evidence.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6606597_ISGF3.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000029' AND x.extraction_id='M22B-P2-R-000029');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000414', 'M22B-EVID-000029', 'M22B-P2-R-000029-R089', 'PMCID:PMC6606597; PMID:31266943; DOI:10.1038/s41467-019-10970-y', '31266943', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6606597', 'linked_unresolved', NULL, 'L1', 'reuse_validated_observation', 'REUSE_SHARED_PATHWAY_PROGRAM', 'PMCID:PMC6606597; PMID:31266943; DOI:10.1038/s41467-019-10970-y; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6606597_ISGF3.xml', 'Reuse the validated full-text ISGF3/ISRE observation for the mixed-anchor handoff. Resting cells showed promoter-associated STAT2-IRF9, while interferon stimulation recruited canonical STAT1-STAT2-IRF9 ISGF3 to ISG promoters.', 'Reuse the validated shared STAT2-IRF9-to-ISGF3-to-ISRE program, but do not assign exact target induction to every IFN-lambda handoff, the extra PMID:11440635 anchor, or the IFN-gamma GAF branch.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6606597_ISGF3.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000029' AND x.extraction_id='M22B-P2-R-000029-R089');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000415', 'M22B-EVID-000052', 'M22B-P2-R-000089', 'PMID:31266943; PMCID:PMC6606597; DOI:10.1038/s41467-019-10970-y', '31266943', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6606597', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_program_support', 'PMID:31266943; PMCID:PMC6606597; DOI:10.1038/s41467-019-10970-y; https://pubmed.ncbi.nlm.nih.gov/31266943/; https://pmc.ncbi.nlm.nih.gov/articles/PMC6606597/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch062_PMC6606597_bioc.json', 'Reuse the validated IFN/STAT2-IRF9-to-ISGF3 promoter-program observation: resting mouse macrophages used STAT2-IRF9 at ISRE-associated promoters, while IFN-beta or IFN-gamma induced complete ISGF3 containing STAT1, STAT2, and IRF9. The full-text ChIP-seq, RNA-seq, DNA-mediated precipitation, and stimulation records support a shared ISRE program, not a single IFNE- or IFNK-specific terminal gene edge.', 'Reuse the validated ISGF3/ISRE program claim for this distinct type-I-interferon handoff. Keep the complete STAT1-STAT2-IRF9 complex and the STAT2-IRF9 resting-state complex distinct from individual ligand-specific terminal TF-target edges; do not infer IFNE/IFNK-specific receptor usage or SCI receiver-cell output.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6606597_ISGF3.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000052' AND x.extraction_id='M22B-P2-R-000089');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000292', 'M22B-EVID-000097', 'M22B-P2-R-000097-R093', 'PMCID:PMC6830343; PMID:31736768; PMID:35044859; DOI:10.3389/fphys.2019.01324', '31736768', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6830343', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC6830343; PMID:31736768; DOI:10.3389/fphys.2019.01324; PMID:35044859; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6830343_MR_CYP11B2.xml; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_MR_ESR1_EGFR_TSHR_pubmed.xml', 'Mineralocorticoid-receptor signaling was associated with CYP11B2 aldosterone-synthase localization and normal repair after acute muscle injury; myofiber or myeloid NR3C2 perturbation altered repair/inflammatory phenotypes, while CYP11B2 was detected in infiltrating immune-cell compartments.', 'The primary studies support an MR/NR3C2-associated injury-repair program and CYP11B2 protein-localization association, but do not demonstrate NR3C2 occupancy at the Cyp11b2 locus or cell-autonomous regulation because MR perturbation and CYP11B2 signal are not confined to the same compartment; aldosterone-source and SCI transfer remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6830343_MR_CYP11B2.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000097' AND x.extraction_id='M22B-P2-R-000097-R093');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000293', 'M22B-EVID-000098', 'M22B-P2-B085-003', 'PMID:31736768; PMCID:PMC6830343; DOI:10.3389/fphys.2019.01324', '31736768', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6830343', 'linked_unresolved', NULL, 'L1', 'validated_fulltext', 'M22B-C-PH2-B085-003', 'Official PMC full text was reviewed; non-SCI tissue evidence remains comparator evidence and is not transferred as SCI-specific.', 'Acute barium-chloride injury of mouse tibialis anterior muscle induced CYP11B2-positive CD11b-positive immune-cell infiltration. Myofiber mineralocorticoid-receptor deletion and systemic spironolactone treatment altered injury, collagen organization, and repair phenotypes, supporting MR-dependent regulation of the injured muscle microenvironment.', 'Discussion and Results', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6830343_MR_CYP11B2.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000098' AND x.extraction_id='M22B-P2-B085-003');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000293', 'M22B-EVID-000098', 'M22B-P2-R-000127', 'PMID:31736768; PMCID:PMC6830343; DOI:10.3389/fphys.2019.01324', '31736768', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6830343', 'candidate_requires_review', NULL, 'L1', 'validated_abstract_bounded', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:31736768; PMCID:PMC6830343; DOI:10.3389/fphys.2019.01324; https://pubmed.ncbi.nlm.nih.gov/31736768/; https://pmc.ncbi.nlm.nih.gov/articles/PMC6830343/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC6830343_bioc.json', 'Reuse the validated aldosterone/MR acute muscle-injury observation for the distinct repair phenotype handoff: MR conditional deletion and antagonist treatment changed damaged-fiber stabilization, fibrosis/collagen infiltration, and myofiber growth. No direct NR3C2/Cyp11b2 target edge is assigned.', 'Reuse MR-dependent muscle-repair and fibrosis phenotype evidence for the distinct functional handoff, preserving the immune-cell CYP11B2 compartment boundary and avoiding direct target inference.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6830343_MR_CYP11B2.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000098' AND x.extraction_id='M22B-P2-R-000127');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000483', 'M22B-EVID-000443', 'M22B-P2-R-000024A', 'PMCID:PMC6972655; PMID:31306552; DOI:10.1111/febs.14998', '31306552', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6972655', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6972655; PMID:31306552; DOI:10.1111/febs.14998; https://pmc.ncbi.nlm.nih.gov/articles/PMC6972655/; https://pubmed.ncbi.nlm.nih.gov/31306552/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6972655_VDR_CYP24A1.xml; inherited lane anchor=PMID:8060315', 'In six independent patient-derived human normal colon organoid cultures analyzed in three VDR ChIP-seq experiments, 100 nanomolar calcitriol for 2 hours produced VDR-binding peaks that were coincident across all three assays at the CYP24A1 locus. The study assigned peaks to the nearest gene within 10 kb and displayed CYP24A1 as a representative VDR-bound calcitriol target; the ChIP-seq peaks were enriched for the consensus DR3 VDR motif. This is direct VDR-DNA occupancy evidence at the CYP24A1 locus, not a purified calcitriol-VDR affinity assay.', 'The authors conclude that CYP24A1 is among the direct calcitriol/VDR transcriptional targets in human normal colon organoids, based on reproducible VDR ChIP-seq binding and its overlap with the calcitriol-regulated gene set.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6972655_VDR_CYP24A1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000443' AND x.extraction_id='M22B-P2-R-000024A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000483', 'M22B-EVID-000443', 'M22B-P2-R-000024B', 'PMCID:PMC6972655; PMID:31306552; DOI:10.1111/febs.14998', '31306552', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6972655', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6972655; PMID:31306552; DOI:10.1111/febs.14998; https://pmc.ncbi.nlm.nih.gov/articles/PMC6972655/; https://pubmed.ncbi.nlm.nih.gov/31306552/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6972655_VDR_CYP24A1.xml; inherited lane anchor=PMID:8060315', 'In matched patient-derived human normal and tumor colon organoids, 100 nanomolar calcitriol for 96 hours increased CYP24A1 RNA and, in a subset of matched cultures, CYP24A1 protein. RNA-seq identified CYP24A1 among common calcitriol-regulated genes, and VDR ChIP-seq identified CYP24A1 among the 182 genes with binding sites coincident across all three ChIP-seq assays. VDR shRNA suppressed regulation of several calcitriol target genes, but the paper does not report a CYP24A1-specific loss-of-function result.', 'The authors conclude that calcitriol regulates CYP24A1 expression in human colon organoids and that the reproducible VDR-binding signal places CYP24A1 within the direct calcitriol/VDR target program, while acknowledging cell-state and species differences in the broader response.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6972655_VDR_CYP24A1.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000443' AND x.extraction_id='M22B-P2-R-000024B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000036', 'M22B-EVID-000137', 'M22B-P2-R-000137-R094', 'PMCID:PMC7044735; PMID:31915257; DOI:10.1523/JNEUROSCI.0367-19.2019; PMID:9390517; DOI:10.1016/S0896-6273(00)80395-5', '31915257', 'full_text_html', 'exact_identifier_match:DOI:10.1523/jneurosci.0367-19.2019;PMCID:PMC7044735', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC7044735; PMID:31915257; DOI:10.1523/JNEUROSCI.0367-19.2019; PMID:9390517; DOI:10.1016/S0896-6273(00)80395-5; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC7044735_BDNF_CREB.html; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_pubmed.xml', 'BDNF-TrkB signaling in primary rat cortical neurons phosphorylated CREB and induced BDNF transcripts; CREB-family perturbation reduced early induction, CREB ChIP-qPCR showed increased phosphorylated-CREB binding at rat Bdnf promoter IV after BDNF, and mutation of the promoter-IV CRE element abolished BDNF-TrkB reporter induction. The earlier neuronal study independently supports BDNF-induced CREB activation through CaMKIV- and Ras-dependent pathways.', 'The primary full text directly supports a BDNF-TrkB-CREB-to-Bdnf promoter IV edge in rat cortical neurons, with promoter occupancy, CRE-element dependence, and early transcript regulation; conservation in human reporter constructs is bounded, and source-cell BDNF, exact receptor-complex stoichiometry, and SCI transfer remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC7044735_BDNF_CREB.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000137' AND x.extraction_id='M22B-P2-R-000137-R094');
