INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_TPO_IL10_GDF10_BMP8A_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_DOI_10.1074_jbc.273.17.10496.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000019', 'M22B-EVID-000735', 'M22B-P2-R-000022C', 'PMCID:PMC17684; PMID:11087824; DOI:10.1073/pnas.240452197', '11087824', 'full_text_html', 'exact_identifier_match:DOI:10.1073/pnas.240452197;PMCID:PMC17684', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC17684; PMID:11087824; DOI:10.1073/pnas.240452197; https://pmc.ncbi.nlm.nih.gov/articles/PMC17684/; https://pubmed.ncbi.nlm.nih.gov/11087824/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC17684_GABAB_CREB2_ATFx.xml', 'In CHO-GABA-B cells, baclofen induced dose-dependent activation of a Gadd153-promoter CAT reporter with an EC50 of approximately 4 micromolar. Reporter activation was abolished by the GABA-B antagonist CGP54626 and strongly reduced by pertussis toxin or the MAPK inhibitor PD98059; it was diminished without transfected CREB2 and was not observed with a mutated CREB2-recognition site in the reporter. The study therefore supports G protein and MAPK-inhibitor-sensitive receptor signaling into a CREB2-responsive reporter, but it did not measure ERK phosphorylation directly or establish endogenous Gadd153 regulation in the receptor model.', 'The authors conclude that GABA-B receptor stimulation activates CREB2-dependent transcription through G protein and MAPK signaling mechanisms, using the Gadd153 promoter-CAT construct as a responsive reporter. They describe Gadd153 as a candidate target but explicitly state that a role for GABA-B receptors in endogenous Gadd153 stress responses was not established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_PMC17684_GABAB_CREB2.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000735' AND x.extraction_id='M22B-P2-R-000022C');
