INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E001537', 'M22B-EVID-000744', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_PMC17684_GABAB_CREB2.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000744' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000017', 'M22B-EVID-000774', 'M22B-P2-R-000022A', 'PMCID:PMC17684; PMID:11087824; DOI:10.1073/pnas.240452197', '11087824', 'full_text_html', 'exact_identifier_match:DOI:10.1073/pnas.240452197;PMCID:PMC17684', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC17684; PMID:11087824; DOI:10.1073/pnas.240452197; https://pmc.ncbi.nlm.nih.gov/articles/PMC17684/; https://pubmed.ncbi.nlm.nih.gov/11087824/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC17684_GABAB_CREB2_ATFx.xml', 'The primary study identified CREB2/ATF4 and ATFx as interactors of the C-terminal regions of both GABA-B-R1 and GABA-B-R2 in a yeast two-hybrid assay. Domain mapping localized the strongest R1 association to the receptor coiled-coil region and the CREB2/ATFx bZIP domains. Myc-GABA-B-R1b and FLAG-CREB2 coimmunoprecipitated in HEK293T cells, and endogenous GABA-B-R1 immunoprecipitated with CREB2 from rat-brain membrane homogenate. Full-length GABA-B-R2 did not coimmunoprecipitate with CREB2, so the R2 interaction remains domain-level and conformation-limited rather than validated as a full-length mammalian complex.', 'The authors conclude that CREB2 and ATFx associate with GABA-B receptor C-terminal tails, with the experimentally verified mammalian association centered on GABA-B-R1 and CREB2. They explicitly leave the full-length GABA-B-R2 association uncertain because the YTH interaction was not reproduced by mammalian coimmunoprecipitation.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_PMC17684_GABAB_CREB2.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000774' AND x.extraction_id='M22B-P2-R-000022A');
