INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_PMC3352154_EGF_EGR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000157', 'M22B-EVID-000121', 'M22B-P2-R-000121-R093', 'PMID:7929459; PMID:8049525; PMID:22593802', NULL, 'literature_xml', 'exact_identifier_match:PMID:22593802', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMID:7929459; PMID:8049525; PMID:22593802; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_MR_ESR1_EGFR_TSHR_pubmed.xml', 'Amphiregulin bound and activated EGFR, with heparan sulfate required for EGFR autophosphorylation and AREG-induced mitogenesis; a separate prostate-cancer study supported EGFR-dependent AREG expression/autocrine feedback. An EGF comparator study, not an AREG study, showed ERK-dependent ELK1 occupancy at the EGR1 promoter.', 'The primary records support AREG-EGFR activation and mitogenic/autocrine pathway context, while the direct ERK-ELK1-EGR1 promoter evidence is ligand-specific to EGF and must not be transferred to AREG; no AREG-specific ELK1 occupancy or direct target was established.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_pubmed_22593802_9553109_21474450_11087824.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000121' AND x.extraction_id='M22B-P2-R-000121-R093');
