INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000154', 'M22B-EVID-000123', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_pubmed_22593802_9553109_21474450_11087824.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000123' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000158', 'M22B-EVID-000622', 'M22B-P2-R-000017A', 'PMCID:PMC3352154; PMID:22593802; DOI:10.1177/1947601911431885', '22593802', 'literature_xml', 'exact_identifier_match:PMID:22593802', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3352154; PMID:22593802; DOI:10.1177/1947601911431885; https://pmc.ncbi.nlm.nih.gov/articles/PMC3352154/; https://pubmed.ncbi.nlm.nih.gov/22593802/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3352154_EGF_ELK1_EGR1.xml', 'In human LNCaP and PC3 prostate-cancer cells, EGF induced EGR1 transcription in a dose- and time-dependent manner. MEK/ERK inhibition with PD98059 attenuated the EGF response by approximately 98% in LNCaP cells and 88% in PC3 cells; EGF induced EGFR and ERK phosphorylation, while the inhibitor suppressed ERK phosphorylation. EGR1-promoter deletion mapping localized the principal EGF-responsive region to -771 to -245 bp containing proximal serum-response elements.', 'The authors conclude that EGF regulates EGR1 transcription through an ERK-dependent pathway and that the proximal EGR1 promoter SRE region is required for the EGF response.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_pubmed_22593802_9553109_21474450_11087824.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000622' AND x.extraction_id='M22B-P2-R-000017A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000158', 'M22B-EVID-000622', 'M22B-P2-R-000017B', 'PMCID:PMC3352154; PMID:22593802; DOI:10.1177/1947601911431885', '22593802', 'literature_xml', 'exact_identifier_match:PMID:22593802', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3352154; PMID:22593802; DOI:10.1177/1947601911431885; https://pmc.ncbi.nlm.nih.gov/articles/PMC3352154/; https://pubmed.ncbi.nlm.nih.gov/22593802/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3352154_EGF_ELK1_EGR1.xml', 'In PC3 cells, EGF enhanced ELK1 occupancy at the proximal EGR1 promoter SRE cluster approximately sixfold over control by in-vivo ChIP at the -603 to -315 bp region containing four predicted ELK1/SRF sites. ELK1 overexpression increased activity of the -771 EGR1 promoter construct, whereas the ELK1 DNA-binding-domain deletion reduced activation and dominant-negative Elk-En suppressed EGF-mediated promoter activity by more than 76%. The result is direct ELK1-to-EGR1 promoter evidence in this model, not a generic ERK-to-all-TF or direct EGF-receptor binding claim.', 'The authors conclude that ELK1 is recruited to the EGF-responsive EGR1 promoter region and is necessary and sufficient for EGF-mediated EGR1 promoter activation in PC3 cells.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_pubmed_22593802_9553109_21474450_11087824.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000622' AND x.extraction_id='M22B-P2-R-000017B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000158', 'M22B-EVID-000622', 'M22B-P2-R-000340', 'PMCID:PMC3352154; PMID:22593802; DOI:10.1177/1947601911431885', '22593802', 'literature_xml', 'exact_identifier_match:PMID:22593802', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC3352154; local full text retry_B22B_batch041_PMC3352154_EGF_EGR1.html', 'EGF induced EGR1 transcription in LNCaP and PC3 prostate cancer cells; MEK inhibition with PD98059 attenuated the response. In PC3 cells, EGF enhanced Elk-1 occupancy at the proximal EGR1 promoter SRE region (-603 to -315 bp; approximately sixfold over control), and Elk-1 overexpression activated while dominant-negative Elk-1 suppressed the EGR1 promoter.', 'EGF-EGFR-ERK signaling directly supports Elk-1 occupancy and Elk-1-dependent activation of the human EGR1 promoter in PC3 cells; the LNCaP branch is not equivalent because EGF did not enhance Elk-1 occupancy there and another TCF factor may contribute.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_pubmed_22593802_9553109_21474450_11087824.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000622' AND x.extraction_id='M22B-P2-R-000340');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000159', 'M22B-EVID-000623', 'M22B-P2-R-000021A', 'PMID:9553109; DOI:10.1074/jbc.273.17.10496', '9553109', 'literature_xml', 'exact_identifier_match:PMID:9553109', 'candidate_requires_review', NULL, 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:9553109; DOI:10.1074/jbc.273.17.10496; https://pubmed.ncbi.nlm.nih.gov/9553109/; https://doi.org/10.1074/jbc.273.17.10496; local PubMed full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMID9553109_EREG_pubmed.xml', 'The primary abstract reports that epiregulin is a broad ErbB ligand: it stimulated ErbB1 and ErbB4 homodimers and all possible heterodimeric ErbB complexes in factor-dependent cell lines engineered to express individual receptors or receptor combinations. Epiregulin bound receptor combinations with approximately 100-fold lower affinity than more selective ligands such as EGF but produced stronger mitogenic signals for most combinations through weak, prolonged receptor activation. This source supports EREG receptor-complex context, but the abstract contains no ERK, ELK1, EGR1, or named terminal-TF assay matching the queued program edge.', 'Leave the exact EREG-to-ERK/ELK1 immediate-early program unknown until the primary full text or a separate EREG-specific pathway paper with section-level assay details is recovered. Do not substitute the EGF–ELK1–EGR1 promoter paper or infer ELK1 occupancy from broad ErbB activation.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_pubmed_22593802_9553109_21474450_11087824.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000623' AND x.extraction_id='M22B-P2-R-000021A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000824', 'M22B-EVID-000628', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch041_pubmed_22593802_9553109_21474450_11087824.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000628' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000830', 'M22B-P2-R-000023A', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468', '26020477', 'full_text_html', 'exact_identifier_match:DOI:10.1038/srep10468;PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; https://pmc.ncbi.nlm.nih.gov/articles/PMC4447080/; https://pubmed.ncbi.nlm.nih.gov/26020477/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml', 'In primary mouse cerebellar granule neurons, baclofen increased Fmrp protein and Fmr1 mRNA in a dose- and time-dependent manner; CGP7930, a GABA-B positive allosteric modulator with agonist activity in this system, produced a similar FMRP-expression response. In recombinant MEFs co-transfected with GABA-B1 and GABA-B2, CREB depletion abolished the baclofen-induced increase in FMRP. The result supports GABA-B-to-CREB-dependent Fmr1/FMRP regulation, but does not establish CREB binding at the endogenous Fmr1 regulatory region.', 'The authors conclude that GABA-B receptor activation increases Fmr1/FMRP expression through CREB-dependent signaling in the tested neuronal and recombinant-cell models. This is an indirect receptor-to-regulatory-output record, not a direct CREB-to-Fmr1 promoter edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch042_PMC4447080_GABAB_FMRP.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000830' AND x.extraction_id='M22B-P2-R-000023A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000830', 'M22B-P2-R-000346', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; PMID:17582742; DOI:10.1016/j.cellsig.2007.05.004', '26020477', 'full_text_html', 'exact_identifier_match:DOI:10.1038/srep10468;PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; local full text retry_B22B_batch042_PMC4447080_GABAB_FMRP.html; local PubMed retry_B22B_batch042_pubmed_11312600_26020477_17582742.xml', 'In cultured mouse cerebellar granule neurons, baclofen and the GABA-B positive allosteric modulator CGP7930 increased Fmr1 mRNA and FMRP protein and induced transient CREB phosphorylation. CREB siRNA blocked baclofen-induced FMRP upregulation in GABA-B1/GABA-B2-expressing MEFs. Perturbation of Gi/o, PLC-beta, FAK, IGF-1R, and PKC bounded parallel GABA-B-to-CREB relays, but no CREB occupancy assay at the Fmr1 regulatory region was reported.', 'GABA-B receptor activation supports a CREB-dependent Fmr1/FMRP expression program through parallel IGF-1R transactivation/ERK-Akt and PKC branches, but the primary study does not demonstrate CREB binding at the Fmr1 regulatory region; retain this as pathway/function evidence rather than a direct TF-target edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch042_PMC4447080_GABAB_FMRP.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000830' AND x.extraction_id='M22B-P2-R-000346');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000831', 'M22B-P2-R-000023B', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468', '26020477', 'full_text_html', 'exact_identifier_match:DOI:10.1038/srep10468;PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; https://pmc.ncbi.nlm.nih.gov/articles/PMC4447080/; https://pubmed.ncbi.nlm.nih.gov/26020477/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml', 'In primary mouse cerebellar granule neurons, baclofen and CGP7930 caused concentration-dependent, transient CREB phosphorylation that peaked at approximately 10 minutes and returned toward baseline by 60 minutes; the baclofen response was blocked by the competitive GABA-B antagonist CGP54626. CREB siRNA in GABA-B1/GABA-B2-expressing MEFs eliminated the baclofen-induced FMRP increase, linking the measured CREB activation state to the downstream FMRP output without demonstrating CREB occupancy at Fmr1 chromatin.', 'The authors conclude that GABA-B receptor activation produces a transient CREB phosphorylation response that is required for the observed FMRP upregulation in the tested models.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch042_PMC4447080_GABAB_FMRP.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000831' AND x.extraction_id='M22B-P2-R-000023B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000832', 'M22B-P2-R-000023C', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468', '26020477', 'full_text_html', 'exact_identifier_match:DOI:10.1038/srep10468;PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; https://pmc.ncbi.nlm.nih.gov/articles/PMC4447080/; https://pubmed.ncbi.nlm.nih.gov/26020477/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml', 'In primary mouse cerebellar granule neurons, baclofen-induced phosphorylation of ERK1/2, Akt, and CREB was reduced by pertussis toxin, the PLC-beta inhibitor U73122, the FAK inhibitor PF573228, or the IGF-1R inhibitor AG1024. In recombinant GABA-B1/GABA-B2-expressing MEFs, IGF-1R siRNA or shRNA reduced baclofen-induced ERK1/2, Akt, and CREB phosphorylation. These perturbations support a G protein/PLC-beta/FAK-dependent IGF-1R transactivation branch feeding into ERK-Akt-CREB, without showing direct GABA-B/IGF-1R binding.', 'The authors conclude that GABA-B receptor-mediated G protein/PLC-beta/FAK signaling transactivates IGF-1R and thereby contributes to ERK1/2, Akt, and CREB phosphorylation. The study supports a receptor-proximal/pathway branch, not a purified receptor-IGF-1R molecular interaction.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch042_PMC4447080_GABAB_FMRP.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000832' AND x.extraction_id='M22B-P2-R-000023C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000049', 'M22B-EVID-000833', 'M22B-P2-R-000023D', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468', '26020477', 'full_text_html', 'exact_identifier_match:DOI:10.1038/srep10468;PMCID:PMC4447080', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4447080; PMID:26020477; DOI:10.1038/srep10468; https://pmc.ncbi.nlm.nih.gov/articles/PMC4447080/; https://pubmed.ncbi.nlm.nih.gov/26020477/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4447080_GABAB_FMRP_CREB.xml', 'In primary mouse cerebellar granule neurons, broad PKC inhibitors reduced baclofen-induced CREB phosphorylation while leaving ERK1/2 and Akt phosphorylation largely unchanged; siRNA against PKC-alpha or PKC-beta in GABA-B1/GABA-B2-expressing MEFs reduced baclofen-induced CREB phosphorylation without reducing IGF-1R transactivation or ERK1/2/Akt phosphorylation. PKC inhibition also reduced baclofen-induced FMRP expression. The findings support a PKC-dependent CREB branch that is at least partly independent of the IGF-1R/ERK-Akt branch.', 'The authors conclude that calcium-sensitive PKC-alpha/beta signaling is required for GABA-B receptor-induced CREB activation and contributes to FMRP upregulation independently of IGF-1R transactivation and ERK1/2-Akt phosphorylation.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch042_PMC4447080_GABAB_FMRP.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000833' AND x.extraction_id='M22B-P2-R-000023D');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000127', 'M22B-EVID-000834', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch042_PMC4447080_GABAB_FMRP.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000834' AND x.extraction_id='');
