INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000133', 'M22B-EVID-000943', 'M22B-P2-R-000348', 'PMCID:PMC2840317; PMID:20133702; DOI:10.1073/pnas.0914897107', '20133702', 'full_text_html', 'exact_identifier_match:DOI:10.1073/pnas.0914897107;PMCID:PMC2840317', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC2840317; local full text retry_B22B_batch043_PMC2840317_CRTC2_glucagon.html', 'Targeted disruption of the CREB coactivator Crtc2 altered fasting and feeding responses, hepatic glucose production, insulin sensitivity, and expression of fasting-responsive metabolic genes in mice. The study supports CRTC2 as a glucagon/cAMP-linked coactivator in hepatic transcription but does not define one GCGR-selective terminal TF locus for this handoff.', 'CRTC2 is required for a glucagon/fasting-linked hepatic transcriptional and metabolic program, but this record does not establish a unique GCGR-to-CREB/CRTC2 direct TF-target locus.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch043_PMC2840317_CRTC2_glucagon.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000943' AND x.extraction_id='M22B-P2-R-000348');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000344', 'M22B-EVID-000018', 'M22B-P2-R-000018-R097', 'PMCID:PMC3423339; PMID:22622516; DOI:10.1007/s10456-012-9277-x', '22622516', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s10456-012-9277-x;PMCID:PMC3423339', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC3423339; PMID:22622516; DOI:10.1007/s10456-012-9277-x; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3423339_BMP9_EphrinB2.xml; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch097_pubmed.xml', 'BMP9 induced EphrinB2 in endothelial cells through an ALK1-ACVRL1 and BMPRII/ActRII coreceptor context, with ID1 and ID3 required for full induction; Alk1 or EphrinB2 loss altered sprouting and arterial-venous anastomosis, while BMP9 blocked endothelial sprouting.', 'The primary study supports a BMP9-ALK1-BMPRII/ActRII-ID1/ID3 endothelial pathway and sprouting phenotype, but does not establish direct ID1/ID3 occupancy at the EphrinB2 locus, distinguish BMPRII from ActRII in every assay, or transfer the vascular result to SCI endothelium.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch043_PMC3423339_BMP9_EphrinB2.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000018' AND x.extraction_id='M22B-P2-R-000018-R097');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch043_PMC3798379_GCGR_NEDD4L.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000385', 'M22B-EVID-000047', 'M22B-P2-R-000047-R089', 'PMCID:PMC4067217; PMID:24798330; DOI:10.1074/jbc.M114.550301', '24798330', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m114.550301;PMCID:PMC4067217', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC4067217; PMID:24798330; DOI:10.1074/jbc.M114.550301; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4067217_program.xml', 'Purified Nodal-Gdf1 heterodimers with bound prodomains produced stronger CAGA-luc Activin-pathway output than Nodal alone; Cryptic/Cripto context, Acvr2a/Acvr2b inhibition or depletion, receptor-Fc pulldown, and improved human ES-cell endoderm marker induction supported a receptor-complex and functional program.', 'The primary study supports a Nodal-Gdf1-CFC/Activin-receptor-Smad2/3-associated pathway and endoderm output, while showing that Gdf1 potentiation does not simply increase receptor affinity. It does not establish direct Smad2/3 promoter occupancy, exact receptor stoichiometry for every context, or SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch043_PMC4067217_Nodal_GDF1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000047' AND x.extraction_id='M22B-P2-R-000047-R089');
