INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000096', 'M22B-EVID-000942', 'M22B-P2-R-000347', 'PMCID:PMC3798379; PMID:24147136; DOI:10.1371/journal.pone.0078522', '24147136', 'literature_xml', 'exact_identifier_match:PMID:24147136', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC3798379; local full text retry_B22B_batch043_PMC3798379_GCGR_NEDD4L.html', 'Glucagon induced the mouse Nedd4l-short transcript and protein in primary hepatocytes and fasting liver. The alternate Nedd4l-short promoter contained a functional CRE2 site; mutation reduced cAMP-stimulated reporter activity, dominant-negative CREB blocked induction, and CREB ChIP recovered the endogenous Nedd4l locus near CRE2. CRTC2 contributed to glucagon-stimulated expression.', 'Glucagon-cAMP/PKA-CREB/CRTC2 signaling directly supports CREB occupancy and transcriptional regulation of the mouse Nedd4l-short promoter at the CRE2 region; the exact GCGR requirement was not independently silenced in this Nedd4l study.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch043_pubmed_24147136_20133702_34896391_24798330_18309101_22622516_8702914.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000942' AND x.extraction_id='M22B-P2-R-000347');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000359', 'M22B-EVID-000956', 'M22B-P2-R-000353', 'DOI:10.1111/febs.12256; DOI:10.1177/2041731420919334; PMCID:PMC7238299; PMID:23527555; PMID:32489577', NULL, 'literature_xml', 'exact_identifier_match:PMID:23527555;PMID:32489577', 'candidate_requires_review', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'DOI:10.1111/febs.12256; DOI:10.1177/2041731420919334; PMCID:PMC7238299; PMID:23527555; PMID:32489577; local PubMed retry_B22B_batch044_pubmed_23527555_32489577_16049014_27156839_22457515_25201974.xml', 'GDF6 activated BMPR1A/ALK3-family and BMPR2 or ACVR2A/ActRIIA receptor contexts and induced SMAD1/5/8-dependent mesenchymal differentiation programs. Primary studies included adipogenic commitment in C3H10T1/2 cells, human adipose-derived stem-cell nucleus-pulposus-like differentiation, and receptor/pathway comparisons; Smad4 and p38 perturbations bounded the pathway, but no direct SMAD occupancy at an endogenous target locus was shown.', 'GDF6-BMPR1A/ACVR2A or BMPR2 signaling supports a SMAD1/5/8-linked mesenchymal anabolic/adipogenic differentiation program, but no direct SMAD-DNA target edge is established and the exact receptor branch varies by model.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch044_pubmed_23527555_32489577_16049014_27156839_22457515_25201974.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000956' AND x.extraction_id='M22B-P2-R-000353');
