INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000042', 'M22B-EVID-000992', 'M22B-P2-R-000359', 'PMCID:PMC3745357; PMID:17234586; PMCID:PMC2804479; PMID:19812345', '19812345', 'full_text_html', 'exact_identifier_match:PMCID:PMC2804479', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC2804479; PMID:19812345; PMCID:PMC3745357; PMID:17234586; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch045_PMC2804479_aspartate_NMDAR_CREB.html; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch045_pubmed_17234586_19812345.xml', 'In mouse cortical cultures, dopamine/cAMP-driven CREB-dependent transcription required an aspartate-mediated autocrine signal and was sensitive to NR2B/NMDAR blockade; the paired NMDAR subtype study links GluN2B signaling to CREB and Bdnf regulation. CRE-luciferase, Bdnf/c-fos expression, and pharmacologic scavenging/blockade support a functional relay, not CREB occupancy at an endogenous target.', 'An aspartate-to-NR2B/NMDAR-to-CREB transcriptional relay is supported in developing cortical neurons, with Bdnf/c-fos as functional outputs; no direct CREB binding at either locus or exact submitted source-receptor coupling is established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch045_PMC2804479_aspartate_NMDAR_CREB.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000992' AND x.extraction_id='M22B-P2-R-000359');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000132', 'M22B-EVID-001018', 'M22B-P2-R-000375', 'PMCID:PMC2804479; PMID:19812345', '19812345', 'full_text_html', 'exact_identifier_match:PMCID:PMC2804479', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC2804479; PMID:19812345; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch045_PMC2804479_aspartate_NMDAR_CREB.html', 'Dopamine/cAMP stimulation of developing mouse cortical cultures induced CREB-dependent transcription through an aspartate-mediated autocrine signal and NR2B-sensitive NMDAR activation; CRE reporter and Bdnf/c-fos outputs were measured. No CREB occupancy at an endogenous locus was shown.', 'An aspartate-to-NR2B/NMDAR-to-CREB transcriptional relay supports Bdnf/c-fos functional output in developing cortical neurons, but does not establish direct CREB occupancy or the exact submitted source-receptor composite.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch045_PMC2804479_aspartate_NMDAR_CREB.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-001018' AND x.extraction_id='M22B-P2-R-000375');
