INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000041', 'M22B-EVID-000991', 'M22B-P2-R-000358', 'PMCID:PMC3745357; PMID:17234586', '17234586', 'full_text_html', 'exact_identifier_match:PMCID:PMC3745357', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC3745357; PMID:17234586; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch045_PMC3745357_NMDAR_GluN2A_GluN2B.html; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch045_pubmed_17234586_19812345.xml', 'In cultured rodent cortical neurons, NMDA stimulation engaged GluN2A- and GluN2B-containing NMDAR contributions to CREB phosphorylation and Bdnf expression; subtype-selective inhibition and genetic perturbation supported the receptor-subtype dependence. The study did not measure CREB occupancy at Bdnf.', 'GluN2A/GluN2B-containing NMDAR signaling can engage CREB-linked Bdnf transcription in cortical neurons, but the evidence is pathway/function-level and does not establish direct CREB-DNA binding or the exact queued glutamate-source composite.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch045_PMC3745357_NMDAR_GluN2A_GluN2B.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000991' AND x.extraction_id='M22B-P2-R-000358');
