INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000416', 'M22B-EVID-000005', 'M22B-P2-R-000005', 'PMID:17994025; DOI:10.1038/ni1537', '17994025', 'literature_xml', 'exact_identifier_match:PMID:17994025', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:17994025; DOI:10.1038/ni1537; local cache=data/raw/evidence/module20_24_supervised_cli_phase2/M22B_batch001_pubmed.xml', 'The retained PubMed abstract reports that IL-27 and IL-6 induced IL-10 production in mouse T-cell subsets, with STAT1 and STAT3 required for IL-27 responses and STAT3 required for IL-6 responses. The abstract does not provide an atomic figure/section passage for import.', 'The abstract supports an IL-27/IL-6-to-STAT1/STAT3-to-IL-10 pathway lead, but exact author interpretation and figure-level evidence require complete primary text.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch049_pubmed_17994025_28878115_20456019_12296825_19926752.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000005' AND x.extraction_id='M22B-P2-R-000005');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000416', 'M22B-EVID-000005', 'M22B-P2-R-000005-R095', 'PMID:17994025; DOI:10.1038/ni1537', '17994025', 'literature_xml', 'exact_identifier_match:PMID:17994025', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMID:17994025; DOI:10.1038/ni1537; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_pubmed.xml', 'IL-27 and IL-6 induced IL-10 production in differentiated T-helper cells; IL-27 depended on STAT1 and STAT3, while IL-6 depended on STAT3.', 'The primary record supports an IL-27/IL-6-to-STAT1/STAT3 pathway associated with adaptive IL-10 production, but does not establish direct STAT1/STAT3 occupancy at the Il10 locus, a single submitted receptor-complex branch, or SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch049_pubmed_17994025_28878115_20456019_12296825_19926752.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000005' AND x.extraction_id='M22B-P2-R-000005-R095');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000416', 'M22B-EVID-000005', 'M22B-P2-R-000061', 'PMID:17994025; DOI:10.1038/ni1537', '17994025', 'literature_xml', 'exact_identifier_match:PMID:17994025', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_context', 'PMID:17994025; DOI:10.1038/ni1537; https://pubmed.ncbi.nlm.nih.gov/17994025/; https://doi.org/10.1038/ni1537; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch057_PMIDs_001_010_pubmed.xml', 'IL-27 induced IL-10 production in mouse T-cell subsets through STAT1 and STAT3, while IL-6 induced IL-10 through STAT3. The study supports cytokine-dependent regulatory function but does not establish direct STAT1/STAT3 occupancy at the Il10 regulatory sequence.', 'Retain IL-27/IL-6 -> STAT1/STAT3-dependent Il10 production as T-cell comparator function evidence. Do not promote direct STAT1/STAT3-Il10 promoter binding or infer that all IL-27/IL-6 receptor handoffs produce this output in SCI cells.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch049_pubmed_17994025_28878115_20456019_12296825_19926752.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000005' AND x.extraction_id='M22B-P2-R-000061');
