INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000416', 'M22B-EVID-000031', 'M22B-P2-R-000391', 'PMID:17994025; DOI:10.1038/ni1537', '17994025', 'literature_xml', 'exact_identifier_match:PMID:17994025', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMID:17994025; DOI:10.1038/ni1537; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch049_pubmed_17994025_28878115_20456019_12296825_19926752.xml', 'IL-27 induced IL-10 secretion from Th1, Th2, and Th17 cells through STAT1/STAT3-dependent signaling, while IL-6 induced IL-10 through STAT3 dependence. The study did not establish direct STAT1/STAT3 binding at the Il10 regulatory locus.', 'IL-27 and IL-6 can induce T-cell IL-10 through STAT-dependent pathways, with IL-27 requiring STAT1/STAT3 and IL-6 requiring STAT3; direct TF occupancy at Il10 remains unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch049_pubmed_17994025_28878115_20456019_12296825_19926752.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000031' AND x.extraction_id='M22B-P2-R-000391');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000442', 'M22B-EVID-000034', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch049_pubmed_17994025_28878115_20456019_12296825_19926752.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000034' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000372', 'M22B-EVID-000092', 'M22B-P2-R-000092-R092', 'PMCID:PMC10409762; PMID:37553521; PMID:15883158; DOI:10.1074/jbc.M502825200', '37553521', 'full_text_html', 'exact_identifier_match:DOI:10.1038/s42003-023-05194-2;PMCID:PMC10409762', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC10409762; PMID:37553521; PMID:15883158; DOI:10.1038/s42003-023-05194-2; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC10409762_BMP8A.xml; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_TPO_IL10_GDF10_BMP8A_pubmed.xml', 'Bmp8a loss caused obesity, fatty liver, and altered lipid metabolism in zebrafish, while Bmp8a overexpression in mouse 3T3-L1 cells increased pSMAD1/5/8 and pSMAD2/3. Inhibition experiments indicated that the anti-adipogenic effect was primarily dependent on SMAD2/3, with SMAD2/3 binding to the PPARgamma promoter and NF-kB/PPARgamma effects on Fabp4.', 'The primary study supports a Bmp8a-associated adipocyte/lipid program with pSMAD1/5/8 and pSMAD2/3 readouts, but its dominant anti-adipogenic mechanism is SMAD2/3-to-PPARgamma rather than an isolated SMAD1/5/8 or SMAD9 branch; submitted receptor-complex composition and SCI transfer remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch050_PMC10409762_BMP8A_SMAD2_3_ALK4_PPARgamma.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000092' AND x.extraction_id='M22B-P2-R-000092-R092');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000371', 'M22B-EVID-000093', 'M22B-P2-R-000123', 'PMID:37553521; PMCID:PMC10409762; DOI:10.1038/s42003-023-05194-2', '37553521', 'full_text_html', 'exact_identifier_match:DOI:10.1038/s42003-023-05194-2;PMCID:PMC10409762', 'candidate_requires_review', NULL, 'L1', 'validated_abstract_bounded', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:37553521; PMCID:PMC10409762; DOI:10.1038/s42003-023-05194-2; https://pubmed.ncbi.nlm.nih.gov/37553521/; https://pmc.ncbi.nlm.nih.gov/articles/PMC10409762/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC10409762_bioc.json', 'Reuse the BMP8A adipocyte/lipid-metabolism observation for the distinct phenotype handoff: Bmp8a loss increased zebrafish obesity/fatty liver and Bmp8a overexpression inhibited 3T3-L1 adipocyte differentiation. The phenotype is not evidence for direct SMAD1/5/9 target binding.', 'Reuse the BMP8A-associated lipid metabolism and adipocyte differentiation phenotype while keeping the dominant SMAD2/3 mechanism and receptor uncertainty explicit. Do not infer a terminal SMAD1/5/9 target or SCI relevance.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch050_PMC10409762_BMP8A_SMAD2_3_ALK4_PPARgamma.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000093' AND x.extraction_id='M22B-P2-R-000123');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000373', 'M22B-EVID-000094', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch050_PMC10409762_BMP8A_SMAD2_3_ALK4_PPARgamma.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000094' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000382', 'M22B-EVID-000422', 'M22B-P2-R-000396', 'PMCID:PMC10409762; PMID:31940275', '31940275', 'full_text_html', 'exact_identifier_match:PMCID:PMC10409762', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC10409762; PMID:31940275; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch050_PMC10409762_BMP8A_SMAD2_3_ALK4_PPARgamma.html', 'Bmp8a overexpression increased Smad2/3 phosphorylation and CAGA reporter activity in 3T3-L1 preadipocytes, while the Smad2/3 inhibitor TP0427736 blocked the anti-adipogenic phenotype. Receptor-expression, dominant-negative receptor, and reporter experiments supported an ALK4-centered type-I context with ACVR2A, ACVR2B, or TGFBR2-compatible type-II contexts; PPARgamma promoter reporter and predicted-site deletion linked the pathway to PPARgamma repression. No ChIP or direct Smad2/3 occupancy assay was shown.', 'BMP8A activates an ALK4-centered SMAD2/3 pathway that suppresses adipocyte differentiation and represses PPARgamma promoter activity in the tested models, but the paper provides reporter/deletion and pathway evidence rather than direct SMAD2/3 occupancy; exact BMPR1A/ACVR2B or BMPR1B/ACVR2B handoff specificity and SCI transfer remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch050_PMC10409762_BMP8A_SMAD2_3_ALK4_PPARgamma.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000422' AND x.extraction_id='M22B-P2-R-000396');
