INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E002538', 'M20B-EVID-002538-P2-FUNC', 'M20B-P2-R-002245-FUNC', 'PMID:20726988; PMCID:PMC2990937; DOI:10.1111/j.1365-2249.2010.04235.x', '20726988', 'full_text_html', 'exact_identifier_match:DOI:10.1111/j.1365-2249.2010.04235.x;PMCID:PMC2990937', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_downstream_functional_support', 'PMID:20726988; PMCID:PMC2990937; DOI:10.1111/j.1365-2249.2010.04235.x; https://pmc.ncbi.nlm.nih.gov/articles/PMC2990937/', 'In human peripheral-blood mononuclear cells, plate-bound ALCAM-Fc with anti-CD3 produced synergistic proliferation, increased CD25 expression and a distinct activation transcription profile, and in the presence of IL-2 increased IFN-gamma, IL-6, and TNF-alpha output. A CD6 membrane-distal antibody reduced phospho-MAPK, phospho-STAT3, phospho-AKT, proliferation, CD25, and cytokine output without blocking the ALCAM-binding site.', 'Promote ALCAM–CD6-associated T-cell co-stimulation and inflammatory/Th1-like output under CD3 and IL-2 co-stimulation. Keep the proliferation, CD25, cytokine, and phosphoprotein results as downstream functional evidence; no terminal TF occupancy or SCI-cell phenotype is established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch055_PMC2990937_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-002538-P2-FUNC' AND x.extraction_id='M20B-P2-R-002245-FUNC');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000002', 'M22B-EVID-002674', 'M22B-P2-R-000557', 'PMCID:PMC2990937', '20726988', 'full_text_html', 'exact_identifier_match:PMCID:PMC2990937', 'candidate_requires_review', NULL, 'L1', 'validated_observation', 'NO_TERMINAL_TF_EVIDENCE', 'PMCID:PMC2990937; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch055_PMC2990937_full.html', 'ALCAM-CD6 binding/adhesion was validated in the full-text primary source; alternate PMID anchors 7760007 and 8823162 map to the same evidence family. Evidence was extracted at the tested model and assay scope; no stronger direct interaction or TF occupancy is inferred.', 'The reconciled ALCAM-CD6 molecular/adhesion evidence does not establish a downstream TF edge.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch055_PMC2990937_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002674' AND x.extraction_id='M22B-P2-R-000557');
