INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'metadata_or_search_json', 'not_attempted', 'metadata_or_search_only', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact. Its role is metadata/search/manifest output and it is not treated as direct biological evidence.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch062_doi_esearch.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch062_doi_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch062_pubmed_B019_pmids.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000457', 'M22B-EVID-000072', 'M22B-P2-B090-002', 'PMID:9343435; PMCID:PMC232525; DOI:10.1128/MCB.17.11.6708', '9343435', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC232525', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_fulltext', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC232525/; https://pubmed.ncbi.nlm.nih.gov/9343435/', 'In mammary epithelial comparator systems, prolactin activated STAT5 and the beta-casein promoter response required the Stat5 response element; STAT5 tyrosine phosphorylation at Y694 was required for transcription. Promoter/reporter and DNA-binding experiments showed that the Stat5 response element was sufficient for the cooperative Stat5/glucocorticoid-receptor transcriptional response, while glucocorticoid-receptor DNA binding was not required for cooperation.', 'The authors conclude that specific DNA binding of STAT5, but not glucocorticoid receptor DNA binding, is required for their functional cooperation at the beta-casein promoter. Retain this as direct STAT5A/B-to-Csn2 promoter evidence in a mammary comparator; do not assign the result to SCI or to a unique receptor branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch063_PMC232525_176708.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000072' AND x.extraction_id='M22B-P2-B090-002');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000457', 'M22B-EVID-000072', 'M22B-P2-R-RECOVERY-STAT5-CSN2-000001', 'PMID:9343435; PMCID:PMC232525; DOI:10.1128/MCB.17.11.6708', '9343435', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC232525', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_tf_target_support_abstract_bounded', 'PMID:9343435; PMCID:PMC232525; DOI:10.1128/MCB.17.11.6708; https://pubmed.ncbi.nlm.nih.gov/9343435/; https://pmc.ncbi.nlm.nih.gov/articles/PMC232525/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch063_PMC232525_STAT5_Csn2.html', 'The primary-paper abstract reports that activated Stat5 binds sequence elements in milk-protein promoters and that the Stat5 response element within the beta-casein gene promoter is sufficient for cooperative transcription with the glucocorticoid receptor; Stat5 Tyr694 phosphorylation is required. The abstract also reports that Stat5 transactivation-domain deletion and glucocorticoid-receptor DNA-binding-domain mutations distinguish the cooperative mechanism. The retained PMC HTML exposes only the abstract and a link to the non-open-access PDF, so figure-level assay details were not independently checked.', 'Retain the STAT5 -> Csn2/beta-casein promoter comparator as primary abstract-bounded support only. Do not promote it as figure-validated full text, assign a unique STAT5A-versus-STAT5B contribution, infer the exact upstream receptor state in SCI, or treat it as evidence for a downstream TF beyond STAT5.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch063_PMC232525_176708.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000072' AND x.extraction_id='M22B-P2-R-RECOVERY-STAT5-CSN2-000001');
