INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000759', 'M23B-EVID-001021', 'P2FALLBACK-23B-M23B-EVID-001021', 'PMCID:PMC532045', '15483051', 'full_text_xml', 'exact_identifier_match:PMCID:PMC532045', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC532045; URL:https://pmc.ncbi.nlm.nih.gov/articles/PMC532045/', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch063_PMC532045_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001021' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-001021');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000393', 'M22B-EVID-000020', 'M22B-P2-R-000053', 'PMID:10022869; PMCID:PMC83975; DOI:10.1128/MCB.19.3.1821', '10022869', 'full_text_html', 'exact_identifier_match:DOI:10.1128/mcb.19.3.1821;PMCID:PMC83975', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:10022869; PMCID:PMC83975; DOI:10.1128/MCB.19.3.1821; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC83975.html', 'In human HaCaT keratinocytes, TGF-beta1 induced a Smad3/Smad4-containing complex to bind the +62 to +73 CAGA repeat in the c-Jun promoter; EMSA supershifts and loss of the induced complex in Smad3-null fibroblasts supported Smad3 dependence. Mutation of the CAGA site reduced TGF-beta-responsive c-Jun reporter activation, while an AP-1/CRE site independently contributed to residual responsiveness.', 'The authors conclude that TGF-beta-induced Smad3/Smad4 binding at a CAGA element and cooperation with AP-1/CRE sequences synergistically activate the c-Jun promoter, with Smad3 required for the induced complex and response.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch063_PMC83975_STAT3_target.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000020' AND x.extraction_id='M22B-P2-R-000053');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000393', 'M22B-EVID-000020', 'M22B-P2-R-RECOVERY-SMAD3-SMAD4-JUN-000001', 'PMID:10022869; PMCID:PMC83975; DOI:10.1128/MCB.19.3.1821', '10022869', 'full_text_html', 'exact_identifier_match:DOI:10.1128/mcb.19.3.1821;PMCID:PMC83975', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMID:10022869; PMCID:PMC83975; DOI:10.1128/MCB.19.3.1821; https://pubmed.ncbi.nlm.nih.gov/10022869/; https://pmc.ncbi.nlm.nih.gov/articles/PMC83975/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch063_PMC83975_STAT3_target.html', 'TGF-beta1 induced a Smad3/Smad4-containing complex to bind the +62 to +73 CAGA region of the human c-Jun promoter in EMSA and supershift assays. Mutation of that site eliminated the induced complex and reduced TGF-beta-responsive c-Jun promoter reporter activity in HaCaT and mink lung epithelial cells. Smad3-deficient mouse embryonic fibroblasts lost TGF-beta induction and induced-complex binding. The c-Jun response also required a separate AP-1/CRE site, demonstrating cooperative promoter regulation rather than a Smad-only mechanism.', 'Retain direct SMAD3/SMAD4 -> JUN/c-Jun promoter evidence with AP-1 cooperation in the reported mammalian comparator systems. Do not split the complex into independent SMAD3-only or SMAD4-only direct edges, infer a specific upstream BMP8B/GDF11/activin/MSTN receptor handoff, or transfer the promoter result to SCI cells.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch063_PMC83975_STAT3_target.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000020' AND x.extraction_id='M22B-P2-R-RECOVERY-SMAD3-SMAD4-JUN-000001');
