INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000754', 'M22B-EVID-005218', 'P2FALLBACK-22B-M22B-EVID-005218', 'PMCID:PMC11128890', '38803393', 'full_text_xml', 'exact_identifier_match:PMCID:PMC11128890', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMCID:PMC11128890', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch064_PMC11128890_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005218' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-005218');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000451', 'M22B-EVID-000079', 'M22B-P2-R-000111', 'PMID:23435120; PMCID:PMC4161284; DOI:10.1038/ni.2541', '23435120', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4161284', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_functional_context', 'PMID:23435120; PMCID:PMC4161284; DOI:10.1038/ni.2541; https://pubmed.ncbi.nlm.nih.gov/23435120/; https://pmc.ncbi.nlm.nih.gov/articles/PMC4161284/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch064_PMC4161284_bioc.json', 'In mouse dendritic-cell models, TSLP activated JAK1/JAK2 and STAT5 in Flt3L-derived CD11b-positive DCs; DC-specific STAT5 deletion or TSLPR deficiency impaired TSLP-induced CCL17, costimulatory molecules, chemokines, allergic type-2 responses, and T-cell priming. The study supports a TSLP-STAT5-dependent program, not a direct STAT5 target-gene occupancy edge.', 'Retain TSLP -> TSLPR/JAK1-JAK2 -> STAT5 -> CCL17/costimulatory and chemokine program -> type-2 DC/T-cell output as mouse comparator evidence. Do not promote direct STAT5 binding to the Ccl17 locus from this record or transfer the allergic DC program to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch064_PMC4161284_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000079' AND x.extraction_id='M22B-P2-R-000111');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000454', 'M22B-EVID-000081', 'M22B-P2-B085-002', 'PMID:23435120; PMCID:PMC4161284; DOI:10.1038/ni.2541', '23435120', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4161284', 'linked_unresolved', NULL, 'L1', 'validated_fulltext', 'M22B-C-PH2-B085-002', 'Official PMC full text was reviewed; no receptor-level or SCI transfer was promoted.', 'Conditional STAT5 deletion in dendritic cells reduced eosinophilic recruitment and IL-4/IL-13-associated TH2 responses in OVA- and Aspergillus-induced airway inflammation, while increasing IFN-gamma in the tested lung models. STAT5 in dendritic cells was required for the TH2 inflammatory phenotype.', 'Discussion and Results', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch064_PMC4161284_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000081' AND x.extraction_id='M22B-P2-B085-002');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000454', 'M22B-EVID-000081', 'M22B-P2-R-000113', 'PMID:23435120; PMCID:PMC4161284; DOI:10.1038/ni.2541', '23435120', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4161284', 'candidate_requires_review', NULL, 'L1', 'validated_abstract_bounded', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:23435120; PMCID:PMC4161284; DOI:10.1038/ni.2541; https://pubmed.ncbi.nlm.nih.gov/23435120/; https://pmc.ncbi.nlm.nih.gov/articles/PMC4161284/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch064_PMC4161284_bioc.json', 'Reuse the validated TSLP-STAT5 dendritic-cell observation for the distinct allergic phenotype handoff: TSLP activated JAK1/JAK2-STAT5 in mouse dendritic cells, and STAT5 or TSLPR loss impaired CCL17/costimulatory/chemokine outputs, allergic airway/barrier responses, and T-cell priming. The phenotype is downstream of a multicytokine immune circuit and is not a direct STAT5 target record.', 'Reuse TSLP -> TSLPR/JAK1-JAK2 -> STAT5-dependent DC and allergic type-2 phenotype evidence for this distinct handoff. Do not promote direct STAT5 binding to Ccl17 or infer the CRLF2-IL7R branch in SCI cells.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch064_PMC4161284_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000081' AND x.extraction_id='M22B-P2-R-000113');
