INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000354', 'M22B-EVID-000088', 'M22B-P2-R-000088-R092', 'PMCID:PMC12097095; PMID:40125634; DOI:10.1002/advs.202500616', '40125634', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC12097095', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC12097095; PMID:40125634; DOI:10.1002/advs.202500616; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml', 'Autocrine GDF10 signaling through BMPR2/ALK3 in mouse and human hepatic stellate cells activated phosphorylated SMAD1/5/8, recruited pSMAD1/5/8 to the Smad7 promoter, activated a Smad7 promoter reporter, and induced Smad7 expression; Smad7 loss weakened the antifibrotic output.', 'The primary study directly supports GDF10-BMPR2/ALK3-pSMAD1/5/8 recruitment and activation of the Smad7 promoter in hepatic stellate-cell models; the BMPR2-only handoff label omits ALK3, SMAD8/SMAD9 paralog specificity is not resolved, and SCI transfer is unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC12097095_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000088' AND x.extraction_id='M22B-P2-R-000088-R092');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000358', 'M22B-EVID-000089', 'M22B-P2-R-000089-R092', 'PMCID:PMC12097095; PMID:40125634; DOI:10.1002/advs.202500616', '40125634', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC12097095', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC12097095; PMID:40125634; DOI:10.1002/advs.202500616; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12097095_GDF10_Smad7.xml', 'GDF10-BMPR2/ALK3-SMAD1/5/8-Smad7 signaling inhibited TGF-beta-SMAD2/3 signaling, reduced hepatic stellate-cell activation, and alleviated liver fibrosis in mouse models; the broader program includes the direct Smad7 promoter record but is not equivalent to it.', 'The primary study supports a GDF10-BMPR2/ALK3-SMAD1/5/8-Smad7 antifibrotic hepatic-stellate-cell program and functional suppression of TGF-beta-SMAD2/3 activation; direct promoter occupancy remains represented only by M22B-E000354.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC12097095_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000089' AND x.extraction_id='M22B-P2-R-000089-R092');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000361', 'M22B-EVID-000090', 'M22B-P2-R-000120', 'PMID:40125634; PMCID:PMC12097095; DOI:10.1002/advs.202500616', '40125634', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC12097095', 'candidate_requires_review', NULL, 'L1', 'validated_abstract_bounded', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:40125634; PMCID:PMC12097095; DOI:10.1002/advs.202500616; https://pubmed.ncbi.nlm.nih.gov/40125634/; https://pmc.ncbi.nlm.nih.gov/articles/PMC12097095/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC12097095_bioc.json', 'Reuse the GDF10-BMPR2/ALK3-SMAD1/5/8-Smad7 observation for the antifibrotic phenotype handoff: GDF10 gain or recombinant treatment reduced HSC activation and liver fibrosis, while GDF10 loss worsened fibrosis. The phenotype is kept distinct from direct SMAD1/5/8 promoter occupancy.', 'Reuse the GDF10-BMPR2/ALK3-SMAD1/5/8-Smad7 antifibrotic HSC/liver-fibrosis phenotype as a distinct functional output. Do not infer direct SMAD target occupancy from the phenotype or transfer the result to SCI.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC12097095_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000090' AND x.extraction_id='M22B-P2-R-000120');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000397', 'M22B-EVID-000091', 'M22B-P2-R-000121', 'PMID:40125634; PMCID:PMC12097095; DOI:10.1002/advs.202500616', '40125634', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC12097095', 'negative_or_boundary_evaluated', 'U', 'L0', 'boundary_only', 'unresolved', 'PMID:40125634; PMCID:PMC12097095; DOI:10.1002/advs.202500616; https://pubmed.ncbi.nlm.nih.gov/40125634/; https://pmc.ncbi.nlm.nih.gov/articles/PMC12097095/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC12097095_bioc.json', 'The retrieved GDF10 primary study supports BMPR2/ALK3 signaling, phospho-SMAD1/5/8, SMAD1/5 promoter occupancy, and a direct Smad7 promoter edge, but it does not resolve SMAD8- or SMAD9-specific occupancy or target-gene causality. No SMAD8-specific target edge is promoted.', 'Leave the SMAD8/SMAD9 target assignment unresolved. Do not transfer the validated SMAD1/5-to-Smad7 promoter evidence to SMAD8 or treat BMPR2-only labeling as equivalent to BMPR2/ALK3 in an SCI receiver cell.', 'The linked Phase-2 adjudication explicitly bounds or rejects support for the requested exact relationship. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC12097095_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000091' AND x.extraction_id='M22B-P2-R-000121');
