INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000432', 'M22B-EVID-000083', 'M22B-P2-R-000083-R092', 'PMCID:PMC3424405; PMID:22865915; DOI:10.4049/jimmunol.1201126', '22865915', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3424405', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC3424405; PMID:22865915; DOI:10.4049/jimmunol.1201126; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3424405_IL10_Zfp36.xml', 'IL-10 induced STAT3 recruitment to a conserved STAT3 binding site in the Ttp/Zfp36 promoter in LPS-activated mouse bone-marrow-derived macrophages; STAT3 was required for efficient IL-10-induced Ttp expression, forming a feedback loop that limited inflammatory cytokine production.', 'The primary study directly supports IL-10 receptor-pathway-associated STAT3 recruitment and transcriptional activation of the Ttp/Zfp36 promoter in activated macrophages; receptor-complex details, cell-state transfer, and SCI application remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch065_PMC3424405_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000083' AND x.extraction_id='M22B-P2-R-000083-R092');
