INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000554', 'M22B-EVID-005436', 'M22B-P2-R-000818', 'PMCID:PMC2080618', '16597617', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2080618', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC2080618; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC2080618_full.xml', 'Primary source PMCID:PMC2080618 reports the tested receptor/proximal or functional observation at its model scope; no stronger terminal-TF edge is inferred.', 'The source supports a bounded receptor/pathway or functional association; no direct TF occupancy or terminal target locus was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC2080618_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005436' AND x.extraction_id='M22B-P2-R-000818');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000292', 'M22B-EVID-000097', 'M22B-P2-R-000097-R093', 'PMCID:PMC6830343; PMID:31736768; PMID:35044859; DOI:10.3389/fphys.2019.01324', '31736768', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6830343', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC6830343; PMID:31736768; DOI:10.3389/fphys.2019.01324; PMID:35044859; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6830343_MR_CYP11B2.xml; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_MR_ESR1_EGFR_TSHR_pubmed.xml', 'Mineralocorticoid-receptor signaling was associated with CYP11B2 aldosterone-synthase localization and normal repair after acute muscle injury; myofiber or myeloid NR3C2 perturbation altered repair/inflammatory phenotypes, while CYP11B2 was detected in infiltrating immune-cell compartments.', 'The primary studies support an MR/NR3C2-associated injury-repair program and CYP11B2 protein-localization association, but do not demonstrate NR3C2 occupancy at the Cyp11b2 locus or cell-autonomous regulation because MR perturbation and CYP11B2 signal are not confined to the same compartment; aldosterone-source and SCI transfer remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC6830343_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000097' AND x.extraction_id='M22B-P2-R-000097-R093');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000293', 'M22B-EVID-000098', 'M22B-P2-B085-003', 'PMID:31736768; PMCID:PMC6830343; DOI:10.3389/fphys.2019.01324', '31736768', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6830343', 'linked_unresolved', NULL, 'L1', 'validated_fulltext', 'M22B-C-PH2-B085-003', 'Official PMC full text was reviewed; non-SCI tissue evidence remains comparator evidence and is not transferred as SCI-specific.', 'Acute barium-chloride injury of mouse tibialis anterior muscle induced CYP11B2-positive CD11b-positive immune-cell infiltration. Myofiber mineralocorticoid-receptor deletion and systemic spironolactone treatment altered injury, collagen organization, and repair phenotypes, supporting MR-dependent regulation of the injured muscle microenvironment.', 'Discussion and Results', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC6830343_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000098' AND x.extraction_id='M22B-P2-B085-003');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000293', 'M22B-EVID-000098', 'M22B-P2-R-000127', 'PMID:31736768; PMCID:PMC6830343; DOI:10.3389/fphys.2019.01324', '31736768', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6830343', 'candidate_requires_review', NULL, 'L1', 'validated_abstract_bounded', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:31736768; PMCID:PMC6830343; DOI:10.3389/fphys.2019.01324; https://pubmed.ncbi.nlm.nih.gov/31736768/; https://pmc.ncbi.nlm.nih.gov/articles/PMC6830343/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC6830343_bioc.json', 'Reuse the validated aldosterone/MR acute muscle-injury observation for the distinct repair phenotype handoff: MR conditional deletion and antagonist treatment changed damaged-fiber stabilization, fibrosis/collagen infiltration, and myofiber growth. No direct NR3C2/Cyp11b2 target edge is assigned.', 'Reuse MR-dependent muscle-repair and fibrosis phenotype evidence for the distinct functional handoff, preserving the immune-cell CYP11B2 compartment boundary and avoiding direct target inference.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC6830343_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000098' AND x.extraction_id='M22B-P2-R-000127');
