INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000015', 'M22B-EVID-000133', '', '', NULL, 'full_text_or_bioc_json', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch070_PMC3235522_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000133' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000234', 'M22B-EVID-000134', 'M22B-P2-R-000014A', 'PMCID:PMC3235522; PMID:21316586; DOI:10.1016/j.devcel.2011.01.002', '21316586', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3235522', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3235522; PMID:21316586; DOI:10.1016/j.devcel.2011.01.002; https://pmc.ncbi.nlm.nih.gov/articles/PMC3235522/; https://pubmed.ncbi.nlm.nih.gov/21316586/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html', 'In dissociated mouse commissural neurons, 30-minute Wnt5a stimulation increased phospho-Jun approximately fourfold without changing total Fzd3 or Vangl2 abundance. In rat E13 open-book explants, JNK inhibitor-I or SP600125 reduced the fraction of correctly guided commissural axons from approximately 91% to approximately 39% and randomized anterior-posterior projections. The result supports a WNT5A-FZD3/Vangl2-associated JNK-to-c-Jun relay and its requirement for axon guidance; it is not a purified Wnt5a-Fzd3 binding assay or direct c-JUN target-gene measurement.', 'The authors conclude that Wnt5a activates JNK signaling in commissural neurons and that JNK activity is required for correct anterior-posterior commissural axon guidance.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch070_PMC3235522_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000134' AND x.extraction_id='M22B-P2-R-000014A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000234', 'M22B-EVID-000134', 'M22B-P2-R-000014B', 'PMCID:PMC3235522; PMID:21316586; DOI:10.1016/j.devcel.2011.01.002', '21316586', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3235522', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3235522; PMID:21316586; DOI:10.1016/j.devcel.2011.01.002; https://pmc.ncbi.nlm.nih.gov/articles/PMC3235522/; https://pubmed.ncbi.nlm.nih.gov/21316586/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html', 'In HEK293T cells, Wnt5a plus Fzd3 increased phospho-Jun; coexpression of Fzd3 with Dvl1 reduced Wnt5a-stimulated phospho-Jun, whereas Vangl2 prolonged the signal and Vangl2 shRNA abolished Wnt5a-stimulated planar-cell-polarity signaling. These experiments support a Fzd3/Dvl1/Vangl2 receptor-complex/pathway branch upstream of JNK/c-Jun and an associated commissural-axon-growth output, while remaining distinct from a direct Wnt5a-Fzd3 affinity measurement.', 'The authors conclude that Fzd3 and Vangl2 mediate Wnt5a-stimulated PCP-like signaling and that Vangl2 antagonizes Dvl1-mediated feedback inhibition, thereby sustaining the JNK/c-Jun signal associated with commissural axon growth.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch070_PMC3235522_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000134' AND x.extraction_id='M22B-P2-R-000014B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000235', 'M22B-EVID-000135', 'M22B-P2-R-000142', 'PMCID:PMC3235522', '21316586', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3235522', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC3235522; https://pmc.ncbi.nlm.nih.gov/articles/PMC3235522/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch070_PMC3235522_bioc.json', 'Reuse the validated Wnt5a-Fzd3/Vangl2-JNK spinal commissural-neuron observation for the distinct axon-guidance phenotype handoff: disruption of Vangl2, Celsr3, Fzd3, or JNK activity randomized post-crossing axon trajectories and reduced Wnt5a-stimulated outgrowth. No direct c-Jun target gene is assigned.', 'Reuse WNT5A-FZD3/Vangl2-JNK axon-guidance evidence for the distinct spinal phenotype handoff, preserving the pathway/phenotype distinction and no direct c-Jun target inference.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch070_PMC3235522_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000135' AND x.extraction_id='M22B-P2-R-000142');
