INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch070_PMIDs_131_140_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000171', 'M22B-EVID-000143', 'M22B-P2-R-000148', 'PMCID:PMC10493313; PMID:37701781; DOI:10.3389/fcell.2023.1220002', '37701781', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC10493313', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_downstream_program', 'PMCID:PMC10493313; PMID:37701781; DOI:10.3389/fcell.2023.1220002; https://pmc.ncbi.nlm.nih.gov/articles/PMC10493313/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC10493313_bioc.json', 'In human fetal lung fibroblasts from pseudoglandular and canalicular stages, recombinant FGF18 increased proliferation and migration, while FGFR-directed siRNA altered the response in a stage-dependent manner. FGF18 treatment also changed ETV4 and ETV5 transcript measurements in the proliferation experiments. The study supports an FGF18-FGFR-context-dependent ETV expression program, not direct ETV4/ETV5 DNA occupancy or a single universal FGFR2/FGFR4 complex.', 'Retain FGF18-to-FGFR-context-dependent ETV4/ETV5 expression and mesenchymal proliferation, migration, and differentiation as a human lung developmental pathway program. Do not promote direct ETV4/ETV5 target binding, and preserve stage-specific FGFR2/3/4 usage rather than collapsing it to one receptor complex.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC10493313_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000143' AND x.extraction_id='M22B-P2-R-000148');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000173', 'M22B-EVID-000144', '', '', NULL, 'full_text_or_bioc_json', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC10493313_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000144' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000124', 'M22B-EVID-000150', 'M22B-P2-R-000028I', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436', '17962702', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2905627', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436; https://pmc.ncbi.nlm.nih.gov/articles/PMC2905627/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml', 'GDNF increased phosphorylation of CREB1, ATF1, and CREM1 and induced c-fos transcription in C18-4 mouse spermatogonial stem cells. MEK1/ERK inhibition with PD98059 blocked GDNF-induced ERK1/2 phosphorylation and c-fos transcription, supporting an ERK-dependent CREB-family/immediate-early branch.', 'The authors conclude that GDNF/GFRα1/Ret activates Ras/ERK1/2 and thereby phosphorylates CREB-family factors and induces c-fos transcription.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000150' AND x.extraction_id='M22B-P2-R-000028I');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000124', 'M22B-EVID-000150', 'M22B-P2-R-000028J', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436', '17962702', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2905627', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436; https://pmc.ncbi.nlm.nih.gov/articles/PMC2905627/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2905627_GDNF.xml', 'GDNF increased BrdU incorporation, metaphase counts, and cyclin A/CDK2 expression in C18-4 cells, while PD98059 blocked the GDNF-induced BrdU, metaphase, cyclin A, and CDK2 responses. These data link the measured GDNF/ERK branch to S-phase entry and spermatogonial stem-cell proliferation.', 'The authors conclude that GDNF-induced Ras/ERK1/2 signaling promotes cell-cycle progression and proliferation of the C18-4 spermatogonial stem-cell model through downstream cyclin A/CDK2-associated outputs.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000150' AND x.extraction_id='M22B-P2-R-000028J');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000124', 'M22B-EVID-000150', 'M22B-P2-R-000152', 'PMCID:PMC2905627; PMID:17962702; PMID:8657281; DOI:10.1634/stemcells.2007-0436; DOI:10.1038/381785a0', '8657281', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2905627', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_downstream_program', 'PMCID:PMC2905627; PMID:17962702; PMID:8657281; DOI:10.1634/stemcells.2007-0436; DOI:10.1038/381785a0; https://pmc.ncbi.nlm.nih.gov/articles/PMC2905627/; https://pubmed.ncbi.nlm.nih.gov/8657281/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMIDs_141_150_pubmed.xml', 'In the mouse C18-4 spermatogonial stem-cell line and freshly isolated type-A spermatogonia, GDNF stimulated RET phosphorylation, Shc/Grb2 recruitment, Ras and ERK1/2 activation, phosphorylation of CREB-1, ATF-1, and CREM-1, and c-fos transcription. MEK1/ERK1/2 inhibition blocked ERK1/2 phosphorylation, c-fos transcription, DNA synthesis, and proliferation readouts. A separate primary receptor study showed GDNF binding to RET and RET-dependent survival/growth responses in transfected fibroblasts.', 'Retain GDNF-GFRα1/RET-to-Ras/ERK1/2-to-CREB-family/c-fos as a primary spermatogonial proliferation program, with direct RET engagement supported by the receptor comparator. Do not infer direct CREB-family occupancy at a terminal gene or transfer the germ-cell proliferative output to SCI receivers.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000150' AND x.extraction_id='M22B-P2-R-000152');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000126', 'M22B-EVID-000151', 'M22B-P2-R-000153', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436', '17962702', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2905627', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC2905627; PMID:17962702; DOI:10.1634/stemcells.2007-0436; https://pmc.ncbi.nlm.nih.gov/articles/PMC2905627/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml', 'Reuse the validated GDNF-GFRα1/RET-Ras/ERK1/2-CREB-family observation for the distinct phenotype handoff: GDNF-induced c-fos transcription, cyclin A/CDK2 expression, DNA synthesis, and spermatogonial stem-cell proliferation were blocked by MEK1/ERK1/2 inhibition. No direct CREB-family target-gene edge is assigned.', 'Reuse GDNF-GFRα1/RET-CREB-family signaling and spermatogonial proliferation as a separate functional output. Do not convert c-fos transcription into direct CREB occupancy or transfer the germ-cell phenotype to SCI receivers.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000151' AND x.extraction_id='M22B-P2-R-000153');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000125', 'M22B-EVID-000152', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC2905627_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000152' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000144', 'M22B-EVID-000147', 'M22B-P2-R-000150', 'PMCID:PMC3060419; PMCID:PMC4654537; PMID:19357251; PMID:26588476; DOI:10.1681/ASN.2008070783; DOI:10.1371/journal.pone.0142924', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC3060419', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_downstream_program', 'PMCID:PMC3060419; PMCID:PMC4654537; PMID:19357251; PMID:26588476; DOI:10.1681/ASN.2008070783; DOI:10.1371/journal.pone.0142924; https://pmc.ncbi.nlm.nih.gov/articles/PMC3060419/; https://pmc.ncbi.nlm.nih.gov/articles/PMC4654537/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC3060419_full.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC4654537_full.xml', 'In FGF23-injected mice, nuclear phospho-ERK1/2 was restricted to α-Klotho-positive distal convoluted-tubule cells and colocalized with FGFR1, establishing an initial renal receptor-proximal branch. In a separate FGF23-treated and egr-1-null mouse study, egr-1 deletion blunted hypophosphatemia and prevented the normal suppression of Npt2a/Npt2c protein or expression responses; FGF23 ChIP-seq recovered Egr-1 at regulatory DNA near phosphate-transport-network genes, with Nab1 enhancer binding validated by ChIP-qPCR and reporter assay. No direct Egr-1-to-Npt2a/Npt2c promoter edge was promoted.', 'Retain FGF23-FGFR1/α-Klotho-to-ERK1/2-to-EGR1 as a renal phosphate-response branch. EGR1 is functionally required for the hypophosphatemic/Npt2a-Npt2c response and has cistrome-level regulatory evidence, including a validated Nab1 enhancer comparator, but the source does not establish direct EGR1 occupancy at the Npt2a or Npt2c promoters and separates the phosphate branch from vitamin-D regulation.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC3060419_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000147' AND x.extraction_id='M22B-P2-R-000150');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000152', 'M22B-EVID-000145', 'M22B-P2-R-000149', 'PMID:24024127; PMCID:PMC3757657; DOI:10.1016/j.molmet.2012.08.007', '24024127', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3138239', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_downstream_program', 'PMID:24024127; PMCID:PMC3757657; DOI:10.1016/j.molmet.2012.08.007; https://pubmed.ncbi.nlm.nih.gov/24024127/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3757657/; queued locator mismatch=PMCID:PMC3138239 resolves to PMID:21712364; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC3757657_full.xml', 'In male diet-induced-obese mice, acute recombinant FGF21 induced EGR1 in white adipose tissue, and adipose FGFR1 deletion in FGFR1lox/lox-AP2Cre mice greatly reduced that response. The same study linked adipose FGFR1 dependence to several FGF21 metabolic outputs. The exact paper did not establish a c-FOS readout in this experiment.', 'Promote FGF21-FGFR1/β-Klotho-associated EGR1 immediate-early signaling and adipose metabolic response as a bounded downstream program. Keep the queued c-FOS component unresolved for this exact primary paper because the retrieved full text reports EGR1 rather than a c-FOS assay; do not infer EGR1 target-gene occupancy.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC3138239_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000145' AND x.extraction_id='M22B-P2-R-000149');
