INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC4654537_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000174', 'M22B-EVID-000141', 'M22B-P2-R-000141-R094', 'PMCID:PMC4763945; PMID:26555052; DOI:10.1016/j.devcel.2015.10.006', '26555052', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4763945', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC4763945; PMID:26555052; DOI:10.1016/j.devcell.2015.10.006; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4763945_ETV.json; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_pubmed.xml', 'In embryonic mouse lung epithelium, FGF-activated ETV4/ETV5 factors promoted Shh expression through a long-range MACS1 enhancer approximately 800 kb upstream of Shh; mutation of conserved ETV sites reduced enhancer activity, wild-type but not DNA-binding-defective ETV5 activated the reporter, and ETV5-Flag ChIP recovered the enhancer.', 'The primary study directly supports ETV5 occupancy and enhancer-dependent activation of Shh in the FGF10-FGFR2-linked lung epithelial program; ETV4 and the exact upstream ligand/receptor isoform are not separately resolved in the ChIP assay, and SCI transfer is unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC4763945_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000141' AND x.extraction_id='M22B-P2-R-000141-R094');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000172', 'M22B-EVID-000142', 'M22B-P2-R-000142-R094', 'PMCID:PMC4763945; PMID:26555052; DOI:10.1016/j.devcel.2015.10.006', '26555052', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4763945', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC4763945; PMID:26555052; DOI:10.1016/j.devcell.2015.10.006; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4763945_ETV.json', 'Loss of epithelial Etv4/Etv5 increased Fgf10, decreased Shh, prolonged lung branch-tip growth, and delayed new branch formation; reducing Fgf10 dosage or activating SHH signaling partially rescued the mutant branching phenotype.', 'The primary study supports an FGF-ETV-SHH feedback program controlling lung branching periodicity and branch-tip morphogenesis, but the developmental phenotype is separate from direct ETV5 enhancer occupancy and is not evidence of an SCI repair function or ETV4-specific causality.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC4763945_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000142' AND x.extraction_id='M22B-P2-R-000142-R094');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000172', 'M22B-EVID-000142', 'M22B-P2-R-000147', 'PMID:26555052; PMCID:PMC4763945; DOI:10.1016/j.devcell.2015.10.006', '26555052', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4763945', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:26555052; PMCID:PMC4763945; DOI:10.1016/j.devcel.2015.10.006; https://pmc.ncbi.nlm.nih.gov/articles/PMC4763945/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC4763945_bioc.json', 'Reuse the validated FGF-regulated ETV/Shh observation for the distinct lung branching phenotype handoff: Etv4/Etv5 loss increased Fgf10, reduced Shh signaling, enlarged branch tips, and reduced or delayed new branch formation; Fgf10 dosage and Smoothened agonist experiments partially attenuated the phenotype. No phenotype-to-TF-target shortcut is made.', 'Reuse the FGF-ETV-SHH feedback-loop and lung branching phenotype as a separate functional output. Do not assign the phenotype to ETV4 or ETV5 alone, and do not infer an SCI repair output.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch071_PMC4763945_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000142' AND x.extraction_id='M22B-P2-R-000147');
