INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch074_PMIDs_171_180_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch075_DOI_M205873200_Ym1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000244', 'M22B-EVID-000182', 'M22B-P2-R-000177', 'PMID:32105707; PMID:9284044; PMCID:PMC316448', '9284044', 'full_text_xml', 'exact_identifier_match:PMCID:PMC316448', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_downstream_program', 'PMID:32105707; PMID:9284044; PMCID:PMC316448; https://pmc.ncbi.nlm.nih.gov/articles/PMC316448/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch075_PMC316448_full.xml', 'FGF-6 expression increased after skeletal-muscle crush injury, while FGF-6-null mice showed impaired regeneration, reduced MyoD- and Myogenin-expressing activated muscle precursor cells, and reduced MyoD/Myogenin RNA. The paper proposes satellite-cell activation or proliferation as the mechanism but does not test FGFR4 or a defined intracellular relay.', 'Correct the queued record to an FGF-6-associated MyoD/Myogenin satellite-cell activation and muscle-regeneration program. Do not promote an FGF6-FGFR4 receptor relay from this paper because FGFR4 was not experimentally assayed, and do not infer direct MyoD or Myogenin target-gene regulation.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch075_PMC316448_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000182' AND x.extraction_id='M22B-P2-R-000177');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000245', 'M22B-EVID-000183', 'M22B-P2-R-000178', 'PMID:32105707; PMID:9284044; PMCID:PMC316448', '9284044', 'full_text_xml', 'exact_identifier_match:PMCID:PMC316448', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:32105707; PMID:9284044; PMCID:PMC316448; https://pmc.ncbi.nlm.nih.gov/articles/PMC316448/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch075_PMC316448_full.xml', 'Reuse the validated FGF-6 observation for the separate phenotype handoff: FGF-6-null mice developed severe post-injury muscle-regeneration defects with fibrosis, myotube degeneration, and compromised regeneration in the FGF-6-null/mdx context. No direct MyoD/Myogenin target edge is assigned.', 'Reuse FGF-6-dependent skeletal-muscle regeneration and fibrosis phenotype as a separate functional output. Do not transfer this muscle phenotype to SCI repair without matched evidence.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch075_PMC316448_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000183' AND x.extraction_id='M22B-P2-R-000178');
