INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000298', 'M22B-EVID-000200', 'M22B-P2-R-000190', 'PMID:21335558; PMCID:PMC3075638; DOI:10.1074/jbc.M110.143693', '21335558', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3075638', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:21335558; PMCID:PMC3075638; DOI:10.1074/jbc.M110.143693; https://pmc.ncbi.nlm.nih.gov/articles/PMC3075638/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch076_PMC3075638_full.xml', 'Reuse the validated collagen I-DDR2 observation for the distinct functional-output handoff: collagen I induced DDR1 and MMP-10 expression and MMP-10 secretion, along with MCP-1, BMP-2, and MMP-2 in primary human lung fibroblasts; the paper frames these as matrix-remodeling and profibrotic outputs.', 'Reuse collagen I-DDR2-associated DDR1, MMP-10, and matrix-remodeling/profibrotic expression outputs as a separate functional layer. Do not infer direct PEA3 binding to MMP-10 or transfer the lung-fibroblast output to SCI without matched evidence.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch076_PMC3075638_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000200' AND x.extraction_id='M22B-P2-R-000190');
