INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000203', 'M22B-EVID-000196', 'M22B-P2-R-000187', 'PMID:21427356; PMCID:PMC3182156; DOI:10.1158/0008-5472.CAN-10-3382', '21427356', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3182156', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:21427356; PMCID:PMC3182156; DOI:10.1158/0008-5472.CAN-10-3382; https://pmc.ncbi.nlm.nih.gov/articles/PMC3182156/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch076_PMC3182156_full.xml', 'Reuse the validated β2M-HFE observation for the distinct phenotype handoff: β2M overexpression increased cancer-cell EMT markers, proliferation, migration/invasion, osteolysis, tumor growth, and bone/soft-tissue metastasis in human cancer cells implanted in nude mice; β2M or HFE inhibition reversed EMT in the prostate model.', 'Reuse β2M-HFE-associated EMT, tumor growth, osteolysis, and metastasis phenotype as a separate functional output. Do not transfer the cancer-metastasis phenotype to SCI repair or infer a direct HIF-1α target gene.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch076_PMC3182156_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000196' AND x.extraction_id='M22B-P2-R-000187');
