INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-001397', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch077_PMC162283_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001397' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000247', 'M22B-EVID-000210', 'M22B-P2-R-000016A', 'PMCID:PMC7804096; PMID:33436772; DOI:10.1038/s41598-020-80060-3', '33436772', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7804096', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC7804096; PMID:33436772; DOI:10.1038/s41598-020-80060-3; https://pmc.ncbi.nlm.nih.gov/articles/PMC7804096/; https://pubmed.ncbi.nlm.nih.gov/33436772/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch077_PMC7804096_full.xml', 'In human OEC-M1 oral squamous-cell-carcinoma cells, exogenous EFNA4-Fc induced ERK phosphorylation, while FAK, AKT, non-phospho-beta-catenin, and ILK were not activated in the reported time-course panel. MEK/ERK inhibition with PD98059 blocked EFNA4-Fc-induced migration, sphere formation, and NANOG, OCT4, and SNAIL mRNA induction. EPHA10 knockdown reduced EFNA4-induced migration, sphere formation, and NANOG/OCT4 expression, supporting an EFNA4-EPHA10-to-ERK pathway branch.', 'The authors conclude that EFNA4-EPHA10 forward signaling induces ERK activation and that ERK activity is required for the associated stemness-transcription-factor expression and OSCC cell functions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch077_PMC7804096_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000210' AND x.extraction_id='M22B-P2-R-000016A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000247', 'M22B-EVID-000210', 'M22B-P2-R-000016B', 'PMCID:PMC7804096; PMID:33436772; DOI:10.1038/s41598-020-80060-3', '33436772', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7804096', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC7804096; PMID:33436772; DOI:10.1038/s41598-020-80060-3; https://pmc.ncbi.nlm.nih.gov/articles/PMC7804096/; https://pubmed.ncbi.nlm.nih.gov/33436772/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch077_PMC7804096_full.xml', 'In human OEC-M1 cells, EFNA4-Fc increased migration, tumorsphere formation, and TWIST, SNAIL, OCT4, and NANOG mRNA. NANOG knockdown suppressed EFNA4-induced migration and sphere formation. In a separate orthotopic nude-mouse model, EPHA10 knockdown reduced OSCC tumor growth and lymph-node metastasis. These are downstream TF-expression and cellular-function outputs associated with EFNA4-EPHA10 forward signaling, not evidence of direct NANOG or OCT4 DNA binding.', 'The authors conclude that EFNA4-EPHA10 signaling promotes OSCC migration and tumor-sphere formation through ERK-associated induction of NANOG, with correlated OCT4 expression; NANOG is required for the measured EFNA4-induced functions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch077_PMC7804096_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000210' AND x.extraction_id='M22B-P2-R-000016B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000248', 'M22B-EVID-000211', 'M22B-P2-R-000198', 'PMID:33436772; PMCID:PMC7804096; DOI:10.1038/s41598-020-80060-3', '33436772', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7804096', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:33436772; PMCID:PMC7804096; DOI:10.1038/s41598-020-80060-3; https://pmc.ncbi.nlm.nih.gov/articles/PMC7804096/', 'Reuse the EFNA4-EPHA10 observation for the distinct functional handoff: EFNA4 stimulation, EPHA10 dependence, ERK-associated NANOG/OCT4/SNAIL expression, and migration/sphere outputs in oral squamous-cell-carcinoma models; EPHA10 is kinase-deficient and no NANOG/OCT4 occupancy assay was reported.', 'Reuse EFNA4-EPHA10-associated migration, sphere formation, stemness-marker expression, and tumor outputs as a separate functional context. Do not infer direct NANOG/OCT4 target binding or transfer the cancer phenotype to SCI repair.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch077_PMC7804096_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000211' AND x.extraction_id='M22B-P2-R-000198');
