INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000052', 'M22B-EVID-000216', 'M22B-P2-R-000202', 'PMID:20693566; PMCID:PMC2952555; DOI:10.1194/jlr.M006841; PMID:35192688; PMCID:PMC7612781; DOI:10.2337/db21-1166', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC2952555', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:20693566; PMCID:PMC2952555; DOI:10.1194/jlr.M006841; PMID:35192688; PMCID:PMC7612781; DOI:10.2337/db21-1166; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch078_PMC2952555_full.xml and retry_B22B_batch078_PMC7612781_full.xml', 'Reuse the GIP observation for the distinct adipocyte functional output: GIP plus insulin increased LPL expression and lipogenic activity in human adipocytes, with CREB/TORC2-dependent transcriptional support in the tested culture system. The mouse WAT localization study indicates that most endogenous WAT GIPR signal is in nonadipocyte populations, so the culture phenotype should not be treated as a direct whole-tissue or SCI-cell prediction.', 'Reuse GIP-associated LPL/lipogenic output as an adipose-context functional record. Do not infer a new receptor edge, direct CREB/TORC2 target beyond LPL, or SCI relevance.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch078_PMC2952555_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000216' AND x.extraction_id='M22B-P2-R-000202');
