INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000233', 'M22B-EVID-000221', 'M22B-P2-R-000206', 'PMCID:PMC4785887; PMID:26280537; DOI:10.1038/ncb3222', '26280537', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4785887', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC4785887; PMID:26280537; DOI:10.1038/ncb3222; https://pmc.ncbi.nlm.nih.gov/articles/PMC4785887/', 'Reuse the MIF observation for the distinct functional output: secreted O-GlcNAcylated MIF antagonized EGFR signaling and reduced tumor-cell invasion, proliferation, and brain-tumor formation in human tumor models; EGFR-induced MMP13 degraded extracellular MIF. No direct JUN target-gene assay was shown.', 'Reuse the MIF-EGFR antagonism and tumor-suppression phenotype as a separate functional context. Do not infer direct c-Jun target binding or transfer the tumor phenotype to SCI repair.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch078_PMC4785887_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000221' AND x.extraction_id='M22B-P2-R-000206');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000238', 'M22B-EVID-000222', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch078_PMC4785887_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000222' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000053', 'M22B-EVID-000213', 'M22B-P2-R-000199', 'PMID:17889508; DOI:10.1016/j.cellsig.2007.08.016; PMID:30115027; PMCID:PMC6097285; DOI:10.1186/s12885-018-4717-7', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC6097285', 'candidate_requires_review', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMID:17889508; DOI:10.1016/j.cellsig.2007.08.016; https://pubmed.ncbi.nlm.nih.gov/17889508/; PMID:30115027; PMCID:PMC6097285; DOI:10.1186/s12885-018-4717-7; https://pmc.ncbi.nlm.nih.gov/articles/PMC6097285/', 'Gastrin acting through CCK-B/CCKBR activates PKC-Raf1-MEK1-ERK1/2 in AGS-B gastric cells; MEK/ERK blockade removes gastrin-dependent chromogranin A promoter transactivation, and the minimal CgA-85/-64 element is necessary and sufficient for MEK/ERK responsiveness. The abstract attributes the promoter effect to enhanced Sp1 and CREB phosphorylation. A separate breast-cancer study supports gastrin/CCKBR/ERK/p65 signaling and tumor-suppressive outputs in ER-positive models, but does not establish a direct p65 target promoter.', 'Promote the gastrin-CCKBR-PKC-Raf1-MEK1-ERK1/2-Sp1/CREB-to-CgA promoter program as direct promoter-reporter evidence bounded to AGS-B cells and the primary abstract. Retain the ER-positive breast CCKBR/ERK/p65 program as a separate receptor/pathway context; do not infer a direct p65 target gene or merge the two cell contexts.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch078_PMC6097285_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000213' AND x.extraction_id='M22B-P2-R-000199');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000054', 'M22B-EVID-000214', 'M22B-P2-R-000200', 'PMID:17889508; DOI:10.1016/j.cellsig.2007.08.016; PMID:30115027; PMCID:PMC6097285; DOI:10.1186/s12885-018-4717-7', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC6097285', 'linked_unresolved', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:30115027; PMCID:PMC6097285; DOI:10.1186/s12885-018-4717-7; PMID:17889508; DOI:10.1016/j.cellsig.2007.08.016; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch078_PMC6097285_full.xml and retry_B22B_batch078_PMIDs_211_220_pubmed.xml', 'Reuse the gastrin/CCKBR observation for a distinct functional output: gastrin-associated ERK/p65 activity inhibited ER-positive breast-cancer cell growth and xenograft output in the tested models, while the separate AGS-B study reported gastrin-dependent CgA promoter transactivation. These are not a single universal cellular response.', 'Reuse the gastrin-associated breast-cancer growth-suppression phenotype as a separate functional context. Do not transfer it to SCI repair, infer direct p65 target binding, or collapse it with the gastric CgA promoter program.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch078_PMC6097285_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000214' AND x.extraction_id='M22B-P2-R-000200');
