INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004764', 'M20B-EVID-004764-P2-FUNC', 'M20B-P2-R-004764-R244B', 'PMID:24833748; PMCID:PMC4203355; DOI:10.15252/emmm.201303498; PMID:25880347; DOI:10.1111/jphp.12415', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC4203355', 'candidate_requires_review', 'B', 'L1', 'validated_primary_fulltext', 'validated_functional_output', 'PMID:24833748; PMCID:PMC4203355; DOI:10.15252/emmm.201303498; PMID:25880347; DOI:10.1111/jphp.12415; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_S100A1_TLR4_PMC4203355.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_S100A1_primary_records.xml', 'S100A1/TLR4-associated MAPK/NF-kappaB signaling altered ICAM1, collagen, cytokine, ROS, and inflammatory responses in cardiac fibroblast, cardiomyocyte, and myocardial-infarction models.', 'Promote conditional S100A1/TLR4 inflammatory and remodeling outputs while leaving direct binding, SCI transfer, and terminal TF target loci unresolved.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch081_PMC4203355_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004764-P2-FUNC' AND x.extraction_id='M20B-P2-R-004764-R244B');
