INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E005171', 'M20B-EVID-005171-P2-RELAY-303', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC30227_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-005171-P2-RELAY-303' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000180', 'M22B-EVID-000275', 'M22B-P2-R-000242', 'PMCID:PMC30227; PMID:11226328; DOI:10.1073/pnas.051626398', '11226328', 'full_text_xml', 'exact_identifier_match:PMCID:PMC30227', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_pathway_bounded', 'PMCID:PMC30227; PMID:11226328; DOI:10.1073/pnas.051626398; https://pmc.ncbi.nlm.nih.gov/articles/PMC30227/', 'Urocortin II bound selectively to CRF-R2 with no appreciable CRF-R1 activity. Central administration of synthetic Ucn II to rats induced Fos in a restricted set of autonomic and neuroendocrine structures, including paraventricular hypothalamus, central amygdala, and nucleus of the solitary tract; the distribution did not broadly match CRF-R2 expression. This is an immediate-early activation output, not a direct FOS target-gene edge.', 'Promote the selective Ucn II-CRF-R2 association and bounded Fos-induction program in the reported rat autonomic/neuroendocrine circuitry. Do not infer CRF-R2 occupancy in every Fos-positive region or direct FOS binding to a downstream gene.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC30227_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000275' AND x.extraction_id='M22B-P2-R-000242');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000179', 'M22B-EVID-000276', 'M22B-P2-R-000243', 'PMCID:PMC30227; PMID:11226328; DOI:10.1073/pnas.051626398', '11226328', 'full_text_xml', 'exact_identifier_match:PMCID:PMC30227', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC30227; PMID:11226328; DOI:10.1073/pnas.051626398; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC30227_full.xml', 'Reuse the validated Ucn II observation for the distinct phenotype: central Ucn II attenuated nighttime feeding and produced autonomic/neuroendocrine activation without increasing gross motor activity. The outcome is downstream of a distributed CRF-R2-associated circuit and does not identify a direct FOS target or SCI repair phenotype.', 'Reuse the primary Ucn II behavioral and autonomic/neuroendocrine output as a separate functional context. Do not infer a cell-autonomous CRF-R2-to-FOS mechanism or a spinal-cord repair outcome.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC30227_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000276' AND x.extraction_id='M22B-P2-R-000243');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000310', 'M22B-EVID-000271', 'M22B-P2-R-000029B', 'PMCID:PMC3408167; PMID:22669972; DOI:10.1074/jbc.M112.356279', '22669972', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3408167', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3408167; PMID:22669972; DOI:10.1074/jbc.M112.356279; https://pmc.ncbi.nlm.nih.gov/articles/PMC3408167/; https://pubmed.ncbi.nlm.nih.gov/22669972/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC3408167_TNF_NFKB_FAS.html', 'In human SW620 metastatic colon carcinoma cells, TNFα treatment increased cell-surface Fas, and p50 ChIP after 30 minutes showed canonical NF-κB association with multiple regions of the human FAS promoter. EMSA showed canonical NF-κB binding to all five mapped NF-κB consensus sequences in the promoter. Blocking canonical NF-κB with dominant-negative IKKβ reduced Fas protein and mRNA, whereas blocking alternate NF-κB with dominant-negative IKKα increased both.', 'The authors conclude that TNFα-activated canonical NF-κB directly binds multiple sites in the human FAS promoter and activates FAS transcription, while alternate NF-κB acts as a repressive branch in the tested carcinoma context.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC3408167_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000271' AND x.extraction_id='M22B-P2-R-000029B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000310', 'M22B-EVID-000271', 'M22B-P2-R-000239', 'PMCID:PMC3408167; PMID:22669972; DOI:10.1074/jbc.M112.356279', '22669972', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3408167', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC3408167; PMID:22669972; DOI:10.1074/jbc.M112.356279; https://pmc.ncbi.nlm.nih.gov/articles/PMC3408167/', 'TNF-alpha and IFN-gamma increased FAS expression in tumor-cell and MEF models. ChIP with p50 and phosphorylated STAT1 across the FAS promoter, EMSA with NF-kappaB subunits including p65, and promoter perturbation support direct canonical NF-kappaB/RelA-associated FAS transcription; the paper also distinguishes an alternate NF-kappaB repressive mechanism. This is a TNF-to-NF-kappaB-to-FAS transcription chain, not a direct TNF-FAS molecular interaction.', 'Promote the direct NF-kappaB/RelA-associated FAS promoter edge in the reported tumor-cell and MEF systems. Link it to TNF only through the measured upstream activation context and preserve the alternate NF-kappaB repressor branch; do not represent TNF as directly binding FAS or assume TNFR subtype specificity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC3408167_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000271' AND x.extraction_id='M22B-P2-R-000239');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000003', 'M22B-EVID-000278', 'P2FALLBACK-22B-M22B-EVID-000278', 'PMCID:PMC4683276', '26499793', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4683276', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMCID:PMC4683276', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC4683276_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000278' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-000278');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000004', 'M22B-EVID-000279', 'M22B-P2-R-000246', 'PMCID:PMC4683276; PMID:26499793; DOI:10.1074/jbc.M115.697615', '26499793', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4683276', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC4683276; PMID:26499793; DOI:10.1074/jbc.M115.697615; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC4683276_full.xml', 'Reuse the PTK7-ROR2-WNT5A observation for the distinct functional output: Ptk7/Ror2-dependent papc expression and convergent-extension/cell-movement phenotypes in Xenopus and mammalian PCP assays. This is a downstream morphogenetic output and does not establish a direct AP-1 target gene.', 'Reuse the primary WNT/PCP morphogenetic and papc expression output as a separate functional context. Do not infer direct AP-1 occupancy, a universal PTK7 receptor mechanism, or SCI-specific repair relevance.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC4683276_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000279' AND x.extraction_id='M22B-P2-R-000246');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000006', 'M22B-EVID-000280', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC4683276_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000280' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000313', 'M22B-EVID-000272', 'M22B-P2-R-000029D', 'PMCID:PMC9807580; PMID:36593298; DOI:10.1038/s41598-022-26674-1', '36593298', 'full_text_xml', 'exact_identifier_match:PMCID:PMC9807580', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC9807580; PMID:36593298; DOI:10.1038/s41598-022-26674-1; https://pmc.ncbi.nlm.nih.gov/articles/PMC9807580/; https://pubmed.ncbi.nlm.nih.gov/36593298/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC9807580_NFKB_NOTCH1.html', 'In activated Jurkat cells and primary mouse CD4+ T cells, RelA-containing NF-κB bound the Notch1 promoter −300 to −270 region by ChIP-qPCR. Serial deletion and internal deletion of this region reduced Notch1 promoter reporter activity, and RelA/p50 overexpression increased Notch1 mRNA and surface protein.', 'The authors conclude that RelA-containing NF-κB directly binds the Notch1 −300 to −270 promoter region and positively regulates Notch1 transcription during T-cell activation.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC9807580_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000272' AND x.extraction_id='M22B-P2-R-000029D');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000313', 'M22B-EVID-000272', 'M22B-P2-R-000240', 'PMCID:PMC9807580; PMID:36593298; DOI:10.1038/s41598-022-26674-1', '36593298', 'full_text_xml', 'exact_identifier_match:PMCID:PMC9807580', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC9807580; PMID:36593298; DOI:10.1038/s41598-022-26674-1; https://pmc.ncbi.nlm.nih.gov/articles/PMC9807580/', 'In activated Jurkat and primary mouse CD4-positive T cells, anti-RelA ChIP-qPCR precipitated the Notch1 promoter -300 to -270 region. RelA/p50 overexpression increased Notch1 promoter reporter activity, Notch1 mRNA, and surface Notch1, while NF-kappaB inhibition reduced Notch1 transcription. EMSA and anti-RelA disruption support sequence-specific RelA-containing NF-kappaB binding. The activating stimulus was TCR/CD3-CD28 or PMA/ionomycin, not TNF.', 'Promote the direct RelA-to-NOTCH1 promoter edge in activated T cells. Preserve the upstream CD28-PI3K-PDK1-NF-kappaB activation context and mark the exact TNF-to-NOTCH1 handoff as unresolved because TNF stimulation was not tested.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMC9807580_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000272' AND x.extraction_id='M22B-P2-R-000240');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch084_PMIDs_274_276_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC2141754_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000104', 'M22B-EVID-000281', 'M22B-P2-R-000247', 'PMCID:PMC3293865; PMID:22403610; DOI:10.1371/journal.pone.0031127', '22403610', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3293865', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_pathway_bounded', 'PMCID:PMC3293865; PMID:22403610; DOI:10.1371/journal.pone.0031127; https://pmc.ncbi.nlm.nih.gov/articles/PMC3293865/', 'WNT5A induced ROR1-dependent signaling in human breast-cancer cells. ROR1 interacted with CK1epsilon and activated PI3K-mediated AKT phosphorylation and CREB phosphorylation; ROR1 silencing reduced CREB-associated gene expression and impaired growth. The source supports a WNT5A-ROR1-PI3K-AKT-CREB tumor-cell program but does not establish CREB occupancy at a specific target gene.', 'Promote the WNT5A-ROR1-CK1epsilon-PI3K-AKT-CREB signaling program and associated breast-tumor growth output. Do not infer direct CREB binding to CCNB1, BCL2, CCND1, or another target from expression and pathway data, and do not transfer this cancer context to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC3293865_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000281' AND x.extraction_id='M22B-P2-R-000247');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000105', 'M22B-EVID-000282', 'M22B-P2-R-000248', 'PMCID:PMC3293865; PMID:22403610; DOI:10.1371/journal.pone.0031127', '22403610', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3293865', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC3293865; PMID:22403610; DOI:10.1371/journal.pone.0031127; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC3293865_full.xml', 'Reuse the validated ROR1 observation for the distinct phenotype: ROR1 silencing increased apoptosis, reduced proliferation and growth of breast-cancer cells in vitro, and reduced tumor growth in immunodeficient mice. This is a cancer-cell phenotype and does not identify a direct CREB target or an SCI repair outcome.', 'Reuse the primary ROR1-dependent tumor-cell survival and growth phenotype as a separate functional context. Do not infer direct CREB target binding, receptor-complex exclusivity, or SCI relevance.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC3293865_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000282' AND x.extraction_id='M22B-P2-R-000248');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000118', 'M22B-EVID-000283', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC3293865_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000283' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000476', 'M22B-EVID-000284', 'M22B-P2-R-000249', 'PMCID:PMC5586543; PMID:28803732; DOI:10.1016/j.neuron.2017.07.031', '28803732', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5586543', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_pathway', 'PMCID:PMC5586543; PMID:28803732; DOI:10.1016/j.neuron.2017.07.031; https://pmc.ncbi.nlm.nih.gov/articles/PMC5586543/', 'RECK and GPR124 formed a WNT7A/WNT7B-specific cell-surface cofactor complex with Frizzled/LRP5/6 context. RECK loss reduced canonical Wnt reporter activity in CNS endothelial cells, while beta-catenin stabilization rescued vascular defects; domain-binding and mutational assays supported physical RECK-GPR124 association and Wnt7-specific coactivation. TCF/LEF reporter output and Axin2-associated canonical Wnt activity were not converted to direct target-gene occupancy.', 'Promote the WNT7A/WNT7B-FZD/LRP5/6-GPR124-RECK canonical signaling complex and its endothelial beta-catenin/TCF-LEF reporter output. Preserve RECK and GPR124 as cofactor nodes rather than treating RECK as a standalone receptor, and do not infer direct TCF/LEF occupancy at a specific endogenous target.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC5586543_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000284' AND x.extraction_id='M22B-P2-R-000249');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000477', 'M22B-EVID-000285', 'M22B-P2-R-000250', 'PMCID:PMC5586543; PMID:28803732; DOI:10.1016/j.neuron.2017.07.031', '28803732', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5586543', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC5586543; PMID:28803732; DOI:10.1016/j.neuron.2017.07.031; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC5586543_full.xml', 'Reuse the validated RECK/GPR124/WNT7 observation for the distinct phenotype: endothelial RECK loss caused CNS angiogenic defects, hemorrhage and blood-brain-barrier impairment, including spinal-cord vascular defects, while canonical beta-catenin stabilization rescued much of the vascular phenotype. This developmental vascular output is not evidence for a direct TCF/LEF target in an SCI repair receiver cell.', 'Reuse the primary CNS angiogenesis and BBB functional output as a separate context. Do not infer direct TCF/LEF target binding, standalone RECK receptor activity, or an SCI repair mechanism from the developmental vascular phenotype.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC5586543_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000285' AND x.extraction_id='M22B-P2-R-000250');
