INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000104', 'M22B-EVID-000281', 'M22B-P2-R-000247', 'PMCID:PMC3293865; PMID:22403610; DOI:10.1371/journal.pone.0031127', '22403610', 'literature_xml', 'exact_identifier_match:PMID:22403610', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_pathway_bounded', 'PMCID:PMC3293865; PMID:22403610; DOI:10.1371/journal.pone.0031127; https://pmc.ncbi.nlm.nih.gov/articles/PMC3293865/', 'WNT5A induced ROR1-dependent signaling in human breast-cancer cells. ROR1 interacted with CK1epsilon and activated PI3K-mediated AKT phosphorylation and CREB phosphorylation; ROR1 silencing reduced CREB-associated gene expression and impaired growth. The source supports a WNT5A-ROR1-PI3K-AKT-CREB tumor-cell program but does not establish CREB occupancy at a specific target gene.', 'Promote the WNT5A-ROR1-CK1epsilon-PI3K-AKT-CREB signaling program and associated breast-tumor growth output. Do not infer direct CREB binding to CCNB1, BCL2, CCND1, or another target from expression and pathway data, and do not transfer this cancer context to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMID22403610_efetch3.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register