INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000118', 'M22B-EVID-000283', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMID22403610_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000283' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000194', 'M22B-EVID-000290', 'M22B-P2-R-000253', 'PMCID:PMC6414217; PMID:29398116; DOI:10.1016/j.cell.2018.01.002', '29398116', 'literature_xml', 'exact_identifier_match:PMID:29398116', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_pathway', 'PMCID:PMC6414217; PMID:29398116; DOI:10.1016/j.cell.2018.01.002; https://pmc.ncbi.nlm.nih.gov/articles/PMC6414217/', 'Dll1 and Dll4 activated Notch1 with different temporal dynamics: Dll1 produced pulsatile signaling that preferentially upregulated Hes1, whereas Dll4 produced sustained signaling that preferentially upregulated Hey1 and HeyL. In C2C12 Notch1 receiver cells with Notch2 knockdown, Dll4 induced substantially more Hey1/HeyL than Dll1 at similar Hes1 levels; the study used reporter, live imaging, qPCR and HCR-FISH, not a new NICD occupancy assay for these target loci.', 'Promote ligand-specific Notch1 signal dynamics leading to distinct Hes1 versus Hey1/HeyL output programs. Keep the dynamic decoding and target-gene expression separate from direct NICD/CSL occupancy, and preserve Dll1/Dll4 context dependence rather than collapsing them into a single Notch branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMID29398116_efetch.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000290' AND x.extraction_id='M22B-P2-R-000253');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000195', 'M22B-EVID-000291', 'M22B-P2-R-000254', 'PMCID:PMC6414217; PMID:29398116; DOI:10.1016/j.cell.2018.01.002', '29398116', 'literature_xml', 'exact_identifier_match:PMID:29398116', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC6414217; PMID:29398116; DOI:10.1016/j.cell.2018.01.002; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMC6414217_full.xml', 'Reuse the validated DLL1/DLL4 observation for the distinct functional output: ectopic Dll1 in chick neural crest increased Hes1 and often MyoD1 in adjacent somites, whereas Dll4 increased Hey1/HeyL and strongly decreased MyoD1, producing opposite myogenic outcomes in the same Notch1-expressing somite population.', 'Reuse the primary chick myogenic differentiation output as a separate functional context. Do not infer direct HES1/HEY1/HEY2 target occupancy, a universal Dll4 mechanism, or SCI relevance.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch085_PMID29398116_efetch.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000291' AND x.extraction_id='M22B-P2-R-000254');
