INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000208', 'M22B-EVID-000208', 'M22B-P2-R-000196', 'PMID:12840057; PMCID:PMC162283; DOI:10.1172/JCI17034; PMID:11959660; DOI:10.1152/ajpheart.00921.2001; PMID:21893328; DOI:10.1016/j.surg.2011.07.013', '12840057', 'full_text_xml', 'exact_identifier_match:PMCID:PMC162283', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_AUTHOR_CLAIM_STAGING:M22B-C-PH2-000207', 'Existing primary observation reused after full-text/abstract validation; no duplicate canonical observation created.', 'Reuse the Del-1 integrin observation for the distinct functional handoff: Del-1 promoted neovascularization and functional recovery in mouse/rabbit ischemic hind limbs and angiogenesis in CAM, while related Del-1-αvβ3 studies reported vascular smooth-muscle adhesion/migration/proliferation and endothelial anti-apoptotic effects through FAK/ERK/Akt.', 'Results; abstracts', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch086_PMC162283_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000208' AND x.extraction_id='M22B-P2-R-000196');
