INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch086_PMC2139816_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000196', 'M22B-EVID-000296', 'M22B-P2-R-000258', 'PMCID:PMC3833432; PMID:24173804; DOI:10.1016/j.molcel.2013.09.008', '24173804', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3833432', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_pathway_bounded', 'PMCID:PMC3833432; PMID:24173804; DOI:10.1016/j.molcel.2013.09.008; https://pmc.ncbi.nlm.nih.gov/articles/PMC3833432/', 'Developing mouse hippocampal pyramidal neurons expressed GDF5 with preferred receptors BMPR1B and BMPR2. GDF5 increased dendrite elongation through SMAD1/5/8 activation and HES5 upregulation; HES5 knockdown and SMAD pathway perturbation supported the program. The study did not establish direct HES5 occupancy at a downstream target gene.', 'Promote the GDF5-BMPR1B/BMPR2-SMAD1/5/8-HES5 dendrite-growth program in developing hippocampal neurons. Keep HES5 expression/reporter output separate from direct HES5 target-gene occupancy and do not transfer the developmental phenotype to SCI repair.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch086_PMC3833432_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000296' AND x.extraction_id='M22B-P2-R-000258');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000197', 'M22B-EVID-000297', 'M22B-P2-R-000259', 'PMCID:PMC3833432; PMID:24173804; DOI:10.1016/j.molcel.2013.09.008', '24173804', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3833432', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC3833432; PMID:24173804; DOI:10.1016/j.molcel.2013.09.008; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch086_PMC3833432_full.xml', 'Reuse the validated GDF5 observation for the distinct phenotype: Gdf5-null and heterozygous mouse hippocampi showed reduced apical and basal dendritic arbor size and complexity, while GDF5 treatment increased dendrite but not axon elongation in cultured pyramidal neurons. This is a developmental neural phenotype, not an SCI repair result.', 'Reuse the primary GDF5-dependent dendrite-growth phenotype as a separate functional context. Do not infer direct HES5 target binding, adult repair relevance, or receptor exclusivity.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch086_PMC3833432_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000297' AND x.extraction_id='M22B-P2-R-000259');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch086_PMC4212947_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000331', 'M22B-EVID-000299', 'M22B-P2-R-000261', 'PMCID:PMC4768137; PMID:26917360; DOI:10.1038/srep22193', '26917360', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4768137', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC4768137; PMID:26917360; DOI:10.1038/srep22193; https://pmc.ncbi.nlm.nih.gov/articles/PMC4768137/', 'In resistin-treated wild-type mice, TLR4-dependent p65/RelA binding to the hepatic Agt promoter increased by ChIP and was absent in Tlr4-null mice. Resistin also increased Agt expression, blood pressure and insulin resistance; perindopril blocked the downstream renin-angiotensin response. This source supports a direct resistin-TLR4-p65-Agt transcriptional chain, but it does not test S100A8/S100A9.', 'Promote the direct p65/RelA-to-Agt promoter edge in the resistin-TLR4 pathway in mouse liver, with Tlr4 dependence. Correct the queued composite wording: this PMID supports resistin, not S100A8/S100A9; do not infer S100A8/S100A9 occupancy or human receptor equivalence from this paper.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch086_PMC4768137_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000299' AND x.extraction_id='M22B-P2-R-000261');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000001', 'M22B-EVID-000309', 'P2FALLBACK-22B-M22B-EVID-000309', 'PMCID:PMC2227265', '15886210', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2227265', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMCID:PMC2227265', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch087_PMC2227265_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000309' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-000309');
