INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000048', 'M22B-EVID-000312', 'M22B-P2-R-000270', 'PMCID:PMC4203348; PMID:14622123; DOI:10.1046/j.1471-4159.2003.02067.x', '14622123', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4203348', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_pathway_bounded', 'PMCID:PMC4203348; PMID:14622123; DOI:10.1046/j.1471-4159.2003.02067.x; https://pmc.ncbi.nlm.nih.gov/articles/PMC4203348/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch087_PMC4203348_full.xml', 'D1 receptor stimulation by dopamine or SKF38393 increased NR1 Ser897 phosphorylation through PKA and increased CREB Ser133 phosphorylation through NMDA-receptor-dependent calcium signaling in primary rat striatal cultures. PKA and CaMK inhibition, NMDA antagonists, and a phosphorylation-deficient NR1 construct blocked CREB phosphorylation or CRE-reporter induction. The study supports a CREB activation program, not direct CREB occupancy at an endogenous target gene.', 'Promote the D1-PKA-NR1/NMDA-Ca2+-CREB/CRE-reporter signaling program in the reported rat striatal models. Do not infer a direct CREB target-gene edge, and preserve the requirement for glutamatergic/NMDA and calcium context.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch087_PMC4203348_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000312' AND x.extraction_id='M22B-P2-R-000270');
