INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000026', 'M22B-EVID-000365', 'M22B-P2-R-000297', 'PMCID:PMC2749879; PMID:19657021; DOI:10.1523/JNEUROSCI.1145-09.2009', '19657021', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2749879', 'candidate_requires_review', NULL, 'L1', 'reuse_validated_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC2749879; PMID:19657021; local=shared observation from M22B-P2-R-000274', 'Reuse the validated 5-HT4-PKA-CREB enteric program for the alternate handoff; no direct CREB target locus was shown.', 'Reuse the validated program without creating a duplicate receptor or direct CREB-target edge.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC2749879_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000365' AND x.extraction_id='M22B-P2-R-000297');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC6725246_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000035', 'M22B-EVID-000329', 'M22B-P2-R-000030B', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC8739224_5HT2A_CREB_targets.html', 'In adult rat neocortex 2 hours after DOI administration, pCREB ChIP-qPCR showed significant enrichment at a putative CRE-containing upstream Arc regulatory region. DOI-induced Arc mRNA was attenuated in 5-HT2A-deficient mice and was completely lost or significantly reduced in CREBαδ knockout mice depending on cortical region, while baseline 5-HT2A receptor expression and DOI-evoked head-twitch behavior were preserved in the CREBαδ model.', 'The authors conclude that DOI-activated 5-HT2A signaling recruits pCREB to the Arc regulatory region and that CREB contributes causally to DOI-induced Arc transcription in rodent neocortex.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000329' AND x.extraction_id='M22B-P2-R-000030B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000035', 'M22B-EVID-000329', 'M22B-P2-R-000276', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml', 'DOI increased pCREB enrichment at a putative Arc promoter CRE in rat cortical neurons and rodent neocortex. DOI-induced Arc expression was attenuated by 5-HT2A antagonism/receptor loss and CREBalpha-delta knockout, supporting a direct pCREB-to-Arc promoter edge.', 'Promote direct pCREB-to-Arc promoter regulation downstream of DOI-activated 5-HT2A in cortical models; keep receptor agonism, occupancy, and broader expression separate and do not transfer to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000329' AND x.extraction_id='M22B-P2-R-000276');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000037', 'M22B-EVID-000330', 'M22B-P2-R-000030C', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC8739224_5HT2A_CREB_targets.html', 'DOI treatment of adult rat neocortex increased pCREB ChIP-qPCR enrichment at a putative CRE-containing Bdnf1 upstream regulatory region and increased Bdnf1 transcript expression. However, DOI-induced Bdnf1 expression was not significantly attenuated in CREBαδ knockout mice, unlike the Arc, Cebpb, and cFos responses.', 'The authors conclude that DOI/5-HT2A stimulation recruits pCREB to the Bdnf1 regulatory region, but the functional CREB-dependence of this DOI-induced Bdnf1 transcript response is incomplete or compensated in the constitutive CREBαδ knockout model.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000330' AND x.extraction_id='M22B-P2-R-000030C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000037', 'M22B-EVID-000330', 'M22B-P2-R-000277', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target_bounded', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml', 'DOI increased pCREB enrichment at a putative Bdnf1 promoter CRE and increased Bdnf1 expression, but CREBalpha-delta knockout did not abolish induction. Occupancy is established while functional CREB necessity remains incomplete.', 'Promote direct pCREB-to-Bdnf1 promoter occupancy downstream of DOI/5-HT2A, with functional CREB dependence bounded because induction persisted in CREBalpha-delta knockout mice. Do not infer endogenous serotonin or SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000330' AND x.extraction_id='M22B-P2-R-000277');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000045', 'M22B-EVID-000331', 'M22B-P2-R-000030D', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC8739224_5HT2A_CREB_targets.html', 'DOI administration increased pCREB enrichment at a putative CRE-containing Cebpb upstream regulatory region in adult rat neocortex. DOI-induced Cebpb mRNA increased in wild-type mice but was lost in CREBαδ knockout mice; the knockout also had lower baseline Cebpb expression.', 'The authors conclude that DOI/5-HT2A stimulation recruits pCREB to the Cebpb regulatory region and that CREB contributes to DOI-induced Cebpb transcription in the tested rodent neocortex.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000331' AND x.extraction_id='M22B-P2-R-000030D');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000045', 'M22B-EVID-000331', 'M22B-P2-R-000278', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml', 'DOI increased pCREB enrichment at a putative Cebpb promoter CRE, and DOI-induced Cebpb expression was lost in CREBalpha-delta knockout mice. Occupancy and genetic dependence support a bounded direct pCREB-to-Cebpb promoter edge.', 'Promote direct pCREB-to-Cebpb promoter regulation downstream of DOI-activated 5-HT2A in cortical models. Keep it distinct from Arc/Bdnf1 and do not infer a direct serotonin-to-CREB edge or SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000331' AND x.extraction_id='M22B-P2-R-000278');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000108', 'M22B-EVID-000332', 'M22B-P2-R-000030E', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC8739224_5HT2A_CREB_targets.html', 'DOI administration increased pCREB enrichment at a putative CRE-containing cFos upstream regulatory region in adult rat neocortex. DOI-induced cFos mRNA increased in wild-type mice but was lost in CREBαδ knockout mice; cFos induction in cultured rat cortical neurons was selectively sensitive to CaMKII inhibition rather than MAPKK inhibition.', 'The authors conclude that DOI/5-HT2A stimulation recruits pCREB to the cFos regulatory region and that CREB contributes to DOI-induced cFos transcription, with CaMKII providing a measured pathway input in cultured cortical neurons.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000332' AND x.extraction_id='M22B-P2-R-000030E');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000108', 'M22B-EVID-000332', 'M22B-P2-R-000279', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml', 'DOI increased pCREB enrichment at a putative cFos promoter CRE in rodent neocortex, and DOI-induced cFos expression was attenuated in CREBalpha-delta knockout mice. The paper also reports 5-HT2A antagonist/receptor-deficient controls, supporting a bounded direct pCREB-to-cFos promoter edge.', 'Promote the direct pCREB-to-cFos promoter edge downstream of DOI-activated 5-HT2A in cortical models. Keep synthetic DOI and endogenous serotonin separate and do not transfer the cortical result to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000332' AND x.extraction_id='M22B-P2-R-000279');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005594', 'M22B-EVID-000333', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000333' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000024', 'M22B-EVID-000340', 'M22B-P2-R-000030A', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; https://pubmed.ncbi.nlm.nih.gov/35002622/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC8739224_5HT2A_CREB_targets.html', 'The synthetic 5-HT2A agonist DOI increased pCREB in primary rat cortical neurons through PLC-linked MAP-kinase and CaMKII pathways; MDL100,907 or PLC inhibition blocked DOI-induced plasticity-gene expression, and U0126 or KN-62 blocked the DOI-induced pCREB increase. DOI-induced gene expression was also reduced in 5-HT2A-deficient mice, establishing a receptor-linked neuronal plasticity program.', 'The authors conclude that DOI-activated 5-HT2A recruits PLC, MAP kinase, and CaMKII signaling to increase CREB phosphorylation and regulate a subset of neuronal plasticity-associated genes.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000340' AND x.extraction_id='M22B-P2-R-000030A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000024', 'M22B-EVID-000340', 'M22B-P2-R-000283', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_functional_program', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; https://pmc.ncbi.nlm.nih.gov/articles/PMC8739224/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml', 'DOI/5-HT2A activation increased pCREB and a neuronal plasticity-associated gene program including Arc, Bdnf1, Cebpb, and cFos in rodent cortical models; pathway inhibitors, receptor loss, and CREB loss separated gene-specific dependence. This is a composite program record and does not replace the separate direct Arc, Bdnf1, Cebpb, and cFos promoter records.', 'Promote the bounded 5-HT2A-PLC/MAPK/CaMKII-pCREB neuronal plasticity program, while pointing to the separate direct promoter records for Arc, Cebpb, cFos, and bounded Bdnf1. Do not infer endogenous serotonin or SCI repair relevance.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000340' AND x.extraction_id='M22B-P2-R-000283');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000035', 'M22B-EVID-000349', 'M22B-P2-R-000287', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'candidate_requires_review', NULL, 'L1', 'reuse_validated_observation', 'REUSE_DIRECT_TF_TARGET', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; local=shared observation from M22B-P2-R-000276', 'Reuse the validated direct pCREB-to-Arc promoter observation from B-22B-032 for the repeated 5-HT2A/DOI handoff. No duplicate Arc edge is created.', 'Reuse the validated direct pCREB-to-Arc promoter edge without duplicating the edge or inferring endogenous serotonin/SCI transfer.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000349' AND x.extraction_id='M22B-P2-R-000287');
