INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000108', 'M22B-EVID-000352', 'M22B-P2-R-000290', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213', '35002622', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8739224', 'candidate_requires_review', NULL, 'L1', 'reuse_validated_observation', 'REUSE_DIRECT_TF_TARGET', 'PMCID:PMC8739224; PMID:35002622; DOI:10.3389/fnmol.2021.790213; local=shared observation from M22B-P2-R-000279', 'Reuse the validated direct pCREB-to-cFos promoter observation from B-22B-033. No duplicate cFos edge is created.', 'Reuse the direct pCREB-to-cFos promoter edge without duplicating the edge or inferring endogenous serotonin/SCI transfer.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch088_PMC8739224_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000352' AND x.extraction_id='M22B-P2-R-000290');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000046', 'M22B-EVID-000336', 'M22B-P2-R-000282', 'PMCID:PMC2614332; PMID:19041748; DOI:10.1016/j.cell.2008.09.059', '19041748', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2614332', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target_bounded', 'PMCID:PMC2614332; PMID:19041748; DOI:10.1016/j.cell.2008.09.059; https://pmc.ncbi.nlm.nih.gov/articles/PMC2614332/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch089_PMC2614332_full.xml', 'Gut-derived serotonin produced through Tph1 acted on Htr1b in mouse osteoblasts, reduced CREB phosphorylation/function, and reduced CycD1 expression and osteoblast proliferation. Serotonin treatment was associated with CREB binding at the consensus CRE in the CycD1 promoter by ChIP, with Htr1b genetic controls and Creb perturbation in the bone pathway.', 'Promote the gut Tph1-serotonin-to-Htr1b osteoblast pathway with CREB binding at the CycD1 promoter and reduced CycD1/proliferation output. Keep the direct CREB-CycD1 promoter record separate from the upstream gut Lrp5-Tph1 endocrine branch and do not transfer the bone phenotype to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch089_PMC2614332_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000336' AND x.extraction_id='M22B-P2-R-000282');
