INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000094', 'M22B-EVID-000348', 'M22B-P2-R-000286', 'PMCID:PMC2956211; PMID:20952540; DOI:10.1101/gad.1977210', '20952540', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2956211', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_receptor_pathway_bounded', 'PMCID:PMC2956211; PMID:20952540; DOI:10.1101/gad.1977210; https://pmc.ncbi.nlm.nih.gov/articles/PMC2956211/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch090_PMC2956211_full.xml', 'Brain-derived serotonin acting through Htr2c in VMH neurons recruited a CaMKKbeta-CaMKIV-CREB pathway that reduced sympathetic tone and increased bone-mass accrual. Htr2c and Tph2 genetic models, serotonin-treated hypothalamic explants, CREB phosphorylation, and microarray/qPCR of Th and Bche supported the program; direct CREB occupancy was not shown.', 'Promote the brain serotonin-Htr2c-CaMKKbeta-CaMKIV-CREB sympathetic/bone program in the reported mouse VMH model. Treat Th/Bche as CREB-regulated expression outputs rather than direct CREB target edges, and do not transfer to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch090_PMC2956211_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000348' AND x.extraction_id='M22B-P2-R-000286');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000094', 'M22B-EVID-000355', 'M22B-P2-R-000293', 'PMCID:PMC2956211; PMID:20952540; DOI:10.1101/gad.1977210', '20952540', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2956211', 'candidate_requires_review', NULL, 'L1', 'reuse_validated_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC2956211; PMID:20952540; local=shared observation from M22B-P2-R-000286', 'Reuse the validated brain serotonin-Htr2c-CaMK-CREB VMH/bone program from B-22B-034; Th and Bche remain expression outputs rather than direct CREB occupancy records.', 'Reuse the validated Htr2c-CREB program without creating a duplicate receptor or direct Th/Bche target edge.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch090_PMC2956211_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000355' AND x.extraction_id='M22B-P2-R-000293');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000240', 'M22B-EVID-000353', 'M22B-P2-R-000291', 'PMCID:PMC3428919; PMID:22120177; DOI:10.1038/nm.2490', '22120177', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3428919', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC3428919; PMID:22120177; DOI:10.1038/nm.2490; https://pmc.ncbi.nlm.nih.gov/articles/PMC3428919/; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch090_PMC3428919_full.xml', 'Serotonin stimulation of rat hepatic stellate cells activated ERK and recruited JunD to the TGF-beta1 promoter by ChIP, increasing TGF-beta1 expression through 5-HT2B. 5-HT2B blockade and ERK inhibition reduced the pathway, and JunD loss altered the injury response.', 'Promote the direct JunD-to-TGF-beta1 promoter edge downstream of serotonin-5-HT2B-ERK in hepatic stellate cells. Keep the liver regeneration/fibrosis output separate and do not transfer the edge to SCI or infer TPH/SLC source dependence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch090_PMC3428919_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000353' AND x.extraction_id='M22B-P2-R-000291');
