INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000856', 'M22B-EVID-000380', 'M22B-P2-R-000307', 'PMCID:PMC3774700; PMID:24052900; DOI:10.4161/adip.24974', '24052900', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3774700', 'candidate_requires_review', 'U', 'L0', 'unresolved_no_evidence', 'UNRESOLVED_PRIMARY_EVIDENCE', 'PMCID:PMC3774700; PMID:24052900; DOI:10.4161/adip.24974; local full text retry_B22B_batch091_PMC3774700_full.xml', 'PMID 24052900 is a secondary Adipocyte review/commentary describing an ALK7/ACVR1C-Smad2/3/4-PPARgamma adipocyte pathway and explicitly stating that the natural ALK7 ligand was not established; it does not establish the queued exact Activin A-ACVR1C-ACVR2A or Activin A-ACVR1C-ACVR2B complex or a primary direct TF-target experiment.', 'No exact Activin A-ACVR1C-ACVR2A/B downstream TF-to-target edge was established after exact PMID, PMC, receptor-pair, ligand, and ALK7/PPARgamma searches; retain the adjacent ALK7-Smad2/3/4-PPARgamma pathway only as secondary context and do not promote it for the queued Activin A edge.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch091_PMC3774700_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000380' AND x.extraction_id='M22B-P2-R-000307');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch091_PMC4190411_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000252', 'M22B-EVID-000390', 'M22B-P2-R-000312', 'PMCID:PMC2701459; PMID:19363165; DOI:10.1124/mol.108.054320', '19363165', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2701459', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_PROMOTER_FUNCTION', 'PMCID:PMC2701459; local full text retry_B22B_batch092_PMC2701459_full.xml', 'Alpha1-adrenergic activation increased IL6 expression and secretion through both mRNA stability and transcriptional regulation; p38 MAPK and NF-kB inhibition reduced the response, and IL6 promoter deletion localized responsive regions containing multiple regulatory elements.', 'Alpha1-adrenergic-p38/NF-kB signaling supports IL6 transcription and secretion in the reported models, but the paper does not establish NF-kB occupancy at endogenous Il6 and does not resolve the submitted alpha1A versus alpha1B/alpha1D handoffs beyond the alpha1-family stimulus.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMC2701459_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000390' AND x.extraction_id='M22B-P2-R-000312');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000122', 'M22B-EVID-000395', 'M22B-P2-R-000316', 'PMCID:PMC2740928; PMID:19477016; DOI:10.1016/j.molimm.2009.04.008', '19477016', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2740928', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_PROMOTER_FUNCTION', 'PMCID:PMC2740928; local full text retry_B22B_batch092_PMC2740928_full.xml', 'Beta3-adrenergic receptor stimulation in adipocytes activated CRE-dependent transcription and increased IL6 expression; p38 and PKC, but not PKA, mediated the response, with CREB and ATF2 phosphorylation downstream of these pathways.', 'Beta3-adrenergic-p38/PKC-CREB/ATF2 signaling supports CRE-dependent IL6 transcription in adipocytes, but no endogenous CREB or ATF2 occupancy at the Il6 locus is shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMC2740928_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000395' AND x.extraction_id='M22B-P2-R-000316');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000038', 'M22B-EVID-000393', 'M22B-P2-R-000314', 'PMCID:PMC3078043; PMID:21143600; DOI:10.1111/j.1471-4159.2010.07137.x', '21143600', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3078043', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC3078043; local full text retry_B22B_batch092_PMC3078043_full.xml', 'Norepinephrine or beta-adrenergic stimulation of cultured striatal neurons caused beta1-dependent CREB phosphorylation through receptor tyrosine-kinase transactivation and Ras/Raf/MEK/MAPK/MSK signaling, with CRE-dependent transcription and c-Fos induction.', 'Beta1-adrenergic activation to RTK-Ras/Raf-MEK-MAPK-MSK-CREB and CRE/c-Fos output is supported in striatal neurons; no direct CREB occupancy at the c-fos locus is established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMC3078043_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000393' AND x.extraction_id='M22B-P2-R-000314');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000205', 'M22B-EVID-000383', 'M22B-P2-R-000308', 'PMCID:PMC3103303; PMID:21464136; DOI:10.1074/jbc.M110.190298', '21464136', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3103303', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_PROMOTER_FUNCTION', 'PMCID:PMC3103303; local full text retry_B22B_batch092_PMC3103303_full.xml', 'Adenosine receptor activation enhanced LPS-induced Pfkfb3 expression and glycolytic flux in macrophages; A2A mediated part of the induction and A2B cooperated at high adenosine. HIF1alpha was required for the basal LPS-linked Pfkfb3 response, while Sp1 activity was required for the synergistic A2-receptor component.', 'A2A/A2B adenosine signaling to HIF1alpha/Sp1-dependent Pfkfb3 promoter function is supported as a cooperative pathway, with A2A contributing at lower adenosine and A2B contributing at high adenosine; no endogenous HIF1alpha or Sp1 occupancy at Pfkfb3 is established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMC3103303_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000383' AND x.extraction_id='M22B-P2-R-000308');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000206', 'M22B-EVID-000385', 'M22B-P2-R-000309', 'PMCID:PMC3103303; PMID:21464136; DOI:10.1074/jbc.M110.190298', '21464136', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3103303', 'candidate_requires_review', NULL, 'L1', 'reuse_validated_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC3103303; local=shared observation from M22B-P2-R-000308', 'Reuse the validated A2A/A2B cooperative adenosine-to-HIF1alpha/Sp1-Pfkfb3 promoter-function observation for the paired A2-family handoff; no duplicate shared pathway edge is created.', 'Reuse the shared A2-family promoter-function program while retaining the paper''s A2A-versus-A2B concentration and cooperation limitations.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMC3103303_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000385' AND x.extraction_id='M22B-P2-R-000309');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000275', 'M22B-EVID-000387', 'M22B-P2-R-000311', 'PMCID:PMC3522188; PMID:21274883; DOI:10.1002/hep.24041', '21274883', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3522188', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC3522188; local full text retry_B22B_batch092_PMC3522188_full.xml', 'Phenylephrine stimulated IP3/Ca2+-dependent proliferation of small mouse cholangiocytes and increased NFAT2, NFAT4, and Sp1 DNA-binding activity and NFAT nuclear translocation; shRNA loss of NFAT2 or Sp1 inhibited the proliferative response.', 'Alpha1-adrenergic-family activation to IP3/Ca2+-calcineurin-NFAT2/Sp1 supports small-cholangiocyte proliferation, but phenylephrine does not isolate ADRA1A from ADRA1B/ADRA1D and no named downstream target locus is established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMC3522188_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000387' AND x.extraction_id='M22B-P2-R-000311');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000136', 'M22B-EVID-000386', 'M22B-P2-R-000310', 'PMCID:PMC3895487; PMID:24352507; DOI:10.1038/ncomms3909', '24352507', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3895487', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_PROMOTER_FUNCTION', 'PMCID:PMC3895487; local full text retry_B22B_batch092_PMC3895487_full.xml', 'Adenosine acting through A2A after LPS/inflammasome priming increased pro-Il1b through a cAMP/PKA/CREB/HIF1alpha pathway; A2A deficiency, HIF1alpha conditional deletion, CREB dominant-negative, and promoter reporters reduced the response.', 'A2A-cAMP/PKA-CREB-HIF1alpha signaling supports IL1B promoter activity and inflammasome-linked IL-1beta production after priming; no endogenous CREB or HIF1alpha occupancy at IL1B is shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMC3895487_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000386' AND x.extraction_id='M22B-P2-R-000310');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000296', 'M22B-EVID-000394', 'M22B-P2-R-000315', 'PMID:15024018; DOI:10.1074/jbc.M313096200', '15024018', 'literature_xml', 'exact_identifier_match:PMID:15024018', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_ENHANCER_FUNCTION_BOUNDED', 'PMID:15024018; DOI:10.1074/jbc.M313096200; local PubMed retry_B22B_batch092_PMID15024018_pubmed.xml', 'Beta2-adrenergic receptor stimulation in CD40L/IL-4-activated B cells increased CREB phosphorylation, OCA-B expression, OCA-B binding to the 3-prime IgH enhancer, and mature IgG1 transcription through a PKA-dependent pathway; OCA-B deficiency eliminated the transcript response.', 'Beta2-adrenergic-PKA-CREB/OCA-B signaling supports 3-prime IgH enhancer function and mature IgG1 transcription, but the study does not establish a direct DNA-binding Oct-2 occupancy-to-IgG1 causal edge under beta2 stimulation; OCA-B is a coactivator.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMID15024018_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000394' AND x.extraction_id='M22B-P2-R-000315');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000034', 'M22B-EVID-000392', 'M22B-P2-R-000313', 'PMID:17680988; DOI:10.1111/j.1471-4159.2007.04852.x', '17680988', 'literature_xml', 'exact_identifier_match:PMID:17680988', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMID:17680988; DOI:10.1111/j.1471-4159.2007.04852.x; local PubMed retry_B22B_batch092_PMID17680988_pubmed.xml', 'Epinephrine stimulation of PC12 cells expressing alpha2-adrenergic receptors increased CREB phosphorylation, CRE-reporter activity, and cyclin D1 expression with subtype-dependent strength alpha2A approximately alpha2C much greater than alpha2B; PLC, arachidonic-acid epoxygenase, and PKA perturbations supported the relay.', 'Alpha2-adrenergic receptor to PLC-arachidonic acid-epoxygenase-cAMP/PKA-CREB signaling is supported as a subtype-biased neuronal differentiation program; cyclin D1 is an expression output, not a direct CREB-target claim.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMID17680988_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000392' AND x.extraction_id='M22B-P2-R-000313');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000106', 'M22B-EVID-000396', 'M22B-P2-R-000317', 'PMID:17680988; DOI:10.1111/j.1471-4159.2007.04852.x', '17680988', 'literature_xml', 'exact_identifier_match:PMID:17680988', 'linked_unresolved', NULL, 'L1', 'reuse_validated_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:17680988; local=shared observation from M22B-P2-R-000313', 'Reuse the validated alpha2 subtype-biased PLC-arachidonic acid-epoxygenase-PKA-CREB PC12 program for the paired alpha2C handoff; no duplicate pathway or direct CREB-target edge is created.', 'Reuse the shared alpha2 observation while retaining the stronger alpha2A/alpha2C-than-alpha2B response and the absence of direct cyclin D1 occupancy evidence.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMID17680988_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000396' AND x.extraction_id='M22B-P2-R-000317');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000123', 'M22B-EVID-000397', 'M22B-P2-R-000318', 'PMID:24947582; DOI:10.1007/s00125-014-3290-0', '24947582', 'literature_xml', 'exact_identifier_match:PMID:24947582', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_PROMOTER_FUNCTION', 'PMID:24947582; DOI:10.1007/s00125-014-3290-0; local PubMed retry_B22B_batch092_PMID24947582_pubmed.xml', 'Adrenaline and isoprenaline increased somatostatin content and transcription through beta1/beta2 adrenergic receptors; parallel Gs-cAMP-PKA-CREB and beta-arrestin1-ERK-PAX6 pathways cooperatively regulated the response, with receptor knockout and CREB/PAX6 perturbation support.', 'Beta1/beta2 adrenergic signaling through Gs-PKA-CREB and beta-arrestin1-ERK-PAX6 supports somatostatin transcription, but the accessible primary record does not establish endogenous CREB or PAX6 occupancy at the Sst locus.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch092_PMID24947582_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000397' AND x.extraction_id='M22B-P2-R-000318');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000295', 'M22B-EVID-000404', 'M22B-P2-R-000321', 'PMCID:PMC11118824; PMID:38790657; DOI:10.3390/antiox13050552', '38790657', 'full_text_xml', 'exact_identifier_match:PMCID:PMC11118824', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC11118824; local full text retry_B22B_batch093_PMC11118824_full.xml', 'ANXA1 or the FPR2 agonist WKYMVm increased SLC7A11/xCT expression and activity, glutathione synthesis, and NRF2 nuclear translocation in human CaLu-6 tumor cells; FPR2 antagonist and NOX inhibition reduced the response.', 'ANXA1-FPR2-NOX/ROS-NRF2 signaling supports an antioxidant SLC7A11/xCT program, but the study does not demonstrate NRF2 occupancy at the SLC7A11 locus or isolate a single direct TF-target edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch093_PMC11118824_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000404' AND x.extraction_id='M22B-P2-R-000321');
