INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000813', 'M22B-EVID-000416', 'M22B-P2-R-000327', 'PMCID:PMC5889092; PMID:29518356; DOI:10.1016/j.neuron.2018.01.031', '29518356', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5889092', 'candidate_requires_review', 'U', 'L0', 'unresolved_no_evidence', 'UNRESOLVED_PRIMARY_EVIDENCE', 'PMCID:PMC5889092; local full text retry_B22B_batch093_PMC5889092_full.xml', 'The primary study establishes beta-amyloid as a TREM2 ligand and shows TREM2-dependent microglial signaling/function, but beta-amyloid derived from APP models is not equivalent to a direct full-length APP-TREM2 interaction and no exact terminal TF-to-target record was established.', 'No exact full-length APP-TREM2-TYROBP terminal TF-to-target edge was established; beta-amyloid/TREM2 results remain adjacent context and are not reassigned to APP as the direct ligand.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch093_PMC5889092_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000416' AND x.extraction_id='M22B-P2-R-000327');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000814', 'M22B-EVID-000401', 'M22B-P2-R-000319', 'PMCID:PMC9928040; PMID:36789429; DOI:10.1101/2023.01.26.525745', '36789429', 'full_text_xml', 'exact_identifier_match:PMCID:PMC9928040', 'candidate_requires_review', 'U', 'L0', 'unresolved_no_evidence', 'UNRESOLVED_PRIMARY_EVIDENCE', 'PMCID:PMC9928040; local full text retry_B22B_batch093_PMC9928040_full.xml', 'The primary preprint shows aldosterone-dependent MR/NR3C2 chromatin binding and transcriptional cooperation with GR/NR3C1 in engineered mouse cells, including MR and GR ChIP-seq, but it does not establish a clean aldosterone-activated NR3C1-to-Cyp11b2 target edge or manipulate CYP11B2 biosynthesis.', 'No exact Aldo-CYP11B2-NR3C1 downstream TF-to-target edge was established. The retrieved primary source supports MR/GR receptor cross-talk and genome-wide chromatin binding, but not the submitted NR3C1-specific terminal target; retain as unresolved and do not promote.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch093_PMC9928040_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000401' AND x.extraction_id='M22B-P2-R-000319');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000289', 'M22B-EVID-000402', 'P2FALLBACK-22B-M22B-EVID-000402', 'PMID:16675527', '16675527', 'literature_xml', 'exact_identifier_match:PMID:16675527', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMID:16675527', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch093_PMID16675527_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000402' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-000402');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000254', 'M22B-EVID-000405', 'M22B-P2-R-000322', 'PMID:22777765; DOI:10.1002/jcp.24156', '22777765', 'literature_xml', 'exact_identifier_match:PMID:22777765', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMID:22777765; DOI:10.1002/jcp.24156; local PubMed retry_B22B_batch093_PMID22777765_pubmed.xml', 'Endogenous ANXA1 silencing or FPR2 blockade in human normal lung fibroblasts increased TNF-induced proliferation and IL6 production while reducing ERK and NF-kB activity; ANXA1/FPR2 effects on TNF-induced inflammatory output were distinct from some glucocorticoid/GILZ effects.', 'ANXA1-FPR2 modulation of TNF-induced ERK/NF-kB inflammatory output is supported, but no direct NF-kB occupancy at the IL6 locus or purified ANXA1-only initiation experiment is established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch093_PMID22777765_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000405' AND x.extraction_id='M22B-P2-R-000322');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000815', 'M22B-EVID-000410', 'M22B-P2-R-000323', 'PMID:27477018; DOI:10.1016/j.neuron.2016.06.015', '27477018', 'literature_xml', 'exact_identifier_match:PMID:27477018', 'candidate_requires_review', 'U', 'L0', 'unresolved_no_evidence', 'UNRESOLVED_PRIMARY_EVIDENCE', 'PMID:27477018; DOI:10.1016/j.neuron.2016.06.015; local PubMed record retrieval 2026-08-21', 'The retrieved primary TREM2 paper establishes binding and microglial uptake for APOE and CLU/APOJ, not a clean isolated ApoA1-triggered TREM2-TYROBP-SYK-to-TF cascade or named endogenous TF target; no exact ApoA1 terminal-TF edge is promoted.', 'No exact ApoA1-TREM2-TYROBP terminal TF-to-target edge was established after exact PMID, ApoA1, TREM2, TYROBP, SYK, and transcription-target searches; APOE/CLU or generic apolipoprotein findings cannot be reassigned to ApoA1.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch093_PMID27477018_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000410' AND x.extraction_id='M22B-P2-R-000323');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000816', 'M22B-EVID-000411', 'M22B-P2-R-000324', 'PMID:27477018; DOI:10.1016/j.neuron.2016.06.015', '27477018', 'literature_xml', 'exact_identifier_match:PMID:27477018', 'candidate_requires_review', 'U', 'L0', 'unresolved_no_evidence', 'UNRESOLVED_PRIMARY_EVIDENCE', 'PMID:27477018; DOI:10.1016/j.neuron.2016.06.015; local PubMed record retrieval 2026-08-21', 'The retrieved primary TREM2 record demonstrates APOE and CLU/APOJ binding and microglial uptake, not isolated ApoA2 as the active ligand or a defined ApoA2-TREM2-TYROBP-SYK-to-TF cascade.', 'No exact ApoA2-TREM2 terminal TF-to-target edge was established; generic apolipoprotein or shared TREM2 evidence cannot be transferred to isolated ApoA2.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch093_PMID27477018_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000411' AND x.extraction_id='M22B-P2-R-000324');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000817', 'M22B-EVID-000413', 'M22B-P2-R-000325', 'PMID:27477018; DOI:10.1016/j.neuron.2016.06.015', '27477018', 'literature_xml', 'exact_identifier_match:PMID:27477018', 'candidate_requires_review', 'U', 'L0', 'unresolved_no_evidence', 'UNRESOLVED_PRIMARY_EVIDENCE', 'PMID:27477018; DOI:10.1016/j.neuron.2016.06.015; local PubMed record retrieval 2026-08-21', 'The retrieved primary TREM2 record does not establish an ApoB-specific TREM2-TYROBP-SYK-to-TF output; binding and uptake findings for APOE/CLU or generic lipoprotein particles cannot be reassigned to ApoB.', 'No exact ApoB-TREM2 terminal TF-to-target edge was established; ApoB isoform and lipoprotein-particle composition remain unresolved in the cited record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch093_PMID27477018_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000413' AND x.extraction_id='M22B-P2-R-000325');
