INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E001814', 'M20B-EVID-005238-P2-FUNC', 'M20B-P2-R-001814-R294B', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200', '18436533', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3258927', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_functional_output_support', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200; https://pubmed.ncbi.nlm.nih.gov/18436533/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3258927/', 'BMP4 treatment of primary human mesenchymal stem cells induced osteogenic markers including ID1, DLX5, IBSP, and PTHR1 and promoted later calcium deposition; receptor knockdown altered the BMP2/4 response.', 'Record BMP4-associated osteogenic differentiation as a cellular output of the context-specific BMPR1A/BMPR2-utilization branch; no terminal TF-to-target edge is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMC3258927_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-005238-P2-FUNC' AND x.extraction_id='M20B-P2-R-001814-R294B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E001814', 'M20B-EVID-005238-P2-RELAY', 'M20B-P2-R-001814-R294A', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200', '18436533', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3258927', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_contextual_receptor_utilization_support', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200; https://pubmed.ncbi.nlm.nih.gov/18436533/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3258927/', 'In primary human mesenchymal stem cells, siRNA receptor-utilization experiments showed that BMP-2/4 osteoinductive signaling used BMPR1A and relied more on BMPR2 than on ACVR2A; BMPR1B and ACVR2B were low/not significant in this model.', 'Promote BMP4–BMPR1A/BMPR2 only as context-specific receptor-utilization/pathway support; do not treat it as purified ternary affinity or transfer the result to BMPR1B/ACVR2B complexes.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMC3258927_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-005238-P2-RELAY' AND x.extraction_id='M20B-P2-R-001814-R294A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E001827', 'M20B-EVID-005239-P2-FUNC', 'M20B-P2-R-001827-R294B', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200', '18436533', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3258927', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_functional_output_support', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200; https://pubmed.ncbi.nlm.nih.gov/18436533/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3258927/', 'BMP6 treatment of primary human mesenchymal stem cells induced osteogenic markers including ID1, DLX5, IBSP, and PTHR1 and promoted later calcium deposition; receptor knockdown altered the BMP6/7 response.', 'Record BMP6-associated osteogenic differentiation as a cellular output of the context-specific ACVR1A/ACVR2A-utilization branch; no terminal TF-to-target edge is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMC3258927_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-005239-P2-FUNC' AND x.extraction_id='M20B-P2-R-001827-R294B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E001827', 'M20B-EVID-005239-P2-RELAY', 'M20B-P2-R-001827-R294A', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200', '18436533', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3258927', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_contextual_receptor_utilization_support', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200; https://pubmed.ncbi.nlm.nih.gov/18436533/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3258927/', 'In primary human mesenchymal stem cells, BMP-6/7 signaling preferentially used ACVR1A as the type-I receptor and relied more on ACVR2A than BMP-2/4 signaling; BMPR1B and ACVR2B were low/not significant in this model.', 'Promote BMP6–ACVR1A/ACVR2A only as context-specific receptor-utilization/pathway support; do not treat it as purified ternary affinity or transfer the result to BMPR1A/ACVR2B alternatives.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMC3258927_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-005239-P2-RELAY' AND x.extraction_id='M20B-P2-R-001827-R294A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E001829', 'M20B-EVID-005242-P2-RELAY', 'M20B-P2-R-001829-R295A', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200', '18436533', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3258927', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_contextual_receptor_utilization_support', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200; https://pubmed.ncbi.nlm.nih.gov/18436533/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3258927/', 'Primary hMSC receptor-utilization experiments placed ACVR1A and BMPR2 among the BMP6/7 signaling receptors; ACVR2A was more critical than BMPR2 for BMP6/7 signaling, so the BMP6-ACVR1A/BMPR2 branch is retained as lower-weight contextual utilization rather than a purified ternary complex.', 'Record BMP6–ACVR1A/BMPR2 as bounded receptor-utilization/pathway context with lower confidence than ACVR1A/ACVR2A; do not infer a stable ternary affinity or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMC3258927_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-005242-P2-RELAY' AND x.extraction_id='M20B-P2-R-001829-R295A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E001830', 'M20B-EVID-005243-P2-RELAY', 'M20B-P2-R-001830-R295A', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200', '18436533', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3258927', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_contextual_receptor_utilization_support', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200; https://pubmed.ncbi.nlm.nih.gov/18436533/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3258927/', 'Primary hMSC receptor-utilization experiments detected a smaller BMPR1A contribution to BMP6/7 osteoinductive signaling and found ACVR2A more critical for BMP6/7 than BMP2/4, supporting a bounded BMP6-BMPR1A/ACVR2A branch.', 'Record BMP6–BMPR1A/ACVR2A as a lower-weight, context-specific receptor-utilization branch; do not promote it to purified ternary binding or a universal BMP6 receptor complex.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMC3258927_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-005243-P2-RELAY' AND x.extraction_id='M20B-P2-R-001830-R295A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E001832', 'M20B-EVID-005259-P2-RELAY', 'M20B-P2-NORM-M20B-EVID-005259-P2-RELAY', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200', '18436533', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3258927', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_primary_claim', 'PMID:18436533; PMCID:PMC3258927; DOI:10.1074/jbc.M800850200; https://pubmed.ncbi.nlm.nih.gov/18436533/', 'Primary hMSC receptor-utilization experiments placed BMPR1A and BMPR2 among BMP6/7-responsive branches, with BMPR2 less strongly supported than ACVR2A.', 'Primary hMSC receptor-utilization experiments placed BMPR1A and BMPR2 among BMP6/7-responsive branches, with BMPR2 less strongly supported than ACVR2A.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMC3258927_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-005259-P2-RELAY' AND x.extraction_id='M20B-P2-NORM-M20B-EVID-005259-P2-RELAY');
