INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004514', 'M22B-EVID-000417', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMID2993292_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000417' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000819', 'M22B-EVID-000418', 'M22B-P2-R-000328', 'PMID:2993292', '2993292', 'literature_xml', 'exact_identifier_match:PMID:2993292', 'candidate_requires_review', 'U', 'L0', 'unresolved_no_evidence', 'UNRESOLVED_PRIMARY_EVIDENCE', 'PMID:2993292; local PubMed retry_B22B_batch094_PMID2993292_pubmed.xml', 'Radioiodinated human beta-endorphin bound rat brain and NG108-15 membranes with high affinity at mu and delta opioid sites but low affinity at kappa sites; the study is a receptor-binding/cross-linking analysis and contains no OPRK1-specific downstream TF or target-gene experiment.', 'No exact beta-endorphin-OPRK1 terminal TF-to-target edge was established; the primary record instead favors mu/delta binding and reports low kappa affinity.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_PMID2993292_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000418' AND x.extraction_id='M22B-P2-R-000328');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_or_bioc_json', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_europepmc_metadata.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch094_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000407', 'M22B-EVID-000461', 'M22B-P2-R-000019A', 'PMCID:PMC12520477; PMID:40755420; DOI:10.1002/advs.202506209', '40755420', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12520477', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC12520477; PMID:40755420; DOI:10.1002/advs.202506209; https://pmc.ncbi.nlm.nih.gov/articles/PMC12520477/; https://pubmed.ncbi.nlm.nih.gov/40755420/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12520477_CCL7_CCR1_STAT1.xml', 'In mouse bone-marrow-derived macrophages, recombinant mouse CCL7 (100 ng/ml, 24 hours) increased STAT1 phosphorylation, inflammatory cytokine secretion, M1 polarization, migration/invasion, glycolysis, and STAT1 K665 succinylation; these effects were reduced in Ccr1-knockout macrophages. Re-expression of CCR1 in Ccr1-knockout cells partially restored inflammatory and metabolic outputs, while STAT1 depletion blocked the rescue. The study supports a CCL7–CCR1–STAT1 pathway branch with KAT2A-dependent STAT1 modification, but it did not demonstrate direct CCL7–CCR1 binding or a canonical JAK1/2 phosphorylation relay.', 'The authors conclude that CCL7–CCR1 activation increases KAT2A-dependent STAT1 K665 succinylation, sustaining STAT1 activity and driving pro-inflammatory macrophage polarization and metabolic reprogramming.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC12520477_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000461' AND x.extraction_id='M22B-P2-R-000019A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000407', 'M22B-EVID-000461', 'M22B-P2-R-000019B', 'PMCID:PMC12520477; PMID:40755420; DOI:10.1002/advs.202506209', '40755420', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12520477', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC12520477; PMID:40755420; DOI:10.1002/advs.202506209; https://pmc.ncbi.nlm.nih.gov/articles/PMC12520477/; https://pubmed.ncbi.nlm.nih.gov/40755420/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC12520477_CCL7_CCR1_STAT1.xml', 'In CCL7-treated mouse BMDMs, STAT1 CUT&Tag showed increased promoter occupancy and ChIP-PCR confirmed STAT1 at HK1, LDHB, and SLC2A1 promoter regions. Dual-luciferase assays validated STAT1-responsive sites, and increased binding was accompanied by increased target-gene mRNA and protein. STAT1 K665R reduced these effects, linking succinylation state to promoter binding and glycolytic-gene regulation. The record supports direct STAT1-to-target-module evidence while retaining HK1/LDHB/SLC2A1 as a gene module rather than claiming every glycolytic gene.', 'The authors conclude that CCL7–CCR1-associated STAT1 K665 succinylation increases STAT1 binding at HK1, LDHB, and SLC2A1 regulatory regions and promotes transcription and translation of this glycolytic target module.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC12520477_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000461' AND x.extraction_id='M22B-P2-R-000019B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000021', 'M22B-EVID-000617', 'M22B-P2-R-000026A', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103', '16606840', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1458887', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103; https://pmc.ncbi.nlm.nih.gov/articles/PMC1458887/; https://pubmed.ncbi.nlm.nih.gov/16606840/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml', 'In NG108-15 neuronal cells, coexpression of dopamine D2R with CLOCK and BMAL1 increased quinpirole-dependent mPer1 promoter-luciferase activity, and haloperidol blocked the response. Deleting the mPer1 CRE did not abolish D2R stimulation, whereas mutation of three E-box elements did. The response was blocked by the MEK inhibitor U0126 and a dominant-negative ERK2, while constitutively active MEK1 mimicked it. Quinpirole also increased CBP recruitment to CLOCK:BMAL1 and CBP phosphorylation without changing CLOCK-BMAL1 association. The study therefore supports a D2R-to-MEK/ERK-to-CLOCK:BMAL1/CBP transcriptional relay, not direct D2R binding to the mPer1 promoter.', 'The authors conclude that D2R signaling potentiates CLOCK:BMAL1-driven mPer1 transcription through a MAPK pathway that increases CBP recruitment and phosphorylation at the CLOCK:BMAL1 complex, with the E-boxes rather than the mPer1 CRE mediating the receptor-dependent response.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC1458887_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000617' AND x.extraction_id='M22B-P2-R-000026A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000021', 'M22B-EVID-000617', 'M22B-P2-R-000026B', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103', '16606840', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1458887', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103; https://pmc.ncbi.nlm.nih.gov/articles/PMC1458887/; https://pubmed.ncbi.nlm.nih.gov/16606840/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1458887_DRD2_CLOCK_BMAL1_mPer1.xml', 'In D2R-null mice, retinal mPer1 oscillatory expression was markedly lower and a 30-minute light pulse at circadian time 18 produced much less mPer1 induction than in wild-type mice. In clock/clock mice expressing transcriptionally inactive CLOCK-Delta19, the same light pulse failed to induce mPer1. These in-vivo data support a physiological requirement for D2R and functional CLOCK:BMAL1 signaling in the retinal mPer1 light-response program.', 'The authors conclude that retinal D2R signaling and a functional CLOCK:BMAL1 complex are required for normal mPer1 oscillation and light-inducibility, establishing an in-vivo dopamine-to-circadian-gene functional branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC1458887_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000617' AND x.extraction_id='M22B-P2-R-000026B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000021', 'M22B-EVID-000617', 'M22B-P2-R-000335', 'PMCID:PMC1458887; PMID:16606840; DOI:10.1073/pnas.0510691103', '16606840', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1458887', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC1458887; local full text retry_B22B_batch095_PMC1458887_full.xml', 'D2 receptor activation enhanced CLOCK:BMAL1-dependent mPer1 reporter transcription through a MAPK/ERK pathway and increased CREB-binding-protein recruitment/phosphorylation; D2R-null retina showed reduced mPer1 expression and light response.', 'D2R-MAPK/ERK signaling supports CLOCK:BMAL1-dependent mPer1 transcription and CREB-binding-protein recruitment, but endogenous CLOCK/BMAL1 occupancy at mPer1 is not established by this study.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC1458887_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000617' AND x.extraction_id='M22B-P2-R-000335');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000821', 'M22B-EVID-000624', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC1458887_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000624' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E001373', 'M22B-EVID-000630', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC1458887_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000630' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000100', 'M22B-EVID-000616', 'M22B-P2-R-000025A', 'PMCID:PMC4207064; PMID:7718243; DOI:10.1016/0896-6273(95)90225-2', '7718243', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4207064', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4207064; PMID:7718243; DOI:10.1016/0896-6273(95)90225-2; https://pmc.ncbi.nlm.nih.gov/articles/PMC4207064/; https://pubmed.ncbi.nlm.nih.gov/7718243/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC4207064_DRD1_CREB_Pdyn.xml', 'In neuron-enriched primary rat embryonic striatal cultures, dopamine/Ro20-1724 induced prodynorphin mRNA and a prodynorphin-CAT reporter containing the three upstream DynCRE elements. Deletion of the two 5-prime DynCREs or all three DynCREs markedly reduced dopamine-responsive CAT activity. Electrophoretic mobility shift and supershift assays with striatal extracts showed CREB-like protein binding to DynCRE1, DynCRE2, and DynCRE3, with CREB antiserum identifying the complex; the putative noncanonical AP-1-like element did not show comparable binding. Dopamine-induced CREB Ser133 phosphorylation and the CREB supershift were blocked by the D1 antagonist SCH-23390, while D1 agonists reproduced the response and D2/D3 agonist quinpirole did not. The record therefore supports a D1-to-CREB-to-DynCRE/Pdyn regulatory branch with direct DNA binding measured in extracts, not endogenous chromatin occupancy.', 'The authors conclude that D1 dopamine receptor stimulation couples through CREB phosphorylation to the three functional upstream prodynorphin CREs and induces prodynorphin transcription in striatal neurons; they reject the putative noncanonical AP-1-like site as the relevant binding element in this primary striatal model.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC4207064_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000616' AND x.extraction_id='M22B-P2-R-000025A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000100', 'M22B-EVID-000616', 'M22B-P2-R-000334', 'PMCID:PMC4207064; PMID:7718243; DOI:10.1016/0896-6273(95)90225-2', '7718243', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4207064', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC4207064; local full text retry_B22B_batch095_PMC4207064_full.xml', 'Dopamine stimulation of primary rat striatal neurons caused D1-dependent CREB Ser133 phosphorylation; CREB bound the three prodynorphin DynCRE elements, and promoter deletion/mutagenesis showed these elements were required for dopamine-responsive Pdyn transcription.', 'Dopamine-D1-cAMP-CREB directly supports CREB binding at the prodynorphin DynCRE elements and dopamine-responsive Pdyn transcription in rat striatal neurons.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC4207064_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000616' AND x.extraction_id='M22B-P2-R-000334');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E001374', 'M22B-EVID-000631', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC4207064_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000631' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000336', 'M22B-EVID-000620', 'M22B-P2-R-000338', 'PMCID:PMC6094125; PMID:30037996; DOI:10.1073/pnas.1800930115', '30037996', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6094125', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC6094125; local full text retry_B22B_batch095_PMC6094125_full.xml', 'Eda/EDAR signaling increased RelB occupancy at the Ltb and human Tnfrsf9 promoter regions and recruited BAF chromatin-remodeling components; RelB, BAF, and Tfg perturbations reduced Eda-induced target transcription. Mouse Tnfrsf9 lacked the relevant NF-kB site in the tested skin context.', 'Eda-A1-EDAR signaling directly supports RelB occupancy and RelB/BAF-dependent transcription at the Ltb promoter; Tnfrsf9 occupancy is human-cell-specific in this study and is not transferred to mouse skin.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC6094125_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000620' AND x.extraction_id='M22B-P2-R-000338');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E001397', 'M22B-EVID-000639', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC6094125_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000639' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000374', 'M22B-EVID-000423', 'M22B-P2-R-000018A', 'PMCID:PMC7617436; PMID:32694734; DOI:10.1038/s42255-020-0214-9', '32694734', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7617436', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC7617436; PMID:32694734; DOI:10.1038/s42255-020-0214-9; https://pmc.ncbi.nlm.nih.gov/articles/PMC7617436/; https://pubmed.ncbi.nlm.nih.gov/32694734/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC7617436_BMP8B_NASH.xml', 'In primary murine hepatic stellate cells, recombinant human BMP8 protein activated both phospho-SMAD2/3 and phospho-SMAD1/5/9 within 30 minutes and induced SMAD-associated target-gene expression after 5 hours. ALK1/2/3/6 inhibition with K02288 and ALK4/5/7 inhibition with A-8301 attenuated the corresponding branch readouts. The experiment supports a BMP8B-associated dual-SMAD pathway in HSCs, but does not identify a unique ACVR1–ACVR2B receptor complex or a direct terminal TF-target interaction.', 'The authors conclude that BMP8B activates both SMAD2/3 and SMAD1/5/9 branches in hepatic stellate cells through ALK-dependent signaling and contributes to the HSC activation program.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC7617436_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000423' AND x.extraction_id='M22B-P2-R-000018A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000374', 'M22B-EVID-000423', 'M22B-P2-R-000018B', 'PMCID:PMC7617436; PMID:32694734; DOI:10.1038/s42255-020-0214-9', '32694734', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7617436', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC7617436; PMID:32694734; DOI:10.1038/s42255-020-0214-9; https://pmc.ncbi.nlm.nih.gov/articles/PMC7617436/; https://pubmed.ncbi.nlm.nih.gov/32694734/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC7617436_BMP8B_NASH.xml', 'Bmp8b deletion in primary mouse HSCs delayed alpha-SMA induction and reduced collagen, pro-inflammatory cytokine, Ccl2/Mcp1, and Ccl5/Rantes expression together with broader inflammatory and TGF-beta pathway activity. In mouse and human NASH models, loss or inhibition of BMP8B reduced HSC activation, inflammation, wound-healing responses, and disease progression; recombinant BMP8 challenged human primary 3D NASH microtissues reproduced pro-inflammatory/fibrotic effects. These are pathway/function outputs, not direct BMP8B receptor binding or terminal TF-target measurements.', 'The authors conclude that BMP8B is a major contributor to hepatic stellate-cell activation and NASH progression by promoting inflammatory and fibrotic responses through its dual SMAD signaling program.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC7617436_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000423' AND x.extraction_id='M22B-P2-R-000018B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000374', 'M22B-EVID-000423', 'M22B-P2-R-000331', 'PMCID:PMC7617436; PMID:32694734; DOI:10.1038/s42255-020-0214-9', '32694734', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7617436', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC7617436; local full text retry_B22B_batch095_PMC7617436_full.xml', 'BMP8B activated both Smad2/3 and Smad1/5/9 branches in hepatic stellate cells and promoted a pro-inflammatory/fibrotic phenotype; Bmp8b loss reduced stellate-cell activation and inflammatory mediators in mouse and human NASH models.', 'BMP8B-Smad2/3 and Smad1/5/9 signaling supports hepatic-stellate inflammatory activation, but exact ACVR1-ACVR2B receptor stoichiometry and a terminal TF-target locus are not established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMC7617436_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000423' AND x.extraction_id='M22B-P2-R-000331');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000137', 'M22B-EVID-000621', 'M22B-P2-R-000339', 'PMID:15245432; DOI:10.1111/j.0022-202X.2004.12645.x', '15245432', 'literature_xml', 'exact_identifier_match:PMID:15245432', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_PROMOTER_FUNCTION', 'PMID:15245432; DOI:10.1111/j.0022-202X.2004.12645.x; local PubMed retry_B22B_batch095_PMID15245432_pubmed.xml', '17beta-estradiol increased GPER1/GPR30-dependent CREB phosphorylation, CRE-like cyclin D2 promoter activity, cyclin D2 expression, and human keratinocyte proliferation; PKA inhibition and GPER1 antisense reduced the response.', 'E2-GPER1/GPR30-cAMP/PKA-CREB supports cyclin D2 promoter activity and keratinocyte proliferation, but the accessible primary record does not establish endogenous CREB chromatin occupancy at the CCND2 locus.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMID15245432_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000621' AND x.extraction_id='M22B-P2-R-000339');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000823', 'M22B-EVID-000627', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMID15245432_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000627' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMID39954359_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000483', 'M22B-EVID-000443', 'M22B-P2-R-000024A', 'PMCID:PMC6972655; PMID:31306552; DOI:10.1111/febs.14998', '31306552', 'literature_xml', 'exact_identifier_match:PMID:8060315', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6972655; PMID:31306552; DOI:10.1111/febs.14998; https://pmc.ncbi.nlm.nih.gov/articles/PMC6972655/; https://pubmed.ncbi.nlm.nih.gov/31306552/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6972655_VDR_CYP24A1.xml; inherited lane anchor=PMID:8060315', 'In six independent patient-derived human normal colon organoid cultures analyzed in three VDR ChIP-seq experiments, 100 nanomolar calcitriol for 2 hours produced VDR-binding peaks that were coincident across all three assays at the CYP24A1 locus. The study assigned peaks to the nearest gene within 10 kb and displayed CYP24A1 as a representative VDR-bound calcitriol target; the ChIP-seq peaks were enriched for the consensus DR3 VDR motif. This is direct VDR-DNA occupancy evidence at the CYP24A1 locus, not a purified calcitriol-VDR affinity assay.', 'The authors conclude that CYP24A1 is among the direct calcitriol/VDR transcriptional targets in human normal colon organoids, based on reproducible VDR ChIP-seq binding and its overlap with the calcitriol-regulated gene set.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMID8060315_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000443' AND x.extraction_id='M22B-P2-R-000024A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000483', 'M22B-EVID-000443', 'M22B-P2-R-000024B', 'PMCID:PMC6972655; PMID:31306552; DOI:10.1111/febs.14998', '31306552', 'literature_xml', 'exact_identifier_match:PMID:8060315', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6972655; PMID:31306552; DOI:10.1111/febs.14998; https://pmc.ncbi.nlm.nih.gov/articles/PMC6972655/; https://pubmed.ncbi.nlm.nih.gov/31306552/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC6972655_VDR_CYP24A1.xml; inherited lane anchor=PMID:8060315', 'In matched patient-derived human normal and tumor colon organoids, 100 nanomolar calcitriol for 96 hours increased CYP24A1 RNA and, in a subset of matched cultures, CYP24A1 protein. RNA-seq identified CYP24A1 among common calcitriol-regulated genes, and VDR ChIP-seq identified CYP24A1 among the 182 genes with binding sites coincident across all three ChIP-seq assays. VDR shRNA suppressed regulation of several calcitriol target genes, but the paper does not report a CYP24A1-specific loss-of-function result.', 'The authors conclude that calcitriol regulates CYP24A1 expression in human colon organoids and that the reproducible VDR-binding signal places CYP24A1 within the direct calcitriol/VDR target program, while acknowledging cell-state and species differences in the broader response.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_PMID8060315_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000443' AND x.extraction_id='M22B-P2-R-000024B');
