INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_smads_extra_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_supplemental_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000034;M21B-E000035;M21B-E000036', 'M21B-EVID-000007', 'M21B-P2-R-000007', 'PMCID:PMC1170167; PMID:9311995', '9311995', 'full_text_html', 'exact_identifier_match:DOI:10.1093/emboj/16.17.5353;PMCID:PMC1170167', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1170167; PMID:9311995; DOI:10.1093/emboj/16.17.5353; https://europepmc.org/articles/PMC1170167?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_TGFBR_SMAD_fulltext_9311995.pdf', 'In TGF-beta1-treated Mv1Lu mink lung epithelial cells, endogenous Smad2 and Smad3 phosphorylation increased (Fig. 3A-B), while Smad4 was constitutively phosphorylated (Fig. 3C). In transfected COS systems, Smad2 and Smad3 associated with kinase-inactive TbetaR-I after TbetaR-II-dependent receptor activation (Fig. 4), Smad2/Smad3 associated with Smad4 after TbetaR-I activation or TGF-beta1 treatment (Fig. 5A-D), and receptor activation increased Smad2-Smad3 association (Fig. 6A-B). TGF-beta1 drove nuclear accumulation of Smad2, Smad3, and Smad4 in Mv1Lu cells (Fig. 7A-F), and Smad2/3/4 combinations produced synergistic p3TPLux transcriptional reporter activity that was inhibited by dominant-negative Smad3 (Fig. 8A-B).', 'The authors conclude that TGF-beta receptor activation phosphorylates Smad2/3, promotes Smad2/3/4 heteromeric complex formation and nuclear translocation, and requires their combined activity for efficient TGF-beta transcriptional signaling. This is receptor-proximal and downstream pathway evidence, not a purified TGF-beta receptor-ligand affinity assay, a unique terminal target-gene occupancy result, or an SCI receiver-cell effect.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B_M21B_EVID007_PMC1170167_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000007' AND x.extraction_id='M21B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000034;M21B-E000035;M21B-E000036', 'M21B-EVID-000007', 'M21B-P2-R-000007', 'PMCID:PMC1170167; PMID:9311995', '9311995', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC1170167', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1170167; PMID:9311995; DOI:10.1093/emboj/16.17.5353; https://europepmc.org/articles/PMC1170167?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_TGFBR_SMAD_fulltext_9311995.pdf', 'In TGF-beta1-treated Mv1Lu mink lung epithelial cells, endogenous Smad2 and Smad3 phosphorylation increased (Fig. 3A-B), while Smad4 was constitutively phosphorylated (Fig. 3C). In transfected COS systems, Smad2 and Smad3 associated with kinase-inactive TbetaR-I after TbetaR-II-dependent receptor activation (Fig. 4), Smad2/Smad3 associated with Smad4 after TbetaR-I activation or TGF-beta1 treatment (Fig. 5A-D), and receptor activation increased Smad2-Smad3 association (Fig. 6A-B). TGF-beta1 drove nuclear accumulation of Smad2, Smad3, and Smad4 in Mv1Lu cells (Fig. 7A-F), and Smad2/3/4 combinations produced synergistic p3TPLux transcriptional reporter activity that was inhibited by dominant-negative Smad3 (Fig. 8A-B).', 'The authors conclude that TGF-beta receptor activation phosphorylates Smad2/3, promotes Smad2/3/4 heteromeric complex formation and nuclear translocation, and requires their combined activity for efficient TGF-beta transcriptional signaling. This is receptor-proximal and downstream pathway evidence, not a purified TGF-beta receptor-ligand affinity assay, a unique terminal target-gene occupancy result, or an SCI receiver-cell effect.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B_M21B_EVID007_PMC1170167_full.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000007' AND x.extraction_id='M21B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B_M22B_EVID004_PMC5621925_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000448', 'M22B-EVID-000007', 'M22B-P2-R-000007', 'PMID:10064602', '10064602', 'full_text_html', 'exact_identifier_match:DOI:10.1093/emboj/18.5.1367;PMCID:PMC1171226', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367; https://pmc.ncbi.nlm.nih.gov/articles/PMC1171226/', 'In human IL-3-dependent F-36P-mpl cells, dominant-negative STAT5 reduced IL-3-dependent growth and cyclin D1 mRNA, while constitutively active STAT5A enabled factor-independent proliferation. STAT5A transactivated a cyclin D1 promoter element near -481 bp, STAT5 bound the element in IL-3-responsive EMSA, and cyclin D1 rescued the dominant-negative STAT5 growth defect.', 'The authors conclude that STAT5 directly regulates the cyclin D1 promoter through a STAT-binding element and contributes, together with Ras, to IL-3-dependent hematopoietic growth.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B_M22B_EVID007_PMC1171226_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000007' AND x.extraction_id='M22B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000448', 'M22B-EVID-000007', 'M22B-P2-R-000007-R096', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367', '10064602', 'full_text_html', 'exact_identifier_match:DOI:10.1093/emboj/18.5.1367;PMCID:PMC1171226', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1171226_STAT5_Ccnd1.html; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch096_pubmed.xml', 'In human IL-3-dependent F-36P-mpl hematopoietic cells, dominant-negative STAT5 or Ras reduced IL-3-dependent growth and cyclin D1 expression; constitutively active STAT5A transactivated the cyclin D1 promoter, mutation of a candidate STAT element at -481 bp reduced activity, and EMSA showed IL-3-responsive STAT5 binding to that element.', 'The primary study directly supports an IL-3-associated STAT5-to-Ccnd1 promoter element and a growth-rescue relationship in hematopoietic models; the exact IL-3 receptor-complex composition, transfer to IL-5/IL-7/IL-9/IL-22 handoffs, and SCI relevance remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_B_M22B_EVID007_PMC1171226_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000007' AND x.extraction_id='M22B-P2-R-000007-R096');
