INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004555', 'M22B-EVID-002606', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B030_pmc3767812.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002606' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004556', 'M22B-EVID-002607', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B030_pmc3767812.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002607' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000101', 'M23B-EVID-000169', 'M23B-P2-R-000163', 'PMID:24039785; PMCID:PMC3767812', '24039785', 'full_text_xml', 'exact_identifier_match:DOI:10.1371/journal.pone.0072607;PMCID:PMC3767812', 'candidate_requires_review', 'B', 'L1', 'unresolved_receptor_specificity', 'unresolved_receptor_specificity', 'PMID:24039785; PMCID:PMC3767812; DOI:10.1371/journal.pone.0072607; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B030_pmids.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B030_pmc3767812.xml; stable source=https://pmc.ncbi.nlm.nih.gov/articles/PMC3767812/', 'The primary PACAP adipogenesis study shows PACAP-induced cAMP accumulation, ERK1/2 phosphorylation, adipogenic differentiation, and C/EBP/PPARgamma-associated outputs in 3T3-L1 cells. PAC1, VPAC1, and VPAC2 are all expressed, and combinations of receptor antagonists alter ERK phosphorylation, but antagonist cross-reactivity and combined perturbation prevent assignment of the observed output specifically to VPAC1.', 'The primary study supports a PACAP receptor-family cAMP-to-ERK adipogenesis branch, but it does not establish a VPAC1-specific downstream edge. Keep the exact PACAP-to-VPAC1 claim unknown unless a receptor-selective perturbation or purified receptor study is recovered.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B030_pmc3767812.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000169' AND x.extraction_id='M23B-P2-R-000163');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000102', 'M23B-EVID-000170', 'M23B-P2-R-000164', 'PMID:15935995; PMID:24039785; PMCID:PMC3767812', '24039785', 'full_text_xml', 'exact_identifier_match:DOI:10.1371/journal.pone.0072607;PMCID:PMC3767812', 'candidate_requires_review', 'B', 'L2', 'unresolved_ligand_and_receptor_specificity', 'unresolved_ligand_and_receptor_specificity', 'PMID:15935995; PMID:24039785; PMCID:PMC3767812; DOI:10.1016/j.brainres.2005.04.077; DOI:10.1371/journal.pone.0072607; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B030_pmids.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B030_pmc3767812.xml; stable sources=https://pubmed.ncbi.nlm.nih.gov/15935995/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3767812/', 'The two primary anchors do not support the exact queued PACAP-to-VPAC2 claim as a single edge. PMID:24039785 reports PACAP-induced cAMP/ERK and adipogenesis in 3T3-L1 cells in which PAC1, VPAC1, and VPAC2 are co-expressed, without a VPAC2-specific endpoint. PMID:15935995 reports VIP, not PACAP, enhancing hippocampal CA1 transmission through VPAC1/VPAC2, with VPAC1-PKC and VPAC2-PKA contributions. The VIP study is relevant receptor-family context but cannot be used as PACAP evidence.', 'The exact PACAP-VPAC2 downstream output remains unknown in this handoff. Retain the PACAP receptor-family adipogenesis observation and the separate VIP-VPAC1/VPAC2 hippocampal observation as related but non-interchangeable evidence; do not merge them into a PACAP-VPAC2 edge.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B030_pmc3767812.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000170' AND x.extraction_id='M23B-P2-R-000164');
