INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005364', 'M22B-EVID-003449', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B032_pmc3323978_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003449' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000134', 'M23B-EVID-000202', 'M23B-P2-R-000174', 'PMCID:PMC3323978; PMID:22411794; PMID:11075810', '22411794', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3323978', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMCID:PMC3323978; PMID:22411794; DOI:10.1073/pnas.1112129109; PMID:11075810; DOI:10.1210/me.14.11.0553; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B032_pmids.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B032_pmc3323978_full.xml; stable source=https://pmc.ncbi.nlm.nih.gov/articles/PMC3323978/', 'The primary EGFR/CAV1 studies support a receptor-proximal scaffold relay. Under hypoxia, HIF-dependent CAV1 upregulation increased caveolae formation, CAV1 association with EGFR, ligand-independent EGFR phosphorylation, Ras-Raf-MEK-ERK activation, and migration/invasion. A complementary caveolin-1 study showed Tyr14 phosphorylation during growth-factor/Src signaling and Grb7 binding, with functional augmentation of EGF-stimulated migration. These are scaffold/pathway observations, not an EGF-CAV1 ligand interaction.', 'The primary studies support CAV1-associated EGFR receptor-proximal signaling with a hypoxia-induced ligand-independent branch and downstream Ras-Raf-MEK-ERK migration/invasion outputs. CAV1 is a scaffold/modulator downstream or alongside EGFR; do not infer a direct EGF-CAV1 molecular edge or treat ligand-independent EGFR activation as EGF stimulation.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B032_pmc3323978_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000202' AND x.extraction_id='M23B-P2-R-000174');
