INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000406', 'M22B-EVID-002692', 'M22B-P2-R-000558', 'PMCID:PMC3582121', '23434592', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3582121', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC3582121; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B034_pmc3582121_full.xml', 'ANGPTL1-associated suppression of SLUG and cancer-cell motility was validated in full text; PMID23434592 is the alternate anchor for the same evidence family. Evidence was extracted at the tested model and assay scope; no stronger direct interaction or TF occupancy is inferred.', 'ANGPTL1-SLUG functional regulation is supported, but direct SLUG occupancy and a receptor-proximal mechanism were not established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B034_pmc3582121_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002692' AND x.extraction_id='M22B-P2-R-000558');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000111', 'M23B-EVID-000179', 'M23B-P2-R-000182', 'PMID:23434592; PMCID:PMC3582121', '23434592', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3582121', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:23434592; PMCID:PMC3582121; DOI:10.1172/JCI64044; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B034_pmids.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B034_pmc3582121_full.xml; stable source=https://pmc.ncbi.nlm.nih.gov/articles/PMC3582121/', 'ANGPTL1 interacted with integrin alpha1beta1 in lung-cancer cells by co-immunoprecipitation, ELISA, and surface-plasmon resonance, with a reported KD of approximately 6.35 x 10^-8 M. ANGPTL1 reduced activated beta1-integrin, FAK, ERK, and AKT signaling and suppressed migration/invasion through an alpha1beta1/FAK/ERK/SP1/miR-630/SLUG branch; integrin alpha1 or beta1 knockdown abolished the ANGPTL1-mediated motility and SLUG effects.', 'The primary study supports a direct ANGPTL1-alpha1beta1 ligand-receptor edge and a separate inhibitory alpha1beta1-FAK-ERK-SP1-miR-630-SLUG motility pathway. The direct binding assays do not by themselves establish every downstream step; keep SLUG/miR-630 and motility outputs distinct from the molecular interaction.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B034_pmc3582121_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000179' AND x.extraction_id='M23B-P2-R-000182');
