INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B035_pmc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000119', 'M23B-EVID-000187', 'M23B-P2-R-000190', 'PMID:17944973; PMCID:PMC11159596; DOI:10.1111/j.1349-7006.2007.00634.x', '17944973', 'full_text_xml', 'exact_identifier_match:PMCID:PMC11159596', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:17944973; PMCID:PMC11159596; DOI:10.1111/j.1349-7006.2007.00634.x; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B035_pmc11159596_full.xml; stable source=https://pmc.ncbi.nlm.nih.gov/articles/PMC11159596/', 'Podoplanin bound CLEC-2 in vitro through a defined extracellular recognition interface. CLEC-2 Fc deletion mutants and podoplanin Fc deletion mutants localized the interaction; the podoplanin disialyl-core1 glycopeptide, O-glycan at Thr52 and the podoplanin stereostructure were required for binding. A synthetic glycopeptide was specifically recognized by CLEC-2, and anti-podoplanin antibody NZ-1 inhibited the interaction and podoplanin-induced platelet aggregation/pulmonary metastasis. Direct podoplanin-CLEC-2 binding is retained separately from the platelet and metastasis outputs.', 'Primary evidence supports a direct podoplanin-CLEC-2 receptor interaction mediated by the podoplanin glycopeptide/protein stereostructure and a defined CLEC-2 extracellular domain. The study also supports separate CLEC-2-dependent platelet aggregation and metastasis outputs, but those outputs do not add a molecular binding edge beyond the mapped interaction. No intracellular CLEC-2 signaling cascade or terminal TF was established in this record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B035_pmc11159596_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000187' AND x.extraction_id='M23B-P2-R-000190');
