INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000155', 'M22B-EVID-000190', 'M22B-P2-R-000183', 'PMID:22134916; PMCID:PMC3285302', '22134916', 'full_text_html', 'exact_identifier_match:PMCID:PMC3285302', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:22134916; PMCID:PMC3285302; https://pmc.ncbi.nlm.nih.gov/articles/PMC3285302/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch075_PMC3285302_full.xml', 'Reuse the validated DPP-integrin-FAK/ERK/ELK1 observation for the distinct phenotype handoff: DPP-coated substrates promoted mesenchymal-cell adhesion, spreading, and terminal odontoblast-like differentiation with increased odontogenic matrix-marker expression, including DMP1 and DSP.', 'Reuse DPP-integrin-ERK-associated odontogenic differentiation and matrix-marker phenotype as a separate functional output. Do not infer direct ELK1 occupancy or transfer the dental phenotype to SCI repair.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B037_pmc3285302_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000190' AND x.extraction_id='M22B-P2-R-000183');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000160', 'M22B-EVID-000191', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B037_pmc3285302_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000191' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000129', 'M23B-EVID-000197', 'M23B-P2-R-000200', 'PMID:22134916; PMCID:PMC3285302; DOI:10.1074/jbc.M111.290080', '22134916', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m111.290080;PMCID:PMC3285302', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:22134916; PMCID:PMC3285302; DOI:10.1074/jbc.M111.290080; local PMC XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B037_pmc_full.xml; local PMC HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B037_pmc3285302_full.html; stable source=https://pmc.ncbi.nlm.nih.gov/articles/PMC3285302/', 'Immobilized dentin phosphoprotein (DPP) used its RGD domain to engage cell-surface integrins containing alphaV and beta1 in C3H10T1/2 mesenchymal cells; membrane-protein capture/immunoblot identified both subunits, beta1 siRNA reduced attachment, and RGD/GRGDS blockade reduced DPP adhesion. DPP induced focal-adhesion/FAK activation and ERK signaling, with ERK-dependent phosphorylation of the transcription factor ELK-1 and odontoblast-like differentiation outputs. No purified DPP-alphaVbeta1 affinity assay was performed.', 'Primary evidence supports a processed DPP-RGD-to-alphaV/beta1 integrin receptor-proximal adhesion and signaling module, with FAK and ERK activation and ELK-1 phosphorylation leading to odontoblast-like differentiation. The receptor assignment is based on cell-surface capture, subunit immunoblot and perturbation rather than purified binary binding; retain alphaV and beta1 as receptor-complex subunits and do not promote a direct affinity edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B037_pmc3285302_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000197' AND x.extraction_id='M23B-P2-R-000200');
