INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000148', 'M23B-EVID-000216', 'M23B-P2-R-000210', 'PMCID:PMC1299195; PMID:17030621; PMCID:PMC1800645; PMID:23844194; PMCID:PMC3699556; DOI:10.1128/MCB.00899-06; DOI:10.1371/journal.pone.0068394', '17030621', 'full_text_html', 'exact_identifier_match:PMCID:PMC1299195', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC1299195; PMID:17030621; PMCID:PMC1800645; PMID:23844194; PMCID:PMC3699556; DOI:10.1128/MCB.00899-06; DOI:10.1371/journal.pone.0068394; https://pmc.ncbi.nlm.nih.gov/articles/PMC1299195/; local full texts=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B040_pmc1299195_full.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B040_hsp90_src_full.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B040_hsp90_conformation_bioc.json', 'HSP90 associates with the ERBB2 kinase domain and restrains ERBB2 catalytic activity, ligand-induced heterodimer formation, and downstream ERK/MAPK signaling. Loss of HSP90 association increases Src-dependent ERBB2 Tyr877 phosphorylation and kinase activity. Independent conformational studies show active ERBB2 kinase conformation supports HSP90/Cdc37 association whereas an inactive conformation disrupts it.', 'HSP90 associates with an intracellular ERBB2 receptor-complex/kinase module and restrains ERBB2 stability, heterodimerization, and catalytic signaling; HSP90 loss permits Src-dependent Tyr877 activation and ERK/MAPK output. This is receptor-proximal chaperone/pathway evidence, not an extracellular ligand-receptor edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B040_pmc1299195_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000216' AND x.extraction_id='M23B-P2-R-000210');
