INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E003388', 'M22B-EVID-004536', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B049_pmc2863204_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-004536' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000226', 'M23B-EVID-000312', 'M23B-P2-R-000254', 'DOI:10.1074/jbc.M109.046672; PMCID:PMC2863204; PMID:20220145', '20220145', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m109.046672;PMCID:PMC2863204', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'DOI:10.1074/jbc.M109.046672; PMCID:PMC2863204; PMID:20220145; https://pmc.ncbi.nlm.nih.gov/articles/PMC2863204/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B049_pmc2863204_full.html', 'PDGF-B stimulation led to PDGFRbeta activation, endocytosis, and LRP1 tyrosine phosphorylation. LRP1 and PDGFRbeta co-localized and co-immunoprecipitated in endosomal compartments; purified PDGFRbeta kinase directly phosphorylated the LRP1 cytoplasmic domain. The study does not establish a direct PDGF-B-LRP1 ligand-binding interaction.', 'Promote the PDGF-BB/PDGFRB-LRP1 endosomal receptor-complex association and direct PDGFRbeta-to-LRP1 cytoplasmic phosphorylation as receptor-proximal relay evidence. Do not create a direct PDGF-BB-LRP1 ligand edge; LRP1 is a co-receptor/endocytic signaling component, not the canonical PDGF kinase receptor.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B049_pmc2863204_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000312' AND x.extraction_id='M23B-P2-R-000254');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000227', 'M23B-EVID-000313', 'M23B-P2-R-000255', 'DOI:10.1074/jbc.M109.046672; PMCID:PMC2863204; PMID:20220145', '20220145', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m109.046672;PMCID:PMC2863204', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'DOI:10.1074/jbc.M109.046672; PMCID:PMC2863204; PMID:20220145; https://pmc.ncbi.nlm.nih.gov/articles/PMC2863204/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B049_pmc2863204_full.html', 'LRP1 expression was required for effective PDGF-mediated ERK activation in mouse embryonic fibroblasts and altered MEK1/2, ERK1, Jun, Rb, and CDK phosphorylation. LRP1 expression also supported PDGF-dependent cell growth, while endosomal PDGFRbeta-LRP1 association and LRP1 phosphorylation required receptor internalization.', 'Promote the PDGF-BB-PDGFRB-LRP1 endosomal pathway to ERK/MEK and cell-growth outputs, with Jun phosphorylation recorded as a downstream pathway readout rather than a direct PDGF-to-TF interaction. Keep this relay distinct from direct PDGF-BB-PDGFRB ligand binding and from the alphaVbeta3 cooperation record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B049_pmc2863204_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000313' AND x.extraction_id='M23B-P2-R-000255');
