INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E003611', 'M22B-EVID-004730', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B055_pmc2064262_ptn_sdc3_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-004730' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000249', 'M23B-EVID-000346', 'M23B-P2-R-000280', 'DOI:10.1083/jcb.200602043; PMCID:PMC2064262; PMID:16908672; PMID:8175719; PMID:9749725', '16908672', 'full_text_xml', 'exact_identifier_match:DOI:10.1083/jcb.200602043;PMCID:PMC2064262', 'candidate_requires_review', 'B', 'L2', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:8175719; DOI:10.1046/j.1460-9568.1998.00082.x; PMID:9749725; PMCID:PMC2064262; DOI:10.1083/jcb.200602043; https://pubmed.ncbi.nlm.nih.gov/8175719/; https://pubmed.ncbi.nlm.nih.gov/9749725/; https://pmc.ncbi.nlm.nih.gov/articles/PMC2064262/; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B055_ptn_sdc3_pmids.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B055_pmc2064262_ptn_sdc3_full.xml', 'Primary evidence identifies N-syndecan/syndecan-3 as a neuronal cell-surface receptor for HB-GAM/pleiotrophin. Affinity-matrix isolation and solid-phase binding found N-syndecan binding to HB-GAM with KD approximately 0.6 nM; the full-text N-syndecan knockout study retains the heparan-sulfate and matrix-associated ligand context. Direct binding is therefore supported for PTN-HS/N-syndecan, not for free SDC3 protein without its glycosaminoglycan context.', 'Retain direct PTN/HB-GAM-syndecan-3 binding with explicit heparan-sulfate, ECM, and matrix-presentation boundaries. Do not split the proteoglycan into free SDC3 or infer direct PTN binding to a different syndecan family member.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B055_pmc2064262_ptn_sdc3_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000346' AND x.extraction_id='M23B-P2-R-000280');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000249', 'M23B-EVID-000347', 'M23B-P2-R-000281', 'DOI:10.1083/jcb.200602043; PMCID:PMC2064262; PMID:16908672', '16908672', 'full_text_xml', 'exact_identifier_match:DOI:10.1083/jcb.200602043;PMCID:PMC2064262', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'DOI:10.1083/jcb.200602043; PMCID:PMC2064262; PMID:16908672; https://pmc.ncbi.nlm.nih.gov/articles/PMC2064262/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B055_pmc2064262_ptn_sdc3_full.xml', 'HB-GAM/PTN matrix presentation induced c-Src phosphorylation in wild-type but not N-syndecan-null embryonic forebrain neurons. N-syndecan was required for HB-GAM-guided haptotactic migration, and N-syndecan cooperated with EGFR at the plasma membrane; EGFR and Src inhibitors blocked the relevant migration enhancement. The relay is receptor-context dependent and does not establish direct PTN-Src binding.', 'Promote the PTN/HB-GAM-to-syndecan-3 receptor-proximal Src/cortactin relay with EGFR co-receptor cooperation in developing neural migration models. Keep EGFR as a co-receptor/crosstalk node and do not create direct PTN-Src or PTN-EGFR molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B055_pmc2064262_ptn_sdc3_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000347' AND x.extraction_id='M23B-P2-R-000281');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000249', 'M23B-EVID-000348', 'P2FALLBACK-23B-M23B-EVID-000348', 'PMCID:PMC2064262', '16908672', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2064262', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC2064262', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B055_pmc2064262_ptn_sdc3_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000348' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000348');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B055_ptn_sdc3_pmids.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000250', 'M23B-EVID-000350', 'M23B-P2-R-000284', 'PMID:10970776; PMCID:PMC1221294', '10970776', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1221294', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1221294; PMID:10970776; https://europepmc.org/articles/PMC1221294?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC1221294_PYY_Y1R_fulltext_10970776.pdf', 'In IEC-6 rat jejunal epithelial cells stably expressing human Y1R, Scatchard analysis of equilibrium 125I-PYY binding reported a Kd of approximately 0.2 nM and approximately 104,000 receptors per cell (Results, Fig. 1). PYY induced time-dependent ERK/MAPK phosphorylation with an early peak at 3 minutes and sustained elevation to 1 hour (Fig. 3); pertussis toxin and alpha-transducin implicate Gi/Go and beta-gamma subunits (Fig. 2). PKC inhibitors blocked PYY-induced MAPK phosphorylation and PYY induced PKCepsilon membrane translocation (Figs. 4-5). Src-family and EGFR tyrosine-kinase inhibitors blocked the PYY-MAPK branch, and PYY increased EGFR tyrosine phosphorylation (Figs. 6-8). PYY stimulated growth of Y1R-expressing cells in an EGFR-kinase-dependent manner (Fig. 9).', 'The authors conclude that PYY activates Y1R-linked Gi/Go and beta-gamma signaling through Src-family kinase, EGFR transactivation, and PKC to produce MAPK activation and epithelial-cell growth. The paper supports a PYY-Y1R cellular binding/relay context; it does not establish direct PYY binding to EGFR or direct PYY-Src/PKC/ERK molecular interactions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B056_pmc1221294_pyy_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000350' AND x.extraction_id='M23B-P2-R-000284');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000251', 'M23B-EVID-001459', 'M23B-P2-R-RETRY-RELIN-APOER2-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'full_text_xml', 'exact_identifier_match:DOI:10.1128/mcb.24.3.1378-1386.2004;PMCID:PMC321426', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'In primary embryonic mouse neurons, bivalent ApoER2- or VLDLR-binding antibodies induced Dab1 tyrosine phosphorylation; Reelin or Fc-RAP receptor clustering activated Src-family kinases and modulated PKB/Akt phosphorylation. Chemical dimerization of Dab1 in HEK293 cells was sufficient for phosphorylation and was inhibited by the Src-family inhibitor PP2.', 'Promote the bounded ApoER2/LRP8 receptor-clustering relay to Dab1 phosphorylation, Src-family activation, and Akt modulation in the tested neuronal and HEK293 systems. Dab1 dimerization is a receptor-independent substrate-activation control, not evidence for direct Reelin-Dab1, Reelin-Src, or Reelin-Akt binding. No terminal TF is identified.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B056_pmc321426_reln_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001459' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-APOER2-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000252', 'M23B-EVID-001460', 'M23B-P2-R-RETRY-RELIN-VLDLR-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'full_text_xml', 'exact_identifier_match:DOI:10.1128/mcb.24.3.1378-1386.2004;PMCID:PMC321426', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'In primary embryonic mouse neurons, bivalent VLDLR-binding antibody and Fc-RAP induced Dab1 tyrosine phosphorylation; Reelin and receptor-clustering agents activated Src-family kinases and modulated PKB/Akt phosphorylation. Chemical dimerization of Dab1 in HEK293 cells was sufficient for phosphorylation and was inhibited by PP2, separating the receptor-clustering relay from direct ligand binding.', 'Promote the bounded VLDLR receptor-clustering relay to Dab1 phosphorylation, Src-family activation, and Akt modulation in the tested neuronal and HEK293 systems. Dab1 dimerization is a receptor-independent substrate-activation control, not evidence for direct Reelin-Dab1, Reelin-Src, or Reelin-Akt binding. No terminal TF is identified.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B056_pmc321426_reln_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001460' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-VLDLR-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000251', 'M23B-EVID-001461', 'M23B-P2-R-RETRY-RELIN-APOER2-BINDING-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'full_text_xml', 'exact_identifier_match:DOI:10.1128/mcb.24.3.1378-1386.2004;PMCID:PMC321426', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'Reelin bound recombinant ApoER2 ligand-binding domain in a quantitative ELISA-based assay; the same paper used receptor-fragment specificity controls and a sandwich assay showing that ApoER2-bound Reelin could bind soluble VLDLR, consistent with multivalent receptor engagement.', 'Promote the bounded recombinant Reelin-ApoER2 association and multivalent receptor-engagement observation. The paper reports similar ApoER2 and VLDLR affinities but this record does not assign a numeric Kd; do not infer direct Reelin-Dab1, Reelin-Src, or terminal-TF binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B056_pmc321426_reln_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001461' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-APOER2-BINDING-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000252', 'M23B-EVID-001462', 'M23B-P2-R-RETRY-RELIN-VLDLR-BINDING-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'full_text_xml', 'exact_identifier_match:DOI:10.1128/mcb.24.3.1378-1386.2004;PMCID:PMC321426', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'Reelin bound recombinant VLDLR ligand-binding domain in a quantitative ELISA-based assay; soluble VLDLR fragments also bound Reelin captured on ApoER2, consistent with multivalent receptor engagement.', 'Promote the bounded recombinant Reelin-VLDLR association and multivalent receptor-engagement observation. The paper reports similar ApoER2 and VLDLR affinities but this record does not assign a numeric Kd; do not infer direct Reelin-Dab1, Reelin-Src, or terminal-TF binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B056_pmc321426_reln_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001462' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-VLDLR-BINDING-000001');
