INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000254', 'M23B-EVID-000362', 'M23B-P2-R-000296', 'DOI:10.1091/mbc.E11-02-0099; PMCID:PMC3183016; PMID:21813734; PMID:33784491', '21813734', 'full_text_xml', 'exact_identifier_match:DOI:10.1091/mbc.e11-02-0099;PMCID:PMC3183016', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'DOI:10.1091/mbc.E11-02-0099; PMCID:PMC3183016; PMID:21813734; https://pmc.ncbi.nlm.nih.gov/articles/PMC3183016/; https://pubmed.ncbi.nlm.nih.gov/21813734/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B059_pmc3183016_sdc2_ptprj_full.xml', 'CD148/PTPRJ signaling from S2ED required Src-family kinase activity and PI3K signaling, including dephosphorylation of the p85 PI3K subunit and potential PI3K-C2beta involvement, to support beta1-integrin-dependent adhesion and cytoskeletal organization. CD148 clustering also generated beta1-integrin-dependent adhesion, while recombinant CD148 did not bind alpha5beta1 in solid-phase assays.', 'Promote the SDC2-CD148/PTPRJ-to-Src/PI3K-C2beta-beta1-integrin receptor-proximal relay. Keep beta1-integrin activation and cytoskeletal organization downstream; do not create direct SDC2-Src, SDC2-PI3K, or SDC2-beta1 molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B059_pmc3183016_sdc2_ptprj_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000362' AND x.extraction_id='M23B-P2-R-000296');
