INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000264', 'M23B-EVID-000387', 'M23B-P2-R-000321', 'PMCID:PMC3001003; PMID:19398782; PMID:20929862; PMID:22442151', '20929862', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3001003', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC3001003; PMID:19398782; PMID:20929862; PMID:22442151; https://pmc.ncbi.nlm.nih.gov/articles/PMC3001003/; https://pubmed.ncbi.nlm.nih.gov/19398782/; https://pubmed.ncbi.nlm.nih.gov/20929862/; https://pubmed.ncbi.nlm.nih.gov/22442151/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B064_pmc3001003_tg2_sdc4_full.xml', 'TG2-FN matrix adhesion required syndecan-4 and beta1-integrin co-signaling, with PKC-alpha proposed as a link to syndecan-2/ROCK and actin organization. The matrix response was RGD-independent and did not require TG2 transamidase activity. The retrieved boundary does not resolve a single SDC4-to-PKC/FAK/integrin ordering across all models.', 'Retain TG2-FN-syndecan-4/beta1-integrin-PKC-alpha/ROCK receptor-proximal matrix signaling as abstract-only. Keep syndecan-2 downstream and do not infer direct TG2-PKC, TG2-ROCK, or TG2-beta1 molecular edges.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B064_pmc3001003_tg2_sdc4_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000387' AND x.extraction_id='M23B-P2-R-000321');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000264', 'M23B-EVID-000388', 'P2FALLBACK-23B-M23B-EVID-000388', 'PMCID:PMC3001003', '20929862', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3001003', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC3001003', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B064_pmc3001003_tg2_sdc4_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000388' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000388');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000699', 'M22B-EVID-005080', 'M22B-P2-R-000690', 'DOI:10.1016/j.jbc.2022.102242', '35810788', 'full_text_xml', 'exact_identifier_match:DOI:10.1016/j.jbc.2022.102242', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'DOI:10.1016/j.jbc.2022.102242; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch062_doi_pubmed.xml', 'DOI-linked primary PubMed record supports the queued receptor, integrin, matrix, or signaling observation; no stronger terminal-TF edge was accepted.', 'The source supports a bounded receptor, matrix, or functional association; no direct TF occupancy or terminal target locus was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B064_pmc9358478_tg2_integrin_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005080' AND x.extraction_id='M22B-P2-R-000690');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000263', 'M23B-EVID-000384', 'M23B-P2-R-000318', 'PMID:35810788; DOI:10.1016/j.jbc.2022.102242; PMCID:PMC9358478; PMID:15691824; DOI:10.1074/jbc.M500962200', '35810788', 'full_text_xml', 'exact_identifier_match:DOI:10.1016/j.jbc.2022.102242;PMCID:PMC9358478', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMID:35810788; DOI:10.1016/j.jbc.2022.102242; PMCID:PMC9358478; PMID:15691824; DOI:10.1074/jbc.M500962200; https://pmc.ncbi.nlm.nih.gov/articles/PMC9358478/; https://pubmed.ncbi.nlm.nih.gov/35810788/; https://pubmed.ncbi.nlm.nih.gov/15691824/; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B064_pmc9358478_tg2_integrin_full.xml; retry_C23B064_tg2_pmids.xml', 'In ovarian cancer cells and patient-derived primary cells, extracellular TG2 in a fibronectin matrix context formed a TG2-FN-integrin cluster and directly interacted with/activated ILK, including ILK Ser246 phosphorylation. TG2/ILK inhibition or knockdown reduced adhesion and growth. A separate chondrocyte study found external GTP-bound TG2 induced beta1-integrin-mediated Rac1 and p38 phosphorylation, preserving a distinct cartilage branch.', 'Promote the TG2-FN-integrin-matrix-to-ILK receptor-proximal branch in ovarian cancer and the separate extracellular-TG2-to-beta1-integrin-Rac1/p38 chondrocyte branch. Do not create a universal direct TG2-beta1 affinity edge or direct TG2-Rac1/p38 molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B064_pmc9358478_tg2_integrin_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000384' AND x.extraction_id='M23B-P2-R-000318');
