INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000270', 'M23B-EVID-000398', 'P2FALLBACK-23B-M23B-EVID-000398', 'PMCID:PMC3110033', '21460247', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3110033', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC3110033', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B066_vegfa_flt1_PMC3110033_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000398' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000398');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000270', 'M23B-EVID-000399', 'M23B-P2-R-000332', 'PMCID:PMC3110033; PMID:21460247', '21460247', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3110033', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3110033; PMID:21460247; DOI:10.1182/blood-2010-09-306928; https://pmc.ncbi.nlm.nih.gov/articles/PMC3110033/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B066_vegfa_flt1_PMC3110033_full.xml', 'In primary endothelial models, PTK7 co-immunoprecipitated with Flt-1 but not KDR/Flk-1 or Flt-4. SPR confirmed the PTK7-Flt-1 interaction and VEGF-A increased the receptor-complex interaction. PTK7 silencing reduced VEGF-induced Flt-1 phosphorylation and downstream FAK and Akt phosphorylation.', 'Promote the PTK7-FLT1 receptor-complex relay and VEGF-A-dependent Flt-1-to-FAK/Akt signaling in vascular endothelial models. Do not create direct VEGFA-PTK7, PTK7-FAK, or VEGFA-Akt molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B066_vegfa_flt1_PMC3110033_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000399' AND x.extraction_id='M23B-P2-R-000332');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000270', 'M23B-EVID-000400', 'M23B-P2-R-000333', 'PMCID:PMC3110033; PMID:21460247; DOI:10.1182/blood-2010-09-306928', '21460247', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3110033', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3110033; PMID:21460247; DOI:10.1182/blood-2010-09-306928; https://pmc.ncbi.nlm.nih.gov/articles/PMC3110033/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B066_vegfa_flt1_PMC3110033_full.xml', 'VEGF-A stimulation of vascular endothelial models produced PTK7/Flt-1-associated migration and angiogenic outputs. PTK7 overexpression enhanced endothelial tube formation, migration, and angiogenesis in vitro, whereas PTK7 silencing reduced VEGF-A-induced migration/angiogenesis and mouse corneal neovascularization.', 'Promote VEGF-A/Flt-1/PTK7-associated endothelial migration and angiogenesis outputs in the tested vascular models. Do not create direct VEGFA-PTK7, VEGFA-FAK, or VEGFA-TF molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B066_vegfa_flt1_PMC3110033_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000400' AND x.extraction_id='M23B-P2-R-000333');
