INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000271', 'M23B-EVID-000401', 'M23B-P2-R-000334', 'PMCID:PMC3158143; PMID:21804034; DOI:10.1073/pnas.1100341108', '21804034', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3158143', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3158143; PMID:21804034; DOI:10.1073/pnas.1100341108; https://pmc.ncbi.nlm.nih.gov/articles/PMC3158143/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B067_vegfa_flk1_nmdar_PMC3158143_full.xml', 'In immature mouse cerebellar granule cells, VEGF stimulation increased surface Flk1/NR2B coclusters and activated Flk1. Flk1 formed a complex with NR1/NR2B, and VEGF-activated Src-family kinases increased NR2B tyrosine phosphorylation; Src inhibition or dominant-negative Src blocked the relay.', 'Promote the VEGFA-Flk1/VEGFR2-to-Src-family-kinase-to-NR2B phosphorylation receptor-proximal relay in immature cerebellar granule cells. Do not infer direct VEGFA-NR2B binding; the Flk1-NR1/NR2B complex is a receptor/channel association.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B067_vegfa_flk1_nmdar_PMC3158143_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000401' AND x.extraction_id='M23B-P2-R-000334');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000271', 'M23B-EVID-000402', 'M23B-P2-R-000335', 'PMCID:PMC3158143; PMID:21804034; DOI:10.1073/pnas.1100341108', '21804034', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3158143', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3158143; PMID:21804034; DOI:10.1073/pnas.1100341108; https://pmc.ncbi.nlm.nih.gov/articles/PMC3158143/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B067_vegfa_flk1_nmdar_PMC3158143_full.xml', 'VEGF enhanced NMDA receptor-mediated currents and calcium influx in immature cerebellar granule cells. VEGF chemotaxis of granule cells was reduced by NMDAR blockade or Flk1 inhibition, and endogenous VEGF-dependent migration in organotypic cerebellar slices was similarly inhibited by Flk1 or NMDAR blockade.', 'Promote VEGFA-Flk1/Src-NR2B-associated enhancement of NMDAR activity and granule-cell migration as downstream functional evidence. Do not create direct VEGFA-NR2B or VEGFA-migration-effector molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B067_vegfa_flk1_nmdar_PMC3158143_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000402' AND x.extraction_id='M23B-P2-R-000335');
