INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000277', 'M23B-EVID-000412', 'M23B-P2-R-000344', 'PMCID:PMC1895591; PMID:16788103; PMID:7523416; DOI:10.1182/blood-2002-03-0806', '16788103', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1895591', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC1895591; PMID:16788103; PMID:7523416; DOI:10.1182/blood-2002-03-0806; https://pmc.ncbi.nlm.nih.gov/articles/PMC1895591/; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_vwf_gpIb_PMC1895591_full.xml and retry_C23B069_vwf_gpIb_7523416_core.json', 'Botrocetin-facilitated VWF binding to platelet GPIb-IX-V initiated signaling that activated alphaIIbbeta3 and platelet aggregation. In the full-text mouse and human platelet study, Btk was required for GPIb-dependent PLCgamma2 phosphorylation, thromboxane A2 production, ATP secretion, ERK1/2 and PKC-associated signaling, and stable arterial thrombus formation; the cited primary abstract separately reports VWF-dependent PI3K and Src activation.', 'Promote VWF-GPIb-IX-V-to-Lyn/Syk/SLP-76/PI3K/Btk/PLCgamma2/PKC-ERK and alphaIIbbeta3 activation as platelet receptor-complex and downstream functional evidence. Do not create direct VWF-alphaIIbbeta3 or VWF-TF molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_vwf_gpIb_PMC1895591_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000412' AND x.extraction_id='M23B-P2-R-000344');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000450', 'M23B-EVID-000630', 'M23B-P2-R-000587', 'PMID:7523416; DOI:10.1074/jbc.269.43.27093; PMCID:PMC1895591', '7523416', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1895591', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:7523416; DOI:10.1074/jbc.269.43.27093; PMCID:PMC1895591; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B121_PMIDs_2104618_7523416_22172944_pubmed.xml', 'vWF stimulation of human platelets induced cytoskeletal association and activation of phosphatidylinositol 3-kinase and pp60c-Src with multiple protein-tyrosine phosphorylation events. The response required platelet stirring/aggregation, was blocked by anti-GPIb antibody, and was absent in platelets lacking the GPIb/IX complex.', 'Promote the bounded vWF→GPIb-IX-V→Src/PI3K/tyrosine-phosphorylation platelet-proximal relay. Preserve the requirement for receptor complex and aggregation context; do not infer a terminal TF or isolated-subunit pathway.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_vwf_gpIb_PMC1895591_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000630' AND x.extraction_id='M23B-P2-R-000587');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000451', 'M23B-EVID-000631', 'M23B-P2-R-000588', 'PMCID:PMC1895591; PMID:7523416; PMID:2104618', '16788103', 'full_text_xml', 'exact_identifier_match:PMCID:PMC1895591', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMCID:PMC1895591; PMID:7523416; PMID:2104618; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B121_PMIDs_2104618_7523416_22172944_pubmed.xml', 'Primary platelet studies link vWF engagement of GPIb/IX to platelet adhesion/activation and cooperation with alphaIIbbeta3 under stirring or aggregation conditions. The vWF/GPIb response is retained as a multimeric platelet receptor branch rather than a free GPIBA output.', 'Promote the bounded vWF–GPIb-IX-V platelet adhesion/activation functional branch with alphaIIbbeta3 cooperation. Do not infer a terminal TF or transfer platelet hemostasis outputs to SCI without separate evidence.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_vwf_gpIb_PMC1895591_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000631' AND x.extraction_id='M23B-P2-R-000588');
