INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000278', 'M23B-EVID-000413', 'M23B-P2-R-000345', 'DOI:10.1186/s12964-020-00646-2; PMCID:PMC7487719; PMID:31907106', '31907106', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7487719', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'DOI:10.1186/s12964-020-00646-2; PMCID:PMC7487719; PMID:31907106; https://pmc.ncbi.nlm.nih.gov/articles/PMC7487719/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_wnt5b_fzd7_PMC7487719_full.xml', 'In human breast-cancer cell systems, Fzd7 co-immunoprecipitated with Wnt5a/b-reactive material and the study used Wnt5b knockdown to test the proposed branch. The primary paper therefore supports a Fzd7-associated Wnt5a/b complex context and Wnt5b-dependent signaling, but the co-IP does not uniquely prove a purified direct WNT5B-FZD7 binary interaction.', 'Retain WNT5B-FZD7 as a contextual/unresolved receptor-association claim with WNT5A/B cross-reactivity explicitly recorded. Do not promote a direct WNT5B-FZD7 affinity edge from the co-IP data alone.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_wnt5b_fzd7_PMC7487719_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000413' AND x.extraction_id='M23B-P2-R-000345');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000278', 'M23B-EVID-000414', 'M23B-P2-R-000346', 'DOI:10.1186/s12964-020-00646-2; PMCID:PMC7487719; PMID:31907106', '31907106', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7487719', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'DOI:10.1186/s12964-020-00646-2; PMCID:PMC7487719; PMID:31907106; https://pmc.ncbi.nlm.nih.gov/articles/PMC7487719/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_wnt5b_fzd7_PMC7487719_full.xml', 'Fzd7 knockdown or Wnt5b knockdown altered the proposed noncanonical branch, including p-STAT3, Smad3, YAP1, and Col6a1-associated readouts. Fzd7/Wnt5b perturbation changed mesenchymal and stemness-associated signaling, but the exact receptor-proximal adaptor sequence was not resolved.', 'Promote the FZD7-associated WNT5B/noncanonical branch to STAT3/Smad3/YAP1/Col6a1-associated signaling as pathway evidence, with WNT5A/B attribution and intermediate adaptors unresolved. Do not infer a direct WNT5B-to-STAT3 or WNT5B-to-YAP1 molecular edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_wnt5b_fzd7_PMC7487719_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000414' AND x.extraction_id='M23B-P2-R-000346');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000278', 'M23B-EVID-000415', 'M23B-P2-R-000347', 'DOI:10.1186/s12964-020-00646-2; PMCID:PMC7487719; PMID:31907106', '31907106', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7487719', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'DOI:10.1186/s12964-020-00646-2; PMCID:PMC7487719; PMID:31907106; https://pmc.ncbi.nlm.nih.gov/articles/PMC7487719/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_wnt5b_fzd7_PMC7487719_full.xml', 'Fzd7 knockdown reduced breast-cancer migration, invasion, mammosphere formation, LGR5-positive subpopulation, xenograft growth, and lung metastasis; Fzd7 overexpression produced opposing phenotypes. Wnt5b knockdown and Col6a1 knockdown disrupted the mesenchymal/stemness phenotype, supporting a downstream functional branch.', 'Promote FZD7/WNT5B-associated breast-cancer migration, invasion, stemness, tumor growth, and metastasis outputs as functional evidence. Keep the WNT5A/B ligand boundary and do not infer direct WNT5B binding to any EMT factor, TF, or Col6a1.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B069_wnt5b_fzd7_PMC7487719_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000415' AND x.extraction_id='M23B-P2-R-000347');
