INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000310', 'M23B-EVID-000459', 'M23B-P2-R-000387', 'PMCID:PMC6729491; PMID:15014111; DOI:10.1523/JNEUROSCI.4711-03.2004', '15014111', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6729491', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC6729491; PMID:15014111; DOI:10.1523/JNEUROSCI.4711-03.2004; https://pubmed.ncbi.nlm.nih.gov/15014111/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B078_PMID15014111_metadata.json', 'Ephrin-B3 promoted adhesion of hippocampal neurons to ephrin-B3-expressing substrates in vitro, and loss of EphB2 abolished this effect. EphB2/EphB3 mutant mice showed persistent hippocampal axon bundling/defasciculation defects, including a phenotype after deletion of the EphB2 cytoplasmic domain, supporting receptor-mediated forward signaling in axon organization.', 'Promote ephrin-B3/EphB2-associated hippocampal adhesion and axon-defasciculation function, with receptor cytoplasmic-domain dependence retained as a forward-signaling boundary. Do not infer a purified ephrin-B3-EphB2 affinity measurement or a direct cytoskeletal molecular edge.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B078_PMC6729491_bioc.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000459' AND x.extraction_id='M23B-P2-R-000387');
