INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000292', 'M23B-EVID-000441', 'M23B-P2-R-000369', 'PMCID:PMC6782661; PMID:10366629; DOI:10.1523/JNEUROSCI.19-12-04962.1999', '10366629', 'full_text_or_bioc_json', 'exact_identifier_match:DOI:10.1523/jneurosci.19-12-04962.1999;PMCID:PMC6782661;PMID:10366629', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC6782661; PMID:10366629; DOI:10.1523/JNEUROSCI.19-12-04962.1999; https://pmc.ncbi.nlm.nih.gov/articles/PMC6782661/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B070_efna1_epha4_PMC6782661_full.xml', 'Ephrin-A4-Fc ligand binding and pull-down assays in postnatal rat striatal tissue detected selective EphA4 association, whereas ephrin-A4 did not bind EphA7 in the corresponding receptor comparison. The observation is a tissue/ectodomain biochemical anchor and does not resolve trans versus cis presentation.', 'Promote ephrin-A4-EphA4 direct tissue-contextual binding with the negative EphA7 boundary. Preserve the Fc/ectodomain and striatal-compartment limitations; do not infer direct ephrin-A4 binding to downstream cytoskeletal effectors.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B079_PMID10366629_metadata.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000441' AND x.extraction_id='M23B-P2-R-000369');
