INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000174', 'M23B-EVID-000248', 'P2FALLBACK-23B-M23B-EVID-000248', 'PMCID:PMC10684450', '38015348', 'full_text_xml', 'exact_identifier_match:PMCID:PMC10684450', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC10684450', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMC10684450_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000248' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000248');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000007', 'M23B-EVID-000008', 'M23B-P2-R-000008', 'PMCID:PMC12394907; PMID:40876929', '40876929', 'full_text_xml', 'exact_identifier_match:PMCID:PMC12394907', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC12394907; PMID:40876929; DOI:10.26508/lsa.202503469; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12394907.html', 'GlcNAc6ST1/GlcNAc6ST4 double-deficient mice showed improved locomotor recovery after SCI, reduced monocyte and monocyte-derived macrophage accumulation and CD68-positive activated macrophage/microglia abundance, increased 5-HT-positive serotonergic fibers and white-matter preservation, and reduced type-I-collagen/ECM gene programs with increased synaptic-plasticity genes.', 'The authors conclude that loss of GlcNAc6ST1 and GlcNAc6ST4 reduces inhibitory glycan/ECM and myeloid inflammatory programs and improves axonal and locomotor recovery after SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMC12394907_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000008' AND x.extraction_id='M23B-P2-R-000008');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000176', 'M23B-EVID-000250', 'P2FALLBACK-23B-M23B-EVID-000250', 'PMCID:PMC3755723', '23966707', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3755723', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMC3755723_ncbi.xml; PMCID:PMC3755723; PMID:23966707', 'After mid-thoracic T8 75-kDyn contusion in Col1a1-GFP mice, Col1alpha1-positive cells accumulated at the lesion from approximately 4-5 days, filled the GFAP-negative injury core by 7 days, persisted through 56 days, and formed the fibrotic-scar population adjacent to the astroglial scar. Light-sheet reconstructions and antigenic profiling placed these cells around larger vessels and distinguished them from NG2-positive pericytes; fibronectin distribution matched the Col1alpha1-positive scar population.', 'The authors conclude that perivascular Col1alpha1-positive fibroblasts are the predominant cellular source and major component of the fibrotic scar after contusive SCI with an intact dura. This supports the registered fibroblast-deposits-ECM-scar unit at the cellular-source and scar-population level; it does not establish secretion or turnover of a specified ECM molecule by an isolated cell.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMC3755723_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000250' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000250');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000177', 'M23B-EVID-000251', 'P2FALLBACK-23B-M23B-EVID-000251', 'PMCID:PMC5871719', '29502968', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5871719', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC5871719', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMC5871719_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000251' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000251');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000005', 'M23B-EVID-000006', 'M23B-P2-R-000006', 'PMCID:PMC7509206; PMID:32957245; DOI:10.1016/j.jmbbm.2020.103953', '32957245', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7509206', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC7509206; PMID:32957245; DOI:10.1016/j.jmbbm.2020.103953; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext/PMC7509206_bioc.json', 'In an approximately 18-week mouse hemi-section SCI model, AFM mapping found a significant reduction in Young''s modulus at the chronic injury core and progressively lower modulus toward the scar center relative to uninjured tissue. The same study documented dense and disorganized nuclei, a CNS-cell-poor fibrotic core bordered by GFAP-positive glial scar, increased vimentin, reduced total sulfated proteoglycans, increased CSPGs, and increased hyaluronan in scar compartments.', 'The authors conclude that chronic hemi-section SCI scar has altered mechanical and extracellular-matrix composition that can shape mechanochemical cell behavior and contribute to an anti-regenerative environment. Retain this as matrix/functional evidence for the fibrotic-scar branch, not as FnEDA-specific receptor or intracellular signaling evidence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMC7509206_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000006' AND x.extraction_id='M23B-P2-R-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000179', 'M23B-EVID-000253', 'P2FALLBACK-23B-M23B-EVID-000253', 'PMCID:PMC7509206', '32957245', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7509206', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC7509206', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMC7509206_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000253' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000253');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000010', 'M23B-EVID-000011', 'M23B-P2-R-000011', 'PMID:28082119', '28082119', 'literature_xml', 'exact_identifier_match:PMID:28082119', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:28082119; DOI:10.1016/j.ajpath.2016.11.010; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_pubmed_m23b_next5.xml', 'The PubMed abstract reports that periostin loss or perturbation altered alphaVbeta3-associated macrophage migration and FAK/Akt-linked scar signaling in a mouse contusive SCI context, with reduced fibrotic scar and inflammatory outcomes. Exact full-text perturbation, receptor-specific necessity, methods, and figure loci remain unavailable.', 'The abstract-level primary claim is that periostin contributes to a macrophage/pericyte-associated fibrotic scar relay involving alphaVbeta3-associated FAK/Akt signaling; full text is required to separate receptor-proximal evidence from functional scar output.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMID28082119_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000011' AND x.extraction_id='M23B-P2-R-000011');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000010', 'M23B-EVID-000011', 'M23B-P2-R-RECOVERY-POSTN-ITGAVB3-SCI-000001', 'PMID:28082119; DOI:10.1016/j.ajpath.2016.11.010', '28082119', 'literature_xml', 'exact_identifier_match:PMID:28082119', 'linked_unresolved', 'B', 'L1', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:28082119; DOI:10.1016/j.ajpath.2016.11.010; https://pubmed.ncbi.nlm.nih.gov/28082119/', 'In mouse traumatic SCI, POSTN expression peaked at 7 days and was predominantly localized to scar-forming pericytes. Recombinant POSTN increased monocyte/macrophage migration and TNF-alpha expression in vitro, which promoted pericyte proliferation; the registered study links this branch to alphaVbeta3-associated scar signaling.', 'The authors conclude that pericyte-derived POSTN promotes scar formation through interaction between pericytes and infiltrating monocytes/macrophages after SCI. The registered alphaVbeta3-associated branch remains receptor-proximal/pathway evidence rather than a purified POSTN–integrin binding claim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMID28082119_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000011' AND x.extraction_id='M23B-P2-R-RECOVERY-POSTN-ITGAVB3-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000011', 'M23B-EVID-000012', 'M23B-P2-R-000012', 'PMID:28082119', '28082119', 'literature_xml', 'exact_identifier_match:PMID:28082119', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:28082119; DOI:10.1016/j.ajpath.2016.11.010; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_pubmed_m23b_next5.xml', 'The PubMed abstract reports that periostin loss reduced fibrotic scar formation and inflammatory outcomes after mouse contusive SCI, including effects involving monocytes/macrophages and pericytes. Exact full-text outcome measures, perturbation schedule, and figure loci remain unavailable.', 'The abstract-level primary claim is that periostin contributes to fibrotic scar and inflammatory functional outcomes after contusive SCI; import-ready promotion requires full-text verification and separation from the receptor-associated relay in EVID-000011.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMID28082119_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000012' AND x.extraction_id='M23B-P2-R-000012');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000011', 'M23B-EVID-000012', 'M23B-P2-R-RECOVERY-POSTN-SCI-FUNCTION-000001', 'PMID:28082119; DOI:10.1016/j.ajpath.2016.11.010; URL:https://ajp.amjpathol.org/article/S0002-9440(16)30531-4/fulltext', '28082119', 'literature_xml', 'exact_identifier_match:PMID:28082119', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_output', 'PMID:28082119; DOI:10.1016/j.ajpath.2016.11.010; https://pubmed.ncbi.nlm.nih.gov/28082119/; https://ajp.amjpathol.org/article/S0002-9440(16)30531-4/fulltext', 'In a mouse traumatic SCI model, Postn expression peaked around 7 days and was concentrated in scar-forming pericytes. Postn deletion reduced lesion-site scar formation by suppressing pericyte proliferation; recombinant POSTN increased monocyte/macrophage migration and their TNF-alpha expression in vitro, which facilitated pericyte proliferation; and pharmacological POSTN blockade reduced scar formation and improved long-term functional outcome. This supports a downstream SCI functional branch without assigning a direct POSTN receptor or intracellular pathway.', 'The authors conclude that POSTN regulates interactive scar formation between pericytes and infiltrating monocytes/macrophages and that inhibiting POSTN reduces scarring and improves functional recovery after SCI. Keep this as downstream functional evidence; the abstract does not establish alphaVbeta3, FAK/Akt, or a terminal TF in this SCI paper.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMID28082119_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000012' AND x.extraction_id='M23B-P2-R-RECOVERY-POSTN-SCI-FUNCTION-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000007', 'M23B-EVID-000008', 'M23B-P2-R-000008', 'PMCID:PMC12394907; PMID:40876929', '40876929', 'literature_xml', 'exact_identifier_match:PMID:40876929', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC12394907; PMID:40876929; DOI:10.26508/lsa.202503469; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12394907.html', 'GlcNAc6ST1/GlcNAc6ST4 double-deficient mice showed improved locomotor recovery after SCI, reduced monocyte and monocyte-derived macrophage accumulation and CD68-positive activated macrophage/microglia abundance, increased 5-HT-positive serotonergic fibers and white-matter preservation, and reduced type-I-collagen/ECM gene programs with increased synaptic-plasticity genes.', 'The authors conclude that loss of GlcNAc6ST1 and GlcNAc6ST4 reduces inhibitory glycan/ECM and myeloid inflammatory programs and improves axonal and locomotor recovery after SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B085_PMID40876929_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000008' AND x.extraction_id='M23B-P2-R-000008');
