INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000185', 'M23B-EVID-000267', 'P2FALLBACK-23B-M23B-EVID-000267', 'PMCID:PMC276084', '9190212', 'full_text_xml', 'exact_identifier_match:PMCID:PMC276084', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC276084', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B087_PMC276084_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000267' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000267');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000555', 'M23B-EVID-000756', 'M23B-P2-R-000713', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:9539703; DOI:10.1073/pnas.95.8.4140; PMID:3315233; DOI:10.1016/0092-8674(87)90104-8', '3315233', 'full_text_xml', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMID:3315233; DOI:10.1016/0092-8674(87)90104-8; PMID:9539703; DOI:10.1073/pnas.95.8.4140; PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMID3315233_ICAM1_LFA1_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMC276084_ICAM1_LFA1_fulltext.xml', 'Primary purified ICAM-1 incorporated into artificial membranes binds LFA-1-positive but not LFA-1-negative cells, with inhibition by anti-ICAM-1 or anti-LFA-1 antibodies. Structural work maps the ICAM-1/LFA-1 interface and its divalent-cation-dependent I-domain geometry; the corrected PMC276084 record adds cell-surface LFA-1 activation/context but is not conflated with the structural paper.', 'Promote the direct ICAM1->ITGAL:ITGB2 (LFA-1) ligand-receptor binding/activation edge, with purified-membrane binding and antibody inhibition. Preserve receptor-complex nomenclature and do not infer a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B087_PMC276084_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000756' AND x.extraction_id='M23B-P2-R-000713');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000556', 'M23B-EVID-000757', 'M23B-P2-R-000714', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:10198043; PMCID:PMC25207; DOI:10.1091/mbc.10.4.861', '9190212', 'full_text_xml', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:10198043; PMCID:PMC25207; DOI:10.1091/mbc.10.4.861; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMC276084_ICAM1_LFA1_fulltext.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMID9190212_ICAM1_LFA1_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMIDs10198043_9539703_ICAM1_LFA1_pubmed.xml', 'Primary LFA-1 studies show that intracellular/cytoskeletal activation controls ICAM-1 binding. Release of LFA-1 from cytoskeletal constraints induces clustering and a high-affinity state, while outside-in ICAM-1 engagement stimulates actin polymerization; chemokine studies show transient LFA-1 avidity activation and alphaL cytoplasmic-tail-dependent regulation.', 'Promote the bounded ICAM1/LFA-1->inside-out integrin affinity/clustering and outside-in actin-polymerization receptor-proximal branch. Keep talin/kindlin/adaptor identity unresolved unless directly measured in a separate record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B087_PMC276084_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000757' AND x.extraction_id='M23B-P2-R-000714');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000557', 'M23B-EVID-000758', 'M23B-P2-R-000715', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:10198043; PMCID:PMC25207; DOI:10.1091/mbc.10.4.861; PMID:9539703', '10198043', 'full_text_xml', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:10198043; PMCID:PMC25207; DOI:10.1091/mbc.10.4.861; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMC276084_ICAM1_LFA1_fulltext.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMIDs10198043_9539703_ICAM1_LFA1_pubmed.xml', 'LFA-1/ICAM-1 engagement supports leukocyte adhesion, with activation-state and cytoskeletal context determining binding strength. Chemokine-triggered LFA-1 activation contributes to monocyte transendothelial chemotaxis, while LFA-1 and Mac-1 have distinct kinetics and contributions.', 'Promote the bounded ICAM1->LFA-1->leukocyte adhesion and chemokine-dependent transendothelial chemotaxis functional branch. Keep LFA-1 distinct from Mac-1 and do not infer a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B087_PMC276084_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000758' AND x.extraction_id='M23B-P2-R-000715');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000184', 'M23B-EVID-001457', 'M23B-P2-R-C23B271-000010', 'PMCID:PMC276084; PMID:9539703; DOI:10.1091/mbc.8.2.341', '9539703', 'full_text_xml', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC276084; PMID:9539703; DOI:10.1091/mbc.8.2.341; https://europepmc.org/articles/PMC276084; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC276084_fulltext_9539703.pdf', 'Activated human lymphocytes and LFA-1 transfectants adhered to ICAM-1-Fc through the complete LFA-1 alphaLbeta2 complex; resting lymphocytes showed weak adhesion unless receptor clustering and/or high-affinity activation was induced.', 'Promote the bounded cellular ICAM1-LFA-1 association at complete alphaLbeta2-complex resolution. Do not treat the result as purified binary affinity, create a free ITGB2 edge, or transfer the tested leukocyte/transfectant context to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B087_PMC276084_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001457' AND x.extraction_id='M23B-P2-R-C23B271-000010');
