INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000461', 'M22B-EVID-000185', 'M22B-P2-R-000179', 'PMID:25561492; PMCID:PMC4281560; DOI:10.1101/gad.253682.114', '25561492', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4281560', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMID:25561492; PMCID:PMC4281560; DOI:10.1101/gad.253682.114; https://pmc.ncbi.nlm.nih.gov/articles/PMC4281560/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch075_PMC4281560_full.xml', 'LM511 engagement of the α6Bβ1 integrin activated nuclear TAZ and TEAD reporter activity in breast-cancer stem-cell models. TAZ knockdown reduced LMα5/LAMA5 RNA and protein; an LMα5 promoter luciferase construct was activated by TAZ; and ChIP detected TAZ at putative TEAD-binding sites in the LMα5 promoter. The source supports a TAZ-associated direct regulatory edge, not a direct LM511-to-promoter interaction.', 'Promote the LM511-α6Bβ1-to-TAZ/TEAD-to-LMα5(LAMA5) positive-feedback record. Retain direct TAZ-associated occupancy of TEAD-motif-containing LMα5 promoter regions and TAZ-dependent promoter activity; do not represent TAZ as a sequence-specific DNA-binding factor or infer direct LM511/CDH11-like promoter binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B090_PMC4281560_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000185' AND x.extraction_id='M22B-P2-R-000179');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000463', 'M22B-EVID-000186', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', NULL, 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B090_PMC4281560_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000186' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000462', 'M22B-EVID-000187', 'M22B-P2-R-000181', 'PMID:25561492; PMCID:PMC4281560; DOI:10.1101/gad.253682.114', '25561492', 'full_text_xml', 'exact_identifier_match:PMCID:PMC4281560', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:25561492; PMCID:PMC4281560; DOI:10.1101/gad.253682.114; https://pmc.ncbi.nlm.nih.gov/articles/PMC4281560/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch075_PMC4281560_full.xml', 'Reuse the validated LM511-α6Bβ1-TAZ observation for the distinct phenotype handoff: LM511 matrix and α6Bβ1-associated TAZ activity supported breast-cancer stem-cell self-renewal, mammosphere formation, and tumor initiation; LMα5 depletion or α6B loss impaired these outputs.', 'Reuse LM511-α6Bβ1-TAZ-associated breast-cancer stem-cell self-renewal and tumor-initiation phenotype as a separate functional output. Do not transfer it to SCI repair or infer direct TEAD target occupancy from the phenotype.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B090_PMC4281560_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000187' AND x.extraction_id='M22B-P2-R-000181');
