INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E002762', 'M22B-EVID-002319', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B090_PMC5580876_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002319' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000068', 'M23B-EVID-000093', 'M23B-P2-R-000093', 'PMID:28879238; PMCID:PMC5580876; DOI:10.1126/sciadv.1701497', '28879238', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5580876', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:28879238; PMCID:PMC5580876; DOI:10.1126/sciadv.1701497; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID28879238.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC5580876/', 'The primary structural study resolved the LM511 integrin-binding fragment and showed that LM511E8 binds recombinant alpha6beta1 from the bottom face of LG1-3. Electron microscopy placed the alpha6beta1 headpiece opposite the coiled-coil extension; cross-linking mapped the laminin gamma1-tail near the beta1 MIDAS, and the gamma1 Glu1607 residue was required for binding. Crystal structure, mutagenesis, disulfide cross-linking, and gamma1-tail peptide inhibition support a direct LM511-alpha6beta1 interface.', 'The primary paper establishes a direct molecular LM511–alpha6beta1 interface in which the laminin gamma1-tail Glu1607 coordinates the beta1 MIDAS region, with the alpha5 LG1-3 structure contributing to the binding surface. This is a direct molecular edge only; no cellular signaling, functional output, SCI model, or TF endpoint was assayed.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B090_PMC5580876_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000093' AND x.extraction_id='M23B-P2-R-000093');
