INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000331', 'M23B-EVID-000487', 'M23B-P2-R-C23B274-000002', 'PMCID:PMC3315466; PMCID:PMC6821389; PMID:11518717', '11518717', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6821389', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC3315466; https://pmc.ncbi.nlm.nih.gov/articles/PMC3315466/; PMCID:PMC6821389; https://pmc.ncbi.nlm.nih.gov/articles/PMC6821389/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B093_PMC3315466_ncbi.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B093_PMC6821389_ncbi.xml', 'E-cadherin extracellular-domain integrity and cell-contact context regulated Igf1r/IGF1R activation; restoring IGF1R signaling rescued blastocyst development in the mouse domain-switch model. In E-cadherin-deficient breast-cancer models, IGF1R/InsR phosphorylation and downstream Akt signaling were increased and were inhibited by IGF1R/InsR pathway inhibitors.', 'Promote an E-cadherin-contextual gate on IGF1R/IGF1-to-PI3K-Akt signaling, preserving receptor-complex regulation, ligand-dependent IGF1R activation, and downstream Akt as separate mechanistic nodes.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B093_PMC6821389_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000487' AND x.extraction_id='M23B-P2-R-C23B274-000002');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000332', 'M23B-EVID-000488', 'M23B-P2-R-C23B274-000003', 'PMCID:PMC3315466; PMCID:PMC6821389; PMID:11518717', '11518717', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6821389', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC3315466; https://pmc.ncbi.nlm.nih.gov/articles/PMC3315466/; PMCID:PMC6821389; https://pmc.ncbi.nlm.nih.gov/articles/PMC6821389/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B093_PMC3315466_ncbi.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B093_PMC6821389_ncbi.xml', 'In mouse embryos, impaired E-cadherin/Igf1r coordination blocked trophectoderm formation, increased apoptosis, and compromised blastocyst survival, while restoring Igf1r signaling rescued development. In E-cadherin-deficient breast-cancer models, IGF1R/InsR inhibition reduced proliferation and tumor-explant growth and increased treatment sensitivity.', 'Promote E-cadherin/IGF1R-associated developmental survival and breast-cancer growth outputs as downstream functional evidence, retaining the opposing context-specific directions and not transferring them to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B093_PMC6821389_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000488' AND x.extraction_id='M23B-P2-R-C23B274-000003');
