INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000328', 'M23B-EVID-000484', 'M23B-P2-R-C23B273-000004', 'PMCID:PMC8794882; DOI:10.1016/j.cell.2021.11.006', '35074920', 'full_text_xml', 'exact_identifier_match:PMCID:PMC8794882', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC8794882; DOI:10.1016/j.cell.2021.11.006; https://pmc.ncbi.nlm.nih.gov/articles/PMC8794882/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B093_PMC8794882_ncbi.xml', 'E-cadherin and EGFR formed a plasma-membrane heterotrimeric receptor-complex arrangement measured by co-immunoprecipitation and quantified FRET. Increased tension on E-cadherin bonds disrupted the complex; soluble EGF was required for mechanically activated EGFR signaling, supporting a force-gated receptor-complex branch rather than an E-cadherin ligand claim.', 'Promote an E-cadherin-EGFR receptor-complex and force-gated EGF/EGFR/MAPK branch at the receptor-proximal level, preserving E-cadherin as a mechanosensory complex component rather than a soluble ligand.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B093_PMC8794882_ncbi.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000484' AND x.extraction_id='M23B-P2-R-C23B273-000004');
