INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005255', 'M22B-EVID-003331', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC9563052_CXCL12_platelet.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003331' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000423', 'M23B-EVID-000597', 'M23B-P2-R-000558', 'PMCID:PMC9563052; PMID:36231020; DOI:10.3390/cells11193059', '36231020', 'full_text_html', 'exact_identifier_match:DOI:10.3390/cells11193059;PMCID:PMC9563052', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC9563052; PMID:36231020; DOI:10.3390/cells11193059; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC9563052_CXCL12_platelet.html', 'The primary platelet-integrin study reports dose-dependent binding of CXCL12 to purified soluble alphaIIbbeta3 in Mn2+-containing conditions, with competition by an alphaIIbbeta3 ligand, and shows that site-2 peptides suppress CXCL12-induced alphaIIbbeta3 activation. This supports a direct CXCL12–complete alphaIIbbeta3 receptor-complex edge and a site-2 allosteric component; no ITGB3-alone interaction is inferred.', 'Promote direct CXCL12 binding to and site-2-mediated activation of the complete platelet alphaIIbbeta3 integrin complex. Retain alphaIIb and beta3 as receptor-complex components and do not create a CXCL12–ITGB3-alone edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC9563052_CXCL12_platelet.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000597' AND x.extraction_id='M23B-P2-R-000558');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000424', 'M23B-EVID-000598', 'M23B-P2-R-000559', 'PMCID:PMC11022931; PMCID:PMC9563052; PMID:35313337; PMID:36231020; DOI:10.1182/blood.2020010140; DOI:10.3390/cells11193059', '36231020', 'full_text_html', 'exact_identifier_match:DOI:10.3390/cells11193059;PMCID:PMC9563052', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC11022931; PMCID:PMC9563052; PMID:35313337; PMID:36231020; DOI:10.1182/blood.2020010140; DOI:10.3390/cells11193059; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC11022931_CXCL12_thrombosis.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC9563052_CXCL12_platelet.html', 'The primary platelet thrombosis study shows that CXCL12 activates CXCR4 and a Btk-involving signaling cascade leading to alphaIIbbeta3 activation, platelet aggregation, and granule release. Pharmacologic CXCR4 antagonism and Btk inhibition reduce CXCL12/collagen or plaque-induced platelet activation, while platelet-specific Cxcl12 deletion attenuates thrombus growth/stability. The separate allosteric study shows CXCL12 can activate alphaIIbbeta3 in cell-free and CXCR4-negative CHO systems; these are distinct receptor-proximal branches and must not be merged.', 'Promote two receptor-proximal records separately: CXCL12→CXCR4→Btk→alphaIIbbeta3 activation in native platelets, and CXCL12→alphaIIbbeta3 site-2 allosteric activation without CXCR4 in purified/CHO systems. Do not collapse extracellular allostery into Btk signaling or assign a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC9563052_CXCL12_platelet.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000598' AND x.extraction_id='M23B-P2-R-000559');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000425', 'M23B-EVID-000599', 'M23B-P2-R-000560', 'PMCID:PMC11022931; PMCID:PMC9563052; PMID:35313337; PMID:36231020; DOI:10.1182/blood.2020010140; DOI:10.3390/cells11193059', '36231020', 'full_text_html', 'exact_identifier_match:DOI:10.3390/cells11193059;PMCID:PMC9563052', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC11022931; PMCID:PMC9563052; PMID:35313337; PMID:36231020; DOI:10.1182/blood.2020010140; DOI:10.3390/cells11193059; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC11022931_CXCL12_thrombosis.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC9563052_CXCL12_platelet.html', 'Platelet-derived CXCL12 deficiency delayed FeCl3-induced arterial occlusion and reduced thrombus growth/stability in mice without prolonging tail bleeding time. CXCR4 antagonism reduced human platelet aggregation induced by collagen or plaque homogenate and reduced plaque-triggered thrombus volume under flow. The alphaIIbbeta3 study separately measured CXCL12-induced integrin activation on purified and CHO-cell-surface alphaIIbbeta3. These are platelet/thrombotic functional outputs, not TF evidence.', 'Promote the bounded CXCL12-CXCR4-alphaIIbbeta3 platelet activation, aggregation, thrombus-growth, and arterial-thrombosis functional branch, while retaining the CXCR4-independent alphaIIbbeta3 allosteric assay as a separate receptor-complex mechanism. Do not assign a terminal TF or transfer platelet outputs to SCI cells.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMC9563052_CXCL12_platelet.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000599' AND x.extraction_id='M23B-P2-R-000560');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B115_PMIDs_35313337_36231020_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
