INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000526', 'M22B-EVID-005378', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', NULL, 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B116_PMC3210559_CXCL16.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005378' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000426', 'M23B-EVID-000600', 'M23B-P2-R-000561', 'PMID:11017100; PMID:17363916; PMID:20181724; PMCID:PMC3210559; DOI:10.1038/79738; DOI:10.1189/jlb.0709482', '20181724', 'full_text_html', 'exact_identifier_match:DOI:10.1189/jlb.0709482;PMCID:PMC3210559', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:11017100; PMID:17363916; PMID:20181724; PMCID:PMC3210559; DOI:10.1038/79738; DOI:10.1189/jlb.0709482; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B116_PMIDs_CXCL16_EDIL3_pubmed.xml', 'Primary CXCL16 studies identify CXCR6 as the receptor for CXCL16 by expression cloning and show that membrane-bound and soluble/cleaved or alternatively spliced CXCL16 forms bind and activate CXCR6-expressing cells. Membrane CXCL16 supports adhesion, while soluble CXCL16 supports chemotaxis; the processing state and ligand presentation mode are part of the receptor-complex identity.', 'Promote CXCL16-CXCR6 ligand-receptor evidence at the complete receptor/presentation-state resolution, keeping membrane adhesion and soluble chemotaxis as distinct outputs. Do not infer a purified affinity constant or an intracellular relay from receptor identification and cell-based binding alone.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B116_PMC3210559_CXCL16.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000600' AND x.extraction_id='M23B-P2-R-000561');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000601', 'M23B-P2-R-000562', 'PMID:11017100; PMID:17363916; PMID:20181724; PMCID:PMC3210559; DOI:10.1038/79738; DOI:10.1189/jlb.0709482', '20181724', 'full_text_html', 'exact_identifier_match:DOI:10.1189/jlb.0709482;PMCID:PMC3210559', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'claim_unresolved_after_primary_search', 'PMID:11017100; PMID:17363916; PMID:20181724; PMCID:PMC3210559; DOI:10.1038/79738; DOI:10.1189/jlb.0709482; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B116_PMIDs_CXCL16_EDIL3_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B116_PMC3210559_CXCL16.html', 'The primary CXCL16/CXCR6 records establish receptor binding, membrane-versus-soluble presentation, shedding, and chemotaxis/adhesion outputs, but do not provide a qualifying CXCR6-specific receptor-proximal phosphorylation, adaptor, second-messenger, or kinase assay. A generic GPCR pathway must not be substituted.', 'Leave the CXCL16-CXCR6 receptor-proximal relay unknown. Do not infer Gi/o, PLC, PI3K, ERK, or a TF from the GPCR identity, chemotaxis, or membrane-adhesion outputs.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B116_PMC3210559_CXCL16.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000601' AND x.extraction_id='M23B-P2-R-000562');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000427', 'M23B-EVID-000602', 'M23B-P2-R-000563', 'PMID:11017100; PMID:17363916; PMID:20181724; PMCID:PMC3210559; DOI:10.1038/79738; DOI:10.1189/jlb.0709482', '20181724', 'full_text_html', 'exact_identifier_match:DOI:10.1189/jlb.0709482;PMCID:PMC3210559', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMID:11017100; PMID:17363916; PMID:20181724; PMCID:PMC3210559; DOI:10.1038/79738; DOI:10.1189/jlb.0709482; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B116_PMC3210559_CXCL16.html', 'Primary CXCL16 studies report binding and chemotactic migration of CXCR6-positive lymphocytes toward soluble CXCL16, adhesion mediated by transmembrane CXCL16, and increased recruitment of CXCR6-positive cells by secreted or cleaved CXCL16 isoforms. The studies support immune-cell recruitment and DC/keratinocyte communication but do not establish a terminal TF.', 'Promote the bounded CXCL16-CXCR6 immune-cell adhesion and chemotaxis/recruitment branch, with membrane-tethered and soluble/secreted CXCL16 kept distinct. Do not assign a CXCR6 intracellular relay or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B116_PMC3210559_CXCL16.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000602' AND x.extraction_id='M23B-P2-R-000563');
