INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000609', 'M23B-P2-R-000570', 'PMID:35227773; DOI:10.1016/j.jhep.2022.02.018; PMCID:PMC3499309', '35227773', 'full_text_html', 'exact_identifier_match:PMCID:PMC3499309', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'claim_unresolved_after_primary_search', 'PMID:35227773; DOI:10.1016/j.jhep.2022.02.018; queue PMCID:PMC3499309 (unrelated profiling paper); local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B117_PMIDs_ephrin_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B117_DOI_10.1016_j.jhep.2022.02.018_EFNA3_EphA2.html', 'The primary HCC abstract supports an EFNA3/EphA2 functional axis under hypoxia, with EFNA3 and EPHA2 knockdown/overexpression and downstream SREBP1/ACLY metabolic effects, but it does not report a direct purified ephrin-A3–EphA2 binding assay or a receptor-complex co-immunoprecipitation result. The queued PMCID:PMC3499309 is a separate 2012 Eph-receptor profiling paper and is not the cited HCC study; it cannot be used to fill this exact-pair gap.', 'Do not promote a direct EFNA3–EphA2 binding edge from the HCC functional axis alone. Retain the EFNA3/EphA2 downstream metabolic/stemness claims for the functional/pathway layer when their dedicated queue records are reviewed; document the queue PMCID mismatch.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B117_PMC3499309_ephrin.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000609' AND x.extraction_id='M23B-P2-R-000570');
