INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000439', 'M23B-EVID-000615', 'M23B-P2-R-000576', 'PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274; PMCID:PMC3941021; PMID:23812375; DOI:10.1038/nsmb.2617', NULL, 'full_text_xml', 'exact_identifier_match:DOI:10.1038/nsmb.2617;PMCID:PMC3941021', 'candidate_requires_review', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274; PMCID:PMC3941021; PMID:23812375; DOI:10.1038/nsmb.2617; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC7261182_EphA5_EphA2_full.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC3941021_EphA5_EphA2_full.xml', 'Primary studies support ephrin-A5 engagement of EphA2 at receptor-complex resolution. Ephrin-A5 DNA nanocalipers shifted in an EphA2 gel assay, while the EphA2/EphA4 structural study reported similar ephrin-A5 binding affinity by SPR and EphA2-dependent adhesion to ephrin-A5-coated stripes. No numeric EphA2 affinity was shown in the structural paper, and nanocaliper binding is multivalent rather than a binary affinity measurement.', 'Promote ephrin-A5–EphA2 receptor-complex engagement at bounded assay resolution. Retain the multivalent/clustered presentation and do not promote a binary EphA2 affinity constant from these records.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC3941021_EphA5_EphA2_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000615' AND x.extraction_id='M23B-P2-R-000576');
