INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000441', 'M23B-EVID-000617', 'M23B-P2-R-000578', 'PMCID:PMC3941021; PMID:23812375; DOI:10.1038/nsmb.2617; PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274', NULL, 'full_text_xml', 'exact_identifier_match:DOI:10.1038/nsmb.2617;PMCID:PMC3941021', 'candidate_requires_review', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3941021; PMID:23812375; DOI:10.1038/nsmb.2617; PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC3941021_EphA5_EphA2_full.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC7261182_EphA5_EphA2_full.xml', 'EphA2-expressing HeLa cells adhered strongly to ephrin-A5-coated stripes, in contrast to stronger cell rounding/collapse with EphA4. In U3013 cells, ephrin-A5 spatial presentation generated distinct EphA2 transcriptional responses, including MAPK, phosphatidylinositol, NOTCH1, actin-cytoskeleton, spliceosome, and cell-cycle pathway enrichment; the reported IgG-clustered stimulus did not change U3013 invasiveness.', 'Promote the context-specific ephrin-A5–EphA2/EphA4 clustering-to-adhesion/cytoskeletal and transcriptional-output branch, preserving the receptor-specific contrast. Do not merge EphA2 adhesion with EphA4 repulsion or infer a terminal TF from pathway enrichment.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC3941021_EphA5_EphA2_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000617' AND x.extraction_id='M23B-P2-R-000578');
