INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000439', 'M23B-EVID-000615', 'M23B-P2-R-000576', 'PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274; PMCID:PMC3941021; PMID:23812375; DOI:10.1038/nsmb.2617', NULL, 'full_text_xml', 'exact_identifier_match:DOI:10.1093/nar/gkaa274;PMCID:PMC7261182', 'candidate_requires_review', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274; PMCID:PMC3941021; PMID:23812375; DOI:10.1038/nsmb.2617; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC7261182_EphA5_EphA2_full.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC3941021_EphA5_EphA2_full.xml', 'Primary studies support ephrin-A5 engagement of EphA2 at receptor-complex resolution. Ephrin-A5 DNA nanocalipers shifted in an EphA2 gel assay, while the EphA2/EphA4 structural study reported similar ephrin-A5 binding affinity by SPR and EphA2-dependent adhesion to ephrin-A5-coated stripes. No numeric EphA2 affinity was shown in the structural paper, and nanocaliper binding is multivalent rather than a binary affinity measurement.', 'Promote ephrin-A5–EphA2 receptor-complex engagement at bounded assay resolution. Retain the multivalent/clustered presentation and do not promote a binary EphA2 affinity constant from these records.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC7261182_EphA5_EphA2_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000615' AND x.extraction_id='M23B-P2-R-000576');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000440', 'M23B-EVID-000616', 'M23B-P2-R-000577', 'PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274', '32352518', 'full_text_xml', 'exact_identifier_match:DOI:10.1093/nar/gkaa274;PMCID:PMC7261182', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC7261182_EphA5_EphA2_full.xml', 'Ephrin-A5 nanocalipers induced EphA2 tyrosine phosphorylation in MDA-MB-231 and U3013 cells after 15-minute stimulation, with the magnitude dependent on nanocaliper spacing and receptor abundance. The study directly measures receptor activation but does not identify a universal downstream kinase or adaptor sequence.', 'Promote the bounded ephrin-A5 spatial presentation→EphA2 tyrosine-phosphorylation receptor-proximal branch. Do not infer Src, FAK, ERK, AKT, or a terminal TF from the receptor phosphorylation readout alone.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC7261182_EphA5_EphA2_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000616' AND x.extraction_id='M23B-P2-R-000577');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000441', 'M23B-EVID-000617', 'M23B-P2-R-000578', 'PMCID:PMC3941021; PMID:23812375; DOI:10.1038/nsmb.2617; PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274', NULL, 'full_text_xml', 'exact_identifier_match:DOI:10.1093/nar/gkaa274;PMCID:PMC7261182', 'candidate_requires_review', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3941021; PMID:23812375; DOI:10.1038/nsmb.2617; PMCID:PMC7261182; PMID:32352518; DOI:10.1093/nar/gkaa274; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC3941021_EphA5_EphA2_full.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC7261182_EphA5_EphA2_full.xml', 'EphA2-expressing HeLa cells adhered strongly to ephrin-A5-coated stripes, in contrast to stronger cell rounding/collapse with EphA4. In U3013 cells, ephrin-A5 spatial presentation generated distinct EphA2 transcriptional responses, including MAPK, phosphatidylinositol, NOTCH1, actin-cytoskeleton, spliceosome, and cell-cycle pathway enrichment; the reported IgG-clustered stimulus did not change U3013 invasiveness.', 'Promote the context-specific ephrin-A5–EphA2/EphA4 clustering-to-adhesion/cytoskeletal and transcriptional-output branch, preserving the receptor-specific contrast. Do not merge EphA2 adhesion with EphA4 repulsion or infer a terminal TF from pathway enrichment.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B119_PMC7261182_EphA5_EphA2_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000617' AND x.extraction_id='M23B-P2-R-000578');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000447', 'M23B-EVID-000626', 'M23B-P2-R-000584', 'PMID:20233213; PMCID:PMC2850410; DOI:10.1111/j.1476-5381.2009.00631.x', '20233213', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2850410', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:20233213; PMCID:PMC2850410; DOI:10.1111/j.1476-5381.2009.00631.x; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B120_PMIDs_29491144_8550562_20233213_26813769_pubmed.xml', 'Primary experiments report that TSP1 signaling through CD47 inhibits nitric-oxide stimulation of soluble guanylate cyclase in endothelial cells, vascular smooth-muscle cells, and platelets, lowering cGMP responses; the same treatment affects platelet aggregation and vascular smooth-muscle contraction. The record does not define a kinase/adaptor cascade.', 'Promote the THBS1→CD47→sGC/cGMP inhibitory pathway at the receptor-associated second-messenger resolution measured. Do not infer a unique intracellular kinase relay or terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B120_PMC2850410_THBS1_CD47_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000626' AND x.extraction_id='M23B-P2-R-000584');
