INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000456', 'M23B-EVID-000636', 'M23B-P2-R-000593', 'PMCID:PMC6460357; PMID:30833305; DOI:10.15252/emmm.201809695', '30833305', 'full_text_xml', 'exact_identifier_match:DOI:10.15252/emmm.201809695;PMCID:PMC6460357', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC6460357; PMID:30833305; DOI:10.15252/emmm.201809695; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B122_PMC6460357_ADAM10_NrCAM_full.xml', 'The primary neuronal study demonstrates that ADAM10 cleaves the neuronal cell-adhesion protein NrCAM, releasing soluble NrCAM and generating a membrane C-terminal fragment that can be further processed by gamma-secretase. ADAM10 loss or inhibition increased surface NrCAM, while NMDA stimulation increased ADAM10-dependent NrCAM shedding.', 'Promote ADAM10→NrCAM cleavage and subsequent gamma-secretase processing as a bounded protease-substrate branch. Preserve NrCAM as a neuronal adhesion substrate rather than a soluble ligand or receptor.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B122_PMC6460357_ADAM10_NrCAM_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000636' AND x.extraction_id='M23B-P2-R-000593');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000457', 'M23B-EVID-000637', 'M23B-P2-R-000594', 'PMCID:PMC6460357; PMID:30833305; DOI:10.15252/emmm.201809695', '30833305', 'full_text_xml', 'exact_identifier_match:DOI:10.15252/emmm.201809695;PMCID:PMC6460357', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC6460357; PMID:30833305; DOI:10.15252/emmm.201809695; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B122_PMC6460357_ADAM10_NrCAM_full.xml', 'ADAM10 controlled NrCAM surface abundance and NrCAM-dependent neurite outgrowth in primary neuronal cultures. Conditional ADAM10 loss or GI254023x increased surface NrCAM and altered neurite extension; NrCAM knockdown reduced neurite outgrowth and prevented rescue by ADAM10 inhibition, supporting a bounded ADAM10/NrCAM neuronal remodeling branch.', 'Promote the bounded ADAM10→NrCAM surface-level/neurite-outgrowth functional branch. Do not infer a unique intracellular relay, SCI-specific effect, or terminal TF from the neuronal remodeling output.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B122_PMC6460357_ADAM10_NrCAM_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000637' AND x.extraction_id='M23B-P2-R-000594');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000875', 'M22B-EVID-002558', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B122_PMC7476718_TSPAN15_ADAM10_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002558' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000458', 'M23B-EVID-000638', 'M23B-P2-R-000595', 'PMCID:PMC7476718; PMID:32111735; DOI:10.1074/jbc.RA120.012601', '32111735', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7476718', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMCID:PMC7476718; PMID:32111735; DOI:10.1074/jbc.RA120.012601; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B122_PMIDs_25925953_26217011_29520422_32111735_pubmed.xml', 'The primary study identifies Tspan15 as a direct regulatory partner of ADAM10 and evaluates the Tspan15-ADAM10 scissor complex using ADAM10-knockout cell systems, Tspan15-directed antibodies, complex-expression and substrate-cleavage assays. Tspan15 is retained as a cis membrane protease cofactor, not an extracellular ligand.', 'Promote the cis Tspan15–ADAM10 scissor-complex regulatory branch at the complex/processing resolution reported. Do not classify Tspan15 as a ligand or infer a terminal TF from cofactor-dependent substrate selectivity.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B122_PMC7476718_TSPAN15_ADAM10_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000638' AND x.extraction_id='M23B-P2-R-000595');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B122_PMIDs_25925953_26217011_29520422_32111735_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000459', 'M23B-EVID-000639', 'M23B-P2-R-000596', 'PMCID:PMC11105247; PMID:29520422; DOI:10.1007/s00018-018-2791-2', '29520422', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11105247', 'candidate_requires_review', 'B', 'L2', 'validated_abstract_importable', 'validated_abstract_importable', 'PMCID:PMC11105247; PMID:29520422; DOI:10.1007/s00018-018-2791-2; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B123_PMID29520422_pubmed.xml', 'The primary in vivo study reports that Tspan15 specifically associates with endogenous ADAM10 in mouse brain. Tspan15 knockout reduces active and mature ADAM10, with age-dependent reduction of neuronal N-cadherin and cellular prion-protein shedding; APP alpha-secretase cleavage and Notch-dependent gene expression were not affected.', 'Promote Tspan15 as an ADAM10 cis-regulatory/scissor-complex cofactor that modulates ADAM10 maturation, surface activity, and substrate-selective shedding. Keep this as receptor-proximal protease regulation, not a ligand-receptor binding edge, and do not infer a universal ADAM10 substrate or a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B123_PMC11105247_Tspan15_ADAM10_full.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000639' AND x.extraction_id='M23B-P2-R-000596');
