INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000462', 'M23B-EVID-000642', 'M23B-P2-R-000599', 'PMCID:PMC2174829; PMID:10831617; DOI:10.1083/jcb.149.5.1143', '10831617', 'full_text_xml', 'exact_identifier_match:DOI:10.1083/jcb.149.5.1143;PMCID:PMC2174829', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2174829; PMID:10831617; DOI:10.1083/jcb.149.5.1143; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B123_PMC2174829_ADAM12_SDC4_full.xml', 'The primary full-text study shows that recombinant ADAM12 cysteine-rich domain binds cell-surface syndecans and that native syndecan-4 binds rADAM12-cys in a solid-phase assay; heparan-sulfate chains are required. Affinity capture identifies syndecan-4 as an ADAM12-cys-associated cell-surface adhesion receptor in the tested cells.', 'Promote the direct ADAM12 cysteine-rich-domain–syndecan-4/heparan-sulfate adhesion association at the domain/receptor-complex level. Keep syndecans as the initial attachment receptors and do not collapse this edge into alpha9beta1 integrin binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B123_PMC2174829_ADAM12_SDC4_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000642' AND x.extraction_id='M23B-P2-R-000599');
