INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000466', 'M23B-EVID-000646', 'M23B-P2-R-000603', 'PMCID:PMC18372; PMID:10518536; DOI:10.1073/pnas.96.21.11830', '10518536', 'literature_xml', 'exact_identifier_match:PMID:10518536', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMCID:PMC18372; PMID:10518536; DOI:10.1073/pnas.96.21.11830; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID10518536_pubmed.xml', 'The primary mouse fertilization study reports that CD9 is present on the egg surface, anti-CD9 inhibits sperm-egg binding and fusion, and anti-CD9 disrupts binding of native fertilin or recombinant fertilin-beta disintegrin-domain beads. The authors conclude that high-avidity ADAM2/fertilin-beta binding to complete alpha6beta1 requires cooperation with CD9.', 'Promote the ADAM2/fertilin-beta–complete alpha6beta1–CD9 cooperative membrane-adhesion complex at receptor-complex resolution. Do not reinterpret CD9 cooperation as an isolated direct ADAM2-CD9 binary edge or as a universal alpha6beta1 signaling pathway.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID10518536_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000646' AND x.extraction_id='M23B-P2-R-000603');
