INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000465', 'M23B-EVID-000645', 'M23B-P2-R-000602', 'PMID:14970227; DOI:10.1074/jbc.M400180200', '14970227', 'literature_xml', 'exact_identifier_match:PMID:14970227', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:14970227; DOI:10.1074/jbc.M400180200; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID14970227_pubmed.xml', 'The primary study reports functional interaction of recombinant ADAM17 extracellular fragments with complete alpha5beta1 integrin: adhesion is sensitive to RGD peptides and EDTA, and the binding site maps to the ADAM17 disintegrin/cysteine-rich region. ADAM17 and alpha5beta1 co-localize in migrating HeLa-cell membrane ruffles and focal adhesions, with redistribution to the wound leading edge.', 'Promote the bounded ADAM17 disintegrin/cysteine-rich-domain–complete alpha5beta1 integrin adhesion relationship. Preserve the reported trans functional interaction and possible cis co-localization as distinct observations; no ADAM17-to-kinase or TF relay is inferred.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID14970227_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000645' AND x.extraction_id='M23B-P2-R-000602');
