INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000468', 'M23B-EVID-000648', 'P2FALLBACK-23B-M23B-EVID-000648', 'PMID:15371519', '15371519', 'literature_xml', 'exact_identifier_match:PMID:15371519', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:15371519', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID15371519_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000648' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000648');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-001466', 'M23B-P2-R-000604', 'PMID:15371519; PMCID:PMC6729792; DOI:10.1523/JNEUROSCI.1345-04.2004', '15371519', 'literature_xml', 'exact_identifier_match:PMID:15371519', 'candidate_requires_review', 'E', 'L0', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMCID:PMC6729792; PMID:15371519; DOI:10.1523/JNEUROSCI.1345-04.2004; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID15371519_pubmed.xml', 'The retrieved primary mouse study genetically tests Itgb1 in motor neurons and skeletal muscle and reports that muscle, but not motor-neuron, beta1 integrin is required for normal neuromuscular-junction development. The abstract contains no alphaV-subunit assignment, agrin-alphaVbeta1 binding assay, or direct agrin-receptor occupancy measurement.', 'Do not promote an agrin-alphaVbeta1 direct-binding edge from this paper. The source supports a muscle beta1-integrin requirement and an agrin-null-like developmental phenotype, but it does not identify alphaV as the partner or prove that agrin signals through alphaVbeta1 in the tested system.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID15371519_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001466' AND x.extraction_id='M23B-P2-R-000604');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-001467', 'M23B-P2-R-000605', 'PMID:15371519; PMCID:PMC6729792; DOI:10.1523/JNEUROSCI.1345-04.2004', '15371519', 'literature_xml', 'exact_identifier_match:PMID:15371519', 'candidate_requires_review', 'E', 'L0', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMID:15371519; PMCID:PMC6729792; DOI:10.1523/JNEUROSCI.1345-04.2004; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID15371519_pubmed.xml', 'The primary mouse study reports defective presynaptic differentiation, excessive motor-axon branching and abnormal nerve terminals after skeletal-muscle Itgb1 deletion; the phenotype resembles agrin-null mice. This is a muscle beta1-integrin developmental output, not a demonstrated agrin-alphaVbeta1 pathway or alphaV-specific synaptic function assay.', 'Do not promote the queued agrin-alphaVbeta1 synaptic-function edge. Retain the paper only as contextual muscle beta1-integrin/NMJ evidence; the exact agrin-to-alphaVbeta1 functional branch and any intracellular relay remain unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B124_PMID15371519_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001467' AND x.extraction_id='M23B-P2-R-000605');
