INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-001463', 'M23B-P2-R-000606', 'PMID:30038556; DOI:10.1186/s12974-2018-1210-9', '30038556', 'literature_xml', 'exact_identifier_match:PMID:30038556', 'candidate_requires_review', 'E', 'L0', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMID:30038556; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B125_PMID30038556_pubmed.xml', 'The retrieved primary record is a transcriptomic and integrative-bioinformatics study of rat sciatic-nerve transection. It identifies Alcam, Nrp1 and related genes as network hubs, but does not report an ALCAM-NRP1 binding assay, trans-adhesion experiment, or direct receptor-complex measurement.', 'Do not promote a direct ALCAM-NRP1 trans-adhesion edge from this paper. The study supports only network-level co-occurrence/hub status in an injured-nerve context; a primary molecular or cell-adhesion source is required.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B125_PMID30038556_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001463' AND x.extraction_id='M23B-P2-R-000606');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-001464', 'M23B-P2-R-000607', 'PMID:30038556; DOI:10.1186/s12974-2018-1210-9', '30038556', 'literature_xml', 'exact_identifier_match:PMID:30038556', 'candidate_requires_review', 'E', 'L0', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMID:30038556; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B125_PMID30038556_pubmed.xml', 'The cited record reports gene-expression and interactive-network associations among Alcam, Nrp1, Nrp2, Rac1, Creb1 and Runx3 after sciatic-nerve transection, but does not provide a perturbation-specific ALCAM/NRP1 adhesion, semaphorin-response, or dopaminergic-neurite functional assay.', 'Do not promote the queued ALCAM-NRP1 neural-function edge from this paper. The record supports injury-associated network correlation only; the exact semaphorin or neurite-outgrowth branch remains unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B125_PMID30038556_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001464' AND x.extraction_id='M23B-P2-R-000607');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004645', 'M22B-EVID-002698', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC12896188_ANGPTL3_integrin_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002698' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000478', 'M23B-EVID-000658', 'M23B-P2-R-000615', 'PMCID:PMC12896188; PMID:41555340; DOI:10.1186/s12967-026-07710-4', '41555340', 'full_text_xml', 'exact_identifier_match:DOI:10.1186/s12967-026-07710-4;PMCID:PMC12896188', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC12896188; PMID:41555340; DOI:10.1186/s12967-026-07710-4; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC12896188_ANGPTL3_integrin_full.xml', 'In streptozotocin-diabetic mice and HUVECs, ANGPTL3 overexpression worsens retinal vascular leakage and endothelial-junction disruption. Co-immunoprecipitation supports ANGPTL3 association with integrin alpha5, while integrin-alpha5 knockdown attenuates ANGPTL3-induced loss of ZO-1 and VE-cadherin and preserves endothelial barrier function; intravitreal evinacumab rescues leakage and junctional proteins in vivo.', 'Promote the bounded ANGPTL3→integrin-alpha5-containing complex→ZO-1/VE-cadherin barrier-disruption functional branch. The co-immunoprecipitation supports association with integrin alpha5, but does not establish a complete alpha5beta1 receptor or a direct purified ligand-receptor interaction; keep the beta partner unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC12896188_ANGPTL3_integrin_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000658' AND x.extraction_id='M23B-P2-R-000615');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000479', 'M23B-EVID-000659', 'M23B-P2-R-000616', 'PMCID:PMC12896188; PMID:41555340; DOI:10.1186/s12967-026-07710-4', '41555340', 'full_text_xml', 'exact_identifier_match:DOI:10.1186/s12967-026-07710-4;PMCID:PMC12896188', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC12896188; PMID:41555340; DOI:10.1186/s12967-026-07710-4; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC12896188_ANGPTL3_integrin_full.xml', 'ANGPTL3 gain and loss in streptozotocin-diabetic mice changes retinal vascular leakage and endothelial-junction integrity. In HUVECs, integrin-alpha5 knockdown attenuates ANGPTL3-induced loss of ZO-1 and VE-cadherin, while evinacumab reduces leakage and restores junctional proteins in vivo.', 'Promote the ANGPTL3→integrin-alpha5-containing complex→endothelial junction/barrier function branch as a model-specific functional output. Keep the alpha5 association and ZO-1/VE-cadherin phenotype separate from complete alpha5beta1 receptor assignment and from any terminal TF claim.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC12896188_ANGPTL3_integrin_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000659' AND x.extraction_id='M23B-P2-R-000616');
