INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000474', 'M23B-EVID-000654', 'M23B-P2-R-000611', 'PMCID:PMC2267358; PMID:17708745; DOI:10.1007/s00018-006-6429-4', '17708745', 'full_text_html', 'exact_identifier_match:PMCID:PMC2267358', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2267358; PMID:17708745; DOI:10.1007/s00018-006-6429-4; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC2267358_amelogenin_LAMP2_full.html', 'The primary full-text study maps amelogenin residues 155–168 to interaction regions in CD63 residues 165–205, LAMP1 residues 226–251, and LAMP2 residues 227–259. Repeated yeast-two-hybrid filter assays support direct protein-region associations, with the same amelogenin motif responsible for the LAMP1, LAMP2 and CD63 interactions.', 'Promote the domain-resolved amelogenin–LAMP2 protein association through amelogenin residues 155–168 and LAMP2 residues 227–259. Keep CD63 and LAMP1 as separate interaction edges; these are noncanonical trafficking associations, not catalytic receptor interactions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC2267358_amelogenin_LAMP2_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000654' AND x.extraction_id='M23B-P2-R-000611');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004641', 'M22B-EVID-002695', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC8804837_ANGPTL2_integrin_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002695' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000475', 'M23B-EVID-000655', 'M23B-P2-R-000612', 'PMCID:PMC8804837; DOI:10.1177/1947603519878242', '31581797', 'full_text_html', 'exact_identifier_match:DOI:10.1177/1947603519878242;PMCID:PMC8804837', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC8804837; DOI:10.1177/1947603519878242; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC8804837_ANGPTL2_integrin_full.html', 'In differentiated mouse ATDC5 chondrocytes, recombinant human ANGPTL2 stimulation is evaluated with an alpha5beta1-blocking antibody. The paper supports alpha5beta1-dependent receptor-proximal engagement in this model, but does not report a purified ANGPTL2-alpha5beta1 affinity measurement.', 'Promote the bounded ANGPTL2→complete alpha5beta1 receptor-proximal engagement assignment in differentiated ATDC5 chondrocytes, based on ligand stimulation and alpha5beta1 blockade. Do not call this a purified direct-binding edge or transfer it to PIRB-mediated hematopoietic ANGPTL2 contexts.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC8804837_ANGPTL2_integrin_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000655' AND x.extraction_id='M23B-P2-R-000612');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000476', 'M23B-EVID-000656', 'M23B-P2-R-000613', 'PMCID:PMC8804837; DOI:10.1177/1947603519878242', '31581797', 'full_text_html', 'exact_identifier_match:DOI:10.1177/1947603519878242;PMCID:PMC8804837', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC8804837; DOI:10.1177/1947603519878242; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC8804837_ANGPTL2_integrin_full.html', 'ANGPTL2 stimulation induces phosphorylation of ERK, JNK, p38, Akt and NF-kappaB in differentiated ATDC5 chondrocytes. Neutralizing alpha5beta1 antibody markedly reduces the ANGPTL2-associated phosphorylation of MAPKs, Akt and NF-kappaB, supporting a context-specific alpha5beta1-to-MAPK/Akt/NF-kappaB relay.', 'Promote the bounded ANGPTL2–alpha5beta1→ERK/JNK/p38, Akt and NF-kappaB receptor-proximal signaling branch in ATDC5 chondrocytes. Preserve the measured phospho-readouts as pathway nodes and do not infer a unique upstream adaptor or a terminal TF beyond NF-kappaB activation.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC8804837_ANGPTL2_integrin_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000656' AND x.extraction_id='M23B-P2-R-000613');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000477', 'M23B-EVID-000657', 'M23B-P2-R-000614', 'PMCID:PMC8804837; DOI:10.1177/1947603519878242', '31581797', 'full_text_html', 'exact_identifier_match:DOI:10.1177/1947603519878242;PMCID:PMC8804837', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC8804837; DOI:10.1177/1947603519878242; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC8804837_ANGPTL2_integrin_full.html', 'In differentiated ATDC5 chondrocytes, ANGPTL2 increases inflammatory-factor transcripts and proteins, including IL-1beta, TNF-alpha, COX-2, ADAMTS-5, MMP-3 and MMP-13. Alpha5beta1 blockade suppresses the ANGPTL2-associated inflammatory and matrix-remodeling response.', 'Promote the ANGPTL2–alpha5beta1 downstream inflammatory and matrix-remodeling output in ATDC5 chondrocytes, including IL-1beta, TNF-alpha, COX-2, ADAMTS-5, MMP-3 and MMP-13 expression. Keep these functional outputs separate from the measured phospho-pathway branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B126_PMC8804837_ANGPTL2_integrin_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000657' AND x.extraction_id='M23B-P2-R-000614');
