INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000482', 'M23B-EVID-000662', 'M23B-P2-R-000619', 'PMID:21841165; DOI:10.1182/blood-2011-01-328716', '21841165', 'literature_xml', 'exact_identifier_match:PMID:21841165', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:21841165; DOI:10.1182/blood-2011-01-328716; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B127_PMID21841165_pubmed.xml', 'The primary vascular study reports that the active C-terminal ANGPTL4 fragment binds and activates complete alpha5beta1-mediated Rac1/PAK signaling in endothelial cells, weakening cell-cell contacts. Interfering with formation of the cANGPTL4 complexes delays vascular disruption.', 'Promote the bounded cANGPTL4→complete alpha5beta1→Rac1/PAK receptor-proximal relay. Keep Rac1/PAK activation distinct from the downstream VE-cadherin/claudin-5 disruption output and do not infer a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B127_PMID21841165_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000662' AND x.extraction_id='M23B-P2-R-000619');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000483', 'M23B-EVID-000663', 'M23B-P2-R-000620', 'PMID:21841165; DOI:10.1182/blood-2011-01-328716', '21841165', 'literature_xml', 'exact_identifier_match:PMID:21841165', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:21841165; DOI:10.1182/blood-2011-01-328716; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B127_PMID21841165_pubmed.xml', 'The same primary study reports that cANGPTL4 subsequently associates with and declusters VE-cadherin and claudin-5, causing endothelial disruption, vascular permeability and enhanced lung metastasis in mouse assays. Interference with cANGPTL4-complex formation delays this output.', 'Promote the cANGPTL4-alpha5beta1→Rac1/PAK→VE-cadherin/claudin-5 disruption and vascular-permeability/metastatic output branch. Keep VE-cadherin and claudin-5 as sequential downstream outputs rather than receptor substitutions, and do not infer a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B127_PMID21841165_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000663' AND x.extraction_id='M23B-P2-R-000620');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000480', 'M23B-EVID-000660', 'M23B-P2-R-000617', 'PMID:28740178; DOI:10.1016/j.matbio.2017.06.007', '28740178', 'literature_xml', 'exact_identifier_match:PMID:28740178', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:28740178; DOI:10.1016/j.matbio.2017.06.007; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B127_PMID28740178_pubmed.xml', 'The primary wound-healing study reports that the C-terminal ANGPTL4 fragment binds cadherin-11 in human fibroblast mechanistic models and interacts with cadherin-11 in human scar tissue. The association is retained at the C-terminal-fragment and cadherin-complex resolution.', 'Promote the bounded C-terminal ANGPTL4 fragment–cadherin-11 association. Preserve the fragment identity and cadherin-complex context; do not represent this as full-length ANGPTL4 binding to every cadherin or as a direct TF interaction.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B127_PMID28740178_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000660' AND x.extraction_id='M23B-P2-R-000617');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000481', 'M23B-EVID-000661', 'M23B-P2-R-000618', 'PMID:28740178; DOI:10.1016/j.matbio.2017.06.007', '28740178', 'literature_xml', 'exact_identifier_match:PMID:28740178', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:28740178; DOI:10.1016/j.matbio.2017.06.007; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B127_PMID28740178_pubmed.xml', 'In human fibroblasts, cANGPTL4-associated cadherin-11 signaling releases membrane-bound beta-catenin, which translocates to the nucleus and increases ID3 expression. ID3 interacts with scleraxis and suppresses scar-associated collagen type I, II and III production; related collagen-reduction effects are observed in mouse and rat wound models.', 'Promote the cANGPTL4–cadherin-11→beta-catenin nuclear translocation→ID3→reduced scar-collagen output branch. Preserve ID3 and scleraxis as downstream transcriptional regulators and do not infer direct ANGPTL4 binding to ID3 or scleraxis.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B127_PMID28740178_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000661' AND x.extraction_id='M23B-P2-R-000618');
