INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_DOI_CRTAM_esearch.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000940', 'M22B-EVID-000426', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMC3631237_CADM1_NECTIN3_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000426' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000488', 'M23B-EVID-000668', 'M23B-P2-R-000625', 'PMID:22703826; DOI:10.1016/j.jneuroim.2012.05.016', '22703826', 'full_text_html', 'exact_identifier_match:PMCID:PMC3631237', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:22703826; DOI:10.1016/j.jneuroim.2012.05.016; related context PMCID:PMC3631237; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID22703826_CADM1_NECTIN3_pubmed.xml', 'The primary mast-cell/neurite study reports that CADM1 on mast cells mediates attachment to dorsal-root-ganglion neurites despite low CADM1 expression in DRG, while nectin-3 is expressed on DRG neurons at contact sites. A neutralizing anti-nectin-3 antibody inhibits mast-cell attachment and subsequent calcium responses, supporting heterophilic CADM1–nectin-3 interaction.', 'Promote the CADM1-on-mast-cell–nectin-3-on-DRG-neurite heterophilic trans-adhesion edge and its contact-dependent calcium-response output. Keep the molecular adhesion and calcium function as separate layers; do not infer a defined kinase or TF relay.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMC3631237_CADM1_NECTIN3_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000668' AND x.extraction_id='M23B-P2-R-000625');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000489', 'M23B-EVID-000669', 'M23B-P2-R-000626', 'PMID:22703826; DOI:10.1016/j.jneuroim.2012.05.016; related PMCID:PMC3631237', '22703826', 'full_text_html', 'exact_identifier_match:PMCID:PMC3631237', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:22703826; DOI:10.1016/j.jneuroim.2012.05.016; related context PMCID:PMC3631237; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID22703826_CADM1_NECTIN3_pubmed.xml', 'The correct primary mast-cell/neurite paper reports that CADM1 on mast cells mediates attachment to dorsal-root-ganglion neurites and that neutralizing nectin-3 inhibits both attachment and subsequent calcium responses. The initially queued PMCID:PMC3631237 is a related lung mast-cell adhesion paper and is retained only as contextual support, not as the direct pairwise source.', 'Promote the CADM1–nectin-3 contact-dependent adhesion and neurite-evoked calcium functional output in the reported neural-immune model. Keep the function record separate from the direct heterophilic binding record and do not infer a defined calcium kinase or TF relay.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMC3631237_CADM1_NECTIN3_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000669' AND x.extraction_id='M23B-P2-R-000626');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004661', 'M22B-EVID-002715', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMC6775579_ANXA2_ROBO4_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002715' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000484', 'M23B-EVID-000664', 'M23B-P2-R-000621', 'PMCID:PMC6775579; PMID:29786451', '29786451', 'full_text_html', 'exact_identifier_match:PMCID:PMC6775579', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC6775579; PMID:29786451; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMC6775579_ANXA2_ROBO4_full.html', 'The primary full-text study reports that endogenous and recombinant ANXA2 associate with Robo4 at the endothelial cell membrane. Immunoprecipitation supports the ANXA2-Robo4 interaction and the formation of a Robo4-paxillin complex; ANXA2 depletion reduces endogenous paxillin binding to Robo4.', 'Promote the bounded membrane ANXA2–Robo4 association and its effect on Robo4-paxillin complex formation. Keep ANXA2 as a membrane-associated/noncanonical Robo4 ligand in this model, not as a universal soluble ligand or a canonical RTK.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMC6775579_ANXA2_ROBO4_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000664' AND x.extraction_id='M23B-P2-R-000621');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000485', 'M23B-EVID-000665', 'M23B-P2-R-000622', 'PMCID:PMC6775579; PMID:29786451', '29786451', 'full_text_html', 'exact_identifier_match:PMCID:PMC6775579', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC6775579; PMID:29786451; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMC6775579_ANXA2_ROBO4_full.html', 'ANXA2 knockout mice show reduced cerebral endothelial junctional proteins and increased tracer leakage. In human brain microvascular endothelial cells injured by hypoxia plus IL-1beta, recombinant ANXA2 rescues junctional proteins and reduces trans-endothelial permeability; Robo4-paxillin signaling and ARF6 activity are implicated in this protection.', 'Promote the ANXA2–Robo4→paxillin→ARF6 barrier-protection branch, with separate F-actin/VE-cadherin junctional support and reduced cerebral endothelial permeability. Do not infer a terminal TF or collapse VE-cadherin into the Robo4 receptor node.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMC6775579_ANXA2_ROBO4_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000665' AND x.extraction_id='M23B-P2-R-000622');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004862', 'M22B-EVID-002923', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID15811952_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002923' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000486', 'M23B-EVID-000666', 'M23B-P2-R-000623', 'PMID:15811952; DOI:10.1182/blood-2005-02-0817', '15811952', 'literature_xml', 'exact_identifier_match:PMID:15811952', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:15811952; DOI:10.1182/blood-2005-02-0817; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID15811952_pubmed.xml', 'The primary immune-adhesion study reports that CADM1/Necl-2 on target cells is recognized by CRTAM on activated NK and CD8-positive T cells. CRTAM-positive cells bind Necl-2-positive cells, and the interaction is inhibited by CRTAM-Ig, supporting a heterophilic trans-adhesion relationship.', 'Promote the CADM1/Necl-2–CRTAM heterophilic trans-adhesion edge at complete receptor/ligand-complex resolution. Keep the immune activation outputs and cooperating receptor context separate; do not infer a unique CRTAM kinase or TF relay.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID15811952_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000666' AND x.extraction_id='M23B-P2-R-000623');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000487', 'M23B-EVID-000667', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID15811952_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000667' AND x.extraction_id='');
