INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000953', 'M22B-EVID-000430', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID22703826_CADM1_NECTIN3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000430' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000488', 'M23B-EVID-000668', 'M23B-P2-R-000625', 'PMID:22703826; DOI:10.1016/j.jneuroim.2012.05.016', '22703826', 'literature_xml', 'exact_identifier_match:PMID:22703826', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:22703826; DOI:10.1016/j.jneuroim.2012.05.016; related context PMCID:PMC3631237; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID22703826_CADM1_NECTIN3_pubmed.xml', 'The primary mast-cell/neurite study reports that CADM1 on mast cells mediates attachment to dorsal-root-ganglion neurites despite low CADM1 expression in DRG, while nectin-3 is expressed on DRG neurons at contact sites. A neutralizing anti-nectin-3 antibody inhibits mast-cell attachment and subsequent calcium responses, supporting heterophilic CADM1–nectin-3 interaction.', 'Promote the CADM1-on-mast-cell–nectin-3-on-DRG-neurite heterophilic trans-adhesion edge and its contact-dependent calcium-response output. Keep the molecular adhesion and calcium function as separate layers; do not infer a defined kinase or TF relay.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID22703826_CADM1_NECTIN3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000668' AND x.extraction_id='M23B-P2-R-000625');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000489', 'M23B-EVID-000669', 'M23B-P2-R-000626', 'PMID:22703826; DOI:10.1016/j.jneuroim.2012.05.016; related PMCID:PMC3631237', '22703826', 'literature_xml', 'exact_identifier_match:PMID:22703826', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:22703826; DOI:10.1016/j.jneuroim.2012.05.016; related context PMCID:PMC3631237; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID22703826_CADM1_NECTIN3_pubmed.xml', 'The correct primary mast-cell/neurite paper reports that CADM1 on mast cells mediates attachment to dorsal-root-ganglion neurites and that neutralizing nectin-3 inhibits both attachment and subsequent calcium responses. The initially queued PMCID:PMC3631237 is a related lung mast-cell adhesion paper and is retained only as contextual support, not as the direct pairwise source.', 'Promote the CADM1–nectin-3 contact-dependent adhesion and neurite-evoked calcium functional output in the reported neural-immune model. Keep the function record separate from the direct heterophilic binding record and do not infer a defined calcium kinase or TF relay.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B128_PMID22703826_CADM1_NECTIN3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000669' AND x.extraction_id='M23B-P2-R-000626');
