INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000492', 'M23B-EVID-000672', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L2', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B129_PMC5073025_CADM3_CADM4_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000672' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000493', 'M23B-EVID-000673', 'M23B-P2-R-000630', 'PMCID:PMC5073025; PMID:37022761; PMCID:PMC2064549; PMID:17724124; PMCID:PMC2836764; PMID:17558405', NULL, 'full_text_html', 'exact_identifier_match:PMCID:PMC5073025', 'candidate_requires_review', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC5073025; PMCID:PMC2064549; PMCID:PMC2836764; PMID:37022761; PMID:17724124; PMID:17558405; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B129_PMC5073025_CADM3_CADM4_full.html, retry_C23B129_PMC2064549_Maurel_CADM_CADM4_full.html and retry_C23B129_PMC2836764_Spiegel_CADM4_full.html', 'Primary axon–Schwann studies report that CADM3/Necl-1 depletion or increased axonal CADM3 changes Schwann-cell myelin-segment formation. In a separate full-text mechanistic study, soluble extracellular CADM3 reduces Nrg1-induced ErbB3 and Akt phosphorylation in Schwann cells while leaving ErbB2/Erk1/2 activation comparatively unaffected; CADM4 perturbation independently blocks Schwann differentiation and myelination.', 'Promote the CADM3/CADM4 axo-glial downstream branch with separate myelination and receptor-proximal outputs: CADM4 loss impairs Schwann differentiation/myelination, while CADM3 abundance or extracellular domain modulates Nrg1-induced ErbB3/PI3K/Akt more strongly than ErbB2/Erk1/2. Do not infer that ErbB3 or Akt is directly bound by CADM3/CADM4 or assign a terminal TF.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B129_PMC5073025_CADM3_CADM4_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000673' AND x.extraction_id='M23B-P2-R-000630');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004528', 'M22B-EVID-000427', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B129_PMID37022761_CADM3_zebrafish_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000427' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000490', 'M23B-EVID-000670', 'M23B-P2-R-000627', 'PMID:37022761; DOI:10.1083/jcb.202204098', '37022761', 'literature_xml', 'exact_identifier_match:PMID:37022761', 'candidate_requires_review', 'B', 'L2', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:37022761; DOI:10.1083/jcb.202204098; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B129_PMID37022761_CADM3_zebrafish_pubmed.xml', 'The primary zebrafish retinal study reports that homophilic Cadm3 interaction provides an intercellular mechanism coordinating retinal neuroepithelial cell proliferation. Full-length or extracellular Cadm3 overexpression suppresses clonal expansion, while deletion of the extracellular Ig1 domain or cadm3 disruption produces expanded clones, supporting an ectodomain-dependent homophilic adhesion function.', 'Promote the bounded homophilic CADM3 cell-adhesion interaction in developing zebrafish retinal neuroepithelium. Keep the ectodomain/Ig1 requirement and tissue context explicit; do not infer a receptor-proximal kinase pathway from homophilic adhesion alone.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B129_PMID37022761_CADM3_zebrafish_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000670' AND x.extraction_id='M23B-P2-R-000627');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000491', 'M23B-EVID-000671', 'M23B-P2-R-000628', 'PMID:37022761; DOI:10.1083/jcb.202204098', '37022761', 'literature_xml', 'exact_identifier_match:PMID:37022761', 'candidate_requires_review', 'B', 'L2', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:37022761; DOI:10.1083/jcb.202204098; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B129_PMID37022761_CADM3_zebrafish_pubmed.xml', 'In zebrafish retinal progenitor/neuroepithelial models, p15-positive host retinae show expanded clones and reduced cadm3, while Cadm3 overexpression suppresses clonal expansion and cadm3 disruption or Ig1-deleted Cadm3 increases retinal cell number. The authors interpret this as Cadm3-dependent coordination of neuroepithelial proliferation and cell-number homeostasis.', 'Promote the CADM3 homophilic-adhesion-associated retinal proliferation and cell-number-homeostasis output in zebrafish. Keep the output distinct from the homophilic interaction evidence and do not infer a conserved SCI pathway or terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B129_PMID37022761_CADM3_zebrafish_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000671' AND x.extraction_id='M23B-P2-R-000628');
