INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000543', 'M22B-EVID-005411', 'P2FALLBACK-22B-M22B-EVID-005411', 'PMID:15536074', '15536074', 'literature_xml', 'exact_identifier_match:PMID:15536074', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMID:15536074', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B130_PMID15536074_EFNB1_EPHB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005411' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-005411');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000678', 'M23B-P2-R-000635', 'PMID:15536074; DOI:10.1074/jbc.M411383200', '15536074', 'literature_xml', 'exact_identifier_match:PMID:15536074', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:15536074; DOI:10.1074/jbc.M411383200; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B130_PMID15536074_EFNB1_EPHB3_pubmed.xml', 'The primary study reports that ephrin-B1 stimulation of endogenous EphB kinases and WT or kinase-deficient EphB3 affects integrin-mediated adhesion and HGF/SF-induced migration in epithelial models. EphB3 kinase activity is required for adhesion inhibition, whereas both WT and kinase-deficient EphB3 reduce Rac1/Cdc42 activity and increase relative RhoA signaling during migration.', 'Promote the bounded ephrin-B1→EphB3 receptor-proximal/function branch: kinase-dependent inhibition of integrin-mediated adhesion and a kinase-independent Rac1/Cdc42 decrease with relative RhoA increase during migration. Do not promote a direct purified ephrin-B1–EphB3 affinity edge from this record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B130_PMID15536074_EFNB1_EPHB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000678' AND x.extraction_id='M23B-P2-R-000635');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000498', 'M23B-EVID-000679', 'M23B-P2-R-000636', 'PMID:15536074; DOI:10.1074/jbc.M411383200', '15536074', 'literature_xml', 'exact_identifier_match:PMID:15536074', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:15536074; DOI:10.1074/jbc.M411383200; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B131_PMID15536074_EFNB1_EPHB3_pubmed.xml', 'Ephrin-B1 stimulation of endogenous EphB kinases in LS174T cells and comparison of wild-type versus kinase-deficient EphB3 in 293 cells showed that inhibition of integrin-mediated adhesion and induction of cell rounding required EphB3 catalytic activity.', 'Promote the bounded ephrin-B1→EphB3 receptor-proximal branch in which EphB3 catalytic activity is required for inhibition of integrin-mediated adhesion and cell rounding. Do not convert this perturbation study into a purified ligand-receptor affinity claim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B130_PMID15536074_EFNB1_EPHB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000679' AND x.extraction_id='M23B-P2-R-000636');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000499', 'M23B-EVID-000680', 'M23B-P2-R-000637', 'PMID:15536074; DOI:10.1074/jbc.M411383200', '15536074', 'literature_xml', 'exact_identifier_match:PMID:15536074', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:15536074; DOI:10.1074/jbc.M411383200; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B131_PMID15536074_EFNB1_EPHB3_pubmed.xml', 'In migrating EphB3-expressing cells stimulated with ephrin-B1, both wild-type and kinase-deficient EphB3 reduced Rac1 and Cdc42 activity; the resulting relative increase in RhoA signaling contributed to inhibition of directional migration. EphB3-mediated adhesion inhibition was distinct because it required catalytic activity.', 'Promote the bounded ephrin-B1→EphB3→Rac1/Cdc42 decrease with relative RhoA increase→inhibited directional migration functional branch. Keep this downstream output separate from the kinase-dependent adhesion branch and do not infer a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B130_PMID15536074_EFNB1_EPHB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000680' AND x.extraction_id='M23B-P2-R-000637');
