INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000500', 'M23B-EVID-000681', 'M23B-P2-R-000638', 'PMCID:PMC11021433; PMID:38627519; DOI:10.1038/s42003-024-06118-4', '38627519', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11021433', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC11021433; PMID:38627519; DOI:10.1038/s42003-024-06118-4; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B131_PMC11021433_EFNB1_EPHB6_fulltext_bioc.json', 'In co-cultured human MDA-MB-231 cells, full-length EphB6 and ephrinB1 accumulated in trans at cell-cell interfaces. Disrupting the conserved EphB6 ligand-binding residue R112E abolished co-clustering, while oligomerization-interface mutations reduced or abolished clustering, supporting an exact EphB6-ephrinB1 trans interaction with receptor ectodomain determinants.', 'Promote the bounded direct trans EphB6–ephrinB1 binding/activation record supported by ligand-binding-site mutagenesis and loss of cell-surface co-clustering. Preserve the distinction between cell-based trans interaction and purified affinity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B131_PMC11021433_EFNB1_EPHB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000681' AND x.extraction_id='M23B-P2-R-000638');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000682', 'M23B-P2-R-000639', 'PMCID:PMC11021433; PMID:38627519; DOI:10.1038/s42003-024-06118-4', '38627519', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11021433', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMCID:PMC11021433; PMID:38627519; DOI:10.1038/s42003-024-06118-4; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B131_PMC11021433_EFNB1_EPHB6_fulltext_bioc.json', 'The EphB6 primary study demonstrates ephrinB1-dependent receptor co-clustering, but EphB6 is a kinase-impaired pseudokinase and the retrieved full text does not report a qualifying receptor-proximal phosphorylation, adaptor, second-messenger, or canonical relay measurement for the EphB6-ephrinB1 pair.', 'Do not promote a receptor-proximal EphB6-ephrinB1 relay from this paper. Preserve the exact binding and downstream functional records while leaving the intermediate signaling layer unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B131_PMC11021433_EFNB1_EPHB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000682' AND x.extraction_id='M23B-P2-R-000639');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000501', 'M23B-EVID-000683', 'M23B-P2-R-000640', 'PMCID:PMC11021433; PMID:38627519; DOI:10.1038/s42003-024-06118-4', '38627519', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11021433', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC11021433; PMID:38627519; DOI:10.1038/s42003-024-06118-4; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B131_PMC11021433_EFNB1_EPHB6_fulltext_bioc.json', 'EphB6-ephrinB1 co-clusters in human MDA-MB-231 co-culture promoted double-membrane tubular structures that stabilized cell-cell adhesion; in three-dimensional spheroid assays, co-clustering reduced the invasive behavior of the breast-cancer cells.', 'Promote the bounded EphB6-ephrinB1→double-membrane tubule formation→stabilized cell-cell adhesion→reduced MDA-MB-231 spheroid invasion functional branch. Keep this cellular output separate from direct binding and do not infer a kinase pathway or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B131_PMC11021433_EFNB1_EPHB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000683' AND x.extraction_id='M23B-P2-R-000640');
