INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000504', 'M23B-EVID-000687', 'M23B-P2-R-000644', 'PMCID:PMC2710021; PMID:18849408; DOI:10.1529/biophysj.108.135491', '18849408', 'full_text_html', 'exact_identifier_match:DOI:10.1529/biophysj.108.135491;PMCID:PMC2710021', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2710021; PMID:18849408; DOI:10.1529/biophysj.108.135491; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC2710021_F11R_LFA1_fulltext.html', 'The primary human JAM-A/F11R-LFA-1 study measured direct heterophilic interaction using recombinant JAM-A domains, LFA-1-expressing Jurkat cells, solid-phase binding, cell adhesion, and single-molecule atomic-force microscopy. LFA-1 binding maps to the membrane-proximal second Ig domain of JAM-A and the interaction is stronger than JAM-A homophilic binding under the tested conditions.', 'Promote the direct F11R/JAM-A–LFA-1 (ITGAL:ITGB2) heterophilic binding record, with JAM-A domain 2 and the LFA-1 I-domain as tested determinants. Keep the receptor-complex and transendothelial adhesion consequences separate from intracellular relay claims.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC2710021_F11R_LFA1_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000687' AND x.extraction_id='M23B-P2-R-000644');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000688', 'M23B-P2-R-000645', 'PMCID:PMC2710021; PMID:18849408; DOI:10.1529/biophysj.108.135491', '18849408', 'full_text_html', 'exact_identifier_match:DOI:10.1529/biophysj.108.135491;PMCID:PMC2710021', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMCID:PMC2710021; PMID:18849408; DOI:10.1529/biophysj.108.135491; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC2710021_F11R_LFA1_fulltext.html', 'The primary F11R/JAM-A-LFA-1 paper demonstrates that LFA-1 binding weakens JAM-A homophilic junctional interactions and supports transendothelial migration, but it does not report a qualifying intracellular phosphorylation, adaptor, second-messenger, or terminal-TF relay uniquely downstream of the F11R-LFA-1 pair.', 'Do not promote an intracellular F11R-LFA-1 relay from this paper. Preserve the direct heterophilic interaction and junctional/transendothelial functional consequence, while leaving the cytoplasmic signaling layer unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC2710021_F11R_LFA1_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000688' AND x.extraction_id='M23B-P2-R-000645');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000505', 'M23B-EVID-000689', 'M23B-P2-R-000646', 'PMCID:PMC2710021; PMID:18849408; DOI:10.1529/biophysj.108.135491', '18849408', 'full_text_html', 'exact_identifier_match:DOI:10.1529/biophysj.108.135491;PMCID:PMC2710021', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2710021; PMID:18849408; DOI:10.1529/biophysj.108.135491; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC2710021_F11R_LFA1_fulltext.html', 'The primary JAM-A/F11R-LFA-1 study links the stronger heterophilic LFA-1/JAM-A interaction to weakening of JAM-A homophilic junctional contacts and supports leukocyte transendothelial migration as the resulting cellular process. The paper does not assign a unique intracellular adaptor.', 'Promote the bounded F11R/JAM-A–LFA-1→junctional adhesion destabilization→leukocyte transendothelial migration functional branch. Keep the mechanical junctional consequence separate from the unresolved intracellular relay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC2710021_F11R_LFA1_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000689' AND x.extraction_id='M23B-P2-R-000646');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005360', 'M22B-EVID-003445', '', '', NULL, 'full_text_or_bioc_json', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC6689289_EFNB3_EPHB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003445' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000502', 'M23B-EVID-000684', 'M23B-P2-R-000641', 'PMCID:PMC6689289; PMID:31011859; DOI:10.1007/s00401-019-02011-1', '31011859', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6689289', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC6689289; PMID:31011859; DOI:10.1007/s00401-019-02011-1; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC6689289_EFNB3_EPHB6_fulltext_bioc.json', 'Clustered recombinant EphrinB3 bound to EphB6 on purified mouse Schwann-cell surfaces, with receptor-specific immunostaining and receptor blocking. The same study reports that EphrinB3-bound EphB6 can participate in a complex in which EphB1 is trans-phosphorylated.', 'Promote the bounded EphrinB3→EphB6 binding/activation record in mouse Schwann cells. Preserve EphB6 as a kinase-defective receptor in a receptor complex and do not treat the cell-surface assay as purified affinity measurement.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC6689289_EFNB3_EPHB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000684' AND x.extraction_id='M23B-P2-R-000641');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000685', 'M23B-P2-R-000642', 'PMCID:PMC6689289; PMID:31011859; DOI:10.1007/s00401-019-02011-1', '31011859', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6689289', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC6689289; PMID:31011859; DOI:10.1007/s00401-019-02011-1; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC6689289_EFNB3_EPHB6_fulltext_bioc.json', 'In primary mouse Schwann cells, clustered EphrinB3 induced EphA4 phosphorylation and EphB1/B2 phosphorylation; the paper states that EphB6, although kinase-defective, can be trans-phosphorylated by EphB1 in the EphrinB3-bound receptor complex. Myelin-induced receptor phosphorylation was blocked by anti-EphrinB3.', 'Promote the bounded EphrinB3→Eph-containing receptor complex→EphB1/B2 phosphorylation branch, with EphB6 as a kinase-defective complex component capable of trans-phosphorylation. Do not infer a unique EphB6-only kinase relay or a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC6689289_EFNB3_EPHB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000685' AND x.extraction_id='M23B-P2-R-000642');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000503', 'M23B-EVID-000686', 'M23B-P2-R-000643', 'PMCID:PMC6689289; PMID:31011859; DOI:10.1007/s00401-019-02011-1', '31011859', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC6689289', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC6689289; PMID:31011859; DOI:10.1007/s00401-019-02011-1; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC6689289_EFNB3_EPHB6_fulltext_bioc.json', 'EphrinB3/EphB6 blockade improved Schwann-cell adhesion and spreading on myelin, while EphrinB3 increased adhesion to fibronectin and migration on fibronectin through an integrin-beta1-sensitive branch. In demyelinated mouse spinal cord, Eph receptor interference reduced Schwann-cell association with blood vessels and lesion-directed migration.', 'Promote the bounded EphrinB3→EphB6/EphA4 receptor branch→reduced myelin adhesion plus integrin-beta1-dependent fibronectin adhesion/migration functional output. Keep the multi-receptor context and do not infer a direct EphB6-to-integrin molecular interaction.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMC6689289_EFNB3_EPHB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000686' AND x.extraction_id='M23B-P2-R-000643');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B132_PMIDs_11812992_15528364_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000387', 'M22B-EVID-000042', 'M22B-P2-R-000042-R089-B', 'PMCID:PMC7840119; PMID:33571112; DOI:10.1126/sciadv.abc7170', '33571112', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC7840119', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC7840119; PMID:33571112; DOI:10.1126/sciadv.abc7170; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC7840119_pathway.xml', 'Fibrillin-1-enriched chronic-kidney-disease matrix induced integrin alphaVbeta6 expression and TGF-beta1/Smad3 activation in human endothelial cells; alphaVbeta6 or TGF-beta1 blockade reduced apoptotic proteins and endothelial apoptosis, while FBN1 depletion mitigated vascular rarefaction in mouse kidney injury models.', 'The PMC7840119 study supports an FBN1-alphaVbeta6-TGF-beta1/Smad3 endothelial injury pathway and vascular-rarefaction output, but it does not establish Smad3 binding to a target locus or prove that the PMID:17158881 binding paper used the same injury model.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMC7840119_FBN1_ITGAVB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000042' AND x.extraction_id='M22B-P2-R-000042-R089-B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000388', 'M22B-EVID-000043', '', '', NULL, 'full_text_or_bioc_json', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMC7840119_FBN1_ITGAVB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000043' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000507', 'M23B-EVID-000693', 'M23B-P2-R-000650', 'PMID:17158881; PMCID:PMC7840119; DOI:10.1074/jbc.M607008200', '17158881', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC7840119', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMID:17158881; PMCID:PMC7840119; DOI:10.1074/jbc.M607008200; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMC7840119_FBN1_ITGAVB6_fulltext_bioc.json', 'The primary FBN1 kidney-injury study shows that recombinant FBN1 induces integrin alphaVbeta6 expression and that an anti-alphaVbeta6 antibody blocks FBN1-induced TGF-beta1/Smad3 activation and endothelial apoptosis. It does not report a direct FBN1-alphaVbeta6 binding assay; the evidence is pathway/functional, not a direct molecular binding result.', 'Retain the direct FBN1–alphaVbeta6 receptor edge on the independently validated SPR study (PMID:17158881; Kd approximately 0.45 micromolar). The kidney-injury paper in this batch supports alphaVbeta6-dependent TGF-beta1/Smad3 activation and endothelial injury, but does not itself establish direct binding; keep those pathway and functional observations in their separate records.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMC7840119_FBN1_ITGAVB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000693' AND x.extraction_id='M23B-P2-R-000650');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000508', 'M23B-EVID-000694', 'M23B-P2-R-000651', 'PMCID:PMC7840119; PMID:17158881; DOI:10.1074/jbc.M607008200', '17158881', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC7840119', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC7840119; PMID:17158881; DOI:10.1074/jbc.M607008200; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMC7840119_FBN1_ITGAVB6_fulltext_bioc.json', 'Recombinant human FBN1 rapidly induced integrin alphaV and beta6 expression and TGF-beta1 activation with Smad3 phosphorylation in HUVECs. A neutralizing anti-alphaVbeta6 antibody abolished FBN1-triggered TGF-beta1/Smad3 activation, supporting an alphaVbeta6-dependent receptor-proximal pathway branch.', 'Promote the bounded FBN1→integrin alphaVbeta6→TGF-beta1/Smad3 receptor-proximal pathway branch. Keep this separate from direct binding because the study uses pathway induction and functional blockade rather than a purified FBN1-alphaVbeta6 affinity assay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMC7840119_FBN1_ITGAVB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000694' AND x.extraction_id='M23B-P2-R-000651');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000509', 'M23B-EVID-000695', 'M23B-P2-R-000652', 'PMCID:PMC7840119; PMID:17158881; DOI:10.1074/jbc.M607008200', '17158881', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC7840119', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC7840119; PMID:17158881; DOI:10.1074/jbc.M607008200; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMC7840119_FBN1_ITGAVB6_fulltext_bioc.json', 'FBN1-induced alphaVbeta6/TGF-beta1/Smad3 signaling caused endothelial apoptosis and loss of proliferative capacity in HUVECs and HRGECs; alphaVbeta6 or TGF-beta blockade reduced FBN1-induced proapoptotic proteins and apoptosis. FBN1 knockdown in mouse kidney injury reduced pathway activation and mitigated vascular rarefaction.', 'Promote the bounded FBN1→alphaVbeta6→TGF-beta1/Smad3→endothelial apoptosis and kidney microvascular rarefaction functional branch. Do not infer a terminal TF from the measured p53, c-Fos, c-Myc, or other downstream protein outputs.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMC7840119_FBN1_ITGAVB6_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000695' AND x.extraction_id='M23B-P2-R-000652');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000549', 'M22B-EVID-005425', 'M22B-P2-R-000812', 'PMID:10848816', '10848816', 'literature_xml', 'exact_identifier_match:PMID:10848816', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMID:10848816; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_pubmed_B023_pmids.xml', 'Primary source PMID:10848816 reports the tested receptor/proximal or functional observation at its model scope; no stronger terminal-TF edge is inferred.', 'The source supports a bounded receptor/pathway or functional association; no direct TF occupancy or terminal target locus was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMID10848816_FBLN2_ITGB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005425' AND x.extraction_id='M22B-P2-R-000812');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000690', 'M23B-P2-R-000647', 'PMID:10848816; DOI:10.1046/j.1365-2141.2000.02011.x', '10848816', 'literature_xml', 'exact_identifier_match:PMID:10848816', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMID:10848816; DOI:10.1046/j.1365-2141.2000.02011.x; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMID10848816_FBLN2_ITGB3_pubmed.xml', 'The primary bone-marrow-stroma study reports that recombinant mouse fibulin-2 adhered to human HEL cells through beta3 integrins, but it did not provide a purified FBLN2-to-ITGB3 binding measurement or isolate a defined alpha/beta3 receptor complex. It also reports no adhesion of mouse megakaryocytes to mouse fibulin-2.', 'Do not promote a direct FBLN2–ITGB3 binding edge from this source. Retain only the separate beta3-integrin-dependent cell-adhesion observation under EVID-000692.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMID10848816_FBLN2_ITGB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000690' AND x.extraction_id='M23B-P2-R-000647');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000691', 'M23B-P2-R-000648', 'PMID:10848816; DOI:10.1046/j.1365-2141.2000.02011.x', '10848816', 'literature_xml', 'exact_identifier_match:PMID:10848816', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMID:10848816; DOI:10.1046/j.1365-2141.2000.02011.x; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMID10848816_FBLN2_ITGB3_pubmed.xml', 'The primary FBLN2 study reports beta3-integrin-dependent adhesion but no receptor-proximal phosphorylation, adaptor, second-messenger, or pathway assay downstream of the FBLN2/ITGB3 relationship.', 'Do not promote an FBLN2–ITGB3 receptor-proximal relay from this paper. Leave the intracellular signaling layer unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMID10848816_FBLN2_ITGB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000691' AND x.extraction_id='M23B-P2-R-000648');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000506', 'M23B-EVID-000692', 'M23B-P2-R-000649', 'PMID:10848816; DOI:10.1046/j.1365-2141.2000.02011.x', '10848816', 'literature_xml', 'exact_identifier_match:PMID:10848816', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:10848816; DOI:10.1046/j.1365-2141.2000.02011.x; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMID10848816_FBLN2_ITGB3_pubmed.xml', 'Recombinant mouse fibulin-2 adhesion to human HEL cells was mediated by beta3 integrins, whereas cultured mouse megakaryocytes did not adhere to mouse fibulin-2. The paper therefore supports a bounded beta3-integrin-dependent cell-attachment output with a strong species/context limitation.', 'Promote the bounded FBLN2→beta3-integrin-dependent cell-adhesion output observed in human HEL cells. Do not generalize it to mouse megakaryocytes, a defined ITGB3 heterodimer, a receptor-proximal relay, or a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B133_PMID10848816_FBLN2_ITGB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000692' AND x.extraction_id='M23B-P2-R-000649');
