INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000510', 'M23B-EVID-000696', 'M23B-P2-R-000653', 'PMCID:PMC2132927; PMID:10037797; DOI:10.1083/jcb.144.4.767', '10037797', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2132927', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2132927; PMID:10037797; DOI:10.1083/jcb.144.4.767; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B134_PMC2132927_CD23_ITGAVB3_CD47_fulltext_bioc.json', 'Soluble CD23 bound human alphaV-positive cells and purified alphaV protein; CD47 coexpression increased binding, while purified beta3 and recombinant CD47 alone did not bind sCD23. The primary study therefore supports direct CD23-alphaV contact within an alphaVbeta3/CD47 functional receptor complex, not a direct CD23-beta3 or CD23-CD47 binary edge.', 'Promote the bounded sCD23/FcER2A→alphaV-containing vitronectin-receptor complex direct-contact record. Keep alphaV as the demonstrated direct binding target and beta3/CD47 as complex-associated functional components; do not create separate sCD23-beta3 or sCD23-CD47 direct edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B134_PMC2132927_CD23_ITGAVB3_CD47_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000696' AND x.extraction_id='M23B-P2-R-000653');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000511', 'M23B-EVID-000697', 'M23B-P2-R-000654', 'PMCID:PMC2132927; PMID:10037797; DOI:10.1083/jcb.144.4.767', '10037797', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2132927', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2132927; PMID:10037797; DOI:10.1083/jcb.144.4.767; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B134_PMC2132927_CD23_ITGAVB3_CD47_fulltext_bioc.json', 'Anti-CD47 and anti-beta3 antibodies suppressed sCD23-induced TNF-alpha, IL-12 and IFN-gamma outputs without blocking sCD23 binding, supporting a receptor-complex signaling role for CD47 and beta3 downstream of direct alphaV engagement. The paper does not identify a unique intracellular adaptor or kinase relay.', 'Promote the bounded sCD23→alphaV-containing alphaVbeta3/CD47 receptor complex→CD47/beta3-dependent inflammatory signaling branch. Do not infer a specific intracellular kinase, adaptor, or terminal TF from antibody-sensitive cytokine outputs.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B134_PMC2132927_CD23_ITGAVB3_CD47_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000697' AND x.extraction_id='M23B-P2-R-000654');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000512', 'M23B-EVID-000698', 'M23B-P2-R-000655', 'PMCID:PMC2132927; PMID:10037797; DOI:10.1083/jcb.144.4.767', '10037797', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2132927', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2132927; PMID:10037797; DOI:10.1083/jcb.144.4.767; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B134_PMC2132927_CD23_ITGAVB3_CD47_fulltext_bioc.json', 'sCD23 stimulation of human monocytes and T-cell/monocyte cocultures induced TNF-alpha, IL-1beta, PGE2, IL-12 and IFN-gamma outputs; anti-CD47 or anti-beta3 inhibition suppressed relevant cytokine responses. This is a receptor-complex inflammatory functional output, not a terminal TF claim.', 'Promote the bounded sCD23→alphaV-containing vitronectin-receptor/CD47 complex→TNF-alpha, IL-1beta, IL-12, IFN-gamma and PGE2 inflammatory output branch. Keep cytokine outputs separate from direct binding and unnamed intracellular relay evidence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B134_PMC2132927_CD23_ITGAVB3_CD47_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000698' AND x.extraction_id='M23B-P2-R-000655');
