INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000513', 'M23B-EVID-000699', 'M23B-P2-R-000656', 'PMID:11588042; DOI:10.1182/blood.v98.8.2448', '11588042', 'literature_xml', 'exact_identifier_match:PMID:11588042', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:11588042; DOI:10.1182/blood.v98.8.2448; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B135_PMID11588042_FGA420_ITGAM_ITGAX_pubmed.xml', 'The primary study identifies the alternatively spliced alpha(E)C domain of human fibrinogen-420 as a direct ligand for alphaMbeta2. Recombinant alpha(E)C bound the recombinant alphaM I domain in a dose-dependent and saturable manner, and alphaM- or beta2-directed antibodies and neutrophil inhibitory factor blocked cell adhesion.', 'Promote the bounded fibrinogen-420 alpha(E)C→alphaMbeta2 direct binding record. Do not relabel the alpha(E)C splice-domain ligand as the common plasma fibrinogen A-alpha chain or transfer gammaC-site evidence to this record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B135_PMID11588042_FGA420_ITGAM_ITGAX_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000699' AND x.extraction_id='M23B-P2-R-000656');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000700', 'M23B-P2-R-000657', 'PMID:11588042; DOI:10.1182/blood.v98.8.2448', '11588042', 'literature_xml', 'exact_identifier_match:PMID:11588042', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMID:11588042; DOI:10.1182/blood.v98.8.2448; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B135_PMID11588042_FGA420_ITGAM_ITGAX_pubmed.xml', 'The primary alpha(E)C fibrinogen-420 study measures ligand binding, cell adhesion and migration, but reports no qualifying receptor-proximal phosphorylation, adaptor, second-messenger, or intracellular pathway assay downstream of alphaMbeta2.', 'Do not promote a receptor-proximal FGA-420 alphaMbeta2 relay from this paper. Leave the intracellular signaling layer unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B135_PMID11588042_FGA420_ITGAM_ITGAX_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000700' AND x.extraction_id='M23B-P2-R-000657');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000514', 'M23B-EVID-000701', 'M23B-P2-R-000658', 'PMID:11588042; DOI:10.1182/blood.v98.8.2448', '11588042', 'literature_xml', 'exact_identifier_match:PMID:11588042', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:11588042; DOI:10.1182/blood.v98.8.2448; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B135_PMID11588042_FGA420_ITGAM_ITGAX_pubmed.xml', 'Recombinant alpha(E)C supported adhesion and migration of nonactivated and activated U937 and THP-1 monocytoid cells and neutrophils expressing alphaMbeta2; alphaM, beta2 and neutrophil-inhibitory-factor blockade inhibited adhesion.', 'Promote the bounded fibrinogen-420 alpha(E)C→alphaMbeta2→leukocyte adhesion/migration functional branch. Keep the alpha(E)C splice-domain identity and the direct alphaM I-domain record explicit.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B135_PMID11588042_FGA420_ITGAM_ITGAX_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000701' AND x.extraction_id='M23B-P2-R-000658');
