INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000516', 'M23B-EVID-000704', 'M23B-P2-R-000661', 'PMID:11588042; DOI:10.1182/blood.v98.8.2448', '11588042', 'literature_xml', 'exact_identifier_match:PMID:11588042', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:11588042; DOI:10.1182/blood.v98.8.2448; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B135_PMID11588042_FGA420_ITGAM_ITGAX_pubmed.xml', 'The alpha(E)C domain of fibrinogen-420 supported adhesion of alphaXbeta2-expressing U937 and THP-1 cells and neutrophils; alphaX- and beta2-directed antibodies and neutrophil inhibitory factor inhibited the alpha(E)C-dependent adhesion.', 'Promote the bounded fibrinogen-420 alpha(E)C→alphaXbeta2→leukocyte adhesion functional branch. Keep it separate from the direct alphaX I-domain binding record and preserve the alpha(E)C splice-domain identity.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B135_PMID11588042_FGA420_ITGAM_ITGAX_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000704' AND x.extraction_id='M23B-P2-R-000661');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005471', 'M22B-EVID-003557', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC25719_FGF2_ITGAVB3_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003557' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000519', 'M23B-EVID-000708', 'M23B-P2-R-000665', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449', '9398667', 'full_text_html', 'exact_identifier_match:DOI:10.1091/mbc.8.12.2449;PMCID:PMC25719', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC25719_FGF2_ITGAVB3_fulltext.html', 'Purified human alphaVbeta3 bound immobilized FGF2 in a cation-dependent cell-free assay; anti-alphaVbeta3 antibodies blocked endothelial adhesion to FGF2, and soluble vitronectin competed with the interaction. The study therefore supports an exact FGF2-alphaVbeta3 receptor-complex interaction, not an FGF2-ITGB3-alone edge.', 'Promote the bounded FGF2→alphaVbeta3 direct binding/activation record. Preserve the complete alphaVbeta3 heterodimer and distinguish this integrin coreceptor interaction from FGFR1 binding and downstream FGF2 signaling.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC25719_FGF2_ITGAVB3_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000708' AND x.extraction_id='M23B-P2-R-000665');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000520', 'M23B-EVID-000709', 'M23B-P2-R-000666', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; PMID:28302677; PMCID:PMC5482197', '9398667', 'full_text_html', 'exact_identifier_match:DOI:10.1091/mbc.8.12.2449;PMCID:PMC25719', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; linked PMCID:PMC5482197; PMID:28302677; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC25719_FGF2_ITGAVB3_fulltext.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC5482197_FGF2_integrin_mutant_fulltext_bioc.json', 'Primary FGF2 studies support an alphaVbeta3/FGFR1 receptor-complex branch. Purified alphaVbeta3 binding is cation-dependent, and integrin-binding-defective FGF2 mutants show reduced sustained ERK1/2 activation and DNA synthesis/migration, while suppressing wild-type FGF2 responses.', 'Promote the bounded FGF2→alphaVbeta3/FGFR1 receptor-complex→sustained ERK1/2 and mitogenic/migratory signaling branch. Preserve that the integrin is a coreceptor/complex component and do not infer an isolated ITGB3 cytoplasmic relay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC25719_FGF2_ITGAVB3_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000709' AND x.extraction_id='M23B-P2-R-000666');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000521', 'M23B-EVID-000710', 'M23B-P2-R-000667', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449', '9398667', 'full_text_html', 'exact_identifier_match:DOI:10.1091/mbc.8.12.2449;PMCID:PMC25719', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC25719_FGF2_ITGAVB3_fulltext.html', 'FGF2 interaction with alphaVbeta3 mediated endothelial cell adhesion, mitogenesis, and urokinase-type plasminogen activator up-regulation; anti-alphaVbeta3 antibodies inhibited the adhesion and free-FGF2 biological outputs in the primary endothelial models.', 'Promote the bounded FGF2→alphaVbeta3/FGFR1 receptor-complex→endothelial adhesion, mitogenesis, and uPA-upregulation functional branch. Keep the integrin coreceptor and FGFR1 contributions distinct.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC25719_FGF2_ITGAVB3_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000710' AND x.extraction_id='M23B-P2-R-000667');
