INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000517', 'M23B-EVID-000705', 'M23B-P2-R-000662', 'PMCID:PMC3307134; PMID:19413351; DOI:10.1021/bi900487d', '19413351', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3307134', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3307134; PMID:19413351; DOI:10.1021/bi900487d; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC3307134_FGB_VEcadherin_fulltext_bioc.json', 'Recombinant fibrin betaN domains, including the dimeric (beta15-66)2 fragment, bound recombinant human VE-cadherin extracellular fragments in ELISA and surface-plasmon-resonance assays. The fibrin-binding site was localized to the third extracellular VE-cadherin domain; the betaN domains were the only tested fibrin(ogen) region with binding, with reported nanomolar affinities.', 'Promote the bounded fibrin betaN/FGB→VE-cadherin (CDH5) direct binding record, specifying fibrin/fibrin-betaN exposure rather than soluble fibrinogen and mapping the receptor contact to VE-cadherin extracellular domain 3.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC3307134_FGB_VEcadherin_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000705' AND x.extraction_id='M23B-P2-R-000662');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000706', 'M23B-P2-R-000663', 'PMCID:PMC3307134; PMID:19413351; DOI:10.1021/bi900487d', '19413351', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3307134', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMCID:PMC3307134; PMID:19413351; DOI:10.1021/bi900487d; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC3307134_FGB_VEcadherin_fulltext_bioc.json', 'The fibrin betaN/VE-cadherin primary study is biochemical domain mapping and does not report a qualifying receptor-proximal phosphorylation, adaptor, second-messenger, or intracellular relay downstream of the interaction.', 'Do not promote a fibrin betaN/VE-cadherin receptor-proximal relay from this paper. Leave the intracellular signaling layer unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC3307134_FGB_VEcadherin_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000706' AND x.extraction_id='M23B-P2-R-000663');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000518', 'M23B-EVID-000707', 'M23B-P2-R-000664', 'PMCID:PMC3307134; PMID:19413351; DOI:10.1021/bi900487d', '19413351', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3307134', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMCID:PMC3307134; PMID:19413351; DOI:10.1021/bi900487d; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC3307134_FGB_VEcadherin_fulltext_bioc.json', 'The primary fibrin betaN/VE-cadherin paper states that fibrin-VE-cadherin interaction has been implicated in angiogenesis and inflammation, but the experiments in this paper are biochemical binding/domain-mapping assays and do not directly measure endothelial barrier, tube formation, angiogenesis, or inflammatory output.', 'Do not promote the queued downstream functional edge from this paper. Preserve the direct fibrin betaN–VE-cadherin binding record and leave the exact cellular output unknown until a primary functional study is separately processed.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC3307134_FGB_VEcadherin_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000707' AND x.extraction_id='M23B-P2-R-000664');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005471', 'M22B-EVID-003557', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMID9398667_FGF2_ITGAVB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003557' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000519', 'M23B-EVID-000708', 'M23B-P2-R-000665', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449', '9398667', 'literature_xml', 'exact_identifier_match:PMID:9398667', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMC25719_FGF2_ITGAVB3_fulltext.html', 'Purified human alphaVbeta3 bound immobilized FGF2 in a cation-dependent cell-free assay; anti-alphaVbeta3 antibodies blocked endothelial adhesion to FGF2, and soluble vitronectin competed with the interaction. The study therefore supports an exact FGF2-alphaVbeta3 receptor-complex interaction, not an FGF2-ITGB3-alone edge.', 'Promote the bounded FGF2→alphaVbeta3 direct binding/activation record. Preserve the complete alphaVbeta3 heterodimer and distinguish this integrin coreceptor interaction from FGFR1 binding and downstream FGF2 signaling.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMID9398667_FGF2_ITGAVB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000708' AND x.extraction_id='M23B-P2-R-000665');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000520', 'M23B-EVID-000709', 'M23B-P2-R-000666', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; PMID:28302677; PMCID:PMC5482197', '9398667', 'literature_xml', 'exact_identifier_match:PMID:9398667', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; linked PMCID:PMC5482197; PMID:28302677; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC25719_FGF2_ITGAVB3_fulltext.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC5482197_FGF2_integrin_mutant_fulltext_bioc.json', 'Primary FGF2 studies support an alphaVbeta3/FGFR1 receptor-complex branch. Purified alphaVbeta3 binding is cation-dependent, and integrin-binding-defective FGF2 mutants show reduced sustained ERK1/2 activation and DNA synthesis/migration, while suppressing wild-type FGF2 responses.', 'Promote the bounded FGF2→alphaVbeta3/FGFR1 receptor-complex→sustained ERK1/2 and mitogenic/migratory signaling branch. Preserve that the integrin is a coreceptor/complex component and do not infer an isolated ITGB3 cytoplasmic relay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMID9398667_FGF2_ITGAVB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000709' AND x.extraction_id='M23B-P2-R-000666');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000521', 'M23B-EVID-000710', 'M23B-P2-R-000667', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449', '9398667', 'literature_xml', 'exact_identifier_match:PMID:9398667', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC25719_FGF2_ITGAVB3_fulltext.html', 'FGF2 interaction with alphaVbeta3 mediated endothelial cell adhesion, mitogenesis, and urokinase-type plasminogen activator up-regulation; anti-alphaVbeta3 antibodies inhibited the adhesion and free-FGF2 biological outputs in the primary endothelial models.', 'Promote the bounded FGF2→alphaVbeta3/FGFR1 receptor-complex→endothelial adhesion, mitogenesis, and uPA-upregulation functional branch. Keep the integrin coreceptor and FGFR1 contributions distinct.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B136_PMID9398667_FGF2_ITGAVB3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000710' AND x.extraction_id='M23B-P2-R-000667');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005481', 'M22B-EVID-003567', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC4767336_FGF23_FGFR2_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003567' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000522', 'M23B-EVID-000711', 'M23B-P2-R-000668', 'PMCID:PMC4767336; PMID:26878171; DOI:10.1172/JCI83470', '26878171', 'full_text_html', 'exact_identifier_match:DOI:10.1172/jci83470;PMCID:PMC4767336', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC4767336; PMID:26878171; DOI:10.1172/JCI83470; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC4767336_FGF23_FGFR2_fulltext.html', 'In primary human neutrophil and HL60 systems, the study identifies FGFR2 as the cell-surface FGF receptor mediating FGF23 effects; FGFR2 knockdown or pharmacologic FGFR blockade rescued CKD-associated neutrophil recruitment and host defense. The authors describe the mechanism as FGF23 binding to FGFR2, but no purified affinity measurement was performed.', 'Promote the bounded FGF23→FGFR2 receptor-engagement record in neutrophils, while explicitly labeling it as receptor dependence rather than purified FGF23-FGFR2 affinity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC4767336_FGF23_FGFR2_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000711' AND x.extraction_id='M23B-P2-R-000668');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000523', 'M23B-EVID-000712', 'M23B-P2-R-000669', 'PMCID:PMC4767336; PMID:26878171; DOI:10.1172/JCI83470', '26878171', 'full_text_html', 'exact_identifier_match:DOI:10.1172/jci83470;PMCID:PMC4767336', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC4767336; PMID:26878171; DOI:10.1172/JCI83470; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC4767336_FGF23_FGFR2_fulltext.html', 'FGF23 exposure of primary human neutrophils and HL60 cells increased PKA substrate phosphorylation and reduced chemokine-triggered Rap1-GTP; PKA knockdown abolished FGF23-mediated inhibition of beta2-integrin activation. This supports an FGF23-FGFR2→PKA→Rap1 inhibition→beta2-integrin deactivation relay.', 'Promote the bounded FGF23→FGFR2→PKA activation→Rap1 inhibition→beta2-integrin deactivation receptor-proximal relay. Do not infer a terminal TF or transfer the branch to Klotho-dependent renal signaling.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC4767336_FGF23_FGFR2_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000712' AND x.extraction_id='M23B-P2-R-000669');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000524', 'M23B-EVID-000713', 'M23B-P2-R-000670', 'PMCID:PMC4767336; PMID:26878171; DOI:10.1172/JCI83470', '26878171', 'full_text_html', 'exact_identifier_match:DOI:10.1172/jci83470;PMCID:PMC4767336', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC4767336; PMID:26878171; DOI:10.1172/JCI83470; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC4767336_FGF23_FGFR2_fulltext.html', 'FGF23 inhibited neutrophil adhesion, arrest under flow, and transendothelial migration in vitro. In mouse CKD and pneumonia models, elevated FGF23 impaired neutrophil recruitment and bacterial clearance; FGF23 neutralization or FGFR2 knockdown restored host defense and recruitment.', 'Promote the bounded FGF23→FGFR2→PKA/Rap1/beta2-integrin deactivation→impaired neutrophil recruitment and host-defense functional branch. Keep the molecular relay and immune outputs distinct.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC4767336_FGF23_FGFR2_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000713' AND x.extraction_id='M23B-P2-R-000670');
