INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000520', 'M23B-EVID-000709', 'M23B-P2-R-000666', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; PMID:28302677; PMCID:PMC5482197', '9398667', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC5482197', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC25719; PMID:9398667; DOI:10.1091/mbc.8.12.2449; linked PMCID:PMC5482197; PMID:28302677; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC25719_FGF2_ITGAVB3_fulltext.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC5482197_FGF2_integrin_mutant_fulltext_bioc.json', 'Primary FGF2 studies support an alphaVbeta3/FGFR1 receptor-complex branch. Purified alphaVbeta3 binding is cation-dependent, and integrin-binding-defective FGF2 mutants show reduced sustained ERK1/2 activation and DNA synthesis/migration, while suppressing wild-type FGF2 responses.', 'Promote the bounded FGF2→alphaVbeta3/FGFR1 receptor-complex→sustained ERK1/2 and mitogenic/migratory signaling branch. Preserve that the integrin is a coreceptor/complex component and do not infer an isolated ITGB3 cytoplasmic relay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B137_PMC5482197_FGF2_integrin_mutant_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000709' AND x.extraction_id='M23B-P2-R-000666');
