INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000525', 'M23B-EVID-000715', 'M23B-P2-R-000672', 'PMID:41967236; DOI:10.1016/j.abb.2026.110820', '41967236', 'literature_xml', 'exact_identifier_match:PMID:41967236', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:41967236; DOI:10.1016/j.abb.2026.110820; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B138_PMID41967236_FGL1_EGFR_pubmed.xml', 'In primary human endothelial systems, recombinant hepassocin/FGL1 activates EGFR and engages an EGFR-NOX1/p22phox redox module with ROS amplification; EGFR or NOX1 silencing abolishes the redox and atherogenic phenotype. EGFR-dependent p38 activation is also reported, and p38 suppression reduces FGL1-driven endothelial activation and monocyte adhesion.', 'Promote the bounded FGL1/hepassocin->EGFR->NOX1/p22phox-ROS and EGFR->p38 receptor-proximal/pathway branches. Do not convert EGFR dependence into a direct FGL1-EGFR binding claim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B138_PMID41967236_FGL1_EGFR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000715' AND x.extraction_id='M23B-P2-R-000672');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000526', 'M23B-EVID-000716', 'M23B-P2-R-000673', 'PMID:41967236; DOI:10.1016/j.abb.2026.110820', '41967236', 'literature_xml', 'exact_identifier_match:PMID:41967236', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:41967236; DOI:10.1016/j.abb.2026.110820; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B138_PMID41967236_FGL1_EGFR_pubmed.xml', 'In HUVECs, recombinant hepassocin/FGL1 increases ROS and lipid peroxidation, promotes endothelial apoptosis and adhesion-molecule expression, and enhances monocyte-endothelial adhesion. The primary study also reports corresponding vascular activation in high-fat-diet mouse models.', 'Promote the bounded FGL1/hepassocin->EGFR-dependent NOX1/ROS and p38-associated endothelial injury/atherogenic activation functional branch, with monocyte-endothelial adhesion as a measured output.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B138_PMID41967236_FGL1_EGFR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000716' AND x.extraction_id='M23B-P2-R-000673');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000531', 'M23B-EVID-000723', 'M23B-P2-R-000680', 'PMCID:PMC2683942; PMID:19765300; DOI:10.1186/gb-2009-10-9-r99; DOI:10.1371/journal.pone.0005742', '19765300', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2683942', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2683942; PMID:19765300; DOI:10.1186/gb-2009-10-9-r99; DOI:10.1371/journal.pone.0005742; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B139_PMC2683942_FLRT3_UNC5B_fulltext_bioc.json', 'Primary cell-surface binding, co-immunoprecipitation, and equilibrium binding experiments show that FLRT3 interacts specifically with UNC5B ectodomains; the FLRT3-UNC5B binding curve reports a Kd of approximately 50 nM, with the FLRT3 LRR region required for binding.', 'Promote the direct FLRT3->UNC5B extracellular binding edge, with bounded ectodomain affinity and LRR-domain mapping. Keep the later Rnd1/cell-adhesion relay and embryonic functional output as separate evidence records.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B139_PMC2683942_FLRT3_UNC5B_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000723' AND x.extraction_id='M23B-P2-R-000680');
