INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000529', 'M23B-EVID-000720', 'M23B-P2-R-000677', 'PMCID:PMC3326387; PMID:22405201; DOI:10.1016/j.neuron.2012.01.018', '22405201', 'literature_xml', 'exact_identifier_match:PMID:22405201', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3326387; PMID:22405201; DOI:10.1016/j.neuron.2012.01.018; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B139_PMC3326387_FLRT3_ADGRL3_fulltext_bioc.json', 'Primary affinity-chromatography, cell-binding, cell-free co-precipitation, and SPR experiments show direct trans interaction between FLRT3 and LPHN3/ADGRL3 ectodomains; the SPR assay reports a Kd of 14.7 nM for the FLRT3-LPHN3 interaction.', 'Promote the direct FLRT3->ADGRL3/LPHN3 extracellular trans-synaptic binding edge, with high-affinity ectodomain support. Do not infer a ligand-specific intracellular G-protein relay from the paper''s discussion.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B139_PMID22405201_FLRT3_ADGRL3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000720' AND x.extraction_id='M23B-P2-R-000677');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000721', 'M23B-P2-R-000678', 'PMCID:PMC3326387; PMID:22405201; DOI:10.1016/j.neuron.2012.01.018', '22405201', 'literature_xml', 'exact_identifier_match:PMID:22405201', 'candidate_requires_review', 'B', 'L2', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMCID:PMC3326387; PMID:22405201; DOI:10.1016/j.neuron.2012.01.018; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B139_PMC3326387_FLRT3_ADGRL3_fulltext_bioc.json', 'The primary FLRT3-LPHN3 paper reports no qualifying ligand-specific phosphorylation, adaptor recruitment, second-messenger, or intracellular relay assay. Its discussion mentions possible G-protein and IP3-mediated calcium signaling by analogy to alpha-latrotoxin and explicitly states that the immediate consequences of FLRT binding remain unknown.', 'Do not promote a ligand-specific FLRT3-ADGRL3 receptor-proximal relay from this paper. Leave adaptor, kinase, second messenger, and terminal TF unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B139_PMID22405201_FLRT3_ADGRL3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000721' AND x.extraction_id='M23B-P2-R-000678');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000530', 'M23B-EVID-000722', 'M23B-P2-R-000679', 'PMCID:PMC3326387; PMID:22405201; DOI:10.1016/j.neuron.2012.01.018', '22405201', 'literature_xml', 'exact_identifier_match:PMID:22405201', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3326387; PMID:22405201; DOI:10.1016/j.neuron.2012.01.018; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B139_PMC3326387_FLRT3_ADGRL3_fulltext_bioc.json', 'Disrupting FLRT3-LPHN3 complexes with soluble ecto-LPHN3-Fc or FLRT3/LPHN3 shRNA reduces excitatory synapse density and miniature EPSC frequency in cultured hippocampal neurons. FLRT3 knockdown also reduces dentate-granule-cell dendritic spine density and evoked AMPA/NMDA synaptic input in vivo.', 'Promote the bounded FLRT3->ADGRL3/LPHN3 trans-synaptic complex->excitatory-synapse density, dendritic-spine, and synaptic-input functional branch. Keep the measured outputs separate from the direct binding and unresolved intracellular relay records.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B139_PMID22405201_FLRT3_ADGRL3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000722' AND x.extraction_id='M23B-P2-R-000679');
