INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000536', 'M23B-EVID-000731', 'M23B-P2-R-000688', 'PMCID:PMC2115745; PMID:2527858', '2527858', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2115745', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2115745; PMID:2527858; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B141_PMC2115745_FN1_ITGA4B1_fulltext_bioc.json', 'Alpha4beta1-directed antibodies selectively inhibit human T-lymphocyte adhesion to the CS-1-containing fibronectin fragment, while alpha5beta1-directed antibodies inhibit adhesion to the RGD-containing fragment. This establishes the FN1-CS1-alpha4beta1-dependent leukocyte-adhesion output.', 'Promote the bounded FN1-CS1->alpha4beta1 leukocyte-adhesion functional branch. Keep it separate from the receptor-selective binding record and leave intracellular relay unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B141_PMC2115745_FN1_ITGA4B1_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000731' AND x.extraction_id='M23B-P2-R-000688');
