INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000537', 'M23B-EVID-000732', 'M23B-P2-R-000689', 'PMCID:PMC2289398; PMID:1372909', '1372909', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2289398', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2289398; PMID:1372909; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B141_PMC2289398_FN1_ITGA4B7_fulltext_bioc.json', 'Primary mouse TK-1 lymphoblast and activated human T-cell studies identify alpha4beta7 as a fibronectin receptor for the CS-1 region. Alpha4 antibodies inhibit adhesion, and affinity chromatography confirms alpha4beta7 binding to the CS-1 fibronectin fragment; PMA increases fibronectin binding.', 'Promote the bounded FN1-CS1->ITGA4:ITGB7 (alpha4beta7/alpha4betaP) receptor-binding record, including affinity-chromatography support. Do not merge it with alpha4beta1 or infer mucosal MAdCAM-1 biology from this FN1 record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B141_PMC2289398_FN1_ITGA4B7_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000732' AND x.extraction_id='M23B-P2-R-000689');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000733', 'P2FALLBACK-23B-M23B-EVID-000733', 'URL:https://pmc.ncbi.nlm.nih.gov/articles/PMC2289398/', '1372909', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2289398', 'candidate_requires_review', NULL, 'L1', 'unresolved', 'unresolved', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2289398/', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B141_PMC2289398_FN1_ITGA4B7_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000733' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000733');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000538', 'M23B-EVID-000734', 'M23B-P2-R-000691', 'PMCID:PMC2289398; PMID:1372909', '1372909', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2289398', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2289398; PMID:1372909; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B141_PMC2289398_FN1_ITGA4B7_fulltext_bioc.json', 'Alpha4beta7/alpha4betaP mediates mouse TK-1-cell adhesion to intact fibronectin and the CS-1 fibronectin fragment; adhesion is inhibited by alpha4 antibodies and enhanced by brief PMA stimulation. The same receptor also supports VCAM-1 adhesion, which is retained only as a comparator and not merged into the FN1 output.', 'Promote the bounded FN1-CS1->alpha4beta7 lymphocyte-adhesion functional branch, with PMA-dependent avidity modulation recorded as context. Do not transfer the VCAM-1/MAdCAM-1 homing branch into this FN1 output.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B141_PMC2289398_FN1_ITGA4B7_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000734' AND x.extraction_id='M23B-P2-R-000691');
