INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000541', 'M23B-EVID-000738', 'M23B-P2-R-000695', 'PMCID:PMC2119613; PMID:8314844', '8314844', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2119613', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2119613; PMID:8314844; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC2119613_FN1_ITGAVB1_fulltext_bioc.json', 'In engineered CHO-B2 cells lacking alpha5, human alphaV combines with endogenous beta1 to form alphaVbeta1. AlphaVbeta1-expressing cells attach and spread on fibronectin-coated dishes, with lower FN1 affinity than alpha5beta1 controls, establishing a bounded cell-surface FN1 receptor record.', 'Promote the bounded FN1->ITGAV:ITGB1 (alphaVbeta1) cell-surface receptor record. Do not infer purified affinity, FN1 matrix assembly, migration, or an intracellular relay from this engineered-cell study.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC2119613_FN1_ITGAVB1_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000738' AND x.extraction_id='M23B-P2-R-000695');
