INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000542', 'M23B-EVID-000740', 'M23B-P2-R-000697', 'PMCID:PMC2119613; PMID:8314844', '8314844', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2119613', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2119613; PMID:8314844; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC2119613_FN1_ITGAVB1_fulltext_bioc.json', 'Engineered CHO-B2 cells expressing alphaVbeta1 attach and spread on fibronectin-coated dishes, but alphaVbeta1 fails to support fibronectin matrix assembly or migration in the tested model; alpha5beta1 controls do support those outputs and show higher FN1 affinity.', 'Promote the bounded FN1->alphaVbeta1 attachment/spreading functional branch, with failure of matrix assembly and migration retained as a model-specific limitation. Do not transfer alpha5beta1 outputs to alphaVbeta1.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC2119613_FN1_ITGAVB1_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000740' AND x.extraction_id='M23B-P2-R-000697');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E001502', 'M22B-EVID-002262', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC301202_FN1_ITGA8B1_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002262' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000539', 'M23B-EVID-000735', 'M23B-P2-R-000692', 'PMCID:PMC301202; PMID:7626807; DOI:10.1091/mbc.6.4.433; PMID:7559467; DOI:10.1074/jbc.270.39.23196', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC301202', 'candidate_requires_review', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC301202; PMID:7626807; DOI:10.1091/mbc.6.4.433; PMID:7559467; DOI:10.1074/jbc.270.39.23196; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC301202_FN1_ITGA8B1_fulltext.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMID7626807_FN1_ITGA8B1_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMID7559467_FN1_ITGA8B1_pubmed.xml', 'Two primary alpha8beta1 studies support FN1-RGD recognition. The PMC301202/PMID7626807 study shows alpha8beta1-transfected K562 cells adhere to fibronectin and that RGD peptides inhibit the interaction; the PMID7559467 study shows alpha8beta1-transfected 293 cells bind fibronectin-Sepharose and are eluted by GRGDSP. The queue''s PMC301202-PMID7559467 pairing was corrected: these are distinct primary records.', 'Promote the direct/bounded FN1-RGD->ITGA8:ITGB1 (alpha8beta1) receptor-binding record, supported by receptor-specific adhesion and RGD-dependent ligand capture. Preserve the corrected PMID/PMCID mapping and do not infer an intracellular relay.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC301202_FN1_ITGA8B1_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000735' AND x.extraction_id='M23B-P2-R-000692');
