INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000540', 'M23B-EVID-000737', 'M23B-P2-R-000694', 'PMCID:PMC301202; PMID:7626807; DOI:10.1091/mbc.6.4.433; PMID:7559467; DOI:10.1074/jbc.270.39.23196', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC301202', 'candidate_requires_review', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC301202; PMID:7626807; DOI:10.1091/mbc.6.4.433; PMID:7559467; DOI:10.1074/jbc.270.39.23196; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC301202_FN1_ITGA8B1_fulltext.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMID7626807_FN1_ITGA8B1_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMID7559467_FN1_ITGA8B1_pubmed.xml', 'Alpha8beta1 promotes attachment and cell spreading on fibronectin in engineered cells, and the primary PMC301202 study reports extensive neurite outgrowth on fibronectin. Alpha8beta1 localization to focal adhesions is observed in chick fibroblast comparators; the receptor does not establish FN1 matrix assembly or migration in the tested CHO-like comparator context.', 'Promote the bounded FN1-RGD->alpha8beta1 attachment, spreading, and neurite-outgrowth functional branch. Keep the absence of FN1 matrix assembly/migration in the tested comparator as a limitation rather than a general negative claim.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMC301202_FN1_ITGA8B1_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000737' AND x.extraction_id='M23B-P2-R-000694');
