INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004032', 'M22B-EVID-002414', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMID7559467_FN1_ITGA8B1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002414' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000074', 'M23B-EVID-000136', 'M23B-P2-R-000136', 'PMID:7541634; PMCID:PMC2692383; DOI:10.1016/0896-6273(95)90268-6; PMID:7559467; DOI:10.1074/jbc.270.39.23196; PMID:9548928; PMCID:PMC2710129; DOI:10.1021/bi9727489', '7559467', 'literature_xml', 'exact_identifier_match:PMID:7559467', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:7541634; PMCID:PMC2692383; DOI:10.1016/0896-6273(95)90268-6; PMID:7559467; DOI:10.1074/jbc.270.39.23196; PMID:9548928; PMCID:PMC2710129; DOI:10.1021/bi9727489; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2692383.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2710129.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC2692383/; https://pmc.ncbi.nlm.nih.gov/articles/PMC2710129/', 'The primary alpha8beta1-tenascin studies support a construct- and context-dependent interaction. In embryonic chick motor/sensory neuron and K562-cell assays, alpha8beta1 antibodies or alpha8 expression supported tenascin-dependent neurite outgrowth/attachment, with tenascin FNIII6-8 implicated. In contrast, soluble murine alpha8beta1-AP bound fibronectin/vitronectin and short tenascin-C fragments containing the third FNIII RGD site, but showed no strong binding to native full-length tenascin-C. The direct molecular record is therefore restricted to RGD-containing tenascin fragments; native TNC cell responses remain a separate context.', 'The primary studies support alpha8beta1 recognition of tenascin-C-derived RGD-containing fragments and alpha8beta1-dependent neuronal/cell adhesion responses to tenascin in selected models. They do not justify an unconditional direct molecular native-TNC-alpha8beta1 claim because soluble alpha8beta1-AP failed to bind strongly to native full-length TNC in one primary study; no intracellular relay or TF endpoint was assayed.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMID7559467_FN1_ITGA8B1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000136' AND x.extraction_id='M23B-P2-R-000136');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000083', 'M23B-EVID-000145', 'M23B-P2-R-000145', 'PMID:7559467; DOI:10.1074/jbc.270.39.23196', '7559467', 'literature_xml', 'exact_identifier_match:PMID:7559467', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:7559467; DOI:10.1074/jbc.270.39.23196; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16099885_7541634_7559467_9548928_7523411_9565552.xml; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/7559467/', 'The primary study reports that alpha8-transfected human 293 cells use alpha8beta1 for adhesion to fibronectin and vitronectin, that alpha8beta1 binds fibronectin- and vitronectin-Sepharose and is eluted by RGD peptide, and that tenascin is also an alpha8beta1 ligand in cell-adhesion assays. This record captures the vitronectin-alpha8beta1 direct/affinity evidence; the tenascin result is separately represented in EVID-000136.', 'The primary study supports direct association of alpha8beta1 with vitronectin in affinity and cell-adhesion assays, with RGD-dependent elution. It does not establish intracellular signaling, SCI function, or a TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B142_PMID7559467_FN1_ITGA8B1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000145' AND x.extraction_id='M23B-P2-R-000145');
