INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000543', 'M23B-EVID-000741', 'M23B-P2-R-000698', 'PMCID:PMC2116382; PMID:1703545; DOI:10.1083/jcb.111.6.2795', '1703545', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2116382', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2116382; PMID:1703545; DOI:10.1083/jcb.111.6.2795; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B143_PMC2116382_FN1_ITGAVB3_fulltext_bioc.json', 'Purified alphaVbeta3 binds fibronectin with high affinity in a saturable, divalent-cation-dependent solid-phase assay. Binding is inhibited by soluble vitronectin, RGD peptides, and anti-alphaVbeta3 LM609; alphaVbeta3 is retained and RGDS-eluted from a fibronectin affinity column. M21 melanoma-cell adhesion also uses alphaVbeta3 together with alpha5beta1.', 'Promote the direct FN1-RGD->ITGAV:ITGB3 (alphaVbeta3) binding edge, with purified high-affinity, cation-dependent, and RGD/antibody-competitive support. Preserve alpha5beta1 cooperation as a separate receptor-complex context.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B143_PMC2116382_FN1_ITGAVB3_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000741' AND x.extraction_id='M23B-P2-R-000698');
