INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000543', 'M23B-EVID-000741', '', '', NULL, 'full_text_or_bioc_json', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B143_PMC2173988_FN1_ITGAVB3_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000741' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000544', 'M23B-EVID-000742', 'M23B-P2-R-000699', 'PMCID:PMC2173988; PMID:12486108; DOI:10.1083/jcb.200205014', '12486108', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2173988', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2173988; PMID:12486108; DOI:10.1083/jcb.200205014; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B143_PMC2173988_FN1_ITGAVB3_fulltext_bioc.json', 'In beta1-deficient GD25/GE11 cells using alphaVbeta3 for FN1 adhesion, fibronectin attachment produces an early decrease in RhoA-GTP and does not produce the sustained later RhoA-GTP increase seen with alpha5beta1. RhoA activity assays, integrin-expression controls, and FN1-spreading time courses support an alphaVbeta3-associated RhoA/focal-adhesion branch.', 'Promote the bounded FN1->alphaVbeta3 adhesion->RhoA-GTP modulation/focal-adhesion organization receptor-proximal branch. Treat RhoA as a measured pathway output, not as a directly bound alphaVbeta3 adaptor or a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B143_PMC2173988_FN1_ITGAVB3_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000742' AND x.extraction_id='M23B-P2-R-000699');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000545', 'M23B-EVID-000743', 'M23B-P2-R-000700', 'PMCID:PMC2173988; PMID:12486108; DOI:10.1083/jcb.200205014', '12486108', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2173988', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2173988; PMID:12486108; DOI:10.1083/jcb.200205014; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B143_PMC2173988_FN1_ITGAVB3_fulltext_bioc.json', 'AlphaVbeta3-mediated FN1 adhesion in beta1-deficient cells promotes cell spreading, cell-matrix adhesion formation, and scattering-like morphology, but does not support the later RhoA-dependent focal-contact translocation or robust FN1 fibrillogenesis seen with alpha5beta1. Constitutively active RhoA partially rescues alphaVbeta3-cell FN1 fibrillogenesis.', 'Promote the bounded FN1->alphaVbeta3->cell spreading/scattering and focal-adhesion organization functional branch, with limited FN1 fibrillogenesis and the active-RhoA rescue retained as context. Keep it distinct from the RhoA pathway record in EVID-000742.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B143_PMC2173988_FN1_ITGAVB3_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000743' AND x.extraction_id='M23B-P2-R-000700');
