INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000553', 'M23B-EVID-000753', 'M23B-P2-R-000710', 'PMCID:PMC11413474', '39310027', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11413474', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC11413474; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC11413474_IBSP_ITGAVB5_fulltext_bioc.json', 'Primary human cancer-cell adhesion assays show that bone sialoprotein/IBSP RGD-dependent attachment is reduced by GRGDSP peptide and by alphaVbeta5-blocking antibody in MDA-MB-231, PC-3, and NCI-H460 cells, with cell-line-specific contributions from alphaVbeta3. This supports receptor-mediated recognition/adhesion but not purified alphaVbeta5-FN/IBSP affinity.', 'Promote the bounded IBSP/BSP-RGD->ITGAV:ITGB5 (alphaVbeta5) receptor-mediated adhesion/recognition association, explicitly not as a purified direct molecular affinity edge. Keep alphaVbeta3 contributions and cell-line differences distinct.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC11413474_IBSP_ITGAVB5_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000753' AND x.extraction_id='M23B-P2-R-000710');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000754', 'M23B-P2-R-000711', 'PMCID:PMC11413474', '39310027', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11413474', 'candidate_requires_review', NULL, 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMCID:PMC11413474; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC11413474_IBSP_ITGAVB5_fulltext_bioc.json', 'The primary bone-sialoprotein/IBSP cancer-cell adhesion study measures RGD peptide and alphaVbeta3/alphaVbeta5 antibody effects but explicitly states that it did not investigate downstream signaling pathways in the adhesion experiments. Literature references to FAK/ERK are not direct results of this study.', 'Do not promote an IBSP-alphaVbeta5 receptor-proximal relay from this paper. Leave FAK, ERK, PI3K/AKT, AP-1, adaptors, and terminal TFs unknown for this exact study.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC11413474_IBSP_ITGAVB5_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000754' AND x.extraction_id='M23B-P2-R-000711');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000554', 'M23B-EVID-000755', 'M23B-P2-R-000712', 'PMCID:PMC11413474', '39310027', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC11413474', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC11413474; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC11413474_IBSP_ITGAVB5_fulltext_bioc.json', 'Human MDA-MB-231, PC-3, and NCI-H460 cancer cells adhere to bone sialoprotein/IBSP in a dose-dependent, RGD-sensitive manner. AlphaVbeta5-blocking antibody markedly reduces adhesion in cell-line-specific patterns, with alphaVbeta3 contributing in other lines; the study therefore supports an alphaVbeta5-containing cancer-cell adhesion output rather than a universal receptor assignment.', 'Promote the bounded IBSP-RGD-alphaVbeta5-containing cancer-cell adhesion functional branch, preserving cell-line-specific alphaVbeta3 contributions and avoiding a direct molecular or downstream signaling inference.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC11413474_IBSP_ITGAVB5_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000755' AND x.extraction_id='M23B-P2-R-000712');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E002084', 'M22B-EVID-003787', '', '', NULL, 'full_text_or_bioc_json', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC209362_P2RY12_GNAI2_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003787' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000750', 'M23B-P2-R-000707', 'PMCID:PMC209362; PMID:25944935; PMID:8554519', NULL, 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC209362', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMCID:PMC209362; PMID:25944935; PMID:8554519; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMIDs25944935_8554519_P2RY12_pubmed.xml', 'The retrieved primary records support ADP-receptor/Gi2 coupling and G alpha(i2)-dependent platelet function, but do not establish a separate direct binding or receptor-activation record for the queued GNAI2/P2RY12 coupling-feature-to-P2RY12 edge. The 1993 assay uses historical P2T/ADP-receptor nomenclature rather than a receptor-selective P2RY12 construct.', 'Do not create a direct GNAI2/P2RY12 molecular binding edge from these records. Keep the measured ADP-receptor-to-Gi2 coupling under EVID-000751 and leave the queued feature-edge boundary explicit.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC209362_P2RY12_GNAI2_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000750' AND x.extraction_id='M23B-P2-R-000707');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000551', 'M23B-EVID-000751', 'M23B-P2-R-000708', 'PMCID:PMC209362; PMID:8554519; PMID:25944935', NULL, 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC209362', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:8554519; PMID:25944935; PMCID:PMC4443332; DOI:10.1073/pnas.1505887112; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMIDs25944935_8554519_P2RY12_pubmed.xml', 'ADP stimulation of human platelet membranes increases GTP analogue labeling of Gi alpha subunits and specifically labels G alpha i2 but not G alpha i3; the response is blocked by the P2T/ADP-receptor antagonist ATP. The primary mouse Gnai2-loss study independently establishes the importance of platelet G alpha i2 for ADP-dependent thrombotic responses.', 'Promote the bounded human platelet ADP-receptor/P2RY12-compatible->G alpha i2 receptor-proximal coupling branch. Historical P2T nomenclature and lack of a receptor-selective P2RY12 construct limit the exact receptor attribution; do not infer direct receptor-Gi2 physical affinity.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC209362_P2RY12_GNAI2_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000751' AND x.extraction_id='M23B-P2-R-000708');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000552', 'M23B-EVID-000752', 'M23B-P2-R-000709', 'PMCID:PMC209362; PMID:25944935; PMID:8554519', NULL, 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC209362', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:25944935; PMID:8554519; PMCID:PMC4443332; DOI:10.1073/pnas.1505887112; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMIDs25944935_8554519_P2RY12_pubmed.xml', 'Platelet or global Gnai2 loss prolongs bleeding time and reduces arterial thrombus formation/stability in mice. Platelet-specific Gnai2 deletion also reduces ADP-dependent platelet-neutrophil complexes, ischemia/reperfusion infarct size, and neurological or myocardial injury. The human ADP-receptor/Gi2 coupling study supplies the proximal receptor context.', 'Promote the bounded ADP-receptor/Gi2->platelet activation/thrombus stability and thrombo-inflammatory injury functional branch. Keep platelet context, species, and receptor-attribution limits explicit.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMC209362_P2RY12_GNAI2_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000752' AND x.extraction_id='M23B-P2-R-000709');
