INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000264', 'M23B-EVID-000387', 'M23B-P2-R-000321', 'PMCID:PMC3001003; PMID:19398782; PMID:20929862; PMID:22442151', '20929862', 'literature_xml', 'exact_identifier_match:PMID:20929862', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC3001003; PMID:19398782; PMID:20929862; PMID:22442151; https://pmc.ncbi.nlm.nih.gov/articles/PMC3001003/; https://pubmed.ncbi.nlm.nih.gov/19398782/; https://pubmed.ncbi.nlm.nih.gov/20929862/; https://pubmed.ncbi.nlm.nih.gov/22442151/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B064_pmc3001003_tg2_sdc4_full.xml', 'TG2-FN matrix adhesion required syndecan-4 and beta1-integrin co-signaling, with PKC-alpha proposed as a link to syndecan-2/ROCK and actin organization. The matrix response was RGD-independent and did not require TG2 transamidase activity. The retrieved boundary does not resolve a single SDC4-to-PKC/FAK/integrin ordering across all models.', 'Retain TG2-FN-syndecan-4/beta1-integrin-PKC-alpha/ROCK receptor-proximal matrix signaling as abstract-only. Keep syndecan-2 downstream and do not infer direct TG2-PKC, TG2-ROCK, or TG2-beta1 molecular edges.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMID20929862_FN1_SDC2_TG2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000387' AND x.extraction_id='M23B-P2-R-000321');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000264', 'M23B-EVID-000388', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMID20929862_FN1_SDC2_TG2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000388' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000747', 'M23B-P2-R-000704', 'PMID:20929862; PMCID:PMC3001003; DOI:10.1074/jbc.M110.123703', '20929862', 'literature_xml', 'exact_identifier_match:PMID:20929862', 'candidate_requires_review', 'B', 'L1', 'not_required_exact_primary_result_not_found', 'unresolved_after_primary_search', 'PMID:20929862; PMCID:PMC3001003; DOI:10.1074/jbc.M110.123703; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B144_PMID20929862_FN1_SDC2_TG2_pubmed.xml', 'The primary TG2-FN matrix study does not establish direct FN1-SDC2 binding. It identifies a tissue-transglutaminase/FN heterocomplex, requires syndecan-2 for the compensatory matrix phenotype, and explicitly places syndecan-2 downstream; no standalone FN1-SDC2 binary binding assay is reported.', 'Do not promote a direct FN1->SDC2 molecular binding edge from this study. Preserve the TG2-FN matrix/co-signaling relay separately and leave the exact FN1-SDC2 interface unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMID20929862_FN1_SDC2_TG2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000747' AND x.extraction_id='M23B-P2-R-000704');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000549', 'M23B-EVID-000748', 'M23B-P2-R-000705', 'PMID:20929862; PMCID:PMC3001003; DOI:10.1074/jbc.M110.123703', '20929862', 'literature_xml', 'exact_identifier_match:PMID:20929862', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:20929862; PMCID:PMC3001003; DOI:10.1074/jbc.M110.123703; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B144_PMID20929862_FN1_SDC2_TG2_pubmed.xml', 'The primary TG2-FN matrix study reports an RGD-independent compensatory adhesion/deposition pathway requiring syndecan-4 and beta1-integrin co-signaling. Syndecan-2 knockdown abolishes the compensation and disrupts actin and FN deposition; syndecan-2 acts downstream through ROCK, and PKCalpha is identified as a likely link between syndecan-4 and syndecan-2 signaling.', 'Promote the bounded TG2-FN matrix->syndecan-4/beta1-integrin co-signaling->PKCalpha->syndecan-2->ROCK/actin/FN-deposition relay. Do not rewrite this as direct FN1-SDC2 binding or as a free-FN1 receptor pathway.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMID20929862_FN1_SDC2_TG2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000748' AND x.extraction_id='M23B-P2-R-000705');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000550', 'M23B-EVID-000749', 'M23B-P2-R-000706', 'PMID:20929862; PMCID:PMC3001003; DOI:10.1074/jbc.M110.123703', '20929862', 'literature_xml', 'exact_identifier_match:PMID:20929862', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_importable', 'validated_abstract_importable', 'PMID:20929862; PMCID:PMC3001003; DOI:10.1074/jbc.M110.123703; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMID20929862_FN1_SDC2_TG2_pubmed.xml', 'The primary TG2-FN matrix study shows that a tissue-transglutaminase/FN heterocomplex restores RGD-independent cell adhesion and soluble/cellular FN deposition when adhesion is interrupted. Syndecan-2 knockdown abolishes the compensation and disrupts actin-skeleton formation and FN deposition; alpha5 and beta1 integrin perturbations establish co-signaling dependence.', 'Promote the bounded TG2-FN matrix->syndecan-4/beta1-integrin/syndecan-2 co-signaling->actin organization and FN deposition functional branch. Do not represent it as direct free-FN1-SDC2 binding.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B145_PMID20929862_FN1_SDC2_TG2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000749' AND x.extraction_id='M23B-P2-R-000706');
