INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000187', 'M23B-EVID-000269', 'P2FALLBACK-23B-M23B-EVID-000269', 'PMCID:PMC2116396', '1980124', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2116396', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC2116396', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMC2116396_ICAM1_MAC1_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000269' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000269');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000558', 'M23B-EVID-000759', 'M23B-P2-R-000716', 'PMCID:PMC2116396; PMID:1980124; PMID:17164347; PMID:21454473', '1980124', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2116396', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2116396; PMID:1980124; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMC2116396_ICAM1_MAC1_fulltext_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMID1980124_ICAM1_MAC1_pubmed.xml; PMID:17164347; PMID:21454473', 'The corrected PMCID PMC2116396/PMID1980124 primary study directly demonstrates that purified Mac-1 and purified ICAM-1 interact: ICAM-1-expressing cells bind immunoaffinity-purified Mac-1 in a specific, dose-dependent manner, and reciprocal Mac-1-expressing cells bind purified ICAM-1; anti-ICAM-1 and anti-Mac-1 antibodies block the interaction. Later primary studies show activated Mac-1 ligand recognition and ICAM adhesion defects from CD11b mutation.', 'Promote the direct ICAM1->ITGAM:ITGB2 (Mac-1/alphaMbeta2) binding edge, preserving the complete heterodimer and activation-state context. Do not infer a subunit-only edge or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMC2116396_ICAM1_MAC1_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000759' AND x.extraction_id='M23B-P2-R-000716');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000559', 'M23B-EVID-000760', 'M23B-P2-R-000717', 'PMCID:PMC2116396; PMID:1980124; PMID:17164347; PMID:21454473', '1980124', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2116396', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMID:17164347; DOI:10.1182/blood-2006-03-007179; PMID:21454473; PMCID:PMC3089572; DOI:10.1074/jbc.M110.182998; PMCID:PMC2116396; PMID:1980124; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMIDs17164347_21454473_17389580_ICAM_integrins_pubmed.xml', 'Primary studies show that Mac-1 activation exposes ligand-binding sites and that activation-specific scFv blockade reduces ICAM-1 binding/adhesion. The CD11b R77H extracellular mutation permits receptor expression and conformational activation but reduces ICAM adhesion, especially under shear, supporting an activation-state/conformational relay rather than a named intracellular kinase pathway.', 'Promote the bounded ICAM1/Mac-1 activation-state and conformational ligand-accessibility branch. Do not represent this as a direct Mac-1-to-adaptor/kinase edge; no such intracellular intermediate was identified in these records.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMC2116396_ICAM1_MAC1_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000760' AND x.extraction_id='M23B-P2-R-000717');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000560', 'M23B-EVID-000761', 'M23B-P2-R-000718', 'PMCID:PMC2116396; PMID:1980124; PMID:17164347; PMID:21454473', '1980124', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2116396', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC2116396; PMID:1980124; PMID:17164347; DOI:10.1182/blood-2006-03-007179; PMID:21454473; PMCID:PMC3089572; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMC2116396_ICAM1_MAC1_fulltext_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMIDs17164347_21454473_17389580_ICAM_integrins_pubmed.xml', 'ICAM-1/Mac-1 supports leukocyte-endothelial adhesion in primary and transfected systems, including antibody-sensitive neutrophil/HUVEC conjugates and static/flow adhesion. Activation-specific Mac-1 scFv blocks activated monocyte adhesion, and CD11b R77H compromises ICAM-1 adhesion under shear; iC3b phagocytosis and IL-6 effects from the R77H study are retained as separate Mac-1 context rather than ICAM1-specific outputs.', 'Promote the bounded ICAM1->Mac-1->leukocyte-endothelial adhesion and flow-arrest functional branch. Keep Mac-1-specific iC3b phagocytosis and IL-6 observations separate from the ICAM1 output.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B147_PMC2116396_ICAM1_MAC1_fulltext_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000761' AND x.extraction_id='M23B-P2-R-000718');
