INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004190', 'M20B-EVID-004190-P2-DIRECT', 'M20B-P2-R-004190-R161A', 'PMID:19252495; PMID:20139422; DOI:10.1074/jbc.M109.061127', '20139422', 'literature_xml', 'exact_identifier_match:PMID:20139422', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_receptor_support', 'PMID:19252495; PMID:20139422; PMCID:PMC2859559; DOI:10.1074/jbc.M109.061127; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_LRRC4B_PTPRF_primary_records.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B173_PMC2859559_NGL3_LAR_fulltext.html', 'NGL-3/LRRC4B binds the extracellular LAR/PTPRF FNIII1–2 region, with direct domain-dependent adhesion and co-culture evidence; the NGL-3 LRR domain and LAR FNIII1–2 are sufficient for the interaction.', 'Promote direct LRRC4B/NGL-3 association with PTPRF/LAR as a trans-synaptic cell-adhesion/receptor-complex interaction, not as a soluble agonist affinity edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B172_PMID20139422_NGL3_LAR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004190-P2-DIRECT' AND x.extraction_id='M20B-P2-R-004190-R161A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004190', 'M20B-EVID-004190-P2-FUNC', 'M20B-P2-R-004190-R161C', 'PMID:19252495; PMID:20139422; DOI:10.1074/jbc.M109.061127', '20139422', 'literature_xml', 'exact_identifier_match:PMID:20139422', 'supporting_validated_claim', 'B', 'L2', 'validated_primary_observation', 'validated_conditional_functional_support', 'PMID:19252495; PMID:20139422; PMCID:PMC2859559; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B173_PMC2859559_NGL3_LAR_fulltext.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B172_PMID19252495_NGL3_LAR_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B172_PMID20139422_NGL3_LAR_pubmed.xml', 'NGL-3/LAR expression induced pre- and postsynaptic differentiation in contacting hippocampal neurons; NGL-3 overexpression increased presynaptic contacts, while NGL-3 knockdown reduced excitatory synapse number and function, and soluble LAR competitively reduced NGL-3-induced presynaptic differentiation.', 'Promote LRRC4B/LAR-dependent trans-synaptic excitatory-synapse organization as a cellular functional output while leaving terminal TF and SCI receiver-cell function unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B172_PMID20139422_NGL3_LAR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004190-P2-FUNC' AND x.extraction_id='M20B-P2-R-004190-R161C');
