INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004212', 'M20B-EVID-004212-P2-DIRECT', 'M20B-P2-R-004212-R175A', 'PMID:10196235', '10196235', 'literature_xml', 'exact_identifier_match:PMID:10196235', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_receptor_support', 'PMID:10196235; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_MATN1_MATRILIN-1_INTEGRIN_ALPHA1.json; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_MATN1_integrin_primary_records.xml', 'Matrilin-1/CMP-coated dishes promoted adhesion and spreading of rabbit and human chondrocytes and fibroblasts; anti-integrin-alpha1 or anti-integrin-beta1 antibodies abolished the response, and alpha1 antibody co-precipitated radiolabeled CMP with competition by unlabeled CMP.', 'Promote direct MATN1 association with the alpha1beta1 integrin receptor complex, with strongest biochemical attribution to the alpha1 subunit and functional dependence on beta1; do not treat this as isolated beta1 binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B173_PMID10196235_matrilin1_integrin_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004212-P2-DIRECT' AND x.extraction_id='M20B-P2-R-004212-R175A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004212', 'M20B-EVID-004212-P2-FUNC', 'M20B-P2-R-004212-R175C', 'PMID:10196235; PMID:17156989', '10196235', 'literature_xml', 'exact_identifier_match:PMID:10196235', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_conditional_functional_support', 'PMID:10196235; PMID:17156989; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_integrin_primary_records.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_MATN1_integrin_primary_records.xml', 'Matrilin-1 supported cell adhesion and spreading in chondrocytes and fibroblasts; broader matrilin-1 attachment studies found integrins contribute to cell attachment without focal-adhesion formation or major actin reorganization.', 'Promote MATN1/alpha1beta1-associated adhesion and spreading as conditional cellular outputs, without importing a specific intracellular kinase or transcriptional endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B173_PMID10196235_matrilin1_integrin_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004212-P2-FUNC' AND x.extraction_id='M20B-P2-R-004212-R175C');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004213', 'M20B-EVID-004213-P2-DIRECT', 'M20B-P2-R-004213-R175A', 'PMID:10196235', '10196235', 'literature_xml', 'exact_identifier_match:PMID:10196235', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_receptor_support', 'PMID:10196235; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_MATN1_MATRILIN-1_INTEGRIN_BETA1.json; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_MATN1_integrin_primary_records.xml', 'Matrilin-1/CMP-mediated cell adhesion and spreading required beta1-integrin function in antibody-blockade assays, while alpha1 antibody co-precipitated radiolabeled CMP and unlabeled CMP competed for the alpha1-associated interaction, supporting an alpha1beta1 receptor-complex edge.', 'Promote MATN1 engagement of a beta1-containing alpha1beta1 integrin receptor complex, but retain that the biochemical co-precipitation was assigned to alpha1 and isolated beta1 binding was not demonstrated.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B173_PMID10196235_matrilin1_integrin_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004213-P2-DIRECT' AND x.extraction_id='M20B-P2-R-004213-R175A');
