INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000879', 'M23B-EVID-001184', 'M23B-P2-R-001112', 'PMCID:PMC6484411; PMID:30869196; DOI:10.1111/jcmm.14236', '30869196', 'full_text_html', 'exact_identifier_match:DOI:10.1111/jcmm.14236;PMCID:PMC6484411', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_receptor_proximal_complex_relay', 'PMCID:PMC6484411; PMID:30869196; DOI:10.1111/jcmm.14236; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B227_PMC6484411_MINDIN_MAC1_SYK_NFKB_fulltext.html', 'Mindin stimulation of Mac-1-expressing macrophage systems increased Syk phosphorylation and activated MEK1/2-ERK1/2 MAPK signaling; Mac-1 blockade or Syk inhibition reduced the response. The study also reported increased NF-kB activation and nuclear translocation of p65. This is a receptor-proximal signaling relay, while p65 nuclear occupancy/transcriptional consequences should be handled separately from the 23B relay edge.', 'Promote the bounded mindin-Mac-1 -> Syk -> MEK/ERK and NF-kB p65 nuclear-translocation relay in macrophage models. Keep Syk/MAPK as receptor-proximal pathway evidence and do not infer a direct Mac-1-to-p65 molecular interaction; any TF activation/target-gene record requires separate Module 22A evidence handling.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B227_PMC6484411_MINDIN_MAC1_SYK_NFKB_fulltext.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001184' AND x.extraction_id='M23B-P2-R-001112');
