INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000251', 'M23B-EVID-000352', 'P2FALLBACK-23B-M23B-EVID-000352', 'PMID:10571240', '10571240', 'literature_xml', 'exact_identifier_match:PMID:10571240', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:10571240', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B235_PMID10571240_REELN_FUNCTION_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000352' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000352');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000251', 'M23B-EVID-000353', 'M23B-P2-R-000287', 'PMID:10571240; PMID:14578885; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; PMCID:PMC321426', '14729980', 'literature_xml', 'exact_identifier_match:PMID:10571240', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'In primary embryonic mouse neurons, bivalent ApoER2- or VLDLR-binding antibodies induced Dab1 tyrosine phosphorylation; in the same study, Reelin or Fc-RAP receptor clustering increased Dab1 phosphorylation, activated Src-family kinases, and modulated PKB/Akt phosphorylation. Dimerization of Dab1 in HEK293 cells was sufficient for phosphorylation and was inhibited by the Src-family inhibitor PP2.', 'Promote the bounded Reelin-lipoprotein-receptor clustering relay: ApoER2/VLDLR clustering is sufficient for Dab1 phosphorylation, Src-family activation, and Akt modulation in the tested neuronal and HEK293 systems. Dimerization of Dab1 is a receptor-independent control for substrate activation, not evidence for direct Reelin-Dab1, Reelin-Src, or Reelin-Akt binding. No terminal TF is identified.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B235_PMID10571240_REELN_FUNCTION_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000353' AND x.extraction_id='M23B-P2-R-000287');
