INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000252', 'M23B-EVID-000356', 'M23B-P2-R-000290', 'PMID:10571240; PMID:14578885; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; PMCID:PMC321426', '14729980', 'literature_xml', 'exact_identifier_match:PMID:14729980', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:10571240; PMID:14578885; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; PMCID:PMC321426; https://pubmed.ncbi.nlm.nih.gov/10571240/; https://pubmed.ncbi.nlm.nih.gov/14578885/; https://pubmed.ncbi.nlm.nih.gov/14729980/; https://pmc.ncbi.nlm.nih.gov/articles/PMC321426/; local sources=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B056_pyypyy_reln_pmids.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B056_pmc321426_reln_full.xml', 'VLDLR-dependent Reelin signaling included Dab1 tyrosine phosphorylation, activation of Src-family kinases, and modulation of Akt phosphorylation. Receptor clustering by bivalent agents was sufficient to reproduce the Reelin-induced Dab1/Src/Akt branch in neuronal and HEK293 systems, separating receptor-proximal clustering from direct ligand binding.', 'Retain the Reelin-VLDLR-to-Dab1-Src/Akt receptor-proximal pathway as abstract-only. Do not create direct Reelin-Dab1, Reelin-Src, or Reelin-Akt molecular edges, and do not assume that clustering-independent signaling is equivalent.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B235_PMID14729980_REELN_DAB1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000356' AND x.extraction_id='M23B-P2-R-000290');
