INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000251', 'M23B-EVID-001459', 'M23B-P2-R-RETRY-RELIN-APOER2-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'literature_xml', 'exact_identifier_match:PMID:14729980', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'In primary embryonic mouse neurons, bivalent ApoER2- or VLDLR-binding antibodies induced Dab1 tyrosine phosphorylation; Reelin or Fc-RAP receptor clustering activated Src-family kinases and modulated PKB/Akt phosphorylation. Chemical dimerization of Dab1 in HEK293 cells was sufficient for phosphorylation and was inhibited by the Src-family inhibitor PP2.', 'Promote the bounded ApoER2/LRP8 receptor-clustering relay to Dab1 phosphorylation, Src-family activation, and Akt modulation in the tested neuronal and HEK293 systems. Dab1 dimerization is a receptor-independent substrate-activation control, not evidence for direct Reelin-Dab1, Reelin-Src, or Reelin-Akt binding. No terminal TF is identified.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B235_PMID14729980_REELN_DAB1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001459' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-APOER2-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000252', 'M23B-EVID-001460', 'M23B-P2-R-RETRY-RELIN-VLDLR-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'literature_xml', 'exact_identifier_match:PMID:14729980', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'In primary embryonic mouse neurons, bivalent VLDLR-binding antibody and Fc-RAP induced Dab1 tyrosine phosphorylation; Reelin and receptor-clustering agents activated Src-family kinases and modulated PKB/Akt phosphorylation. Chemical dimerization of Dab1 in HEK293 cells was sufficient for phosphorylation and was inhibited by PP2, separating the receptor-clustering relay from direct ligand binding.', 'Promote the bounded VLDLR receptor-clustering relay to Dab1 phosphorylation, Src-family activation, and Akt modulation in the tested neuronal and HEK293 systems. Dab1 dimerization is a receptor-independent substrate-activation control, not evidence for direct Reelin-Dab1, Reelin-Src, or Reelin-Akt binding. No terminal TF is identified.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B235_PMID14729980_REELN_DAB1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001460' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-VLDLR-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000251', 'M23B-EVID-001461', 'M23B-P2-R-RETRY-RELIN-APOER2-BINDING-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'literature_xml', 'exact_identifier_match:PMID:14729980', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'Reelin bound recombinant ApoER2 ligand-binding domain in a quantitative ELISA-based assay; the same paper used receptor-fragment specificity controls and a sandwich assay showing that ApoER2-bound Reelin could bind soluble VLDLR, consistent with multivalent receptor engagement.', 'Promote the bounded recombinant Reelin-ApoER2 association and multivalent receptor-engagement observation. The paper reports similar ApoER2 and VLDLR affinities but this record does not assign a numeric Kd; do not infer direct Reelin-Dab1, Reelin-Src, or terminal-TF binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B235_PMID14729980_REELN_DAB1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001461' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-APOER2-BINDING-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000252', 'M23B-EVID-001462', 'M23B-P2-R-RETRY-RELIN-VLDLR-BINDING-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'literature_xml', 'exact_identifier_match:PMID:14729980', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'Reelin bound recombinant VLDLR ligand-binding domain in a quantitative ELISA-based assay; soluble VLDLR fragments also bound Reelin captured on ApoER2, consistent with multivalent receptor engagement.', 'Promote the bounded recombinant Reelin-VLDLR association and multivalent receptor-engagement observation. The paper reports similar ApoER2 and VLDLR affinities but this record does not assign a numeric Kd; do not infer direct Reelin-Dab1, Reelin-Src, or terminal-TF binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B235_PMID14729980_REELN_DAB1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001462' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-VLDLR-BINDING-000001');
