INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000299', 'M22B-EVID-000198', 'M22B-P2-B090-003', 'PMID:21335558; PMCID:PMC3075638; DOI:10.1074/jbc.M110.143693', '21335558', 'literature_xml', 'exact_identifier_match:PMID:21335558', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_fulltext', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3075638/; https://pubmed.ncbi.nlm.nih.gov/21335558/', 'In primary normal human lung fibroblasts, collagen I induced DDR1 and MMP-10 expression through DDR2-associated JAK2 and ERK1/2 signaling. ChIP analysis in DDR2-overexpressing HEK293 cells showed recruitment of PEA3 to the DDR1 promoter; MEK/ERK inhibition reduced the promoter-associated PEA3 signal and blocked DDR1 induction. This identifies a direct PEA3-promoter observation downstream of a receptor-associated pathway.', 'The authors conclude that collagen I induces DDR1 expression through DDR2-associated JAK2-ERK1/2 signaling and recruitment of PEA3 to the DDR1 promoter. Retain the PEA3-to-DDR1 promoter edge and separate it from receptor-proximal DDR2/JAK2/ERK and cellular expression outputs; do not generalize it to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B242_PMID21335558_COLLAGEN3_DDR2_alias_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000198' AND x.extraction_id='M22B-P2-B090-003');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000297', 'M22B-EVID-000199', 'P2FALLBACK-22B-M22B-EVID-000199', 'PMID:21335558', '21335558', 'literature_xml', 'exact_identifier_match:PMID:21335558', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMID:21335558', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B242_PMID21335558_COLLAGEN3_DDR2_alias_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000199' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-000199');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000298', 'M22B-EVID-000200', 'M22B-P2-R-000190', 'PMID:21335558; PMCID:PMC3075638; DOI:10.1074/jbc.M110.143693', '21335558', 'literature_xml', 'exact_identifier_match:PMID:21335558', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMID:21335558; PMCID:PMC3075638; DOI:10.1074/jbc.M110.143693; https://pmc.ncbi.nlm.nih.gov/articles/PMC3075638/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch076_PMC3075638_full.xml', 'Reuse the validated collagen I-DDR2 observation for the distinct functional-output handoff: collagen I induced DDR1 and MMP-10 expression and MMP-10 secretion, along with MCP-1, BMP-2, and MMP-2 in primary human lung fibroblasts; the paper frames these as matrix-remodeling and profibrotic outputs.', 'Reuse collagen I-DDR2-associated DDR1, MMP-10, and matrix-remodeling/profibrotic expression outputs as a separate functional layer. Do not infer direct PEA3 binding to MMP-10 or transfer the lung-fibroblast output to SCI without matched evidence.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B242_PMID21335558_COLLAGEN3_DDR2_alias_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000200' AND x.extraction_id='M22B-P2-R-000190');
