INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E001031', 'M23B-EVID-001387', 'M23B-P2-R-001266', 'PMID:29330021; DOI:10.1016/j.matbio.2018.01.004; PMCID:PMC6015535', '29330021', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6015535', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_receptor_proximal_relay', 'PMID:29330021; DOI:10.1016/j.matbio.2018.01.004; PMCID:PMC6015535; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B259_PMC6015535_WISP1_ITGA5B1_fulltext.xml', 'Recombinant CCN4 increased dermal-fibroblast migration and rapidly increased ERK and JNK phosphorylation. Alpha5beta1-blocking antibody neutralized CCN4-induced migration and blocked CCN4-stimulated ERK phosphorylation, while MEK/ERK inhibition reduced migration. The data place alpha5beta1 upstream of an ERK/JNK-associated receptor-proximal relay in this model, with strongest causal perturbation for ERK.', 'Promote a CCN4/WISP1 -> integrin alpha5beta1 -> ERK-associated relay with JNK phosphorylation as a parallel observed response in human dermal fibroblasts. Do not assign a terminal TF or claim that the experiment establishes a complete alpha5beta1-to-JNK molecular chain.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B259_PMC6015535_WISP1_ITGA5B1_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001387' AND x.extraction_id='M23B-P2-R-001266');
