INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E001071', 'M23B-EVID-001444', 'M23B-P2-R-001306', 'PMID:14697347; DOI:10.1016/j.yexcr.2003.09.011', '14697347', 'literature_xml', 'exact_identifier_match:PMID:14697347', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:14697347; DOI:10.1016/j.yexcr.2003.09.011; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B267_PMID14697347_pubmed.xml', 'The primary study identified an MFG-E8-alphaVbeta5-DOCK180 module for Rac1 activation; antisense DOCK180 abrogated MFG-E8-alphaVbeta5-mediated Rac activation. The measured relay is Crk-DOCK180-Rac1-associated, without a terminal transcription factor.', 'Promote the MFG-E8 -> alphaVbeta5 -> Crk/DOCK180 -> Rac1 receptor-proximal relay in phagocytic dendritic-cell systems. Keep Crk/DOCK180 and Rac1 as measured pathway components and do not infer a TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B267_PMID14697347_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001444' AND x.extraction_id='M23B-P2-R-001306');
