INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000654', 'M23B-EVID-000877', 'P2FALLBACK-23B-M23B-EVID-000877', 'PMCID:PMC4578660', '26321637', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4578660', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC4578660', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B268_PMC4578660_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000877' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000877');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000655', 'M23B-EVID-000878', 'P2FALLBACK-23B-M23B-EVID-000878', 'PMCID:PMC4578660', '26321637', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4578660', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B172_PMC4578660_LRFN4_PTPRD_fulltext.html; PMCID:PMC4578660; PMID:26321637; DOI:10.1016/j.celrep.2015.08.002', 'SALM3/LRFN4-expressing cells coaggregated with LAR-RPTP-expressing cells; PTPdelta Ig1-3-Fc containing the mini-exon-B insert bound SALM3-expressing cells, whereas the B-minus form did not. In hippocampal-neuron co-culture, knockdown of all three LAR-RPTPs reduced SALM3-induced synapsin-I clustering by 85.2 +/- 3.0 percent, with PTPdelta showing the largest individual contribution. These measurements support SALM3 organization of PTPRD/LAR-RPTP-dependent presynaptic differentiation.', 'The authors conclude that postsynaptic SALM3/LRFN4 interacts trans-synaptically with the three presynaptic LAR-RPTPs, with splice-insert-dependent binding, and that the complex is required for efficient presynaptic differentiation and contributes to excitatory synapse development. The registered PTPRD/LAR-RPTP organization claim is supported without inferring a defined PTPRD substrate, kinase relay, SCI transfer, or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B268_PMC4578660_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000878' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000878');
