INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000555', 'M23B-EVID-000756', 'M23B-P2-R-000713', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:9539703; DOI:10.1073/pnas.95.8.4140; PMID:3315233; DOI:10.1016/0092-8674(87)90104-8', '3315233', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMID:3315233; DOI:10.1016/0092-8674(87)90104-8; PMID:9539703; DOI:10.1073/pnas.95.8.4140; PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMID3315233_ICAM1_LFA1_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMC276084_ICAM1_LFA1_fulltext.xml', 'Primary purified ICAM-1 incorporated into artificial membranes binds LFA-1-positive but not LFA-1-negative cells, with inhibition by anti-ICAM-1 or anti-LFA-1 antibodies. Structural work maps the ICAM-1/LFA-1 interface and its divalent-cation-dependent I-domain geometry; the corrected PMC276084 record adds cell-surface LFA-1 activation/context but is not conflated with the structural paper.', 'Promote the direct ICAM1->ITGAL:ITGB2 (LFA-1) ligand-receptor binding/activation edge, with purified-membrane binding and antibody inhibition. Preserve receptor-complex nomenclature and do not infer a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC276084_fulltext_9539703.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000756' AND x.extraction_id='M23B-P2-R-000713');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000556', 'M23B-EVID-000757', 'M23B-P2-R-000714', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:10198043; PMCID:PMC25207; DOI:10.1091/mbc.10.4.861', '9190212', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:10198043; PMCID:PMC25207; DOI:10.1091/mbc.10.4.861; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMC276084_ICAM1_LFA1_fulltext.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMID9190212_ICAM1_LFA1_pubmed.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMIDs10198043_9539703_ICAM1_LFA1_pubmed.xml', 'Primary LFA-1 studies show that intracellular/cytoskeletal activation controls ICAM-1 binding. Release of LFA-1 from cytoskeletal constraints induces clustering and a high-affinity state, while outside-in ICAM-1 engagement stimulates actin polymerization; chemokine studies show transient LFA-1 avidity activation and alphaL cytoplasmic-tail-dependent regulation.', 'Promote the bounded ICAM1/LFA-1->inside-out integrin affinity/clustering and outside-in actin-polymerization receptor-proximal branch. Keep talin/kindlin/adaptor identity unresolved unless directly measured in a separate record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC276084_fulltext_9539703.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000757' AND x.extraction_id='M23B-P2-R-000714');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000557', 'M23B-EVID-000758', 'M23B-P2-R-000715', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:10198043; PMCID:PMC25207; DOI:10.1091/mbc.10.4.861; PMID:9539703', '10198043', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC276084; PMID:9190212; DOI:10.1091/mbc.8.2.341; PMID:10198043; PMCID:PMC25207; DOI:10.1091/mbc.10.4.861; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMC276084_ICAM1_LFA1_fulltext.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B146_PMIDs10198043_9539703_ICAM1_LFA1_pubmed.xml', 'LFA-1/ICAM-1 engagement supports leukocyte adhesion, with activation-state and cytoskeletal context determining binding strength. Chemokine-triggered LFA-1 activation contributes to monocyte transendothelial chemotaxis, while LFA-1 and Mac-1 have distinct kinetics and contributions.', 'Promote the bounded ICAM1->LFA-1->leukocyte adhesion and chemokine-dependent transendothelial chemotaxis functional branch. Keep LFA-1 distinct from Mac-1 and do not infer a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC276084_fulltext_9539703.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000758' AND x.extraction_id='M23B-P2-R-000715');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000184', 'M23B-EVID-001457', 'M23B-P2-R-C23B271-000010', 'PMCID:PMC276084; PMID:9539703; DOI:10.1091/mbc.8.2.341', '9539703', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC276084; PMID:9539703; DOI:10.1091/mbc.8.2.341; https://europepmc.org/articles/PMC276084; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC276084_fulltext_9539703.pdf', 'Activated human lymphocytes and LFA-1 transfectants adhered to ICAM-1-Fc through the complete LFA-1 alphaLbeta2 complex; resting lymphocytes showed weak adhesion unless receptor clustering and/or high-affinity activation was induced.', 'Promote the bounded cellular ICAM1-LFA-1 association at complete alphaLbeta2-complex resolution. Do not treat the result as purified binary affinity, create a free ITGB2 edge, or transfer the tested leukocyte/transfectant context to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC276084_fulltext_9539703.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001457' AND x.extraction_id='M23B-P2-R-C23B271-000010');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000184', 'M23B-EVID-001458', 'M23B-P2-R-C23B271-000011', 'PMCID:PMC276084; PMID:9539703; DOI:10.1091/mbc.8.2.341', '9539703', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC276084', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC276084; PMID:9539703; DOI:10.1091/mbc.8.2.341; https://europepmc.org/articles/PMC276084; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC276084_fulltext_9539703.pdf', 'LFA-1 activation and cytoskeletal uncoupling promoted receptor clustering/high-affinity-state formation, while outside-in engagement stabilized adhesion and stimulated actin polymerization; induced adhesion required intact intermediate filaments, microtubules, and metabolic energy in the tested systems.', 'Retain the LFA-1 inside-out activation and outside-in actin-stabilization pathway as receptor-proximal evidence. Do not infer a unique kinase, phosphatase, second messenger, terminal TF, SCI pathway, or generic integrin relay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC276084_fulltext_9539703.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001458' AND x.extraction_id='M23B-P2-R-C23B271-000011');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000251', 'M23B-EVID-001459', 'M23B-P2-R-RETRY-RELIN-APOER2-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC321426', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'In primary embryonic mouse neurons, bivalent ApoER2- or VLDLR-binding antibodies induced Dab1 tyrosine phosphorylation; Reelin or Fc-RAP receptor clustering activated Src-family kinases and modulated PKB/Akt phosphorylation. Chemical dimerization of Dab1 in HEK293 cells was sufficient for phosphorylation and was inhibited by the Src-family inhibitor PP2.', 'Promote the bounded ApoER2/LRP8 receptor-clustering relay to Dab1 phosphorylation, Src-family activation, and Akt modulation in the tested neuronal and HEK293 systems. Dab1 dimerization is a receptor-independent substrate-activation control, not evidence for direct Reelin-Dab1, Reelin-Src, or Reelin-Akt binding. No terminal TF is identified.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001459' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-APOER2-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000252', 'M23B-EVID-001460', 'M23B-P2-R-RETRY-RELIN-VLDLR-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC321426', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'In primary embryonic mouse neurons, bivalent VLDLR-binding antibody and Fc-RAP induced Dab1 tyrosine phosphorylation; Reelin and receptor-clustering agents activated Src-family kinases and modulated PKB/Akt phosphorylation. Chemical dimerization of Dab1 in HEK293 cells was sufficient for phosphorylation and was inhibited by PP2, separating the receptor-clustering relay from direct ligand binding.', 'Promote the bounded VLDLR receptor-clustering relay to Dab1 phosphorylation, Src-family activation, and Akt modulation in the tested neuronal and HEK293 systems. Dab1 dimerization is a receptor-independent substrate-activation control, not evidence for direct Reelin-Dab1, Reelin-Src, or Reelin-Akt binding. No terminal TF is identified.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001460' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-VLDLR-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000251', 'M23B-EVID-001461', 'M23B-P2-R-RETRY-RELIN-APOER2-BINDING-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC321426', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'Reelin bound recombinant ApoER2 ligand-binding domain in a quantitative ELISA-based assay; the same paper used receptor-fragment specificity controls and a sandwich assay showing that ApoER2-bound Reelin could bind soluble VLDLR, consistent with multivalent receptor engagement.', 'Promote the bounded recombinant Reelin-ApoER2 association and multivalent receptor-engagement observation. The paper reports similar ApoER2 and VLDLR affinities but this record does not assign a numeric Kd; do not infer direct Reelin-Dab1, Reelin-Src, or terminal-TF binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001461' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-APOER2-BINDING-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000252', 'M23B-EVID-001462', 'M23B-P2-R-RETRY-RELIN-VLDLR-BINDING-000001', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004', '14729980', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC321426', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC321426; PMID:14729980; DOI:10.1128/MCB.24.3.1378-1386.2004; https://europepmc.org/articles/PMC321426; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf', 'Reelin bound recombinant VLDLR ligand-binding domain in a quantitative ELISA-based assay; soluble VLDLR fragments also bound Reelin captured on ApoER2, consistent with multivalent receptor engagement.', 'Promote the bounded recombinant Reelin-VLDLR association and multivalent receptor-engagement observation. The paper reports similar ApoER2 and VLDLR affinities but this record does not assign a numeric Kd; do not infer direct Reelin-Dab1, Reelin-Src, or terminal-TF binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B271_PMC321426_reelin_clustering_fulltext_14729980.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001462' AND x.extraction_id='M23B-P2-R-RETRY-RELIN-VLDLR-BINDING-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000036', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B280_PMC11957695_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000036' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000029', 'M23B-EVID-000053', 'M23B-P2-R-000053', 'PMCID:PMC11957695; PMID:40166934; DOI:10.1172/JCI189197', '40166934', 'full_text_xml', 'exact_identifier_match:PMCID:PMC11957695', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC11957695; PMID:40166934; DOI:10.1172/JCI189197; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_JCI189197.html; PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_pubmed_C23B_EVID053_057.xml', 'In mouse and human lung-adenocarcinoma models, glucosylated collagen VI/Col6a3 increased integrin-beta1 activation, FAK phosphorylation, and cell migration. Neutralizing antibodies, small-molecule inhibition, and alpha2/beta1 knockdown attenuated Col6-driven migration, while purified alpha2beta1 heterodimers bound Col6 in a solid-phase assay and bound more strongly to glucosylated than deglucosylated Col6. The staged edge remains a collagen-VI-to-alpha2beta1 receptor-proximal relay with direct binding support, not a TF endpoint.', 'The authors conclude that LH2-dependent glucosylation of collagen VI, particularly Col6a3, increases alpha2beta1 integrin binding and focal-adhesion signaling to promote LUAD migration, invasion, tumor growth, and metastasis.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B280_PMC11957695_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000053' AND x.extraction_id='M23B-P2-R-000053');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000029', 'M23B-EVID-000067', 'M23B-P2-R-000067', 'PMCID:PMC11957695; PMID:40166934; DOI:10.1172/JCI189197', '40166934', 'full_text_xml', 'exact_identifier_match:PMCID:PMC11957695', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC11957695; PMID:40166934; DOI:10.1172/JCI189197; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_JCI189197.html', 'This is a distinct handoff to the same validated primary collagen-VI/alpha2beta1 receptor-proximal experiment staged for EVID-000053: purified alpha2beta1-Col6 solid-phase binding, glucosylation-dependent binding, integrin activation, pFAK, and alpha2/beta1-dependent LUAD migration. Reuse prevents duplicate staging while preserving the separate queue handoff.', 'Reuse the validated author claim that LH2-dependent collagen-VI glucosylation enhances alpha2beta1 binding and focal-adhesion signaling to promote LUAD migration, invasion, growth, and metastasis; preserve this as a duplicate handoff to the EVID-000053 staging object.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B280_PMC11957695_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000067' AND x.extraction_id='M23B-P2-R-000067');
