INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000008', 'M23B-EVID-000009', 'M23B-P2-R-000009', 'PMCID:PMC2199946; PMID:7542249', '7542249', 'full_text_html', 'exact_identifier_match:PMCID:PMC2199946', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451; local HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946.html; local XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946_epmc.xml', 'The primary abstract reports that recombinant soluble CD31/PECAM-1 supported heterophilic leukocyte adhesion mediated by alphaVbeta3 integrin, that the interaction mapped to the second PECAM-1 Ig-like domain and was inhibited by alphaVbeta3-specific antibodies, and that alphaVbeta3 was precipitated from cell lysates by recombinant CD31. Exact full-text assay conditions and figure loci remain unavailable because PMC exposes the article body as PDF-only and the publisher route was access-blocked.', 'The abstract-level primary claim is that alphaVbeta3 is a heterophilic ligand for CD31/PECAM-1 in leukocyte-endothelial adhesion; full-text methods and figure verification are required before import-ready promotion.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B283_PMC2199946_pdf_gate.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000009' AND x.extraction_id='M23B-P2-R-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000008', 'M23B-EVID-000009', 'M23B-P2-R-RECOVERY-PECAM1-ITGAVB3-000001', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451', '7542249', 'full_text_html', 'exact_identifier_match:PMCID:PMC2199946', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451; https://pmc.ncbi.nlm.nih.gov/articles/PMC2199946/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch062_PMC2199946_PECAM1_alphaVbeta3.html', 'Recombinant CD31/PECAM-1 supported heterophilic leukocyte adhesion through its second Ig-like domain; alphaVbeta3-specific antibodies inhibited the adhesion and recombinant CD31 precipitated alphaVbeta3 from cell lysates. This is direct pair-specific adhesion evidence in an endothelial/leukocyte comparator system, with no SCI or neural receiver-cell inference.', 'The authors conclude that alphaVbeta3 integrin is a heterophilic ligand for CD31/PECAM-1 and that the pair contributes to leukocyte-endothelial adhesion. The direct molecular record is retained as an adhesion interaction; no downstream TF or SCI transfer is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B283_PMC2199946_pdf_gate.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000009' AND x.extraction_id='M23B-P2-R-RECOVERY-PECAM1-ITGAVB3-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-001456', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B283_PMC2199946_pdf_gate.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001456' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000903', 'M22B-EVID-005321', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B283_PMC2730485_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005321' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000108', 'M23B-EVID-000176', 'M23B-P2-R-000170', 'PMID:19379779; PMCID:PMC2730485', '19379779', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2730485', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text', 'PMID:19379779; PMCID:PMC2730485; DOI:10.1016/j.neures.2009.04.007; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B031_pmids.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B031_pmc.xml; stable source=https://pmc.ncbi.nlm.nih.gov/articles/PMC2730485/', 'Ang1 induced PC12 neurite outgrowth and survival in a Tie2-negative, beta1-integrin-positive neuronal model. Ang1 increased FAK phosphorylation without changing MAPK or JNK activation; beta1-integrin or FAK inhibition attenuated outgrowth, and PI3K inhibition blocked the response. NGF produced a distinct MAPK/JNK branch, keeping the Ang1-beta1-integrin-FAK-PI3K-Akt output separate.', 'The primary study supports an Ang1-associated neuronal output branch mediated by beta1-integrin, FAK, and PI3K-Akt, leading to neurite outgrowth and survival in PC12 cells. It does not establish a direct Ang1-free-ITGB1 biochemical interaction or a Tie2-mediated neuronal mechanism; the model is distinct from endothelial Ang1/Tie2 signaling.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B283_PMC2730485_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000176' AND x.extraction_id='M23B-P2-R-000170');
