INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005673', 'M22B-EVID-005447', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B283_PMC6298040_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005447' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000143', 'M23B-EVID-000211', 'M23B-P2-R-000205', 'PMID:30550785; PMCID:PMC6298040; DOI:10.1016/j.cell.2018.10.025', '30550785', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6298040', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:30550785; PMCID:PMC6298040; DOI:10.1016/j.cell.2018.10.025; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B039_pmc_full.xml; stable source=https://pmc.ncbi.nlm.nih.gov/articles/PMC6298040/', 'Processed irisin bound purified integrin alphaV/beta5 complexes in protein-protein assays, with the highest binding among tested integrins; HDX-MS and structural modeling identified interacting surfaces. Cell-surface cross-linking/proteomics identified beta1-containing integrin complexes as candidate receptors, and alphaV-integrin antagonists blocked irisin-induced FAK/AKT/CREB/zyxin signaling and osteocyte/fat-cell outputs. In MLO-Y4 osteocyte-like cells, irisin increased survival and sclerostin; in mice, FNDC5/irisin deletion prevented ovariectomy-induced osteocytic osteolysis and bone loss. The direct alphaVbeta5 complex and broader alphaV-family functional evidence are kept separate.', 'Primary research supports direct processed-irisin binding to alphaVbeta5 integrin complexes and a distinct alphaV-family receptor-proximal signaling branch leading to FAK/AKT/CREB/zyxin and osteocyte, adipose and bone outputs. The ligand is shed/processed irisin from FNDC5, not full-length FNDC5; do not assign the edge to ITGB5 alone or infer a universal alphaV complex from the functional inhibitor data.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B283_PMC6298040_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000211' AND x.extraction_id='M23B-P2-R-000205');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000144', 'M23B-EVID-000212', 'M23B-P2-R-000206', 'PMID:30550785; PMCID:PMC6298040; DOI:10.1016/j.cell.2018.10.025', '30550785', 'full_text_xml', 'exact_identifier_match:PMCID:PMC6298040', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:30550785; PMCID:PMC6298040; DOI:10.1016/j.cell.2018.10.025; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B039_pmc_full.xml; stable source=https://pmc.ncbi.nlm.nih.gov/articles/PMC6298040/', 'The primary irisin study supports an alphaV-family integrin receptor complex, with direct purified binding strongest for the alphaVbeta5 heterodimer and functional inhibition by alphaV-integrin antagonists. This record is retained as a complex-resolution hold for the queued edge: no evidence supports assigning irisin binding to the ITGB5 subunit alone or selecting a different alphaV heterodimer without preserving the alpha subunit and beta5 complex context.', 'The correct molecular representation is a processed-irisin-to-alphaV-integrin-complex record, with the strongest direct evidence for alphaVbeta5; preserve the complex and do not create an ITGB5-only edge. Functional alphaV-family inhibition can support receptor-family dependence but cannot substitute for heterodimer-specific direct binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B283_PMC6298040_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000212' AND x.extraction_id='M23B-P2-R-000206');
