INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004870', 'M20B-EVID-004870-P2-FUNC', 'M20B-P2-R-004870-R252B', 'PMID:15218527; PMCID:PMC1299100; DOI:10.1038/sj.embor.7400189', '15218527', 'full_text_html', 'exact_identifier_match:DOI:10.1038/sj.embor.7400189;PMCID:PMC1299100', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_full_text', 'validated_author_claim', 'PMID:15218527; PMCID:PMC1299100; DOI:10.1038/sj.embor.7400189; data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_EVID244_PMC1299100_full.html; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_Sema5A_PMC1299100_fulltext.xml', 'Sema5A/Plexin-B3 signaling produced receptor-associated motility, collapse, adhesion, and migration outputs in the reported cellular models, with Met signaling as a complex-associated branch.', 'The authors conclude that Sema5A elicits multiple functional responses through Plexin-B3 and can trigger intracellular Met signaling when Met is associated with Plexin-B3; this supports a conditional Plexin-B3/Met complex branch, not direct Sema5A–Met binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_EVID244_PMC1299100_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004870-P2-FUNC' AND x.extraction_id='M20B-P2-R-004870-R252B');
