INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000236', 'M23B-EVID-000323', 'P2FALLBACK-23B-M23B-EVID-000323', 'PMID:11598185', '11598185', 'full_text_html', 'exact_identifier_match:PMCID:PMC60149', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:11598185; PMCID:PMC60149', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_EVID322_PMC60149_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000323' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000323');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000250', 'M23B-EVID-000350', 'M23B-P2-R-000284', 'PMID:10970776; PMCID:PMC1221294', '10970776', 'full_text_html', 'exact_identifier_match:PMCID:PMC1221294', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1221294; PMID:10970776; https://europepmc.org/articles/PMC1221294?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC1221294_PYY_Y1R_fulltext_10970776.pdf', 'In IEC-6 rat jejunal epithelial cells stably expressing human Y1R, Scatchard analysis of equilibrium 125I-PYY binding reported a Kd of approximately 0.2 nM and approximately 104,000 receptors per cell (Results, Fig. 1). PYY induced time-dependent ERK/MAPK phosphorylation with an early peak at 3 minutes and sustained elevation to 1 hour (Fig. 3); pertussis toxin and alpha-transducin implicate Gi/Go and beta-gamma subunits (Fig. 2). PKC inhibitors blocked PYY-induced MAPK phosphorylation and PYY induced PKCepsilon membrane translocation (Figs. 4-5). Src-family and EGFR tyrosine-kinase inhibitors blocked the PYY-MAPK branch, and PYY increased EGFR tyrosine phosphorylation (Figs. 6-8). PYY stimulated growth of Y1R-expressing cells in an EGFR-kinase-dependent manner (Fig. 9).', 'The authors conclude that PYY activates Y1R-linked Gi/Go and beta-gamma signaling through Src-family kinase, EGFR transactivation, and PKC to produce MAPK activation and epithelial-cell growth. The paper supports a PYY-Y1R cellular binding/relay context; it does not establish direct PYY binding to EGFR or direct PYY-Src/PKC/ERK molecular interactions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_EVID349_PMC1221294_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000350' AND x.extraction_id='M23B-P2-R-000284');
