INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000264', 'M23B-EVID-000386', 'P2FALLBACK-23B-M23B-EVID-000386', 'PMCID:PMC3001003', '20929862', 'full_text_html', 'exact_identifier_match:PMCID:PMC3001003', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC3001003', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC3001003_TG2_FN_SDC4_SDC2_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000386' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000386');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000264', 'M23B-EVID-000387', 'M23B-P2-R-000321', 'PMCID:PMC3001003; PMID:19398782; PMID:20929862; PMID:22442151', '20929862', 'full_text_html', 'exact_identifier_match:PMCID:PMC3001003', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC3001003; PMID:19398782; PMID:20929862; PMID:22442151; https://pmc.ncbi.nlm.nih.gov/articles/PMC3001003/; https://pubmed.ncbi.nlm.nih.gov/19398782/; https://pubmed.ncbi.nlm.nih.gov/20929862/; https://pubmed.ncbi.nlm.nih.gov/22442151/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B064_pmc3001003_tg2_sdc4_full.xml', 'TG2-FN matrix adhesion required syndecan-4 and beta1-integrin co-signaling, with PKC-alpha proposed as a link to syndecan-2/ROCK and actin organization. The matrix response was RGD-independent and did not require TG2 transamidase activity. The retrieved boundary does not resolve a single SDC4-to-PKC/FAK/integrin ordering across all models.', 'Retain TG2-FN-syndecan-4/beta1-integrin-PKC-alpha/ROCK receptor-proximal matrix signaling as abstract-only. Keep syndecan-2 downstream and do not infer direct TG2-PKC, TG2-ROCK, or TG2-beta1 molecular edges.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC3001003_TG2_FN_SDC4_SDC2_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000387' AND x.extraction_id='M23B-P2-R-000321');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000264', 'M23B-EVID-000388', 'P2FALLBACK-23B-M23B-EVID-000388', 'PMCID:PMC3001003', '20929862', 'full_text_html', 'exact_identifier_match:PMCID:PMC3001003', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC3001003', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC3001003_TG2_FN_SDC4_SDC2_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000388' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000388');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000045', 'M23B-EVID-000070', 'M23B-P2-R-000070', 'PMID:7542940; PMCID:PMC301201; DOI:10.1091/mbc.6.4.419', '7542940', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC301201', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC301201; PMID:7542940; DOI:10.1091/mbc.6.4.419; https://europepmc.org/articles/PMC301201?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC301201_beta8_neural_fulltext_7542940.pdf', 'In embryonic chick dorsal-root-ganglion cultures, surface-labeling immunoprecipitation identified the beta8 integrin subunit with putative alpha partners. Affinity-purified anti-beta8-Ex strongly inhibited neurite outgrowth on fibronectin, including the fibronectin 40-kDa C-terminal fragment, while alpha4/beta1 blocking antibodies and beta8 blockade showed distinct substrate-specific contributions. The study supports a beta8-containing integrin-dependent FN1 neurite-outgrowth function, but does not resolve the alpha partner or provide purified FN1-beta8 heterodimer affinity.', 'The authors conclude that beta8 integrins in association with one or more alpha subunits form an important set of extracellular-matrix receptors on chick sensory neurons and mediate part of fibronectin-dependent neurite outgrowth. The exact alpha partner for the FN1 beta8-containing complex remains unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC301201_beta8_neural_fulltext_7542940.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000070' AND x.extraction_id='M23B-P2-R-000070');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000053', 'M23B-EVID-000078', 'M23B-P2-R-000078', 'PMID:7542940; PMCID:PMC301201; DOI:10.1091/mbc.6.4.419', '7542940', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC301201', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC301201; PMID:7542940; DOI:10.1091/mbc.6.4.419; https://europepmc.org/articles/PMC301201?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC301201_beta8_neural_fulltext_7542940.pdf', 'In embryonic chick dorsal-root-ganglion cultures, surface-labeling immunoprecipitation identified beta8 integrin with putative alpha partners. Affinity-purified anti-beta8-Ex inhibited neurite outgrowth on intact laminin-1 and heat-inactivated laminin-1; the heat-resistant laminin functional site was mapped to a domain likely corresponding to laminin E1X. The study supports a beta8-containing integrin-dependent LAMA1 neurite-outgrowth function, but does not resolve the alpha partner or provide purified LAMA1-beta8 heterodimer affinity.', 'The authors conclude that beta8 integrins in association with one or more alpha subunits form an important set of extracellular-matrix receptors on chick sensory neurons and mediate part of laminin-1-dependent neurite outgrowth. The exact alpha partner for the LAMA1 beta8-containing complex remains unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC301201_beta8_neural_fulltext_7542940.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000078' AND x.extraction_id='M23B-P2-R-000078');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004099', 'M22B-EVID-001943', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC3110033_VEGFA_FLT1_PTK7_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-001943' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000270', 'M23B-EVID-000398', 'P2FALLBACK-23B-M23B-EVID-000398', 'PMCID:PMC3110033', '21460247', 'full_text_html', 'exact_identifier_match:PMCID:PMC3110033', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC3110033', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC3110033_VEGFA_FLT1_PTK7_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000398' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000398');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000270', 'M23B-EVID-000399', 'M23B-P2-R-000332', 'PMCID:PMC3110033; PMID:21460247', '21460247', 'full_text_html', 'exact_identifier_match:DOI:10.1182/blood-2010-09-306928;PMCID:PMC3110033', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3110033; PMID:21460247; DOI:10.1182/blood-2010-09-306928; https://pmc.ncbi.nlm.nih.gov/articles/PMC3110033/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B066_vegfa_flt1_PMC3110033_full.xml', 'In primary endothelial models, PTK7 co-immunoprecipitated with Flt-1 but not KDR/Flk-1 or Flt-4. SPR confirmed the PTK7-Flt-1 interaction and VEGF-A increased the receptor-complex interaction. PTK7 silencing reduced VEGF-induced Flt-1 phosphorylation and downstream FAK and Akt phosphorylation.', 'Promote the PTK7-FLT1 receptor-complex relay and VEGF-A-dependent Flt-1-to-FAK/Akt signaling in vascular endothelial models. Do not create direct VEGFA-PTK7, PTK7-FAK, or VEGFA-Akt molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC3110033_VEGFA_FLT1_PTK7_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000399' AND x.extraction_id='M23B-P2-R-000332');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000270', 'M23B-EVID-000400', 'M23B-P2-R-000333', 'PMCID:PMC3110033; PMID:21460247; DOI:10.1182/blood-2010-09-306928', '21460247', 'full_text_html', 'exact_identifier_match:DOI:10.1182/blood-2010-09-306928;PMCID:PMC3110033', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text_importable', 'PMCID:PMC3110033; PMID:21460247; DOI:10.1182/blood-2010-09-306928; https://pmc.ncbi.nlm.nih.gov/articles/PMC3110033/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B066_vegfa_flt1_PMC3110033_full.xml', 'VEGF-A stimulation of vascular endothelial models produced PTK7/Flt-1-associated migration and angiogenic outputs. PTK7 overexpression enhanced endothelial tube formation, migration, and angiogenesis in vitro, whereas PTK7 silencing reduced VEGF-A-induced migration/angiogenesis and mouse corneal neovascularization.', 'Promote VEGF-A/Flt-1/PTK7-associated endothelial migration and angiogenesis outputs in the tested vascular models. Do not create direct VEGFA-PTK7, VEGFA-FAK, or VEGFA-TF molecular edges.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC3110033_VEGFA_FLT1_PTK7_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000400' AND x.extraction_id='M23B-P2-R-000333');
