INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000008', 'M23B-EVID-000009', 'M23B-P2-R-000009', 'PMCID:PMC2199946; PMID:7542249', '7542249', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.130.2.451;PMCID:PMC2199946', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451; local HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946.html; local XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946_epmc.xml', 'The primary abstract reports that recombinant soluble CD31/PECAM-1 supported heterophilic leukocyte adhesion mediated by alphaVbeta3 integrin, that the interaction mapped to the second PECAM-1 Ig-like domain and was inhibited by alphaVbeta3-specific antibodies, and that alphaVbeta3 was precipitated from cell lysates by recombinant CD31. Exact full-text assay conditions and figure loci remain unavailable because PMC exposes the article body as PDF-only and the publisher route was access-blocked.', 'The abstract-level primary claim is that alphaVbeta3 is a heterophilic ligand for CD31/PECAM-1 in leukocyte-endothelial adhesion; full-text methods and figure verification are required before import-ready promotion.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch062_PMC2199946_PECAM1_alphaVbeta3.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000009' AND x.extraction_id='M23B-P2-R-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000008', 'M23B-EVID-000009', 'M23B-P2-R-RECOVERY-PECAM1-ITGAVB3-000001', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451', '7542249', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.130.2.451;PMCID:PMC2199946', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451; https://pmc.ncbi.nlm.nih.gov/articles/PMC2199946/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch062_PMC2199946_PECAM1_alphaVbeta3.html', 'Recombinant CD31/PECAM-1 supported heterophilic leukocyte adhesion through its second Ig-like domain; alphaVbeta3-specific antibodies inhibited the adhesion and recombinant CD31 precipitated alphaVbeta3 from cell lysates. This is direct pair-specific adhesion evidence in an endothelial/leukocyte comparator system, with no SCI or neural receiver-cell inference.', 'The authors conclude that alphaVbeta3 integrin is a heterophilic ligand for CD31/PECAM-1 and that the pair contributes to leukocyte-endothelial adhesion. The direct molecular record is retained as an adhesion interaction; no downstream TF or SCI transfer is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch062_PMC2199946_PECAM1_alphaVbeta3.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000009' AND x.extraction_id='M23B-P2-R-RECOVERY-PECAM1-ITGAVB3-000001');
