INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000026', 'M23B-EVID-000027', 'M23B-P2-R-000027', 'PMCID:PMC2288935; PMID:2010469; PMID:7535784; DOI:10.1083/jcb.113.2.417', '2010469', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.113.2.417;PMCID:PMC2288935', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_author_claim', 'PMID:8344274; DOI:10.1111/j.1432-1033.1993.tb18017.x; PMCID:PMC2288935; PMID:2010469; PMID:7535784; https://pubmed.ncbi.nlm.nih.gov/8344274/', 'Purified isolated alpha1beta1 and alpha2beta1 integrins bound the collagen-IV CB3 fragment in solid-phase and inhibition assays, with nanomolar affinity and cation-dependent specificity. The linked neural primary study separately shows collagen-IV/NC1 and alpha1beta1-dependent neurite outgrowth by antibody blockade.', 'The direct primary binding study establishes collagen-IV recognition by isolated alpha1beta1, while the neural study provides separate alpha1beta1-dependent neurite/axon outgrowth context.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch062_PMC2288935_collagenIV_integrin.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000027' AND x.extraction_id='M23B-P2-R-000027');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000026', 'M23B-EVID-000027', 'M23B-P2-R-RECOVERY-COLL4-ITGA1B1-000001', 'PMCID:PMC2288935; PMID:2010469; PMID:7535784; DOI:10.1083/jcb.113.2.417', '2010469', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.113.2.417;PMCID:PMC2288935', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_author_claim', 'PMID:8344274; DOI:10.1111/j.1432-1033.1993.tb18017.x; PMCID:PMC2288935; PMID:2010469; PMID:7535784; https://pubmed.ncbi.nlm.nih.gov/8344274/', 'The primary isolated-integrin study showed collagen-IV CB3 fragment binding to purified alpha1beta1 and alpha2beta1 in solid-phase/inhibition assays with nanomolar affinity. The linked neural study showed collagen-IV/NC1-dependent neurite outgrowth blocked by beta1-integrin and alpha1beta1-specific antibodies.', 'The authors conclude that the NC1 domain of type-IV collagen promotes axonal growth through interaction with alpha1beta1 integrin in peripheral neurons. The observation remains a receptor-dependent functional adhesion/outgrowth record and does not infer SCI relevance or a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch062_PMC2288935_collagenIV_integrin.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000027' AND x.extraction_id='M23B-P2-R-RECOVERY-COLL4-ITGA1B1-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_pdf', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch285_Tamaru_36336030_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'search_output', 'not_attempted', 'metadata_or_search_only', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact. Its role is metadata/search/manifest output and it is not treated as direct biological evidence.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch285_Tamaru_36336030_fulltext.txt' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000006', 'M23B-EVID-000007', 'M23B-P2-R-000007', 'PMCID:PMC12048928; PMID:40317093', '40317093', 'full_text_html', 'exact_identifier_match:DOI:10.1186/s40478-025-01995-0;PMCID:PMC12048928', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch286_PMC12048928_alpha9_kindlin1.html; PMCID:PMC12048928; PMID:40317093; DOI:10.1186/s40478-025-01995-0', 'In adult female rats with C4 or T10 complete dorsal-column crush lesions, AAV co-expression of alpha9 integrin and kindlin-1 enabled sensory axons to cross tenascin-C-positive connective-tissue bridges, re-enter rostral CNS tissue, and extend toward the medulla; cFOS/VGLUT readouts and sensory behavioral assays supported pathway reconstruction and sensory recovery. The intervention was the joint alpha9-integrin plus kindlin-1 treatment, with no alpha9-only arm.', 'The authors conclude that activated alpha9 integrin, in combination with kindlin-1, enables sensory axon regeneration through tenascin-C-positive connective-tissue bridges and supports reconstruction of sensory pathways and recovery after SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch286_PMC12048928_alpha9_kindlin1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000007' AND x.extraction_id='M23B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000019', 'M23B-EVID-000020', 'M23B-P2-R-000019', 'PMCID:PMC12048928; PMID:40317093; DOI:10.1186/s40478-025-01995-0', '40317093', 'full_text_html', 'exact_identifier_match:DOI:10.1186/s40478-025-01995-0;PMCID:PMC12048928', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:40317093; PMCID:PMC12048928; DOI:10.1186/s40478-025-01995-0; https://pmc.ncbi.nlm.nih.gov/articles/PMC12048928/', 'In adult female rats with complete C4 or T10 dorsal-column crush lesions, AAV-mediated co-expression of alpha9 integrin and kindlin-1 enabled sensory axons to regenerate through laminin-positive and tenascin-C-positive lesion bridges, form functional connections above the lesion, and improve sensory behavior. The study is a receptor-associated pathway and functional experiment, not a purified tenascin-C–alpha9beta1 binding assay.', 'The primary SCI study supports an alpha9-integrin/kindlin-1 receptor-associated regeneration branch and downstream sensory-function outputs; it does not establish direct tenascin-C or laminin-111 binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch286_PMC12048928_alpha9_kindlin1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000020' AND x.extraction_id='M23B-P2-R-000019');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000019', 'M23B-EVID-000020', 'M23B-P2-R-RECOVERY-ALPHA9-K1-SCI-FULLTEXT-000001', 'PMID:40317093; PMCID:PMC12048928; DOI:10.1186/s40478-025-01995-0', '40317093', 'full_text_html', 'exact_identifier_match:DOI:10.1186/s40478-025-01995-0;PMCID:PMC12048928', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:40317093; PMCID:PMC12048928; DOI:10.1186/s40478-025-01995-0; https://pmc.ncbi.nlm.nih.gov/articles/PMC12048928/; https://pubmed.ncbi.nlm.nih.gov/40317093/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch286_PMC12048928_alpha9_kindlin1.html', 'In adult female rats with complete C4 or T10 dorsal-column crush lesions, AAV-mediated co-expression of α9 integrin and kindlin-1 in sensory DRG neurons enabled axons to cross the lesion and regenerate rostrally through laminin-positive connective-tissue bridges and tenascin-C-positive strands, whereas GFP and kindlin-1-only controls did not show comparable passage into and beyond the lesion. At 12 weeks, α9-kindlin-1 axons reached the medulla in the thoracic cohort; peripheral nerve stimulation produced more cFOS-positive neurons rostral to the lesion, V5-positive axon swellings co-localized with VGLUT1/2, and thoracic animals showed recovery in heat, pressure, and tape-removal tests. This validates an α9-integrin/kindlin-1 receptor-associated regeneration branch and downstream sensory-function outputs, not a purified tenascin-C–α9β1 binding edge.', 'The authors conclude that activating an introduced α9β1 integrin with kindlin-1 enables sensory axons to use tenascin-C/laminin-associated connective-tissue bridges, regenerate long distances through spinal lesions, form functional connections above the lesion, and improve sensory behavior. The study establishes a receptor-associated pathway and functional branch; it does not establish direct molecular binding in this experiment or a terminal TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch286_PMC12048928_alpha9_kindlin1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000020' AND x.extraction_id='M23B-P2-R-RECOVERY-ALPHA9-K1-SCI-FULLTEXT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000008', 'M23B-EVID-000009', 'M23B-P2-R-000009', 'PMCID:PMC2199946; PMID:7542249', '7542249', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2199946', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451; local HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946.html; local XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946_epmc.xml', 'The primary abstract reports that recombinant soluble CD31/PECAM-1 supported heterophilic leukocyte adhesion mediated by alphaVbeta3 integrin, that the interaction mapped to the second PECAM-1 Ig-like domain and was inhibited by alphaVbeta3-specific antibodies, and that alphaVbeta3 was precipitated from cell lysates by recombinant CD31. Exact full-text assay conditions and figure loci remain unavailable because PMC exposes the article body as PDF-only and the publisher route was access-blocked.', 'The abstract-level primary claim is that alphaVbeta3 is a heterophilic ligand for CD31/PECAM-1 in leukocyte-endothelial adhesion; full-text methods and figure verification are required before import-ready promotion.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext/PMC2199946_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000009' AND x.extraction_id='M23B-P2-R-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000008', 'M23B-EVID-000009', 'M23B-P2-R-RECOVERY-PECAM1-ITGAVB3-000001', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451', '7542249', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2199946', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451; https://pmc.ncbi.nlm.nih.gov/articles/PMC2199946/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch062_PMC2199946_PECAM1_alphaVbeta3.html', 'Recombinant CD31/PECAM-1 supported heterophilic leukocyte adhesion through its second Ig-like domain; alphaVbeta3-specific antibodies inhibited the adhesion and recombinant CD31 precipitated alphaVbeta3 from cell lysates. This is direct pair-specific adhesion evidence in an endothelial/leukocyte comparator system, with no SCI or neural receiver-cell inference.', 'The authors conclude that alphaVbeta3 integrin is a heterophilic ligand for CD31/PECAM-1 and that the pair contributes to leukocyte-endothelial adhesion. The direct molecular record is retained as an adhesion interaction; no downstream TF or SCI transfer is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext/PMC2199946_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000009' AND x.extraction_id='M23B-P2-R-RECOVERY-PECAM1-ITGAVB3-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-001456', '', '', NULL, 'full_text_or_bioc_json', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext/PMC2199946_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001456' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000005', 'M23B-EVID-000006', 'M23B-P2-R-000006', 'PMCID:PMC7509206; PMID:32957245; DOI:10.1016/j.jmbbm.2020.103953', '32957245', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC7509206', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC7509206; PMID:32957245; DOI:10.1016/j.jmbbm.2020.103953; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext/PMC7509206_bioc.json', 'In an approximately 18-week mouse hemi-section SCI model, AFM mapping found a significant reduction in Young''s modulus at the chronic injury core and progressively lower modulus toward the scar center relative to uninjured tissue. The same study documented dense and disorganized nuclei, a CNS-cell-poor fibrotic core bordered by GFAP-positive glial scar, increased vimentin, reduced total sulfated proteoglycans, increased CSPGs, and increased hyaluronan in scar compartments.', 'The authors conclude that chronic hemi-section SCI scar has altered mechanical and extracellular-matrix composition that can shape mechanochemical cell behavior and contribute to an anti-regenerative environment. Retain this as matrix/functional evidence for the fibrotic-scar branch, not as FnEDA-specific receptor or intracellular signaling evidence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext/PMC7509206_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000006' AND x.extraction_id='M23B-P2-R-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000179', 'M23B-EVID-000253', 'P2FALLBACK-23B-M23B-EVID-000253', 'PMCID:PMC7509206', '32957245', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC7509206', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMCID:PMC7509206', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext/PMC7509206_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000253' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000253');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000250', 'M23B-EVID-000350', 'M23B-P2-R-000284', 'PMID:10970776; PMCID:PMC1221294', '10970776', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC1221294', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1221294; PMID:10970776; https://europepmc.org/articles/PMC1221294?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC1221294_PYY_Y1R_fulltext_10970776.pdf', 'In IEC-6 rat jejunal epithelial cells stably expressing human Y1R, Scatchard analysis of equilibrium 125I-PYY binding reported a Kd of approximately 0.2 nM and approximately 104,000 receptors per cell (Results, Fig. 1). PYY induced time-dependent ERK/MAPK phosphorylation with an early peak at 3 minutes and sustained elevation to 1 hour (Fig. 3); pertussis toxin and alpha-transducin implicate Gi/Go and beta-gamma subunits (Fig. 2). PKC inhibitors blocked PYY-induced MAPK phosphorylation and PYY induced PKCepsilon membrane translocation (Figs. 4-5). Src-family and EGFR tyrosine-kinase inhibitors blocked the PYY-MAPK branch, and PYY increased EGFR tyrosine phosphorylation (Figs. 6-8). PYY stimulated growth of Y1R-expressing cells in an EGFR-kinase-dependent manner (Fig. 9).', 'The authors conclude that PYY activates Y1R-linked Gi/Go and beta-gamma signaling through Src-family kinase, EGFR transactivation, and PKC to produce MAPK activation and epithelial-cell growth. The paper supports a PYY-Y1R cellular binding/relay context; it does not establish direct PYY binding to EGFR or direct PYY-Src/PKC/ERK molecular interactions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext_batch2/PMC1221294_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000350' AND x.extraction_id='M23B-P2-R-000284');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_or_bioc_json', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext_batch2/PMC1885470_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
