INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-000006', 'PMID:32964315', '32964315', 'full_text_pdf', 'exact_identifier_match:PMID:32964315', 'linked_unresolved', 'B', 'L4', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', 'Stable PMID and DOI anchor are present, but no retained abstract or full-text Results/Methods/figure passage was available in the local cache; the registered RvD3 resolution/neuroprotection summary is not sufficient for an atomic Observation.', 'No import-ready author claim; the B-layer summary cannot be converted into a claim without the primary paper passage.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B002_PMID32964315_RvD3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-000006', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', '32964315', 'full_text_pdf', 'exact_identifier_match:PMID:32964315', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text', 'validated_author_claim', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7; https://link.springer.com/article/10.1007/s12035-020-02118-7; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B002_PMID32964315_RvD3_SCI_fulltext.pdf', 'In female C57BL/6 mice with T10 weight-compression SCI (20 g for 1 minute), a single intrathecal RvD3 injection (1 microgram/20 microliters at 1 hour) improved BMS locomotor recovery, reduced thermal hyperalgesia and lesion area, lowered inflammatory cytokine/chemokine expression, shifted macrophage markers toward an M2-associated pattern, preserved tight-junction proteins, and reduced glial/fibrotic scar markers. In LPS-treated RAW264.7 cells and hCMEC/D3 endothelial cells, RvD3 reduced inflammatory/NO outputs and increased migration or angiogenic-associated markers.', 'Promote the bounded RvD3 downstream functional branch for inflammatory resolution, neuroprotection, pain reduction, barrier preservation, and locomotor recovery in this mouse SCI model. Do not infer a cognate receptor, receptor-proximal relay, or terminal TF: the authors explicitly state that the detailed G-protein receptor mechanism was not investigated and that unique RvD3/RvD4 receptors remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B002_PMID32964315_RvD3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-000921', 'PMID:32964315', '32964315', 'full_text_pdf', 'exact_identifier_match:PMID:32964315', 'supporting_validated_claim', 'B', 'L4', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMID:32964315; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Primary SCI paper retrieved; exact observation retained at source scope.', 'SCI phenotype is supported at the reported model scope; no direct terminal-TF edge was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B002_PMID32964315_RvD3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-000921');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-RECOVERY-RVD3-SCI-ABSTRACT-000001', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', '32964315', 'full_text_pdf', 'exact_identifier_match:PMID:32964315', 'candidate_requires_review', 'B', 'L4', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7; https://pubmed.ncbi.nlm.nih.gov/32964315/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml', 'In female C57BL/6 mice subjected to moderate compression SCI, intrathecal RvD3 at 1 microgram/20 microliters one hour after injury improved locomotor recovery and reduced thermal hyperalgesia at 14 days. RvD3 treatment reduced TNF-alpha, IL6, IL1beta, CCL2, and CCL3, increased ZO-1 and occludin, reduced GFAP/Iba1 gliosis and CD68/TGF-beta neuroinflammation, and enhanced neuroprotection. In RAW264.7 cells and hCMEC/D3 cells, RvD3 reduced LPS-induced inflammatory mediators/NO and promoted angiogenic responses.', 'The primary authors conclude that RvD3 promotes inflammatory resolution, neuroprotection, barrier-associated protein expression, and neurological recovery after experimental SCI. The record supports downstream function only; no RvD3 receptor, intracellular relay, or terminal TF was established in the retrieved primary abstract.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B002_PMID32964315_RvD3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-RECOVERY-RVD3-SCI-ABSTRACT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000178', '', '', NULL, 'full_text_pdf', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B002_PMID32964315_RvD3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000178' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000007', 'M24B-P2-000007', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971', '37446149', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC10341423', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971; https://europepmc.org/articles/PMC10341423; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf', 'In Sprague-Dawley rats with T9 compressive SCI, a single post-injury administration of RvD1 (0.1 microgram) combined with peripheral-nerve-derived stem-cell spheroids improved BBB locomotion, ladder-rung performance, tissue regeneration/remyelination measures, and mechanical allodynia relative to injury controls and monotherapy groups. In LPS-stimulated PNSC spheroids, RvD1 reduced TNF-alpha, IL-1beta, and NF-kappaB protein signals and increased IL-10 and TGF-beta transcripts.', 'Promote the bounded RvD1-plus-PNSC combination-therapy functional branch in the reported rat SCI model, including anti-inflammatory marker changes and locomotor/tissue-regeneration outputs. Do not infer that RvD1 alone caused the combination effect, do not promote ALX/FPR2 as directly tested in this paper, and do not assign a terminal TF beyond the measured NF-kappaB protein signal.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000007' AND x.extraction_id='M24B-P2-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000007', 'M24B-P2-R-000007', 'PMID:37446149', '37446149', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC10341423', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:37446149; PMCID:PMC10341423; DOI:10.1007/s12035-020-02118-7; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC10341423_article.html', 'In vitro RvD1 treatment of LPS-stimulated peripheral nerve-derived stem-cell spheroids reduced TNF-alpha, IL-1beta, and NF-kB and increased IL-10/TGF-beta at selected concentrations. In a rat compressive SCI model, the RvD1 plus spheroid combination produced the strongest BBB/laddder-rung recovery and reduced inflammatory markers compared with vehicle and monotherapy groups.', 'The authors interpret combined RvD1 and PNSC spheroid treatment as a therapeutic strategy that enhances neuronal regeneration and anti-inflammatory recovery after SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000007' AND x.extraction_id='M24B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000012', 'M24B-P2-000012', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971', '37446149', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC10341423', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971; https://europepmc.org/articles/PMC10341423; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf', 'The same full-text primary paper supports reuse of the validated RvD1-plus-PNSC combination-therapy observation on the duplicate B evidence record: rat T9 compressive SCI functional/tissue-regeneration outputs and LPS-stimulated PNSC-spheroid inflammatory marker changes are documented in Results, Figures 1-3, and Methods 4.4-4.8.', 'Reuse the bounded author claim from M24B-P2-000007 for this separate evidence record; no duplicate observation is created. Direct RvD1-receptor binding, receptor-proximal relay, ALX/FPR2 causality, and terminal-TF occupancy remain unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000012' AND x.extraction_id='M24B-P2-000012');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000014', 'M24B-EVID-000014', 'M24B-P2-000014', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248', '16936276', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC1698827', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248; https://europepmc.org/articles/PMC1698827; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC1698827_CR2_Crry_C3_SCI_fulltext.pdf', 'In female C57BL/6 mice with T12 weight-drop contusion SCI, deposited C3 and radiolabeled engineered CR2-Crry localized to the injury site; C3 deficiency or a single intravenous 0.25 mg CR2-Crry dose at 1 hour reduced neutrophil infiltration, tissue destruction/demyelination, and improved BBB locomotor recovery through the reported 21-day window. The study supports targeting/association of the CR2 domain with deposited C3 fragments in the engineered inhibitor context.', 'Promote the bounded engineered CR2-Crry targeting and C3-level complement-inhibition branch in mouse contusion SCI, including reduced neutrophil infiltration/tissue injury and improved locomotor recovery. Do not substitute intact C3 for a defined C3b/iC3b/C3d/C3dg ligand, do not treat CR2-Crry biodistribution as purified affinity, and do not infer an intracellular CR2 relay or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC1698827_CR2_Crry_C3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000014' AND x.extraction_id='M24B-P2-000014');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000014', 'M24B-EVID-000014', 'M24B-P2-R-RECOVERY-C3FRAG-CR2CRRY-SCI-000001', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248', '16936276', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC1698827', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248; https://pmc.ncbi.nlm.nih.gov/articles/PMC1698827/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC1698827_C3_CR2-Crry.html', 'After traumatic mouse SCI, C3-deficient animals had better BBB locomotor scores, more tissue sparing, and less necrosis, demyelination, and neutrophil infiltration than wild-type controls. A single intravenous dose of engineered CR2-Crry one hour after injury improved locomotor outcome and pathology similarly and localized to deposited C3 at the lesion. The paper supports C3-fragment engagement by the CR2 targeting domain and C3-level complement inhibition in SCI; it does not identify the exact endogenous fragment or establish a purified CR2-fragment affinity measurement.', 'The authors conclude that complement activation contributes to secondary SCI and that CR2-Crry targets deposited C3 fragments at the lesion to inhibit complement and improve recovery. The target is an engineered CR2-Crry receptor-like targeting domain, not an endogenous CR2 signaling pathway, and the exact C3 breakdown fragment remains unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC1698827_CR2_Crry_C3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000014' AND x.extraction_id='M24B-P2-R-RECOVERY-C3FRAG-CR2CRRY-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000028', '', '', NULL, 'full_text_pdf', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC1698827_CR2_Crry_C3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000028' AND x.extraction_id='');
