INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000031', '', '', NULL, 'full_text_pdf', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC1698827_CR2_Crry_C3_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000031' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000015', 'M24B-EVID-000015', 'M24B-P2-000015', 'PMCID:PMC4624364; PMID:26502875; DOI:10.1186/s12974-015-0413-6', '26502875', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC4624364', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC4624364; PMID:26502875; DOI:10.1186/s12974-015-0413-6; https://europepmc.org/articles/PMC4624364; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC4624364_CR2_nerve_injury_fulltext.pdf', 'In rat ventral-root-avulsion and sciatic-nerve-transection models, Cr2 expression rose after injury and was associated with glial responses; in Cr2-knockout mice after sciatic-nerve transection, synaptophysin loss in the ventral horn was greater than in wild-type controls. Rat astrocyte cultures expressed Cr2 by RT-PCR whereas microglia did not, and soluble CR2 increased in CSF after ventral-root avulsion.', 'Promote the bounded CR2-associated peripheral-nerve-injury functional branch: injury-associated Cr2 expression and astrocyte localization correlate with complement/synaptic responses, while Cr2 loss increases synaptic-terminal loss after sciatic-nerve transection. Keep this as a peripheral-nerve comparator, not contusive SCI; do not infer a C3-fragment binding event, intracellular CR2 relay, or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC4624364_CR2_nerve_injury_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000015' AND x.extraction_id='M24B-P2-000015');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000017', 'M24B-EVID-000017', 'M24B-P2-R-000017', 'PMCID:PMC9836372; PMID:36634215; DOI:10.1111/bpa.13113', '36634215', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC9836372', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC9836372; PMID:36634215; DOI:10.1111/bpa.13113; https://europepmc.org/articles/PMC9836372; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B004_PMC9836372_S100A8_TLR4_SCI_fulltext.pdf', 'In rat spinal ischemia/reperfusion injury, intrathecal recombinant S100A8 increased TLR4, p-ERK/ERK, p-NF-kB/NF-kB, IL-1beta, and apoptosis-associated readouts; TAK-242 given before S100A8 reduced TUNEL-positive cells and these pathway readouts. S100A8 knockdown also reduced the same inflammatory/apoptotic outputs.', 'The authors conclude that Fra-1/S100A8 forms a feedback loop involving TLR4, ERK1/2, and NF-kB that promotes apoptosis and neuroinflammation after spinal ischemia/reperfusion injury.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B004_PMC9836372_S100A8_TLR4_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000017' AND x.extraction_id='M24B-P2-R-000017');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000022', 'M24B-EVID-000022', 'M24B-P2-R-000022', 'PMCID:PMC4761922; PMID:26899371', '26899371', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4761922', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text', 'validated_receptor_proximal_relay', 'PMCID:PMC4761922; PMID:26899371; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B269_PMC4761922_bioc.json', 'Tenascin-C was released into conditioned medium from one-week injured rat spinal-cord explants, and injury-conditioned medium induced inflammatory genes and p38, ERK, ATF2, and NF-kB-associated signaling in primary rat fibroblasts. TLR4 siRNA partially suppressed iNOS, IL6, TNF, and CXCL10 responses, while TLR4 pathway signaling remained confounded by other soluble alarmins and cytokine inputs. The study does not isolate tenascin-C as the sole TLR4 agonist.', 'Promote an injury-conditioned-medium -> TLR4-associated p38/ERK/ATF2/NF-kB inflammatory relay in the tested SCI-derived fibroblast model, with tenascin-C retained as a candidate alarmin component rather than a promoted direct TNC-TLR4 edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B269_PMC4761922_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000022' AND x.extraction_id='M24B-P2-R-000022');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_or_bioc_json', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B269_PMC7694914_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000023', 'M24B-EVID-000023', 'M24B-P2-R-000023', 'PMID:16629625; DOI:10.1089/neu.2006.23.397', '16629625', 'literature_xml', 'exact_identifier_match:PMID:16629625', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_output', 'PMID:16629625; DOI:10.1089/neu.2006.23.397; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B269_PMID16629625_pubmed.xml', 'Intralesional human recombinant decorin infusion during the first eight days after rat dorsal-column SCI increased plasminogen and plasmin protein at the injury site, while decorin treatment of cultured adult spinal-cord microglia increased plasminogen mRNA. The measured output supports protease-associated CSPG remodeling and axon-growth permissiveness, not decorin-TLR2 signaling.', 'Promote decorin-associated plasminogen/plasmin induction and protease-adjacency remodeling in acute SCI and adult spinal-cord microglia. Keep this functional/protease output separate from any unmeasured decorin receptor or downstream TF claim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B269_PMID16629625_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000023' AND x.extraction_id='M24B-P2-R-000023');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000024', 'M24B-EVID-000024', 'M24B-P2-R-000024', 'PMID:38326029; DOI:10.1523/JNEUROSCI.0778-23.2023', '38326029', 'literature_xml', 'exact_identifier_match:PMID:38326029', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:38326029; DOI:10.1523/JNEUROSCI.0778-23.2023; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B269_PMID38326029_pubmed.xml', 'In adult female TLR4-null mice with chronic contusion SCI, loss of TLR4 signaling reduced late NF-kB activation, inflammatory cytokines, necroptotic-pathway expression, neuronal and myelin loss, scar-related ECM, and improved serotonergic fiber sprouting and locomotor recovery at eight weeks. The direction is TLR4 signaling -> downstream ECM/inflammation/function; no MMP9->TLR4 activation was established.', 'Promote TLR4 signaling as an upstream receptor-pathway context that modulates chronic SCI inflammation, NF-kB-associated cell-death/ECM programs, axonal sprouting, and locomotor recovery. Do not reverse the edge into MMP9 activating TLR4 and do not infer a ligand or direct binding record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B269_PMID38326029_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000024' AND x.extraction_id='M24B-P2-R-000024');
