INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000038', 'M24B-EVID-PROMO-20260826-005', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B270_PMID33621043_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-PROMO-20260826-005' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000144', 'M24B-EVID-PROMO-20260826-024', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B270_PMID33621043_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-PROMO-20260826-024' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000010', 'M24B-EVID-000005', 'M24B-P2-000005', 'PMCID:PMC2241786; PMID:18059327; DOI:10.1038/sj.bjp.0707577', '18059327', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC2241786', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC2241786; PMID:18059327; DOI:10.1038/sj.bjp.0707577; https://europepmc.org/articles/PMC2241786; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B271_PMC2241786_5LO_CysLT1_SCI_fulltext.pdf', 'In male CD1 mice subjected to T6-T7 clip-compression SCI, zileuton or montelukast reduced inflammatory-cell infiltration, tissue injury, apoptosis-associated Bax/FasL changes, COX-2 expression, and ERK1/2 phosphorylation, while improving motor recovery in the reported treatment window. The paper also measured SCI-associated PGE2 and LTB4 increases and their reduction after drug treatment.', 'Promote the bounded 5-lipoxygenase/cysteinyl-leukotriene pathway modulation branch to ERK1/2, COX-2, apoptosis, inflammatory-cell, and locomotor outputs in this mouse SCI model. Do not infer a purified leukotriene-receptor interaction, BLT1 specificity, or a terminal TF from the pharmacology.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B271_PMC2241786_5LO_CysLT1_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000005' AND x.extraction_id='M24B-P2-000005');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000010', 'M24B-EVID-000005', 'M24B-P2-R-RECOVERY-5LO-CYSLT-SCI-000001', 'PMCID:PMC2241786; PMID:18059327; DOI:10.1038/sj.bjp.0707577', '18059327', 'full_text_pdf', 'exact_identifier_match:PMCID:PMC2241786', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2241786; PMID:18059327; DOI:10.1038/sj.bjp.0707577; https://pmc.ncbi.nlm.nih.gov/articles/PMC2241786/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC2241786_lipid_mediator.html', 'In a mouse T6-T7 clip-compression SCI model, 5-LO inhibition with zileuton and Cys-LT1-directed pharmacology with montelukast reduced tissue edema and injury, neutrophil infiltration, TNF-alpha, COX-2, PGE2, LTB4, pERK1/2, and apoptosis, while improving limb-function recovery over 10 days. This supports a receptor-proximal/pathway and functional leukotriene/eicosanoid branch, but the pharmacology does not isolate a single endogenous ligand-receptor edge.', 'The authors conclude that 5-LO products and Cys-LT signaling contribute to inflammatory events and tissue injury after experimental SCI, and that zileuton or montelukast improves recovery. This remains a pathway/pharmacology record and does not establish a purified LTB4/CysLT1 binding edge or a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B271_PMC2241786_5LO_CysLT1_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000005' AND x.extraction_id='M24B-P2-R-RECOVERY-5LO-CYSLT-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B271_PMC5635131_C3_axon_fullText.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
