INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000066', 'M24B-EVID-000087', 'M24B-P2-R-000087', 'PMID:29138422; PMCID:PMC5686125; DOI:10.1038/s41598-017-15586-0', '29138422', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC5686125', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_functional_context', 'PMID:29138422; PMCID:PMC5686125; DOI:10.1038/s41598-017-15586-0; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B284_PMC5686125_TAFA5_FPR2_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B285_PMID29138422_pubmed.xml', 'Mouse FAM19A5/TAFA5 stimulated bone-marrow-derived macrophage chemotaxis and inhibited RANKL-induced osteoclastogenesis; WRW4 and Fpr2 deficiency reversed the effects, with ERK/Akt-associated signaling reported. The study supports an FPR2-dependent comparator relay but does not establish a purified binary FAM19A5-FPR2 binding measurement or any SCI lesion-context activity.', 'Retain FAM19A5/TAFA5 -> FPR2-dependent macrophage migration and anti-osteoclastogenesis as non-SCI comparator evidence. Do not promote a direct molecular binding edge, infer spinal release, or transfer the bone-remodeling output to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B284_PMC5686125_TAFA5_FPR2_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000087' AND x.extraction_id='M24B-P2-R-000087');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000040', 'M24B-EVID-000090', 'M24B-P2-R-000090', 'PMID:2007135; PMID:25904802; PMCID:PMC6605214; DOI:10.1523/JNEUROSCI.5218-14.2015', '25904802', 'literature_xml', 'exact_identifier_match:PMID:2007135', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:2007135; PMID:25904802; PMCID:PMC6605214; DOI:10.1523/JNEUROSCI.5218-14.2015; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B285_PMID2007135_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B278_PMID25904802_C5aR1_pubmed.xml', 'Expression cloning transferred specific binding of iodinated recombinant human C5a to the cloned human C5a receptor in COS-7 cells, establishing a direct cognate C5a-C5aR1 molecular interaction. In separate mouse contusive-SCI experiments, C5aR1 loss or early selective blockade reduced acute inflammation and improved early recovery, whereas continued receptor absence/blockade impaired later repair, myelin, lesion, and astroglial-scar outcomes.', 'Promote the direct C5a -> C5aR1 molecular edge and the phase-dependent C5aR1 SCI relay as separate evidence layers: acute signaling is injurious in the tested window, while post-acute signaling supports astrocyte hyperplasia/hypertrophy and glial-scar repair. Keep C5aR2-specific contributions and any universal downstream TF endpoint unresolved.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B285_PMID2007135_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000090' AND x.extraction_id='M24B-P2-R-000090');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000102', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B285_PMID2007135_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000102' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000066', 'M24B-EVID-000087', 'M24B-P2-R-000087', 'PMID:29138422; PMCID:PMC5686125; DOI:10.1038/s41598-017-15586-0', '29138422', 'literature_xml', 'exact_identifier_match:PMID:29138422', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_functional_context', 'PMID:29138422; PMCID:PMC5686125; DOI:10.1038/s41598-017-15586-0; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B284_PMC5686125_TAFA5_FPR2_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B285_PMID29138422_pubmed.xml', 'Mouse FAM19A5/TAFA5 stimulated bone-marrow-derived macrophage chemotaxis and inhibited RANKL-induced osteoclastogenesis; WRW4 and Fpr2 deficiency reversed the effects, with ERK/Akt-associated signaling reported. The study supports an FPR2-dependent comparator relay but does not establish a purified binary FAM19A5-FPR2 binding measurement or any SCI lesion-context activity.', 'Retain FAM19A5/TAFA5 -> FPR2-dependent macrophage migration and anti-osteoclastogenesis as non-SCI comparator evidence. Do not promote a direct molecular binding edge, infer spinal release, or transfer the bone-remodeling output to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B285_PMID29138422_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000087' AND x.extraction_id='M24B-P2-R-000087');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000067', 'M24B-EVID-000103', 'M24B-P2-R-RECOVERY-PGE2-EP2-SCI-000001', 'PMID:17329433; PMCID:PMC6673468', '17329433', 'literature_xml', 'exact_identifier_match:PMID:17329433', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMID:17329433; PMCID:PMC6673468; https://pubmed.ncbi.nlm.nih.gov/17329433/; https://pmc.ncbi.nlm.nih.gov/articles/PMC6673468/', 'In adult male Sprague-Dawley rats with T9 contusive SCI, microglial activation and ERK1/2 signaling were associated with spinal PGE2 release, EP2 receptor was localized to dorsal-horn neurons, and EP2 blockade reduced neuronal hyperresponsiveness and pain behavior; microglial depletion reduced PGE2 and reversed the pain phenotype.', 'The authors conclude that ERK-regulated microglia-neuron signaling through PGE2 and neuronal EP2 contributes to pain after SCI, and that interrupting microglial activation, ERK1/2, or EP2 reduces the pain phenotype. Retain this as receptor-proximal/pathway and functional evidence, not as a purified PGE2-EP2 binding result.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B286_PMID17329433_PGE2_EP2_SCI_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000103' AND x.extraction_id='M24B-P2-R-RECOVERY-PGE2-EP2-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000068', 'M24B-EVID-000104', 'M24B-P2-R-RECOVERY-PGE2-EP2-EP4-NEUROINFLAMMATION-000001', 'PMID:21075851; PMCID:PMC3023527; DOI:10.1074/jbc.M110.157362', '21075851', 'literature_xml', 'exact_identifier_match:PMID:21075851', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:21075851; PMCID:PMC3023527; DOI:10.1074/jbc.M110.157362; https://pubmed.ncbi.nlm.nih.gov/21075851/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3023527/', 'In primary rat spinal cultures and mouse neuroinflammation experiments, EP2 and EP4 agonism reduced LPS-induced TNF-alpha, COX2, mPGES1, and prostaglandin outputs; EP2 was upregulated in microglia, and EP2 genetic deletion or receptor agonism reduced inflammatory outputs.', 'The authors conclude that microsomal PGE synthase-1 and PGE2 receptor signaling participate in spinal neuroinflammation, with EP2/EP4 activation limiting selected inflammatory outputs in the tested culture and mouse contexts. This is a bounded pathway/function comparator, not direct PGE2-EP2 or PGE2-EP4 binding evidence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B287_PMID21075851_EP4_spinal_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000104' AND x.extraction_id='M24B-P2-R-RECOVERY-PGE2-EP2-EP4-NEUROINFLAMMATION-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000068', 'M24B-EVID-PROMO-20260826-009', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B287_PMID21075851_EP4_spinal_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-PROMO-20260826-009' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000070', 'M24B-EVID-000106', 'M24B-P2-R-RECOVERY-S1PR1-SPINAL-PAIN-000001', 'PMID:30802544; PMCID:PMC6933942; DOI:10.1016/j.jpain.2019.02.007', '30802544', 'literature_xml', 'exact_identifier_match:PMID:30802544', 'supporting_validated_claim', 'B', 'L3', 'validated_full_text_importable', 'validated_author_claim', 'PMID:30802544; PMCID:PMC6933942; DOI:10.1016/j.jpain.2019.02.007; https://pubmed.ncbi.nlm.nih.gov/30802544/; https://pmc.ncbi.nlm.nih.gov/articles/PMC6933942/', 'In a mouse spinal pain model, intrathecal S1PR1 agonism caused mechanical allodynia with NLRP3, cleaved caspase-1, and mature IL-1beta activation; FTY720 antagonism attenuated the phenotype, and astrocyte-specific S1pr1 deletion prevented allodynia and reduced cleaved caspase-1.', 'The authors conclude that spinal astrocytic S1PR1 signaling drives mechanohypersensitivity through NLRP3 inflammasome and IL-1beta activation in the tested mouse pain model. Retain this as receptor-proximal/pathway and functional evidence, not direct S1P-S1PR1 binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B287_PMID30802544_S1PR1_spinal_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000106' AND x.extraction_id='M24B-P2-R-RECOVERY-S1PR1-SPINAL-PAIN-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000071', 'M24B-EVID-000107', 'M24B-P2-R-RECOVERY-S1P-S1PR3-SCI-000001', 'PMID:33602274; PMCID:PMC7893778; DOI:10.1186/s12974-021-02092-4', '33602274', 'literature_xml', 'exact_identifier_match:PMID:33602274', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMID:33602274; PMCID:PMC7893778; DOI:10.1186/s12974-021-02092-4; https://pubmed.ncbi.nlm.nih.gov/33602274/; https://pmc.ncbi.nlm.nih.gov/articles/PMC7893778/', 'In rat traumatic SCI and cultured microglia, Sphk1 and S1P production increased with S1PR3 and p38 signaling; Sphk1 inhibition reduced p65 activation, inflammatory outputs, neuronal damage, and functional deficit, while exogenous S1P increased p38/p65 signaling and receptor/pathway inhibitors attenuated the response.', 'The authors conclude that Sphk1-derived S1P and S1PR3/p38/NF-kB signaling amplify microglial inflammation and secondary injury after SCI, while Sphk1 or pathway inhibition improves tissue and functional outcomes. Retain the branch as pathway/function evidence, not as purified S1P-S1PR3 binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B287_PMID33602274_S1PR3_SCI_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000107' AND x.extraction_id='M24B-P2-R-RECOVERY-S1P-S1PR3-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000069', 'M24B-EVID-000105', 'M24B-P2-R-000105', 'PMID:39386527; PMCID:PMC11463606; DOI:10.1101/2024.09.23.614540', '39386527', 'literature_xml', 'exact_identifier_match:PMID:39386527', 'supporting_validated_claim', 'B', 'L1', 'validated_in_silico_bounded', 'validated_context_only', 'PMID:39386527; PMCID:PMC11463606; DOI:10.1101/2024.09.23.614540; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B287_PMID39386527_RvD1_FPR2_pubmed.xml', 'Molecular-dynamics and membrane-partitioning analyses modeled RvD1 access to and interactions within the FPR2/ALX binding site, identifying a plausible binding pose and receptor residues. The source is a preprint/in-silico study rather than a purified biochemical binding experiment, and it does not establish GPR32 causality or an SCI receptor perturbation.', 'Retain RvD1/FPR2 as bounded structural molecular-context evidence supporting a plausible receptor-access/binding model. Do not promote it to definitive biochemical binding, infer GPR32 assignment, or transfer it to SCI without primary injury-context perturbation.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B287_PMID39386527_RvD1_FPR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000105' AND x.extraction_id='M24B-P2-R-000105');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000178', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B287_PMID39386527_RvD1_FPR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000178' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000074', 'M24B-EVID-000110', 'M24B-P2-R-RECOVERY-GAL9-TIM3-000001', 'PMID:16286920; DOI:10.1038/ni1271', '16286920', 'literature_xml', 'exact_identifier_match:PMID:16286920', 'linked_unresolved', 'B', 'L1', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:16286920; DOI:10.1038/ni1271; https://pubmed.ncbi.nlm.nih.gov/16286920/; https://www.nature.com/articles/ni1271', 'The primary study identified galectin-9 as a Tim-3 ligand; galectin-9-induced intracellular calcium flux, aggregation, and death of Th1 cells were Tim-3-dependent in vitro, and in vivo galectin-9 caused selective loss of interferon-gamma-producing cells and suppression of Th1 autoimmunity.', 'The authors conclude that the Tim-3/galectin-9 pathway terminates effector Th1 responses. Retain the ligand-receptor and functional observations in the tested immune context; do not infer SCI relevance or a terminal TF.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B288_PMID16286920_Gal9_TIM3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000110' AND x.extraction_id='M24B-P2-R-RECOVERY-GAL9-TIM3-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000075', 'M24B-EVID-000111', 'M24B-P2-R-000111', 'PMID:16286920; DOI:10.1038/ni1271', '16286920', 'literature_xml', 'exact_identifier_match:PMID:16286920', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_context', 'PMID:16286920; DOI:10.1038/ni1271; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B288_PMID16286920_Gal9_TIM3_pubmed.xml', 'Galectin-9/TIM-3-dependent calcium flux, Th1-cell aggregation and death, selective loss of interferon-gamma-producing cells, and suppression of Th1 autoimmunity were reported in mouse comparator systems. This functional output is retained separately from direct ligand/receptor assignment and has no SCI receiver-state validation.', 'Retain the Galectin-9/TIM-3 immune checkpoint functional outputs as non-SCI comparator evidence. Do not infer a spinal pathway, direct molecular edge from the functional readouts alone, or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B288_PMID16286920_Gal9_TIM3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000111' AND x.extraction_id='M24B-P2-R-000111');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E002606', 'M22B-EVID-001551', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B288_PMID23647384_Klk6_PAR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-001551' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E002607', 'M22B-EVID-001552', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B288_PMID23647384_Klk6_PAR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-001552' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000073', 'M24B-EVID-000109', 'M24B-P2-R-RECOVERY-KLK6-PAR-SCI-000001', 'PMCID:PMC4097186; PMID:23647384; DOI:10.1111/jnc.12293', '23647384', 'literature_xml', 'exact_identifier_match:PMID:23647384', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4097186; PMID:23647384; DOI:10.1111/jnc.12293; https://pmc.ncbi.nlm.nih.gov/articles/PMC4097186/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC4097186_Klk6_PAR.html', 'In mouse clip-compression SCI, Klk6, thrombin, PAR1, and PAR2 were differentially elevated. Recombinant Klk6 triggered ERK1/2 in primary cerebellar granule neurons and NSC34 spinal motoneurons; PAR1 genetic deletion and PAR1/PAR2 lipopeptide inhibitors reduced the response, and PI3K or MEK inhibition suppressed ERK1/2 activation. Klk6 and thrombin promoted neuronal loss and enhanced glutamate neurotoxicity; in NSC34 motoneurons, Klk6 increased Bim, cleaved PARP, and LDH release in a PAR1/PAR2-inhibitor-sensitive manner. This validates a receptor-proximal PAR1/PAR2-PI3K/MEK-ERK neurotoxicity relay, not purified protease-receptor binding.', 'The authors conclude that Klk6 signals through PAR1 and PAR2 to activate ERK1/2 through PI3K and MEK and to exacerbate neuronal/glutamate neurotoxicity. The paper supports Klk6-specific receptor-proximal signaling and functional injury outputs but does not justify generic substitution of other proteases or a terminal TF claim.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B288_PMID23647384_Klk6_PAR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000109' AND x.extraction_id='M24B-P2-R-RECOVERY-KLK6-PAR-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000179', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B288_PMID23647384_Klk6_PAR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000179' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000072', 'M24B-EVID-000108', 'M24B-P2-R-RECOVERY-S1P-S1PR2-SCI-000001', 'PMID:42448629; DOI:10.1111/bph.70581', '42448629', 'literature_xml', 'exact_identifier_match:PMID:42448629', 'linked_unresolved', 'B', 'L2', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:42448629; DOI:10.1111/bph.70581; https://pubmed.ncbi.nlm.nih.gov/42448629/', 'In female-rat T10 contusive SCI, S1P was reported to be released from crushed spinal cord, neuronal S1PR2 signaling was associated with pERK/ERK/ACSL4 lipid-peroxidation and ferroptosis, and systemic S1PR2 antagonist S118 reduced neuronal ferroptosis and improved locomotor recovery.', 'The authors conclude that S1P/S1PR2 activation contributes to neuronal ferroptosis through the pERK/ERK/ACSL4 pathway after contusive SCI and that S118 improves locomotor recovery by reducing lipid peroxidation and ferroptotic neuronal loss.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B288_PMID42448629_S1PR2_ferroptosis_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000108' AND x.extraction_id='M24B-P2-R-RECOVERY-S1P-S1PR2-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000077', 'M24B-EVID-000113', 'M24B-P2-R-000113', 'PMID:19754671; PMCID:PMC3829009; DOI:10.1111/j.1582-4934.2009.00899.x', '19754671', 'literature_xml', 'exact_identifier_match:PMID:19754671', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:19754671; PMCID:PMC3829009; DOI:10.1111/j.1582-4934.2009.00899.x; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID19754671_Resistin_TLR4_pubmed.xml', 'Recombinant resistin bound human myeloid/epithelial cells and co-precipitated with TLR4; TLR4 antibodies blocked resistin binding and cytokine production, and TLR4-transfected HEK293 cells but not TLR2/MD2-CD14 or null controls responded. The study supports direct resistin-TLR4 receptor evidence in human comparator systems, not SCI activity.', 'Retain resistin -> TLR4 direct binding/receptor-reconstitution evidence and the associated MyD88/MAPK/NF-kappaB inflammatory relay in human comparator systems. Do not infer SCI release, species-universal resistin biology, or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID19754671_Resistin_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000113' AND x.extraction_id='M24B-P2-R-000113');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000078', 'M24B-EVID-000114', 'M24B-P2-R-000114', 'PMID:19754671; PMCID:PMC3829009; DOI:10.1111/j.1582-4934.2009.00899.x', '19754671', 'literature_xml', 'exact_identifier_match:PMID:19754671', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:19754671; PMCID:PMC3829009; DOI:10.1111/j.1582-4934.2009.00899.x; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID19754671_Resistin_TLR4_pubmed.xml', 'Resistin stimulation of human immune/epithelial comparator systems required TLR4 and MyD88-associated signaling and engaged MAPK, NF-kappaB, and PI3K-related pathways. This pathway record is retained separately from the direct resistin-TLR4 binding/reconstitution observation and has no SCI model.', 'Retain the resistin -> TLR4 -> MyD88/MAPK/NF-kappaB/PI3K receptor-proximal comparator relay as a separate pathway layer. Do not infer traumatic-SCI signaling or a terminal TF endpoint from the comparator study.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID19754671_Resistin_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000114' AND x.extraction_id='M24B-P2-R-000114');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000078', 'M24B-EVID-PROMO-20260826-010', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID19754671_Resistin_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-PROMO-20260826-010' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000331', 'M22B-EVID-000299', 'M22B-P2-R-000261', 'PMCID:PMC4768137; PMID:26917360; DOI:10.1038/srep22193', '26917360', 'literature_xml', 'exact_identifier_match:PMID:26917360', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMCID:PMC4768137; PMID:26917360; DOI:10.1038/srep22193; https://pmc.ncbi.nlm.nih.gov/articles/PMC4768137/', 'In resistin-treated wild-type mice, TLR4-dependent p65/RelA binding to the hepatic Agt promoter increased by ChIP and was absent in Tlr4-null mice. Resistin also increased Agt expression, blood pressure and insulin resistance; perindopril blocked the downstream renin-angiotensin response. This source supports a direct resistin-TLR4-p65-Agt transcriptional chain, but it does not test S100A8/S100A9.', 'Promote the direct p65/RelA-to-Agt promoter edge in the resistin-TLR4 pathway in mouse liver, with Tlr4 dependence. Correct the queued composite wording: this PMID supports resistin, not S100A8/S100A9; do not infer S100A8/S100A9 occupancy or human receptor equivalence from this paper.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID26917360_Resistin_function_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000299' AND x.extraction_id='M22B-P2-R-000261');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000079', 'M24B-EVID-000115', 'M24B-P2-R-000115', 'PMID:26917360; DOI:10.1038/srep22193', '26917360', 'literature_xml', 'exact_identifier_match:PMID:26917360', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_context', 'PMID:26917360; DOI:10.1038/srep22193; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID26917360_Resistin_function_pubmed.xml', 'In wild-type mice, resistin induced hypertension and insulin resistance but not in Tlr4-null mice; resistin activated the renin-angiotensin system through a TLR4/p65/Agt pathway, supported by chromatin immunoprecipitation and angiotensin-converting-enzyme inhibitor perturbation. This is a non-SCI functional comparator output and is separate from direct binding and proximal pathway evidence.', 'Retain the resistin -> TLR4 -> p65/Agt -> renin-angiotensin-system hypertension/insulin-resistance output as non-SCI comparator evidence. Do not infer SCI function or a direct molecular edge from the phenotype.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID26917360_Resistin_function_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000115' AND x.extraction_id='M24B-P2-R-000115');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000620', 'M22B-EVID-005322', 'P2FALLBACK-22B-M22B-EVID-005322', 'PMID:28946139', '28946139', 'literature_xml', 'exact_identifier_match:PMID:28946139', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMID:28946139', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID28946139_ANGPTL2_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005322' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-005322');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000076', 'M24B-EVID-000112', 'M24B-P2-R-000112', 'PMID:28946139; DOI:10.1159/000480654', '28946139', 'literature_xml', 'exact_identifier_match:PMID:28946139', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_context_only', 'PMID:28946139; DOI:10.1159/000480654; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID28946139_ANGPTL2_TLR4_pubmed.xml', 'ANGPTL2 and TLR4 were elevated in streptozotocin-diabetic nephropathy rats and high-glucose podocytes; ANGPTL2 knockdown reduced inflammatory cytokines and extracellular-matrix accumulation, with TLR4 inhibition modifying the effect. The paper supports an ANGPTL2/TLR4-associated inflammatory comparator branch but does not establish direct ANGPTL2-TLR4 binding or SCI activity.', 'Retain ANGPTL2-associated TLR4 inflammatory pathway context in diabetic-nephropathy comparator systems. Do not promote a direct ligand-receptor edge, infer alpha5beta1 exclusion, or transfer the branch to SCI.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID28946139_ANGPTL2_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000112' AND x.extraction_id='M24B-P2-R-000112');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000123', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B289_PMID28946139_ANGPTL2_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000123' AND x.extraction_id='');
