INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000083', 'M24B-EVID-000119', 'M24B-P2-R-000119', 'PMID:24531000; PMCID:PMC3993933; DOI:10.1016/j.jsb.2014.02.001', '24531000', 'literature_xml', 'exact_identifier_match:PMID:24531000', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:24531000; PMCID:PMC3993933; DOI:10.1016/j.jsb.2014.02.001; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B290_PMID24531000_C1QTNF5_MFRP_pubmed.xml', 'C1QTNF5 immobilized on resin selectively enriched detergent-extracted membrane-bound MFRP, with structural/multimerization analyses supporting a C1QTNF5-MFRP membrane-association/adhesion complex in retinal comparator systems. No SCI model or downstream signaling assay was reported.', 'Retain C1QTNF5 -> MFRP membrane association/adhesion-complex evidence in the tested retinal comparator context. Do not infer SCI expression, downstream pathway, or generic complement-receptor behavior.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B290_PMID24531000_C1QTNF5_MFRP_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000119' AND x.extraction_id='M24B-P2-R-000119');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000081', 'M24B-EVID-000117', 'M24B-P2-R-000117', 'PMID:27133466; DOI:10.1016/j.neuron.2016.04.001', '27133466', 'literature_xml', 'exact_identifier_match:PMID:27133466', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:27133466; DOI:10.1016/j.neuron.2016.04.001; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B290_PMID27133466_C1QL2_NRXN3_pubmed.xml', 'Mouse C1ql2/C1ql3 proteins bound the amino-terminal domains of postsynaptic GluK2/GluK4 kainate receptor subunits and presynaptic neurexin-3 containing a specified sequence in vitro, organizing a transsynaptic receptor complex at hippocampal mossy-fiber/CA3 synapses. The exact splice/complex context must be preserved and no SCI model was tested.', 'Retain C1QL2 -> NRXN3 and GluK2/GluK4 transsynaptic complex binding with the specified synaptic/splice context. Do not infer SCI expression, lesion receiver state, or a generic C1q-family receptor assignment.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B290_PMID27133466_C1QL2_NRXN3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000117' AND x.extraction_id='M24B-P2-R-000117');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000082', 'M24B-EVID-000118', 'M24B-P2-R-000118', 'PMID:27133466; DOI:10.1016/j.neuron.2016.04.001', '27133466', 'literature_xml', 'exact_identifier_match:PMID:27133466', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_context', 'PMID:27133466; DOI:10.1016/j.neuron.2016.04.001; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B290_PMID27133466_C1QL2_NRXN3_pubmed.xml', 'C1ql2/C1ql3 double-null mice lost slow kainate-receptor-mediated components of CA3 synaptic responses; synaptic receptor recruitment and recurrent circuit activity were reduced in the tested hippocampal and epilepsy comparator contexts. This functional output is separate from direct protein-binding records and has no SCI receiver-state validation.', 'Retain the C1QL2/C1QL3 -> NRXN3/GluK2/GluK4 synaptic-organizer functional outputs as non-SCI comparator evidence. Do not infer a direct molecular edge from the physiology alone or transfer it to SCI.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B290_PMID27133466_C1QL2_NRXN3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000118' AND x.extraction_id='M24B-P2-R-000118');
