INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000084', 'M24B-EVID-000120', 'M24B-P2-R-000120', 'PMID:12682303; PMCID:PMC154321; DOI:10.1073/pnas.0531290100', '12682303', 'literature_xml', 'exact_identifier_match:PMID:12682303', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:12682303; PMCID:PMC154321; DOI:10.1073/pnas.0531290100; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B291_PMID12682303_Cripto_ALK4_pubmed.xml', 'Cripto directly interacted with ALK4 and assembled activin/type-II receptor complexes in mammalian reconstitution systems; Cripto inhibited activin-ALK4 association and signaling while facilitating Nodal-family signaling. Cripto is a coreceptor/complex organizer, not a standalone canonical ligand, and no SCI model was tested.', 'Retain Cripto-ALK4 and Cripto/type-II receptor complex assembly/modulation as a receptor-complex comparator record. Do not treat Cripto as the direct canonical ligand for ALK4 or transfer the branch to SCI.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B291_PMID12682303_Cripto_ALK4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000120' AND x.extraction_id='M24B-P2-R-000120');
