INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000086', 'M24B-EVID-000122', 'M24B-P2-R-000122', 'PMID:27084102; DOI:10.4049/jimmunol.1501908', '27084102', 'literature_xml', 'exact_identifier_match:PMID:27084102', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:27084102; DOI:10.4049/jimmunol.1501908; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B291_PMID27084102_CYTL1_CCR2_pubmed.xml', 'Human recombinant CYTL1 bound and internalized CCR2B in HEK293 reconstitution systems and drove CCR2B-dependent monocyte/macrophage chemotaxis; radioactive binding, pertussis-toxin sensitivity, ERK dependence, and Ccr2-null macrophage controls supported the receptor assignment. No SCI model was tested.', 'Retain CYTL1 -> CCR2B direct receptor and Gi/ERK chemotaxis relay as comparator evidence. Do not infer traumatic-SCI release, spinal receiver expression, or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B291_PMID27084102_CYTL1_CCR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000122' AND x.extraction_id='M24B-P2-R-000122');
