INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000087', 'M24B-EVID-000124', 'M24B-P2-R-RECOVERY-FLRT3-HOMOPHILIC-ADHESION-000001', 'PMID:25374360; PMCID:PMC4210639; DOI:10.1016/j.neuron.2014.10.008', '25374360', 'literature_xml', 'exact_identifier_match:PMID:25374360', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:25374360; PMCID:PMC4210639; DOI:10.1016/j.neuron.2014.10.008; https://pubmed.ncbi.nlm.nih.gov/25374360/; https://pmc.ncbi.nlm.nih.gov/articles/PMC4210639/', 'Structural and cell-aggregation experiments identified an FLRT3 homophilic adhesion interface; FLRT3 oligomerization and full-length cell aggregation supported the homophilic interaction, while cortical neuronal assays linked FLRT3 adhesion to neuronal distribution.', 'The authors conclude that FLRT3 homophilic interactions regulate cell adhesion and cortical neuron distribution. Preserve this as a direct adhesion/receptor-complex comparator, not as an SCI pathway or intracellular relay.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B292_PMID25374360_FLRT3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000124' AND x.extraction_id='M24B-P2-R-RECOVERY-FLRT3-HOMOPHILIC-ADHESION-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000088', 'M24B-EVID-000125', 'M24B-P2-R-RECOVERY-FLRT3-CORTICAL-DISTRIBUTION-000001', 'PMID:25374360; PMCID:PMC4210639; DOI:10.1016/j.neuron.2014.10.008', '25374360', 'literature_xml', 'exact_identifier_match:PMID:25374360', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_author_claim', 'PMID:25374360; PMCID:PMC4210639; DOI:10.1016/j.neuron.2014.10.008; https://pubmed.ncbi.nlm.nih.gov/25374360/; https://pmc.ncbi.nlm.nih.gov/articles/PMC4210639/', 'In mouse cortical neuron experiments, FLRT3 homophilic interactions were linked to neuronal distribution and cell-adhesion outputs through the same oligomerization/interface system described for the FLRT3 structural study.', 'The authors conclude that FLRT3 homophilic interactions contribute to cortical neuron distribution. Retain this as a non-SCI adhesion/function observation; no intracellular relay or terminal TF is established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B292_PMID25374360_FLRT3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000125' AND x.extraction_id='M24B-P2-R-RECOVERY-FLRT3-CORTICAL-DISTRIBUTION-000001');
