INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000089', 'M24B-EVID-000126', 'M24B-P2-R-000126', 'PMID:33852831; DOI:10.1016/j.immuni.2021.03.018', '33852831', 'literature_xml', 'exact_identifier_match:PMID:33852831', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:33852831; DOI:10.1016/j.immuni.2021.03.018; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B292_PMID33852831_IL17D_CD93_pubmed.xml', 'Protein-purification and receptor studies identify CD93, rather than canonical IL-17 receptors, as a receptor for IL-17D on mature ILC3s. Cd93 conditional loss and IL-17D perturbation support receptor-dependent ILC3 biology in mouse gut/infection comparator systems; no SCI model was tested.', 'Retain IL-17D -> CD93 direct receptor evidence and its ILC3 receptor-dependent comparator branch. Do not substitute canonical IL-17 receptors, infer SCI activity, or infer a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B292_PMID33852831_IL17D_CD93_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000126' AND x.extraction_id='M24B-P2-R-000126');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000090', 'M24B-EVID-000127', 'M24B-P2-R-000127', 'PMID:33852831; DOI:10.1016/j.immuni.2021.03.018', '33852831', 'literature_xml', 'exact_identifier_match:PMID:33852831', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_context', 'PMID:33852831; DOI:10.1016/j.immuni.2021.03.018; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B292_PMID33852831_IL17D_CD93_pubmed.xml', 'IL-17D deficiency and ILC3-specific Cd93 loss reduced IL-22 production and IL-22-dependent antimicrobial peptides and worsened colitis, bacterial infection, and experimental colon-cancer outcomes in mice. This downstream homeostatic function is separate from the direct IL-17D-CD93 receptor record and has no SCI validation.', 'Retain the IL-17D -> CD93 -> ILC3 IL-22/antimicrobial homeostatic output as non-SCI comparator function. Do not infer a direct molecular edge from the phenotype or transfer it to spinal injury.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B292_PMID33852831_IL17D_CD93_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000127' AND x.extraction_id='M24B-P2-R-000127');
