INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E002477', 'M22B-EVID-004057', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-004057' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000093', 'M24B-EVID-000130', 'M24B-P2-R-000130', 'PMID:29180446; DOI:10.1074/jbc.M117.805622', '29180446', 'literature_xml', 'exact_identifier_match:PMID:29180446', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:29180446; DOI:10.1074/jbc.M117.805622; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml', 'Quantitative SPR and direct-binding studies showed active IL-36alpha binds the extracellular IL-36R domain with micromolar affinity, does not detectably bind IL-1RAP alone, and induces strong IL-1RAP recruitment to form the IL-36R-IL-36alpha-IL-1RAP ternary complex. The active processed ligand form and receptor-complex assembly must remain explicit.', 'Retain active IL-36alpha -> IL-36R/IL-1RAP ternary receptor-complex activation, with IL-36R as the initial ligand-binding receptor and IL-1RAP as recruited accessory subunit. Do not infer SCI function or bind IL-36alpha directly to IL-1RAP in the absence of IL-36R.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000130' AND x.extraction_id='M24B-P2-R-000130');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000094', 'M24B-EVID-000131', 'M24B-P2-R-000131', 'PMID:29180446; DOI:10.1074/jbc.M117.805622', '29180446', 'literature_xml', 'exact_identifier_match:PMID:29180446', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:29180446; DOI:10.1074/jbc.M117.805622; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml', 'The quantitative IL-36 receptor study included active IL-36beta as an IL-36R agonist that participates in the shared IL-36R/IL-1RAP activation mechanism; active-form processing is required for agonist activity. Direct binding measurements in the paper are strongest for IL-36R ligand engagement and agonist-dependent accessory-subunit recruitment, not a free IL-36beta-IL-1RAP interaction.', 'Retain active IL-36beta -> IL-36R/IL-1RAP ternary receptor-complex activation, preserving IL-36R as the initial ligand-binding subunit and IL-1RAP as recruited accessory component. Do not infer SCI function or direct IL-36beta-IL-1RAP binding in isolation.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000131' AND x.extraction_id='M24B-P2-R-000131');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000095', 'M24B-EVID-000132', 'M24B-P2-R-000132', 'PMID:29180446; DOI:10.1074/jbc.M117.805622', '29180446', 'literature_xml', 'exact_identifier_match:PMID:29180446', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:29180446; DOI:10.1074/jbc.M117.805622; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml', 'The quantitative IL-36 receptor study included active IL-36gamma as an agonist that binds the IL-36R extracellular domain and participates in agonist-dependent recruitment of IL-1RAP to the ternary IL-36R-IL-36gamma-IL-1RAP complex. Active/processed ligand status is essential and no SCI model was tested.', 'Retain active IL-36gamma -> IL-36R/IL-1RAP ternary receptor-complex activation, with IL-36R as the initial ligand-binding subunit and IL-1RAP as recruited accessory component. Do not infer SCI function or direct IL-36gamma-IL-1RAP binding in isolation.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000132' AND x.extraction_id='M24B-P2-R-000132');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000096', 'M24B-EVID-000133', 'M24B-P2-R-000133', 'PMID:29180446; DOI:10.1074/jbc.M117.805622', '29180446', 'literature_xml', 'exact_identifier_match:PMID:29180446', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:29180446; DOI:10.1074/jbc.M117.805622; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml', 'Active IL-36 agonists formed IL-36R binary complexes that recruited IL-1RAP, defining a shared receptor-complex activation mechanism for the IL-36 pathway. The proximal complex record is retained separately from ligand-specific direct binding and downstream inflammatory output; no SCI receiver state was tested.', 'Retain the shared active IL-36 -> IL-36R -> IL-1RAP receptor-proximal ternary-complex relay. Preserve ligand-specific binding and active-form boundaries and do not infer a traumatic-SCI pathway or terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000133' AND x.extraction_id='M24B-P2-R-000133');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000097', 'M24B-EVID-000134', 'M24B-P2-R-000134', 'PMID:29180446; DOI:10.1074/jbc.M117.805622', '29180446', 'literature_xml', 'exact_identifier_match:PMID:29180446', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_context', 'PMID:29180446; DOI:10.1074/jbc.M117.805622; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml', 'Active IL-36 agonist stimulation and receptor-complex assembly were linked to inflammatory pathway output in the tested receptor/cell systems. The record is retained as a bounded IL-36 receptor-complex functional comparator and is not used to infer a direct molecular edge or SCI-specific receiver response.', 'Retain IL-36 receptor-complex-dependent inflammatory output as non-SCI comparator function. Do not infer a direct molecular edge from downstream inflammatory readouts, transfer it to SCI, or assign a terminal TF without direct evidence.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID29180446_IL36_receptor_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000134' AND x.extraction_id='M24B-P2-R-000134');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000091', 'M24B-EVID-000128', 'M24B-P2-R-000128', 'PMID:9820540; DOI:10.1128/MCB.18.12.6633', '9820540', 'literature_xml', 'exact_identifier_match:PMID:9820540', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:9820540; DOI:10.1128/MCB.18.12.6633; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID9820540_IL1RAP_pubmed.xml', 'IL-1 agonists bound type-I IL-1R on IL-1RAP-deficient cells but failed to activate NF-kappaB/AP-1 gene-expression signaling; IL-1RAP deficiency altered ligand affinity and abolished in-vivo IL-1 responses. The evidence supports an IL-1R/IL-1RAP receptor complex, not IL-1RAP as a standalone receptor.', 'Retain IL-1alpha -> IL-1R/IL-1RAP receptor-complex activation and NF-kappaB/AP-1 proximal signaling. Preserve IL-1RAP as an essential accessory/signaling component rather than a free ligand receptor; no SCI model was tested.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID9820540_IL1RAP_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000128' AND x.extraction_id='M24B-P2-R-000128');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000092', 'M24B-EVID-000129', 'M24B-P2-R-000129', 'PMID:9820540; DOI:10.1128/MCB.18.12.6633', '9820540', 'literature_xml', 'exact_identifier_match:PMID:9820540', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:9820540; DOI:10.1128/MCB.18.12.6633; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID9820540_IL1RAP_pubmed.xml', 'IL-1beta binding affinity was markedly reduced in IL-1RAP-deficient cells and IL-1 agonists failed to activate NF-kappaB/AP-1 signaling or in-vivo responses without the IL-1R/IL-1RAP complex. The record supports a processed/cognate IL-1beta receptor-complex branch, not a standalone IL-1RAP interaction.', 'Retain IL-1beta -> IL-1R/IL-1RAP receptor-complex activation and proximal NF-kappaB/AP-1 signaling. Preserve IL-1RAP as an accessory component and do not infer traumatic-SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B293_PMID9820540_IL1RAP_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000129' AND x.extraction_id='M24B-P2-R-000129');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000098', 'M24B-EVID-000135', 'M24B-P2-R-000135', 'PMID:31539874; DOI:10.1016/j.cmet.2019.08.001', '31539874', 'literature_xml', 'exact_identifier_match:PMID:31539874', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_context_only', 'PMID:31539874; DOI:10.1016/j.cmet.2019.08.001; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B294_PMID31539874_LEAP2_GHSR_pubmed.xml', 'Intracerebroventricular LEAP2 suppressed central ghrelin-specific Fos expression, food intake, blood-glucose elevation, and body-temperature effects in rats; the effects were absent for NPY or des-acyl ghrelin and were GHSR-specific in the tested comparator context. Pharmacologic antagonism does not establish purified LEAP2-GHSR binding and no SCI model was tested.', 'Retain LEAP2-dependent antagonism of GHSR-mediated central ghrelin functions as non-SCI comparator context. Do not promote a direct molecular binding edge, infer spinal activity, or assign a terminal TF from Fos alone.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B294_PMID31539874_LEAP2_GHSR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000135' AND x.extraction_id='M24B-P2-R-000135');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000099', 'M24B-EVID-000136', 'M24B-P2-R-000136', 'PMID:31539874; DOI:10.1016/j.cmet.2019.08.001', '31539874', 'literature_xml', 'exact_identifier_match:PMID:31539874', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_context', 'PMID:31539874; DOI:10.1016/j.cmet.2019.08.001; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B294_PMID31539874_LEAP2_GHSR_pubmed.xml', 'LEAP2 administration suppressed central ghrelin-specific Fos expression, food intake, blood-glucose elevation, and body-temperature effects in rat and mouse comparator models. These downstream outputs are separate from GHSR pharmacologic antagonism and do not establish a direct LEAP2-GHSR binding measurement or SCI function.', 'Retain LEAP2/GHSR-dependent central appetite and metabolic outputs as non-SCI comparator function. Do not infer a direct molecular edge, spinal receiver state, or terminal TF from Fos alone.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B294_PMID31539874_LEAP2_GHSR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000136' AND x.extraction_id='M24B-P2-R-000136');
