INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000100', 'M24B-EVID-000137', 'M24B-P2-R-000137', 'PMID:35799511', '35799511', 'literature_xml', 'exact_identifier_match:PMID:35799511', 'linked_unresolved', 'B', 'L2', 'validated_abstract_bounded', 'validated_context_only', 'PMID:35799511; https://pubmed.ncbi.nlm.nih.gov/35799511/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B295_PMID35799511_PCDHGC3_pubmed.xml', 'A review summarizes PCDHGC3 as a highly expressed brain microvascular endothelial molecule associated with vascular-barrier function and permeability regulation. The cited item is not a primary mechanistic experiment for a PCDHGC3 self-binding edge and does not by itself establish an intracellular relay or SCI-specific causal function.', 'Retain PCDHGC3 vascular-barrier association as review-level comparator context only. Do not promote a direct PCDHGC3 homophilic edge, infer SCI causality, or create a terminal TF claim without the cited primary study.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B295_PMID35799511_PCDHGC3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000137' AND x.extraction_id='M24B-P2-R-000137');
