INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000811', 'M22B-EVID-005517', 'M22B-P2-R-000861', 'PMID:17660747', '17660747', 'literature_xml', 'exact_identifier_match:PMID:17660747', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMID:17660747; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch067_pubmed_B024_pmids.xml', 'Primary source PMID:17660747 reports the tested receptor/proximal or functional observation at its model scope; no stronger terminal-TF edge is inferred.', 'The source supports a bounded receptor/pathway or functional association; no direct TF occupancy or terminal target locus was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B296_PMID17660747_S100B_RAGE_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005517' AND x.extraction_id='M22B-P2-R-000861');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000101', 'M24B-EVID-000143', 'M24B-P2-R-000143', 'PMID:17660747; PMID:21209080', NULL, 'literature_xml', 'exact_identifier_match:PMID:17660747', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:17660747; PMID:21209080; https://pubmed.ncbi.nlm.nih.gov/17660747/; https://pubmed.ncbi.nlm.nih.gov/21209080/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B296_PMID17660747_S100B_RAGE_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B296_PMID21209080_S100B_RAGE_neural_pubmed.xml', 'Purified multimeric human S100B bound the RAGE V-domain, with tetrameric/hexameric/octameric forms showing stronger binding than dimeric S100B and structural data supporting RAGE dimerization. A separate mouse microglial study showed high-concentration S100B/RAGE-dependent Src/Ras/PI3K/MEK-ERK, RhoA/ROCK, Rac1/JNK/AP-1, and Rac1/NF-kappaB pathways with CCL3/CCL5/CXCL12 chemokine output. Direct binding and downstream relay are retained as distinct evidence components; no SCI-specific receptor-causal model was tested.', 'Retain multimeric S100B -> RAGE direct molecular binding and the separately supported RAGE-dependent microglial Src/Ras/PI3K/ERK/NF-kappaB/AP-1/chemokine relay in comparator systems. Preserve oligomeric-state and concentration boundaries; do not infer traumatic-SCI causality or a terminal TF beyond the measured pathway nodes.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B296_PMID17660747_S100B_RAGE_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000143' AND x.extraction_id='M24B-P2-R-000143');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000101', 'M24B-EVID-000143', 'M24B-P2-R-000143', 'PMID:17660747; PMID:21209080', NULL, 'literature_xml', 'exact_identifier_match:PMID:21209080', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:17660747; PMID:21209080; https://pubmed.ncbi.nlm.nih.gov/17660747/; https://pubmed.ncbi.nlm.nih.gov/21209080/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B296_PMID17660747_S100B_RAGE_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B296_PMID21209080_S100B_RAGE_neural_pubmed.xml', 'Purified multimeric human S100B bound the RAGE V-domain, with tetrameric/hexameric/octameric forms showing stronger binding than dimeric S100B and structural data supporting RAGE dimerization. A separate mouse microglial study showed high-concentration S100B/RAGE-dependent Src/Ras/PI3K/MEK-ERK, RhoA/ROCK, Rac1/JNK/AP-1, and Rac1/NF-kappaB pathways with CCL3/CCL5/CXCL12 chemokine output. Direct binding and downstream relay are retained as distinct evidence components; no SCI-specific receptor-causal model was tested.', 'Retain multimeric S100B -> RAGE direct molecular binding and the separately supported RAGE-dependent microglial Src/Ras/PI3K/ERK/NF-kappaB/AP-1/chemokine relay in comparator systems. Preserve oligomeric-state and concentration boundaries; do not infer traumatic-SCI causality or a terminal TF beyond the measured pathway nodes.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B296_PMID21209080_S100B_RAGE_neural_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000143' AND x.extraction_id='M24B-P2-R-000143');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000104', 'M24B-EVID-000146', 'M24B-P2-R-000146', 'PMID:23858030', '23858030', 'literature_xml', 'exact_identifier_match:PMID:23858030', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:23858030; https://pubmed.ncbi.nlm.nih.gov/23858030/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID23858030_SAA3_TLR4_pubmed.xml', 'Synthetic SAA3(20–86) and SAA3(43–57) peptides bound purified TLR4/MD2 with measured micromolar affinities; SAA3(20–86) activated TLR4/MD2/MyD88-dependent p38, NF-kappaB, and Rho signaling and induced IL-6/TNF-alpha. The active peptide/processed context is explicit and no SCI model was tested.', 'Retain SAA3(20–86)/(43–57) -> MD2/TLR4 -> MyD88/p38/NF-kappaB/Rho inflammatory relay. Preserve the active peptide boundary and do not substitute full-length SAA3 or infer SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID23858030_SAA3_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000146' AND x.extraction_id='M24B-P2-R-000146');
