INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004783', 'M20B-EVID-004783-P2-FUNC', 'M20B-P2-R-004783-R248B', 'PMID:12393391; DOI:10.1182/blood-2002-05-1431; PMID:25154907; PMCID:PMC2745437', '12393391', 'literature_xml', 'exact_identifier_match:PMID:25154907', 'candidate_requires_review', 'B', 'L1', 'validated_primary_abstract', 'validated_receptor_dependent_function', 'PMID:12393391; DOI:10.1182/blood-2002-05-1431; PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_SAA1_SAA2_primary_records.xml', 'SAA stimulation of human neutrophils induced IL-8 through Gi-sensitive FPRL1/FPR2-associated signaling, intracellular Ca2+, ERK1/2, p38, and NF-kB; the isoform comparison also measured chemotaxis and ERK outputs.', 'Retain FPR2/FPRL1-associated IL-8, chemotaxis, Ca2+, ERK/p38, and NF-kB outputs as downstream evidence; terminal TF identity is not established beyond NF-kB reporter activation.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID25154907_SAA1_TLR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004783-P2-FUNC' AND x.extraction_id='M20B-P2-R-004783-R248B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004783', 'M20B-EVID-004783-P2-FUNC-FT', 'M20B-P2-R-004783-FT-FUNC', 'PMID:25154907; PMCID:PMC4252704; DOI:10.1016/j.imbio.2014.08.002; PMID:12393391; DOI:10.1182/blood-2002-05-1431', '25154907', 'literature_xml', 'exact_identifier_match:PMID:25154907', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_full_text', 'validated_primary_full_text_isoform_FPR2_functional_output', 'PMID:25154907; PMCID:PMC4252704; DOI:10.1016/j.imbio.2014.08.002; https://pmc.ncbi.nlm.nih.gov/articles/PMC4252704/; PMID:12393391; DOI:10.1182/blood-2002-05-1431', 'Human SAA1 isoforms induced FPR2-dependent chemotaxis and calcium responses, and SAA1.1/SAA2.2 produced stronger ERK phosphorylation than SAA1.3/SAA1.5; generic SAA/FPRL1 studies additionally reported IL-8 and MAPK/NF-kB outputs in human neutrophil systems.', 'Full-text primary evidence supports conditional human SAA1/FPR2 chemotactic and signaling outputs; terminal TF identity and mouse SCI-cell function remain unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID25154907_SAA1_TLR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004783-P2-FUNC-FT' AND x.extraction_id='M20B-P2-R-004783-FT-FUNC');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004783', 'M20B-EVID-004783-P2-RELAY', 'M20B-P2-R-004783-R248A', 'PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002', '25154907', 'literature_xml', 'exact_identifier_match:PMID:25154907', 'candidate_requires_review', 'B', 'L1', 'validated_primary_abstract', 'validated_isoform_receptor_activation', 'PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_SAA1_SAA2_isoform_P25154907.xml', 'Recombinant human SAA1.1, SAA1.3, SAA1.5, and SAA2.2 activated FPR2 in calcium-mobilization and chemotaxis assays; SAA1.1 and SAA2.2 produced stronger ERK phosphorylation than SAA1.3 and SAA1.5.', 'Record isoform-specific FPR2 activation for human SAA1 variants, with SAA1.1 and SAA2.2 as the strongest tested activators; this is receptor activation, not purified binary binding.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID25154907_SAA1_TLR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004783-P2-RELAY' AND x.extraction_id='M20B-P2-R-004783-R248A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004783', 'M20B-EVID-004783-P2-RELAY-FT', 'M20B-P2-R-004783-FT-RELAY', 'PMID:25154907; PMCID:PMC4252704; DOI:10.1016/j.imbio.2014.08.002', '25154907', 'literature_xml', 'exact_identifier_match:PMID:25154907', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_full_text', 'validated_primary_full_text_isoform_FPR2_activation', 'PMID:25154907; PMCID:PMC4252704; DOI:10.1016/j.imbio.2014.08.002; https://pmc.ncbi.nlm.nih.gov/articles/PMC4252704/', 'Purified human SAA1.1, SAA1.3, SAA1.5, and SAA2.2 activated human FPR2 in transfected RBL-2H3 cells; SAA1.1 and SAA2.2 were the strongest isoforms in calcium mobilization, chemotaxis, and ERK phosphorylation, whereas SAA1.3 and SAA1.5 were weaker at FPR2.', 'Full-text primary evidence supports isoform-specific human SAA1 activation of FPR2, with SAA1.1 more efficacious than SAA1.3 and SAA1.5 in the tested receptor-proximal assays; this is activation evidence, not purified binary affinity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID25154907_SAA1_TLR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004783-P2-RELAY-FT' AND x.extraction_id='M20B-P2-R-004783-FT-RELAY');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004790', 'M20B-EVID-004790-P2-FUNC', 'M20B-P2-R-004790-R248B', 'PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002', '25154907', 'literature_xml', 'exact_identifier_match:PMID:25154907', 'candidate_requires_review', 'B', 'L1', 'validated_primary_abstract', 'validated_isoform_functional_output', 'PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_SAA1_SAA2_isoform_P25154907.xml', 'SAA2.2-dependent FPR2 activation produced calcium, chemotaxis, and ERK outputs in the isoform comparison; no terminal TF was assayed.', 'Retain SAA2.2/FPR2-associated calcium, chemotaxis, and ERK outputs as downstream evidence; terminal TF remains unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID25154907_SAA1_TLR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004790-P2-FUNC' AND x.extraction_id='M20B-P2-R-004790-R248B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004790', 'M20B-EVID-004790-P2-RELAY', 'M20B-P2-R-004790-R248A', 'PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002', '25154907', 'literature_xml', 'exact_identifier_match:PMID:25154907', 'candidate_requires_review', 'B', 'L1', 'validated_primary_abstract', 'validated_isoform_receptor_activation', 'PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_SAA1_SAA2_isoform_P25154907.xml', 'Recombinant human SAA2.2 activated FPR2 in calcium-mobilization and chemotaxis assays and produced ERK phosphorylation comparable to SAA1.1.', 'Retain exact human SAA2.2-to-FPR2 receptor activation as a paralog-specific comparator for the murine Saa2 edge; direct binding was not measured.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID25154907_SAA1_TLR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004790-P2-RELAY' AND x.extraction_id='M20B-P2-R-004790-R248A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E004794', 'M20B-EVID-004794-P2-FUNC', 'M20B-P2-R-004794-R248B', 'PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002', '25154907', 'literature_xml', 'exact_identifier_match:PMID:25154907', 'candidate_requires_review', 'B', 'L1', 'validated_primary_abstract', 'validated_pathway_functional_output', 'PMID:25154907; PMCID:PMC2745437; DOI:10.1016/j.imbio.2014.08.002; data/raw/evidence/module20_24_supervised_cli_phase2/retry_A20B_SAA1_SAA2_isoform_P25154907.xml', 'SAA2.2 induced TLR2-reporter NF-kB activity and was compared with SAA1 isoforms; the study did not establish a terminal transcription factor beyond the NF-kB reporter readout.', 'Retain SAA2.2/TLR2-associated NF-kB reporter output, with terminal TF identity unresolved.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID25154907_SAA1_TLR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-004794-P2-FUNC' AND x.extraction_id='M20B-P2-R-004794-R248B');
