INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000102', 'M24B-EVID-000144', 'M24B-P2-R-000144', 'PMID:25154907', '25154907', 'literature_xml', 'exact_identifier_match:PMID:25154907', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMCID:PMC4252704; PMID:25154907; DOI:10.1016/j.imbio.2014.08.002; https://pmc.ncbi.nlm.nih.gov/articles/PMC4252704/', 'SAA1 isoforms 1.1, 1.3, 1.5 and SAA2.2 were compared in FPR2 calcium/chemotaxis/ERK assays and in TLR2-expressing HeLa NF-kappaB reporter and ERK/p38 phosphorylation assays; isoform-dependent cytokine outputs were measured in mouse Tlr4lps-del BMDMs. This supports a TLR2-proximal/pathway record, not purified SAA1-TLR2 binding.', 'Promote SAA1 isoform-dependent TLR2-proximal NF-kappaB/MAPK signaling in the tested human/mouse comparator systems. Keep FPR2 activity as a separate branch; do not infer purified binary SAA1-TLR2 binding or SCI relevance.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID25154907_SAA1_TLR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000144' AND x.extraction_id='M24B-P2-R-000144');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000105', 'M24B-EVID-000147', 'M24B-P2-R-RECOVERY-TNC-FBG-TLR4-000001', 'PMID:29150600; PMCID:PMC5693923; DOI:10.1038/s41467-017-01718-7', '29150600', 'literature_xml', 'exact_identifier_match:PMID:29150600', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:29150600; PMCID:PMC5693923; DOI:10.1038/s41467-017-01718-7; https://pubmed.ncbi.nlm.nih.gov/29150600/; https://pmc.ncbi.nlm.nih.gov/articles/PMC5693923/', 'Recombinant fibrinogen-like globes from tenascin-C, tenascin-R, and tenascin-W activated NF-kB reporter cells and cytokine production in human macrophages; plate-binding experiments showed TLR4 binding to FBG-C, and mutational mapping identified three FBG-C regions contributing to TLR4 activation.', 'The authors conclude that a conserved inflammatory epitope within the tenascin FBG domain directly and cooperatively interacts with TLR4 and can mark endogenous proteins for TLR-mediated sterile inflammation. Apply this only to the tested FBG-C domain and comparator systems; do not transfer it to unprocessed full-length TNC in SCI without injury-context evidence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID29150600_TNC_FBG_C_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000147' AND x.extraction_id='M24B-P2-R-RECOVERY-TNC-FBG-TLR4-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000103', 'M24B-EVID-000145', 'M24B-P2-R-000145', 'PMID:35247611', '35247611', 'literature_xml', 'exact_identifier_match:PMID:35247611', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:35247611; https://pubmed.ncbi.nlm.nih.gov/35247611/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID35247611_SAA1_TLR4_pubmed.xml', 'Mouse and human NAFLD studies showed SAA1 directly bound the TLR4/MD2 complex, induced TLR4 internalization and NF-kappaB signaling, and drove IL-6/CCL2 and feed-forward SAA1 production; Tlr4 loss alleviated the phenotype. This is a metabolic comparator, not SCI.', 'Retain SAA1 -> TLR4/MD2 direct molecular and NF-kappaB inflammatory comparator evidence. Preserve the MD2 receptor-complex node and do not infer traumatic-SCI release or function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B297_PMID35247611_SAA1_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000145' AND x.extraction_id='M24B-P2-R-000145');
