INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000111', 'M24B-EVID-000153', 'M24B-P2-R-000153', 'PMID:10975800', '10975800', 'literature_xml', 'exact_identifier_match:PMID:10975800', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:10975800; https://pubmed.ncbi.nlm.nih.gov/10975800/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B299_PMID10975800_CCL28_CCR3_pubmed.xml', 'Mucosae-associated epithelial chemokine CCL28/MEC supported CCR10-dependent lymphoid-cell migration and also CCR3-dependent eosinophil migration in transfected/recombinant comparator systems. The study distinguishes CCL28 from CCL27 and has no SCI context.', 'Retain CCL28 -> CCR10 and CCL28 -> CCR3 receptor-use/chemotaxis branches as distinct mucosal/eosinophil comparator records. Do not infer SCI expression or collapse the two receptor contexts.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B299_PMID10975800_CCL28_CCR3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000153' AND x.extraction_id='M24B-P2-R-000153');
