INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000110', 'M24B-EVID-000152', 'M24B-P2-R-000152', 'PMID:11821900', '11821900', 'literature_xml', 'exact_identifier_match:PMID:11821900', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:11821900; https://pubmed.ncbi.nlm.nih.gov/11821900/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B299_PMID11821900_CCL27_CCR10_pubmed.xml', 'CCL27/CTACK bound extracellular matrix and supported CCR10-dependent chemotaxis/adhesion of skin-homing T cells; CCL27 neutralization impaired lymphocyte recruitment and skin inflammation in human and mouse comparator models. No SCI model was tested.', 'Retain CCL27 -> CCR10 skin-homing chemotaxis/recruitment evidence in the tested comparator context. Do not infer spinal release, SCI receiver expression, or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B299_PMID11821900_CCL27_CCR10_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000152' AND x.extraction_id='M24B-P2-R-000152');
