INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000113', 'M24B-EVID-000155', 'M24B-P2-R-000155', 'PMID:12055240', '12055240', 'literature_xml', 'exact_identifier_match:PMID:12055240', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:12055240; https://pubmed.ncbi.nlm.nih.gov/12055240/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B299_PMID12055240_CCL5_CCR1_pubmed.xml', 'CCL5/RANTES bound CCR1 on human memory and naive CD4 T cells, with CCR1 blockade reducing ligand-induced chemotaxis and protein-tyrosine-kinase signaling in memory T cells; naive-cell hyporesponsiveness reflected downstream signaling regulation and low CCR5 expression. No SCI model was tested.', 'Retain CCL5 -> CCR1 binding and memory-T-cell chemotaxis/proximal signaling comparator evidence. Preserve cell-state differences and do not infer traumatic-SCI activity or a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B299_PMID12055240_CCL5_CCR1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000155' AND x.extraction_id='M24B-P2-R-000155');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000112', 'M24B-EVID-000154', 'M24B-P2-R-000154', 'PMID:7679328', '7679328', 'literature_xml', 'exact_identifier_match:PMID:7679328', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:7679328; https://pubmed.ncbi.nlm.nih.gov/7679328/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B299_PMID7679328_CCL3_CCR1_pubmed.xml', 'Cloned human CCR1/C-C CKR-1 bound CCL3/MIP-1alpha and other CC chemokines and transmitted intracellular calcium signals in recombinant receptor systems. Ligand affinity and signaling potency varied by chemokine; no SCI model was tested.', 'Retain CCL3 -> CCR1 direct binding and calcium-signaling comparator evidence. Do not infer traumatic-SCI release, receptor activity, or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B299_PMID7679328_CCL3_CCR1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000154' AND x.extraction_id='M24B-P2-R-000154');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000115', 'M24B-EVID-000157', 'M24B-P2-R-000157', 'PMID:16002730; PMID:30567735', NULL, 'literature_xml', 'exact_identifier_match:PMID:16002730', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:16002730; PMID:30567735; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID16002730_CCL7_CCR_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID30567735_CCL7_CCR1_pubmed.xml', 'CCL7/MCP-3 retained affinity and signaling activity at CCR1 in human recombinant/leukocyte comparator systems; a three-step binding/activation study showed the chemokine N-terminal region contributes to CCR1 affinity and receptor activation. No SCI model was tested.', 'Retain CCL7/MCP-3 -> CCR1 direct receptor affinity and activation comparator evidence, preserving the chemokine two-site/three-step binding model. Do not infer traumatic-SCI release or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID16002730_CCL7_CCR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000157' AND x.extraction_id='M24B-P2-R-000157');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000116', 'M24B-EVID-000158', 'M24B-P2-R-000158', 'PMID:16002730', '16002730', 'literature_xml', 'exact_identifier_match:PMID:16002730', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:16002730; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID16002730_CCL7_CCR_pubmed.xml', 'Wild-type and non-glycosaminoglycan-binding mutant CCL7/MCP-3 retained affinity and calcium signaling at CCR2B in recombinant/leukocyte comparator systems; altered glycosaminoglycan binding changed endothelial crossing and in-vivo leukocyte recruitment without changing receptor affinity. No SCI model was tested.', 'Retain CCL7/MCP-3 -> CCR2B direct receptor affinity/signaling comparator evidence and keep GAG-binding-dependent vectorial recruitment as a separate functional constraint. Do not infer SCI release or directness from the in-vivo recruitment phenotype alone.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID16002730_CCL7_CCR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000158' AND x.extraction_id='M24B-P2-R-000158');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000117', 'M24B-EVID-000159', 'M24B-P2-R-000159', 'PMID:16002730; PMID:36998150', '36998150', 'literature_xml', 'exact_identifier_match:PMID:16002730', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:16002730; PMID:36998150; https://pubmed.ncbi.nlm.nih.gov/36998150/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID16002730_CCL7_CCR_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID36998150_CCL7_CCR3_pubmed.xml', 'CCL7/MCP-3 showed CCR3 affinity/signaling in comparator systems, while a mouse trigeminal neuropathic-pain study reported CCL7 activation of ERK in trigeminal-ganglion neurons through CCR2/CCR3, increasing neuronal excitability and maintaining pain. This is not traumatic-SCI evidence and does not establish purified CCL7-CCR3 binding in the pain model.', 'Retain CCL7 -> CCR3 comparator receptor activity and the separate CCL7 -> CCR2/CCR3 -> ERK trigeminal pain relay. Do not transfer the trigeminal pathway to spinal cord injury or infer a direct molecular edge from ERK/pain outcomes alone.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID16002730_CCL7_CCR_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000159' AND x.extraction_id='M24B-P2-R-000159');
