INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000117', 'M24B-EVID-000159', 'M24B-P2-R-000159', 'PMID:16002730; PMID:36998150', '36998150', 'literature_xml', 'exact_identifier_match:PMID:36998150', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:16002730; PMID:36998150; https://pubmed.ncbi.nlm.nih.gov/36998150/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID16002730_CCL7_CCR_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID36998150_CCL7_CCR3_pubmed.xml', 'CCL7/MCP-3 showed CCR3 affinity/signaling in comparator systems, while a mouse trigeminal neuropathic-pain study reported CCL7 activation of ERK in trigeminal-ganglion neurons through CCR2/CCR3, increasing neuronal excitability and maintaining pain. This is not traumatic-SCI evidence and does not establish purified CCL7-CCR3 binding in the pain model.', 'Retain CCL7 -> CCR3 comparator receptor activity and the separate CCL7 -> CCR2/CCR3 -> ERK trigeminal pain relay. Do not transfer the trigeminal pathway to spinal cord injury or infer a direct molecular edge from ERK/pain outcomes alone.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID36998150_CCL7_CCR3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000159' AND x.extraction_id='M24B-P2-R-000159');
