INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000114', 'M24B-EVID-000156', 'M24B-P2-R-000156', 'PMID:9005985; PMID:9289016', '9289016', 'literature_xml', 'exact_identifier_match:PMID:9289016', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:9005985; PMID:9289016; https://pubmed.ncbi.nlm.nih.gov/9289016/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B298_PMID9005985_CCL11_CCR3_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID9289016_CCL5_CCR3_pubmed.xml', 'CCL5/RANTES activated CCR3-dependent eosinophil responses in comparator systems, and alanine-scanning studies identified distinct but overlapping RANTES epitopes for CCR1, CCR3, and CCR5 binding and signal activation. The exact receptor-epitope and cell-context boundaries are retained; no SCI model was tested.', 'Retain CCL5/RANTES -> CCR3 direct receptor and eosinophil comparator evidence, with distinct overlapping CCR1/CCR3/CCR5 interaction epitopes. Do not infer SCI release or collapse receptor-specific binding sites.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B300_PMID9289016_CCL5_CCR3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000156' AND x.extraction_id='M24B-P2-R-000156');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000120', 'M24B-EVID-000162', 'M24B-P2-R-000162', 'PMID:21241660', '21241660', 'literature_xml', 'exact_identifier_match:PMID:21241660', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:21241660; https://pubmed.ncbi.nlm.nih.gov/21241660/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B301_PMID21241660_PANP_PILRA_pubmed.xml', 'Neural protein PANP/PIANP bound PILRalpha-Ig in a glycosylation-dependent manner and activated PILRalpha reporter cells; specific O-glycan structures were required for recognition. The record is a non-SCI neural/immune comparator and does not establish a spinal injury pathway.', 'Retain PANP/PIANP -> PILRalpha glycosylation-dependent direct receptor evidence. Preserve the PANP/PIANP nomenclature and O-glycan requirement; do not infer SCI release or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B301_PMID21241660_PANP_PILRA_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000162' AND x.extraction_id='M24B-P2-R-000162');
