INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000025', 'M24B-EVID-000034', 'M24B-P2-R-000034', 'PMID:9115216; DOI:10.1074/jbc.272.18.11682', '9115216', 'literature_xml', 'exact_identifier_match:PMID:9115216', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_context_only', 'PMID:9115216; DOI:10.1074/jbc.272.8.11682; https://pubmed.ncbi.nlm.nih.gov/9115216/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B272_chemokine_relay_pubmed.xml', 'The primary human chemokine study used radioiodinated MCP-2/CCL8 and receptor-transfected cells: 125I-MCP-2 bound CCR1- and CCR2B-transfected cells, and both receptor systems migrated in response to MCP-2. This is direct comparator evidence for CCL8 receptor usage, not mouse SCI evidence.', 'Retain direct human comparator support for CCL8/MCP-2 binding and functional activation of CCR2B (and CCR1). Do not transfer the exact edge to mouse SCI or merge it with the queued SCI-specific record without species/model validation.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B301_PMID9115216_CCL8_CCR1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000034' AND x.extraction_id='M24B-P2-R-000034');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000025', 'M24B-EVID-000034', 'M24B-P2-R-000934', 'PMID:9115216', '9115216', 'literature_xml', 'exact_identifier_match:PMID:9115216', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMID:9115216; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Primary SCI paper retrieved; exact observation retained at source scope.', 'SCI phenotype is supported at the reported model scope; no direct terminal-TF edge was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B301_PMID9115216_CCL8_CCR1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000034' AND x.extraction_id='M24B-P2-R-000934');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000118', 'M24B-EVID-000160', 'M24B-P2-R-000160', 'PMID:9115216', '9115216', 'literature_xml', 'exact_identifier_match:PMID:9115216', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:9115216; https://pubmed.ncbi.nlm.nih.gov/9115216/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B301_PMID9115216_CCL8_CCR1_pubmed.xml', 'CCL8/MCP-2 bound CCR1 and CCR2B in human receptor-transfected cells and supported receptor-dependent migration in addition to monocyte binding. The dual-receptor comparator record is non-SCI and does not establish a spinal release or receiver state.', 'Retain CCL8/MCP-2 -> CCR1 and CCL8/MCP-2 -> CCR2B direct receptor/chemotaxis comparator branches. Do not collapse the dual-receptor assignment or infer traumatic-SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B301_PMID9115216_CCL8_CCR1_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000160' AND x.extraction_id='M24B-P2-R-000160');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000489', 'M22B-EVID-005323', 'P2FALLBACK-22B-M22B-EVID-005323', 'PMCID:PMC4755027', '26885373', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4755027', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMCID:PMC4755027', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMC4755027_ANXA2_TLR2_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005323' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-005323');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000123', 'M24B-EVID-000165', 'M24B-P2-R-000165', 'PMCID:PMC4755027', '26885373', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4755027', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_direct_molecular_support', 'PMCID:PMC4755027; https://pmc.ncbi.nlm.nih.gov/articles/PMC4755027/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMC4755027_ANXA2_TLR2_bioc.json', 'Purified monomeric ANXA2 and its N-terminal 15-amino-acid peptide bound TLR2 and activated TLR2 reporter and dendritic-cell responses; the active monomeric ligand was enriched under hypoxia and induced DC maturation, antigen cross-presentation, IL-12p70, TNF-alpha, and IFN-gamma. Preserve monomeric ANXA2/peptide specificity and do not transfer ANXA2/S100A10 tetramer or SCI claims.', 'Retain monomeric ANXA2 -> TLR2 direct binding and dendritic-cell activation in the tested comparator system. Preserve the N-terminal peptide and monomeric-state boundary; do not infer ANXA2/S100A10 tetramer signaling, SCI release, or a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMC4755027_ANXA2_TLR2_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000165' AND x.extraction_id='M24B-P2-R-000165');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000253', 'M22B-EVID-003355', 'M22B-P2-R-000583', 'PMCID:PMC5029092', '22087031', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC5029092', 'candidate_requires_review', NULL, 'L1', 'validated_observation', 'Decorin; TLR2; receptor/adaptor perturbation', 'PMCID:PMC5029092; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMC5029092_decorin_TLR2_bioc.json', 'Results; decorin-TLR2 receptor engagement and inflammatory signaling', 'Decorin-TLR2 inflammatory signaling is supported; no single terminal TF target was directly demonstrated.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMC5029092_decorin_TLR2_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003355' AND x.extraction_id='M22B-P2-R-000583');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000530', 'M22B-EVID-005383', 'P2FALLBACK-22B-M22B-EVID-005383', 'PMCID:PMC5029092', '22087031', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC5029092', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'PMCID:PMC5029092', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMC5029092_decorin_TLR2_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005383' AND x.extraction_id='P2FALLBACK-22B-M22B-EVID-005383');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000125', 'M24B-EVID-000167', 'M24B-P2-R-RECOVERY-DECORIN-TLR2-MAPK-NFKB-000001', 'PMCID:PMC5029092; PMID:22087031; DOI:10.1126/scisignal.2001868', '22087031', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC5029092', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC5029092; PMID:22087031; DOI:10.1126/scisignal.2001868; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMC5029092_decorin_TLR2_bioc.json', 'Soluble intact human decorin bound recombinant human TLR2 by microscale thermophoresis with Kd 59 ± 10 nM and was recovered with TLR2 from TLR2-expressing cells. In mouse macrophages, decorin-induced TNF-alpha and IL-12p70 release and p44/p42 and p38 MAPK activation were TLR2/TLR4 dependent; in HEK-Blue reporter cells, decorin activated NF-kB through TLR2 and TLR4. The study also linked decorin/TLR signaling to PDCD4, miR-21, and IL-10 regulation, but did not establish an SCI receiver or a direct TF-target edge.', 'The authors conclude that soluble decorin acts as an endogenous TLR2/TLR4 ligand and drives a receptor-proximal MAPK/NF-kB inflammatory program that increases PDCD4 and alters miR-21/IL-10 regulation. For the registered decorin-TLR2 branch, direct binding and TLR2-dependent signaling are supported; TLR4, adaptor/co-receptor context, and downstream PDCD4/miR-21/IL-10 effects remain distinct branches rather than a single direct molecular edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMC5029092_decorin_TLR2_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000167' AND x.extraction_id='M24B-P2-R-RECOVERY-DECORIN-TLR2-MAPK-NFKB-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000122', 'M24B-EVID-000164', 'M24B-P2-R-RECOVERY-WNT5A-ROR2-VANGL2-000001', 'PMID:21316585; PMCID:PMC3062198; DOI:10.1016/j.devcel.2011.01.001', '21316585', 'literature_xml', 'exact_identifier_match:PMID:21316585', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:21316585; PMCID:PMC3062198; DOI:10.1016/j.devcel.2011.01.001; https://pubmed.ncbi.nlm.nih.gov/21316585/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3062198/', 'Wnt signaling gradients induced a receptor complex containing ROR2 and Vangl2; Wnt dose-dependently induced Vangl2 phosphorylation, and Vangl2 activity depended on phosphorylation. In limb-bud chondrocytes, Wnt5a signaling through ROR2-associated PCP machinery regulated planar polarity and limb elongation.', 'The authors conclude that Wnt signaling gradients act through ROR2-associated Vangl2 to establish planar cell polarity by inducing dose-dependent Vangl2 phosphorylation. Preserve Wnt5a-ROR2 receptor signaling and ROR2-Vangl2 complex/pathway evidence as distinct from any direct binary Wnt5a-Vangl2 interaction.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMID21316585_WNT5A_ROR2_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000164' AND x.extraction_id='M24B-P2-R-RECOVERY-WNT5A-ROR2-VANGL2-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000124', 'M24B-EVID-000166', 'M24B-P2-R-RECOVERY-CIRP-TLR4-MD2-000001', 'PMID:24097189; PMCID:PMC3826915; DOI:10.1038/nm.3368', '24097189', 'literature_xml', 'exact_identifier_match:PMID:24097189', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:24097189; PMCID:PMC3826915; DOI:10.1038/nm.3368; https://pubmed.ncbi.nlm.nih.gov/24097189/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3826915/', 'Recombinant human CIRP bound purified TLR4, MD2, and the TLR4/MD2 complex by surface plasmon resonance, with apparent Kd values of approximately 0.617, 0.302, and 0.239 micromolar respectively; CIRP residues 101-125, including 106-125, bound MD2. Recombinant CIRP induced macrophage inflammatory outputs and CIRP neutralization reduced hemorrhage/sepsis inflammation.', 'The authors conclude that extracellular CIRP is a DAMP whose inflammatory activity is mediated through TLR4/MD2, with CIRP directly binding TLR4 and MD2 and residues 106-125 contributing to MD2 binding. Preserve the direct molecular and receptor-proximal evidence separately from the downstream NF-kB/cytokine and shock phenotypes.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B302_PMID24097189_CIRP_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000166' AND x.extraction_id='M24B-P2-R-RECOVERY-CIRP-TLR4-MD2-000001');
