INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000128', 'M24B-EVID-000170', 'M24B-P2-R-000170', 'PMID:22842346; PMCID:PMC3622453', '22842346', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3622453', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMID:22842346; PMCID:PMC3622453; https://pmc.ncbi.nlm.nih.gov/articles/PMC3622453/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMC3622453_HMGB1_TIM3_bioc.json', 'Tumor-associated dendritic-cell TIM-3 interacted with the alarmin HMGB1 and interfered with nucleic-acid recruitment into DC endosomes, suppressing TLR/cytosolic-sensor innate responses in mouse and human tumor comparator systems. HMGB1 redox/form and endosomal context are essential; no SCI model was tested.', 'Retain HMGB1 -> TIM-3 receptor-proximal suppression of nucleic-acid/TLR sensing in tumor DC comparators. Do not substitute Galectin-9/TIM-3, infer SCI function, or assign a terminal TF from the suppression phenotype.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMC3622453_HMGB1_TIM3_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000170' AND x.extraction_id='M24B-P2-R-000170');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000127', 'M24B-EVID-000169', 'M24B-P2-R-000169', 'PMCID:PMC5506452', '28380665', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC5506452', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMCID:PMC5506452; https://pmc.ncbi.nlm.nih.gov/articles/PMC5506452/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMC5506452_ficolinA_TLR4_fulltext.xml', 'Ficolin-A/ficolin-2 promoted macrophage polarization and inflammatory responses through a TLR4-MyD88-MAPK/NF-kappaB-associated pathway in mouse colitis models and macrophage systems. Co-IP/knockout/adoptive-transfer evidence supports pathway association, but direct binary TLR4 binding remained unresolved and LPS/complex context must be retained.', 'Retain ficolin-A -> TLR4 -> MyD88/MAPK/NF-kappaB macrophage-polarization pathway in the tested comparator context. Do not promote direct ficolin-A-TLR4 binding or infer SCI activity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMC5506452_ficolinA_TLR4_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000169' AND x.extraction_id='M24B-P2-R-000169');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000127', 'M24B-EVID-000169', 'M24B-P2-R-000169', 'PMCID:PMC5506452', '28380665', 'full_text_xml', 'exact_identifier_match:PMCID:PMC5506452', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMCID:PMC5506452; https://pmc.ncbi.nlm.nih.gov/articles/PMC5506452/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMC5506452_ficolinA_TLR4_fulltext.xml', 'Ficolin-A/ficolin-2 promoted macrophage polarization and inflammatory responses through a TLR4-MyD88-MAPK/NF-kappaB-associated pathway in mouse colitis models and macrophage systems. Co-IP/knockout/adoptive-transfer evidence supports pathway association, but direct binary TLR4 binding remained unresolved and LPS/complex context must be retained.', 'Retain ficolin-A -> TLR4 -> MyD88/MAPK/NF-kappaB macrophage-polarization pathway in the tested comparator context. Do not promote direct ficolin-A-TLR4 binding or infer SCI activity.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMC5506452_ficolinA_TLR4_fulltext.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000169' AND x.extraction_id='M24B-P2-R-000169');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000126', 'M24B-EVID-000168', 'M24B-P2-R-RECOVERY-BDEF2-TLR4-000001', 'PMID:12411706; DOI:10.1126/science.1075565', '12411706', 'literature_xml', 'exact_identifier_match:PMID:12411706', 'linked_unresolved', 'B', 'L1', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:12411706; DOI:10.1126/science.1075565; https://pubmed.ncbi.nlm.nih.gov/12411706/', 'The primary study reported that mature murine beta-defensin-2 acts directly on immature dendritic cells as an endogenous TLR4 ligand, inducing costimulatory-molecule upregulation and dendritic-cell maturation and promoting type-1 polarized adaptive responses in vivo.', 'The authors conclude that mature mouse beta-defensin-2 functions as an endogenous TLR4 ligand in dendritic-cell assays. Preserve peptide identity and species boundaries; this is direct/proximal comparator evidence and not an SCI-specific result.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMID12411706_DEFB2_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000168' AND x.extraction_id='M24B-P2-R-RECOVERY-BDEF2-TLR4-000001');
