INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000128', 'M24B-EVID-000170', 'M24B-P2-R-000170', 'PMID:22842346; PMCID:PMC3622453', '22842346', 'literature_xml', 'exact_identifier_match:PMID:22842346', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMID:22842346; PMCID:PMC3622453; https://pmc.ncbi.nlm.nih.gov/articles/PMC3622453/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMC3622453_HMGB1_TIM3_bioc.json', 'Tumor-associated dendritic-cell TIM-3 interacted with the alarmin HMGB1 and interfered with nucleic-acid recruitment into DC endosomes, suppressing TLR/cytosolic-sensor innate responses in mouse and human tumor comparator systems. HMGB1 redox/form and endosomal context are essential; no SCI model was tested.', 'Retain HMGB1 -> TIM-3 receptor-proximal suppression of nucleic-acid/TLR sensing in tumor DC comparators. Do not substitute Galectin-9/TIM-3, infer SCI function, or assign a terminal TF from the suppression phenotype.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B303_PMID22842346_HMGB1_TIM3_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000170' AND x.extraction_id='M24B-P2-R-000170');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000130', 'M24B-EVID-000172', 'M24B-P2-R-000172', 'PMID:34369876', '34369876', 'literature_xml', 'exact_identifier_match:PMID:34369876', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_context_only', 'PMID:34369876; https://pubmed.ncbi.nlm.nih.gov/34369876/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B304_PMID34369876_LGALS9_TLR4_pubmed.xml', 'Galectin-9 regulated TLR responses in mouse B-1a cells through glycan/cell-context-dependent interactions with regulatory molecules including CD180, setting B-cell activation thresholds and autoimmunity. The study does not justify a generic direct galectin-9-TLR4 ligand edge or any SCI function.', 'Retain galectin-9 glycan/cell-context modulation of TLR responses in B-1a comparator systems. Do not promote a generic galectin-9-TLR4 direct edge, substitute Galectin-9/TIM-3 evidence, or infer SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B304_PMID34369876_LGALS9_TLR4_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000172' AND x.extraction_id='M24B-P2-R-000172');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000131', 'M24B-EVID-000180', 'M24B-P2-R-000180', 'PMID:41044292; PMCID:PMC12789345; DOI:10.1007/s12264-025-01488-z', '41044292', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC12789345', 'supporting_validated_claim', 'B', 'L2', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMID:41044292; PMCID:PMC12789345; DOI:10.1007/s12264-025-01488-z; https://pubmed.ncbi.nlm.nih.gov/41044292/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMC12789345_C3a_SCI_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMID41044292_C3a_NFkb_Nrf2_SCI_pubmed.xml', 'In mouse SCI spinal neural stem cells and injured cord, C3a/C3aR signaling activated NF-kappaB p65, inhibited Nrf2 and UCHL1/proteasome activity, increased protein aggregates, and impaired NSC activation. C3aR blockade, NF-kappaB p65 knockdown, or Nrf2 overexpression rescued downstream activity; C3aR pharmacology does not establish purified C3a-C3aR1 binding.', 'Promote the bounded C3a/C3aR -> NF-kappaB p65 -> Nrf2 -> UCHL1/proteasome -> NSC activation relay after mouse SCI. Keep Nrf2 -> UCHL1 as a downstream TF edge for Module 22A, not a direct receptor edge; do not infer purified ligand binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMC12789345_C3a_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000180' AND x.extraction_id='M24B-P2-R-000180');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000132', 'M24B-EVID-000181', 'M24B-P2-R-000181', 'PMID:41044292; PMCID:PMC12789345; DOI:10.1007/s12264-025-01488-z', '41044292', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC12789345', 'supporting_validated_claim', 'B', 'L2', 'validated_fulltext', 'validated_functional_context', 'PMID:41044292; PMCID:PMC12789345; DOI:10.1007/s12264-025-01488-z; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMC12789345_C3a_SCI_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMID41044292_C3a_NFkb_Nrf2_SCI_pubmed.xml', 'C3a/C3aR signaling impaired spinal NSC activation and neurogenic repair-associated cellular state through the NF-kappaB p65/Nrf2/UCHL1-proteasome axis; C3aR blockade, NF-kappaB p65 knockdown, Nrf2 overexpression, or UCHL1 rescue improved protein aggregate clearance and NSC activation in mouse SCI models.', 'Promote the C3a/C3aR-dependent suppression of NSC activation and protein-aggregate clearance after mouse SCI as a downstream functional output. Keep it separate from direct ligand binding and from the Nrf2-to-UCHL1 TF edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMC12789345_C3a_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000181' AND x.extraction_id='M24B-P2-R-000181');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000133', 'M24B-EVID-000182', 'M24B-P2-R-000182', 'PMID:22862305; PMCID:PMC3525875; DOI:10.1111/j.1476-5381.2012.02127.x', '22862305', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3525875', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:22862305; PMCID:PMC3525875; DOI:10.1111/j.1476-5381.2012.02127.x; https://pubmed.ncbi.nlm.nih.gov/22862305/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMID22862305_BDKRB1_SCI_pubmed.xml', 'Rat SCI-associated overactive bladder studies showed increased BDKRB1 expression in bladder, dorsal-root ganglia, and spinal cord; selective B1 agonist/antagonist and B2 antagonist pharmacology altered bladder responses. The B1 receptor pathway is pharmacologic and does not establish purified des-Arg9-bradykinin/BDKRB1 binding or endogenous kallikrein cleavage.', 'Promote the bounded des-Arg9-bradykinin/BDKRB1 and B2 pharmacologic relay in rat SCI-associated bladder dysfunction. Keep B1 and B2 branches distinct and do not infer direct ligand binding or lesion-core inflammatory function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMC3525875_BDKRB1_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000182' AND x.extraction_id='M24B-P2-R-000182');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000134', 'M24B-EVID-000183', 'M24B-P2-R-000183', 'PMID:22862305; PMCID:PMC3525875; DOI:10.1111/j.1476-5381.2012.02127.x', '22862305', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3525875', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_context', 'PMID:22862305; PMCID:PMC3525875; DOI:10.1111/j.1476-5381.2012.02127.x; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMID22862305_BDKRB1_SCI_pubmed.xml', 'After rat SCI, BDKRB1 expression increased and selective B1 antagonist treatment reduced non-voiding contractions and improved bladder capacity, voided volume, and voiding efficiency; B2 blockade also reduced non-voiding contractions. These are bladder/autonomic functional outputs, not direct binding or lesion-core inflammatory evidence.', 'Promote the BDKRB1/B2-dependent bladder hyperexcitability and overactive-bladder functional outputs after rat SCI, keeping B1/B2 pharmacology separate from endogenous ligand processing and direct receptor binding.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B305_PMC3525875_BDKRB1_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000183' AND x.extraction_id='M24B-P2-R-000183');
