INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000151', 'M24B-EVID-000200', 'M24B-P2-R-000200', 'PMID:24086560; PMCID:PMC3782447; DOI:10.1371/journal.pone.0075543', '24086560', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC3782447', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_contextual_support', 'PMID:24086560; PMCID:PMC3782447; DOI:10.1371/journal.pone.0075543; https://pubmed.ncbi.nlm.nih.gov/24086560/; https://pmc.ncbi.nlm.nih.gov/articles/PMC3782447/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B309_PMIDs_35784110_18670324_12196576_22393018_24086560_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B309_PMC3782447_RvD1_FPR2_spinal_bioc.json', 'In a rat carrageenan peripheral-inflammation model, intrathecal 17(R)-RvD1 reduced mechanical hypersensitivity and CSF TNF release; RvD1 also reduced stimulus-induced TNF release in rat primary spinal astrocytes and altered ERK-associated responses in human astrocytes. FPR2/ALX was localized to rat spinal astrocytes, while rodent GPR32 was not established and no SCI model was tested.', 'Retain the RvD1-FPR2/ALX-associated spinal anti-nociceptive and astrocyte cytokine-resolution comparator output. Do not infer traumatic-SCI causality, a direct rodent GPR32 edge, or receptor-selective FPR2/ALX necessity from expression/localization and pharmacologic treatment alone.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B309_PMC3782447_RvD1_FPR2_spinal_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000200' AND x.extraction_id='M24B-P2-R-000200');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000148', 'M24B-EVID-000197', 'M24B-P2-R-000197', 'PMID:35784110; PMCID:PMC9242000; DOI:10.2147/JPR.S366782', '35784110', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC9242000', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_contextual_support', 'PMID:35784110; PMCID:PMC9242000; DOI:10.2147/JPR.S366782; https://pubmed.ncbi.nlm.nih.gov/35784110/; https://pmc.ncbi.nlm.nih.gov/articles/PMC9242000/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B309_PMIDs_35784110_18670324_12196576_22393018_24086560_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B309_PMC9242000_C3_CR3_NR2B_SCI_bioc.json', 'In a preliminary rat traumatic-SCI cohort, 9 of 17 animals developed evoked neuropathic pain; C3, C1q, and CR3 expression patterns differed between pain and non-pain SCI groups, and NR2B expression increased in the superficial dorsal horn of pain animals. The study is correlative and does not perturb CR3 or identify a C3 fragment.', 'Retain the bounded C3/CR3-associated neuropathic-pain correlation and NR2B dorsal-horn output after rat SCI. Do not infer intact C3 -> CR3 binding, direct CR3 signaling, or a causal C3/CR3 -> NR2B edge from the subgroup expression data.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B309_PMC9242000_C3_CR3_NR2B_SCI_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000197' AND x.extraction_id='M24B-P2-R-000197');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'literature_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B309_PMIDs_35784110_18670324_12196576_22393018_24086560_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000013', 'M24B-EVID-000003', 'M24B-P2-000003', 'PMID:34993473', '34993473', 'full_text_html', 'exact_identifier_match:DOI:10.1093/braincomms/fcab271;PMCID:PMC8728726', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:34993473; PMCID:PMC8728726; DOI:10.1093/braincomms/fcab271; local BioC cache=data/raw/evidence/module20_24_supervised_cli_phase2/M24B_34993473_PMC8728726.json', 'In primary rat cortical neurons, mixed extracellular histones inhibited neurite outgrowth in a microfluidic chamber assay, while combined activated protein C and histone treatment restored neurite outgrowth relative to histone alone; the paper also reports partial protection after TLR2 knockdown. In a rat optic-nerve-crush comparator, APC applied in gelfoam increased CTB-labeled axonal regeneration beyond the lesion.', 'The authors propose that APC blocks histone-mediated inhibition because it cleaves histones, while acknowledging that APC anti-inflammatory, anti-apoptotic, and anticoagulant effects may also contribute to regeneration.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID003_PMC8728726_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000003' AND x.extraction_id='M24B-P2-000003');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000013', 'M24B-EVID-000013', 'M24B-P2-000013', 'PMID:34993473', '34993473', 'full_text_html', 'exact_identifier_match:DOI:10.1093/braincomms/fcab271;PMCID:PMC8728726', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:34993473; PMCID:PMC8728726; DOI:10.1093/braincomms/fcab271; local BioC cache=data/raw/evidence/module20_24_supervised_cli_phase2/M24B_34993473_PMC8728726.json', 'Same primary experiment as M24B-EVID-000003: primary rat cortical-neuron microfluidic assays showed histone-mediated neurite inhibition reversed by APC, with comparator rat optic-nerve-crush regeneration and TLR2/YB-1 pathway results. Reuse the previously validated atomic observation rather than create a duplicate.', 'Reuse the validated APC/histone author interpretation from M24B-EVID-000003; the paper''s Discussion states that APC can block histone effects but other APC properties may contribute to regeneration.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID003_PMC8728726_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000013' AND x.extraction_id='M24B-P2-000013');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000008', 'M24B-EVID-000011', 'M24B-P2-R-D24B052-000003', 'PMCID:PMC9713475; PMID:36466087; DOI:10.1155/2022/9197940', '36466087', 'full_text_html', 'exact_identifier_match:DOI:10.1155/2022/9197940;PMCID:PMC9713475', 'supporting_validated_claim', 'B', 'L3', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC9713475; PMID:36466087; DOI:10.1155/2022/9197940; https://pmc.ncbi.nlm.nih.gov/articles/PMC9713475/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID011_PMC9713475_full.html', 'In rat contusive SCI tissue, LL37, described as a structural component of macrophage extracellular traps, co-immunoprecipitated with membrane P2X7R; injured tissue showed increased P2X7R, LL37, total NF-kB, and phospho-NF-kB, and DNase I reduced these signals relative to untreated SCI. The paper does not isolate a purified LL37-P2X7R affinity measurement.', 'Promote the bounded LL37-P2X7R-NF-kB receptor-proximal relay in rat SCI tissue as co-immunoprecipitation plus pathway-associated evidence. Preserve extracellular-trap context and do not convert the Co-IP into purified binary affinity or infer that all DNase-I effects are P2X7R-specific.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID011_PMC9713475_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000011' AND x.extraction_id='M24B-P2-R-D24B052-000003');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000008', 'M24B-EVID-000045', 'M24B-P2-R-000945', 'PMCID:PMC9713475', '36466087', 'full_text_html', 'exact_identifier_match:PMCID:PMC9713475', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMCID:PMC9713475; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Primary SCI paper retrieved; exact observation retained at source scope.', 'SCI phenotype is supported at the reported model scope; no direct terminal-TF edge was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID011_PMC9713475_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000045' AND x.extraction_id='M24B-P2-R-000945');
