INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID018_PMC6399007_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000018', 'M24B-EVID-000018', 'M24B-P2-R-RECOVERY-P2X4-DHCB-SCI-ABSTRACT-000001', 'PMID:30622226; DOI:10.14348/molcells.2018.0028', '30622226', 'literature_xml', 'exact_identifier_match:PMID:30622226', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:30622226; DOI:10.14348/molcells.2018.0028; https://pubmed.ncbi.nlm.nih.gov/30622226/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml', 'In a rat contusion SCI model, P2X4R expression increased and chronic neuropathic pain was present by day 7. Intravenous dehydrocorybulbine relieved pain-related behaviors without changing motor function, reduced IL-1beta, IL-18, and MMP-9 elevations, attenuated P2X4R upregulation, and reduced ATP-evoked intracellular calcium. P2X receptor and dopamine D2 receptor agonists antagonized dehydrocorybulbine''s antinociceptive effects. The primary abstract supports a pharmacologic P2X4-associated pain pathway, not direct ATP-P2X4 binding.', 'The primary authors propose that dehydrocorybulbine reduces SCI-associated neuropathic pain by inhibiting P2X4R-associated signaling. The pharmacology supports a receptor-proximal pain branch, but does not establish purified ATP-P2X4 affinity or a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID018_PUBMED_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000018' AND x.extraction_id='M24B-P2-R-RECOVERY-P2X4-DHCB-SCI-ABSTRACT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000018', 'M24B-EVID-PROMO-20260826-002', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID018_PUBMED_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-PROMO-20260826-002' AND x.extraction_id='');
