INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000083', 'M24B-EVID-000119', 'M24B-P2-R-000119', 'PMID:24531000; PMCID:PMC3993933; DOI:10.1016/j.jsb.2014.02.001', '24531000', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.jsb.2014.02.001;PMCID:PMC3993933', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:24531000; PMCID:PMC3993933; DOI:10.1016/j.jsb.2014.02.001; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B290_PMID24531000_C1QTNF5_MFRP_pubmed.xml', 'C1QTNF5 immobilized on resin selectively enriched detergent-extracted membrane-bound MFRP, with structural/multimerization analyses supporting a C1QTNF5-MFRP membrane-association/adhesion complex in retinal comparator systems. No SCI model or downstream signaling assay was reported.', 'Retain C1QTNF5 -> MFRP membrane association/adhesion-complex evidence in the tested retinal comparator context. Do not infer SCI expression, downstream pathway, or generic complement-receptor behavior.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_EVID119_PMC3993933_full.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000119' AND x.extraction_id='M24B-P2-R-000119');
