INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_PMC6399007_DHCB_P2X4_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_PMC6781990_CCL28_CCR10_full.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000038', 'M24B-EVID-000055', 'M24B-P2-R-RECOVERY-BK-B2R-GDNF-000001', 'PMCID:PMC4753273; PMID:26634895; DOI:10.1113/JP271152', '26634895', 'full_text_html', 'exact_identifier_match:DOI:10.1113/jp271152;PMCID:PMC4753273', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4753273; PMID:26634895; DOI:10.1113/JP271152; https://pmc.ncbi.nlm.nih.gov/articles/PMC4753273/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC4753273_BK_B2R.html', 'In neonatal mouse spinal preparations and BV2 microglia, bradykinin disrupted fictive locomotion and depolarized spinal motor and interneuron populations through B2R-associated pharmacology. In a neonatal SCI model, microglia increased and GDNF expression was localized to microglia; in BV2 cultures, bradykinin increased GDNF expression, and the effect was blocked by the B2R antagonist HOE 140 but not assigned to a downstream TF. The study supports a B2R-proximal relay and microglial GDNF functional output, not direct BK-B2R affinity or a complete PLC/IP3/Ca2+ cascade.', 'The authors conclude that bradykinin acts through B2R to modulate sensorimotor spinal networks and induce microglial GDNF expression, providing a proposed plasticity mechanism after neonatal SCI. The direct receptor-proximal result and GDNF output are retained separately; no BDKRB1, terminal TF, or adult SCI transfer is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC4753273_BK_B2R.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000055' AND x.extraction_id='M24B-P2-R-RECOVERY-BK-B2R-GDNF-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000037', 'M24B-EVID-000054', 'M24B-P2-R-RECOVERY-APC-PAR1-SCI-000001', 'PMCID:PMC5266300; PMID:28122028; DOI:10.1371/journal.pone.0170512', '28122028', 'full_text_html', 'exact_identifier_match:DOI:10.1371/journal.pone.0170512;PMCID:PMC5266300', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC5266300; PMID:28122028; DOI:10.1371/journal.pone.0170512; https://pmc.ncbi.nlm.nih.gov/articles/PMC5266300/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC5266300_APC_PAR1.html', 'In adult mice with contusive SCI, PAR1-null animals showed reduced neutrophil infiltration and blood-spinal-cord barrier disruption at the lesion, improved locomotor and inclined-grid performance, greater white-matter sparing, and reduced glial scarring. Acute recombinant APC improved locomotor recovery in wild-type mice but did not add benefit in PAR1-null mice, supporting PAR1 dependence of the APC functional effect and the paper''s biased-agonism interpretation. The study did not measure purified APC-PAR1 binding or define a complete intracellular relay in the injured cord.', 'The authors conclude that thrombin-activated PAR1 contributes to secondary injury and that APC acts through PAR1 by biased agonism to improve recovery after contusive SCI. This is a receptor-complex and functional-output record; it is not evidence of purified ligand-receptor affinity or a terminal TF pathway.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC5266300_APC_PAR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000054' AND x.extraction_id='M24B-P2-R-RECOVERY-APC-PAR1-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000041', 'M24B-EVID-000059', 'M24B-P2-R-000059', 'PMID:28122028; PMCID:PMC5266300; DOI:10.1371/journal.pone.0170512', '28122028', 'full_text_html', 'exact_identifier_match:DOI:10.1371/journal.pone.0170512;PMCID:PMC5266300', 'candidate_requires_review', 'B', 'L1', 'reused_validated_evidence', 'reused_validated_evidence', 'PMID:28122028; PMCID:PMC5266300; DOI:10.1371/journal.pone.0170512; reused local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B277_PMC5266300_APC_PAR1_SCI_bioc.json', 'Reuse the validated mouse APC/PAR1-null SCI observation from EVID-000054: acute APC improved wild-type locomotor, barrier, inflammatory, white-matter, and glial-scar outcomes, but did not add benefit in PAR1-null mice. No new observation is created.', 'Reuse the bounded claim that APC protection in the tested mouse contusive-SCI model depends on PAR1, while preserving that EPCR, endogenous APC release, and direct ligand binding were not independently isolated.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC5266300_APC_PAR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000059' AND x.extraction_id='M24B-P2-R-000059');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000028', 'M24B-EVID-000037', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC6538362_C3a_C3aR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000037' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000039', 'M24B-EVID-000056', 'M24B-P2-R-RECOVERY-C3a-C3aR1-PTEN-000001', 'PMCID:PMC6538362; PMID:31045582; DOI:10.1172/jci.insight.98254', '31045582', 'full_text_html', 'exact_identifier_match:DOI:10.1172/jci.insight.98254;PMCID:PMC6538362', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6538362; PMID:31045582; DOI:10.1172/jci.insight.98254; https://pmc.ncbi.nlm.nih.gov/articles/PMC6538362/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC6538362_C3a_C3aR1.html', 'After traumatic mouse SCI, C3a levels rose in blood and spinal cord and C3aR1 was detected on infiltrating neutrophils, microglia/macrophages, astrocytes, and other lesion-associated cells. C3ar1-null mice had worse locomotor recovery and pathology; bone-marrow chimeras and neutrophil depletion localized the recovery phenotype primarily to the peripheral immune compartment. C3aR1 agonism in bone-marrow neutrophils increased ERK phosphorylation and PTEN, blocked CXCL1-induced AKT phosphorylation and chemotaxis, and the PTEN inhibitor reversed this suppression. The paper therefore supports a C3a/C3aR1-to-PTEN antagonism of CXCR2/PI3K-AKT chemotactic signaling and SCI functional protection, without a terminal TF claim.', 'The authors conclude that the C3a/C3aR1 axis is neuroprotective after SCI by engaging PTEN to restrain CXCR2-driven neutrophil mobilization and PI3K-AKT chemotaxis. This is a receptor-proximal/pathway and functional record; no purified C3a-C3aR1 binding or terminal TF endpoint is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC6538362_C3a_C3aR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000056' AND x.extraction_id='M24B-P2-R-RECOVERY-C3a-C3aR1-PTEN-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000039', 'M24B-EVID-000089', 'M24B-P2-R-000089', 'PMID:37852260; PMID:31045582; PMCID:PMC7615941; PMCID:PMC6538362; DOI:10.1016/j.cell.2023.09.020', '31045582', 'full_text_html', 'exact_identifier_match:PMCID:PMC6538362', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:37852260; https://pubmed.ncbi.nlm.nih.gov/37852260/; PMID:31045582; https://pubmed.ncbi.nlm.nih.gov/31045582/; PMCID:PMC7615941; PMCID:PMC6538362; DOI:10.1016/j.cell.2023.09.020', 'Primary cognate-receptor evidence supports C3a activation of C3aR1, while a separate traumatic-SCI study showed C3a/C3aR1-dependent PTEN restraint of CXCR2 signaling and neutrophil mobilization. Structural/receptor-transducer evidence and the SCI receptor-proximal/functional relay are retained as distinct components; no intact C3-to-C3aR1 interaction is inferred.', 'Retain C3a -> C3aR1 -> PTEN antagonism of CXCR2/PI3K-AKT-associated neutrophil mobilization in the tested SCI context, alongside separate cognate C3aR1 molecular evidence. Do not collapse C3a into intact C3 or infer C3aR2/C5aR substitutions.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC6538362_C3a_C3aR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000089' AND x.extraction_id='M24B-P2-R-000089');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000040', 'M24B-EVID-000057', 'M24B-P2-R-RECOVERY-C5a-C5aR1-SCI-000001', 'PMCID:PMC6605214; PMID:25904802; DOI:10.1523/JNEUROSCI.5218-14.2015', '25904802', 'full_text_html', 'exact_identifier_match:DOI:10.1523/jneurosci.5218-14.2015;PMCID:PMC6605214', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6605214; PMID:25904802; DOI:10.1523/JNEUROSCI.5218-14.2015; https://pmc.ncbi.nlm.nih.gov/articles/PMC6605214/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC6605214_C5a_C5aR1.html', 'In adult mouse contusive SCI, C5a and C5aR increased in the injured cord and C5aR was detected on microglia/macrophages, astrocytes, and other lesion-associated cells. C5ar-null mice showed improved early but worse later locomotor outcomes, larger chronic lesions, reduced myelin and GFAP scarring, and altered inflammatory-cell distribution. Acute C5aR blockade reduced early inflammatory cytokines and monocyte/macrophage recruitment, whereas chronic C5aR signaling promoted astrocyte proliferation and glial scarring. In cultured astrocytes, C5a induced STAT3 phosphorylation and proliferation; a STAT3 inhibitor blocked both effects, and C5ar-null astrocytes did not respond. The paper supports a time-dependent C5a/C5aR-to-STAT3 astrocyte relay and SCI function, not direct C5a-C5aR binding or STAT3 target-gene occupancy.', 'The authors conclude that C5aR signaling has a dual, time-dependent role after SCI: acute signaling contributes to inflammatory pathology, while postacute signaling supports STAT3-dependent astrocyte proliferation and glial-scar formation. This validates a receptor-proximal/pathway and functional record, but not purified binding, C5aR2-specific signaling, or direct STAT3 promoter occupancy.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC6605214_C5a_C5aR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000057' AND x.extraction_id='M24B-P2-R-RECOVERY-C5a-C5aR1-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000040', 'M24B-EVID-000090', 'M24B-P2-R-000090', 'PMID:2007135; PMID:25904802; PMCID:PMC6605214; DOI:10.1523/JNEUROSCI.5218-14.2015', '25904802', 'full_text_html', 'exact_identifier_match:DOI:10.1523/jneurosci.5218-14.2015;PMCID:PMC6605214', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:2007135; PMID:25904802; PMCID:PMC6605214; DOI:10.1523/JNEUROSCI.5218-14.2015; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B285_PMID2007135_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B278_PMID25904802_C5aR1_pubmed.xml', 'Expression cloning transferred specific binding of iodinated recombinant human C5a to the cloned human C5a receptor in COS-7 cells, establishing a direct cognate C5a-C5aR1 molecular interaction. In separate mouse contusive-SCI experiments, C5aR1 loss or early selective blockade reduced acute inflammation and improved early recovery, whereas continued receptor absence/blockade impaired later repair, myelin, lesion, and astroglial-scar outcomes.', 'Promote the direct C5a -> C5aR1 molecular edge and the phase-dependent C5aR1 SCI relay as separate evidence layers: acute signaling is injurious in the tested window, while post-acute signaling supports astrocyte hyperplasia/hypertrophy and glial-scar repair. Keep C5aR2-specific contributions and any universal downstream TF endpoint unresolved.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC6605214_C5a_C5aR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000090' AND x.extraction_id='M24B-P2-R-000090');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000040', 'M24B-EVID-000090', 'M24B-P2-R-RECOVERY-C5A-C5AR1-STAT3-000001', 'PMCID:PMC6605214; PMID:25904802; DOI:10.1523/JNEUROSCI.5218-14.2015', '25904802', 'full_text_html', 'exact_identifier_match:DOI:10.1523/jneurosci.5218-14.2015;PMCID:PMC6605214', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6605214; PMID:25904802; DOI:10.1523/JNEUROSCI.5218-14.2015; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_fulltext/html/PMC6605214.html', 'In mouse contusive SCI, C5a levels increased in spinal cord and plasma and C5aR1 was detected on microglia/macrophage-like cells and astrocytes. C5ar-null mice and early C5aR antagonist treatment reduced acute inflammatory or functional injury, whereas prolonged C5aR loss/blockade impaired later recovery and glial-scar-associated outcomes. In cultured wild-type astrocytes, recombinant C5a induced dose-dependent proliferation and approximately 2.5-fold STAT3 phosphorylation; the response was absent in C5ar-null astrocytes and was blocked by the STAT3 inhibitor BP-1-102.', 'The authors conclude that C5a-C5aR signaling has a dual, time-dependent role after SCI: acute/subacute signaling contributes to inflammatory injury, while postacute signaling supports astrocyte proliferation and glial-scar formation. The in vitro data place STAT3 phosphorylation downstream of C5aR in astrocytes and show that STAT3 inhibition blocks the C5a-induced proliferative output.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC6605214_C5a_C5aR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000090' AND x.extraction_id='M24B-P2-R-RECOVERY-C5A-C5AR1-STAT3-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000041', 'M24B-EVID-000058', 'M24B-P2-R-RECOVERY-THROMBIN-PAR1-MAPK-000001', 'PMCID:PMC8995373; PMID:35399122; DOI:10.1038/s41420-022-00997-4', '35399122', 'full_text_html', 'exact_identifier_match:DOI:10.1038/s41420-022-00997-4;PMCID:PMC8995373', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC8995373; PMID:35399122; DOI:10.1038/s41420-022-00997-4; https://pmc.ncbi.nlm.nih.gov/articles/PMC8995373/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC8995373_thrombin_PAR1.html', 'In rat contusive SCI, thrombin increased at lesion sites and PAR1 was upregulated and colocalized with GFAP-positive astrocytes. In primary rat astrocytes, thrombin or a PAR1 agonist reversed stellation, increased proliferation, inhibited migration, and increased TNF-alpha, IL-1beta, and IL-6. PAR1 siRNA, but not PAR3 siRNA or PAR4 inhibition, attenuated thrombin-induced morphology changes. Thrombin increased phosphorylation of ERK, JNK, and NF-kappaB but not p38; the PAR1 inhibitor SCH79797 reduced the ERK/JNK/NF-kappaB responses and inflammatory cytokine production. The study supports a thrombin/PAR1-to-MAPK/NF-kappaB receptor-proximal relay and astrocyte functional output, not direct thrombin-PAR1 affinity or terminal NF-kappaB target-gene occupancy.', 'The authors conclude that thrombin activates PAR1 in astrocytes and induces morphological and inflammatory responses through MAPK/NF-kappaB signaling after SCI. This is receptor-proximal and functional evidence; PAR3/PAR4 were considered as controls, but direct ligand-receptor binding, exact G-protein coupling, and terminal NF-kappaB target occupancy remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch058_PMC8995373_thrombin_PAR1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000058' AND x.extraction_id='M24B-P2-R-RECOVERY-THROMBIN-PAR1-MAPK-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000054', 'M24B-EVID-000075', 'M24B-P2-R-RECOVERY-SP-NK1-SCI-BLADDER-000001', 'PMCID:PMC2685299; PMID:18945947', '18945947', 'full_text_html', 'exact_identifier_match:PMCID:PMC2685299', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2685299; PMID:18945947; https://pmc.ncbi.nlm.nih.gov/articles/PMC2685299/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC2685299_substanceP_NK1.html', 'In rats two weeks after complete T9 spinal transection, substance-P immunoreactivity increased in the sacral parasympathetic nucleus and intrathecal NK1 antagonist L-733060 blocked the established spinal micturition reflex in most SCI animals at the effective doses, while having little effect in intact rats. This supports an SCI functional dependence on spinal NK1/tachykinin signaling, not purified substance-P/TACR1 binding.', 'The primary SCI study supports a post-transection increase in spinal substance-P input and NK1-receptor-dependent spinal micturition reflexes. It does not resolve the downstream PLC/ERK/p38 relay or a terminal transcription factor.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC2685299_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000075' AND x.extraction_id='M24B-P2-R-RECOVERY-SP-NK1-SCI-BLADDER-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000057', 'M24B-EVID-000078', 'M24B-P2-R-000078', 'PMID:18945947; PMID:25921821; PMCID:PMC2685299; DOI:10.1152/ajpregu.90653.2008; DOI:10.1016/j.spinee.2015.04.032', '18945947', 'full_text_html', 'exact_identifier_match:DOI:10.1152/ajpregu.90653.2008;PMCID:PMC2685299', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMID:18945947; PMID:25921821; PMCID:PMC2685299; DOI:10.1152/ajpregu.90653.2008; DOI:10.1016/j.spinee.2015.04.032; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B282_substanceP_NK_SCI_pubmed.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC2685299_substanceP_NK1.html', 'In adult rats with complete T9 spinal cord transection, Substance P immunoreactivity was increased in the L6-S1 sacral parasympathetic nucleus relative to intact rats. In conscious cystometry, intrathecal NK1 antagonist L-733060 at 30-100 micrograms blocked or reduced post-injury spinal micturition reflexes in most SCI rats, with little or no effect in intact controls.', 'Within the tested rat SCI bladder-reflex model, the authors support a bounded Substance P/Tacr1 (NK1) functional pathway: SP is increased after SCI and NK1 antagonism suppresses the post-injury micturition reflex. The abstract-only PMID25921821 ERK/p38 progenitor result is not transferred into this source unit.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC2685299_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000078' AND x.extraction_id='M24B-P2-R-000078');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000046', 'M24B-EVID-000067', 'M24B-P2-R-000067', 'PMID:9276127; PMID:30359406; PMCID:PMC6201908', '30359406', 'full_text_html', 'exact_identifier_match:PMCID:PMC6201908', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:9276127; PMID:30359406; PMCID:PMC6201908; https://pubmed.ncbi.nlm.nih.gov/30359406/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B280_tachykinin_NK_pubmed.xml', 'Primary mouse native-tissue and human recombinant-receptor studies show neurokinin A binding/activation of NK1/Tacr1, with calcium/cAMP and contractility pharmacology. Exogenous NKA activity in receptor systems is distinct from injury-induced spinal release or SCI lesion signaling.', 'Retain NKA/NK1 direct receptor-pharmacology support as a non-SCI comparator and keep spinal injury release and lesion-specific function unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC6201908_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000067' AND x.extraction_id='M24B-P2-R-000067');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000047', 'M24B-EVID-000068', 'M24B-P2-R-000068', 'PMID:9276127; PMID:30359406; PMCID:PMC6201908', '30359406', 'full_text_html', 'exact_identifier_match:PMCID:PMC6201908', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:9276127; PMID:30359406; PMCID:PMC6201908; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B280_tachykinin_NK_pubmed.xml', 'Primary studies support NKA binding/activation of NK2/Tacr2, including mouse native-tissue pharmacology and human recombinant NK2 receptor binding/calcium/cAMP assays. These are non-SCI receptor-comparator results and do not establish an NKA-NK2 spinal injury relay.', 'Retain NKA/NK2 direct receptor-pharmacology support as a non-SCI comparator. Keep traumatic-SCI release, processing, and lesion-receiver function unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC6201908_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000068' AND x.extraction_id='M24B-P2-R-000068');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000054', 'M24B-EVID-000075', 'M24B-P2-R-RECOVERY-SP-TACR1-BIND-000001', 'PMCID:PMC6201908; PMID:30359406; DOI:10.1371/journal.pone.0205894', '30359406', 'full_text_html', 'exact_identifier_match:DOI:10.1371/journal.pone.0205894;PMCID:PMC6201908', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6201908; PMID:30359406; DOI:10.1371/journal.pone.0205894; https://pmc.ncbi.nlm.nih.gov/articles/PMC6201908/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC6201908_substanceP_NK1.html', 'In CHO cells expressing human recombinant NK1/TACR1, substance P competed for [3H]-septide binding with the highest affinity among the tested peptides and produced a concentration-dependent intracellular Ca2+ response as a full agonist reference; substance P was also tested in the CRE-luciferase cAMP assay. This directly supports substance-P activation of NK1/TACR1 in a recombinant human receptor system, but it is not an SCI model.', 'The primary paper supports direct substance-P binding/activation of recombinant human NK1/TACR1 and downstream Ca2+/cAMP assay responses. It does not establish the SCI-specific PLC-Ca2+/ERK-p38 relay, endogenous peptide release, or a terminal TF target.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC6201908_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000075' AND x.extraction_id='M24B-P2-R-RECOVERY-SP-TACR1-BIND-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000055', 'M24B-EVID-000076', 'M24B-P2-R-000076', 'PMID:30359406; PMID:9276127; PMCID:PMC6201908', '30359406', 'full_text_html', 'exact_identifier_match:PMCID:PMC6201908', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_context_only', 'PMID:30359406; PMID:9276127; PMCID:PMC6201908; https://pubmed.ncbi.nlm.nih.gov/30359406/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B282_substanceP_NK_SCI_pubmed.xml', 'Primary human recombinant and mouse native-tissue studies support Substance P/Tacr2-NK2 pharmacology, including binding/activation in recombinant systems and native smooth-muscle activity. No direct Substance P-Tacr2 traumatic-SCI intervention was validated.', 'Retain Substance P/NK2 as non-SCI receptor-pharmacology comparator evidence and leave traumatic-SCI Tacr2 activation unknown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC6201908_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000076' AND x.extraction_id='M24B-P2-R-000076');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000056', 'M24B-EVID-000077', 'M24B-P2-R-000077', 'PMID:30359406; PMCID:PMC6201908', '30359406', 'full_text_html', 'exact_identifier_match:PMCID:PMC6201908', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_context_only', 'PMID:30359406; PMCID:PMC6201908; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B282_substanceP_NK_SCI_pubmed.xml', 'Human recombinant NK3/Tacr3 pharmacology supports lower-potency Substance P activity at NK3 relative to its preferred tachykinin agonists. This is weak receptor cross-reactivity in a non-SCI comparator system, not evidence of a traumatic-SCI SP-NK3 relay.', 'Retain Substance P/NK3 as weak non-SCI cross-reactivity context only. Do not infer a direct physiologic SCI edge, endogenous spinal SP release, or a downstream TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC6201908_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000077' AND x.extraction_id='M24B-P2-R-000077');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000046', 'M24B-EVID-000094', 'M24B-P2-R-000094', 'PMID:9276127; PMID:30359406; PMCID:PMC6201908', '30359406', 'full_text_html', 'exact_identifier_match:PMCID:PMC6201908', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:9276127; PMID:30359406; PMCID:PMC6201908; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B280_tachykinin_NK_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B282_substanceP_NK_SCI_pubmed.xml', 'NKA showed high-affinity binding and receptor activation at recombinant human NK1/Tacr1 systems, with calcium/cAMP-linked assays and separate mouse native-tissue comparator pharmacology. No injury-induced NKA release or traumatic-SCI NKA-NK1 pathway was tested.', 'Retain NKA -> NK1/Tacr1 direct receptor and receptor-effector comparator evidence. Do not infer SCI release, lesion function, or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC6201908_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000094' AND x.extraction_id='M24B-P2-R-000094');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000047', 'M24B-EVID-000095', 'M24B-P2-R-000095', 'PMID:9276127; PMID:30359406; PMCID:PMC6201908', '30359406', 'full_text_html', 'exact_identifier_match:PMCID:PMC6201908', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:9276127; PMID:30359406; PMCID:PMC6201908; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B280_tachykinin_NK_pubmed.xml; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B282_substanceP_NK_SCI_pubmed.xml', 'Human recombinant NK2 studies support NKA binding and activation through calcium/cAMP-linked receptor assays, with separate mouse native-tissue tachykinin pharmacology showing NKA as a strong NK2 agonist. No endogenous injury release or traumatic-SCI NKA-NK2 relay was tested.', 'Retain NKA -> NK2/Tacr2 direct receptor and receptor-effector comparator evidence. Do not infer injury-induced NKA release or an SCI pathway from these recombinant/native systems.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC6201908_substanceP_NK1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000095' AND x.extraction_id='M24B-P2-R-000095');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000054', 'M24B-EVID-000075', 'M24B-P2-R-RECOVERY-SP-NK1-SCI-NSPC-000001', 'PMID:25921821; DOI:10.1016/j.spinee.2015.04.032', '25921821', 'literature_xml', 'exact_identifier_match:PMID:25921821', 'candidate_requires_review', 'B', 'L4', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:25921821; DOI:10.1016/j.spinee.2015.04.032; https://pubmed.ncbi.nlm.nih.gov/25921821/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMID25921821_pubmed.xml', 'The PubMed abstract reports that substance P increased proliferation of rat spinal cord-derived neural stem/progenitor cells in vitro and after SCI, that the NK1R antagonist L-703,606 reduced proliferation, and that phosphorylated ERK and p38 increased with substance P. The abstract supports an NK1-associated MAPK/progenitor functional program, but exact full-text assay details and figure-level controls are required before import-ready promotion.', 'The abstract supports a substance-P/NK1R-associated ERK/p38 proliferation response after SCI, but the full primary paper is required to validate exact receptor perturbation, cell-source context, pathway ordering, and any claim about a terminal TF. Do not promote the abstract into a canonical direct molecular or TF record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMID25921821_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000075' AND x.extraction_id='M24B-P2-R-RECOVERY-SP-NK1-SCI-NSPC-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000057', 'M24B-EVID-000078', 'M24B-P2-R-000078', 'PMID:18945947; PMID:25921821; PMCID:PMC2685299; DOI:10.1152/ajpregu.90653.2008; DOI:10.1016/j.spinee.2015.04.032', '18945947', 'literature_xml', 'exact_identifier_match:PMID:25921821', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMID:18945947; PMID:25921821; PMCID:PMC2685299; DOI:10.1152/ajpregu.90653.2008; DOI:10.1016/j.spinee.2015.04.032; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B282_substanceP_NK_SCI_pubmed.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMC2685299_substanceP_NK1.html', 'In adult rats with complete T9 spinal cord transection, Substance P immunoreactivity was increased in the L6-S1 sacral parasympathetic nucleus relative to intact rats. In conscious cystometry, intrathecal NK1 antagonist L-733060 at 30-100 micrograms blocked or reduced post-injury spinal micturition reflexes in most SCI rats, with little or no effect in intact controls.', 'Within the tested rat SCI bladder-reflex model, the authors support a bounded Substance P/Tacr1 (NK1) functional pathway: SP is increased after SCI and NK1 antagonism suppresses the post-injury micturition reflex. The abstract-only PMID25921821 ERK/p38 progenitor result is not transferred into this source unit.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch059_PMID25921821_pubmed.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000078' AND x.extraction_id='M24B-P2-R-000078');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000014', 'M24B-EVID-000014', 'M24B-P2-000014', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248', '16936276', 'full_text_html', 'exact_identifier_match:DOI:10.2353/ajpath.2006.060248;PMCID:PMC1698827', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248; https://europepmc.org/articles/PMC1698827; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC1698827_CR2_Crry_C3_SCI_fulltext.pdf', 'In female C57BL/6 mice with T12 weight-drop contusion SCI, deposited C3 and radiolabeled engineered CR2-Crry localized to the injury site; C3 deficiency or a single intravenous 0.25 mg CR2-Crry dose at 1 hour reduced neutrophil infiltration, tissue destruction/demyelination, and improved BBB locomotor recovery through the reported 21-day window. The study supports targeting/association of the CR2 domain with deposited C3 fragments in the engineered inhibitor context.', 'Promote the bounded engineered CR2-Crry targeting and C3-level complement-inhibition branch in mouse contusion SCI, including reduced neutrophil infiltration/tissue injury and improved locomotor recovery. Do not substitute intact C3 for a defined C3b/iC3b/C3d/C3dg ligand, do not treat CR2-Crry biodistribution as purified affinity, and do not infer an intracellular CR2 relay or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC1698827_C3_CR2-Crry.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000014' AND x.extraction_id='M24B-P2-000014');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000014', 'M24B-EVID-000014', 'M24B-P2-R-RECOVERY-C3FRAG-CR2CRRY-SCI-000001', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248', '16936276', 'full_text_html', 'exact_identifier_match:DOI:10.2353/ajpath.2006.060248;PMCID:PMC1698827', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248; https://pmc.ncbi.nlm.nih.gov/articles/PMC1698827/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC1698827_C3_CR2-Crry.html', 'After traumatic mouse SCI, C3-deficient animals had better BBB locomotor scores, more tissue sparing, and less necrosis, demyelination, and neutrophil infiltration than wild-type controls. A single intravenous dose of engineered CR2-Crry one hour after injury improved locomotor outcome and pathology similarly and localized to deposited C3 at the lesion. The paper supports C3-fragment engagement by the CR2 targeting domain and C3-level complement inhibition in SCI; it does not identify the exact endogenous fragment or establish a purified CR2-fragment affinity measurement.', 'The authors conclude that complement activation contributes to secondary SCI and that CR2-Crry targets deposited C3 fragments at the lesion to inhibit complement and improve recovery. The target is an engineered CR2-Crry receptor-like targeting domain, not an endogenous CR2 signaling pathway, and the exact C3 breakdown fragment remains unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC1698827_C3_CR2-Crry.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000014' AND x.extraction_id='M24B-P2-R-RECOVERY-C3FRAG-CR2CRRY-SCI-000001');
