INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000030', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC1698827_C3_CR2-Crry.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000030' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000031', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC1698827_C3_CR2-Crry.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000031' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000009', 'M24B-EVID-000004', 'M24B-P2-R-RECOVERY-LTB4-BLT1-SCI-000001', 'PMCID:PMC2861100; PMID:20304963; DOI:10.2353/ajpath.2010.090839', '20304963', 'full_text_html', 'exact_identifier_match:DOI:10.2353/ajpath.2010.090839;PMCID:PMC2861100', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2861100; PMID:20304963; DOI:10.2353/ajpath.2010.090839; https://pmc.ncbi.nlm.nih.gov/articles/PMC2861100/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC2861100_LTB4_BLT1.html', 'In adult mice with traumatic SCI, BLT1 knockout or repeated LTB4-receptor antagonist ONO-4057 reduced early leukocyte infiltration, inflammatory cytokine/chemokine expression, neural apoptosis, and white-matter loss, and improved locomotor recovery. The paper supports an LTB4-BLT1-dependent inflammatory amplification and functional branch in the injured cord; it does not provide purified LTB4-BLT1 affinity or a terminal TF assay.', 'The authors conclude that the LTB4-BLT1 axis amplifies leukocyte infiltration and secondary injury after SCI, while BLT1 loss or pharmacologic blockade attenuates inflammation, apoptosis, white-matter loss, and functional deficit. The registered edge is retained as an SCI receptor-associated pathway/functional record rather than a direct biochemical binding record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC2861100_LTB4_BLT1.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000004' AND x.extraction_id='M24B-P2-R-RECOVERY-LTB4-BLT1-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000034', 'M24B-EVID-000043', 'M24B-P2-R-000043', 'PMID:41407858; PMCID:PMC12823418; DOI:10.1038/s41586-025-09887-y', '41407858', 'full_text_html', 'exact_identifier_match:DOI:10.1038/s41586-025-09887-y;PMCID:PMC12823418', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_direct_molecular_support', 'PMID:41407858; PMCID:PMC12823418; DOI:10.1038/s41586-025-09887-y; https://pubmed.ncbi.nlm.nih.gov/41407858/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B274_CXCL5_XCL1_CCN1_pubmed.xml', 'The primary mouse incomplete-SCI study reports that secreted astrocyte-derived CCN1 binds microglial SDC4 and augments lipid storage, linking this interaction to debris-clearing microglial repair. Astrocyte Ccn1 depletion impaired debris processing and neurological recovery. The abstract explicitly states binding but does not provide full assay/figure details in this pass.', 'Promote the bounded direct molecular claim that astrocyte-derived CCN1 binds microglial SDC4 in the tested mouse incomplete-SCI white-matter repair context, while keeping the downstream lipid-buffering and debris-clearance branch separate.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC12823418_CCN1_SDC4.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000043' AND x.extraction_id='M24B-P2-R-000043');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000034', 'M24B-EVID-000043', 'M24B-P2-R-RECOVERY-CCN1-SDC4-SCI-000001', 'PMCID:PMC12823418; PMID:41407858; DOI:10.1038/s41586-025-09887-y', '41407858', 'full_text_html', 'exact_identifier_match:DOI:10.1038/s41586-025-09887-y;PMCID:PMC12823418', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC12823418; PMID:41407858; DOI:10.1038/s41586-025-09887-y; https://pmc.ncbi.nlm.nih.gov/articles/PMC12823418/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC12823418_CCN1_SDC4.html', 'In mouse incomplete SCI, lesion-remote white-matter astrocytes secreted CCN1 and neighboured debris-clearing microglia. CCN1-directed co-immunoprecipitation/proteomics identified SDC4 among candidate binding partners; recombinant CCN1 increased microglial lipid storage, and SDC4 function-blocking antibodies abolished that response. Astrocyte-specific Ccn1 depletion impaired debris clearance and neurological recovery. This supports a CCN1-SDC4 receptor-proximal/functional repair axis, while the co-IP is not a purified direct-affinity measurement.', 'The authors conclude that astrocyte-secreted CCN1 engages SDC4 on local microglia to promote lipid buffering and debris clearance in degenerating white matter, thereby supporting repair and neurological recovery after incomplete SCI. The direct molecular component is co-IP/proteomic partner identification plus receptor-blocking dependence, not purified binding or a terminal TF record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC12823418_CCN1_SDC4.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000043' AND x.extraction_id='M24B-P2-R-RECOVERY-CCN1-SDC4-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000035', 'M24B-EVID-000044', 'M24B-P2-R-000044', 'PMID:41407858; PMCID:PMC12823418; DOI:10.1038/s41586-025-09887-y', '41407858', 'full_text_html', 'exact_identifier_match:DOI:10.1038/s41586-025-09887-y;PMCID:PMC12823418', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_output', 'PMID:41407858; PMCID:PMC12823418; DOI:10.1038/s41586-025-09887-y; https://pubmed.ncbi.nlm.nih.gov/41407858/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B274_CXCL5_XCL1_CCN1_pubmed.xml', 'In the same mouse incomplete-SCI study, astrocyte CCN1 loss caused aberrant microglial activation, impaired myelin/axon-debris processing and lipid metabolism, and blunted neurological recovery. The author-reported CCN1-SDC4 interaction is the receptor-complex context, while these are downstream repair and functional outputs rather than additional direct binding observations.', 'Promote the CCN1-SDC4-associated microglial lipid-buffering, debris-clearance, and neurological-recovery branch in the tested incomplete-SCI model, keeping it distinct from the direct binding claim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC12823418_CCN1_SDC4.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000044' AND x.extraction_id='M24B-P2-R-000044');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000010', 'M24B-EVID-000005', 'M24B-P2-000005', 'PMCID:PMC2241786; PMID:18059327; DOI:10.1038/sj.bjp.0707577', '18059327', 'full_text_html', 'exact_identifier_match:DOI:10.1038/sj.bjp.0707577;PMCID:PMC2241786', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC2241786; PMID:18059327; DOI:10.1038/sj.bjp.0707577; https://europepmc.org/articles/PMC2241786; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B271_PMC2241786_5LO_CysLT1_SCI_fulltext.pdf', 'In male CD1 mice subjected to T6-T7 clip-compression SCI, zileuton or montelukast reduced inflammatory-cell infiltration, tissue injury, apoptosis-associated Bax/FasL changes, COX-2 expression, and ERK1/2 phosphorylation, while improving motor recovery in the reported treatment window. The paper also measured SCI-associated PGE2 and LTB4 increases and their reduction after drug treatment.', 'Promote the bounded 5-lipoxygenase/cysteinyl-leukotriene pathway modulation branch to ERK1/2, COX-2, apoptosis, inflammatory-cell, and locomotor outputs in this mouse SCI model. Do not infer a purified leukotriene-receptor interaction, BLT1 specificity, or a terminal TF from the pharmacology.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC2241786_lipid_mediator.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000005' AND x.extraction_id='M24B-P2-000005');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000010', 'M24B-EVID-000005', 'M24B-P2-R-RECOVERY-5LO-CYSLT-SCI-000001', 'PMCID:PMC2241786; PMID:18059327; DOI:10.1038/sj.bjp.0707577', '18059327', 'full_text_html', 'exact_identifier_match:DOI:10.1038/sj.bjp.0707577;PMCID:PMC2241786', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2241786; PMID:18059327; DOI:10.1038/sj.bjp.0707577; https://pmc.ncbi.nlm.nih.gov/articles/PMC2241786/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC2241786_lipid_mediator.html', 'In a mouse T6-T7 clip-compression SCI model, 5-LO inhibition with zileuton and Cys-LT1-directed pharmacology with montelukast reduced tissue edema and injury, neutrophil infiltration, TNF-alpha, COX-2, PGE2, LTB4, pERK1/2, and apoptosis, while improving limb-function recovery over 10 days. This supports a receptor-proximal/pathway and functional leukotriene/eicosanoid branch, but the pharmacology does not isolate a single endogenous ligand-receptor edge.', 'The authors conclude that 5-LO products and Cys-LT signaling contribute to inflammatory events and tissue injury after experimental SCI, and that zileuton or montelukast improves recovery. This remains a pathway/pharmacology record and does not establish a purified LTB4/CysLT1 binding edge or a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC2241786_lipid_mediator.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000005' AND x.extraction_id='M24B-P2-R-RECOVERY-5LO-CYSLT-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E002606', 'M22B-EVID-001551', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC4097186_Klk6_PAR.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-001551' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000073', 'M24B-EVID-000109', 'M24B-P2-R-RECOVERY-KLK6-PAR-SCI-000001', 'PMCID:PMC4097186; PMID:23647384; DOI:10.1111/jnc.12293', '23647384', 'full_text_html', 'exact_identifier_match:DOI:10.1111/jnc.12293;PMCID:PMC4097186', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4097186; PMID:23647384; DOI:10.1111/jnc.12293; https://pmc.ncbi.nlm.nih.gov/articles/PMC4097186/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC4097186_Klk6_PAR.html', 'In mouse clip-compression SCI, Klk6, thrombin, PAR1, and PAR2 were differentially elevated. Recombinant Klk6 triggered ERK1/2 in primary cerebellar granule neurons and NSC34 spinal motoneurons; PAR1 genetic deletion and PAR1/PAR2 lipopeptide inhibitors reduced the response, and PI3K or MEK inhibition suppressed ERK1/2 activation. Klk6 and thrombin promoted neuronal loss and enhanced glutamate neurotoxicity; in NSC34 motoneurons, Klk6 increased Bim, cleaved PARP, and LDH release in a PAR1/PAR2-inhibitor-sensitive manner. This validates a receptor-proximal PAR1/PAR2-PI3K/MEK-ERK neurotoxicity relay, not purified protease-receptor binding.', 'The authors conclude that Klk6 signals through PAR1 and PAR2 to activate ERK1/2 through PI3K and MEK and to exacerbate neuronal/glutamate neurotoxicity. The paper supports Klk6-specific receptor-proximal signaling and functional injury outputs but does not justify generic substitution of other proteases or a terminal TF claim.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch061_PMC4097186_Klk6_PAR.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000109' AND x.extraction_id='M24B-P2-R-RECOVERY-KLK6-PAR-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000005', 'M24B-EVID-000009', 'M24B-P2-000009', 'PMCID:PMC2718350', '19666625', 'full_text_html', 'exact_identifier_match:PMCID:PMC2718350', 'linked_unresolved', 'B', 'L1', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'PMCID:PMC2718350', 'Stable PMCID anchor is present, but no retained full-text Results/Methods/figure passage was available in the local cache; the registered Brilliant Blue G intervention summary is not sufficient for an atomic Observation.', 'No import-ready author claim; the B-layer pathway summary cannot be converted into a claim without the primary paper passage.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch097_PMC2718350_BBG_P2X7_SCI.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000009' AND x.extraction_id='M24B-P2-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000005', 'M24B-EVID-000009', 'M24B-P2-R-000009', 'PMCID:PMC2718350', '19666625', 'full_text_html', 'exact_identifier_match:PMCID:PMC2718350', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:15258577; PMCID:PMC2718350; DOI:10.1038/nm1082; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2718350_article.html', 'In rat T11-T12 weight-drop SCI, intravenous Brilliant Blue G at 10 or 50 mg/kg immediately after injury and on days 2-3 improved BBB motor recovery and reduced tissue loss. Immunohistochemistry at 4 days and 6 weeks showed reduced CD68-positive microglial activation, reactive astrocytosis, and neutrophil infiltration in treated animals.', 'The authors interpret BBG as a systemically deliverable P2X7R inhibitor that reduces purinergic excitotoxicity and inflammatory activation after traumatic SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch097_PMC2718350_BBG_P2X7_SCI.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000009' AND x.extraction_id='M24B-P2-R-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000005', 'M24B-EVID-000009', 'M24B-P2-R-000924', 'PMCID:PMC2718350', '19666625', 'full_text_html', 'exact_identifier_match:PMCID:PMC2718350', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMCID:PMC2718350; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Primary SCI paper retrieved; exact observation retained at source scope.', 'SCI phenotype is supported at the reported model scope; no direct terminal-TF edge was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch097_PMC2718350_BBG_P2X7_SCI.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000009' AND x.extraction_id='M24B-P2-R-000924');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000005', 'M24B-EVID-000009', 'M24B-P2-R-RECOVERY-BBG-P2X7-SCI-FULLTEXT-000001', 'PMCID:PMC2718350', '19666625', 'full_text_html', 'exact_identifier_match:PMCID:PMC2718350', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2718350; PMID:15258577; DOI:10.1038/nm1082; https://pmc.ncbi.nlm.nih.gov/articles/PMC2718350/; https://pubmed.ncbi.nlm.nih.gov/15258577/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch097_PMC2718350_BBG_P2X7_SCI.html', 'In a rat thoracic weight-drop SCI model, systemic Brilliant Blue G at 10 or 50 mg/kg beginning 15 minutes after injury and repeated for three total doses reduced lesion/tissue-loss volume and improved BBB hindlimb scores through six weeks. BBG also reduced Iba1/CD68 microglial activation, reactive gliosis, and MPO-positive neutrophil infiltration near the lesion. The paper supports an ATP-P2X7-associated receptor/pathway and downstream inflammatory-neuroprotective branch, but BBG is a pharmacologic antagonist with possible multiple cellular targets and is not a direct ATP-P2X7 binding assay.', 'The primary authors conclude that systemic P2X7-receptor inhibition with BBG reduces secondary spinal-cord injury, glial activation, and neutrophil invasion while improving motor recovery. This is receptor-associated pharmacology plus functional evidence; it does not establish purified ATP-P2X7 binding, a complete intracellular relay, or a terminal TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch097_PMC2718350_BBG_P2X7_SCI.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000009' AND x.extraction_id='M24B-P2-R-RECOVERY-BBG-P2X7-SCI-FULLTEXT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000004', 'M24B-EVID-000047', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch097_PMC2718350_BBG_P2X7_SCI.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000047' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000009', 'M24B-EVID-000004', 'M24B-P2-R-RECOVERY-LTB4-BLT1-SCI-000001', 'PMCID:PMC2861100; PMID:20304963; DOI:10.2353/ajpath.2010.090839', '20304963', 'full_text_html', 'exact_identifier_match:DOI:10.2353/ajpath.2010.090839;PMCID:PMC2861100', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2861100; PMID:20304963; DOI:10.2353/ajpath.2010.090839; https://pmc.ncbi.nlm.nih.gov/articles/PMC2861100/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC2861100_LTB4_BLT1.html', 'In adult mice with traumatic SCI, BLT1 knockout or repeated LTB4-receptor antagonist ONO-4057 reduced early leukocyte infiltration, inflammatory cytokine/chemokine expression, neural apoptosis, and white-matter loss, and improved locomotor recovery. The paper supports an LTB4-BLT1-dependent inflammatory amplification and functional branch in the injured cord; it does not provide purified LTB4-BLT1 affinity or a terminal TF assay.', 'The authors conclude that the LTB4-BLT1 axis amplifies leukocyte infiltration and secondary injury after SCI, while BLT1 loss or pharmacologic blockade attenuates inflammation, apoptosis, white-matter loss, and functional deficit. The registered edge is retained as an SCI receptor-associated pathway/functional record rather than a direct biochemical binding record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch097_PMC2861100_LTB4_BLT1_SCI.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000004' AND x.extraction_id='M24B-P2-R-RECOVERY-LTB4-BLT1-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_PMC11437233_HMGB1_TLR_CCL5_SCI.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-000006', 'PMID:32964315', '32964315', 'literature_xml', 'exact_identifier_match:PMID:32964315', 'linked_unresolved', 'B', 'L4', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', 'Stable PMID and DOI anchor are present, but no retained abstract or full-text Results/Methods/figure passage was available in the local cache; the registered RvD3 resolution/neuroprotection summary is not sufficient for an atomic Observation.', 'No import-ready author claim; the B-layer summary cannot be converted into a claim without the primary paper passage.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-000006', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', '32964315', 'literature_xml', 'exact_identifier_match:PMID:32964315', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text', 'validated_author_claim', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7; https://link.springer.com/article/10.1007/s12035-020-02118-7; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B002_PMID32964315_RvD3_SCI_fulltext.pdf', 'In female C57BL/6 mice with T10 weight-compression SCI (20 g for 1 minute), a single intrathecal RvD3 injection (1 microgram/20 microliters at 1 hour) improved BMS locomotor recovery, reduced thermal hyperalgesia and lesion area, lowered inflammatory cytokine/chemokine expression, shifted macrophage markers toward an M2-associated pattern, preserved tight-junction proteins, and reduced glial/fibrotic scar markers. In LPS-treated RAW264.7 cells and hCMEC/D3 endothelial cells, RvD3 reduced inflammatory/NO outputs and increased migration or angiogenic-associated markers.', 'Promote the bounded RvD3 downstream functional branch for inflammatory resolution, neuroprotection, pain reduction, barrier preservation, and locomotor recovery in this mouse SCI model. Do not infer a cognate receptor, receptor-proximal relay, or terminal TF: the authors explicitly state that the detailed G-protein receptor mechanism was not investigated and that unique RvD3/RvD4 receptors remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-000921', 'PMID:32964315', '32964315', 'literature_xml', 'exact_identifier_match:PMID:32964315', 'supporting_validated_claim', 'B', 'L4', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMID:32964315; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Primary SCI paper retrieved; exact observation retained at source scope.', 'SCI phenotype is supported at the reported model scope; no direct terminal-TF edge was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-000921');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-RECOVERY-RVD3-SCI-ABSTRACT-000001', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', '32964315', 'literature_xml', 'exact_identifier_match:PMID:32964315', 'candidate_requires_review', 'B', 'L4', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7; https://pubmed.ncbi.nlm.nih.gov/32964315/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml', 'In female C57BL/6 mice subjected to moderate compression SCI, intrathecal RvD3 at 1 microgram/20 microliters one hour after injury improved locomotor recovery and reduced thermal hyperalgesia at 14 days. RvD3 treatment reduced TNF-alpha, IL6, IL1beta, CCL2, and CCL3, increased ZO-1 and occludin, reduced GFAP/Iba1 gliosis and CD68/TGF-beta neuroinflammation, and enhanced neuroprotection. In RAW264.7 cells and hCMEC/D3 cells, RvD3 reduced LPS-induced inflammatory mediators/NO and promoted angiogenic responses.', 'The primary authors conclude that RvD3 promotes inflammatory resolution, neuroprotection, barrier-associated protein expression, and neurological recovery after experimental SCI. The record supports downstream function only; no RvD3 receptor, intracellular relay, or terminal TF was established in the retrieved primary abstract.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-RECOVERY-RVD3-SCI-ABSTRACT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000178', '', '', NULL, 'literature_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000178' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000004', 'M24B-EVID-000008', 'M24B-P2-R-RECOVERY-P2X7-ATP-SCI-ABSTRACT-000001', 'PMID:15258577; DOI:10.1038/nm1082', '15258577', 'literature_xml', 'exact_identifier_match:PMID:15258577', 'candidate_requires_review', 'B', 'L2', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:15258577; DOI:10.1038/nm1082; https://pubmed.ncbi.nlm.nih.gov/15258577/; https://doi.org/10.1038/nm1082; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch099_pubmed_15258577.xml', 'In rats after acute impact SCI, the primary abstract reports sustained high ATP release in the peritraumatic zone, P2X7R expression in spinal cord neurons, and ATP-induced high-frequency spiking, irreversible cytosolic calcium elevation, and neuronal death. Intraspinal OxATP or PPADS after injury improved functional recovery and reduced peritraumatic cell death. This supports an ATP/P2X7-associated excitotoxic pathway and functional branch, but not purified ATP-P2X7 binding.', 'The primary authors conclude that prolonged purinergic receptor activation after SCI contributes to excitotoxic neuronal degeneration and that P2X7R antagonists reduce histological and functional sequelae. This is receptor-associated pharmacology and downstream function, not a direct biochemical binding record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch099_pubmed_15258577.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000008' AND x.extraction_id='M24B-P2-R-RECOVERY-P2X7-ATP-SCI-ABSTRACT-000001');
