INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_pdf', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M21B_RYK_astrocyte_SCI_fulltext.pdf' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000138', 'M22B-EVID-000036', 'M22B-P2-R-000012', 'PMCID:PMC2080618; PMID:16597617; DOI:10.1074/jbc.M601252200', '16597617', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m601252200;PMCID:PMC2080618', 'candidate_requires_review', 'U', 'L0', 'unresolved', 'unknown_after_primary_review', 'PMCID:PMC2080618; PMID:16597617; DOI:10.1074/jbc.M601252200; https://pmc.ncbi.nlm.nih.gov/articles/PMC2080618/; https://pubmed.ncbi.nlm.nih.gov/16597617/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC2080618_article.html', 'The official primary article for PMCID:PMC2080618 is titled “Receptor Specificity of the Fibroblast Growth Factor Family: The Complete Mammalian FGF Family.” Its complete PMC text reports FGF-family/FGFR receptor-specific BaF3 mitogenic assays and general FGF-FGFR activation context, but it contains no FGF5 experiment and no measured CREB, c-FOS, or STAT3 pathway/target-gene result matching the registered FGF5-FGFR1 handoff. The cited paper therefore cannot support the queued CREB/c-FOS/STAT3 claim.', 'Leave the registered FGF5-FGFR1-to-CREB/c-FOS/STAT3 program unknown. Do not substitute this FGF-family receptor-specificity paper, its general FGF-FGFR statements, or its unrelated ligand assays for the exact FGF5 handoff or infer a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC2080618_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000036' AND x.extraction_id='M22B-P2-R-000012');
