INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000553', 'M22B-EVID-005435', 'M22B-P2-R-000817', 'PMCID:PMC2080618', '16597617', 'full_text_html', 'exact_identifier_match:PMCID:PMC2080618', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC2080618; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC2080618_full.xml', 'Primary source PMCID:PMC2080618 reports the tested receptor/proximal or functional observation at its model scope; no stronger terminal-TF edge is inferred.', 'The source supports a bounded receptor/pathway or functional association; no direct TF occupancy or terminal target locus was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC2080618_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005435' AND x.extraction_id='M22B-P2-R-000817');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000554', 'M22B-EVID-005436', 'M22B-P2-R-000818', 'PMCID:PMC2080618', '16597617', 'full_text_html', 'exact_identifier_match:PMCID:PMC2080618', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_PATHWAY_FUNCTION_BOUNDED', 'PMCID:PMC2080618; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch066_PMC2080618_full.xml', 'Primary source PMCID:PMC2080618 reports the tested receptor/proximal or functional observation at its model scope; no stronger terminal-TF edge is inferred.', 'The source supports a bounded receptor/pathway or functional association; no direct TF occupancy or terminal target locus was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC2080618_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-005436' AND x.extraction_id='M22B-P2-R-000818');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000015', 'M22B-EVID-000133', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000133' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000234', 'M22B-EVID-000134', 'M22B-P2-R-000014A', 'PMCID:PMC3235522; PMID:21316586; DOI:10.1016/j.devcel.2011.01.002', '21316586', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.devcel.2011.01.002;PMCID:PMC3235522', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3235522; PMID:21316586; DOI:10.1016/j.devcel.2011.01.002; https://pmc.ncbi.nlm.nih.gov/articles/PMC3235522/; https://pubmed.ncbi.nlm.nih.gov/21316586/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html', 'In dissociated mouse commissural neurons, 30-minute Wnt5a stimulation increased phospho-Jun approximately fourfold without changing total Fzd3 or Vangl2 abundance. In rat E13 open-book explants, JNK inhibitor-I or SP600125 reduced the fraction of correctly guided commissural axons from approximately 91% to approximately 39% and randomized anterior-posterior projections. The result supports a WNT5A-FZD3/Vangl2-associated JNK-to-c-Jun relay and its requirement for axon guidance; it is not a purified Wnt5a-Fzd3 binding assay or direct c-JUN target-gene measurement.', 'The authors conclude that Wnt5a activates JNK signaling in commissural neurons and that JNK activity is required for correct anterior-posterior commissural axon guidance.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000134' AND x.extraction_id='M22B-P2-R-000014A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000234', 'M22B-EVID-000134', 'M22B-P2-R-000014B', 'PMCID:PMC3235522; PMID:21316586; DOI:10.1016/j.devcel.2011.01.002', '21316586', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.devcel.2011.01.002;PMCID:PMC3235522', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC3235522; PMID:21316586; DOI:10.1016/j.devcel.2011.01.002; https://pmc.ncbi.nlm.nih.gov/articles/PMC3235522/; https://pubmed.ncbi.nlm.nih.gov/21316586/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html', 'In HEK293T cells, Wnt5a plus Fzd3 increased phospho-Jun; coexpression of Fzd3 with Dvl1 reduced Wnt5a-stimulated phospho-Jun, whereas Vangl2 prolonged the signal and Vangl2 shRNA abolished Wnt5a-stimulated planar-cell-polarity signaling. These experiments support a Fzd3/Dvl1/Vangl2 receptor-complex/pathway branch upstream of JNK/c-Jun and an associated commissural-axon-growth output, while remaining distinct from a direct Wnt5a-Fzd3 affinity measurement.', 'The authors conclude that Fzd3 and Vangl2 mediate Wnt5a-stimulated PCP-like signaling and that Vangl2 antagonizes Dvl1-mediated feedback inhibition, thereby sustaining the JNK/c-Jun signal associated with commissural axon growth.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000134' AND x.extraction_id='M22B-P2-R-000014B');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000235', 'M22B-EVID-000135', 'M22B-P2-R-000142', 'PMCID:PMC3235522', '21316586', 'full_text_html', 'exact_identifier_match:PMCID:PMC3235522', 'candidate_requires_review', NULL, 'L1', 'validated_primary_observation', 'REUSE_FUNCTIONAL_CONTEXT', 'PMCID:PMC3235522; https://pmc.ncbi.nlm.nih.gov/articles/PMC3235522/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch070_PMC3235522_bioc.json', 'Reuse the validated Wnt5a-Fzd3/Vangl2-JNK spinal commissural-neuron observation for the distinct axon-guidance phenotype handoff: disruption of Vangl2, Celsr3, Fzd3, or JNK activity randomized post-crossing axon trajectories and reduced Wnt5a-stimulated outgrowth. No direct c-Jun target gene is assigned.', 'Reuse WNT5A-FZD3/Vangl2-JNK axon-guidance evidence for the distinct spinal phenotype handoff, preserving the pathway/phenotype distinction and no direct c-Jun target inference.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000135' AND x.extraction_id='M22B-P2-R-000142');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000239', 'M22B-EVID-000136', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC3235522_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000136' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000355', 'M22B-EVID-000085', 'M22B-P2-R-000013', 'PMCID:PMC4023255; PMID:18322278; DOI:10.1095/biolreprod.107.066605', '18322278', 'full_text_html', 'exact_identifier_match:DOI:10.1095/biolreprod.107.066605;PMCID:PMC4023255', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC4023255; PMID:18322278; DOI:10.1095/biolreprod.107.066605; https://pmc.ncbi.nlm.nih.gov/articles/PMC4023255/; https://pubmed.ncbi.nlm.nih.gov/18322278/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC4023255_article.html', 'In mouse Müllerian-duct mesenchyme, Amhr2-Cre conditional genetics showed redundant type-I-receptor and receptor-Smad requirements for AMH-induced Müllerian duct regression. Acvr1 loss alone allowed regression, Bmpr1a loss caused retention in approximately 55% of males, and combined Acvr1/Bmpr1a loss caused complete retention in all tested males (n=10). Smad1 or Smad1/Smad8 loss did not block regression, Smad5-containing combinations caused partial retention, and combined Smad1/Smad5/Smad8 loss caused complete retention in all tested males (n=4; Figs. 1-4; Tables 1-2). The study supports an AMHR2-associated ACVR1/BMPR1A-to-SMAD1/5/8 pathway and a Müllerian-duct regression output, not a purified AMH-receptor binding assay or a direct SMAD target-gene occupancy record.', 'The authors conclude that AMH uses redundant ACVR1 and BMPR1A type-I receptors and redundant SMAD1, SMAD5, and SMAD8 receptor-Smads to activate Müllerian duct regression in the mouse. They propose Mmp2 and possibly a Wnt as downstream transcriptional targets, but explicitly identify future target-gene work; this paper does not establish direct SMAD occupancy at either target.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC4023255_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000085' AND x.extraction_id='M22B-P2-R-000013');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000362', 'M22B-EVID-000086', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', NULL, 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC4023255_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000086' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000369', 'M22B-EVID-000087', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_M22B_PMC4023255_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000087' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000007', 'M24B-P2-000007', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971', '37446149', 'full_text_html', 'exact_identifier_match:DOI:10.3390/ijms241310971;PMCID:PMC10341423', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971; https://europepmc.org/articles/PMC10341423; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf', 'In Sprague-Dawley rats with T9 compressive SCI, a single post-injury administration of RvD1 (0.1 microgram) combined with peripheral-nerve-derived stem-cell spheroids improved BBB locomotion, ladder-rung performance, tissue regeneration/remyelination measures, and mechanical allodynia relative to injury controls and monotherapy groups. In LPS-stimulated PNSC spheroids, RvD1 reduced TNF-alpha, IL-1beta, and NF-kappaB protein signals and increased IL-10 and TGF-beta transcripts.', 'Promote the bounded RvD1-plus-PNSC combination-therapy functional branch in the reported rat SCI model, including anti-inflammatory marker changes and locomotor/tissue-regeneration outputs. Do not infer that RvD1 alone caused the combination effect, do not promote ALX/FPR2 as directly tested in this paper, and do not assign a terminal TF beyond the measured NF-kappaB protein signal.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC10341423_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000007' AND x.extraction_id='M24B-P2-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000007', 'M24B-P2-R-000007', 'PMID:37446149', '37446149', 'full_text_html', 'exact_identifier_match:PMCID:PMC10341423', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:37446149; PMCID:PMC10341423; DOI:10.1007/s12035-020-02118-7; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC10341423_article.html', 'In vitro RvD1 treatment of LPS-stimulated peripheral nerve-derived stem-cell spheroids reduced TNF-alpha, IL-1beta, and NF-kB and increased IL-10/TGF-beta at selected concentrations. In a rat compressive SCI model, the RvD1 plus spheroid combination produced the strongest BBB/laddder-rung recovery and reduced inflammatory markers compared with vehicle and monotherapy groups.', 'The authors interpret combined RvD1 and PNSC spheroid treatment as a therapeutic strategy that enhances neuronal regeneration and anti-inflammatory recovery after SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC10341423_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000007' AND x.extraction_id='M24B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000012', 'M24B-P2-000012', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971', '37446149', 'full_text_html', 'exact_identifier_match:DOI:10.3390/ijms241310971;PMCID:PMC10341423', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971; https://europepmc.org/articles/PMC10341423; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf', 'The same full-text primary paper supports reuse of the validated RvD1-plus-PNSC combination-therapy observation on the duplicate B evidence record: rat T9 compressive SCI functional/tissue-regeneration outputs and LPS-stimulated PNSC-spheroid inflammatory marker changes are documented in Results, Figures 1-3, and Methods 4.4-4.8.', 'Reuse the bounded author claim from M24B-P2-000007 for this separate evidence record; no duplicate observation is created. Direct RvD1-receptor binding, receptor-proximal relay, ALX/FPR2 causality, and terminal-TF occupancy remain unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC10341423_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000012' AND x.extraction_id='M24B-P2-000012');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC10517332_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E005026', 'M22B-EVID-003100', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC11039321_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-003100' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000047', 'M21B-EVID-000011', 'M21B-P2-R-000011', 'PMCID:PMC1137045; PMID:7519847', '7519847', 'full_text_html', 'exact_identifier_match:DOI:10.1042/bj3010703;PMCID:PMC1137045', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1137045; PMID:7519847; DOI:10.1042/bj3010703; https://europepmc.org/articles/PMC1137045?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PDGF_PI3K_fulltext_7519847.pdf', 'In quiescent NIH-3T3 fibroblasts, PDGF stimulation induced rapid, transient association of PI3-K with the activated PDGF receptor, detectable within 1 minute and maximal at 5 minutes, with a correlated transient increase in intrinsic PI3-K activity (Fig. 5A-D). Reconstitution and kinase assays showed that the PDGF receptor phosphorylated both p85alpha and p110 when the p85alpha-p110 complex was present (Fig. 2A-D), while receptor immunoprecipitates from PDGF-stimulated NIH-3T3 cells contained a p110 product phosphorylated predominantly on tyrosine (Fig. 3A-C). Tyrosine phosphorylation of p110 was detected in vivo after PDGF stimulation and persisted while receptor association declined (Fig. 6A-B); receptor immunodepletion showed release of tyrosine-phosphorylated p110 (Fig. 7A-B).', 'The authors conclude that the PDGF receptor activates PI3-K in vivo through rapid enzyme relocation/recruitment and increased intrinsic activity, and that receptor tyrosine phosphorylation of p110 may regulate PI3-K in some circumstances. The paper supports a receptor-proximal PDGFR-PI3K relay, not a complete PDGFR-to-AKT/ERK or SCI functional chain.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC1137045_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000011' AND x.extraction_id='M21B-P2-R-000011');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000034;M21B-E000035;M21B-E000036', 'M21B-EVID-000007', 'M21B-P2-R-000007', 'PMCID:PMC1170167; PMID:9311995', '9311995', 'full_text_html', 'exact_identifier_match:DOI:10.1093/emboj/16.17.5353;PMCID:PMC1170167', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1170167; PMID:9311995; DOI:10.1093/emboj/16.17.5353; https://europepmc.org/articles/PMC1170167?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_TGFBR_SMAD_fulltext_9311995.pdf', 'In TGF-beta1-treated Mv1Lu mink lung epithelial cells, endogenous Smad2 and Smad3 phosphorylation increased (Fig. 3A-B), while Smad4 was constitutively phosphorylated (Fig. 3C). In transfected COS systems, Smad2 and Smad3 associated with kinase-inactive TbetaR-I after TbetaR-II-dependent receptor activation (Fig. 4), Smad2/Smad3 associated with Smad4 after TbetaR-I activation or TGF-beta1 treatment (Fig. 5A-D), and receptor activation increased Smad2-Smad3 association (Fig. 6A-B). TGF-beta1 drove nuclear accumulation of Smad2, Smad3, and Smad4 in Mv1Lu cells (Fig. 7A-F), and Smad2/3/4 combinations produced synergistic p3TPLux transcriptional reporter activity that was inhibited by dominant-negative Smad3 (Fig. 8A-B).', 'The authors conclude that TGF-beta receptor activation phosphorylates Smad2/3, promotes Smad2/3/4 heteromeric complex formation and nuclear translocation, and requires their combined activity for efficient TGF-beta transcriptional signaling. This is receptor-proximal and downstream pathway evidence, not a purified TGF-beta receptor-ligand affinity assay, a unique terminal target-gene occupancy result, or an SCI receiver-cell effect.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC1170167_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000007' AND x.extraction_id='M21B-P2-R-000007');
