INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_or_bioc_json', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC1447428_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E001018', 'M23B-EVID-000118', 'M23B-P2-R-000118', 'PMID:10982388; PMCID:PMC14963; DOI:10.1091/mbc.11.9.2885; PMID:10196234; DOI:10.1074/jbc.274.16.11408', '10982388', 'full_text_xml', 'exact_identifier_match:PMCID:PMC14963', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:10982388; PMCID:PMC14963; DOI:10.1091/mbc.11.9.2885; PMID:10196234; DOI:10.1074/jbc.274.16.11408; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC14963.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC14963/', 'In cultured endothelial cells, loss of cell-cell contact or CD98 ligation activated recognition of TSP1 and a TSP1 alpha3beta1-binding peptide. Alpha3beta1 mediated spreading on TSP1 substrates only in the activated/sparse state; alpha3beta1 blockade inhibited migration, and soluble TSP1 peptide inhibited endothelial migration and chick chorioallantoic membrane angiogenesis. The paper supports a context-dependent alpha3beta1 receptor-proximal adhesion/migration relay.', 'The primary study establishes that endothelial-cell state controls alpha3beta1 recognition of TSP1 and that this receptor contributes to TSP1-dependent spreading, proliferation, migration, and angiogenic output. It does not establish a purified TSP1-alpha3beta1 affinity measurement or identify a complete intracellular relay/TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC14963.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000118' AND x.extraction_id='M23B-P2-R-000118');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000014', 'M24B-EVID-000014', 'M24B-P2-000014', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248', '16936276', 'full_text_html', 'exact_identifier_match:DOI:10.2353/ajpath.2006.060248;PMCID:PMC1698827', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248; https://europepmc.org/articles/PMC1698827; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC1698827_CR2_Crry_C3_SCI_fulltext.pdf', 'In female C57BL/6 mice with T12 weight-drop contusion SCI, deposited C3 and radiolabeled engineered CR2-Crry localized to the injury site; C3 deficiency or a single intravenous 0.25 mg CR2-Crry dose at 1 hour reduced neutrophil infiltration, tissue destruction/demyelination, and improved BBB locomotor recovery through the reported 21-day window. The study supports targeting/association of the CR2 domain with deposited C3 fragments in the engineered inhibitor context.', 'Promote the bounded engineered CR2-Crry targeting and C3-level complement-inhibition branch in mouse contusion SCI, including reduced neutrophil infiltration/tissue injury and improved locomotor recovery. Do not substitute intact C3 for a defined C3b/iC3b/C3d/C3dg ligand, do not treat CR2-Crry biodistribution as purified affinity, and do not infer an intracellular CR2 relay or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC1698827_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000014' AND x.extraction_id='M24B-P2-000014');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000014', 'M24B-EVID-000014', 'M24B-P2-R-RECOVERY-C3FRAG-CR2CRRY-SCI-000001', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248', '16936276', 'full_text_html', 'exact_identifier_match:DOI:10.2353/ajpath.2006.060248;PMCID:PMC1698827', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1698827; PMID:16936276; DOI:10.2353/ajpath.2006.060248; https://pmc.ncbi.nlm.nih.gov/articles/PMC1698827/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC1698827_C3_CR2-Crry.html', 'After traumatic mouse SCI, C3-deficient animals had better BBB locomotor scores, more tissue sparing, and less necrosis, demyelination, and neutrophil infiltration than wild-type controls. A single intravenous dose of engineered CR2-Crry one hour after injury improved locomotor outcome and pathology similarly and localized to deposited C3 at the lesion. The paper supports C3-fragment engagement by the CR2 targeting domain and C3-level complement inhibition in SCI; it does not identify the exact endogenous fragment or establish a purified CR2-fragment affinity measurement.', 'The authors conclude that complement activation contributes to secondary SCI and that CR2-Crry targets deposited C3 fragments at the lesion to inhibit complement and improve recovery. The target is an engineered CR2-Crry receptor-like targeting domain, not an endogenous CR2 signaling pathway, and the exact C3 breakdown fragment remains unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC1698827_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000014' AND x.extraction_id='M24B-P2-R-RECOVERY-C3FRAG-CR2CRRY-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000028', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC1698827_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000028' AND x.extraction_id='');
