INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E003968', 'M22B-EVID-002380', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2199199.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002380' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E001020', 'M23B-EVID-000120', 'M23B-P2-R-000120', 'PMID:11257118; PMCID:PMC2199199; DOI:10.1083/jcb.152.6.1169; PMID:8601596; PMCID:PMC2120752; DOI:10.1083/jcb.132.6.1209', NULL, 'full_text_xml', 'exact_identifier_match:PMCID:PMC2199199', 'candidate_requires_review', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:11257118; PMCID:PMC2199199; DOI:10.1083/jcb.152.6.1169; PMID:8601596; PMCID:PMC2120752; DOI:10.1083/jcb.132.6.1209; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2199199.xml; data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2120752.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC2199199/; https://pmc.ncbi.nlm.nih.gov/articles/PMC2120752/', 'The primary syndecan-1 studies support a TSP1-syndecan-1 adhesion relay. Syndecan-1 expression in COS-7 cells enabled spreading, fascin-spike assembly, and ruffling on TSP1; GAG modification at syndecan-1 residues S45/S47 and the VC2 cytoplasmic region were required for specified outputs. In C2C12 cells, syndecan-1 VC2 deletion or GAG-negative mutants impaired TSP1-dependent spreading/fascin spikes. Independent Raji-cell transfection showed syndecan-1-dependent binding/spreading on immobilized thrombospondin, with spreading mediated by the core protein and cytoskeletal inhibitors blocking the output.', 'The primary studies support a receptor-proximal TSP1-syndecan-1 relay in which heparan-sulfate/GAG-modified syndecan-1 couples matrix engagement to cell spreading, cortical actin organization, fascin spikes, and membrane ruffling. These studies do not establish a purified TSP1-syndecan-1 affinity value, a unique intracellular kinase cascade, or a TF endpoint.', 'The observation and claim are validated, but the Phase-2 paper identity resolver did not establish one PMID for this artifact/extraction pair. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2199199.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000120' AND x.extraction_id='M23B-P2-R-000120');
