tive_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2241786_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000005' AND x.extraction_id='M24B-P2-R-RECOVERY-5LO-CYSLT-SCI-000001');
