INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000760', 'M23B-EVID-001024', 'P2FALLBACK-23B-M23B-EVID-001024', 'URL:https://pmc.ncbi.nlm.nih.gov/articles/PMC2692383/', '7541634', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2692383', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2692383/', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2692383.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001024' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-001024');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000032', 'M22B-EVID-000192', 'M22B-P2-R-000015A', 'PMCID:PMC2696635; PMID:19401592; DOI:10.1126/scisignal.2000188', '19401592', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2696635', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2696635; PMID:19401592; DOI:10.1126/scisignal.2000188; https://pmc.ncbi.nlm.nih.gov/articles/PMC2696635/; https://pubmed.ncbi.nlm.nih.gov/19401592/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch076_PMC2696635_full.xml', 'In PC12 cells, activated full-length human alpha2-macroglobulin and its LRP1-binding domain induced Trk phosphorylation and ERK1/2 and Akt activation. LRP1 antagonism with receptor-associated protein, LRP1-specific siRNA, TrkA inhibition or silencing, and Src-family-kinase inhibition each blocked the relevant relay, supporting an activated-alpha2M-to-LRP1-to-SFK-to-TrkA-to-ERK/Akt pathway. The paper does not measure CREB phosphorylation or direct CREB target occupancy.', 'The authors conclude that activated alpha2M and other LRP1 ligands transactivate Trk receptors through an LRP1- and Src-family-kinase-dependent pathway, thereby activating Akt and ERK1/2 in PC12 cells.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2696635.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000192' AND x.extraction_id='M22B-P2-R-000015A');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000032', 'M22B-EVID-000192', 'M22B-P2-R-000015B', 'PMCID:PMC2696635; PMID:19401592; DOI:10.1126/scisignal.2000188', '19401592', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2696635', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2696635; PMID:19401592; DOI:10.1126/scisignal.2000188; https://pmc.ncbi.nlm.nih.gov/articles/PMC2696635/; https://pubmed.ncbi.nlm.nih.gov/19401592/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch076_PMC2696635_full.xml', 'In rat cerebellar granular neurons and PC12 cells, the alpha2M receptor-binding domain increased neurite outgrowth over 48 hours; the response was blocked by receptor-associated protein, the Trk inhibitor K252a, or the Src-family inhibitor PP2. In adult rat dorsal-root ganglia, direct alpha2M receptor-binding-domain injection induced Trk phosphorylation that was blocked by receptor-associated protein. These are functional and in-vivo receptor-proximal outputs downstream of LRP1 ligand engagement, not a direct alpha2M-LRP1 binding assay or a terminal CREB target readout.', 'The authors conclude that LRP1 ligand binding can drive Trk receptor activation and neurite outgrowth through Src-family kinases, establishing a neurotrophic functional output downstream of LRP1.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2696635.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000192' AND x.extraction_id='M22B-P2-R-000015B');
