INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000005', 'M24B-EVID-000009', 'M24B-P2-000009', 'PMCID:PMC2718350', '19666625', 'full_text_html', 'exact_identifier_match:PMCID:PMC2718350', 'linked_unresolved', 'B', 'L1', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'PMCID:PMC2718350', 'Stable PMCID anchor is present, but no retained full-text Results/Methods/figure passage was available in the local cache; the registered Brilliant Blue G intervention summary is not sufficient for an atomic Observation.', 'No import-ready author claim; the B-layer pathway summary cannot be converted into a claim without the primary paper passage.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2718350_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000009' AND x.extraction_id='M24B-P2-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000005', 'M24B-EVID-000009', 'M24B-P2-R-000009', 'PMCID:PMC2718350', '19666625', 'full_text_html', 'exact_identifier_match:PMCID:PMC2718350', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:15258577; PMCID:PMC2718350; DOI:10.1038/nm1082; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2718350_article.html', 'In rat T11-T12 weight-drop SCI, intravenous Brilliant Blue G at 10 or 50 mg/kg immediately after injury and on days 2-3 improved BBB motor recovery and reduced tissue loss. Immunohistochemistry at 4 days and 6 weeks showed reduced CD68-positive microglial activation, reactive astrocytosis, and neutrophil infiltration in treated animals.', 'The authors interpret BBG as a systemically deliverable P2X7R inhibitor that reduces purinergic excitotoxicity and inflammatory activation after traumatic SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2718350_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000009' AND x.extraction_id='M24B-P2-R-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000005', 'M24B-EVID-000009', 'M24B-P2-R-000924', 'PMCID:PMC2718350', '19666625', 'full_text_html', 'exact_identifier_match:PMCID:PMC2718350', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMCID:PMC2718350; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Primary SCI paper retrieved; exact observation retained at source scope.', 'SCI phenotype is supported at the reported model scope; no direct terminal-TF edge was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2718350_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000009' AND x.extraction_id='M24B-P2-R-000924');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000005', 'M24B-EVID-000009', 'M24B-P2-R-RECOVERY-BBG-P2X7-SCI-FULLTEXT-000001', 'PMCID:PMC2718350', '19666625', 'full_text_html', 'exact_identifier_match:PMCID:PMC2718350', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2718350; PMID:15258577; DOI:10.1038/nm1082; https://pmc.ncbi.nlm.nih.gov/articles/PMC2718350/; https://pubmed.ncbi.nlm.nih.gov/15258577/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch097_PMC2718350_BBG_P2X7_SCI.html', 'In a rat thoracic weight-drop SCI model, systemic Brilliant Blue G at 10 or 50 mg/kg beginning 15 minutes after injury and repeated for three total doses reduced lesion/tissue-loss volume and improved BBB hindlimb scores through six weeks. BBG also reduced Iba1/CD68 microglial activation, reactive gliosis, and MPO-positive neutrophil infiltration near the lesion. The paper supports an ATP-P2X7-associated receptor/pathway and downstream inflammatory-neuroprotective branch, but BBG is a pharmacologic antagonist with possible multiple cellular targets and is not a direct ATP-P2X7 binding assay.', 'The primary authors conclude that systemic P2X7-receptor inhibition with BBG reduces secondary spinal-cord injury, glial activation, and neutrophil invasion while improving motor recovery. This is receptor-associated pharmacology plus functional evidence; it does not establish purified ATP-P2X7 binding, a complete intracellular relay, or a terminal TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2718350_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000009' AND x.extraction_id='M24B-P2-R-RECOVERY-BBG-P2X7-SCI-FULLTEXT-000001');
