INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000009', 'M24B-EVID-000004', 'M24B-P2-R-RECOVERY-LTB4-BLT1-SCI-000001', 'PMCID:PMC2861100; PMID:20304963; DOI:10.2353/ajpath.2010.090839', '20304963', 'full_text_html', 'exact_identifier_match:DOI:10.2353/ajpath.2010.090839;PMCID:PMC2861100', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2861100; PMID:20304963; DOI:10.2353/ajpath.2010.090839; https://pmc.ncbi.nlm.nih.gov/articles/PMC2861100/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC2861100_LTB4_BLT1.html', 'In adult mice with traumatic SCI, BLT1 knockout or repeated LTB4-receptor antagonist ONO-4057 reduced early leukocyte infiltration, inflammatory cytokine/chemokine expression, neural apoptosis, and white-matter loss, and improved locomotor recovery. The paper supports an LTB4-BLT1-dependent inflammatory amplification and functional branch in the injured cord; it does not provide purified LTB4-BLT1 affinity or a terminal TF assay.', 'The authors conclude that the LTB4-BLT1 axis amplifies leukocyte infiltration and secondary injury after SCI, while BLT1 loss or pharmacologic blockade attenuates inflammation, apoptosis, white-matter loss, and functional deficit. The registered edge is retained as an SCI receptor-associated pathway/functional record rather than a direct biochemical binding record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2861100_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000004' AND x.extraction_id='M24B-P2-R-RECOVERY-LTB4-BLT1-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000009', 'M24B-EVID-000004', 'M24B-P2-R-RECOVERY-LTB4-BLT1-SCI-000001', 'PMCID:PMC2861100; PMID:20304963; DOI:10.2353/ajpath.2010.090839', '20304963', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC2861100', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2861100; PMID:20304963; DOI:10.2353/ajpath.2010.090839; https://pmc.ncbi.nlm.nih.gov/articles/PMC2861100/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch060_PMC2861100_LTB4_BLT1.html', 'In adult mice with traumatic SCI, BLT1 knockout or repeated LTB4-receptor antagonist ONO-4057 reduced early leukocyte infiltration, inflammatory cytokine/chemokine expression, neural apoptosis, and white-matter loss, and improved locomotor recovery. The paper supports an LTB4-BLT1-dependent inflammatory amplification and functional branch in the injured cord; it does not provide purified LTB4-BLT1 affinity or a terminal TF assay.', 'The authors conclude that the LTB4-BLT1 axis amplifies leukocyte infiltration and secondary injury after SCI, while BLT1 loss or pharmacologic blockade attenuates inflammation, apoptosis, white-matter loss, and functional deficit. The registered edge is retained as an SCI receptor-associated pathway/functional record rather than a direct biochemical binding record.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2861100_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000004' AND x.extraction_id='M24B-P2-R-RECOVERY-LTB4-BLT1-SCI-000001');
