INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000739', 'M23B-EVID-000994', 'P2FALLBACK-23B-M23B-EVID-000994', 'URL:https://pmc.ncbi.nlm.nih.gov/articles/PMC2993182/', '20884877', 'full_text_xml', 'exact_identifier_match:PMCID:PMC2993182', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2993182/', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2993182.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000994' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000994');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000045', 'M23B-EVID-000070', 'M23B-P2-R-000070', 'PMID:7542940; PMCID:PMC301201; DOI:10.1091/mbc.6.4.419', '7542940', 'full_text_html', 'exact_identifier_match:DOI:10.1091/mbc.6.4.419;PMCID:PMC301201', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC301201; PMID:7542940; DOI:10.1091/mbc.6.4.419; https://europepmc.org/articles/PMC301201?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC301201_beta8_neural_fulltext_7542940.pdf', 'In embryonic chick dorsal-root-ganglion cultures, surface-labeling immunoprecipitation identified the beta8 integrin subunit with putative alpha partners. Affinity-purified anti-beta8-Ex strongly inhibited neurite outgrowth on fibronectin, including the fibronectin 40-kDa C-terminal fragment, while alpha4/beta1 blocking antibodies and beta8 blockade showed distinct substrate-specific contributions. The study supports a beta8-containing integrin-dependent FN1 neurite-outgrowth function, but does not resolve the alpha partner or provide purified FN1-beta8 heterodimer affinity.', 'The authors conclude that beta8 integrins in association with one or more alpha subunits form an important set of extracellular-matrix receptors on chick sensory neurons and mediate part of fibronectin-dependent neurite outgrowth. The exact alpha partner for the FN1 beta8-containing complex remains unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC301201_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000070' AND x.extraction_id='M23B-P2-R-000070');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000053', 'M23B-EVID-000078', 'M23B-P2-R-000078', 'PMID:7542940; PMCID:PMC301201; DOI:10.1091/mbc.6.4.419', '7542940', 'full_text_html', 'exact_identifier_match:DOI:10.1091/mbc.6.4.419;PMCID:PMC301201', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC301201; PMID:7542940; DOI:10.1091/mbc.6.4.419; https://europepmc.org/articles/PMC301201?pdf=render; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_PMC301201_beta8_neural_fulltext_7542940.pdf', 'In embryonic chick dorsal-root-ganglion cultures, surface-labeling immunoprecipitation identified beta8 integrin with putative alpha partners. Affinity-purified anti-beta8-Ex inhibited neurite outgrowth on intact laminin-1 and heat-inactivated laminin-1; the heat-resistant laminin functional site was mapped to a domain likely corresponding to laminin E1X. The study supports a beta8-containing integrin-dependent LAMA1 neurite-outgrowth function, but does not resolve the alpha partner or provide purified LAMA1-beta8 heterodimer affinity.', 'The authors conclude that beta8 integrins in association with one or more alpha subunits form an important set of extracellular-matrix receptors on chick sensory neurons and mediate part of laminin-1-dependent neurite outgrowth. The exact alpha partner for the LAMA1 beta8-containing complex remains unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC301201_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000078' AND x.extraction_id='M23B-P2-R-000078');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC3082435_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E001016', 'M23B-EVID-000116', 'M23B-P2-R-000116', 'PMID:21378271; PMCID:PMC3099580; DOI:10.1182/blood-2010-09-305284', '21378271', 'full_text_xml', 'exact_identifier_match:PMCID:PMC3099580', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:21378271; PMCID:PMC3099580; DOI:10.1182/blood-2010-09-305284; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC3099580.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC3099580/', 'In human dermal microvascular endothelial cells and HUVECs, CD36 associated with VEGFR2, Syk, integrins, PI3K-p85, and other membrane proteins. TSP1-null mouse lung reduced CD36/VEGFR2 and Syk/VEGFR2 complex association; CD36 overexpression increased Syk expression; Syk inhibition or knockdown reduced VEGF-A-induced endothelial migration and decreased VEGFR2 Y1175 phosphorylation without blocking VEGFR2 autophosphorylation. The paper therefore supports a TSP1-CD36-Syk-VEGFR2 receptor-proximal relay, with context-dependent short-term VEGF-A pathway priming.', 'The primary study supports a receptor-proximal CD36-Syk-VEGFR2 relay in endothelial cells: TSP1-dependent membrane complex organization enables Syk-dependent modulation of VEGF-A-induced VEGFR2 Y1175 phosphorylation and migration. This is not evidence of a direct TSP1-CD36 intracellular binding interface or a TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC3099580.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000116' AND x.extraction_id='M23B-P2-R-000116');
