INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004004', 'M22B-EVID-002399', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC3759126.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002399' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000046', 'M23B-EVID-000071', 'M23B-P2-R-000071', 'PMCID:PMC4315246; PMID:25646087; DOI:10.1083/jcb.201403111', '25646087', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.201403111;PMCID:PMC4315246', 'supporting_validated_claim', 'B', 'L2', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC4315246; PMID:25646087; DOI:10.1083/jcb.201403111; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC4315246_article.html', 'Recombinant alpha-dystroglycan Fc constructs bound purified perlecan in Far-Western/solid-phase assays; DGFc5 and DGFc6 bound rat Schwann-cell membrane and associated ECM, whereas DGFc2 did not. Perlecan was selectively lost from nodes in dystroglycan-deficient mouse nerves, and the reported solid-phase apparent dissociation constant was approximately 41 nM for dystroglycan versus approximately 8 nM for gliomedin.', 'The primary study concludes that dystroglycan recruits or concentrates perlecan at peripheral nodes and that perlecan binds gliomedin to support nodal-component clustering. The direct molecular edge here is alpha-dystroglycan-perlecan; the paper reports no direct binding of DGFc constructs to gliomedin-expressing CHO cells.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC4315246_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000071' AND x.extraction_id='M23B-P2-R-000071');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000044', 'M23B-EVID-000069', 'M23B-P2-R-000069', 'PMCID:PMC4507358; PMID:25492623; DOI:10.1089/neu.2014.3703', '25492623', 'full_text_html', 'exact_identifier_match:DOI:10.1089/neu.2014.3703;PMCID:PMC4507358', 'supporting_validated_claim', 'B', 'L4', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC4507358; PMID:25492623; DOI:10.1089/neu.2014.3703; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC4507358_article.html', 'After mouse contusion SCI, soluble fibronectin increased early and insoluble fibrillar matrix accumulated around 7-14 days. Alpha5 and beta1 integrin expression increased after injury, most fibronectin co-localized with alpha5beta1, and approximately 80% of alpha5beta1-positive scar cells were CD11b-positive while approximately 20% were Col1a1-GFP-positive; myeloid fibronectin deletion did not visibly reduce lesion fibronectin, supporting fibroblasts as the primary source.', 'The authors propose alpha5beta1 as the primary fibronectin receptor after SCI because alpha5 and beta1 expression increased and fibronectin largely co-localized with alpha5beta1; they further propose fibroblasts supply fibronectin and activated macrophages/microglia participate in matrix assembly.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC4507358_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000069' AND x.extraction_id='M23B-P2-R-000069');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000015', 'M24B-EVID-000015', 'M24B-P2-000015', 'PMCID:PMC4624364; PMID:26502875; DOI:10.1186/s12974-015-0413-6', '26502875', 'full_text_or_bioc_json', 'exact_identifier_match:PMCID:PMC4624364', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC4624364; PMID:26502875; DOI:10.1186/s12974-015-0413-6; https://europepmc.org/articles/PMC4624364; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC4624364_CR2_nerve_injury_fulltext.pdf', 'In rat ventral-root-avulsion and sciatic-nerve-transection models, Cr2 expression rose after injury and was associated with glial responses; in Cr2-knockout mice after sciatic-nerve transection, synaptophysin loss in the ventral horn was greater than in wild-type controls. Rat astrocyte cultures expressed Cr2 by RT-PCR whereas microglia did not, and soluble CR2 increased in CSF after ventral-root avulsion.', 'Promote the bounded CR2-associated peripheral-nerve-injury functional branch: injury-associated Cr2 expression and astrocyte localization correlate with complement/synaptic responses, while Cr2 loss increases synaptic-terminal loss after sciatic-nerve transection. Keep this as a peripheral-nerve comparator, not contusive SCI; do not infer a C3-fragment binding event, intracellular CR2 relay, or terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC4624364_bioc.json' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000015' AND x.extraction_id='M24B-P2-000015');
