INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000004', 'M23B-EVID-000005', 'M23B-P2-000005', 'DOI:10.1016/j.nbd.2018.04.014', '29705186', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.nbd.2018.04.014', 'linked_unresolved', 'B', 'L1', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'DOI:10.1016/j.nbd.2018.04.014; local cache=data/raw/evidence/module20_24_supervised_cli_phase2/M23B_batch001_3_10_1016_j_nbd_2018_04_014.html', 'Stable DOI anchor is registered, but the local DOI response is only a redirect page and contains no retained Results/Methods/figure passage; the FnEDA deletion summary is not sufficient for an atomic Observation.', 'No import-ready author claim; exact primary interpretation and source anchor require full text.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC5995671_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000005' AND x.extraction_id='M23B-P2-000005');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000004', 'M23B-EVID-000005', 'M23B-P2-R-000005', 'PMCID:PMC5995671; PMID:29705186', '29705186', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.nbd.2018.04.014;PMCID:PMC5995671', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC5995671; PMID:29705186; DOI:10.1016/j.nbd.2018.04.014; local BioC cache=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC5995671_bioc.json', 'In male and female FnEDA-null mice after contusion SCI, deletion of the fibronectin EDA splice variant reduced chronic insoluble fibronectin matrix and lesion size, increased axonal density, and improved BMS/mBBB motor recovery while leaving the glial scar and acute fibrotic response comparatively unchanged. The paper also reports TGF-beta stimulation of cultured fibroblasts as a possible FnEDA-regulatory context, not a demonstrated receptor relay.', 'The authors conclude that FnEDA is an important building block of degradation-resistant insoluble fibronectin matrix after SCI and that its deletion reduces chronic fibrotic scarring and improves recovery.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC5995671_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000005' AND x.extraction_id='M23B-P2-R-000005');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000020', 'M23B-EVID-000021', 'M23B-P2-R-000021', 'PMCID:PMC5995671; PMID:29705186', '29705186', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.nbd.2018.04.014;PMCID:PMC5995671', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC5995671; PMID:29705186; DOI:10.1016/j.nbd.2018.04.014; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC5995671_article.html', 'The FnEDA-null mouse contusion-SCI experiment reduced chronic insoluble fibronectin matrix and lesion size, increased axonal density, and improved BMS/mBBB motor recovery while leaving the glial scar and acute fibrotic response comparatively unchanged. This is the same validated primary experiment already staged for the distinct C-23B EVID-000005 handoff.', 'The authors conclude that FnEDA is an important building block of degradation-resistant insoluble fibronectin matrix after SCI and that its deletion reduces chronic fibrotic scarring and improves recovery.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC5995671_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000021' AND x.extraction_id='M23B-P2-R-000021');
