INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E003974', 'M22B-EVID-002385', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC7686970.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002385' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E001022', 'M23B-EVID-000125', 'M23B-P2-R-000125', 'PMID:33021341; PMCID:PMC7686970; DOI:10.1111/jcmm.15874; PMID:7798222', '33021341', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7686970', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:33021341; PMCID:PMC7686970; DOI:10.1111/jcmm.15874; PMID:7798222; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC7686970.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC7686970/', 'In human osteosarcoma cells, recombinant TSP2 increased migration and MMP-9 expression. Neutralizing alphaVbeta3 antibody reduced TSP2-induced signaling/output, supporting alphaVbeta3 as the receptor-proximal entry point for the TSP2 response. The study used TSP2 stimulation and alphaVbeta3 blockade/knockdown-related experiments but did not perform purified alphaVbeta3-TSP2 affinity measurements.', 'The primary study supports a receptor-proximal TSP2-alphaVbeta3 signaling branch in osteosarcoma cells, with the downstream PLCbeta/PKCalpha/c-Src/NF-kB/MMP-9 program represented separately by EVID-000126. It does not establish a purified direct molecular binding interface.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC7686970.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000125' AND x.extraction_id='M23B-P2-R-000125');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000267', 'M23B-EVID-000126', 'M23B-P2-R-000126', 'PMID:33021341; PMCID:PMC7686970; DOI:10.1111/jcmm.15874', '33021341', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7686970', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:33021341; PMCID:PMC7686970; DOI:10.1111/jcmm.15874; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC7686970.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC7686970/', 'TSP2 treatment activated PLCbeta, PKCalpha, c-Src, IKK/I-kappaB/NF-kB signaling and increased MMP-9 expression and migration in human osteosarcoma cells. Specific inhibitors, siRNA, dominant-negative IKK mutants, MMP-9 blockade/inhibition/siRNA, and TSP2 knockdown reduced pathway activation or migration. NF-kB p65 promoter occupancy was assayed at the MMP-9 promoter, providing a downstream TF readout without proving a direct alphaVbeta3-to-p65 molecular interaction.', 'The primary study supports a TSP2-associated PLCbeta–PKCalpha–c-Src–NF-kB(p65) pathway leading to MMP-9 expression and osteosarcoma migration/metastatic behavior. The TF endpoint is NF-kB p65 activity at the MMP-9 promoter; the data do not establish a direct alphaVbeta3-p65 interaction or exclude parallel receptor inputs.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC7686970.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000126' AND x.extraction_id='M23B-P2-R-000126');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000267', 'M23B-EVID-000392', 'P2FALLBACK-23B-M23B-EVID-000392', 'PMCID:PMC7686970', '33021341', 'full_text_xml', 'exact_identifier_match:PMCID:PMC7686970', 'linked_unresolved', NULL, 'L1', 'unresolved', 'unresolved', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7686970/', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC7686970.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000392' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000392');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC87113_article.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
