INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000086', 'M23B-EVID-000148', 'M23B-P2-R-000148', 'PMID:11423542; DOI:10.1074/jbc.M103997200', '11423542', 'full_text_xml', 'exact_identifier_match:PMID:11423542', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:11423542; DOI:10.1074/jbc.M103997200; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID11423542_1709170_9484807_7525578_40400463_8565074.xml; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/11423542/', 'The primary study reports that alphaVbeta3 initially binds fibronectin and vitronectin without metabolic energy, but strong alphaVbeta3-vitronectin adhesion requires phosphorylation of the beta3 cytoplasmic domain, intracellular signaling, and cytoskeletal binding involving beta3 Tyr-747 and Tyr-759. AlphaVbeta3-fibronectin adhesion was not affected by these perturbations.', 'The primary study supports ligand-specific receptor-proximal activation of alphaVbeta3: strong vitronectin adhesion requires beta3-tail phosphorylation and cytoskeletal coupling, whereas fibronectin adhesion uses a different receptor state. It does not establish a downstream TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID11423542_1709170_9484807_7525578_40400463_8565074.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000148' AND x.extraction_id='M23B-P2-R-000148');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_xml', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID12843252.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000052', 'M23B-EVID-000077', 'M23B-P2-R-000077', 'PMID:15691705; DOI:10.1016/j.mcn.2004.08.017', '15691705', 'full_text_html', 'exact_identifier_match:PMID:15691705', 'candidate_requires_review', 'B', 'L4', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:15691705; DOI:10.1016/j.mcn.2004.08.017; https://pubmed.ncbi.nlm.nih.gov/15691705/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID15691705.xml; local PubMed HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID15691705.html', 'The corrected primary abstract reports alpha7 integrin expression in adult sensory neurons after sciatic-nerve crush. Function-blocking antibodies and alpha7-null mice reduced NGF- and NT-3-stimulated neurite outgrowth, while GDNF-stimulated outgrowth was less dependent on alpha7. This supports an alpha7beta1-laminin functional regeneration branch.', 'The corrected primary paper supports a context-dependent alpha7beta1-laminin functional branch in injured adult sensory neurons. It does not establish a direct purified laminin-alpha7beta1 affinity measurement, an intracellular relay, a terminal TF, or an SCI model.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID15691705.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000077' AND x.extraction_id='M23B-P2-R-000077');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000052', 'M23B-EVID-000077', 'M23B-P2-R-000077', 'PMID:15691705; DOI:10.1016/j.mcn.2004.08.017', '15691705', 'full_text_xml', 'exact_identifier_match:PMID:15691705', 'candidate_requires_review', 'B', 'L4', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:15691705; DOI:10.1016/j.mcn.2004.08.017; https://pubmed.ncbi.nlm.nih.gov/15691705/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID15691705.xml; local PubMed HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID15691705.html', 'The corrected primary abstract reports alpha7 integrin expression in adult sensory neurons after sciatic-nerve crush. Function-blocking antibodies and alpha7-null mice reduced NGF- and NT-3-stimulated neurite outgrowth, while GDNF-stimulated outgrowth was less dependent on alpha7. This supports an alpha7beta1-laminin functional regeneration branch.', 'The corrected primary paper supports a context-dependent alpha7beta1-laminin functional branch in injured adult sensory neurons. It does not establish a direct purified laminin-alpha7beta1 affinity measurement, an intracellular relay, a terminal TF, or an SCI model.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID15691705.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000077' AND x.extraction_id='M23B-P2-R-000077');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000073', 'M23B-EVID-000135', 'M23B-P2-R-000135', 'PMID:20884877; PMCID:PMC2993182; DOI:10.1161/CIRCRESAHA.110.232371; PMID:16099885', '20884877', 'full_text_xml', 'exact_identifier_match:PMID:16099885', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:20884877; PMCID:PMC2993182; DOI:10.1161/CIRCRESAHA.110.232371; PMID:16099885; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2993182.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC2993182/', 'In mouse RAW264.7 and primary peritoneal macrophages, purified recombinant TSP4 supported adhesion and migration that were blocked by alphaMbeta2 or beta3-integrin antibodies; CD36 and other control antibodies had little effect. TSP4 adhesion induced p38 MAPK phosphorylation, which was reduced by alphaMbeta2 or beta3 blockade and by alphaM or beta3 deficiency. Thbs4 deficiency reduced lesion p38 activation and inflammatory readouts in ApoE-null atherosclerosis models.', 'The primary study supports a TSP4-alphaMbeta2/beta3 receptor-proximal adhesion and p38-MAPK inflammatory branch in macrophages, with corresponding vascular inflammation effects in mouse atherosclerosis. It does not establish purified TSP4-integrin affinity or a TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16099885_7541634_7559467_9548928_7523411_9565552.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000135' AND x.extraction_id='M23B-P2-R-000135');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '20B', 'M20B-E002135', 'M20B-EVID-PROMO-20260826-038', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='20B' AND x.register_evidence_id='M20B-EVID-PROMO-20260826-038' AND x.extraction_id='');
