INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000001', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000001' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000059', 'M23B-EVID-000084', 'M23B-P2-R-000084', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'The corrected primary abstract reports soluble recombinant alpha3beta1, alpha6beta1, alpha7X1beta1, alpha7X2beta1, and alpha6beta4 binding to a panel of purified laminin isoforms with distinct specificities and affinities. Laminin-332 was a clear ligand for alpha3beta1 and alpha6beta4; alpha6beta1 bound broadly; alpha7X1beta1 and alpha7X2beta1 differed in laminin specificity. This directly supports assembled laminin-complex/recombinant-integrin binding at the abstract boundary.', 'The primary study supports direct molecular binding of assembled laminin isoforms to defined recombinant integrin complexes, including laminin-332-alpha3beta1 and laminin-332-alpha6beta4, with broader alpha6beta1 and splice-form-specific alpha7beta1 binding. It does not support isolated laminin-alpha-chain binding, cellular signaling, or SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000084' AND x.extraction_id='M23B-P2-R-000084');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000061', 'M23B-EVID-000086', 'M23B-P2-R-000086', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'The primary abstract reports soluble recombinant alpha6beta1 binding to a purified laminin isoform panel, including laminin-332, with alpha6beta1 showing broad specificity and a preference for laminin-111, laminin-332, and laminin-511/521. The queued laminin-332-alpha6beta1 direct molecular mapping is supported at the abstract boundary; exact affinity values and assay loci require full text.', 'The primary study supports direct molecular binding of assembled laminin-332 to recombinant alpha6beta1. It does not support isolated LAMA3 binding, cellular FAK/Src signaling, or SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000086' AND x.extraction_id='M23B-P2-R-000086');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000062', 'M23B-EVID-000087', 'M23B-P2-R-000087', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'The primary abstract reports that recombinant alpha6beta4 exhibited clear specificity for laminin-332 and laminin-511/521 in a purified laminin isoform panel. This supports a direct assembled laminin-332-alpha6beta4 binding mapping at the abstract boundary, but exact assay loci and affinity values require full text.', 'The primary study supports direct molecular binding of assembled laminin-332 to recombinant alpha6beta4. It does not establish a cellular hemidesmosome response, intracellular signaling, or SCI function in this experiment.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000087' AND x.extraction_id='M23B-P2-R-000087');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000064', 'M23B-EVID-000089', 'M23B-P2-R-000089', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'The primary abstract reports modest binding of recombinant alpha6beta1 to laminin-411/LM-411 in the purified laminin isoform panel. This supports a low-affinity/modest direct assembled laminin-411-alpha6beta1 mapping at the abstract boundary; exact affinity values and assay loci require full text.', 'The primary study supports modest direct molecular binding of assembled laminin-411 to recombinant alpha6beta1. It does not establish a neural or Schwann-cell functional outcome, intracellular signaling, or SCI relevance.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000089' AND x.extraction_id='M23B-P2-R-000089');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000065', 'M23B-EVID-000090', 'M23B-P2-R-000090', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'The primary abstract reports that soluble recombinant alpha7X1beta1 bound all tested laminin isoforms except laminin-332, with preference for laminin-211/221 and laminin-511/521; laminin-411 was a poor ligand with only modest binding. The queued laminin-411 mapping therefore resolves to the alpha7X1beta1 splice form, not generic alpha7beta1.', 'The primary study supports modest direct molecular binding of assembled laminin-411 to recombinant alpha7X1beta1. It does not support generic alpha7beta1 without the splice-form caveat, cellular signaling, or neural/SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000090' AND x.extraction_id='M23B-P2-R-000090');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000067', 'M23B-EVID-000092', 'M23B-P2-R-000092', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'The primary abstract reports that recombinant alpha3beta1 bound laminin-511/LM-511 and laminin-521/LM-521 in a purified laminin isoform panel. The queue combines 511/521 because the abstract reports both beta-chain variants; the exact individual affinity values and assay loci require full text.', 'The primary study supports direct molecular binding of assembled laminin-511/521 to recombinant alpha3beta1. It does not support isolated LAMA5/LAMB1 binding, cellular signaling, or SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000092' AND x.extraction_id='M23B-P2-R-000092');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000071', 'M23B-EVID-000096', 'M23B-P2-R-000096', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'The primary abstract reports clear recombinant alpha6beta4 specificity for laminin-511/LM-511 and laminin-521/LM-521 in a purified laminin isoform panel. This supports direct assembled laminin-511/521-alpha6beta4 binding at the abstract boundary; exact affinity values and assay loci require full text.', 'The primary study supports direct molecular binding of assembled laminin-511/521 to recombinant alpha6beta4. It does not establish cellular hemidesmosome function, intracellular signaling, or SCI function in this binding survey.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000096' AND x.extraction_id='M23B-P2-R-000096');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000072', 'M23B-EVID-000097', 'M23B-P2-R-000097', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'The primary abstract reports distinct binding specificities for recombinant alpha7X1beta1 and alpha7X2beta1 splice variants: alpha7X1beta1 preferred laminin-211/221 and laminin-511/521, while alpha7X2beta1 preferred laminin-111 and laminin-211/221; neither bound laminin-332. This supports splice-form-resolved direct binding to assembled LM511/521, not a generic alpha7beta1 claim.', 'The primary study supports direct molecular binding of assembled laminin-511/521 to alpha7X1beta1 and/or alpha7X2beta1 according to splice-form preference. It does not support collapsing these variants into generic alpha7beta1, cellular signaling, or SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000097' AND x.extraction_id='M23B-P2-R-000097');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000059', 'M23B-EVID-000098', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000098' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000061', 'M23B-EVID-000099', 'M23B-P2-R-000099', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'Reuse the validated abstract-level observation that recombinant alpha6beta1 showed broad laminin specificity, including direct binding to assembled laminin-332 in the purified isoform panel. Exact affinity values and assay loci remain unavailable at the same paper boundary.', 'Reuse the corrected primary-paper claim that assembled laminin-332 directly binds recombinant alpha6beta1 in the Nishiuchi et al. binding survey. Keep this direct molecular mapping separate from cellular laminin-332 adhesion and FAK/Src pathway records.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000099' AND x.extraction_id='M23B-P2-R-000099');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000062', 'M23B-EVID-000100', 'M23B-P2-R-000100', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:9151677', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:9151677; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/9151677/', 'Reuse the validated abstract-level observation that recombinant alpha6beta4 showed direct binding specificity for assembled laminin-332 in the purified laminin isoform panel. The additional PMID:9151677 paper provides alpha3beta1/alpha6beta4 cellular developmental context but does not replace the purified binding result.', 'Reuse the primary-paper claim that assembled laminin-332 directly binds recombinant alpha6beta4. Keep the separate alpha3beta1-deficient skin adhesion/development result from PMID:9151677 out of this direct molecular claim because it is functional receptor evidence, not a purified binding assay.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000100' AND x.extraction_id='M23B-P2-R-000100');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000067', 'M23B-EVID-000101', 'M23B-P2-R-000101', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml', 'Reuse the validated abstract-level observation that recombinant alpha3beta1 bound assembled laminin-511 and laminin-521 in the purified laminin isoform panel. PMID:30193894 independently reports LM-511 adhesion in kidney epithelial cells but does not establish isolated purified binding and is retained as functional context only.', 'Reuse the primary-paper claim that assembled laminin-511/521 directly bind recombinant alpha3beta1. Do not merge the kidney-cell LM-511 adhesion, Akt/TRAF6, or growth-factor signaling findings from PMID:30193894 into this direct molecular claim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000101' AND x.extraction_id='M23B-P2-R-000101');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000068', 'M23B-EVID-000102', 'M23B-P2-R-000102', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml', 'The primary abstract reports direct binding of assembled laminin-511/521 to recombinant alpha6beta1 in a purified laminin isoform panel. The exact affinity values and assay loci require the unavailable full text. PMID:30193894 supports LM-511 cell adhesion and integrin-linked Akt/TRAF6 signaling, but does not substitute for or expand the purified binding observation.', 'The primary survey supports a direct molecular assembled laminin-511/521-alpha6beta1 mapping at the abstract boundary. It does not support isolated LAMA5 or LAMB1 binding, a specific intracellular relay, SCI function, or a TF endpoint. The kidney-cell Akt/TRAF6 findings are a separate pathway/functional evidence layer.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000102' AND x.extraction_id='M23B-P2-R-000102');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000071', 'M23B-EVID-000103', 'M23B-P2-R-000103', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml', 'Reuse the validated abstract-level observation that recombinant alpha6beta4 bound assembled laminin-511/laminin-521 in the purified laminin isoform panel. PMID:30193894 discusses alpha6-containing integrin functions on LM-511 but does not establish isolated purified alpha6beta4 binding and remains contextual.', 'Reuse the primary-paper claim that assembled laminin-511/521 directly bind recombinant alpha6beta4. Keep kidney-cell adhesion and Akt/TRAF6 pathway observations from PMID:30193894 separate from this direct molecular record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000103' AND x.extraction_id='M23B-P2-R-000103');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000072', 'M23B-EVID-000104', 'M23B-P2-R-000104', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'Reuse the validated abstract-level observation that recombinant alpha7X1beta1 and alpha7X2beta1 showed direct binding to assembled laminin-511/laminin-521 in the purified laminin isoform panel. The alpha7 splice forms remain distinct receptor complexes.', 'Reuse the primary-paper claim that both alpha7X1beta1 and alpha7X2beta1 directly bind assembled laminin-511/521. Preserve splice-form identity and do not infer a shared intracellular pathway, neural/SCI function, or TF endpoint from this purified survey.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000104' AND x.extraction_id='M23B-P2-R-000104');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000061', 'M23B-EVID-000107', 'M23B-P2-R-000107', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml', 'Reuse the validated abstract-level observation that recombinant alpha6beta1 showed broad laminin specificity, including direct binding to assembled laminin-332 in the purified laminin isoform panel. Exact affinity values and assay loci remain unavailable at the same paper boundary.', 'Reuse the corrected primary-paper claim that assembled laminin-332 directly binds recombinant alpha6beta1 in the Nishiuchi et al. binding survey. Keep it separate from cell-based keratinocyte migration and hemidesmosome-function records.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000107' AND x.extraction_id='M23B-P2-R-000107');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000062', 'M23B-EVID-000108', 'M23B-P2-R-000108', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:9151677', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:16413178', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:9151677; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/9151677/', 'Reuse the validated abstract-level observation that recombinant alpha6beta4 directly bound assembled laminin-332 in the purified laminin isoform panel. PMID:9151677 provides alpha3beta1-deficient mouse skin functional context for laminin-5 adhesion and hemidesmosome organization, but not a purified alpha6beta4 affinity assay.', 'Reuse the primary-paper claim that assembled laminin-332 directly binds recombinant alpha6beta4. Keep the alpha3beta1-deficient skin adhesion/development result and hemidesmosome context separate from this direct molecular record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EV