INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000064', 'M23B-EVID-PROMO-20260826-003', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-PROMO-20260826-003' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000091', 'M23B-EVID-000153', 'M23B-P2-R-000153', 'PMID:1688848; PMID:9310484', NULL, 'full_text_xml', 'exact_identifier_match:PMID:1688848;PMID:9310484', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:1688848; PMID:9310484; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID1688848_9310484_31516087_11507091_18499670_19401592_21290408.xml; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/1688848/; https://pubmed.ncbi.nlm.nih.gov/9310484/', 'The primary studies report that endothelial adhesion to VWF is mainly mediated by alphaVbeta3 recognition of the VWF RGD sequence, while the platelet GPIbalpha-binding domain is dispensable for endothelial adhesion. RGD/RGGS-mutant VWF reduced endothelial adhesion, and alphaVbeta3 receptor labeling mapped the RGD-binding site to both integrin subunits. These are cell-adhesion and receptor-mapping observations rather than a complete purified VWF-alphaVbeta3 affinity assay.', 'The primary studies support VWF RGD-dependent alphaVbeta3-mediated endothelial adhesion and identify the receptor ligand-binding region, but do not establish a downstream signaling cascade or TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID1688848_9310484_31516087_11507091_18499670_19401592_21290408.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000153' AND x.extraction_id='M23B-P2-R-000153');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000049', 'M23B-EVID-000074', 'M23B-P2-R-000074', 'PMID:17598176; DOI:10.1002/glia.20536', '17598176', 'full_text_html', 'exact_identifier_match:PMID:17598176', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:17598176; DOI:10.1002/glia.20536; https://pubmed.ncbi.nlm.nih.gov/17598176/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9699501_17598176.xml; local PubMed HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID17598176.html', 'The primary abstract identifies laminin-2, not laminin-1, as the Schwann-cell matrix ligand: alpha7beta1 bound laminin-2-Sepharose, dystroglycan also bound laminin-2-Sepharose, alpha7 antibody partially inhibited adhesion, and individual or combined alpha7-integrin/dystroglycan knockdown reduced Schwann-cell adhesion and spreading. Alpha7beta1 also co-precipitated with focal adhesion kinase in differentiating cocultures.', 'The corrected primary paper supports a laminin-2–alpha7beta1/dystroglycan receptor-complex association and a Schwann-cell adhesion/spreading relay. It does not support the queued laminin-1/LAMA1 label, isolated LAMA1-chain binding, SCI relevance, or a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID17598176.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000074' AND x.extraction_id='M23B-P2-R-000074');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000054', 'M23B-EVID-000079', 'M23B-P2-R-000079', 'PMID:17598176; DOI:10.1002/glia.20536', '17598176', 'full_text_html', 'exact_identifier_match:PMID:17598176', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'REUSE_VALIDATED_AUTHOR_CLAIM', 'PMID:17598176; DOI:10.1002/glia.20536; https://pubmed.ncbi.nlm.nih.gov/17598176/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9699501_17598176.xml; local PubMed HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID17598176.html', 'Reuse the validated abstract-level observation for the same primary paper: laminin-2-Sepharose bound alpha7beta1 and dystroglycan-associated Schwann-cell material; alpha7-integrin or dystroglycan knockdown and blocking reduced Schwann-cell adhesion/spreading, and alpha7beta1 co-precipitated with FAK in differentiating cocultures. The paper reports laminin-2, not laminin-1.', 'Reuse the corrected primary-paper claim that laminin-2 associates with alpha7beta1/dystroglycan in a Schwann-cell adhesion/spreading relay, with a reported alpha7beta1-FAK association. Do not substitute laminin-1, infer isolated LAMA1 binding, or promote a terminal TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID17598176.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000079' AND x.extraction_id='M23B-P2-R-000079');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000057', 'M23B-EVID-000082', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L2', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID17598176.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000082' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000058', 'M23B-EVID-000083', 'M23B-P2-R-000083', 'PMID:17598176; DOI:10.1002/glia.20536', '17598176', 'full_text_html', 'exact_identifier_match:PMID:17598176', 'candidate_requires_review', 'B', 'L2', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:17598176; DOI:10.1002/glia.20536; local PubMed HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID17598176.html; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/17598176/', 'Reuse the validated primary-paper observation that laminin-2-Sepharose bound alpha7beta1 and dystroglycan-associated Schwann-cell material, alpha7/dystroglycan knockdown reduced Schwann-cell adhesion and spreading, and alpha7beta1 co-precipitated with FAK in differentiating neuron-Schwann-cell cocultures. The accessible abstract does not directly test axon sorting or establish the complete downstream relay.', 'The primary paper supports a laminin-2–alpha7beta1/dystroglycan receptor-complex association with a reported alpha7beta1-FAK association in Schwann-cell cocultures. The queued axon-sorting relay is not directly demonstrated in this paper; do not infer a complete laminin-2-to-axon-sorting pathway or TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID17598176.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000083' AND x.extraction_id='M23B-P2-R-000083');
