INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-001253', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID17598176.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-001253' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000055', 'M23B-EVID-000080', 'M23B-P2-R-000080', 'PMID:18590826; DOI:10.1016/j.mcn.2008.05.015', '18590826', 'full_text_xml', 'exact_identifier_match:PMID:18590826', 'candidate_requires_review', 'B', 'L2', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:18590826; DOI:10.1016/j.mcn.2008.05.015; https://pubmed.ncbi.nlm.nih.gov/18590826/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID18590826.xml', 'The corrected primary abstract reports adult mouse DRG neurite-outgrowth assays on laminin-1/LM-111, laminin-2/LM-211, laminin-8/LM-411, and laminin-10/LM-511. Function-blocking antibodies assigned non-overlapping receptor use: alpha3beta1 and alpha7beta1 appeared to mediate responses on laminin-1 and laminin-2, while alpha6beta1 was associated with laminin-8 and laminin-10. Laminin-2 outgrowth was relatively poor without neurotrophin support.', 'The corrected paper supports a context-dependent alpha3beta1-to-laminin-2 functional neural-guidance branch in adult mouse DRG neurons, but only at the antibody-blockade/functional layer. It does not establish purified alpha3beta1-laminin-2 affinity, an intracellular relay, a terminal TF, or an SCI model.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID18590826.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000080' AND x.extraction_id='M23B-P2-R-000080');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000063', 'M23B-EVID-000088', 'M23B-P2-R-000088', 'PMID:22563463; PMCID:PMC3341393; DOI:10.1371/journal.pone.0035546', '22563463', 'full_text_xml', 'exact_identifier_match:PMID:22563463', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:22563463; PMCID:PMC3341393; DOI:10.1371/journal.pone.0035546; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID22563463.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC3341393/', 'Polymerized laminin-332 matrix supported rapid, tight keratinocyte adhesion and suppressed migration. Neutralizing-integrin experiments and detergent-resistant hemidesmosome-like structures indicated contributions from alpha3beta1 and alpha6beta4, with alpha6beta4 contributing more strongly to adhesion to polymerized matrix than to purified laminin-332. The matrix-contextual adhesion result is distinct from purified recombinant binding.', 'The primary paper supports a downstream laminin-332 matrix-adhesion branch in which alpha3beta1 and alpha6beta4 contribute to stable epithelial adhesion, with alpha6beta4-associated hemidesmosome-like structures and suppressed migration in the polymerized-matrix context. It does not establish isolated receptor affinity, intracellular kinase causality, neural function, or a TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID22563463.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000088' AND x.extraction_id='M23B-P2-R-000088');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000063', 'M23B-EVID-PROMO-20260826-002', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID22563463.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-PROMO-20260826-002' AND x.extraction_id='');
