INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E004035', 'M22B-EVID-002417', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID23958855_7505785_7693733_9314546_11731446_17901052.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-002417' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000076', 'M23B-EVID-000138', 'M23B-P2-R-000138', 'PMID:7505785; DOI:10.1242/jcs.106.1.389; PMID:7693733; DOI:10.1242/jcs.105.4.1001; PMID:23958855; PMCID:PMC3759126; DOI:10.1038/oncsis.2013.27', '7693733', 'full_text_xml', 'exact_identifier_match:PMID:23958855;PMID:7505785;PMID:7693733', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:7505785; DOI:10.1242/jcs.106.1.389; PMID:7693733; DOI:10.1242/jcs.105.4.1001; PMID:23958855; PMCID:PMC3759126; DOI:10.1038/oncsis.2013.27; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID23958855_7505785_7693733_9314546_11731446_17901052.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC3759126/', 'Primary tenascin studies report RGD/cation-dependent endothelial adhesion to isolated TNfn3 and identify alphaVbeta3 by blocking antibodies and affinity purification from endothelial-cell extracts. A separate breast-cancer study reports alphaVbeta1/alphaVbeta6-dependent TNC adhesion and EMT-like responses, but does not establish purified alphaVbeta3-TNC binding. The direct molecular record is retained at the cell-extract affinity/fragment boundary.', 'The primary studies support tenascin recognition involving alphaVbeta3 in endothelial-cell adhesion and alphaV-containing integrin responses in epithelial cancer cells, but do not justify one unconditional purified native-TNC-alphaVbeta3 affinity edge. No intracellular TF endpoint is established in this direct record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID23958855_7505785_7693733_9314546_11731446_17901052.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000138' AND x.extraction_id='M23B-P2-R-000138');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000078', 'M23B-EVID-000140', 'M23B-P2-R-000140', 'PMID:23958855; PMCID:PMC3759126; DOI:10.1038/oncsis.2013.27', '23958855', 'full_text_xml', 'exact_identifier_match:PMID:23958855', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:23958855; PMCID:PMC3759126; DOI:10.1038/oncsis.2013.27; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC3759126.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC3759126/', 'In MCF-7 breast cancer cells, TNC treatment increased alphaVbeta1 heterodimer abundance, activated beta1 integrin colocalized with alphaV in focal adhesions, and increased FAK Y925 phosphorylation. Neutralizing alphaV/beta1/alphaVbeta6 antibodies reduced TNC- or TGF-beta1/TNC-induced EMT-like changes. The record captures the cell-state/adhesion output rather than a purified receptor-binding result.', 'The primary study supports a TNC-associated alphaV-containing integrin/FAK EMT-like epithelial output in breast cancer cells, with alphaVbeta1 and alphaVbeta6 contributions that depend on treatment context. It does not prove a direct native-TNC affinity edge or a TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID23958855_7505785_7693733_9314546_11731446_17901052.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000140' AND x.extraction_id='M23B-P2-R-000140');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000079', 'M23B-EVID-000141', 'M23B-P2-R-000141', 'PMID:23958855; PMCID:PMC3759126; DOI:10.1038/oncsis.2013.27', '23958855', 'full_text_xml', 'exact_identifier_match:PMID:23958855', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:23958855; PMCID:PMC3759126; DOI:10.1038/oncsis.2013.27; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC3759126.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC3759126/', 'The same primary breast-cancer study reports TNC-associated EMT-like morphological and marker changes, including focal-adhesion accumulation of alphaVbeta6, beta1 activation, FAK Y925 phosphorylation, and neutralizing-antibody suppression of TNC- or TGF-beta1/TNC-induced EMT-like responses. This record is retained as a distinct functional output for the M23B-E000079 handoff.', 'The primary study supports a context-dependent TNC/TGF-beta1-associated alphaV-containing integrin and FAK functional program leading to EMT-like breast-cancer cell behavior. It does not establish a direct receptor-ligand affinity or a TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID23958855_7505785_7693733_9314546_11731446_17901052.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000141' AND x.extraction_id='M23B-P2-R-000141');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000078', 'M23B-EVID-PROMO-20260826-005', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID23958855_7505785_7693733_9314546_11731446_17901052.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-PROMO-20260826-005' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000056', 'M23B-EVID-000081', 'M23B-P2-R-000081', 'PMID:24227711; PMCID:PMC3893357; DOI:10.1523/JNEUROSCI.3179-13.2013', '24227711', 'full_text_xml', 'exact_identifier_match:PMID:24227711', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text', 'PMID:24227711; PMCID:PMC3893357; DOI:10.1523/JNEUROSCI.3179-13.2013; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID24227711.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC3893357/', 'In mouse Schwann cells, conditional loss of alpha6 or alpha7 integrin reduced the ability of Schwann-cell/DRG explant cultures to bind laminin-411 or laminin-211, respectively, and reduced spreading. Combined alpha6/alpha7 loss produced a partial radial-sorting defect and myelination impairment, while alpha7 was upregulated and compensated for alpha6 loss during development. The paper measured FAK/Src/AKT and related pathway states but did not use the queue-described ILK/PI3K/AKT perturbation as a specific causal test.', 'The primary paper supports alpha6beta1 and alpha7beta1 as functionally preferred Schwann-cell laminin receptor branches for laminin-411 and laminin-211, respectively, with alpha7 compensation for alpha6 loss during radial sorting. It is receptor-proximal/pathway and functional genetic evidence, not a purified direct alpha6beta1-laminin-211 binding assay; the claimed ILK/PI3K/AKT perturbation should not be imported as causal from this paper.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID24227711.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000081' AND x.extraction_id='M23B-P2-R-000081');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000068', 'M23B-EVID-000093', 'M23B-P2-R-000093', 'PMID:28879238; PMCID:PMC5580876; DOI:10.1126/sciadv.1701497', '28879238', 'full_text_xml', 'exact_identifier_match:PMID:28879238', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:28879238; PMCID:PMC5580876; DOI:10.1126/sciadv.1701497; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID28879238.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC5580876/', 'The primary structural study resolved the LM511 integrin-binding fragment and showed that LM511E8 binds recombinant alpha6beta1 from the bottom face of LG1-3. Electron microscopy placed the alpha6beta1 headpiece opposite the coiled-coil extension; cross-linking mapped the laminin gamma1-tail near the beta1 MIDAS, and the gamma1 Glu1607 residue was required for binding. Crystal structure, mutagenesis, disulfide cross-linking, and gamma1-tail peptide inhibition support a direct LM511-alpha6beta1 interface.', 'The primary paper establishes a direct molecular LM511–alpha6beta1 interface in which the laminin gamma1-tail Glu1607 coordinates the beta1 MIDAS region, with the alpha5 LG1-3 structure contributing to the binding surface. This is a direct molecular edge only; no cellular signaling, functional output, SCI model, or TF endpoint was assayed.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID28879238.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000093' AND x.extraction_id='M23B-P2-R-000093');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000067', 'M23B-EVID-000101', 'M23B-P2-R-000101', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:30193894', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml', 'Reuse the validated abstract-level observation that recombinant alpha3beta1 bound assembled laminin-511 and laminin-521 in the purified laminin isoform panel. PMID:30193894 independently reports LM-511 adhesion in kidney epithelial cells but does not establish isolated purified binding and is retained as functional context only.', 'Reuse the primary-paper claim that assembled laminin-511/521 directly bind recombinant alpha3beta1. Do not merge the kidney-cell LM-511 adhesion, Akt/TRAF6, or growth-factor signaling findings from PMID:30193894 into this direct molecular claim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000101' AND x.extraction_id='M23B-P2-R-000101');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000068', 'M23B-EVID-000102', 'M23B-P2-R-000102', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:30193894', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml', 'The primary abstract reports direct binding of assembled laminin-511/521 to recombinant alpha6beta1 in a purified laminin isoform panel. The exact affinity values and assay loci require the unavailable full text. PMID:30193894 supports LM-511 cell adhesion and integrin-linked Akt/TRAF6 signaling, but does not substitute for or expand the purified binding observation.', 'The primary survey supports a direct molecular assembled laminin-511/521-alpha6beta1 mapping at the abstract boundary. It does not support isolated LAMA5 or LAMB1 binding, a specific intracellular relay, SCI function, or a TF endpoint. The kidney-cell Akt/TRAF6 findings are a separate pathway/functional evidence layer.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000102' AND x.extraction_id='M23B-P2-R-000102');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000071', 'M23B-EVID-000103', 'M23B-P2-R-000103', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894', '16413178', 'full_text_xml', 'exact_identifier_match:PMID:30193894', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:16413178; DOI:10.1016/j.matbio.2005.12.001; PMID:30193894; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID16413178.xml; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml', 'Reuse the validated abstract-level observation that recombinant alpha6beta4 bound assembled laminin-511/laminin-521 in the purified laminin isoform panel. PMID:30193894 discusses alpha6-containing integrin functions on LM-511 but does not establish isolated purified alpha6beta4 binding and remains contextual.', 'Reuse the primary-paper claim that assembled laminin-511/521 directly bind recombinant alpha6beta4. Keep kidney-cell adhesion and Akt/TRAF6 pathway observations from PMID:30193894 separate from this direct molecular record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID30193894.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000103' AND x.extraction_id='M23B-P2-R-000103');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000066', 'M23B-EVID-000091', 'M23B-P2-R-000091', 'PMID:31506597; PMCID:PMC6737067; DOI:10.1038/s41598-019-49669-x', '31506597', 'full_text_xml', 'exact_identifier_match:PMID:31506597', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:31506597; PMCID:PMC6737067; DOI:10.1038/s41598-019-49669-x; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID31506597.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC6737067/', 'The primary study found that recombinant mouse alpha-dystroglycan-Fc bound immobilized LM511 and LM511-E8 in solid-phase assays, with LM511-E8 binding weaker and detectable at higher coating concentration. Synthetic laminin-alpha5 peptides, especially hE8A5-20 (human alpha5 residues 2688-2699, KTLPQLLAKLSI), bound dystroglycan; deletion/mutation mapped the active core to LLAKLSI and identified K2696 as critical. The same peptide supported hiPSC attachment when conjugated to chitosan.', 'The primary paper supports a direct LM511-E8/laminin-alpha5 sequence to alpha-dystroglycan binding branch and a linked hiPSC adhesion output. The binding assay and adhesion output must remain distinct; this paper does not establish an integrin relay, intracellular pathway, SCI function, or TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID31506597.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000091' AND x.extraction_id='M23B-P2-R-000091');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000069', 'M23B-EVID-000094', 'M23B-P2-R-000094', 'PMID:35726387; PMCID:PMC9700348; DOI:10.1089/scd.2022.0010', '35726387', 'full_text_xml', 'exact_identifier_match:PMID:35726387', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:35726387; PMCID:PMC9700348; DOI:10.1089/scd.2022.0010; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID35726387.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC9700348/', 'In human 201B7 hiPSCs, iMatrix-511 scaffold culture was associated with increased integrin-alpha6, FYN, PI3K-related, E-cadherin/RAC1, RhoGAP, and RhoA/ROCK pathway readouts compared with collagen plus MFGE8 controls. Phospho-Fyn showed membrane and nuclear distribution in iMatrix-511 cultures, and proteome analysis indicated enhanced PI3K signaling and cytoskeletal actin activity. The paper presents this as an alpha6beta1-integrin/Fyn-RhoA-ROCK survival pathway, but does not isolate alpha6beta1 with a receptor-specific loss-of-function experiment.', 'The primary paper supports an LM511 scaffold-associated alpha6beta1/Fyn-RhoA-ROCK and PI3K pathway in human hiPSCs, with E-cadherin/RAC1 context. Because the receptor assignment is not isolated by clean alpha6beta1 perturbation in this study, this should remain receptor-proximal/pathway evidence rather than a definitive direct molecular or receptor-exclusive causal edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID35726387.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000094' AND x.extraction_id='M23B-P2-R-000094');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000070', 'M23B-EVID-000095', 'M23B-P2-R-000095', 'PMID:35726387; PMCID:PMC9700348; DOI:10.1089/scd.2022.0010', '35726387', 'full_text_xml', 'exact_identifier_match:PMID:35726387', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:35726387; PMCID:PMC9700348; DOI:10.1089/scd.2022.0010; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID35726387.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC9700348/', 'iMatrix-511 scaffold culture produced more viable hiPSC colonies/cells and lower apoptosis-associated loss than collagen plus MFGE8 comparison culture. The paper connects this survival phenotype to LM511/alpha6beta1-associated Fyn-RhoA-ROCK and PI3K signaling and to reduced dependence on ROCK inhibition during culture, but the survival output remains function-level evidence.', 'The primary paper supports a downstream laminin-511 scaffold-associated hiPSC survival/anti-apoptosis output. It does not by itself prove direct laminin binding to alpha6beta1, a receptor-exclusive causal chain, SCI relevance, or a terminal TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID35726387.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000095' AND x.extraction_id='M23B-P2-R-000095');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000713', 'M23B-EVID-000115', 'M23B-P2-R-000115', 'PMID:7531696; DOI:10.1074/jbc.270.7.2981', '7531696', 'full_text_xml', 'exact_identifier_match:PMID:7531696', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:7531696; DOI:10.1074/jbc.270.7.2981; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID7531696_21378271_10196234_11358957_10982388_7798222_9858782.xml; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/7531696/', 'The primary recombinant GST/CD36 mapping study reports specific, saturable, reversible, calcium-dependent thrombospondin binding to CD36 residues 93-120. The fusion protein competed with TSP binding to purified platelet CD36 and cell-surface CD36 on monocytes and CD36-transfected melanoma cells, and binding was blocked by antibodies to both CD36 and TSP.', 'The primary study supports a direct molecular TSP1-CD36 interaction and maps a sufficient CD36 binding region to residues 93-120 at the abstract boundary. It does not establish the intracellular CD36 relay, endothelial antiangiogenic function, or a TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID7531696_21378271_10196234_11358957_10982388_7798222_9858782.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000115' AND x.extraction_id='M23B-P2-R-000115');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000082', 'M23B-EVID-000144', 'M23B-P2-R-000144', 'PMID:9153222', '9153222', 'full_text_xml', 'exact_identifier_match:PMID:9153222', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:9153222; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/9153222/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9153222_14766759_7525179_1717468.xml', 'The primary solid-phase study reports that denatured or conformationally altered plasma vitronectin binds purified glycoprotein IIb/IIIa and alphaVbeta3 in a dose-dependent manner, whereas native plasma vitronectin does not. Thermal denaturation or complexation with PAI-1 exposes the cryptic cell-adhesion domain.', 'The primary study supports direct binding of conformationally altered/denatured vitronectin to purified alphaVbeta3 and glycoprotein IIb/IIIa, but not native plasma vitronectin. The conformational state is part of the ligand definition; no intracellular signaling or TF endpoint was assayed.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9153222_14766759_7525179_1717468.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000144' AND x.extraction_id='M23B-P2-R-000144');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000059', 'M23B-EVID-000098', 'M23B-P2-R-000098', 'PMID:9692987; DOI:10.1021/bi980175+', '9692987', 'full_text_xml', 'exact_identifier_match:PMID:9692987', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:9692987; DOI:10.1021/bi980175+; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9692987.xml; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/9692987/', 'The corrected primary abstract reports soluble human alpha3beta1 integrin ectodomains produced in insect cells and direct ligand-binding assays showing specific binding to laminin-5/laminin-332 and laminin-10, but not laminin-1, laminin-2, fibronectin, collagens, nidogen, thrombospondin, or complement factors. Laminin-5 binding was weaker than invasin binding and was increased by Mn2+ or activating antibody 9EG7 and decreased by Ca2+.', 'The primary study supports direct molecular binding of assembled laminin-332/laminin-5 to recombinant alpha3beta1 and receptor-state-dependent affinity regulation. It does not support isolated LAMA3 binding, cellular FAK/Src signaling, neural/SCI function, or a TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9692987.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000098' AND x.extraction_id='M23B-P2-R-000098');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000059', 'M23B-EVID-000106', 'M23B-P2-R-000106', 'PMID:18045589; DOI:10.1016/j.yexcr.2007.10.027; PMID:9692987', '18045589', 'full_text_xml', 'exact_identifier_match:PMID:9692987', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:18045589; DOI:10.1016/j.yexcr.2007.10.027; PMID:9692987; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID11171386_18045589_11470831_19342381.xml; stable PubMed=https://pubmed.ncbi.nlm.nih.gov/18045589/', 'The primary recombinant mini-laminin-332 study reports that deleting the three C-terminal gamma2 residues abolished alpha3beta1 binding and cell attachment/spreading, whereas deleting the beta3 C-terminal residue did not. Gamma2-tail peptide did not block binding, and electron microscopy indicated an indirect conformational role for the gamma2 C terminus in presenting the alpha3 LG1-3 integrin-binding region.', 'The study supports a direct assembled laminin-332-alpha3beta1 recognition requirement for the gamma2 C-terminally regulated integrin-binding conformation, but argues that the gamma2 tail is indirect rather than a simple contact epitope. It does not support isolated LAMC2 affinity, intracellular FAK/Src signaling, neural/SCI function, or a TF endpoint.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9692987.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000106' AND x.extraction_id='M23B-P2-R-000106');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000048', 'M23B-EVID-000073', 'M23B-P2-R-000073', 'PMID:9699501; DOI:10.1002/(SICI)1097-4652(199809)176:3<482::AID-JCP5>3.0.CO;2-K', '9699501', 'full_text_html', 'exact_identifier_match:PMID:9699501', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:9699501; DOI:10.1002/(SICI)1097-4652(199809)176:3<482::AID-JCP5>3.0.CO;2-K; https://pubmed.ncbi.nlm.nih.gov/9699501/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9699501_17598176.xml; local PubMed HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9699501.html; mismatched queued PMID:27717828 and DOI retained only in review notes', 'The corrected primary abstract reports that purified BSP, recombinant BSP fragments, and BSP-RGD peptides elicited adhesive, proliferative, and migratory responses in human MDA-MB-231 cells. Integrin-blocking antibodies assigned BSP-RGD-induced migration mainly to alphaVbeta3, while adhesion and proliferation were alphaVbeta5-mediated.', 'The corrected primary paper supports a context-dependent BSP-RGD integrin branch: alphaVbeta3 was associated with migration, whereas alphaVbeta5 was associated with adhesion and proliferation in MDA-MB-231 cells. This is receptor-proximal/functional evidence, not direct purified BSP-alphaVbeta5 affinity, an intracellular relay, a terminal TF, or SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9699501.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000073' AND x.extraction_id='M23B-P2-R-000073');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000048', 'M23B-EVID-000073', 'M23B-P2-R-000073', 'PMID:9699501; DOI:10.1002/(SICI)1097-4652(199809)176:3<482::AID-JCP5>3.0.CO;2-K', '9699501', 'full_text_xml', 'exact_identifier_match:PMID:9699501', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:9699501; DOI:10.1002/(SICI)1097-4652(199809)176:3<482::AID-JCP5>3.0.CO;2-K; https://pubmed.ncbi.nlm.nih.gov/9699501/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9699501_17598176.xml; local PubMed HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9699501.html; mismatched queued PMID:27717828 and DOI retained only in review notes', 'The corrected primary abstract reports that purified BSP, recombinant BSP fragments, and BSP-RGD peptides elicited adhesive, proliferative, and migratory responses in human MDA-MB-231 cells. Integrin-blocking antibodies assigned BSP-RGD-induced migration mainly to alphaVbeta3, while adhesion and proliferation were alphaVbeta5-mediated.', 'The corrected primary paper supports a context-dependent BSP-RGD integrin branch: alphaVbeta3 was associated with migration, whereas alphaVbeta5 was associated with adhesion and proliferation in MDA-MB-231 cells. This is receptor-proximal/functional evidence, not direct purified BSP-alphaVbeta5 affinity, an intracellular relay, a terminal TF, or SCI function.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9699501_17598176.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000073' AND x.extraction_id='M23B-P2-R-000073');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', '', 'M23B-EVID-000046', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9822731.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000046' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000050', 'M23B-EVID-000075', 'M23B-P2-R-000075', 'PMID:9822731; PMCID:PMC6793292; DOI:10.1523/JNEUROSCI.18-23-09703.1998', '9822731', 'full_text_xml', 'exact_identifier_match:PMID:9822731', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text', 'PMID:9822731; PMCID:PMC6793292; DOI:10.1523/JNEUROSCI.18-23-09703.1998; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC6793292_article.html', 'Antibody-activated laminin-1 supported attachment, spreading, and neurite outgrowth of late embryonic retinal neurons. Function-blocking anti-alpha3beta1 antibody substantially inhibited neurite outgrowth while sparing spreading, whereas broad beta1 blockade abolished attachment, spreading, and neurite outgrowth. Alpha3beta1 was detected in embryonic rat retinal ganglion-cell layers and optic nerve; alpha3-deficient mouse cultures showed compensatory alpha6beta1-dependent outgrowth.', 'The primary paper supports an activated-laminin-1 to alpha3beta1 receptor-proximal neural-guidance branch: alpha3beta1 is preferentially required for neurite outgrowth, while alpha6beta1 can compensate in alpha3-deficient cultures. This is functional receptor assignment, not a purified ligand-affinity measurement and not an intracellular kinase or TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9822731.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000075' AND x.extraction_id='M23B-P2-R-000075');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000051', 'M23B-EVID-000076', 'M23B-P2-R-000076', 'PMID:9822731; PMCID:PMC6793292; DOI:10.1523/JNEUROSCI.18-23-09703.1998', '9822731', 'full_text_xml', 'exact_identifier_match:PMID:9822731', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_full_text', 'PMID:9822731; PMCID:PMC6793292; DOI:10.1523/JNEUROSCI.18-23-09703.1998; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC6793292_article.html', 'In embryonic retinal-neuron cultures on laminin-1 and other laminin substrates, alpha6beta1 blockade with GoH3 markedly reduced cell attachment and spreading but had a smaller effect on neurite outgrowth than alpha3beta1 blockade. The paper identifies alpha6beta1 as a primary receptor for activated laminin-1 attachment/spreading and reports compensatory alpha6beta1-mediated outgrowth in alpha3-deficient cultures.', 'The primary paper supports an activated-laminin-1 to alpha6beta1 receptor-proximal neural-adhesion branch: alpha6beta1 preferentially mediates attachment and spreading, with context-dependent support of neurite outgrowth. The evidence is receptor-blockade/function based and does not establish a direct purified laminin-alpha6beta1 affinity measurement or an intracellular pathway/TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID9822731.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000076' AND x.extraction_id='M23B-P2-R-000076');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000019', 'M24B-EVID-000019', 'M24B-P2-000019', 'PMID:12111830', '12111830', 'full_text_xml', 'exact_identifier_match:PMID:12111830', 'linked_unresolved', 'B', 'L1', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'PMID:12111830; DOI:10.1002/jnr.10269', 'Stable PMID and DOI anchors are present, but no retained primary Results/Methods/figure passage was available; the registered CCR2 knockout/myelin-removal summary is not sufficient for an atomic Observation.', 'No import-ready author claim; exact source section and author interpretation require full text.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_12111830.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000019' AND x.extraction_id='M24B-P2-000019');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000019', 'M24B-EVID-000019', 'M24B-P2-R-RECOVERY-CCR2-SCI-000001', 'PMID:12111830; DOI:10.1002/jnr.10269', '12111830', 'full_text_xml', 'exact_identifier_match:PMID:12111830', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_functional_output', 'PMID:12111830; DOI:10.1002/jnr.10269; https://pubmed.ncbi.nlm.nih.gov/12111830/; https://onlinelibrary.wiley.com/doi/10.1002/jnr.10269', 'In mice with mid-thoracic contusion SCI, Ccr2 deletion reduced Mac-1-positive macrophage/monocyte accumulation at the lesion epicenter and coincidentally reduced myelin degradation at 7 days, while the difference was absent by 14 days. Injury-induced MCP-1/CCL2, MCP-3/CCL7, and MIP-2/CXCL2 mRNA increases were not changed by Ccr2 deletion; Ccr2-deficient mice also showed reduced Ccr1 and Ccr5 mRNA. This supports a time-limited CCR2-dependent monocyte-recruitment and myelin-clearance function in the tested SCI model, not a purified CCL2-CCR2 binding measurement.', 'The authors conclude that chemokines acting through CCR2 contribute to early monocyte recruitment to the SCI lesion epicenter. Preserve the temporal limitation and the absence of a demonstrated direct ligand-binding or terminal-TF result.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_12111830.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000019' AND x.extraction_id='M24B-P2-R-RECOVERY-CCR2-SCI-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000019', 'M24B-EVID-000019', 'M24B-P2-R-RECOVERY-CCR2-SCI-ABSTRACT-000001', 'PMID:12111830; DOI:10.1002/jnr.10269', '12111830', 'full_text_xml', 'exact_identifier_match:PMID:12111830', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:12111830; DOI:10.1002/jnr.10269; https://pubmed.ncbi.nlm.nih.gov/12111830/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml', 'In CCR2-deficient mice after midthoracic contusion SCI, Mac-1 immunoreactivity and associated myelin degradation were significantly reduced at the lesion epicenter at 7 days, while differences were absent by 14 days. MCP-1, MCP-3, and MIP-2 mRNA increased after injury without genotype-dependent differences; CCR2-deficient mice also showed reduced CCR1 and CCR5 mRNA. The study supports an early CCR2-dependent monocyte-recruitment and myelin-clearance phenotype.', 'The primary authors conclude that chemokines acting through CCR2 contribute to early monocyte recruitment to the SCI lesion epicenter. The evidence is receptor-genetic downstream function, not purified CCL2/CCR2 binding and not a complete intracellular relay.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_12111830.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000019' AND x.extraction_id='M24B-P2-R-RECOVERY-CCR2-SCI-ABSTRACT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000004', 'M24B-EVID-000008', 'M24B-P2-R-RECOVERY-P2X7-ATP-SCI-ABSTRACT-000001', 'PMID:15258577; DOI:10.1038/nm1082', '15258577', 'full_text_xml', 'exact_identifier_match:PMID:15258577', 'candidate_requires_review', 'B', 'L2', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:15258577; DOI:10.1038/nm1082; https://pubmed.ncbi.nlm.nih.gov/15258577/; https://doi.org/10.1038/nm1082; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch099_pubmed_15258577.xml', 'In rats after acute impact SCI, the primary abstract reports sustained high ATP release in the peritraumatic zone, P2X7R expression in spinal cord neurons, and ATP-induced high-frequency spiking, irreversible cytosolic calcium elevation, and neuronal death. Intraspinal OxATP or PPADS after injury improved functional recovery and reduced peritraumatic cell death. This supports an ATP/P2X7-associated excitotoxic pathway and functional branch, but not purified ATP-P2X7 binding.', 'The primary authors conclude that prolonged purinergic receptor activation after SCI contributes to excitotoxic neuronal degeneration and that P2X7R antagonists reduce histological and functional sequelae. This is receptor-associated pharmacology and downstream function, not a direct biochemical binding record.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_15258577.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000008' AND x.extraction_id='M24B-P2-R-RECOVERY-P2X7-ATP-SCI-ABSTRACT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000004', 'M24B-EVID-000047', 'M24B-P2-R-000947', 'PMID:15258577', '15258577', 'full_text_xml', 'exact_identifier_match:PMID:15258577', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMID:15258577; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Primary SCI paper retrieved; exact observation retained at source scope.', 'SCI phenotype is supported at the reported model scope; no direct terminal-TF edge was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_15258577.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000047' AND x.extraction_id='M24B-P2-R-000947');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000004', 'M24B-EVID-PROMO-20260826-001', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_15258577.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-PROMO-20260826-001' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000077;M21B-E000078', 'M21B-EVID-000029', 'M21B-P2-000029', 'PMCID:PMC2621323', '18922473', 'full_text_xml', 'exact_identifier_match:PMID:18922473', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC2621323_TGFBR1_TAK1_bioc.json; M21B-EVID-000029; identifier: PMCID:PMC2621323; PMID:18922473; DOI:10.1016/j.molcel.2008.09.002', 'TGF-β receptor activation required TRAF6 for JNK/p38 activation; TRAF6 associated with activated TβRI/TβRII complexes, underwent transient K63-linked ubiquitination, and interacted with TAK1; TRAF6 loss reduced JNK/p38 and apoptosis/EMT outputs while leaving Smad activation intact (Figs. 1–4).', 'The authors conclude that receptor-associated TRAF6 connects activated TGF-β receptors to a Smad-independent TAK1/JNK/p38 branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_18922473.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000029' AND x.extraction_id='M21B-P2-000029');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000077;M21B-E000078', 'M21B-EVID-000029', 'M21B-P2-R-000029', 'PMCID:PMC2621323', '18922473', 'full_text_xml', 'exact_identifier_match:PMID:18922473', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC2621323; PMID:18922473; DOI:10.1016/j.molcel.2008.09.002; local BioC cache=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC2621323_bioc.json', 'In TGF-beta-treated signaling systems, dominant-negative or siRNA loss of TRAF6 suppressed JNK and p38 activation while sparing Smad2 signaling. Immunoprecipitation and reprecipitation experiments showed ligand-activated TGF-beta receptor complexes associate with TRAF6; TGF-beta induced K63-linked TRAF6 ubiquitination and TRAF6-TAK1 association, linking the receptor complex to the Smad-independent JNK/p38 branch.', 'The authors conclude that the ligand-activated TGF-beta receptor complex binds and K63-ubiquitinates TRAF6, which is specifically required to activate TAK1-dependent JNK and p38 independently of Smads.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_18922473.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000029' AND x.extraction_id='M21B-P2-R-000029');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000077;M21B-E000078', 'M21B-EVID-000029', 'M21B-P2-R-000044', 'PMID:18922473; PMCID:PMC2621323; DOI:10.1016/j.molcel.2008.09.002', '18922473', 'full_text_xml', 'exact_identifier_match:PMID:18922473', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_receptor_proximal_relay', 'PMID:18922473; PMCID:PMC2621323; DOI:10.1016/j.molcel.2008.09.002; https://pubmed.ncbi.nlm.nih.gov/18922473/; https://pmc.ncbi.nlm.nih.gov/articles/PMC2621323/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMC2621323_TGFBR1_TAK1_bioc.json; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMIDs_33921794_28559424_18922473_19361494_pubmed.xml', 'In mink lung epithelial and mouse hepatocyte systems, activated TGF-beta receptor complexes associated with TRAF6; TGF-beta induced K63-linked TRAF6 ubiquitination and TRAF6-TAK1 association, and TRAF6 loss or dominant-negative perturbation reduced TGF-beta-induced JNK and p38 activation without equivalently blocking Smad2 phosphorylation.', 'Promote the bounded TGF-beta receptor-complex -> TRAF6 K63-ubiquitination -> TAK1 -> JNK/p38 noncanonical relay. Preserve receptor-complex and adaptor ordering; do not treat this pathway evidence as direct TGF-beta receptor ligand-binding biophysics or transfer it wholesale to SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_18922473.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000029' AND x.extraction_id='M21B-P2-R-000044');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000079', 'M21B-EVID-000030', 'M21B-P2-000030', 'PMID:19361494', '19361494', 'full_text_xml', 'exact_identifier_match:PMID:19361494', 'linked_unresolved', 'B', 'L2', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'PMID:19361494', 'Stable PMID anchor is present, but no retained primary Results/Methods/figure passage was available; the registered BMPR2-LIMK1 retinal-axon summary is not sufficient for an atomic Observation.', 'No import-ready author claim; exact source section and author interpretation require full-text verification.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_19361494.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000030' AND x.extraction_id='M21B-P2-000030');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000079', 'M21B-EVID-000030', 'M21B-P2-R-000045', 'PMID:19361494; DOI:10.1016/j.ydbio.2009.03.027', '19361494', 'full_text_xml', 'exact_identifier_match:PMID:19361494', 'candidate_requires_review', 'B', 'L2', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:19361494; DOI:10.1016/j.ydbio.2009.03.027; https://pubmed.ncbi.nlm.nih.gov/19361494/; https://doi.org/10.1016/j.ydbio.2009.03.027; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMIDs_33921794_28559424_18922473_19361494_pubmed.xml', 'In developing Xenopus laevis retinal ganglion cell axons, BMPRII receptor-tail interaction with LIMK1 was required for proper axon extension; BMPRII lacking the LIMK1-binding region shortened axons, while manipulation of LIMK1 did not alter dendrite growth. The record supports a developmental BMPRII-LIMK1 cytoskeletal branch, not a specific BMP7 ligand assignment.', 'Retain the bounded BMPRII -> LIMK1 -> cofilin/actin axon-extension comparator branch. Do not infer a BMP7-specific ligand edge, SCI glial relevance, or a universal BMP receptor pathway from this Xenopus developmental study.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_19361494.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000030' AND x.extraction_id='M21B-P2-R-000045');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000079', 'M21B-EVID-PROMO-20260826-006', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L2', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_19361494.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-PROMO-20260826-006' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000016', 'M24B-EVID-000016', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_21343866.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000016' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000075;M21B-E000076', 'M21B-EVID-000028', 'M21B-P2-B083-001', 'PMID:28559424; PMCID:PMC5508197; DOI:10.1124/mol.117.108522', '28559424', 'full_text_xml', 'exact_identifier_match:PMID:28559424', 'linked_unresolved', 'B', 'L1', 'validated_fulltext', 'M21B-C-PH2-B083-001', 'Primary full text was available through official PMC; no direct molecular affinity or SCI-cell transfer was inferred.', 'CXCL4, CXCL9, CXCL10, and CXCL11 activated G-alpha-i signaling through CXCR3A in transfected HEK293-derived assays; CXCR3A also showed ligand-induced beta-arrestin recruitment and receptor internalization, with GRK2/3 and GRK5/6 perturbation defining differential recruitment requirements.', 'Discussion and Summary', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_28559424.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000028' AND x.extraction_id='M21B-P2-B083-001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000075;M21B-E000076', 'M21B-EVID-000028', 'M21B-P2-B083-002', 'PMID:28559424; PMCID:PMC5508197; DOI:10.1124/mol.117.108522', '28559424', 'full_text_xml', 'exact_identifier_match:PMID:28559424', 'linked_unresolved', 'B', 'L1', 'validated_fulltext', 'M21B-C-PH2-B083-002', 'Primary full text was available through official PMC; no direct molecular affinity or SCI-cell transfer was inferred.', 'CXCR3B recruited beta-arrestin with reduced/variant-specific kinetics relative to CXCR3A; beta-arrestin knockout reduced CXCL11-induced pERK1/2 at CXCR3B, and CXCL11 activated SRE/SRF transcriptional reporters at CXCR3A but not CXCR3B in HEK293T assays.', 'Discussion and Summary', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_28559424.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000028' AND x.extraction_id='M21B-P2-B083-002');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000004', 'M23B-EVID-000005', 'M23B-P2-R-000005', 'PMCID:PMC5995671; PMID:29705186', '29705186', 'full_text_xml', 'exact_identifier_match:PMID:29705186', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC5995671; PMID:29705186; DOI:10.1016/j.nbd.2018.04.014; local BioC cache=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC5995671_bioc.json', 'In male and female FnEDA-null mice after contusion SCI, deletion of the fibronectin EDA splice variant reduced chronic insoluble fibronectin matrix and lesion size, increased axonal density, and improved BMS/mBBB motor recovery while leaving the glial scar and acute fibrotic response comparatively unchanged. The paper also reports TGF-beta stimulation of cultured fibroblasts as a possible FnEDA-regulatory context, not a demonstrated receptor relay.', 'The authors conclude that FnEDA is an important building block of degradation-resistant insoluble fibronectin matrix after SCI and that its deletion reduces chronic fibrotic scarring and improves recovery.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_29705186.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000005' AND x.extraction_id='M23B-P2-R-000005');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000020', 'M23B-EVID-000021', 'M23B-P2-R-000021', 'PMCID:PMC5995671; PMID:29705186', '29705186', 'full_text_xml', 'exact_identifier_match:PMID:29705186', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC5995671; PMID:29705186; DOI:10.1016/j.nbd.2018.04.014; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC5995671_article.html', 'The FnEDA-null mouse contusion-SCI experiment reduced chronic insoluble fibronectin matrix and lesion size, increased axonal density, and improved BMS/mBBB motor recovery while leaving the glial scar and acute fibrotic response comparatively unchanged. This is the same validated primary experiment already staged for the distinct C-23B EVID-000005 handoff.', 'The authors conclude that FnEDA is an important building block of degradation-resistant insoluble fibronectin matrix after SCI and that its deletion reduces chronic fibrotic scarring and improves recovery.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_29705186.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000021' AND x.extraction_id='M23B-P2-R-000021');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000018', 'M24B-EVID-000018', 'M24B-P2-R-RECOVERY-P2X4-DHCB-SCI-ABSTRACT-000001', 'PMID:30622226; DOI:10.14348/molcells.2018.0028', '30622226', 'full_text_xml', 'exact_identifier_match:PMID:30622226', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:30622226; DOI:10.14348/molcells.2018.0028; https://pubmed.ncbi.nlm.nih.gov/30622226/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml', 'In a rat contusion SCI model, P2X4R expression increased and chronic neuropathic pain was present by day 7. Intravenous dehydrocorybulbine relieved pain-related behaviors without changing motor function, reduced IL-1beta, IL-18, and MMP-9 elevations, attenuated P2X4R upregulation, and reduced ATP-evoked intracellular calcium. P2X receptor and dopamine D2 receptor agonists antagonized dehydrocorybulbine''s antinociceptive effects. The primary abstract supports a pharmacologic P2X4-associated pain pathway, not direct ATP-P2X4 binding.', 'The primary authors propose that dehydrocorybulbine reduces SCI-associated neuropathic pain by inhibiting P2X4R-associated signaling. The pharmacology supports a receptor-proximal pain branch, but does not establish purified ATP-P2X4 affinity or a terminal TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000018' AND x.extraction_id='M24B-P2-R-RECOVERY-P2X4-DHCB-SCI-ABSTRACT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000018', 'M24B-EVID-PROMO-20260826-002', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'A', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_30622226.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-PROMO-20260826-002' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000002', 'M23B-EVID-000003', 'M23B-P2-000003', 'DOI:10.1089/neu.2019.6540', '31516087', 'full_text_xml', 'exact_identifier_match:PMID:31516087', 'linked_unresolved', 'B', 'L1', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'DOI:10.1089/neu.2019.6540; PMCID:PMC6978780; PMID:31516087; local cache=data/raw/evidence/module20_24_supervised_cli_phase2/M23B_batch001_2_10_1089_neu_2019_6540.html', 'Stable DOI and alternate PMID/PMCID anchors are registered, but the local DOI response is only a redirect page and contains no retained Results/Methods/figure passage; the stiffness/integrin-ILK summary is not sufficient for an atomic Observation.', 'No import-ready author claim; exact primary interpretation and source anchor require full text.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31516087.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000003' AND x.extraction_id='M23B-P2-000003');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000002', 'M23B-EVID-000003', 'M23B-P2-R-000003', 'PMCID:PMC6978780; PMID:31516087', '31516087', 'full_text_xml', 'exact_identifier_match:PMID:31516087', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC6978780; PMID:31516087; DOI:10.1089/neu.2019.6540; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC6978780_article.html', 'In mouse primary cortical astrocytes and hESC-derived human astrocytes, substrates approximating chronically scarred spinal-cord stiffness increased cellular complexity and beta1-integrin and integrin-linked kinase protein levels compared with softer substrates; GFAP protein was unchanged. The study measured mechanosensitive pathway-associated protein expression, not direct matrix-receptor binding or a complete kinase cascade.', 'The authors report that astrocytes respond to physiologically relevant substrate stiffness through changes in morphology and mechanosensitive protein expression, including beta1-integrin and ILK.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31516087.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000003' AND x.extraction_id='M23B-P2-R-000003');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000003', 'M23B-EVID-000004', 'M23B-P2-000004', 'DOI:10.1089/neu.2019.6540', '31516087', 'full_text_xml', 'exact_identifier_match:PMID:31516087', 'linked_unresolved', 'B', 'L1', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'DOI:10.1089/neu.2019.6540; PMCID:PMC6978780; PMID:31516087; local cache=data/raw/evidence/module20_24_supervised_cli_phase2/M23B_batch001_2_10_1089_neu_2019_6540.html', 'Stable DOI and alternate PMID/PMCID anchors are registered, but the local DOI response is only a redirect page and contains no retained Results/Methods/figure passage; the chronic lesion-stiffness summary is not sufficient for an atomic Observation.', 'No import-ready author claim; exact primary interpretation and source anchor require full text.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31516087.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000004' AND x.extraction_id='M23B-P2-000004');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000003', 'M23B-EVID-000004', 'M23B-P2-R-000004', 'PMCID:PMC6978780; PMID:31516087', '31516087', 'full_text_xml', 'exact_identifier_match:PMID:31516087', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC6978780; PMID:31516087; DOI:10.1089/neu.2019.6540; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC6978780_article.html', 'In a severe T11 contusion mouse SCI model, chronic lesion tissue at 12 weeks was stiffer than uninjured tissue; acute immune-modifying nanoparticle treatment reduced lesion stiffness toward uninjured values and reduced pathological GFAP-positive fiber alignment at the glial/fibrotic interface. The study linked chronic scar mechanics to astrocyte morphology and glial-scar organization, not to a unique receptor or TF endpoint.', 'The authors conclude that chronic fibrotic scarring contributes to spinal-cord stiffening and that the resulting mechanical environment participates in astrocyte morphology and maintenance of the chronic glial scar.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31516087.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000004' AND x.extraction_id='M23B-P2-R-000004');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000043', 'M23B-EVID-000068', 'M23B-P2-R-000068', 'PMID:31516087; PMCID:PMC6978780; DOI:10.1089/neu.2019.6540', '31516087', 'full_text_xml', 'exact_identifier_match:PMID:31516087', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC6978780; PMID:31516087; DOI:10.1089/neu.2019.6540; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC6978780_article.html', 'The primary astrocyte stiffness experiment already staged for M23B-EVID-000003 found that 2000-Pa versus 200-Pa substrates increased astrocyte surface area and process complexity and increased beta1-integrin and integrin-linked kinase protein levels, while GFAP was unchanged. The same study measured chronic T11 contusion lesion stiffening by AFM and mitigation of scar-associated alignment/stiffness after IMP treatment.', 'The authors interpret integrin-mediated focal adhesions as the transmembrane linkage through which cells sense and exert tension; this paper supports stiffness-associated beta1-integrin/ILK mechanotransduction context, not a ligand-specific binding event or complete kinase/TF cascade.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31516087.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000068' AND x.extraction_id='M23B-P2-R-000068');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000092', 'M23B-EVID-000154', 'M23B-P2-R-000154', 'PMID:31516087; PMCID:PMC6978780; DOI:10.1089/neu.2019.6540', '31516087', 'full_text_xml', 'exact_identifier_match:PMID:31516087', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:31516087; PMCID:PMC6978780; DOI:10.1089/neu.2019.6540; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC6978780.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC6978780/', 'Chronic mouse SCI tissue was mechanically stiffer than uninjured tissue, with lesion core/rim values around 1314/1120 Pa in the reported model. Mouse and human astrocytes cultured on 2000 Pa scar-like versus 200 Pa intact-tissue-like substrates developed distinct morphology and actin stress fibers; beta1-integrin and ILK protein levels were higher on the stiff substrate, while GFAP levels were not changed by this stiffness comparison.', 'The primary study supports a stiffness-sensitive astrocyte mechanotransduction program associated with beta1 integrin and ILK abundance and actin remodeling over the physiologic SCI stiffness range. It does not identify a specific ECM ligand, prove a direct beta1-integrin-to-ILK molecular edge, or establish a TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31516087.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000154' AND x.extraction_id='M23B-P2-R-000154');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000093', 'M23B-EVID-000155', 'M23B-P2-R-000155', 'PMID:31516087; PMCID:PMC6978780; DOI:10.1089/neu.2019.6540', '31516087', 'full_text_xml', 'exact_identifier_match:PMID:31516087', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:31516087; PMCID:PMC6978780; DOI:10.1089/neu.2019.6540; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC6978780.xml; stable full text=https://pmc.ncbi.nlm.nih.gov/articles/PMC6978780/', 'The primary SCI study reports chronic lesion stiffening, fibronectin-rich lesion core and GFAP-positive rim architecture, and reduction of lesion stiffness and pathological glial-fiber alignment after immune-modifying nanoparticle treatment. IMP-treated lesion stiffness approached uninjured values, while the study did not show a change in GFAP protein abundance from stiffness or IMP treatment.', 'The primary study supports a functional chronic SCI lesion-mechanics branch in which fibrotic scar and glial architecture contribute to tissue stiffening, and IMP treatment reduces stiffness and pathological fiber alignment. It does not establish a specific ligand-receptor edge, direct beta1-integrin causality, or a TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31516087.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000155' AND x.extraction_id='M23B-P2-R-000155');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000116', 'M23B-EVID-000184', 'M23B-P2-R-000187', 'PMID:10781587; PMID:31557129; PMCID:PMC6781990; PMID:32124475; PMCID:PMC7136142', '31557129', 'full_text_xml', 'exact_identifier_match:PMID:31557129', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_full_text', 'PMID:10781587; PMID:31557129; PMCID:PMC6781990; PMID:32124475; PMCID:PMC7136142; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B035_pmids.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B035_pmc_full.xml; stable sources=https://pubmed.ncbi.nlm.nih.gov/10781587/; https://pmc.ncbi.nlm.nih.gov/articles/PMC6781990/; https://pmc.ncbi.nlm.nih.gov/articles/PMC7136142/', 'CCL28 activated CCR10 in transfectants with calcium mobilization and chemotaxis in the receptor-characterization study. In a mouse spinal-cord-hemitransection model, CCL28 was induced downstream of IL-1beta/TNF-alpha/NF-kappaB, CCR10-positive FOXP3-positive regulatory T cells accumulated in the injured cord, and CCL28 or CCR10 neutralization reduced Treg recruitment and delayed locomotor recovery. In primary endothelial cells, CCL28 stimulation was associated with a CCR10-eNOS interaction and Src/PI3K/MAPK/NO-dependent tube-formation and wound-healing outputs. The receptor pharmacology, SCI functional axis, and endothelial relay are retained as separate observations.', 'Primary research supports CCL28-CCR10 receptor activation and separate CCL28-CCR10-associated Treg recruitment/locomotor recovery and CCR10-eNOS endothelial angiogenic branches. The SCI paper does not establish a complete intracellular CCR10 pathway or terminal TF; NF-kappaB is an upstream regulator of CCL28 production in that model, not evidence that CCR10 directly activates NF-kappaB. The endothelial CCR10-eNOS interaction is a receptor-proximal protein relay, not a direct CCL28-eNOS edge.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31557129.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000184' AND x.extraction_id='M23B-P2-R-000187');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000020', 'M24B-EVID-000020', 'M24B-P2-000020', 'PMID:31557129', '31557129', 'full_text_xml', 'exact_identifier_match:PMID:31557129', 'linked_unresolved', 'B', 'L1', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'PMID:31557129; DOI:10.18632/aging.102239', 'Stable PMID and DOI anchors are present, but no retained primary Results/Methods/figure passage was available; the registered CCL28/CCR10 recruitment/recovery summary is not sufficient for an atomic Observation.', 'No import-ready author claim; exact source section and author interpretation require full text.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31557129.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000020' AND x.extraction_id='M24B-P2-000020');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000020', 'M24B-EVID-000020', 'M24B-P2-R-RECOVERY-CCL28-CCR10-FUNCTION-000001', 'PMCID:PMC6781990; PMID:31557129; DOI:10.18632/aging.102239', '31557129', 'full_text_xml', 'exact_identifier_match:PMID:31557129', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6781990; PMID:31557129; DOI:10.18632/aging.102239; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_PMC6781990_CCL28_CCR10_full.xml', 'After mouse SCI, spinal-cord CCL28 mRNA/protein increased; recombinant CCL28 recruited CD4+CD25+FOXP3+ Treg cells in transwell and intraspinal SCI assays, with recruitment reduced by CCL28 or CCR10 neutralization. CCL28 neutralization delayed BMS locomotor recovery, whereas recombinant CCL28 improved recovery and the effect was reversed by CCR10 or CD25 neutralization.', 'The authors conclude that SCI-induced CCL28 recruits CCR10-expressing Treg cells and that this axis suppresses local inflammation and contributes to improved locomotor recovery; the evidence is neutralization/recruitment/function, not purified CCL28-CCR10 binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31557129.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000020' AND x.extraction_id='M24B-P2-R-RECOVERY-CCL28-CCR10-FUNCTION-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000020', 'M24B-EVID-000020', 'M24B-P2-R-RECOVERY-CCL28-CCR10-SCI-FULLTEXT-000001', 'PMCID:PMC6781990; PMID:31557129; DOI:10.18632/aging.102239', '31557129', 'full_text_xml', 'exact_identifier_match:PMID:31557129', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC6781990; PMID:31557129; DOI:10.18632/aging.102239; https://pmc.ncbi.nlm.nih.gov/articles/PMC6781990/; https://pubmed.ncbi.nlm.nih.gov/31557129/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch100_PMC6781990_CCL28_CCR10_SCI.html', 'In male C57BL/6J mice with T12 hemitransection/contusion SCI, CCL28 mRNA and protein increased early and were reduced by IL-1beta/TNF-alpha neutralization or IKK-beta/NF-kB inhibition. CD4-positive CD25-positive FOXP3-positive Treg cells accumulated in the injured cord and preferentially expressed CCR10 over CCR3. Recombinant CCL28 increased Treg chemotaxis and spinal recruitment, while CCL28 or CCR10 neutralization reduced recruitment; recombinant CCL28 improved BMS locomotor recovery, and CCR10 or CD25 neutralization reversed that benefit. CCL28/CCR10-associated Treg recruitment reduced proinflammatory cytokines, increased IL-10, and reduced effector T-cell proliferation.', 'The primary study supports an NF-kB-regulated CCL28-to-CCR10 Treg recruitment branch that suppresses local inflammation and promotes locomotor recovery after mouse SCI. The record is downstream/functional and receptor-dependence evidence; it does not establish purified CCL28-CCR10 affinity, a complete intracellular CCR10 relay, or a terminal TF endpoint downstream of CCR10.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_31557129.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000020' AND x.extraction_id='M24B-P2-R-RECOVERY-CCL28-CCR10-SCI-FULLTEXT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000005', 'M23B-EVID-000006', 'M23B-P2-R-000006', 'PMCID:PMC7509206; PMID:32957245; DOI:10.1016/j.jmbbm.2020.103953', '32957245', 'full_text_xml', 'exact_identifier_match:PMID:32957245', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC7509206; PMID:32957245; DOI:10.1016/j.jmbbm.2020.103953; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_fulltext/PMC7509206_bioc.json', 'In an approximately 18-week mouse hemi-section SCI model, AFM mapping found a significant reduction in Young''s modulus at the chronic injury core and progressively lower modulus toward the scar center relative to uninjured tissue. The same study documented dense and disorganized nuclei, a CNS-cell-poor fibrotic core bordered by GFAP-positive glial scar, increased vimentin, reduced total sulfated proteoglycans, increased CSPGs, and increased hyaluronan in scar compartments.', 'The authors conclude that chronic hemi-section SCI scar has altered mechanical and extracellular-matrix composition that can shape mechanochemical cell behavior and contribute to an anti-regenerative environment. Retain this as matrix/functional evidence for the fibrotic-scar branch, not as FnEDA-specific receptor or intracellular signaling evidence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_32957245.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000006' AND x.extraction_id='M23B-P2-R-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000179', 'M23B-EVID-000253', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'B', 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_32957245.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000253' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-000006', 'PMID:32964315', '32964315', 'full_text_xml', 'exact_identifier_match:PMID:32964315', 'linked_unresolved', 'B', 'L4', 'metadata_only_not_import_ready', 'metadata_only_not_import_ready', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', 'Stable PMID and DOI anchor are present, but no retained abstract or full-text Results/Methods/figure passage was available in the local cache; the registered RvD3 resolution/neuroprotection summary is not sufficient for an atomic Observation.', 'No import-ready author claim; the B-layer summary cannot be converted into a claim without the primary paper passage.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_32964315.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-000006', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', '32964315', 'full_text_xml', 'exact_identifier_match:PMID:32964315', 'supporting_validated_claim', 'B', 'L4', 'validated_full_text', 'validated_author_claim', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7; https://link.springer.com/article/10.1007/s12035-020-02118-7; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B002_PMID32964315_RvD3_SCI_fulltext.pdf', 'In female C57BL/6 mice with T10 weight-compression SCI (20 g for 1 minute), a single intrathecal RvD3 injection (1 microgram/20 microliters at 1 hour) improved BMS locomotor recovery, reduced thermal hyperalgesia and lesion area, lowered inflammatory cytokine/chemokine expression, shifted macrophage markers toward an M2-associated pattern, preserved tight-junction proteins, and reduced glial/fibrotic scar markers. In LPS-treated RAW264.7 cells and hCMEC/D3 endothelial cells, RvD3 reduced inflammatory/NO outputs and increased migration or angiogenic-associated markers.', 'Promote the bounded RvD3 downstream functional branch for inflammatory resolution, neuroprotection, pain reduction, barrier preservation, and locomotor recovery in this mouse SCI model. Do not infer a cognate receptor, receptor-proximal relay, or terminal TF: the authors explicitly state that the detailed G-protein receptor mechanism was not investigated and that unique RvD3/RvD4 receptors remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_32964315.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-000006');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-000921', 'PMID:32964315', '32964315', 'full_text_xml', 'exact_identifier_match:PMID:32964315', 'supporting_validated_claim', 'B', 'L4', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMID:32964315; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Primary SCI paper retrieved; exact observation retained at source scope.', 'SCI phenotype is supported at the reported model scope; no direct terminal-TF edge was shown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_32964315.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-000921');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000011', 'M24B-EVID-000006', 'M24B-P2-R-RECOVERY-RVD3-SCI-ABSTRACT-000001', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7', '32964315', 'full_text_xml', 'exact_identifier_match:PMID:32964315', 'candidate_requires_review', 'B', 'L4', 'validated_abstract_bounded', 'validated_author_claim', 'PMID:32964315; DOI:10.1007/s12035-020-02118-7; https://pubmed.ncbi.nlm.nih.gov/32964315/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_pubmed_32964315_12111830_30622226.xml', 'In female C57BL/6 mice subjected to moderate compression SCI, intrathecal RvD3 at 1 microgram/20 microliters one hour after injury improved locomotor recovery and reduced thermal hyperalgesia at 14 days. RvD3 treatment reduced TNF-alpha, IL6, IL1beta, CCL2, and CCL3, increased ZO-1 and occludin, reduced GFAP/Iba1 gliosis and CD68/TGF-beta neuroinflammation, and enhanced neuroprotection. In RAW264.7 cells and hCMEC/D3 cells, RvD3 reduced LPS-induced inflammatory mediators/NO and promoted angiogenic responses.', 'The primary authors conclude that RvD3 promotes inflammatory resolution, neuroprotection, barrier-associated protein expression, and neurological recovery after experimental SCI. The record supports downstream function only; no RvD3 receptor, intracellular relay, or terminal TF was established in the retrieved primary abstract.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_32964315.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000006' AND x.extraction_id='M24B-P2-R-RECOVERY-RVD3-SCI-ABSTRACT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000178', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_32964315.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000178' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000073;M21B-E000074', 'M21B-EVID-000027', 'M21B-P2-000027', 'PMID:33921794', '33921794', 'full_text_xml', 'exact_identifier_match:PMID:33921794', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC8073111.html; M21B-EVID-000027; identifier: PMID:33921794; PMCID:PMC8073111; DOI:10.3390/ijms22084232', 'In matched engineered receptor assays, CCL17/CCL22 recruited β-arrestin to CCR4 without robust G-protein signaling, while CCL19/CCL21 activated both G-protein and β-arrestin responses at CCR7, with CCL19 generally more potent (Figs. 1–3; Tables 1–2).', 'The authors conclude that CCR4 and CCR7 have distinct signaling arrays and that the tested ligands did not show the proposed ligand-biased agonism under the matched assay conditions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_33921794.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000027' AND x.extraction_id='M21B-P2-000027');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000073;M21B-E000074', 'M21B-EVID-000027', 'M21B-P2-R-000042', 'PMID:33921794; DOI:10.3390/ijms22084232', '33921794', 'full_text_xml', 'exact_identifier_match:PMID:33921794', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:33921794; DOI:10.3390/ijms22084232; https://pubmed.ncbi.nlm.nih.gov/33921794/; https://doi.org/10.3390/ijms22084232; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch050_PMIDs_33921794_28559424_18922473_19361494_pubmed.xml', 'In matched human receptor assay systems, CCL17 and CCL22 stimulated beta-arrestin recruitment but not measurable G-protein signaling at CCR4; CCL19 and CCL21 activated both G-protein and beta-arrestin pathways at CCR7, with CCL19 more potent. The comparison supports receptor-specific signaling branch differences in a non-SCI system.', 'Retain the chemokine–CCR4/CCR7 receptor-proximal branch comparison: CCR4 favored beta-arrestin/scavenger-like signaling in this assay set, whereas CCR7 coupled to both G-protein and beta-arrestin pathways. Do not infer branch weights in SCI receiver cells or a direct downstream TF.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_33921794.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000027' AND x.extraction_id='M21B-P2-R-000042');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000001', 'M23B-EVID-000002', 'M23B-P2-R-000002', 'PMID:36336030', '36336030', 'full_text_xml', 'exact_identifier_match:PMID:36336030', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMID:36336030; DOI:10.1016/j.expneurol.2022.114264; local cache=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_36336030.xml', 'PubMed abstract reports that the integrin-N-cadherin pathway is associated with glial-scar formation and that anti-beta1-integrin antibody blocked scar-forming astrocyte recruitment and reduced chronic scar volume; exact Results/Methods/figure locus remains unverified.', 'Abstract-level conclusion retained as a retrieval lead; exact author interpretation and assay locus require full text.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_36336030.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000002' AND x.extraction_id='M23B-P2-R-000002');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000001', 'M23B-EVID-000002', 'M23B-P2-R-RECOVERY-TAMARU-FULLTEXT-000001', 'PMID:36336030; DOI:10.1016/j.expneurol.2022.114264', '36336030', 'full_text_xml', 'exact_identifier_match:PMID:36336030', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch285_Tamaru_36336030_fulltext.pdf; /Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch285_Tamaru_36336030_fulltext.txt; PMID:36336030; DOI:10.1016/j.expneurol.2022.114264', 'In primary mouse astrocyte experiments, IL-6 plus soluble IL-6 receptor induced reactive astrocytes and type-I-collagen culture generated collagen-I-grown scar-forming astrocytes that retained flattened morphology, N-cadherin expression, and scar-marker expression after removal from collagen or in-vitro beta1-integrin or N-cadherin antibody treatment. In transplantation experiments, collagen-I-grown scar-forming astrocytes induced surrounding host astrocytes to acquire the scar-forming/N-cadherin-positive phenotype; anti-beta1-integrin antibody reduced this recruitment. In a 70-kdyn T9 contusion model, anti-beta1-integrin delivered during the chronic interval reduced GFAP/N-cadherin-positive scar-forming astrocytes and increased GAP43-positive area.', 'The authors conclude that scar-forming astrocytes persist and recruit neighboring astrocytes through a collagen-I-associated beta1-integrin/N-cadherin axis in chronic SCI, and that beta1-integrin blockade reduces glial-scar burden and increases the measured GAP43-positive axon-associated area. This is pathway and functional evidence, not purified collagen-I binding, alpha-chain resolution, a direct FAK/SRC assay, or a terminal TF result.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_36336030.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000002' AND x.extraction_id='M23B-P2-R-RECOVERY-TAMARU-FULLTEXT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000017', 'M24B-EVID-000017', 'M24B-P2-R-000017', 'PMCID:PMC9836372; PMID:36634215; DOI:10.1111/bpa.13113', '36634215', 'full_text_xml', 'exact_identifier_match:PMID:36634215', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC9836372; PMID:36634215; DOI:10.1111/bpa.13113; https://europepmc.org/articles/PMC9836372; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B004_PMC9836372_S100A8_TLR4_SCI_fulltext.pdf', 'In rat spinal ischemia/reperfusion injury, intrathecal recombinant S100A8 increased TLR4, p-ERK/ERK, p-NF-kB/NF-kB, IL-1beta, and apoptosis-associated readouts; TAK-242 given before S100A8 reduced TUNEL-positive cells and these pathway readouts. S100A8 knockdown also reduced the same inflammatory/apoptotic outputs.', 'The authors conclude that Fra-1/S100A8 forms a feedback loop involving TLR4, ERK1/2, and NF-kB that promotes apoptosis and neuroinflammation after spinal ischemia/reperfusion injury.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_36634215.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000017' AND x.extraction_id='M24B-P2-R-000017');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000007', 'M24B-P2-000007', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971', '37446149', 'full_text_xml', 'exact_identifier_match:PMID:37446149', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971; https://europepmc.org/articles/PMC10341423; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf', 'In Sprague-Dawley rats with T9 compressive SCI, a single post-injury administration of RvD1 (0.1 microgram) combined with peripheral-nerve-derived stem-cell spheroids improved BBB locomotion, ladder-rung performance, tissue regeneration/remyelination measures, and mechanical allodynia relative to injury controls and monotherapy groups. In LPS-stimulated PNSC spheroids, RvD1 reduced TNF-alpha, IL-1beta, and NF-kappaB protein signals and increased IL-10 and TGF-beta transcripts.', 'Promote the bounded RvD1-plus-PNSC combination-therapy functional branch in the reported rat SCI model, including anti-inflammatory marker changes and locomotor/tissue-regeneration outputs. Do not infer that RvD1 alone caused the combination effect, do not promote ALX/FPR2 as directly tested in this paper, and do not assign a terminal TF beyond the measured NF-kappaB protein signal.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_37446149.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000007' AND x.extraction_id='M24B-P2-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000007', 'M24B-P2-R-000007', 'PMID:37446149', '37446149', 'full_text_xml', 'exact_identifier_match:PMID:37446149', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:37446149; PMCID:PMC10341423; DOI:10.1007/s12035-020-02118-7; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC10341423_article.html', 'In vitro RvD1 treatment of LPS-stimulated peripheral nerve-derived stem-cell spheroids reduced TNF-alpha, IL-1beta, and NF-kB and increased IL-10/TGF-beta at selected concentrations. In a rat compressive SCI model, the RvD1 plus spheroid combination produced the strongest BBB/laddder-rung recovery and reduced inflammatory markers compared with vehicle and monotherapy groups.', 'The authors interpret combined RvD1 and PNSC spheroid treatment as a therapeutic strategy that enhances neuronal regeneration and anti-inflammatory recovery after SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_37446149.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000007' AND x.extraction_id='M24B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000007', 'M24B-P2-R-000922', 'PMID:37446149', '37446149', 'full_text_xml', 'exact_identifier_match:PMID:37446149', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMID:37446149; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Resolvin D1 plus peripheral-nerve-derived stem-cell spheroids improved outcomes in rat SCI.', 'The combined repair phenotype is supported; no receptor-specific terminal-TF edge was established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_37446149.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000007' AND x.extraction_id='M24B-P2-R-000922');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000012', 'M24B-P2-000012', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971', '37446149', 'full_text_xml', 'exact_identifier_match:PMID:37446149', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC10341423; PMID:37446149; DOI:10.3390/ijms241310971; https://europepmc.org/articles/PMC10341423; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B003_PMC10341423_RvD1_PNSC_SCI_fulltext.pdf', 'The same full-text primary paper supports reuse of the validated RvD1-plus-PNSC combination-therapy observation on the duplicate B evidence record: rat T9 compressive SCI functional/tissue-regeneration outputs and LPS-stimulated PNSC-spheroid inflammatory marker changes are documented in Results, Figures 1-3, and Methods 4.4-4.8.', 'Reuse the bounded author claim from M24B-P2-000007 for this separate evidence record; no duplicate observation is created. Direct RvD1-receptor binding, receptor-proximal relay, ALX/FPR2 causality, and terminal-TF occupancy remain unknown.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_37446149.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000012' AND x.extraction_id='M24B-P2-000012');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000012', 'M24B-EVID-000012', 'M24B-P2-R-000927', 'PMID:37446149', '37446149', 'full_text_xml', 'exact_identifier_match:PMID:37446149', 'supporting_validated_claim', 'B', 'L1', 'validated_observation', 'VALIDATED_SCI_FUNCTION_BOUNDED', 'PMID:37446149; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch001_pmids.xml', 'Resolvin D1 plus peripheral-nerve-derived stem-cell spheroids improved outcomes in rat SCI.', 'The combined repair phenotype is supported; no receptor-specific terminal-TF edge was established.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_37446149.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000012' AND x.extraction_id='M24B-P2-R-000927');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', '', 'M24B-EVID-000178', '', '', NULL, 'full_text_xml', 'no_exact_phase2_paper_match', 'linked_unresolved', 'E', 'L0', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_37446149.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000178' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '24B', 'M24B-E000016', 'M24B-EVID-000016', 'M24B-P2-R-RECOVERY-HMGB1-TLR-CCL5-SCI-FULLTEXT-000001', 'PMCID:PMC11437233; PMID:39333662; DOI:10.1038/s41598-024-72947-2', '39333662', 'full_text_xml', 'exact_identifier_match:PMID:39333662', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC11437233; PMID:39333662; DOI:10.1038/s41598-024-72947-2; https://pmc.ncbi.nlm.nih.gov/articles/PMC11437233/; https://pubmed.ncbi.nlm.nih.gov/39333662/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_D24B_batch098_PMC11437233_HMGB1_TLR_CCL5_SCI.html', 'In adult male Sprague-Dawley rats with T8-T10 contusion SCI, HMGB1 and CCL5 increased synchronously at the lesion and peaked around day 4; intrathecal HMGB1-neutralizing antibody reduced astrocytic CCL5. In primary rat astrocytes, recombinant HMGB1 dose-dependently increased CCL5, while TLR2 inhibitor C29 or TLR4 inhibitor TAK-242, but not RAGE inhibitor FPS-ZM1, reduced CCL5. ERK inhibitor PD98059, JNK inhibitor SP600125, or NF-kB inhibitor SN50 reduced HMGB1-induced CCL5, whereas p38 inhibition did not. CCL5 or HMGB1 blockade reduced microglia/macrophage accumulation, M1 polarization-associated markers, lesion size, and improved BBB locomotor scores.', 'The primary study supports an HMGB1-associated TLR2/4-to-ERK/JNK-to-NF-kB astrocytic relay that increases CCL5, promotes microglia/macrophage recruitment and M1-associated polarization, and worsens lesion and motor outcomes after rat SCI. It is receptor-proximal/pathway evidence with downstream functional outputs; no purified HMGB1-TLR2 or HMGB1-TLR4 binding assay, receptor-complex resolution, or terminal-TF occupancy was established in this paper.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_39333662.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='24B' AND x.register_evidence_id='M24B-EVID-000016' AND x.extraction_id='M24B-P2-R-RECOVERY-HMGB1-TLR-CCL5-SCI-FULLTEXT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000008;M21B-E000009;M21B-E000010;M21B-E000011;M21B-E000012', 'M21B-EVID-000002', 'M21B-P2-R-000002', 'PMCID:PMC359352; PMID:7526154; PMCID:PMC230354; PMID:7532278; PMID:8232552; PMID:9461596', '7526154', 'full_text_xml', 'exact_identifier_match:PMID:7526154', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC359352; PMCID:PMC230354; PMID:8232552; PMID:9461596; local cache=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_M21B_001_005.xml; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC359352_article.html', 'Recovered primary abstracts support several type-I IFN relay components: TYK2 directly binds and phosphorylates the IFN receptor alpha cytoplasmic region; JAK1 complementation restores IFN-alpha/beta signaling; STAT2 is required for IFN-alpha response and ISGF3 formation; and TYK2 interaction maps to IFNAR1 JH3-7/JH6 regions. PMC pages for the older records expose scanned/abstract material but no retained surrounding Results/Methods/figure passage suitable for import.', 'Abstract-level relay claims retained as retrieval leads; exact author interpretation and figure locus require complete primary text.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_7526154.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000002' AND x.extraction_id='M21B-P2-R-000002');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000008;M21B-E000009;M21B-E000010;M21B-E000011;M21B-E000012', 'M21B-EVID-000002', 'M21B-P2-R-RECOVERY-TYK2-IFNAR1-000001', 'PMCID:PMC359352; PMID:7526154; DOI:10.1128/MCB.14.12.8133', '7526154', 'full_text_xml', 'exact_identifier_match:PMID:7526154', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC359352; PMID:7526154; DOI:10.1128/MCB.14.12.8133; https://pmc.ncbi.nlm.nih.gov/articles/PMC359352/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMC359352_article.html', 'In the primary human type-I interferon receptor study, GST fusion proteins containing IFN receptor alpha cytoplasmic regions bound p135/TYK2 from human cell lysates. The association was supported by immunoblotting and in-vitro kinase assays; recombinant TYK2, but not JAK1 or JAK2, bound the GST-IFN-R constructs and catalyzed their tyrosine phosphorylation. Deletion mapping localized binding and phosphorylation to a 46-amino-acid juxtamembrane region of the receptor alpha cytoplasmic domain. This is a direct intracellular receptor-proximal association, not extracellular IFN ligand occupancy.', 'The authors conclude that TYK2 directly and specifically associates with and phosphorylates the type-I IFN receptor alpha cytoplasmic region, supporting TYK2 as part of the receptor complex that initiates type-I IFN intracellular signaling.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_7526154.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000002' AND x.extraction_id='M21B-P2-R-RECOVERY-TYK2-IFNAR1-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000008;M21B-E000009;M21B-E000010;M21B-E000011;M21B-E000012', 'M21B-EVID-000002', 'P2MAN-M21B-M21B-EVID-000002-PMID_7526154', 'PMID:7526154', '7526154', 'full_text_xml', 'exact_identifier_match:PMID:7526154', 'candidate_requires_review', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:7526154', 'Unresolved: exact primary paper anchor identified, but no verified surrounding Results/Methods/figure/table passage was retained in this run; abstract/metadata alone is insufficient for an atomic Observation.', 'Unresolved: no separate explicit author interpretation was verified from an accessible primary-paper section or figure legend; do not convert the B-layer curator summary into an AuthorClaim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_7526154.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000002' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000002-PMID_7526154');
