INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000008;M21B-E000009;M21B-E000010;M21B-E000011;M21B-E000012', 'M21B-EVID-000002', 'P2MAN-M21B-M21B-EVID-000002-PMID_8232552', 'PMID:8232552', '8232552', 'full_text_xml', 'exact_identifier_match:PMID:8232552', 'candidate_requires_review', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:8232552', 'Unresolved: exact primary paper anchor identified, but no verified surrounding Results/Methods/figure/table passage was retained in this run; abstract/metadata alone is insufficient for an atomic Observation.', 'Unresolved: no separate explicit author interpretation was verified from an accessible primary-paper section or figure legend; do not convert the B-layer curator summary into an AuthorClaim.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_8232552.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000002' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000002-PMID_8232552');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000001;M21B-E000002;M21B-E000003;M21B-E000004;M21B-E000005;M21B-E000006;M21B-E000007', 'M21B-EVID-000001', 'M21B-P2-R-000001', 'PMID:8999038; DOI:10.1074/jbc.271.51.32635; PMID:9188471; DOI:10.1074/jbc.272.25.15760', NULL, 'full_text_xml', 'exact_identifier_match:PMID:8999038', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_abstract_bounded', 'PMID:8999038; DOI:10.1074/jbc.271.51.32635; https://pubmed.ncbi.nlm.nih.gov/8999038/; PMID:9188471; DOI:10.1074/jbc.272.25.15760; https://pubmed.ncbi.nlm.nih.gov/9188471/; local PubMed XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_M21B_001_005.xml', 'The primary PubMed abstracts report that human OSM activates two receptor-complex branches: gp130-LIFR (type I) and gp130-OSMRbeta (type II), whereas LIF activates gp130-LIFR but not gp130-OSMRbeta. The studies report receptor-associated JAK1, JAK2, and TYK2 activation and STAT3 recruitment through both OSM receptor complexes, with STAT5B activation specifically associated with the type-II gp130-OSMRbeta complex; the receptor-subunit comparison used co-precipitation, flow cytometry, PCR, tyrosine-phosphorylation analyses, proliferation, and acute-phase protein assays.', 'The primary abstracts conclude that alternative LIFR-gp130 and OSMRbeta-gp130 subunits confer different OSM receptor specificities and signaling outputs. This supports the registered receptor-complex-to-JAK/STAT pathway edges, but does not establish ligand occupancy by purified binding, receptor-specific necessity for every JAK node, a traumatic-SCI receiver-cell context, or a terminal TF target.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_8999038.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000001' AND x.extraction_id='M21B-P2-R-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000001;M21B-E000002;M21B-E000003;M21B-E000004;M21B-E000005;M21B-E000006;M21B-E000007', 'M21B-EVID-000001', 'M21B-P2-R-000046', 'PMID:8999038; PMID:9188471', NULL, 'full_text_xml', 'exact_identifier_match:PMID:8999038', 'candidate_requires_review', 'B', 'L1', 'validated_abstract_bounded', 'validated_receptor_proximal_relay', 'PMID:8999038; PMID:9188471; https://pubmed.ncbi.nlm.nih.gov/8999038/; https://pubmed.ncbi.nlm.nih.gov/9188471/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_batch051_PMIDs_001_005_pubmed.xml', 'Human OSM signaling used two gp130-containing receptor complexes: gp130-LIFR, which responds to both LIF and OSM, and gp130-OSMRbeta, which responds to OSM but not LIF. Both receptor complexes activated JAK1, JAK2, and TYK2 and recruited STAT3; STAT5b activation was specific to the gp130-OSMRbeta type-II complex.', 'Retain distinct gp130-LIFR and gp130-OSMRbeta receptor-complex branches: both activate JAK-family kinases and STAT3, while STAT5b is specific to the type-II OSMRbeta-gp130 branch in the tested human systems. Do not collapse the complexes or infer SCI branch weights.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_PMID_8999038.xml' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000001' AND x.extraction_id='M21B-P2-R-000046');
