INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000448', 'M22B-EVID-000007', 'M22B-P2-R-000007', 'PMID:10064602', '10064602', 'full_text_html', 'exact_identifier_match:DOI:10.1093/emboj/18.5.1367;PMCID:PMC1171226', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367; https://pmc.ncbi.nlm.nih.gov/articles/PMC1171226/', 'In human IL-3-dependent F-36P-mpl cells, dominant-negative STAT5 reduced IL-3-dependent growth and cyclin D1 mRNA, while constitutively active STAT5A enabled factor-independent proliferation. STAT5A transactivated a cyclin D1 promoter element near -481 bp, STAT5 bound the element in IL-3-responsive EMSA, and cyclin D1 rescued the dominant-negative STAT5 growth defect.', 'The authors conclude that STAT5 directly regulates the cyclin D1 promoter through a STAT-binding element and contributes, together with Ras, to IL-3-dependent hematopoietic growth.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC1171226.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000007' AND x.extraction_id='M22B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000448', 'M22B-EVID-000007', 'M22B-P2-R-000007-R096', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367', '10064602', 'full_text_html', 'exact_identifier_match:DOI:10.1093/emboj/18.5.1367;PMCID:PMC1171226', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC1171226; PMID:10064602; DOI:10.1093/emboj/18.5.1367; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC1171226_STAT5_Ccnd1.html; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch096_pubmed.xml', 'In human IL-3-dependent F-36P-mpl hematopoietic cells, dominant-negative STAT5 or Ras reduced IL-3-dependent growth and cyclin D1 expression; constitutively active STAT5A transactivated the cyclin D1 promoter, mutation of a candidate STAT element at -481 bp reduced activity, and EMSA showed IL-3-responsive STAT5 binding to that element.', 'The primary study directly supports an IL-3-associated STAT5-to-Ccnd1 promoter element and a growth-rescue relationship in hematopoietic models; the exact IL-3 receptor-complex composition, transfer to IL-5/IL-7/IL-9/IL-22 handoffs, and SCI relevance remain unresolved.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC1171226.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000007' AND x.extraction_id='M22B-P2-R-000007-R096');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC1171330.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000006', 'M23B-EVID-000007', 'M23B-P2-R-000007', 'PMCID:PMC12048928; PMID:40317093', '40317093', 'full_text_html', 'exact_identifier_match:DOI:10.1186/s40478-025-01995-0;PMCID:PMC12048928', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch286_PMC12048928_alpha9_kindlin1.html; PMCID:PMC12048928; PMID:40317093; DOI:10.1186/s40478-025-01995-0', 'In adult female rats with C4 or T10 complete dorsal-column crush lesions, AAV co-expression of alpha9 integrin and kindlin-1 enabled sensory axons to cross tenascin-C-positive connective-tissue bridges, re-enter rostral CNS tissue, and extend toward the medulla; cFOS/VGLUT readouts and sensory behavioral assays supported pathway reconstruction and sensory recovery. The intervention was the joint alpha9-integrin plus kindlin-1 treatment, with no alpha9-only arm.', 'The authors conclude that activated alpha9 integrin, in combination with kindlin-1, enables sensory axon regeneration through tenascin-C-positive connective-tissue bridges and supports reconstruction of sensory pathways and recovery after SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12048928.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000007' AND x.extraction_id='M23B-P2-R-000007');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000019', 'M23B-EVID-000020', 'M23B-P2-R-000019', 'PMCID:PMC12048928; PMID:40317093; DOI:10.1186/s40478-025-01995-0', '40317093', 'full_text_html', 'exact_identifier_match:DOI:10.1186/s40478-025-01995-0;PMCID:PMC12048928', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:40317093; PMCID:PMC12048928; DOI:10.1186/s40478-025-01995-0; https://pmc.ncbi.nlm.nih.gov/articles/PMC12048928/', 'In adult female rats with complete C4 or T10 dorsal-column crush lesions, AAV-mediated co-expression of alpha9 integrin and kindlin-1 enabled sensory axons to regenerate through laminin-positive and tenascin-C-positive lesion bridges, form functional connections above the lesion, and improve sensory behavior. The study is a receptor-associated pathway and functional experiment, not a purified tenascin-C–alpha9beta1 binding assay.', 'The primary SCI study supports an alpha9-integrin/kindlin-1 receptor-associated regeneration branch and downstream sensory-function outputs; it does not establish direct tenascin-C or laminin-111 binding.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12048928.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000020' AND x.extraction_id='M23B-P2-R-000019');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000019', 'M23B-EVID-000020', 'M23B-P2-R-RECOVERY-ALPHA9-K1-SCI-FULLTEXT-000001', 'PMID:40317093; PMCID:PMC12048928; DOI:10.1186/s40478-025-01995-0', '40317093', 'full_text_html', 'exact_identifier_match:DOI:10.1186/s40478-025-01995-0;PMCID:PMC12048928', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMID:40317093; PMCID:PMC12048928; DOI:10.1186/s40478-025-01995-0; https://pmc.ncbi.nlm.nih.gov/articles/PMC12048928/; https://pubmed.ncbi.nlm.nih.gov/40317093/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch286_PMC12048928_alpha9_kindlin1.html', 'In adult female rats with complete C4 or T10 dorsal-column crush lesions, AAV-mediated co-expression of α9 integrin and kindlin-1 in sensory DRG neurons enabled axons to cross the lesion and regenerate rostrally through laminin-positive connective-tissue bridges and tenascin-C-positive strands, whereas GFP and kindlin-1-only controls did not show comparable passage into and beyond the lesion. At 12 weeks, α9-kindlin-1 axons reached the medulla in the thoracic cohort; peripheral nerve stimulation produced more cFOS-positive neurons rostral to the lesion, V5-positive axon swellings co-localized with VGLUT1/2, and thoracic animals showed recovery in heat, pressure, and tape-removal tests. This validates an α9-integrin/kindlin-1 receptor-associated regeneration branch and downstream sensory-function outputs, not a purified tenascin-C–α9β1 binding edge.', 'The authors conclude that activating an introduced α9β1 integrin with kindlin-1 enables sensory axons to use tenascin-C/laminin-associated connective-tissue bridges, regenerate long distances through spinal lesions, form functional connections above the lesion, and improve sensory behavior. The study establishes a receptor-associated pathway and functional branch; it does not establish direct molecular binding in this experiment or a terminal TF endpoint.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12048928.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000020' AND x.extraction_id='M23B-P2-R-RECOVERY-ALPHA9-K1-SCI-FULLTEXT-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000028', 'M23B-EVID-000029', 'M23B-P2-R-000029', 'PMCID:PMC12184084; PMID:40384159; DOI:10.1002/adhm.202500830', '40384159', 'full_text_html', 'exact_identifier_match:DOI:10.1002/adhm.202500830;PMCID:PMC12184084', 'supporting_validated_claim', 'B', 'L2', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC12184084; PMID:40384159; DOI:10.1002/adhm.202500830; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12184084.html', 'Soft collagen-IV/fibronectin-functionalized hyaluronic-acid scaffolds supported human iPSC-derived astrocyte-progenitor spheroid growth, increased glutamate uptake and trophic/immunomodulatory capacity, and enhanced neurite outgrowth from NSC-34 motor neurons, primary mouse spinal-cord neurons, and adult mouse DRG explants. Effects depended on scaffold composition and stiffness; no receptor perturbation was performed.', 'The authors conclude that soft collagen-IV/fibronectin scaffolds improve the reparative, angiogenic, immunomodulatory, and neurotrophic capacity of iPSC astrocyte progenitors and promote neurite/axonal outgrowth in neural models relevant to spinal-cord repair.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12184084.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000029' AND x.extraction_id='M23B-P2-R-000029');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000007', 'M23B-EVID-000008', 'M23B-P2-R-000008', 'PMCID:PMC12394907; PMID:40876929', '40876929', 'full_text_html', 'exact_identifier_match:DOI:10.26508/lsa.202503469;PMCID:PMC12394907', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC12394907; PMID:40876929; DOI:10.26508/lsa.202503469; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12394907.html', 'GlcNAc6ST1/GlcNAc6ST4 double-deficient mice showed improved locomotor recovery after SCI, reduced monocyte and monocyte-derived macrophage accumulation and CD68-positive activated macrophage/microglia abundance, increased 5-HT-positive serotonergic fibers and white-matter preservation, and reduced type-I-collagen/ECM gene programs with increased synaptic-plasticity genes.', 'The authors conclude that loss of GlcNAc6ST1 and GlcNAc6ST4 reduces inhibitory glycan/ECM and myeloid inflammatory programs and improves axonal and locomotor recovery after SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC12394907.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000008' AND x.extraction_id='M23B-P2-R-000008');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000459', 'M22B-EVID-000010', 'M22B-P2-R-000010', 'PMID:16814729', '16814729', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.cmet.2006.05.011;PMCID:PMC1904486', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011; https://pmc.ncbi.nlm.nih.gov/articles/PMC1904486/', 'IL-4 induced PGC-1β in macrophages in a STAT6-dependent manner, and PGC-1β coactivated STAT6 at the Arg1 promoter. IL-4 increased STAT6 and PGC-1β recruitment to the Arg1 enhancer; mutation of the STAT6 site abolished STAT6/PGC-1β reporter activation, while PGC-1β expression increased arginase activity and reduced LPS-induced inflammatory cytokines.', 'The authors conclude that STAT6 and PGC-1β cooperate at the Arg1 promoter to drive alternative macrophage activation and associated oxidative/anti-inflammatory functions.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC1904486.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000010' AND x.extraction_id='M22B-P2-R-000010');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000459', 'M22B-EVID-000010', 'M22B-P2-R-000010-R096', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011', '16814729', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.cmet.2006.05.011;PMCID:PMC1904486', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_fulltext', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011; https://pmc.ncbi.nlm.nih.gov/articles/PMC1904486/', 'In mouse RAW264.7 macrophages, IL-4 activated STAT6 and increased Arg1 promoter activity; PGC-1β coexpression enhanced this activity, mutation of the STAT6 response element abolished activation, co-immunoprecipitation detected a PGC-1β–STAT6 complex, and quantitative ChIP showed IL-4-dependent corecruitment of STAT6 and PGC-1β to the Arg1 enhancer. PGC-1β perturbation changed arginase and inflammatory-cytokine outputs.', 'The primary study concludes that IL-4-activated STAT6 recruits and is coactivated by PGC-1β at the Arg1 enhancer, contributing to alternative macrophage activation and metabolic/anti-inflammatory outputs.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC1904486.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000010' AND x.extraction_id='M22B-P2-R-000010-R096');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000459', 'M22B-EVID-000010', 'M22B-P2-R-RECOVERY-STAT6-ARG1-000001', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011', '16814729', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.cmet.2006.05.011;PMCID:PMC1904486', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC1904486; PMID:16814729; DOI:10.1016/j.cmet.2006.05.011; https://pmc.ncbi.nlm.nih.gov/articles/PMC1904486/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch074_PMC1904486_PGC1beta.html', 'In mouse RAW264.7 macrophages, IL-4 activated STAT6 and increased arginase I promoter activity approximately twofold; coexpression of PGC-1beta increased activity to approximately eightfold over basal. Mutation of the STAT6 response element in the arginase I enhancer abolished activation by STAT6 plus PGC-1beta. Coimmunoprecipitation detected a soluble PGC-1beta-STAT6 complex, and quantitative ChIP showed IL-4-dependent corecruitment of STAT6 and PGC-1beta to the arginase I enhancer. PGC-1beta expression increased IL-4-associated arginase activity and reduced inflammatory cytokine output, while PGC-1beta knockdown impaired the alternative macrophage program. Separately, STAT6-null macrophages failed to induce the IL-4-responsive metabolic program, and STAT6 directly bound and activated an MCAD promoter STAT6 response element by EMSA, supershift, and promoter mutagenesis.', 'The authors conclude that IL-4-activated STAT6 recruits and is coactivated by PGC-1beta at the arginase I enhancer, contributing to alternative macrophage activation and its metabolic and anti-inflammatory outputs. The STAT6 response-element mutation, STAT6/PGC-1beta ChIP, and coimmunoprecipitation support a direct promoter/enhancer-regulatory record with co-regulatory dependence. This does not establish direct IL-13 receptor-complex regulation in every cell type or an SCI receiver-cell result.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC1904486.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000010' AND x.extraction_id='M22B-P2-R-RECOVERY-STAT6-ARG1-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC20959.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000008', 'M23B-EVID-000009', 'M23B-P2-R-000009', 'PMCID:PMC2199946; PMID:7542249', '7542249', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.130.2.451;PMCID:PMC2199946', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451; local HTML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946.html; local XML=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946_epmc.xml', 'The primary abstract reports that recombinant soluble CD31/PECAM-1 supported heterophilic leukocyte adhesion mediated by alphaVbeta3 integrin, that the interaction mapped to the second PECAM-1 Ig-like domain and was inhibited by alphaVbeta3-specific antibodies, and that alphaVbeta3 was precipitated from cell lysates by recombinant CD31. Exact full-text assay conditions and figure loci remain unavailable because PMC exposes the article body as PDF-only and the publisher route was access-blocked.', 'The abstract-level primary claim is that alphaVbeta3 is a heterophilic ligand for CD31/PECAM-1 in leukocyte-endothelial adhesion; full-text methods and figure verification are required before import-ready promotion.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000009' AND x.extraction_id='M23B-P2-R-000009');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000008', 'M23B-EVID-000009', 'M23B-P2-R-RECOVERY-PECAM1-ITGAVB3-000001', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451', '7542249', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.130.2.451;PMCID:PMC2199946', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2199946; PMID:7542249; DOI:10.1083/jcb.130.2.451; https://pmc.ncbi.nlm.nih.gov/articles/PMC2199946/; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_C23B_batch062_PMC2199946_PECAM1_alphaVbeta3.html', 'Recombinant CD31/PECAM-1 supported heterophilic leukocyte adhesion through its second Ig-like domain; alphaVbeta3-specific antibodies inhibited the adhesion and recombinant CD31 precipitated alphaVbeta3 from cell lysates. This is direct pair-specific adhesion evidence in an endothelial/leukocyte comparator system, with no SCI or neural receiver-cell inference.', 'The authors conclude that alphaVbeta3 integrin is a heterophilic ligand for CD31/PECAM-1 and that the pair contributes to leukocyte-endothelial adhesion. The direct molecular record is retained as an adhesion interaction; no downstream TF or SCI transfer is inferred.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2199946.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000009' AND x.extraction_id='M23B-P2-R-RECOVERY-PECAM1-ITGAVB3-000001');
