INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000026', 'M23B-EVID-000027', 'M23B-P2-R-000027', 'PMCID:PMC2288935; PMID:2010469; PMID:7535784; DOI:10.1083/jcb.113.2.417', '2010469', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.113.2.417;PMCID:PMC2288935', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_author_claim', 'PMID:8344274; DOI:10.1111/j.1432-1033.1993.tb18017.x; PMCID:PMC2288935; PMID:2010469; PMID:7535784; https://pubmed.ncbi.nlm.nih.gov/8344274/', 'Purified isolated alpha1beta1 and alpha2beta1 integrins bound the collagen-IV CB3 fragment in solid-phase and inhibition assays, with nanomolar affinity and cation-dependent specificity. The linked neural primary study separately shows collagen-IV/NC1 and alpha1beta1-dependent neurite outgrowth by antibody blockade.', 'The direct primary binding study establishes collagen-IV recognition by isolated alpha1beta1, while the neural study provides separate alpha1beta1-dependent neurite/axon outgrowth context.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2288935.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000027' AND x.extraction_id='M23B-P2-R-000027');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000026', 'M23B-EVID-000027', 'M23B-P2-R-RECOVERY-COLL4-ITGA1B1-000001', 'PMCID:PMC2288935; PMID:2010469; PMID:7535784; DOI:10.1083/jcb.113.2.417', '2010469', 'full_text_html', 'exact_identifier_match:DOI:10.1083/jcb.113.2.417;PMCID:PMC2288935', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_author_claim', 'PMID:8344274; DOI:10.1111/j.1432-1033.1993.tb18017.x; PMCID:PMC2288935; PMID:2010469; PMID:7535784; https://pubmed.ncbi.nlm.nih.gov/8344274/', 'The primary isolated-integrin study showed collagen-IV CB3 fragment binding to purified alpha1beta1 and alpha2beta1 in solid-phase/inhibition assays with nanomolar affinity. The linked neural study showed collagen-IV/NC1-dependent neurite outgrowth blocked by beta1-integrin and alpha1beta1-specific antibodies.', 'The authors conclude that the NC1 domain of type-IV collagen promotes axonal growth through interaction with alpha1beta1 integrin in peripheral neurons. The observation remains a receptor-dependent functional adhesion/outgrowth record and does not infer SCI relevance or a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2288935.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000027' AND x.extraction_id='M23B-P2-R-RECOVERY-COLL4-ITGA1B1-000001');
