INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000026', 'M23B-EVID-000027', 'M23B-P2-R-RECOVERY-COLL4-ITGA1B1-000001', 'PMCID:PMC2288935; PMID:2010469; PMID:7535784; DOI:10.1083/jcb.113.2.417', '2010469', 'full_text_html', 'exact_identifier_match:PMCID:PMC2288935', 'supporting_validated_claim', 'B', 'L2', 'validated_full_text_importable', 'validated_author_claim', 'PMID:8344274; DOI:10.1111/j.1432-1033.1993.tb18017.x; PMCID:PMC2288935; PMID:2010469; PMID:7535784; https://pubmed.ncbi.nlm.nih.gov/8344274/', 'The primary isolated-integrin study showed collagen-IV CB3 fragment binding to purified alpha1beta1 and alpha2beta1 in solid-phase/inhibition assays with nanomolar affinity. The linked neural study showed collagen-IV/NC1-dependent neurite outgrowth blocked by beta1-integrin and alpha1beta1-specific antibodies.', 'The authors conclude that the NC1 domain of type-IV collagen promotes axonal growth through interaction with alpha1beta1 integrin in peripheral neurons. The observation remains a receptor-dependent functional adhesion/outgrowth record and does not infer SCI relevance or a terminal TF.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2288935_pdf_gate.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000027' AND x.extraction_id='M23B-P2-R-RECOVERY-COLL4-ITGA1B1-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000392', 'M22B-EVID-000022', 'M22B-P2-R-000022-R098', 'PMCID:PMC2430079; PMID:18314002; DOI:10.1016/j.bone.2008.01.006', '18314002', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.bone.2008.01.006;PMCID:PMC2430079', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC2430079; PMID:18314002; DOI:10.1016/j.bone.2008.01.006; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_PMC2430079_SMAD_CTGF.html; local PubMed=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch098_pubmed.xml', 'TGF-beta1 induced CTGF promoter activity in primary rat osteoblasts through Smads3/4 plus Src-ERK signaling; promoter deletion/mutation and EMSA showed that both TRE and SBE motifs were required.', 'The primary study supports a TGF-beta1-Smad3/4-Src-ERK CTGF promoter pathway in rat osteoblasts, but does not establish an isolated Smad3/4-only edge, Smad2 participation, BMP8B/GDF11/activin/MSTN receptor use, or SCI transfer.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2430079.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000022' AND x.extraction_id='M22B-P2-R-000022-R098');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000392', 'M22B-EVID-000022', 'M22B-P2-R-000054', 'PMID:18314002; PMCID:PMC2430079; DOI:10.1016/j.bone.2008.01.006', '18314002', 'full_text_html', 'exact_identifier_match:DOI:10.1016/j.bone.2008.01.006;PMCID:PMC2430079', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:18314002; PMCID:PMC2430079; DOI:10.1016/j.bone.2008.01.006; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2430079.html', 'In primary rat osteoblasts, TGF-beta1 increased CTGF promoter activity and CTGF protein expression. TGF-beta1 activated Smad2 and Smad3, but siRNA depletion showed that Smad3 and Smad4, not Smad2, were required for CTGF promoter activation and protein induction. ERK and Src activity were also required, and promoter deletion analysis supported combined SBE and TRE requirements.', 'The authors conclude that TGF-beta1 induction of CTGF in primary osteoblasts requires Smad3/Smad4 together with ERK and Src signaling and depends on cooperating SBE and TRE promoter elements; Smad2 activation alone is insufficient.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2430079.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000022' AND x.extraction_id='M22B-P2-R-000054');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000395', 'M22B-EVID-000023', '', '', NULL, 'full_text_html', 'no_exact_phase2_paper_match', 'linked_unresolved', NULL, 'L1', '', '', '', '', '', 'Conservative filename/register crosswalk exists, but no exact source-identifier match to a Phase-2 paper row was found; no claim is inferred.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2430079.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000023' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000431', 'M22B-EVID-000001', 'M22B-P2-R-000001', 'PMCID:PMC2441693; PMID:16718380; DOI:10.1007/s11010-006-9137-3', '16718380', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s11010-006-9137-3;PMCID:PMC2441693', 'candidate_requires_review', 'B', 'L1', 'abstract_only_not_import_ready', 'abstract_only_not_import_ready', 'PMCID:PMC2441693; PMID:16718380; DOI:10.1007/s11010-006-9137-3; local cache=data/raw/evidence/module20_24_supervised_cli_phase2/M22B_batch001_pubmed.xml; BioC retry=data/raw/evidence/module20_24_supervised_cli_phase2/M22B_16718380_PMC2441693.json', 'The retained PubMed abstract reports IL-6-induced STAT3 activation and Socs3 expression in Stat3-null MEF reconstitution systems, with STAT3 binding at the Socs3 promoter and an N-domain deletion mutant retaining Socs3 induction. The abstract does not provide an atomic figure/section passage for import.', 'The abstract supports a STAT3-to-Socs3 transcriptional lead, but exact author interpretation and figure-level promoter evidence require complete primary text.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2441693.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000001' AND x.extraction_id='M22B-P2-R-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000431', 'M22B-EVID-000001', 'M22B-P2-R-000001-R098', 'PMCID:PMC2441693; PMID:16718380; DOI:10.1007/s11010-006-9137-3', '16718380', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s11010-006-9137-3;PMCID:PMC2441693', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_DIRECT_TF_TARGET', 'PMCID:PMC2441693; PMID:16718380; DOI:10.1007/s11010-006-9137-3; local=data/raw/evidence/module20_24_supervised_cli_phase2/M22B_16718380_PMC2441693.json', 'Cytokine stimulation activated STAT3 and induced SOCS3 expression; STAT3-dependent promoter regulation and SOCS3 feedback were supported by perturbation and promoter assays.', 'The primary full text supports a shared STAT3-to-Socs3 regulatory edge, strongest in the tested cytokine context, but does not prove that every submitted IL-20/IL-21/IL-24/IL-6/LIF handoff induces Socs3 in the same SCI receiver cell.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2441693.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000001' AND x.extraction_id='M22B-P2-R-000001-R098');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000431', 'M22B-EVID-000001', 'M22B-P2-R-RECOVERY-STAT3-SOCS3-000001', 'PMCID:PMC2441693; PMID:16718380; DOI:10.1007/s11010-006-9137-3', '16718380', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s11010-006-9137-3;PMCID:PMC2441693', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text_importable', 'validated_author_claim', 'PMCID:PMC2441693; PMID:16718380; DOI:10.1007/s11010-006-9137-3; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_B22B_fulltext/html/PMC2441693.html', 'IL-6 plus soluble IL-6 receptor induced SOCS3 expression in Stat3+/− and STAT3-reconstituted Stat3−/− mouse embryonic fibroblasts but not Stat3−/− cells; EMSA showed activated STAT3 binding predominantly to the proximal Socs3 promoter STAT motif, with competition and anti-STAT3 supershift controls.', 'The authors conclude that STAT3 interaction at the proximal Socs3 promoter motif is sufficient for IL-6-dependent Socs3 activation and that the STAT3 N-domain is dispensable for this response; this is a STAT3-to-Socs3 target-gene result, not evidence that every upstream ligand-receptor pair induces Socs3 in SCI.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2441693.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000001' AND x.extraction_id='M22B-P2-R-RECOVERY-STAT3-SOCS3-000001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000431', 'M22B-EVID-000001', 'M22B-P2-R-RECOVERY-STAT3-SOCS3-000002', 'PMID:16718380; PMCID:PMC2441693; DOI:10.1007/s11010-006-9137-3', '16718380', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s11010-006-9137-3;PMCID:PMC2441693', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_direct_tf_target', 'PMID:16718380; PMCID:PMC2441693; DOI:10.1007/s11010-006-9137-3; https://pubmed.ncbi.nlm.nih.gov/16718380/; https://pmc.ncbi.nlm.nih.gov/articles/PMC2441693/; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch063_PMC2441693_STAT3_Socs3.html', 'IL-6 plus soluble IL-6 receptor activated STAT3 in Stat3-null mouse embryonic fibroblasts reconstituted with STAT3 or Delta133STAT3. Northern blot and quantitative PCR showed endogenous Socs3 induction only with STAT3-containing cells. EMSA with murine Socs3 promoter oligonucleotides showed STAT3 interaction primarily at the proximal STAT consensus site; excess intact competitor blocked binding, anti-STAT3 partially supershifted the complex, and mutation of the proximal site prevented competition. Delta133STAT3 retained IL-6-dependent Socs3 induction, so the STAT3 N-domain was not required for this target-gene output.', 'Retain a direct STAT3 -> Socs3 promoter/target-gene edge in the tested IL-6-responsive mouse comparator. Do not infer that every IL-6-family ligand-receptor handoff induces Socs3 in the same SCI receiver cell, that receptor-proximal pSTAT3 alone proves promoter occupancy, or that the study identifies a downstream TF beyond STAT3.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2441693.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000001' AND x.extraction_id='M22B-P2-R-RECOVERY-STAT3-SOCS3-000002');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000431', 'M22B-EVID-000027', 'M22B-P2-R-000027', 'PMID:16718380; PMCID:PMC2441693; DOI:10.1007/s11010-006-9137-3', '16718380', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s11010-006-9137-3;PMCID:PMC2441693', 'candidate_requires_review', NULL, 'L1', 'unresolved', 'unresolved', 'PMID:16718380; PMCID:PMC2441693; DOI:10.1007/s11010-006-9137-3', 'A prior abstract-only retrieval exists for this source family, but this distinct handoff row requires an exact primary passage for the shared STAT3-to-Socs3 claim and no retained full-text passage was available through the supervised CLI cache.', 'Do not reuse the abstract-only or B-layer summary as an import-ready direct STAT3-to-Socs3 record for this distinct edge row.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2441693.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000027' AND x.extraction_id='M22B-P2-R-000027');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000431', 'M22B-EVID-000027', 'M22B-P2-R-000027-R089', 'PMCID:PMC2441693; PMID:16718380; DOI:10.1007/s11010-006-9137-3', '16718380', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s11010-006-9137-3;PMCID:PMC2441693', 'linked_unresolved', NULL, 'L1', 'reuse_validated_observation', 'REUSE_DIRECT_TF_TARGET', 'PMCID:PMC2441693; PMID:16718380; DOI:10.1007/s11010-006-9137-3; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2441693.html', 'Reuse the validated STAT3-to-Socs3 primary observation for the repeated handoff; the exact shared TF-level result is supported, but no new ligand-receptor-specific Socs3 experiment is created.', 'Reuse the validated direct STAT3-to-Socs3 promoter observation without asserting that each submitted IL-20/IL-21/IL-24/IL-6/LIF receptor handoff induces Socs3 in an SCI receiver cell.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2441693.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000027' AND x.extraction_id='M22B-P2-R-000027-R089');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000431', 'M22B-EVID-000057', 'M22B-P2-B090-001', 'PMID:16718380; PMCID:PMC2441693; DOI:10.1007/s11010-006-9137-3', '16718380', 'full_text_html', 'exact_identifier_match:DOI:10.1007/s11010-006-9137-3;PMCID:PMC2441693', 'supporting_validated_claim', 'B', 'L1', 'validated_fulltext', 'validated_fulltext', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2441693/; https://pubmed.ncbi.nlm.nih.gov/16718380/', 'IL-6 plus soluble IL-6 receptor induced STAT3 phosphorylation and endogenous Socs3 expression in Stat3-deficient mouse embryonic fibroblasts reconstituted with wild-type STAT3 or Delta133STAT3, but not in unreconstituted Stat3-deficient cells. Electrophoretic mobility-shift assays showed STAT3 binding predominantly at the proximal STAT consensus element of the Socs3 promoter; the Delta133STAT3 mutant retained this promoter response.', 'The authors conclude that IL-6/STAT3 activates Socs3 and that STAT3 interaction at the proximal Socs3 promoter element is sufficient for the tested response; STAT3 N-domain sequences are dispensable in this context. This is direct STAT3-to-Socs3 target evidence, not proof that every queued ligand-receptor handoff induces Socs3 in SCI astrocytes.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2441693.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000057' AND x.extraction_id='M22B-P2-B090-001');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000678', 'M22B-EVID-004999', 'M22B-P2-R-000664', 'DOI:10.1091/mbc.9.6.1425', '9614184', 'full_text_html', 'exact_identifier_match:DOI:10.1091/mbc.9.6.1425', 'candidate_requires_review', NULL, 'L1', 'validated_observation', 'NO_TERMINAL_TF_EVIDENCE', 'DOI:10.1091/mbc.9.6.1425; local source=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch061_doi_pubmed.xml', 'The DOI-linked primary record supports the queued molecular binding, receptor, or matrix-function observation; no terminal TF endpoint was reported.', 'The primary source supports a bounded receptor/pathway or functional association; no direct TF occupancy or terminal target locus was shown.', 'The artifact is linked to a resolved paper-level review row, but the observation and claim gates are not both satisfied. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC25364.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-004999' AND x.extraction_id='M22B-P2-R-000664');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000015', 'M23B-EVID-000016', 'M23B-P2-R-000016', 'PMCID:PMC25364; PMID:9614184', '9614184', 'full_text_html', 'exact_identifier_match:DOI:10.1091/mbc.9.6.1425;PMCID:PMC25364', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC25364; PMID:9614184; DOI:10.1091/mbc.9.6.1425; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC25364.html', 'Purified soluble mouse alpha8t-beta1-AP heterodimer bound native human OPN and recombinant GST-OPN in solid-phase assays; binding was inhibited by RGD peptide and a function-blocking beta1 antibody. Far-Western analysis of mouse embryo/kidney extracts identified OPN-sized alpha8beta1-reactive material, and alpha8-transfected K562 (KA8) but not parental K562 cells adhered to OPN/GST-OPN in beta1- and RGD-sensitive assays.', 'The authors conclude that osteopontin is a novel ligand for integrin alpha8beta1 and that this interaction may contribute to epithelial-mesenchymal and kidney morphogenesis processes.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC25364.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000016' AND x.extraction_id='M23B-P2-R-000016');
