INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000684', 'M23B-EVID-000913', 'P2FALLBACK-23B-M23B-EVID-000913', 'PMID:9614184', '9614184', 'full_text_html', 'exact_identifier_match:DOI:10.1091/mbc.9.6.1425;PMCID:PMC25364', 'linked_unresolved', 'B', 'L1', 'unresolved', 'unresolved', 'PMID:9614184; PMCID:PMC25364; DOI:10.1091/mbc.9.6.1425', 'Unresolved: no validated atomic primary-paper observation was retained for this evidence record; do not import.', 'Unresolved: no separate explicit author interpretation was retained from a primary-paper section or figure legend; do not convert the B-layer summary into an AuthorClaim.', 'The artifact is linked to a Phase-2 evidence row, but the paper, observation, or claim remains unresolved. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC25364.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000913' AND x.extraction_id='P2FALLBACK-23B-M23B-EVID-000913');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '', '', '', '', '', NULL, 'full_text_html', 'not_attempted', 'unmapped_source_artifact', NULL, NULL, '', '', '', '', '', 'No conservative register crosswalk exists for this artifact.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2798829.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='' AND x.register_evidence_id='' AND x.extraction_id='');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'M21B-P2-R-000021', 'PMID:20038584', '20038584', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m109.037341;PMCID:PMC2844188', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC2844188; PMID:20038584; DOI:10.1074/jbc.M109.037341; PMID:21558270; DOI:10.1073/pnas.0837789100', 'In TNFR2-expressing HeLa and Jurkat systems and primary human T cells, receptor-selective membrane-TNF stimulation caused TNFR2-specific p100 processing, p52/RelB nuclear translocation, and cytosolic TRAF2 depletion; the study separated this alternative NF-kappaB branch from the stronger TNFR1 classical NF-kappaB response. The linked TNFR2 review/primary record also supports TRAF2-dependent NF-kappaB/JNK signaling, but no universal TRAF2-to-JNK ordering was inferred from the full-text paper.', 'The authors conclude that membrane TNF activates TNFR2 to deplete TRAF2 and trigger the alternative NF-kappaB pathway through p100 processing, p52 generation and RelB nuclear translocation, while TNFR1 preferentially drives the classical NF-kappaB branch. The TNFR2/JNK component remains bounded to linked primary evidence and is not merged with the measured alternative-NF-kappaB sequence.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2844188.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='M21B-P2-R-000021');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'M21B-P2-R-000036', 'PMID:20038584; PMCID:PMC2844188; DOI:10.1074/jbc.M109.037341', '20038584', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m109.037341;PMCID:PMC2844188', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:20038584; PMCID:PMC2844188; DOI:10.1074/jbc.M109.037341; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2844188.html', 'TNFR2-specific oligomerized or membrane TNF induced IL-8 in TNFR2-expressing HeLa systems, was blocked by TNFR2-Fc but not TNFR1-Fc, and shifted signaling toward p100 processing, p52/RelB nuclear accumulation, TRAF2 depletion, and NIK accumulation rather than the TNFR1-associated p65/p50 branch. The same TNFR2-specific membrane-TNF system induced p100 processing in co-culture, and TNFR2-specific stimulation induced p100 processing in a subset of primary human T-cell samples.', 'The authors conclude that membrane or oligomerized TNF selectively activates TNFR2 and drives a TRAF2/cIAP/TRAF3/NIK-associated alternative NF-kappaB program with p100 processing, p52/RelB nuclear signaling, and IL-8 output, distinct from the TNFR1 p65/p50 branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2844188.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='M21B-P2-R-000036');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '21B', 'M21B-E000066;M21B-E000067', 'M21B-EVID-000021', 'P2MAN-M21B-M21B-EVID-000021-PMID_20038584', 'PMID:20038584', '20038584', 'full_text_html', 'exact_identifier_match:PMCID:PMC2844188', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', '/Users/derea/Documents/SCI/mSCIdblit/data/raw/evidence/module20_24_supervised_cli_phase2/retry_B21B_PMC2844188_TNFR2_p100_full.html; M21B-EVID-000021; identifier: PMID:20038584; PMCID:PMC2844188', 'Oligomerized/membrane TNF activated TNFR2-associated p100 processing and nuclear translocation of p52/RelB in multiple cell lines, whereas non-oligomerized soluble TNF was weak or inactive for this alternative NF-κB output.', 'The authors conclude that TNFR2, unlike TNFR1 in the tested setting, can trigger p100 processing and that ligand form controls this branch.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2844188.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='21B' AND x.register_evidence_id='M21B-EVID-000021' AND x.extraction_id='P2MAN-M21B-M21B-EVID-000021-PMID_20038584');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000446', 'M22B-EVID-000008', 'M22B-P2-R-000008', 'PMID:20644163', '20644163', 'full_text_html', 'exact_identifier_match:DOI:10.4049/jimmunol.1000842;PMCID:PMC2991082', 'supporting_validated_claim', 'B', 'L1', 'validated_full_text', 'validated_author_claim', 'PMCID:PMC2991082; PMID:20644163; DOI:10.4049/jimmunol.1000842; https://pmc.ncbi.nlm.nih.gov/articles/PMC2991082/', 'In LCMV-infected mice, conditional STAT5 loss reduced Bcl-2 in effector CD8+ T cells. IL-7 and IL-15 increased Bcl-2 in primary effector CD8+ T cells, and this induction was impaired after STAT5 deletion; short-term cytokine stimulation increased Bcl2 mRNA even with cycloheximide, supporting a rapid STAT5-dependent transcriptional response.', 'The study concludes that IL-7 and IL-15 require STAT5 to induce Bcl-2 and maintain effector CD8+ T-cell responses. It provides downstream survival/function evidence, not a native-chromatin STAT5 occupancy assay at Bcl2 in this paper.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2991082.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000008' AND x.extraction_id='M22B-P2-R-000008');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000446', 'M22B-EVID-000008', 'M22B-P2-R-000008-R096', 'PMCID:PMC2991082; PMID:20644163; DOI:10.4049/jimmunol.1000842', '20644163', 'full_text_html', 'exact_identifier_match:DOI:10.4049/jimmunol.1000842;PMCID:PMC2991082', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'VALIDATED_RECEPTOR_PATHWAY_BOUNDED', 'PMCID:PMC2991082; PMID:20644163; DOI:10.4049/jimmunol.1000842; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2991082.html; local=data/raw/evidence/module20_24_supervised_cli_phase2/retry_B22B_batch095_pubmed.xml', 'IL-7/STAT5 signaling was associated with maintenance of Bcl2 expression and survival in effector CD8 T-cell models; STAT5 perturbation reduced the survival-gene program and effector-cell maintenance, but the study did not establish STAT5 occupancy at the Bcl2 locus.', 'The primary study supports an IL-7-associated STAT5 survival-gene program involving Bcl2 maintenance in effector CD8 T cells, but not direct STAT5-Bcl2 promoter occupancy or transfer to SCI receiver cells.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2991082.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000008' AND x.extraction_id='M22B-P2-R-000008-R096');
INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '22B', 'M22B-E000446', 'M22B-EVID-000008', 'M22B-P2-R-000045', 'PMID:20644163; PMCID:PMC2991082; DOI:10.4049/jimmunol.1000842', '20644163', 'full_text_html', 'exact_identifier_match:DOI:10.4049/jimmunol.1000842;PMCID:PMC2991082', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMID:20644163; PMCID:PMC2991082; DOI:10.4049/jimmunol.1000842; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2991082.html', 'In LCMV-infected mice, IL-7 and IL-15 contributed to effector CD8 T-cell survival and maintenance of Bcl-2, with IL-15 particularly important for most effector CD8 subsets. Conditional STAT5 loss reduced effector CD8 T-cell numbers and Bcl-2 levels; in vitro IL-7 or IL-15 stimulation induced STAT5 phosphorylation and Bcl-2 upregulation, and the cytokine-driven Bcl-2 response was STAT5 dependent.', 'The authors conclude that STAT5 is required for IL-7- and IL-15-driven Bcl-2 maintenance and effector CD8 T-cell survival during LCMV infection, with partially overlapping cytokine dependence across effector subsets.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC2991082.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='22B' AND x.register_evidence_id='M22B-EVID-000008' AND x.extraction_id='M22B-P2-R-000045');
