INSERT INTO EvidenceArtifactAdjudication (artifact_id, module, register_edge_id, register_evidence_id, extraction_id, canonical_paper_key, resolved_pmid, artifact_role, paper_match_status, artifact_support_status, evidence_grade, context_level, observation_status, claim_status, source_locator, candidate_observation_snippet, candidate_claim_snippet, adjudication_basis) SELECT artifact_id, '23B', 'M23B-E000023', 'M23B-EVID-000024', 'M23B-P2-R-000024', 'PMCID:PMC3030393; PMID:21127050; DOI:10.1074/jbc.M110.161141', '21127050', 'full_text_html', 'exact_identifier_match:DOI:10.1074/jbc.m110.161141;PMCID:PMC3030393', 'supporting_validated_claim', 'B', 'L1', 'validated_primary_observation', 'validated_author_claim', 'PMCID:PMC3030393; PMID:21127050; DOI:10.1074/jbc.M110.161141; local full text=data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC3030393.html', 'Chondroadherin cell attachment was mediated by an alpha2beta1 integrin-associated binding motif, CQLRGLRRWLEAK318. The peptide inhibited adhesion to immobilized chondroadherin, promoted attachment when immobilized, and affinity purification from chondrocyte membrane lysates recovered the alpha2 integrin subunit specifically from the peptide column; ERK phosphorylation was induced after adhesion to chondroadherin or the active peptide.', 'The authors identify CQLRGLRRWLEAK318 as a chondroadherin cell-binding motif that engages integrin alpha2beta1 and triggers ERK phosphorylation without the spreading and division seen on collagen.', 'The artifact has an exact identifier match to a Phase-2 row with validated observation and validated claim statuses. Matched identifiers are recorded for audit; filename tokens and database links alone are not treated as claim support.' FROM EvidenceArtifact WHERE relative_path='data/raw/evidence/module20_24_supervised_cli_phase2/retry_external_PMC3030393.html' AND NOT EXISTS (SELECT 1 FROM EvidenceArtifactAdjudication x WHERE x.artifact_id=EvidenceArtifact.artifact_id AND x.module='23B' AND x.register_evidence_id='M23B-EVID-000024' AND x.extraction_id='M23B-P2-R-000024');
